const LAUNCH_ORDER = ['analytics', 'reporting', 'people', 'alerts', 'closing', 'sales', 'approve', 'acct', 'treasury', 'purchasing', 'partners', 'inv', 'vat', 'brmgmt', 'entities', 'docs', 'backup', 'audit', 'archive'];
const launchRank = (id) => { const i = LAUNCH_ORDER.indexOf(id); return i < 0 ? 999 : i; };
/* v8.5 — لقطات احتياطية يومية محلية (IndexedDB) على أجهزة الإدارة:
   حماية إضافية ضد التلف أو الحذف الخاطئ — والنسخة الملفية تبقى الحماية الخارجية */
const snapDB = () => new Promise((res, rej) => {
  const r = indexedDB.open('rms8-snaps', 1);
  r.onupgradeneeded = () => { r.result.createObjectStore('snaps', { keyPath: 'key' }); };
  r.onsuccess = () => res(r.result);
  r.onerror = () => rej(r.error);
});
const snapPut = async (key, val) => { const db = await snapDB(); return new Promise((res, rej) => { const tx = db.transaction('snaps', 'readwrite'); tx.objectStore('snaps').put({ key, ...val }); tx.oncomplete = () => { db.close(); res(true); }; tx.onerror = () => { db.close(); rej(tx.error); }; }); };
const snapAll = async () => { const db = await snapDB(); return new Promise((res, rej) => { const rq = db.transaction('snaps').objectStore('snaps').getAll(); rq.onsuccess = () => { db.close(); res(rq.result || []); }; rq.onerror = () => { db.close(); rej(rq.error); }; }); };
const snapDel = async (key) => { const db = await snapDB(); return new Promise((res, rej) => { const tx = db.transaction('snaps', 'readwrite'); tx.objectStore('snaps').delete(key); tx.oncomplete = () => { db.close(); res(true); }; tx.onerror = () => { db.close(); rej(tx.error); }; }); };
// فحص سلامة نسخة احتياطية: البنية + تشغيل المحرك المحاسبي عليها والتأكد من توازنها
function verifyBackup(data) {
  try {
    if (!data || typeof data !== 'object') return { ok: false, err: 'الملف ليس نسخة صالحة' };
    if (!data.org || !Array.isArray(data.org.branches) || !Array.isArray(data.org.users)) return { ok: false, err: 'بنية المنشأة ناقصة (فروع/مستخدمون)' };
    const ops2 = data.ops || {};
    const A = buildAccounting(data.org, ops2);
    return {
      ok: true,
      counts: {
        branches: (data.org.branches || []).length, users: (data.org.users || []).length,
        closings: (ops2.closings || []).length, suppliers: (data.org.suppliers || []).length,
        items: (data.org.items || []).length, assets: (data.org.assets || []).length,
        entries: A.entries.length
      },
      balanced: A.balanced, totalDebit: A.totalDebit,
      exportedAt: (data.meta && data.meta.exportedAt) || data.exportedAt || '', by: (data.meta && data.meta.by) || ''
    };
  } catch (e) { return { ok: false, err: 'تعذّرت قراءة النسخة: ' + (e.message || '') }; }
}

// تفضيلات الاستخدام لكل مستخدم (مفضلة + آخر استخدام) — محلية على الجهاز
const appUseGet = (uid) => { try { return JSON.parse(localStorage.getItem('rms8:appuse:' + uid) || '{}') || {}; } catch { return {}; } };
const appUseSet = (uid, v) => { try { localStorage.setItem('rms8:appuse:' + uid, JSON.stringify(v)); } catch { } };
// يقبل كائن المستخدم (لتخصيص الظهور لكل مستخدم) أو نص الدور (توافق قديم)
const appCanSee = (meOrRole, a) => {
  const role = typeof meOrRole === 'string' ? meOrRole : meOrRole?.role;
  const R = ROLES[role] || {};
  if (a.soon) return R.scope === 'all' && !R.limitedApps;  // خارطة الطريق تظهر لأدوار المركز فقط (لا للأدوار المحدودة)
  if (meOrRole && typeof meOrRole === 'object') {
    if ((meOrRole.appDeny || []).includes(a.id)) return false;   // مُخفى يدويًا لهذا المستخدم
    if ((meOrRole.appAllow || []).includes(a.id)) return true;   // مُضاف يدويًا فوق دوره
  }
  return (R.tabs || []).includes(a.open.tab);              // الأساس: صلاحيات دور المستخدم
};
const appOpenNow = (a, me, setTab, openAcctView, openInvView) => {
  if (a.soon) return false;
  const u = appUseGet(me.id); const r = (u.rec = u.rec || {});
  r[a.id] = { at: Date.now(), count: ((r[a.id] || {}).count || 0) + 1 };
  appUseSet(me.id, u);
  if (a.open.view) {
    if (a.open.tab === 'acct' && openAcctView) openAcctView(a.open.view);
    if (a.open.tab === 'inv' && openInvView) openInvView(a.open.view);
  }
  setTab(a.open.tab);
  return true;
};



/* ============================================================
   منصة سحابية متكاملة لإدارة وإغلاق فروع المطاعم
   نسخة تفاعلية متعددة المستخدمين — بيانات مشتركة سحابياً
   ============================================================ */



/* ================= أدوات ================= */
/* ================= البيانات التأسيسية ================= */
function rnd(seed) { const x = Math.sin(seed) * 10000; return x - Math.floor(x); }

function emptyOrg(company) {
  return {
    company: company || {
      name: '', activity: 'مطاعم ومقاهي', taxNumber: '', commercialReg: '',
      phone: '', email: '', address: '', logoUrl: ''
    },
    branches: [],
    users: [],
    employees: [],
    departments: [],
    positions: [],
    expenseCats: EXP_CATS.map(c => ({ ...c, budgetLimitMonthly: 0 })),
    deliveryApps: APPS,
    suppliers: [],
    partners: [],
    setupComplete: false
  };
}

function emptyOps() {
  return { closings: [], transfers: [], advances: [], notifications: [], invoices: [], fixedExpenses: [], disbursements: [], ledgerEntries: [], partnerRequests: [], journalManual: [], purchaseOrders: [], stockMoves: [], bankRecs: [], closingInvPays: [], appSettlements: [], schedules: [], branchPartners: [],
    attendanceEvents: [], hrPins: [], shiftTemplates: [], shiftAssignments: [], shiftSwapRequests: [], branchTransferRequests: [], taskTemplates: [], taskAssignments: [], taskCompletions: [], pointsEntries: [], qualityReviews: [], rewardRequests: [], hrSignDocs: [], hrCorrective: [], hrPips: [], hrTraining: [], hrKpiEntries: [], hrScoreSnapshots: [] };
}


/* ================= الجذر ================= */
export default function App() {
  const [org, setOrg] = useState(null);
  const [ops, setOps] = useState({ closings: [], transfers: [], advances: [], notifications: [], invoices: [], fixedExpenses: [], disbursements: [], ledgerEntries: [], partnerRequests: [], journalManual: [], purchaseOrders: [], stockMoves: [], bankRecs: [], closingInvPays: [], appSettlements: [], schedules: [], branchPartners: [] });
  const [pulse, setPulse] = useState({ presence: {}, audit: [] });
  const [me, setMe] = useState(null);
  const [tab, setTab] = useState('home');
  const [acctIntent, setAcctIntent] = useState(null);          // فتح المحاسبة على شاشة محددة من مركز التطبيقات
  const openAcctView = useCallback((v) => setAcctIntent({ v, ts: Date.now() }), []);
  const [invIntent, setInvIntent] = useState(null);            // فتح المخزون على شاشة محددة
  const openInvView = useCallback((v) => setInvIntent({ v, ts: Date.now() }), []);
  const [drawer, setDrawer] = useState(false);
  const [moreSheet, setMoreSheet] = useState(false);
  const [userMenu, setUserMenu] = useState(false);   // v9.6 قائمة الحساب في الرأس
  const [themePick, setThemePick] = useState(false); // v14.3 منتقي الثيمات
  const touchRef = useRef({ x0: 0, y0: 0, active: false, mode: null });
  const [syncing, setSyncing] = useState(false);
  const [lastSync, setLastSync] = useState(null);
  const [boot, setBoot] = useState('loading');
  const [toast, setToast] = useState(null);
  const [bell, setBell] = useState(false);
  const [lastSeenAudit, setLastSeenAudit] = useState(() => Date.now());
  const [theme, setTheme] = useState(() => { try { return normTheme(localStorage.getItem('rms8:theme') || 'gold'); } catch { return 'gold'; } });
  const [mode, setMode] = useState(() => { try { return localStorage.getItem('rms8:mode') === 'dark' ? 'dark' : 'light'; } catch { return 'light'; } });
  const [tour, setTour] = useState(false);
  const [live, setLive] = useState(false);
  const [offline, setOffline] = useState(typeof navigator !== 'undefined' && navigator.onLine === false);
  const [installPrompt, setInstallPrompt] = useState(null);
  const [installed, setInstalled] = useState(false);
  const [updateReady, setUpdateReady] = useState(false);   // v11.1 توفّر نسخة أحدث منشورة
  // v27.1 — تشخيص صلاحيات الخادم على جهاز الفرع: {kind:'dir'|'branch'|'member', ids, mem, expected}
  // (سابقًا كان رفض القراءة يسقط بصمت إلى نسخة localStorage القديمة فتبدو الشاشات «تعمل» بينما كل كتابة سحابية ترفض)
  const [accessErr, setAccessErr] = useState(null);
  const lastWriteErr = useRef('');   // 'denied' | 'net' | 'scope' | ''
  const [brSetVer, setBrSetVer] = useState(0);   // v27.3: يتغيّر عند تغيّر مجموعة الفروع المشترَك بها — يُعيد بناء الاشتراكات الحيّة
  const sid = useRef(uid('s'));
  // v15.29 — جلسة واحدة لكل مستخدم (عدا أدوار الإدارة): هوية ثابتة لهذا المتصفح تبقى
  // عبر إعادة التحميل وتتشاركها تبويبات المتصفح الواحد (فلا يطرد المتصفح نفسه)،
  // بينما يحمل كل متصفح/جهاز آخر هوية مختلفة فيُكشف الدخول المزدوج ويُنهى الأقدم.
  const bsid = useRef((() => {
    try {
      if (typeof window !== 'undefined' && window.__bsidTest) return window.__bsidTest;   // خطّاف اختبار آلي فقط
      let v = localStorage.getItem('rms8:bsid');
      if (!v) { v = uid('bw'); localStorage.setItem('rms8:bsid', v); }
      return v;
    } catch { return uid('bw'); }
  })());
  const claimRef = useRef({ done: false, at: 0 });          // مطالبة هذا المتصفح بجلسة المستخدم الحالي
  const [kickMsg, setKickMsg] = useState(null);             // سبب الإنهاء التلقائي — يُعرض في بوابة الدخول
  const toastTimer = useRef(null);

  // v15.14: نلغي أي مؤقّت إخفاء سابق قبل جدولة مؤقّت جديد — وإلا فرسالة سريعة تالية لأخرى
  // خلال أقل من 3.2 ثانية (كإضافة شريك ثم ترقيته مباشرة) قد تُخفى قبل أن يراها المستخدم،
  // لأن مؤقّت الرسالة الأقدم كان سيبقى يعمل ويُخفي الرسالة الأحدث دون علاقة بها.
  const say = useCallback((msg, kind) => {
    if (toastTimer.current) clearTimeout(toastTimer.current);
    setToast({ msg, kind: kind || 'ok' });
    toastTimer.current = setTimeout(() => setToast(null), 3200);
  }, []);

  /* --- الإقلاع: مع المصادقة السحابية لا تُحمَّل أي بيانات قبل دخول حقيقي --- */
  const [needAuth, setNeedAuth] = useState(false);

  // v9: سياق الجلسة — مركزية (ترى كل الفروع) أم فرعية (مستند فرعها فقط)
  const dataCtx = useRef({ central: true, myBrIds: [], email: '' });

  const loadAll = useCallback(async (email) => {
    if (email) dataCtx.current.email = (email || '').toLowerCase();
    const t = await cloud.tryGet(KEYS.org);
    let o = t.value;

    if (t.denied || (window.__forceDirOnly && !o?.__ignore)) {
      /* ===== مسار الفرع: الخادم رفض المنشأة الكاملة — نقرأ الدليل العام فقط ===== */
      // v27.1: tryGet بدل get — رفض الصلاحيات يُعلَن صراحةً (ولا يُخفى بنسخة localStorage قديمة)
      const dr = await cloud.tryGet(KEYS.dir);
      const dir = dr.value || null;
      if (dr.denied) setAccessErr({ kind: 'dir' });
      if (!dir) { setBoot('ready'); setNeedAuth(false); setOrg(emptyOrg()); setOps(emptyOps()); return emptyOrg(); }
      o = { ...emptyOrg(), ...dir };
      const em = dataCtx.current.email || ((await authApi.ready()) || {}).email || '';
      const meU = (o.users || []).find(x => (x.email || '').toLowerCase() === em && x.isActive);
      // v27.1: نطاق الجلسة يطابق myBranches حرفيًا (المدير الإقليمي = فروعه المُسندة وإن كان له branchId)
      const myBr = branchIdsOfUser(meU) || [];
      dataCtx.current = { central: false, myBrIds: myBr, email: em };
      const brMap = {}; const deniedBr = [];
      for (const b of myBr) { const r = await cloud.tryGet(brKey(b)); if (r.denied) deniedBr.push(b); brMap[b] = r.value || {}; }
      if (deniedBr.length) {
        // نقارن عضوية الخادم (التي تعتمد عليها القواعد) بسجل المستخدم في المنصة لتسمية السبب بدقة
        let mem = null; try { mem = await authApi.myMembership(); } catch { mem = null; }
        setAccessErr({ kind: 'branch', ids: deniedBr, mem, expected: myBr });
      }
      docsCache.current = { core: null, br: brMap };
      setOps(composeOps(null, brMap));
      setOrg(o);
      setPulse(await cloud.get(KEYS.pulse, { presence: {}, audit: [] }));
      setLastSync(new Date()); setBoot('ready');
      return o;
    }

    /* ===== مسار المركز ===== */
    if (!o || !o.branches) {
      o = emptyOrg();
      await cloud.set(KEYS.org, o);
      await cloud.set(KEYS.ops, emptyOps());
      await cloud.set(KEYS.pulse, { presence: {}, audit: [] });
    }
    // الهجرة الآمنة لمرة واحدة: لقطة أمان ثم تقسيم القديم
    if (!o.migratedV9 && (o.branches || []).length) {
      try { const oldOps = (await cloud.get(KEYS.ops, null)) || emptyOps(); await snapPut('pre-v9-migration-' + today(), { at: nowISO(), by: 'migration', org: o, ops: oldOps }); } catch { }
      const oldOps = (await cloud.get(KEYS.ops, null)) || emptyOps();
      o = await migrateV9(o, oldOps);
    }
    // مزامنة نطاقات الأعضاء (فرع/مركز) مع مستندات العضوية — تعتمد عليها القواعد الخادمية
    if (authApi.enabled && o.migratedV9 && !o.membersSyncedV9) {
      try {
        for (const u2 of (o.users || [])) {
          if (!u2.email) continue;
          await authApi.upsertMember(u2.email, { active: u2.isActive !== false, role: u2.role, branchId: u2.branchId || '', branchIds: u2.allowedBranchIds || [], scope: (ROLES[u2.role]?.scope === 'all') ? 'all' : 'branch' });
        }
        o = { ...o, membersSyncedV9: nowISO() };
        await cloud.set(KEYS.org, o);
      } catch { }
    }
    // v24.0: نقل بيانات HR من org إلى مستندات الفروع + تجديد الدليل العام (يحمل الآن إعدادات HR غير الحساسة) — مرة واحدة
    if (o.migratedV9 && !o.hrMigratedV24) {
      try {
        const o3 = await migrateHrToOps(o);
        if (await cloud.set(KEYS.org, o3)) { o = o3; try { await cloud.set(KEYS.dir, dirOf(o)); } catch { } }
      } catch (e) { console.warn('هجرة HR v24.0 لم تكتمل — ستُعاد في التحميل التالي:', e); }
    }
    const branchIds = (o.branches || []).map(b => b.id);
    dataCtx.current = { central: true, myBrIds: branchIds, email: dataCtx.current.email };
    const core = (await cloud.get(KEYS.core, null)) || {};
    const brMap = {};
    for (const b of branchIds) brMap[b] = (await cloud.get(brKey(b), null)) || {};
    // v27.1: تهيئة المخبأ الحيّ منذ الإقلاع — كان يبقى فارغًا حتى تصل لقطة كل مستند فرع (ومستند فرع غير موجود
    // لا يرسل لقطة أبدًا) فتتعطّل إعادة التجميع اللحظية حتى أول استطلاع دوري (٥ دقائق) — أي أن حضورًا يُسجَّل
    // من جهاز فرع قد لا يظهر في المركز إلا بعد دقائق أو بعد «مزامنة الآن».
    docsCache.current = { core, br: brMap };
    setOps(composeOps(core, brMap));
    setOrg(o);
    setPulse(await cloud.get(KEYS.pulse, { presence: {}, audit: [] }));
    setLastSync(new Date());
    setBoot('ready');
    return o;
  }, []);

  useEffect(() => {
    (async () => {
      if (authApi.enabled) {
        const u = await authApi.ready();
        if (!u) { setNeedAuth(true); setBoot('ready'); return; }   // بوابة الدخول أولاً
        await authApi.bootstrap();
        // جلسة قائمة لعضوية أُوقفت لاحقاً → خروج وعرض البوابة (الرسالة تظهر عند محاولة الدخول)
        const mem = await authApi.myMembership();
        if (mem && !mem.active) {
          await authApi.signOutAll().catch(() => { });
          setNeedAuth(true); setBoot('ready'); return;
        }
        const o2 = await loadAll(u.email);
        // v15.15 — إصلاح جذري: جلسة موثّقة قائمة كانت تحمّل البيانات ثم تعرض بوابة «ثانية»
        // تفحص كلمة السر محليًا (passHash قد يكون قديمًا/غير متزامن) فيعلق المستخدم على
        // «كلمة السر غير صحيحة» رغم أن مصادقته السحابية صحيحة تمامًا. الصحيح: من اجتاز
        // المصادقة السحابية وعضويته نشطة وحسابه مسجَّل بالمنصة يدخل مباشرة — نفس منطق
        // finishFb حرفيًا بعد الدخول اليدوي.
        const uu = ((o2 && o2.users) || []).find(x => (x.email || '').toLowerCase() === u.email && x.isActive);
        if (uu) {
          setMe(uu); setTab('home');
          try { localStorage.setItem('rms8:lastEmail', uu.email || ''); } catch { }
        } else if (((o2 && o2.users) || []).length > 0) {
          // جلسة موثّقة لبريد لم يعد مسجّلًا/نشطًا بالمنصة (حساب حُذف مثلاً): خروج وبوابة
          // المصادقة — لا بوابة محلية عالقة بلا مخرج.
          await authApi.signOutAll().catch(() => { });
          setNeedAuth(true);
        }
        return;
      }
      await loadAll();
    })();
  }, [loadAll]);

  /* --- دخول المصادقة السحابية --- */
  const mapAuthErr = (e) => {
    const c = String((e && e.code) || '');
    if (c.includes('user-not-found')) return 'لا يوجد حساب مصادقة بهذا البريد — إن كنت المالك استخدم «الإعداد الأول»، وإلا اطلب من المدير إنشاءه';
    if (c.includes('wrong-password') || c.includes('invalid-credential') || c.includes('invalid-login')) return 'كلمة السر غير صحيحة';
    if (c.includes('too-many-requests')) return 'محاولات كثيرة — انتظر دقائق ثم أعد المحاولة';
    if (c.includes('email-already-in-use')) return 'هذا البريد له حساب مصادقة — استخدم «دخول» بكلمة سرّه';
    if (c.includes('weak-password')) return 'كلمة السر ضعيفة — 6 أحرف على الأقل';
    if (c.includes('invalid-email')) return 'صيغة البريد غير صحيحة';
    if (c.includes('network')) return 'تعذّر الاتصال — تحقق من الشبكة';
    return 'تعذّر الدخول (' + c.replace('auth/', '') + ')';
  };

  const finishFb = useCallback(async (email) => {
    await authApi.bootstrap();
    // بوابة العضوية: موثّق بلا عضوية نشطة لا يُكمل — رسالة واضحة بدل شاشة مشوّشة
    const mem = await authApi.myMembership();
    if (mem && !mem.active) {
      await authApi.signOutAll().catch(() => { });
      return {
        ok: false, err: mem.exists
          ? 'عضويتك موقوفة — راجع مسؤول النظام'
          : 'حسابك موثّق لكن عضويتك غير مهيأة بعد — اطلب من المدير فتح حسابك في «الفروع والمستخدمون» وحفظه'
      };
    }
    const o = await loadAll(email);
    const u = (o.users || []).find(x => (x.email || '').toLowerCase() === email && x.isActive);
    if (!u && (o.users || []).length > 0) {
      await authApi.signOutAll().catch(() => { });
      return { ok: false, err: 'حسابك موثّق لكنه غير مُسجَّل في المنصة — يضيفه مسؤول النظام من «الفروع والمستخدمون»' };
    }
    setNeedAuth(false);
    if (u) {
      setMe(u); setTab('home');
      try { localStorage.setItem('rms8:lastEmail', u.email || ''); } catch { }
    }
    return { ok: true };   // لا مستخدمين بعد → شاشة التهيئة الأولى
  }, [loadAll]);

  const fbLogin = useCallback(async (email, pass) => {
    try { const r = await authApi.signIn(email, pass); return await finishFb(r.email); }
    catch (e) { return { ok: false, err: mapAuthErr(e) }; }
  }, [finishFb]);

  const fbFirstSetup = useCallback(async (email, pass) => {
    try { const r = await authApi.firstSetup(email, pass); return await finishFb(r.email); }
    catch (e) { return { ok: false, err: mapAuthErr(e) }; }
  }, [finishFb]);

  useEffect(() => {
    const on = () => setOffline(false), off = () => setOffline(true);
    window.addEventListener('online', on); window.addEventListener('offline', off);
    return () => { window.removeEventListener('online', on); window.removeEventListener('offline', off); };
  }, []);

  // v16.2 — بطلب المالك: نوافذ الإدخال والاستعراض تتبع ألوان الشاشة (الوضع الفاتح/الداكن
  // والثيم المختار). النوافذ تُرسم عبر portal خارج غلاف الثيم فكانت تبقى داكنة دائماً؛
  // مزامنة أصناف الثيم على body تجعلها ترث الثيم والوضع الحاليين تلقائياً.
  useEffect(() => {
    const cs = themeCls(theme, mode).split(' ').filter(Boolean);
    document.body.classList.add(...cs);
    return () => document.body.classList.remove(...cs);
  }, [theme, mode]);

  useEffect(() => {
    const bip = (e) => { e.preventDefault(); setInstallPrompt(e); };
    const done = () => { setInstalled(true); setInstallPrompt(null); };
    const standalone = window.matchMedia && window.matchMedia('(display-mode: standalone)').matches;
    if (standalone || window.navigator.standalone) setInstalled(true);
    window.addEventListener('beforeinstallprompt', bip);
    window.addEventListener('appinstalled', done);
    return () => { window.removeEventListener('beforeinstallprompt', bip); window.removeEventListener('appinstalled', done); };
  }, []);

  const doInstall = useCallback(async () => {
    if (!installPrompt) {
      const iOS = /iphone|ipad|ipod/i.test(navigator.userAgent);
      say(iOS
        ? 'على آيفون: اضغط زر المشاركة في المتصفح ثم «إضافة إلى الشاشة الرئيسية»'
        : 'لتثبيت التطبيق: افتح قائمة المتصفح واختر «تثبيت التطبيق» أو «Install app»', 'ok');
      return;
    }
    installPrompt.prompt();
    const res = await installPrompt.userChoice;
    if (res.outcome === 'accepted') say('تم تثبيت التطبيق على جهازك');
    setInstallPrompt(null);
  }, [installPrompt, say]);

  // v11.1 — تحديث فوري للأحدث: يزيل عامل الخدمة وكل الكاش ويعيد التحميل بلا تخزين مؤقت (يعمل على الجوال بضغطة)
  const forceUpdate = useCallback(async () => {
    try {
      if ('serviceWorker' in navigator) { const regs = await navigator.serviceWorker.getRegistrations(); await Promise.all(regs.map(r => r.unregister())); }
      if (typeof caches !== 'undefined') { const ks = await caches.keys(); await Promise.all(ks.map(k => caches.delete(k))); }
    } catch (e) { /* تجاهل */ }
    location.replace(location.pathname + '?u=' + Date.now());   // معلمة كسر الكاش تضمن جلب index.html جديدًا
  }, []);

  // v11.1 — كشف تلقائي لنسخة أحدث منشورة: يقارن اسم حزمة index.html المنشورة باسم الحزمة الجارية
  useEffect(() => {
    const grab = (s) => (String(s || '').match(/assets\/index-[\w-]+\.js/) || [])[0] || '';
    const mineEl = document.querySelector('script[type=module][src*="assets/index-"]');
    const mine = grab(mineEl && mineEl.getAttribute('src'));
    if (!mine) return;   // بيئة تطوير (بلا حزمة مُجمّعة) — لا فحص
    let stop = false;
    const check = async () => {
      try {
        const r = await fetch(location.pathname + '?_c=' + Date.now(), { cache: 'no-store' });
        if (!r.ok) return; const html = await r.text(); const latest = grab(html);
        if (latest && latest !== mine && !stop) setUpdateReady(true);
      } catch (e) { /* غير متصل — تجاهل */ }
    };
    const t = setInterval(check, 150000);        // كل ٢٫٥ دقيقة
    const onFocus = () => check();
    window.addEventListener('focus', onFocus);
    const first = setTimeout(check, 9000);       // فحص أولي بعد التحميل
    return () => { stop = true; clearInterval(t); clearTimeout(first); window.removeEventListener('focus', onFocus); };
  }, []);

  /* --- المزامنة الدورية + الحضور --- */
  const snap = useRef({});
  // v15.28 — مخبأ المستندات الحيّ: الاستماع اللحظي يحدّث نسخة المستند الواصل هنا فقط
  // ويعيد التجميع محلياً بصفر قراءات إضافية (كان كل إشعار يعيد قراءة كل المستندات).
  const docsCache = useRef({ core: null, br: {} });
  const refresh = useCallback(async (silent) => {
    if (silent && typeof document !== 'undefined' && document.hidden) return;
    if (!silent) setSyncing(true);
    const ctx = dataCtx.current;
    const orgKey = ctx.central ? KEYS.org : KEYS.dir;
    const [o, core, pu, ...brs] = await Promise.all([
      cloud.get(orgKey, null),
      ctx.central ? cloud.get(KEYS.core, null) : Promise.resolve(null),
      cloud.get(KEYS.pulse, null),
      ...ctx.myBrIds.map(b => cloud.get(brKey(b), null))
    ]);
    const brMap = {}; ctx.myBrIds.forEach((b, i) => { brMap[b] = brs[i] || {}; });
    docsCache.current = { core: core || null, br: brMap };
    const p = composeOps(core, brMap);
    const put = (k, v, setter) => {
      if (!v) return;
      const j = JSON.stringify(v);
      if (snap.current[k] === j) return;   // لا تغيير — نتفادى إعادة الرسم
      snap.current[k] = j; setter(v);
    };
    put('org', o ? (ctx.central ? o : { ...emptyOrg(), ...o }) : null, setOrg);
    put('ops', p, setOps); put('pulse', pu, setPulse);
    setLastSync(new Date());
    setTimeout(() => setSyncing(false), 350);
  }, []);

  useEffect(() => {
    if (boot !== 'ready' || needAuth) return;
    const subs = [];
    const wire = (slot, key, setter) => {
      const un = cloud.subscribe?.(key, (v) => {
        const j = JSON.stringify(v);
        if (snap.current[slot] === j) return;
        snap.current[slot] = j; setter(v); setLastSync(new Date());
      });
      if (un) subs.push(un);
    };
    const ctx = dataCtx.current;
    wire('org', ctx.central ? KEYS.org : KEYS.dir, (v) => setOrg(ctx.central ? v : { ...emptyOrg(), ...v }));
    wire('pulse', KEYS.pulse, setPulse);
    // v15.28: المستند الواصل لحظياً يُخزَّن في المخبأ ويُعاد التجميع محلياً — صفر قراءات
    // إضافية (سابقاً كان كل إشعار يستدعي refresh كاملاً يقرأ كل المستندات من جديد).
    const cacheRecompose = () => {
      const dc = docsCache.current;
      const ready = (!ctx.central || dc.core != null) && ctx.myBrIds.every(b => dc.br[b] != null);
      if (!ready) return;   // اللقطات الأولى لم تكتمل بعد — نُبقي على ما حمّله الإقلاع
      const composed = composeOps(ctx.central ? dc.core : null, dc.br);
      const j = JSON.stringify(composed);
      if (snap.current.ops === j) return;
      snap.current.ops = j; setOps(composed); setLastSync(new Date());
    };
    if (ctx.central) { const un = cloud.subscribe?.(KEYS.core, (v) => { docsCache.current.core = v || {}; cacheRecompose(); }); if (un) subs.push(un); }
    ctx.myBrIds.forEach(b => { const un = cloud.subscribe?.(brKey(b), (v) => { docsCache.current.br[b] = v || {}; cacheRecompose(); }); if (un) subs.push(un); });
    if (subs.length) setLive(true);
    return () => subs.forEach(u => u());
  }, [boot, needAuth, refresh, brSetVer]);   // v27.3: brSetVer يُعيد بناء الاشتراكات عند تغيّر مجموعة الفروع (فرع جديد يظهر حيًّا بلا إعادة تحميل)

  useEffect(() => {
    if (boot !== 'ready') return;
    // v15.28: مع الاستماع اللحظي (الذي يوصل كل تغيير فور وقوعه) يكفي استطلاع احتياطي كل
    // ٥ دقائق بدل ٤٥ ثانية — خفض قراءات الاستطلاع نحو ٧ أضعاف دون أي تأثير على الفورية.
    const t = setInterval(() => refresh(true), live ? 300000 : 8000);
    // v27.1: العودة إلى التبويب = مزامنة فورية (الاستطلاع الدوري يتوقف والتبويب مخفي، فقد يتأخر ما سجّلته الفروع)
    const onVis = () => { if (typeof document !== 'undefined' && !document.hidden) refresh(true); };
    if (typeof document !== 'undefined') document.addEventListener('visibilitychange', onVis);
    return () => { clearInterval(t); if (typeof document !== 'undefined') document.removeEventListener('visibilitychange', onVis); };
  }, [boot, live, refresh]);

  // v9: نضبط نطاق فروع الجلسة بعد الإقلاع.
  // v27.3: يشمل الآن حساب المركز أيضًا — كان مستثنى صراحةً، فأي فرع يُنشأ/يُسند بعد فتح صفحة
  // المركز لم يكن يُقرأ مستنده ولا يُشترَك فيه حتى إعادة تحميل كاملة، فلا يظهر حضوره ولا بياناته
  // في المركز والتقارير. الآن عند تغيّر قائمة الفروع نحدّث النطاق ونعيد بناء الاشتراكات فورًا.
  useEffect(() => {
    if (!me) return;
    const central = dataCtx.current.central;
    const ids = central ? (org.branches || []).map(b => b.id) : (branchIdsOfUser(me) || []);
    if (JSON.stringify(ids) !== JSON.stringify(dataCtx.current.myBrIds)) {
      dataCtx.current.myBrIds = ids;
      if (!central) dataCtx.current.email = (me.email || '').toLowerCase();
      setBrSetVer(v => v + 1);   // يُعيد تشغيل تأثير الاشتراكات على المجموعة الجديدة
      refresh(true);
    }
  }, [me, org, refresh]);

  /* --- تنبيهات النشاط الحيّة لمدراء النظام: إشعار متصفح + صوت لأي نشاط من الآخرين --- */
  const actBaseRef = useRef(Date.now());
  useEffect(() => { actBaseRef.current = Date.now(); }, [me]);

  // v8.5: لقطة احتياطية يومية محلية تلقائية (أجهزة أدوار الإدارة فقط) — آخر 7 أيام
  const snapDoneRef = useRef(false);
  useEffect(() => {
    if (snapDoneRef.current || !me || !ROLES[me.role]?.admin || !(org.branches || []).length) return;
    snapDoneRef.current = true;
    (async () => {
      try {
        const key = 'day-' + today();
        const all = await snapAll();
        if (!all.some(x => x.key === key)) {
          await snapPut(key, { at: nowISO(), by: me.name, org, ops });
          const days = all.filter(x => (x.key || '').startsWith('day-')).sort((a, b) => b.key.localeCompare(a.key));
          for (const old2 of days.slice(6)) await snapDel(old2.key);
        }
      } catch { /* متصفح بوضع خاص أو تخزين ممتلئ — النسخة الملفية تبقى متاحة */ }
    })();
  }, [me, org, ops]);
  useEffect(() => {
    if (!me || !ROLES[me.role]?.admin) return;
    const cfg = notifyCfg();
    if (!cfg.on) return;
    const fresh = (pulse.audit || []).filter(e => (e.at || 0) > actBaseRef.current && e.userName !== me.name);
    if (!fresh.length) return;
    actBaseRef.current = Math.max(...fresh.map(e => e.at || 0));
    const e = fresh[0];
    const more = fresh.length > 1 ? ` (+${fresh.length - 1} نشاط آخر)` : '';
    const body = `${e.userName}: ${e.title}${e.details ? ' — ' + String(e.details).slice(0, 90) : ''}${more}`;
    notifyBrowser('نشاط جديد — ' + (org.company?.name || 'المنصة'), body, org.company?.logoUrl);
    if (cfg.sound) alertBeep();
  }, [pulse, me, org]);

  /* --- v15.24: مهلة انتهاء الجلسة (خمول) — معطّلة افتراضياً، تُفعَّل من إعدادات النظام --- */
  const lastActRef = useRef(Date.now());
  const [sessWarnLeft, setSessWarnLeft] = useState(null);   // ثوانٍ متبقية في التحذير، null = لا تحذير
  const [locked, setLocked] = useState(false);              // v15.25: شاشة القفل — عودة بالدخول السريع (رقم سري/بصمة)
  useEffect(() => {
    const bumpAct = () => { lastActRef.current = Date.now(); };
    const evs = ['pointerdown', 'keydown', 'touchstart', 'wheel'];
    evs.forEach(ev => window.addEventListener(ev, bumpAct, { passive: true }));
    return () => evs.forEach(ev => window.removeEventListener(ev, bumpAct));
  }, []);
  const sessLogout = useCallback(async () => {
    setSessWarnLeft(null); setLocked(false);
    // خروج سحابي صحيح: إنهاء جلسة المصادقة أيضاً حتى تظهر بوابة الدخول الحقيقية لا بوابة محلية
    if (authApi.enabled) { try { await authApi.signOutAll(); } catch { } setNeedAuth(true); }
    setMe(null);
  }, []);
  useEffect(() => {
    const cfg = (org && org.sessionCfg) || {};
    if (!me || !cfg.enabled || locked) { setSessWarnLeft(null); return; }
    // خطّافا اختبار (على غرار __forceOrgReadonly): يقصّران المهلة والتحذير للفحص الآلي فقط
    const limit = (typeof window !== 'undefined' && window.__sessTestMs) || Math.max(1, Number(cfg.minutes) || 15) * 60000;
    const warnDur = (typeof window !== 'undefined' && window.__sessTestWarnMs) || 60000;
    const t = setInterval(() => {
      const idle = Date.now() - lastActRef.current;
      if (idle >= limit + warnDur) {
        // v15.25: عند التهيئة على «قفل» ولدى المستخدم دخول سريع (رقم سري/بصمة) نقفل الشاشة
        // بدل الخروج الكامل؛ من لا يملك أياً منهما يسقط للخروج الكامل الآمن.
        if (cfg.onTimeout === 'lock' && (me.pinHash || me.bioCredId)) {
          setSessWarnLeft(null); lastActRef.current = Date.now(); setLocked(true);
        } else sessLogout();
      }
      else if (idle >= limit) setSessWarnLeft(Math.max(0, Math.ceil((limit + warnDur - idle) / 1000)));
      else setSessWarnLeft(w => (w == null ? w : null));   // عاد النشاط أثناء التحذير — يختفي تلقائياً
    }, 1000);
    return () => clearInterval(t);
  }, [me, org, locked, sessLogout]);

  // v15.29: رسالة الإنهاء التلقائي (دخول من متصفح آخر) — تُمسح فور دخول ناجح جديد
  useEffect(() => { if (me) setKickMsg(null); }, [me]);
  const kickOut = useCallback(() => {
    setKickMsg('تم تسجيل الدخول لحسابك من متصفح أو جهاز آخر، فأُنهيت هذه الجلسة تلقائياً حفاظاً على سلامة إدخال البيانات. إن لم يكن ذلك أنت فغيّر كلمة السر فوراً.');
    sessLogout();
  }, [sessLogout]);

  useEffect(() => {
    if (!me) return;
    // v15.29 — جلسة واحدة لكل مستخدم (عدا أدوار الإدارة admin): عند الدخول يطالب هذا
    // المتصفح بالجلسة داخل مستند النبض (logins[معرّف المستخدم] = هوية المتصفح + لحظة
    // الدخول)، وأي متصفح آخر لنفس المستخدم يكتشف مطالبة أحدث فيخرج تلقائياً — الأحدث
    // دائماً يفوز، فلا إدخال مزدوج متعارض. صفر قراءات إضافية: الفحص داخل قراءة النبضة
    // القائمة أصلاً، والاكتشاف اللحظي عبر اشتراك النبض القائم أصلاً.
    claimRef.current = { done: false, at: Date.now() };
    const single = !(ROLES[me.role] || {}).admin;
    const beat = async () => {
      if (typeof document !== 'undefined' && document.hidden) return;
      const pu = await cloud.get(KEYS.pulse, { presence: {}, audit: [] });
      if (single && claimRef.current.done) {
        const lg = (pu.logins || {})[me.id];
        if (lg && lg.sid !== bsid.current && (lg.at || 0) > claimRef.current.at) { kickOut(); return; }
        // مطالبة أقدم أو ممسوحة بكتابة متزامنة عتيقة → نعيد كتابة مطالبتنا الأحدث أدناه
      }
      const pres = { ...(pu.presence || {}) };
      pres[sid.current] = { name: me.name, role: me.role, at: Date.now() };
      Object.keys(pres).forEach(k => { if (Date.now() - (pres[k].at || 0) > 150000) delete pres[k]; });
      const next = { ...pu, presence: pres };
      if (single) {
        next.logins = { ...(pu.logins || {}) };
        next.logins[me.id] = { sid: bsid.current, at: claimRef.current.at, name: me.name };
        claimRef.current.done = true;
      }
      await cloud.set(KEYS.pulse, next);
      setPulse(next);
    };
    beat();
    const t = setInterval(beat, 60000);
    const onVis = () => { if (!document.hidden) beat(); };   // عودة التبويب = نبضة فورية
    document.addEventListener('visibilitychange', onVis);
    return () => { clearInterval(t); document.removeEventListener('visibilitychange', onVis); };
  }, [me, kickOut]);

  // v15.29: الاكتشاف اللحظي — أي تحديث للنبض يصل (اشتراك لحظي أو استطلاع) يُفحص فوراً،
  // فالمتصفح الأقدم يخرج خلال ثوانٍ من دخول الأحدث دون انتظار النبضة التالية.
  useEffect(() => {
    if (!me || (ROLES[me.role] || {}).admin || !claimRef.current.done) return;
    const lg = (pulse.logins || {})[me.id];
    if (lg && lg.sid !== bsid.current && (lg.at || 0) > claimRef.current.at) kickOut();
  }, [pulse, me, kickOut]);

  /* --- v9: الكتابة الآمنة الموجَّهة — التعديل يقع على ops المدمجة كما اعتاد كل الكود،
         ثم يُوزَّع على المستند المركزي ومستندات الفروع، ولا يُكتب إلا ما تغيّر فعلًا.
         محاولة كتابة خارج نطاق الجلسة يرفضها الخادم فيفشل الحفظ بصدق --- */
  const writeOps = useCallback(async (mutator) => {
    const ctx = dataCtx.current;
    lastWriteErr.current = '';
    for (let attempt = 0; attempt < 3; attempt++) {
      // أحدث نسخة لكل مستند ضمن نطاقي
      const core = ctx.central ? ((await cloud.get(KEYS.core, null)) || {}) : null;
      const brMap = {};
      for (const b of ctx.myBrIds) {
        // v27.1: على مسار الفرع، رفض القراءة = رفض كتابة حتمًا — نُبلغ بدقة بدل الكتابة فوق نسخة localStorage قديمة
        const r = await cloud.tryGet(brKey(b));
        if (r.denied) { lastWriteErr.current = 'denied'; setAccessErr(a => a || { kind: 'branch', ids: [b], expected: ctx.myBrIds }); return false; }
        brMap[b] = r.value || {};
      }
      const latest = composeOps(core, brMap);
      const next = mutator(JSON.parse(JSON.stringify(latest)));
      // v27.1: على مسار الفرع لا يُكتب المستند المركزي — أي سجل جديد بلا فرع أو لفرع خارج نطاقي كان يضيع بصمت
      // (يظهر محليًا ثم يختفي بعد إعادة التحميل). نرفضه صراحةً.
      if (!ctx.central) {
        const lost = outOfScopeRecords(next, latest, ctx.myBrIds);
        if (lost.length) { lastWriteErr.current = 'scope'; console.warn('writeOps: سجلات خارج نطاق الفرع لن تُحفظ', lost, ctx.myBrIds); return false; }
      }
      const { core: coreOut, br: brOut } = splitOps(next, ctx.myBrIds);

      let allOk = true, conflict = false;
      let wroteCoreDoc = null; const wroteBrDocs = {};
      // المستند المركزي (أدوار المركز فقط)
      if (ctx.central) {
        if (!sameDoc(coreOut, core)) {
          const rv = ((core || {}).rev || 0) + 1;
          const doc = { ...coreOut, rev: rv, wtag: uid('w') };   // v27.2: وسم كاتب لكشف التصادم
          const ok = await cloud.set(KEYS.core, doc);
          if (!ok) { allOk = false; }
          else { const chk = await cloud.get(KEYS.core, null); if (!wroteMine(chk, doc)) conflict = true; else wroteCoreDoc = doc; }
        }
      }
      // مستندات الفروع المتغيرة فقط
      for (const b of ctx.myBrIds) {
        if (!sameDoc(brOut[b], brMap[b])) {
          const rv = ((brMap[b] || {}).rev || 0) + 1;
          const doc = { ...brOut[b], rev: rv, wtag: uid('w') };   // v27.2: وسم كاتب لكشف التصادم
          const ok = await cloud.set(brKey(b), doc);
          if (!ok) { allOk = false; if (String((cloud.lastError || {}).code || '').toLowerCase().includes('permission')) { lastWriteErr.current = 'denied'; return false; } }
          else { const chk = await cloud.get(brKey(b), null); if (!wroteMine(chk, doc)) conflict = true; else wroteBrDocs[b] = doc; }
        }
      }
      if (!allOk) { if (attempt === 2) { lastWriteErr.current = lastWriteErr.current || 'net'; return false; } continue; }
      if (conflict) continue;   // كتب آخر بنفس اللحظة — نعيد على الأحدث
      // v15.28: نجاح — ما كتبناه (وما قرأناه للتو قبله) هو الحالة الكاملة بين أيدينا؛
      // لا حاجة لإعادة قراءة كل المستندات من السحابة (كانت تكلف قراءة لكل فرع بعد كل حفظ).
      if (ctx.central) docsCache.current.core = wroteCoreDoc || core || {};
      for (const b of ctx.myBrIds) docsCache.current.br[b] = wroteBrDocs[b] || brMap[b] || {};
      snap.current.ops = JSON.stringify(next); setOps(next);
      return true;
    }
    return false;
  }, []);

  const commit = useCallback(async (mutator, log) => {
    // v15.12: البوابة المركزية — ترفض أي حفظ حسّاس (log.need) لا يملك المستخدم صلاحيته، مهما كان مصدر النداء.
    if (log?.need && !capOK(me?.role, log.need)) { say('لا تملك صلاحية هذا الإجراء — تواصل مع مدير النظام', 'no'); return false; }
    const ok = await writeOps(mutator);
    if (!ok) {
      // v27.1: رسالة تُسمّي السبب — رفض صلاحيات الخادم (عضوية الحساب لا تحمل فرعه) يختلف تمامًا عن انقطاع الشبكة
      const k = lastWriteErr.current;
      if (k === 'denied') say('رفض الخادم حفظ بيانات فرعك (صلاحيات، لا اتصال): عضوية حسابك على الخادم لا تحمل هذا الفرع — اطلب من مسؤول النظام «مزامنة صلاحيات الأعضاء» من الفروع والمستخدمين ثم أعد الدخول', 'no');
      else if (k === 'scope') say('لم يُحفظ: السجل يخص فرعًا خارج نطاق حسابك (أو بلا فرع) — راجع إعداد فرع حسابك', 'no');
      else say('تعذّر الحفظ السحابي بعد عدة محاولات — تحقق من الاتصال وأعد المحاولة', 'no');
      return false;
    }
    if (log && me) {
      const pu = (await cloud.get(KEYS.pulse, { presence: {}, audit: [] })) || { presence: {}, audit: [] };
      const entry = {
        id: uid('lg'), timestamp: nowISO(), at: Date.now(), userName: me.name, userRole: me.role,
        userRoleLabel: (ROLES[me.role] || {}).ar || me.role, ...log
      };
      const nx = { ...pu, audit: [entry, ...(pu.audit || [])].slice(0, 150) };
      await cloud.set(KEYS.pulse, nx);
      setPulse(nx);
    }
    setLastSync(new Date());
    return true;
  }, [writeOps, me, say]);

  const commitOrg = useCallback(async (mutator, log) => {
    // v15.12: البوابة المركزية — نفس الحارس على كتابات الإعدادات/المنشأة.
    if (log?.need && !capOK(me?.role, log.need)) { say('لا تملك صلاحية هذا الإجراء — تواصل مع مدير النظام', 'no'); return false; }
    const latest = (await cloud.get(KEYS.org, null)) || org;
    const next = mutator(JSON.parse(JSON.stringify(latest)));
    const ok = await cloud.set(KEYS.org, next);
    if (!ok) { say('تعذّر حفظ الإعدادات سحابياً — أعد المحاولة', 'no'); return false; }
    // v9: كل تعديل للمنشأة يجدّد الدليل العام المنزوع الأسرار الذي تقرؤه أجهزة الفروع
    try { await cloud.set(KEYS.dir, dirOf(next)); } catch { }
    snap.current.org = JSON.stringify(next);
    setOrg(next);
    if (log && me) {
      const pu = (await cloud.get(KEYS.pulse, { presence: {}, audit: [] })) || { presence: {}, audit: [] };
      const entry = { id: uid('lg'), timestamp: nowISO(), at: Date.now(), userName: me.name, userRole: me.role, userRoleLabel: (ROLES[me.role] || {}).ar || me.role, ...log };
      const nx = { ...pu, audit: [entry, ...(pu.audit || [])].slice(0, 150) };
      await cloud.set(KEYS.pulse, nx);
      setPulse(nx);
    }
    setLastSync(new Date());
    return true;
  }, [org, me, say]);

  const resetAll = useCallback(async () => {
    if (!window.confirm('سيُحذف كل ما أدخلته نهائياً (الإغلاقات، الموظفون، الموردون) وتعود المنصة فارغة. هل أنت متأكد؟')) return;
    const keepCompany = org?.company;
    const o = emptyOrg(keepCompany); const p = emptyOps();
    await cloud.set(KEYS.org, o); await cloud.set(KEYS.ops, p);
    await cloud.set(KEYS.core, { rev: 1 });
    for (const b of (org.branches || [])) await cloud.set(brKey(b.id), { rev: 1 });
    await cloud.set(KEYS.dir, dirOf(o));
    await cloud.set(KEYS.pulse, { presence: {}, audit: [] });
    setOrg(o); setOps(p); setPulse({ presence: {}, audit: [] });
    say('تمت إعادة المنصة إلى الوضع الفارغ');
  }, [say, org]);

  /* --- نطاق الفروع حسب الدور --- */
  const myBranches = useMemo(() => {
    if (!org || !me) return [];
    const s = (ROLES[me.role] || ROLES.cashier).scope;   // دور غير معروف → أضيق صلاحية بدل انهيار الواجهة
    if (s === 'all') return org.branches;
    if (s === 'own') return org.branches.filter(b => b.id === me.branchId);
    return org.branches.filter(b => (me.allowedBranchIds || []).includes(b.id));
  }, [org, me]);

  const scoped = useMemo(() => {
    const ids = myBranches.map(b => b.id);
    return {
      closings: (ops.closings || []).filter(c => ids.includes(c.branchId)),
      transfers: (ops.transfers || []).filter(t => ids.includes(t.branchId)),
      advances: (ops.advances || []).filter(a => ids.includes(a.branchId))
    };
  }, [ops, myBranches]);

  if (boot === 'loading') {
    return (
      <div className="rms" style={{ display: 'grid', placeItems: 'center', minHeight: '100vh' }}>
        <style dangerouslySetInnerHTML={{ __html: CSS }} />
        <div style={{ textAlign: 'center' }}>
          <RefreshCw size={26} color="#C8A24A" className="spin" />
          <div style={{ marginTop: 12, color: '#A2968A', fontSize: 13 }}>جارٍ الاتصال بالسحابة…</div>
        </div>
      </div>
    );
  }

  // مصادقة سحابية مفعّلة ولا جلسة: بوابة الدخول الحقيقية قبل تحميل أي بيانات
  if (needAuth && !me) {
    return <FbGate css={CSS} theme={theme} fbLogin={fbLogin} fbFirstSetup={fbFirstSetup} notice={kickMsg} />;
  }

  // أول تشغيل: لا يوجد أي مستخدم بعد → شاشة التسجيل الأولي لإنشاء حساب المالك
  if ((org.users || []).length === 0) {
    return <FirstRun css={CSS} theme={theme} commitOrg={commitOrg} say={say}
      onDone={(u) => { setMe(u); setTab('admin'); }} />;
  }

  if (!me) {
    return <Gate css={CSS} theme={theme} org={org} notice={kickMsg}
      onLogin={(u) => { setMe(u); setTab('home'); }}
      online={Object.values(pulse.presence || {}).filter(p => Date.now() - p.at < 150000)} />;
  }

  // v15.25: الشاشة مقفلة — عودة سريعة برقم سري/بصمة (الجلسة السحابية باقية تحتها)
  if (locked) {
    return <LockScreen me={me} theme={theme} mode={mode}
      onUnlock={() => { setLocked(false); lastActRef.current = Date.now(); }}
      onLogout={sessLogout} />;
  }

  const smartAlertCount = computeSmartAlerts(org, ops, myBranches).length;
  const unread = (ops.notifications || []).filter(n => !n.isRead).length + smartAlertCount;
  const pending = scoped.closings.filter(c => c.status === 'submitted').length;
  const online = Object.values(pulse.presence || {}).filter(p => Date.now() - p.at < 150000);

  // النشاط الجديد منذ آخر مشاهدة للسجل (تنبيه مستمر)
  const auditLog = pulse.audit || [];
  const newActivity = auditLog.filter(a => (a.at || Date.parse(a.timestamp) || 0) > lastSeenAudit && a.userName !== me.name);
  const latestActivity = auditLog[0];

  // التبويبات الفعّالة = تبويبات الدور + تبويبات التطبيقات المُضافة يدويًا − التبويبات المُخفاة بالكامل
  // «الرئيسية» تبقى دائمًا (لا خطر حجب المستخدم — يهبط على الشبكة)
  const roleTabsMe = ROLES[me.role]?.tabs || [];
  const grantTabsMe = (me.appAllow || []).map(id => LAUNCH_IX[id]?.open?.tab).filter(Boolean);
  const denyDedMe = (() => {
    const deny = new Set(me.appDeny || []);
    if (!deny.size) return new Set();
    const byTab = {};
    LAUNCH_APPS.forEach(a => { (byTab[a.open.tab] = byTab[a.open.tab] || []).push(a.id); });
    return new Set(Object.entries(byTab).filter(([t, ids]) => ids.length && ids.every(id => deny.has(id))).map(([t]) => t));
  })();
  const NAV = [
    { id: 'home', ar: 'الرئيسية', icon: Home },
    { id: 'analytics', ar: 'مركز التحليل والأداء', icon: Compass },
    { id: 'alerts', ar: 'مركز التنبيهات', icon: Bell },
    { id: 'reporting', ar: 'مركز التقارير', icon: FileBarChart },
    { id: 'sales', ar: 'المبيعات', icon: CircleDollarSign },
    { id: 'closing', ar: 'الإغلاق اليومي', icon: ClipboardCheck },
    { id: 'shifts', ar: 'مواعيد الإغلاق والتذكيرات', icon: Clock },
    { id: 'hrops', ar: 'الموارد البشرية — التشغيل', icon: Fingerprint },
    { id: 'hrperf', ar: 'الأداء والانضباط', icon: TrendingUp },
    { id: 'apps', ar: 'إدارة التطبيقات', icon: Grid3x3 },
    { id: 'approve', ar: 'التدقيق والاعتماد', icon: ShieldCheck, cnt: pending },
    { id: 'treasury', ar: 'الخزينة والترحيل', icon: Landmark },
    { id: 'people', ar: 'شؤون الموظفين', icon: Wallet },
    { id: 'purchasing', ar: 'المشتريات والموردون', icon: Truck },
    { id: 'inv', ar: 'المخزون والمنتجات', icon: HardDrive },
    { id: 'partners', ar: 'دفتر الشركاء', icon: Users },
    { id: 'acct', ar: 'المحاسبة', icon: Scale },
    { id: 'docs', ar: 'مركز المستندات', icon: Stamp },
    { id: 'archive', ar: 'أرشيف المستندات', icon: ImageIcon },
    { id: 'entities', ar: 'مركز المنشآت', icon: Building2 },
    { id: 'admin', ar: 'الفروع والمستخدمون', icon: UserCog },
    { id: 'audit', ar: 'سجل التدقيق', icon: Eye }
  ].filter(n => n.id === 'home' || ((roleTabsMe.includes(n.id) || grantTabsMe.includes(n.id)) && !denyDedMe.has(n.id)));

  const shared = { org, ops, pulse, me, myBranches, scoped, commit, commitOrg, say, setTab, theme, acctIntent, openAcctView, invIntent, openInvView };

  // حماية: منع الوصول لتبويب غير مسموح لدور المستخدم (بلا hook — بعد returns الشرطية)
  const allowedTabs = [...NAV.map(n => n.id), ...(NAV.some(n => n.id === 'analytics') ? ['exec', 'dash', 'compare', 'growth', 'breakeven', 'scorecard', 'scenario', 'ai'] : []), ...(NAV.some(n => n.id === 'reporting') ? ['reports', 'rbuild', 'boardpack', 'cashflow'] : []), ...(NAV.some(n => n.id === 'people') ? ['payroll', 'workforce'] : []), ...(NAV.some(n => n.id === 'purchasing') ? ['suppliers', 'reorder'] : []), ...(NAV.some(n => n.id === 'hrops') ? ['attendance', 'shiftengine', 'tasks', 'points', 'esign'] : []), ...(NAV.some(n => n.id === 'hrperf') ? ['kpi', 'rolekpi', 'rewards', 'corrective', 'training', 'perfsnap', 'hrdash'] : [])];
  const safeTab = allowedTabs.includes(tab) ? tab : (allowedTabs[0] || 'closing');

  return (
    <div className={themeCls(theme, mode)}>
      <style dangerouslySetInnerHTML={{ __html: CSS + '.spin{animation:sp 1s linear infinite}@keyframes sp{to{transform:rotate(360deg)}}' }} />
      <div className="shell"
        onTouchStart={(e) => {
          if (window.innerWidth > 900) return;
          const t = e.touches[0];
          const startX = t.clientX;
          // فتح: يبدأ اللمس من الحافة اليمنى (بداية RTL) والقائمة مغلقة
          // إغلاق: اللمس والقائمة مفتوحة
          const nearStartEdge = startX > window.innerWidth - 28;
          touchRef.current = {
            x0: startX, y0: t.clientY, active: true,
            mode: drawer ? 'close' : (nearStartEdge ? 'open' : null)
          };
        }}
        onTouchMove={(e) => {
          const r = touchRef.current;
          if (!r.active || !r.mode) return;
          const t = e.touches[0];
          const dx = t.clientX - r.x0;
          const dy = t.clientY - r.y0;
          if (Math.abs(dy) > Math.abs(dx)) return; // تمرير عمودي، تجاهل
          // في RTL: السحب لليسار (dx سالب) يفتح، السحب لليمين (dx موجب) يغلق
          if (r.mode === 'open' && dx < -55) { setDrawer(true); r.mode = null; }
          if (r.mode === 'close' && dx > 55) { setDrawer(false); r.mode = null; }
        }}
        onTouchEnd={() => { touchRef.current.active = false; touchRef.current.mode = null; }}>
        {!drawer && <div className="edgehint" />}
        {drawer && <div className="mask" style={{ zIndex: 55 }} onClick={() => setDrawer(false)} />}
        <aside className={'side' + (drawer ? ' open' : '')}>
          <div className="brand">
            {org.company.logoUrl
              ? <img className="brand-logo" src={org.company.logoUrl} alt="شعار الشركة" />
              : <div className="brand-mark">{(org.company.name || 'مذ').trim().charAt(0) || 'م'}</div>}
            <div style={{ flex: 1, minWidth: 0 }}>
              <div className="brand-t">{org.company.name}</div>
              <div className="brand-s">CLOUD CLOSING SUITE</div>
            </div>
            <button className="btn sm gh sideclose" onClick={() => setDrawer(false)} title="إخفاء القائمة">
              <X size={18} />
            </button>
          </div>
          <div className="nav-lbl">التشغيل اليومي</div>
          {NAV.map(n => (
            <button key={n.id} className={'nav-i' + (tab === n.id ? ' on' : '')}
              onClick={() => { setTab(n.id); setDrawer(false); }}>
              <n.icon size={16} />{n.ar}
              {n.cnt > 0 && <span className="cnt num">{n.cnt}</span>}
            </button>
          ))}
          <div style={{ marginTop: 'auto', paddingTop: 16 }}>
            <div className="mono-b" style={{ marginBottom: 8, padding: '9px 11px' }}>
              <div style={{ minWidth: 0 }}>
                <div style={{ fontSize: 12, fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis' }}>{me.name}</div>
                <div style={{ fontSize: 10, color: 'var(--faint)' }}>{((ROLES[me.role] || {}).ar || me.role).split('—')[0]}</div>
              </div>
              <button className="btn sm gh" onClick={() => setMe(null)} title="خروج"><LogOut size={13} /></button>
            </div>
            {!installed && (
              <button className="nav-i" onClick={doInstall} style={{ fontSize: 11.5, color: 'var(--brass)' }}>
                <Download size={14} />تثبيت التطبيق على الجهاز
              </button>
            )}
            <button className="nav-i" onClick={() => setTour(true)} style={{ fontSize: 11.5 }}>
              <Compass size={14} />جولة تعريفية في المنصة
            </button>
            <button className="nav-i" onClick={resetAll} style={{ fontSize: 11.5 }}>
              <Trash2 size={14} />تفريغ بيانات المنصة
            </button>
          </div>
        </aside>

        <div className="main">
          <header className="top">
            <button className="btn sm gh hidden-desk topmenu" onClick={() => setDrawer(d => !d)} title={drawer ? 'إخفاء القائمة' : 'إظهار القائمة'}>
              {drawer ? <X size={18} /> : <Menu size={18} />}
            </button>
            {safeTab !== 'home' && (
              <button className="homebtn2" onClick={() => setTab('home')} title="الرئيسية — كل التطبيقات">
                <Home size={17} />
              </button>
            )}
            {org.company.logoUrl
              ? <img className="toplogo" src={org.company.logoUrl} alt="شعار الشركة" />
              : <span className="toplogo-mark">{(org.company.name || 'م').trim().charAt(0) || 'م'}</span>}
            <h1 className="toptitle">{safeTab === 'home' ? (org.company.name || 'الرئيسية') : (NAV.find(n => n.id === safeTab)?.ar || TAB_AR[safeTab] || '')}</h1>
            <span style={{ fontSize: 11, color: '#1a1410', background: 'var(--mint)', fontFamily: 'monospace', flexShrink: 0, padding: '3px 8px', borderRadius: 6, fontWeight: 700, alignSelf: 'center' }}>v27.13 🚀</span>
            <div className="topstatus">
              <div className="row avrow" style={{ gap: 0 }}>
                {online.slice(0, 4).map((p, i) => (
                  <div key={i} className="av avtip" style={{ background: clr(i) }}
                    data-tip={p.name + ((ROLES[p.role] || {}).ar ? ' · ' + ROLES[p.role].ar.split('—')[0].trim() : '')}>
                    {p.name.charAt(0)}
                  </div>
                ))}
              </div>
              <span className={'badge livebadge ' + (live ? 'b-mint' : 'b-dim')}
                title={live ? 'مزامنة لحظية عبر Firestore' : 'مزامنة دورية كل 8 ثوانٍ'}>
                <span className="dot" />{online.length}{live ? ' · لحظي' : ''}
              </span>
              <button className="btn sm gh synctime" onClick={() => refresh(false)} title="مزامنة الآن">
                <RefreshCw size={14} className={syncing ? 'spin' : ''} />
                <span className="num tt" style={{ fontSize: 10, color: 'var(--faint)' }}>
                  {lastSync ? lastSync.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' }) : '--:--'}
                </span>
              </button>
              <button className="btn sm gh" title={mode === 'dark' ? 'التبديل إلى الوضع النهاري' : 'التبديل إلى الوضع الليلي'} onClick={() => setMode(m => { const n = m === 'dark' ? 'light' : 'dark'; try { localStorage.setItem('rms8:mode', n); } catch { } return n; })} style={{ fontSize: 15 }}>{mode === 'dark' ? '🌞' : '🌙'}</button>
              <div style={{ position: 'relative', flexShrink: 0 }}>
                <button className="btn sm gh themebtn" title="ثيم المنصّة" onClick={() => setThemePick(v => !v)} style={{ fontSize: 15 }}>🎨</button>
                {themePick && (<>
                  <div className="usermenu-back" onClick={() => setThemePick(false)} />
                  <div className="usermenu-menu" style={{ minWidth: 252, padding: 8, zIndex: 70 }}>
                    <div className="umhd" style={{ padding: '4px 6px 8px' }}><b>ثيم المنصّة</b><small>أسلوب التصميم والوضع — فوريّ ومحفوظ</small></div>
                    <div style={{ display: 'flex', gap: 6, marginBottom: 8 }}>
                      {[['light', '🌞 نهار'], ['dark', '🌙 ليل']].map(([mv, lbl]) => (
                        <button key={mv} onClick={() => { setMode(mv); try { localStorage.setItem('rms8:mode', mv); } catch { } }}
                          style={{ flex: 1, padding: '7px 6px', borderRadius: 8, cursor: 'pointer', fontFamily: 'inherit', fontSize: 11.5, fontWeight: 600, color: 'var(--txt)', border: '1px solid ' + (mode === mv ? 'var(--brass)' : 'var(--line)'), background: mode === mv ? 'var(--acc-soft)' : 'transparent' }}>{lbl}</button>
                      ))}
                    </div>
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 6 }}>
                      {THEME_ORDER.map(id => { const m = THEME_META[id]; const on = normTheme(theme) === id; return (
                        <button key={id} onClick={() => { setTheme(id); try { localStorage.setItem('rms8:theme', id); } catch { } }}
                          style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '7px 9px', borderRadius: 9, cursor: 'pointer', fontFamily: 'inherit', textAlign: 'start', border: '1px solid ' + (on ? 'var(--brass)' : 'var(--line)'), background: on ? 'var(--acc-soft)' : 'transparent', color: 'var(--txt)' }}>
                          <span style={{ width: 20, height: 20, borderRadius: '50%', flexShrink: 0, background: m.color, boxShadow: 'inset 0 0 0 2px rgba(255,255,255,.35)' }} />
                          <span style={{ minWidth: 0, display: 'flex', flexDirection: 'column', lineHeight: 1.15 }}><span style={{ fontSize: 11, fontWeight: 700, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{m.name}{on ? ' ✓' : ''}</span><span style={{ fontSize: 9, color: 'var(--faint)', whiteSpace: 'nowrap' }}>{m.desc}</span></span>
                        </button>
                      ); })}
                    </div>
                  </div>
                </>)}
              </div>
              <button className="btn sm gh" onClick={() => setBell(true)} style={{ position: 'relative' }}>
                <Bell size={15} />
                {unread > 0 && <span style={{
                  position: 'absolute', top: -3, insetInlineEnd: -3, background: 'var(--rose)',
                  width: 15, height: 15, borderRadius: '50%', fontSize: 9, display: 'grid',
                  placeItems: 'center', color: '#fff', fontWeight: 700
                }}>{unread}</span>}
              </button>
              {/* قائمة الحساب — v9.6 (بديل ذيل القائمة الجانبية المخفية) · v15.8: على الجوال تفتح لوحة «الأقسام» السفلية بدل القائمة المنسدلة التي يقصّها رأس الجوال */}
              <div className="usermenu">
                <button className="usermenu-btn" onClick={() => { if (typeof window !== 'undefined' && window.innerWidth <= 900) { setUserMenu(false); setMoreSheet(true); } else { setUserMenu(v => !v); } }} title="حسابي">
                  <span className="uav">{(me.name || 'م').trim().charAt(0)}</span>
                  <span className="un">{(me.name || '').split(' ')[0]}<small>{((ROLES[me.role] || {}).ar || me.role).split('—')[0].trim()}</small></span>
                  <ChevronDown size={13} />
                </button>
                {userMenu && (<>
                  <div className="usermenu-back" onClick={() => setUserMenu(false)} />
                  <div className="usermenu-menu">
                    <div className="umhd"><b>{me.name}</b><small>{me.email || ''}</small></div>
                    <button onClick={() => { setUserMenu(false); setTab('home'); }}><Home size={14} />الرئيسية — كل التطبيقات</button>
                    {!installed && <button onClick={() => { setUserMenu(false); doInstall(); }}><Download size={14} />تثبيت التطبيق على الجهاز</button>}
                    <button onClick={() => { setUserMenu(false); forceUpdate(); }}><RefreshCw size={14} />تحديث للأحدث (مسح الكاش){updateReady ? ' — نسخة جديدة!' : ''}</button>
                    <button onClick={() => { setUserMenu(false); setTour(true); }}><Compass size={14} />جولة تعريفية في المنصة</button>
                    {(me.pinHash || me.bioCredId) && (
                      <button onClick={() => { setUserMenu(false); setLocked(true); }}><Lock size={14} />قفل الشاشة — عودة بالدخول السريع</button>
                    )}
                    <button onClick={() => { setUserMenu(false); resetAll(); }}><Trash2 size={14} />تفريغ بيانات المنصة</button>
                    <button className="danger" onClick={() => { setUserMenu(false); sessLogout(); }}><LogOut size={14} />تسجيل الخروج</button>
                  </div>
                </>)}
              </div>
            </div>
          </header>

          {updateReady && (
            <div style={{
              background: 'rgba(79,178,134,.16)', borderBottom: '1px solid rgba(79,178,134,.45)',
              color: 'var(--mint)', padding: '9px 20px', fontSize: 12.5, display: 'flex', gap: 10, alignItems: 'center', justifyContent: 'center', flexWrap: 'wrap'
            }}>
              <RefreshCw size={15} />
              نسخة أحدث من المنصة متوفّرة الآن.
              <button className="btn sm pri" onClick={forceUpdate}><RefreshCw size={13} />تحديث الآن</button>
            </div>
          )}

          {accessErr && (() => {
            // v27.1 — تشخيص صلاحيات الخادم على جهاز الفرع (يظهر بدل الفشل الصامت)
            const nm = (id) => ((org.branches || []).find(x => x.id === id) || {}).name || id;
            const mem = accessErr.mem || null;
            const memBr = mem ? [mem.branchId, ...(mem.branchIds || [])].filter(Boolean) : [];
            const diag = accessErr.kind === 'dir'
              ? 'الخادم رفض قراءة الدليل العام لهذا الحساب — عضويته على الخادم غير نشطة أو غير موجودة.'
              : 'الخادم رفض قراءة/كتابة بيانات فرع ' + (accessErr.ids || []).map(nm).join('، ') + ' لهذا الحساب'
                + (mem && mem.exists ? ' — عضويته على الخادم' + (memBr.length ? ' مرتبطة بفرع ' + memBr.map(nm).join('، ') : ' بلا فرع') + (mem.scope ? ' (نطاق ' + mem.scope + ')' : '') + ' بينما حسابه في المنصة مرتبط بفرع ' + (accessErr.expected || []).map(nm).join('، ') + '.' : (mem && !mem.exists ? ' — لا توجد عضوية له على الخادم.' : '.'));
            return (
              <div style={{ background: 'rgba(217,84,77,.14)', borderBottom: '1px solid rgba(217,84,77,.45)', color: 'var(--rose)', padding: '9px 20px', fontSize: 12.5, display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'wrap' }}>
                <ShieldAlert size={16} />
                <div style={{ flex: 1, minWidth: 240 }}>
                  <b>لن تُحفظ أي بيانات من هذا الجهاز سحابيًا.</b> {diag}
                  <div style={{ fontSize: 11.5, marginTop: 3, color: 'var(--dim)' }}>الحل: يفتح مسؤول النظام «الفروع والمستخدمون ← المستخدمون» ويضغط «مزامنة صلاحيات الأعضاء» (أو يعيد حفظ هذا المستخدم)، ثم يُعاد الدخول هنا.</div>
                </div>
                <button className="btn sm" onClick={() => location.reload()}><RefreshCw size={13} />أعد المحاولة</button>
              </div>
            );
          })()}

          {offline && (
            <div style={{
              background: 'rgba(224,164,88,.14)', borderBottom: '1px solid rgba(224,164,88,.4)',
              color: 'var(--amber)', padding: '9px 20px', fontSize: 12, display: 'flex', gap: 9, alignItems: 'center'
            }}>
              <AlertTriangle size={15} />
              انقطع الاتصال — تابع الإدخال، لكن الحفظ السحابي لن يكتمل حتى عودة الشبكة. تجنّب اعتماد الإغلاق الآن.
            </div>
          )}

          {(newActivity.length > 0 || (unread > 0 && tab !== 'audit')) && (
            <div className="actbar">
              <div className="row" style={{ gap: 9, alignItems: 'center', flex: 1, minWidth: 0 }}>
                <span className="actbar-dot" />
                <Bell size={14} style={{ flexShrink: 0 }} />
                <span style={{ fontSize: 12, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                  {newActivity.length > 0
                    ? <>نشاط جديد: <b>{latestActivity?.userName}</b> — {latestActivity?.title}
                        {newActivity.length > 1 && <span className="num"> (+{newActivity.length - 1})</span>}</>
                    : <>لديك <span className="num">{unread}</span> تنبيه بانتظار الاطلاع</>}
                </span>
              </div>
              <div className="row" style={{ gap: 6, flexShrink: 0 }}>
                <button className="btn sm gh" onClick={() => { setTab('audit'); setLastSeenAudit(Date.now()); }}>
                  <Eye size={12} />سجل النشاط
                </button>
                <button className="btn sm gh" onClick={() => setLastSeenAudit(Date.now())} title="إخفاء">
                  <X size={12} />
                </button>
              </div>
            </div>
          )}

          <div className="page">
            <div className="page-inner">
              {safeTab === 'home' && <Launcher {...shared} online={online} />}
              {['analytics', 'exec', 'dash', 'compare', 'growth', 'breakeven', 'scorecard', 'scenario', 'ai'].includes(safeTab) && <Hub hubId="analytics" {...shared} online={online} view={safeTab} />}
              {safeTab === 'alerts' && <AlertsCenter {...shared} />}
              {['reporting', 'reports', 'rbuild', 'boardpack', 'cashflow'].includes(safeTab) && <Hub hubId="reporting" {...shared} view={safeTab} />}
              {safeTab === 'sales' && <Sales {...shared} />}
              {safeTab === 'closing' && <Closing {...shared} />}
              {['hrops', 'attendance', 'shiftengine', 'tasks', 'points', 'esign'].includes(safeTab) && <Hub hubId="hrops" {...shared} view={safeTab} />}
              {['hrperf', 'kpi', 'rolekpi', 'rewards', 'corrective', 'training', 'perfsnap', 'hrdash'].includes(safeTab) && <Hub hubId="hrperf" {...shared} view={safeTab} />}
              {safeTab === 'apps' && <AppsCenter {...shared} />}
              {safeTab === 'approve' && <Approvals {...shared} />}
              {safeTab === 'treasury' && <Treasury {...shared} />}
              {['people', 'hrmaster', 'hrpolicy', 'payroll', 'workforce'].includes(safeTab) && <Hub hubId="people" {...shared} view={safeTab} />}
              {safeTab === 'shifts' && <Shifts {...shared} />}
              {['purchasing', 'suppliers', 'reorder'].includes(safeTab) && <Hub hubId="purchasing" {...shared} view={safeTab} />}
              {safeTab === 'inv' && <Inventory {...shared} />}
              {safeTab === 'partners' && <Partners {...shared} />}
              {safeTab === 'acct' && <Accounting {...shared} />}
              {safeTab === 'docs' && <DocsCenter {...shared} />}
              {safeTab === 'archive' && <Archive {...shared} />}
              {safeTab === 'entities' && <EntitiesCenter {...shared} />}
              {safeTab === 'admin' && <Admin {...shared} />}
              {safeTab === 'audit' && <AuditView {...shared} onSeen={() => setLastSeenAudit(Date.now())} />}
            </div>
          </div>

          <div className="tick">
            <span>الشركة: {org.company.name || '—'}</span>
            {org.company.taxNumber && <span>الرقم الضريبي: <span className="num">{org.company.taxNumber}</span></span>}
            <span>{myBranches.length === 1 ? 'فرعك' : 'فروعك'}: <span className="num">{myBranches.filter(b => b.isActive).length}</span></span>
            <span>إغلاقاتك المسجلة: <span className="num">{scoped.closings.length}</span></span>
            <span style={{ color: live ? 'var(--mint)' : 'var(--dim)' }}>{live ? 'مزامنة لحظية' : 'مزامنة دورية'}</span>
          </div>
        </div>
      {/* شريط تنقّل سفلي — يظهر على الجوال فقط */}
      <nav className="botnav">
        {(NAV.length <= 5 ? NAV : NAV.slice(0, 4)).map(n => (
          <button key={n.id} className={'botnav-i' + (tab === n.id ? ' on' : '')} onClick={() => { setTab(n.id); setMoreSheet(false); }}>
            <n.icon size={20} />
            <span>{n.ar.split(' ')[0]}</span>
            {n.cnt > 0 && <span className="bdg">{n.cnt}</span>}
          </button>
        ))}
        {NAV.length > 5 && (
          <button className={'botnav-i botnav-more' + (moreSheet ? ' on' : '')} onClick={() => setMoreSheet(v => !v)}>
            <Grid3x3 size={20} />
            <span>الأقسام</span>
            {(pending + unread) > 0 && !moreSheet && <span className="bdg">{pending + unread}</span>}
          </button>
        )}
      </nav>
      </div>



      {moreSheet && (
        <div className="sheet-mask" onClick={() => setMoreSheet(false)}>
          <div className="sheet" onClick={e => e.stopPropagation()}>
            <div className="sheet-handle" />
            <div className="sheet-head">
              <span>كل الأقسام</span>
              <button className="btn sm gh" onClick={() => setMoreSheet(false)}><X size={16} /></button>
            </div>
            <div style={{ marginBottom: 12, paddingBottom: 12, borderBottom: '1px solid var(--line)' }}>
              <div className="row" style={{ gap: 10, alignItems: 'center', padding: '2px 4px 10px' }}>
                <span style={{ width: 40, height: 40, borderRadius: '50%', background: 'var(--acc-soft)', color: 'var(--brass)', display: 'grid', placeItems: 'center', fontWeight: 800, flexShrink: 0 }}>{(me.name || 'م').trim().charAt(0)}</span>
                <div style={{ minWidth: 0, flex: 1 }}>
                  <div style={{ fontSize: 13.5, fontWeight: 700, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{me.name}</div>
                  <div style={{ fontSize: 10.5, color: 'var(--faint)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{me.email || ((ROLES[me.role] || {}).ar || me.role)}</div>
                </div>
              </div>
              <div className="grid g2" style={{ gap: 8 }}>
                <button className="btn gh" onClick={() => { setMoreSheet(false); forceUpdate(); }}><RefreshCw size={15} />تحديث للأحدث</button>
                <button className="btn" style={{ background: 'rgba(217,84,77,.14)', color: 'var(--rose)', borderColor: 'rgba(217,84,77,.42)' }} onClick={() => { setMoreSheet(false); setMe(null); }}><LogOut size={15} />تسجيل الخروج</button>
              </div>
            </div>
            <div className="iconsgrid">
              {NAV.map(n => (
                <button key={n.id} className={'icontile' + (tab === n.id ? ' on' : '')}
                  onClick={() => { setTab(n.id); setMoreSheet(false); }}>
                  <div className="icontile-i"><n.icon size={22} />
                    {n.cnt > 0 && <span className="icontile-b">{n.cnt}</span>}
                  </div>
                  <span>{n.ar}</span>
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      {bell && <Notifications ops={ops} org={org} me={me} myBranches={myBranches} commit={commit} onClose={() => setBell(false)} />}
      {tour && <TourModal me={me} onClose={() => setTour(false)} go={(t) => { setTab(t); setTour(false); }} />}

      {sessWarnLeft != null && (
        <Modal title="ستنتهي الجلسة قريباً" icon={Clock}
          onClose={() => { lastActRef.current = Date.now(); setSessWarnLeft(null); }}>
          <div style={{ textAlign: 'center', padding: '6px 0' }}>
            <div className="num" style={{ fontSize: 44, fontWeight: 800, color: sessWarnLeft <= 10 ? 'var(--rose)' : 'var(--brass)' }}>{sessWarnLeft}</div>
            <div style={{ fontSize: 12.5, color: 'var(--dim)', marginTop: 6, lineHeight: 1.8 }}>
              لا يوجد نشاط منذ فترة — حمايةً لحسابك سيُسجَّل خروجك تلقائياً خلال الثواني أعلاه.
            </div>
            <button className="btn pri" style={{ marginTop: 14 }}
              onClick={() => { lastActRef.current = Date.now(); setSessWarnLeft(null); }}>
              <Check size={14} />متابعة الجلسة
            </button>
          </div>
        </Modal>
      )}
      {toast && (
        <div style={{
          position: 'fixed', bottom: 20, insetInlineStart: 20, zIndex: 99,
          background: toast.kind === 'no' ? 'rgba(217,84,77,.15)' : 'rgba(79,178,134,.14)',
          border: '1px solid ' + (toast.kind === 'no' ? 'rgba(217,84,77,.45)' : 'rgba(79,178,134,.45)'),
          color: toast.kind === 'no' ? '#D9544D' : '#4FB286',
          padding: '11px 16px', borderRadius: 11, fontSize: 12.5, maxWidth: 340,
          backdropFilter: 'blur(8px)'
        }}>{toast.msg}</div>
      )}
    </div>
  );
}

/* ================= بوابة الدخول ================= */
function BrandHead({ title, sub, logo }) {
  return (
    <div className="bhead" style={{ textAlign: 'center', marginBottom: 24 }}>
      {logo
        ? <img src={logo} alt="شعار" className="bhead-logo" style={{ width: 64, height: 64, margin: '0 auto 14px', borderRadius: 16, objectFit: 'cover', border: '1px solid var(--line)', display: 'block' }} />
        : <div className="brand-mark bhead-logo" style={{ width: 54, height: 54, margin: '0 auto 14px', fontSize: 19, borderRadius: 16 }}>
          {(title || 'المنصة').trim().charAt(0) || 'م'}
        </div>}
      <h1 style={{ fontSize: 20 }}>{title || 'منصة إغلاق وإدارة الفروع'}</h1>
      <div style={{ color: 'var(--dim)', fontSize: 12.5, marginTop: 5 }}>{sub}</div>
    </div>
  );
}

/* ================= التسجيل الأول (إنشاء حساب المالك) ================= */
function FirstRun({ css, theme, commitOrg, say, onDone }) {
  const [f, setF] = useState({ company: '', taxNumber: '', name: '', email: '', pass: '', pass2: '' });
  const [busy, setBusy] = useState(false);
  const set = (k, v) => setF(p => ({ ...p, [k]: v }));

  const create = async () => {
    if (!f.company.trim()) return say('اكتب اسم المنشأة', 'no');
    if (!f.name.trim()) return say('اكتب اسمك', 'no');
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(f.email)) return say('أدخل بريداً إلكترونياً صحيحاً', 'no');
    if (f.pass.length < 6) return say('كلمة السر يجب ألا تقل عن 6 أحرف', 'no');
    if (f.pass !== f.pass2) return say('كلمتا السر غير متطابقتين', 'no');
    setBusy(true);
    const passHash = await sha(f.pass);
    const owner = {
      id: uid('u'), name: f.name.trim(), email: f.email.trim().toLowerCase(),
      role: 'system_admin', passHash, isActive: true, createdAt: today()
    };
    await commitOrg(d => ({
      ...d,
      company: { ...d.company, name: f.company.trim(), taxNumber: f.taxNumber.trim() },
      users: [owner],
      setupComplete: true
    }), { actionType: 'create', targetType: 'user_account', targetId: owner.id, title: 'أنشأ حساب المالك وهيّأ المنصة', details: f.company.trim() });
    setBusy(false);
    say('تم إنشاء المنصة — أضف الآن فروعك ومستخدميك');
    onDone(owner);
  };

  return (
    <div className={themeCls(theme, readMode())}>
      <style dangerouslySetInnerHTML={{ __html: css }} />
      <div className="gate">
        <div className="gate-c">
          <BrandHead title="تهيئة المنصة لأول مرة" sub="أنشئ حساب المالك — سيكون لك وصول كامل لكل الشاشات" />
          <div className="card">
            <div className="lbl" style={{ marginBottom: 8 }}>بيانات المنشأة</div>
            <Field label="اسم المنشأة">
              <input className="inp" value={f.company} placeholder="مثال: مجموعة … للمطاعم" onChange={e => set('company', e.target.value)} />
            </Field>
            <Field label="الرقم الضريبي (اختياري الآن)">
              <input className="inp n" value={f.taxNumber} placeholder="3xxxxxxxxxxxxx3" onChange={e => set('taxNumber', e.target.value)} />
            </Field>
            <hr className="hr" />
            <div className="lbl" style={{ marginBottom: 8 }}>حساب المالك (المدير العام)</div>
            <Field label="الاسم الكامل">
              <input className="inp" value={f.name} onChange={e => set('name', e.target.value)} />
            </Field>
            <Field label="البريد الإلكتروني">
              <input className="inp" type="email" style={{ direction: 'ltr', textAlign: 'right' }} value={f.email}
                placeholder="owner@company.com" onChange={e => set('email', e.target.value)} />
            </Field>
            <div className="grid g2">
              <Field label="كلمة السر">
                <input className="inp" type="password" value={f.pass} onChange={e => set('pass', e.target.value)} />
              </Field>
              <Field label="تأكيد كلمة السر">
                <input className="inp" type="password" value={f.pass2} onChange={e => set('pass2', e.target.value)} />
              </Field>
            </div>
            <button className="btn pri" style={{ width: '100%', marginTop: 6 }} disabled={busy} onClick={create}>
              {busy ? <RefreshCw size={15} className="spin" /> : <Check size={15} />}
              إنشاء المنصة والدخول
            </button>
            <div style={{ fontSize: 11, color: 'var(--faint)', marginTop: 12, lineHeight: 1.8, textAlign: 'center' }}>
              كلمة السر تُخزَّن مجزّأة (SHA-256) ولا تُحفظ كنص. احتفظ بها — لا يمكن استرجاعها.
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ================= بوابة الدخول (بريد وكلمة سر) ================= */
/* ================= بوابة الدخول — المصادقة السحابية الحقيقية ================= */
function FbGate({ css, theme, fbLogin, fbFirstSetup, notice }) {
  const [email, setEmail] = useState(() => { try { return localStorage.getItem('rms8:lastEmail') || ''; } catch { return ''; } });
  const [pass, setPass] = useState('');
  const [err, setErr] = useState('');
  const [busy, setBusy] = useState(false);
  const [show, setShow] = useState(false);
  const [setup, setSetup] = useState(false);

  const go = async () => {
    if (!email || !pass || busy) return;
    setErr(''); setBusy(true);
    const r = setup ? await fbFirstSetup(email, pass) : await fbLogin(email, pass);
    setBusy(false);
    if (!r.ok) setErr(r.err || 'تعذّر الدخول');
  };

  return (
    <div className={themeCls(theme, readMode())}>
      <style dangerouslySetInnerHTML={{ __html: css }} />
      <div className="gate">
        <div className="gate-c">
          <BrandHead title="منصة الإغلاق اليومي" sub="دخول موثّق — البيانات محمية بحساب مصادقة لكل مستخدم" />
          <div className="row" style={{ justifyContent: 'center', marginBottom: 16 }}>
            <span className="badge b-mint"><Lock size={10} />مصادقة سحابية مفعّلة</span>
          </div>
          <div className="card">
            {notice && <div style={{ border: '1px solid rgba(200,162,74,.45)', background: 'rgba(200,162,74,.10)', color: 'var(--brass-l)', borderRadius: 10, padding: '10px 12px', marginBottom: 12, fontSize: 12, lineHeight: 1.8, textAlign: 'center' }}>{notice}</div>}
            {setup && <div style={{ border: '1px solid rgba(200,162,74,.4)', background: 'rgba(200,162,74,.08)', color: 'var(--brass-l)', borderRadius: 10, padding: '9px 12px', marginBottom: 12, fontSize: 11.5, lineHeight: 1.7 }}>
              الإعداد الأول (مرة واحدة بعد الترقية): أدخل بريد المالك وكلمة سر جديدة — يُنشأ حساب المصادقة وتصبح مديرًا للمنصة.
            </div>}
            <Field label="البريد الإلكتروني">
              <input className="inp" type="email" autoFocus style={{ direction: 'ltr', textAlign: 'right' }}
                value={email} placeholder="you@company.com"
                onChange={e => { setEmail(e.target.value); setErr(''); }}
                onKeyDown={e => e.key === 'Enter' && go()} />
            </Field>
            <Field label={setup ? 'كلمة سر جديدة (6 أحرف فأكثر)' : 'كلمة السر'}>
              <div style={{ position: 'relative' }}>
                <input className="inp" type={show ? 'text' : 'password'} value={pass}
                  onChange={e => { setPass(e.target.value); setErr(''); }}
                  onKeyDown={e => e.key === 'Enter' && go()} />
                <button className="btn sm gh" style={{ position: 'absolute', insetInlineEnd: 4, top: 4, padding: '4px 8px' }}
                  onClick={() => setShow(s => !s)} tabIndex={-1}><Eye size={14} /></button>
              </div>
            </Field>
            {err && <div className="gate-err">{err}</div>}
            <button className="btn pri" style={{ width: '100%' }} disabled={busy || !email || !pass} onClick={go}>
              {busy ? <RefreshCw size={15} className="spin" /> : <Lock size={15} />}
              {setup ? 'إنشاء حساب المصادقة والدخول' : 'دخول'}
            </button>
            <button className="btn gh" style={{ width: '100%', marginTop: 10 }} onClick={() => { setSetup(s => !s); setErr(''); }}>
              {setup ? 'لديّ حساب — عودة للدخول' : 'الإعداد الأول بعد الترقية (للمالك)'}
            </button>
            <div style={{ fontSize: 11, color: 'var(--faint)', marginTop: 14, lineHeight: 1.7, textAlign: 'center' }}>
              نسيت كلمة السر؟ اطلب من المدير «إرسال رابط تعيين كلمة السر» من إدارة المستخدمين.
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

/* v15.25 — شاشة القفل: عودة سريعة للجلسة برقم سري أو بصمة دون إعادة كتابة البريد وكلمة السر */
function LockScreen({ me, theme, mode, onUnlock, onLogout }) {
  const [pin, setPin] = useState('');
  const [err, setErr] = useState('');
  const [busy, setBusy] = useState(false);
  const tryPin = async () => {
    setErr('');
    const h = await sha('pin:' + pin);
    if (h === me.pinHash) onUnlock();
    else { setErr('الرقم السري غير صحيح'); setPin(''); }
  };
  const key = (d) => { setErr(''); if (d === 'del') setPin(p => p.slice(0, -1)); else setPin(p => (p.length < 6 ? p + d : p)); };
  const tryBio = async () => {
    setBusy(true); setErr('');
    try { await bioVerify(me.bioCredId); onUnlock(); }
    catch { setErr('تعذّر التحقق بالبصمة — جرّب الرقم السري'); }
    setBusy(false);
  };
  // v16.3 — بطلب المالك: لوحة القفل تستجيب للوحة المفاتيح مباشرة (مع بقاء الفأرة):
  // أرقام 0-9 (ومكافئاتها العربية ٠-٩ ولوحة الأرقام الجانبية) + Backspace للمسح + Enter للفتح.
  useEffect(() => {
    const AR = '٠١٢٣٤٥٦٧٨٩';
    const onKey = (e) => {
      if (e.ctrlKey || e.metaKey || e.altKey) return;
      const tag = ((e.target && e.target.tagName) || '').toUpperCase();
      if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
      let d = e.key;
      if (AR.includes(d)) d = String(AR.indexOf(d));
      if (/^[0-9]$/.test(d)) { e.preventDefault(); key(d); }
      else if (e.key === 'Backspace') { e.preventDefault(); key('del'); }
      else if (e.key === 'Enter') { e.preventDefault(); if (pin.length >= 4) tryPin(); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [pin]);
  return (
    <div className={themeCls(theme, mode || readMode())}>
      <style dangerouslySetInnerHTML={{ __html: CSS }} />
      <div className="gate">
        <div className="gate-c">
          <div className="bhead" style={{ textAlign: 'center', marginBottom: 20 }}>
            <div className="brand-mark bhead-logo" style={{ width: 54, height: 54, margin: '0 auto 12px', fontSize: 19, borderRadius: 16 }}>
              {(me.name || 'م').trim().charAt(0) || 'م'}
            </div>
            <h1 style={{ fontSize: 19 }}>الشاشة مقفلة 🔒</h1>
            <div style={{ color: 'var(--dim)', fontSize: 12.5, marginTop: 5 }}>
              {me.name} — ادخل سريعاً برقمك السري{me.bioCredId ? ' أو بصمتك' : ''}
            </div>
          </div>
          <div className="card">
            {me.pinHash ? (<>
              <div className="pin-dots">
                {[0, 1, 2, 3, 4, 5].map(i => <span key={i} className={'pin-dot' + (i < pin.length ? ' on' : '')} />)}
              </div>
              {err && <div className="gate-err">{err}</div>}
              <div className="pinpad">
                {['1', '2', '3', '4', '5', '6', '7', '8', '9'].map(d =>
                  <button key={d} type="button" className="pinkey" onClick={() => key(d)}>{d}</button>)}
                <button type="button" className="pinkey ghost" onClick={() => setPin('')}>مسح</button>
                <button type="button" className="pinkey" onClick={() => key('0')}>0</button>
                <button type="button" className="pinkey ghost" onClick={() => key('del')} aria-label="حذف"><Delete size={17} /></button>
              </div>
              <button className="btn pri" style={{ width: '100%' }} disabled={pin.length < 4} onClick={tryPin}>
                <Grid3x3 size={15} />فتح
              </button>
            </>) : (
              <>
                {err && <div className="gate-err">{err}</div>}
                <div className="empty" style={{ padding: '10px 0' }}>
                  لا رقم سري لحسابك — استخدم البصمة أو الخروج الكامل. (يُضبط الرقم السري من إدارة المستخدمين.)
                </div>
              </>
            )}
            {me.bioCredId && webauthnSupported() && (
              <button className="btn" style={{ width: '100%', marginTop: 10 }} disabled={busy} onClick={tryBio}>
                {busy ? <RefreshCw size={15} className="spin" /> : <Fingerprint size={16} />}فتح بالبصمة الحيوية
              </button>
            )}
            <button className="btn gh" style={{ width: '100%', marginTop: 10 }} onClick={onLogout}>
              <LogOut size={14} />تسجيل خروج كامل — دخول بحساب آخر
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

function Gate({ css, org, onLogin, online, theme, notice }) {
  const [email, setEmail] = useState('');
  const [pass, setPass] = useState('');
  const [err, setErr] = useState('');
  const [busy, setBusy] = useState(false);
  const [show, setShow] = useState(false);
  const [bioBusy, setBioBusy] = useState(false);
  const [mode, setMode] = useState('pass');   // pass | pin
  const [pin, setPin] = useState('');
  const bioUsers = (org.users || []).filter(u => u.isActive && u.bioCredId);
  const hasPinUsers = (org.users || []).some(u => u.isActive && u.pinHash);

  // تذكّر آخر بريد على هذا الجهاز لتسريع الدخول
  useEffect(() => { try { const e = localStorage.getItem('rms8:lastEmail'); if (e) setEmail(e); } catch { } }, []);
  const finish = (u) => { try { localStorage.setItem('rms8:lastEmail', u.email || ''); } catch { } onLogin(u); };

  const bioLogin = async () => {
    setErr(''); setBioBusy(true);
    try {
      // نطابق البصمة مع الحساب المرتبط بها. عند تعدد الحسابات ذات البصمة على الجهاز
      // يكفي التحقق من أحدها؛ WebAuthn سيعرض المتاح على هذا الجهاز.
      const target = bioUsers.find(u => (u.email || '').toLowerCase() === email.trim().toLowerCase()) || bioUsers[0];
      await bioVerify(target.bioCredId);
      finish(target);
    } catch (e) {
      setErr('تعذّر التحقق بالبصمة. استخدم البريد وكلمة السر، أو جرّب مجدداً.');
    }
    setBioBusy(false);
  };

  const submit = async () => {
    setErr(''); setBusy(true);
    const u = (org.users || []).find(x => (x.email || '').toLowerCase() === email.trim().toLowerCase() && x.isActive);
    if (!u) { setBusy(false); return setErr('لا يوجد حساب نشط بهذا البريد'); }
    const h = await sha(pass);
    // دعم الحسابات القديمة التي تملك pin بدل passHash
    const ok = u.passHash ? u.passHash === h : (u.pin && u.pin === pass);
    setBusy(false);
    if (ok) finish(u);
    else setErr('كلمة السر غير صحيحة');
  };

  const pinSubmit = async () => {
    setErr(''); setBusy(true);
    const u = (org.users || []).find(x => (x.email || '').toLowerCase() === email.trim().toLowerCase() && x.isActive);
    if (!u) { setBusy(false); return setErr('لا يوجد حساب نشط بهذا البريد'); }
    if (!u.pinHash) { setBusy(false); return setErr('لا يوجد رقم سري لهذا الحساب — ادخل بكلمة السر، ثم اضبط رقماً سرياً من إدارة المستخدمين'); }
    const h = await sha('pin:' + pin);
    setBusy(false);
    if (h === u.pinHash) finish(u);
    else { setErr('الرقم السري غير صحيح'); setPin(''); }
  };
  const pinKey = (d) => { setErr(''); if (d === 'del') setPin(p => p.slice(0, -1)); else setPin(p => (p.length < 6 ? p + d : p)); };

  // v16.3 — بوابة «الدخول السريع برقم سري» تستجيب للوحة المفاتيح مباشرة (والفأرة متاحة كما هي):
  // أرقام 0-9/٠-٩/لوحة الأرقام + Backspace للمسح + Enter للدخول. الكتابة داخل حقل البريد لا تُلتقط.
  useEffect(() => {
    if (mode !== 'pin') return;
    const AR = '٠١٢٣٤٥٦٧٨٩';
    const onKey = (e) => {
      if (e.ctrlKey || e.metaKey || e.altKey) return;
      const tag = ((e.target && e.target.tagName) || '').toUpperCase();
      if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
      let d = e.key;
      if (AR.includes(d)) d = String(AR.indexOf(d));
      if (/^[0-9]$/.test(d)) { e.preventDefault(); pinKey(d); }
      else if (e.key === 'Backspace') { e.preventDefault(); pinKey('del'); }
      else if (e.key === 'Enter') { e.preventDefault(); if (pin.length >= 4) pinSubmit(); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [mode, pin, email]);

  return (
    <div className={themeCls(theme, readMode())}>
      <style dangerouslySetInnerHTML={{ __html: css }} />
      <div className="gate">
        <div className="gate-c">
          <BrandHead title={org.company?.name || 'منصة إغلاق الفروع'} sub="منصة سحابية متكاملة لإغلاق وإدارة فروع المطاعم" logo={org.company?.logoUrl} />
          <div className="row" style={{ justifyContent: 'center', marginBottom: 16 }}>
            <span className="badge b-mint"><span className="dot" />{online.length} متصل الآن</span>
            <span className="badge b-dim"><Lock size={10} />بيانات مشتركة ومؤمّنة</span>
          </div>
          <div className="card">
            {notice && <div style={{ border: '1px solid rgba(200,162,74,.45)', background: 'rgba(200,162,74,.10)', color: 'var(--brass-l)', borderRadius: 10, padding: '10px 12px', marginBottom: 12, fontSize: 12, lineHeight: 1.8, textAlign: 'center' }}>{notice}</div>}
            {(hasPinUsers || mode === 'pin') && (
              <div className="loginseg">
                <button type="button" className={'loginseg-b' + (mode === 'pass' ? ' on' : '')} onClick={() => { setMode('pass'); setErr(''); }}><Lock size={13} />كلمة السر</button>
                <button type="button" className={'loginseg-b' + (mode === 'pin' ? ' on' : '')} onClick={() => { setMode('pin'); setErr(''); }}><Grid3x3 size={13} />دخول سريع برقم سري</button>
              </div>
            )}
            <Field label="البريد الإلكتروني">
              <input className="inp" type="email" autoFocus style={{ direction: 'ltr', textAlign: 'right' }}
                value={email} placeholder="you@company.com"
                onChange={e => { setEmail(e.target.value); setErr(''); }}
                onKeyDown={e => e.key === 'Enter' && (mode === 'pin' ? pinSubmit() : submit())} />
            </Field>

            {mode === 'pass' ? (
              <>
                <Field label="كلمة السر">
                  <div style={{ position: 'relative' }}>
                    <input className="inp" type={show ? 'text' : 'password'} value={pass}
                      onChange={e => { setPass(e.target.value); setErr(''); }}
                      onKeyDown={e => e.key === 'Enter' && submit()} />
                    <button className="btn sm gh" style={{ position: 'absolute', insetInlineEnd: 4, top: 4, padding: '4px 8px' }}
                      onClick={() => setShow(s => !s)} tabIndex={-1}><Eye size={14} /></button>
                  </div>
                </Field>
                {err && <div className="gate-err">{err}</div>}
                <button className="btn pri" style={{ width: '100%' }} disabled={busy || !email || !pass} onClick={submit}>
                  {busy ? <RefreshCw size={15} className="spin" /> : <Lock size={15} />}دخول
                </button>
              </>
            ) : (
              <>
                <div className="lbl" style={{ textAlign: 'center', marginBottom: 8 }}>أدخل الرقم السري</div>
                <div className="pin-dots">
                  {[0, 1, 2, 3, 4, 5].map(i => <span key={i} className={'pin-dot' + (i < pin.length ? ' on' : '')} />)}
                </div>
                {err && <div className="gate-err">{err}</div>}
                <div className="pinpad">
                  {['1', '2', '3', '4', '5', '6', '7', '8', '9'].map(d =>
                    <button key={d} type="button" className="pinkey" onClick={() => pinKey(d)}>{d}</button>)}
                  <button type="button" className="pinkey ghost" onClick={() => setPin('')}>مسح</button>
                  <button type="button" className="pinkey" onClick={() => pinKey('0')}>0</button>
                  <button type="button" className="pinkey ghost" onClick={() => pinKey('del')} aria-label="حذف"><Delete size={17} /></button>
                </div>
                <button className="btn pri" style={{ width: '100%' }} disabled={busy || !email || pin.length < 4} onClick={pinSubmit}>
                  {busy ? <RefreshCw size={15} className="spin" /> : <Grid3x3 size={15} />}دخول بالرقم السري
                </button>
              </>
            )}

            {bioUsers.length > 0 && webauthnSupported() && (
              <>
                <div className="row" style={{ justifyContent: 'center', margin: '12px 0', color: 'var(--faint)', fontSize: 11 }}>
                  <span style={{ height: 1, background: 'var(--line)', flex: 1 }} /> أو <span style={{ height: 1, background: 'var(--line)', flex: 1 }} />
                </div>
                <button className="btn" style={{ width: '100%' }} disabled={bioBusy} onClick={bioLogin}>
                  {bioBusy ? <RefreshCw size={15} className="spin" /> : <Fingerprint size={16} />}الدخول بالبصمة الحيوية
                </button>
              </>
            )}
            <div style={{ fontSize: 11, color: 'var(--faint)', marginTop: 14, lineHeight: 1.7, textAlign: 'center' }}>
              نسيت بياناتك؟ راجع المدير العام لإعادة تعيينها من إدارة المستخدمين.
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ================= مكوّنات مشتركة ================= */
function Modal({ title, sub, icon: Icon, children, foot, onClose, wide, flow }) {
  // قفل تمرير الصفحة الخلفية بالكامل (يعمل مع تداخل النوافذ) + إغلاق بمفتاح Escape
  useEffect(() => {
    const de = document.documentElement, b = document.body;
    const prev = { htmlO: de.style.overflow, bodyO: b.style.overflow, osb: b.style.overscrollBehavior };
    de.style.overflow = 'hidden'; b.style.overflow = 'hidden'; b.style.overscrollBehavior = 'none';
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    return () => {
      de.style.overflow = prev.htmlO; b.style.overflow = prev.bodyO; b.style.overscrollBehavior = prev.osb;
      window.removeEventListener('keydown', onKey);
    };
  }, [onClose]);

  // نُصيّر النافذة مباشرةً على body (Portal) حتى لا يحصرها أي عنصر أب فيه transform/filter
  return createPortal((
    <div className="mask" onClick={e => { if (e.target === e.currentTarget) onClose(); }}
      role="dialog" aria-modal="true" aria-label={typeof title === 'string' ? title : undefined}>
      <div className={'modal' + (flow ? ' modal-flow' : '')} style={flow ? undefined : (wide ? { maxWidth: 1100 } : undefined)}>
        <div className="modal-h">
          <div className="modal-h-t">
            <div className="card-t">{Icon && <Icon size={16} color="var(--brass)" />}{title}</div>
            {sub && <div className="modal-h-s">{sub}</div>}
          </div>
          <button className="btn sm gh" onClick={onClose} aria-label="إغلاق"><X size={15} /></button>
        </div>
        <div className="modal-b">{children}</div>
        {foot && <div className="modal-f">{foot}</div>}
      </div>
    </div>
  ), document.body);
}

function Field({ label, children, style }) {
  return <div className="fld" style={style}><label className="lbl">{label}</label>{children}</div>;
}

// حقل مالي ذكي: تنسيق حيّ (١٬٢٥٠٫٠٠) + دعم عدة مبالغ في حقل واحد عند sum
function MoneyField({ value, onChange, sum, placeholder, autoFocus, style }) {
  const [raw, setRaw] = useState(() => (value ? money(value) : ''));
  const [focused, setFocused] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    if (focused) return;
    if (Math.round(parseAmounts(raw).total * 100) !== Math.round((Number(value) || 0) * 100)) {
      setRaw(value ? money(value) : '');
    }
  }, [value]); // eslint-disable-line react-hooks/exhaustive-deps
  const { nums, total } = parseAmounts(raw);
  const multi = sum && nums.length > 1;
  const onText = (e) => {
    let s = e.target.value;
    s = sum ? s.replace(/[^\d.+\n ]/g, '') : fmtCurStr(s.replace(/[^\d.]/g, ''));
    setRaw(s);
    onChange(parseAmounts(s).total);
  };
  // زر «أضف مبلغًا»: يضيف فاصل + لإدخال عدة مبالغ على الجوال حيث لا تتوفّر علامة + في لوحة الأرقام
  const addAmount = () => {
    const base = raw.trim().replace(/[+\s]+$/, '');
    const nv = base ? base + ' + ' : '';
    setRaw(nv); onChange(parseAmounts(nv).total);
    requestAnimationFrame(() => { const el = ref.current; if (el) { el.focus(); const l = el.value.length; try { el.setSelectionRange(l, l); } catch (er) {} } });
  };
  const common = {
    ref, value: raw, placeholder: placeholder || '0.00', inputMode: 'decimal', autoFocus,
    onFocus: () => setFocused(true),
    onBlur: () => { setFocused(false); if (!(sum && parseAmounts(raw).nums.length > 1)) setRaw(value ? money(value) : ''); },
    onChange: onText
  };
  return (
    <>
      {sum
        ? <textarea {...common} className={'inp n inp-sum-ta' + (multi ? ' on' : '')} rows={1}
            placeholder="مبلغ واحد، أو عدة مبالغ: 500+250 — أو زر «أضف مبلغًا»" style={{ ...style, resize: 'vertical', minHeight: 44, lineHeight: 1.6 }} />
        : <input {...common} className="inp n" style={style} />}
      {sum && (
        <div className="money-multi">
          <button type="button" className="btn sm gh money-add" onClick={addAmount}><Plus size={14} />أضف مبلغًا</button>
          {multi && <span className="money-multi-t"><b className="num">{nums.length}</b> مبالغ · الإجمالي: <b className="num">{money(total)}</b></span>}
        </div>
      )}
    </>
  );
}

function Num({ label, value, onChange, hint, sum }) {
  return (
    <div className="fld">
      <label className="lbl">{label}{sum && <span style={{ color: 'var(--brass)', fontWeight: 400 }}> · يقبل عدة مبالغ</span>}</label>
      <MoneyField value={value} onChange={onChange} sum={sum} />
      {hint && <div style={{ fontSize: 10.5, color: 'var(--faint)', marginTop: 4 }}>{hint}</div>}
    </div>
  );
}

/* ================= الجهاز والمتصفح (لسجل التدقيق) ================= */
const deviceType = () => {
  const u = (typeof navigator !== 'undefined' && navigator.userAgent) || '';
  if (/iPhone|iPad|iPod/i.test(u)) return 'iPhone/iPad';
  if (/Android/i.test(u)) return 'Android';
  return 'كمبيوتر';
};
const browserName = () => {
  const u = (typeof navigator !== 'undefined' && navigator.userAgent) || '';
  if (/Edg/i.test(u)) return 'Edge';
  if (/OPR|Opera/i.test(u)) return 'Opera';
  if (/Chrome/i.test(u)) return 'Chrome';
  if (/Firefox/i.test(u)) return 'Firefox';
  if (/Safari/i.test(u)) return 'Safari';
  return 'متصفح';
};

/* ================= نافذة الإخراج الإلزامية قبل إتمام الإغلاق (#21) ================= */
function OutputDialog({ rec, org, onDone, onCancel }) {
  const [method, setMethod] = useState('both');
  const [size, setSize] = useState('80');
  const [phase, setPhase] = useState('choose'); // choose | confirm
  const [attempts, setAttempts] = useState(0);
  const [pdfOk, setPdfOk] = useState(false);
  const [printConfirmed, setPrintConfirmed] = useState(false);
  const [printFailed, setPrintFailed] = useState(false);
  const [pdfAck, setPdfAck] = useState(false);
  const [hash, setHash] = useState('');

  const needPdf = method === 'pdf' || method === 'both';
  const needPrint = method === 'print' || method === 'both';

  const runOutputs = async () => {
    const h = await sha([rec.transferReferenceNo, rec.branchName, rec.date, rec.totalRevenue, rec.totalExpenses, rec.actualCashCount, rec.variance, rec.transferredToMainTreasury].join('|'));
    setHash(h);
    if (needPdf) { const ok = printClosingA4(rec, org); setPdfOk(ok !== false); }
    if (needPrint) { const ok = printReceipt(rec, org, size); setAttempts(1); setPrintFailed(ok === false); }
    setPhase('confirm');
  };
  const reprint = () => { const ok = printReceipt(rec, org, size); setAttempts(a => a + 1); setPrintFailed(ok === false); };
  const regenPdf = () => { const ok = printClosingA4(rec, org); setPdfOk(ok !== false); };

  // يكفي لإتمام الإغلاق أن يكون المُخرَج الرسمي قد أُنشئ فعلاً (بعد «متابعة الإخراج»).
  // تأكيد الطباعة وحالة الـPDF تُسجَّل في التدقيق لكنها لا تحجب الإتمام حتى لا يعلق المستخدم.
  const canFinish = phase === 'confirm';
  const finish = () => onDone({
    outputMethod: method === 'both' ? 'طباعة + PDF' : method === 'pdf' ? 'PDF فقط' : 'طباعة حرارية',
    thermalSize: needPrint ? size + 'مم' : '—',
    pdfStatus: needPdf ? (pdfOk ? 'تم الإنشاء' : 'فشل') : 'غير مطلوب',
    printStatus: needPrint ? (printConfirmed ? 'تمت' : printFailed ? 'فشلت' : 'غير مؤكدة') : 'غير مطلوب',
    printAttempts: attempts, device: deviceType(), browser: browserName(), reportHash: hash
  });

  const opt = (k, lbl, tag) => (
    <button key={k} type="button" onClick={() => setMethod(k)}
      style={{ display: 'flex', alignItems: 'center', gap: 10, width: '100%', textAlign: 'start', marginBottom: 8, padding: '13px 14px', borderRadius: 12, cursor: 'pointer', minHeight: 44,
        border: '1px solid ' + (method === k ? 'var(--brass)' : 'var(--line)'), background: method === k ? 'rgba(200,162,74,.1)' : 'var(--ink3)', color: 'var(--txt)', fontFamily: 'inherit', fontSize: 13.5, fontWeight: 600 }}>
      <span style={{ width: 18, height: 18, borderRadius: '50%', border: '2px solid ' + (method === k ? 'var(--brass)' : 'var(--faint)'), flexShrink: 0, display: 'grid', placeItems: 'center' }}>
        {method === k && <span style={{ width: 9, height: 9, borderRadius: '50%', background: 'var(--brass)' }} />}
      </span>
      <span style={{ flex: 1 }}>{lbl}</span>
      <span className="badge b-dim" style={{ fontSize: 9.5 }}>{tag}</span>
    </button>
  );
  const statusRow = (label, node) => (
    <div className="row" style={{ justifyContent: 'space-between', gap: 10, padding: '9px 0', borderBottom: '1px solid rgba(120,100,80,.14)', flexWrap: 'wrap' }}>
      <span style={{ fontSize: 12.5 }}>{label}</span>{node}
    </div>
  );

  return (
    <Modal title="إخراج الإغلاق الرسمي — خطوة إلزامية" icon={Printer} onClose={onCancel}
      foot={phase === 'confirm'
        ? <>
            <button className="btn pri" disabled={!canFinish} onClick={finish}><Check size={14} />إتمام الإغلاق</button>
            <button className="btn gh" onClick={onCancel}>إلغاء الإغلاق</button>
          </>
        : <>
            <button className="btn pri" onClick={runOutputs}><Printer size={14} />متابعة الإخراج</button>
            <button className="btn gh" onClick={onCancel}>إلغاء</button>
          </>}>
      {phase === 'choose' ? (
        <>
          <div style={{ fontSize: 12.5, color: 'var(--dim)', marginBottom: 12 }}>
            لا يمكن إتمام الإغلاق قبل اختيار مُخرَج رسمي واحد على الأقل:
          </div>
          {opt('both', '🖨 + 📄  طباعة حرارية + تقرير PDF', 'موصى به')}
          {opt('print', '🖨  طباعة حرارية للكاشير', '58/80مم')}
          {opt('pdf', '📄  تقرير PDF رسمي', 'A4')}
          {needPrint && (
            <div style={{ marginTop: 12 }}>
              <div className="lbl">حجم ورق طابعة الكاشير</div>
              <div className="row" style={{ gap: 8 }}>
                <button type="button" className={'btn sm' + (size === '80' ? ' pri' : ' gh')} onClick={() => setSize('80')}>80مم</button>
                <button type="button" className={'btn sm' + (size === '58' ? ' pri' : ' gh')} onClick={() => setSize('58')}>58مم</button>
              </div>
            </div>
          )}
          <div className="cflow-alert" style={{ border: '1px solid rgba(91,147,196,.4)', background: 'rgba(91,147,196,.1)', color: 'var(--sky)', marginTop: 14, borderRadius: 10, padding: '10px 12px', display: 'flex', gap: 8 }}>
            <span>ℹ</span><span style={{ fontSize: 11.5, lineHeight: 1.6 }}>تُرسَل الطباعة عبر نافذة الطباعة في المتصفح — اختر طابعة الكاشير (58/80مم) المثبّتة على الجهاز. سيُطلب منك تأكيد نجاح الطباعة قبل اعتماد الإغلاق.</span>
          </div>
        </>
      ) : (
        <>
          {needPdf && statusRow('📄 تقرير PDF الرسمي',
            (pdfOk || pdfAck) ? <span className="badge b-mint"><Check size={11} />{pdfOk ? 'تم الإنشاء — عايِنه ونزّله من النافذة' : 'مُتابَع'}</span>
              : <span className="row" style={{ gap: 6, flexWrap: 'wrap' }}><span className="badge b-rose">لم تُفتح النافذة</span><button className="btn sm" onClick={regenPdf}>إعادة</button><button className="btn sm gh" onClick={() => setPdfAck(true)}>متابعة بدونها</button></span>)}
          {needPrint && (
            <>
              {statusRow(<span>🖨 طباعة حرارية {size}مم · محاولات: <span className="num">{attempts}</span></span>,
                printConfirmed ? <span className="badge b-mint"><Check size={11} />تمت الطباعة</span>
                  : <span className="badge b-amber">بانتظار تأكيدك</span>)}
              {!printConfirmed && (
                <div className="row" style={{ gap: 8, marginTop: 10, flexWrap: 'wrap' }}>
                  <button className="btn sm pri" onClick={() => { setPrintConfirmed(true); setPrintFailed(false); }}><Check size={13} />نعم، تمت الطباعة</button>
                  <button className="btn sm" onClick={reprint}><RefreshCw size={13} />أعد المحاولة</button>
                  <button className="btn sm gh" onClick={() => { const ns = size === '80' ? '58' : '80'; setSize(ns); }}>بدّل الحجم</button>
                </div>
              )}
            </>
          )}
          <div className="cflow-alert" style={{ border: '1px solid rgba(200,162,74,.35)', background: 'rgba(200,162,74,.08)', color: 'var(--dim)', marginTop: 14, borderRadius: 10, padding: '10px 12px', display: 'flex', gap: 8, fontSize: 11 }}>
            <span>🔒</span><span>بصمة التقرير الرقمية: <span className="num" style={{ fontSize: 10 }}>{(hash || '').slice(0, 20)}…</span><br />الجهاز: {deviceType()} · المتصفح: {browserName()} — تُحفظ في سجل التدقيق.</span>
          </div>
          <div style={{ fontSize: 11.5, color: 'var(--mint)', marginTop: 10, textAlign: 'center', lineHeight: 1.7 }}>
            تم إنشاء المُخرَج الرسمي — اضغط «إتمام الإغلاق» لإنهاء الوردية وبدء وردية جديدة.
            {needPrint && !printConfirmed ? ' (تأكيد الطباعة اختياري ويُسجَّل في التدقيق.)' : ''}
          </div>
        </>
      )}
    </Modal>
  );
}

const ST = {
  draft: ['b-dim', 'مسودة'], submitted: ['b-amber', 'مرحّل للمراجعة'],
  approved: ['b-mint', 'مدقّق ومعتمد'], rejected: ['b-rose', 'مرفوض'],
  pending: ['b-amber', 'قيد الانتظار'], received: ['b-mint', 'مستلم بالخزينة']
};
/* v16.5 — مرفقات PDF: حقول الصور تقبل PDF أيضاً (ميزة قائمة)، لكن العرض كان يضعها في
   وسم <img> فتظهر «صورة مكسورة». هذه الأدوات تكشف النوع وتفتح PDF بشكل صحيح. */
const isPdfData = (v) => typeof v === 'string' && v.startsWith('data:application/pdf');
const openPdfData = (v, name) => {
  try {
    const bin = atob((v.split(',')[1] || ''));
    const arr = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
    const url = URL.createObjectURL(new Blob([arr], { type: 'application/pdf' }));
    const a = document.createElement('a');
    a.href = url; a.target = '_blank'; a.rel = 'noopener';
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 60000);
  } catch (e) { /* ملف تالف */ }
};
function PdfTile({ v, label, small }) {
  return (
    <button type="button" className="btn" onClick={() => openPdfData(v, label)}
      style={{ display: 'flex', alignItems: 'center', gap: 8, width: small ? 'auto' : '100%', justifyContent: 'flex-start', padding: small ? '6px 10px' : '12px 14px' }}>
      <FileText size={small ? 13 : 17} color="var(--rose)" />
      <span style={{ textAlign: 'start', minWidth: 0 }}>
        <b style={{ fontSize: small ? 11 : 12.5, display: 'block' }}>{label || 'مرفق PDF'}</b>
        {!small && <small style={{ color: 'var(--dim)', fontSize: 10.5 }}>ملف PDF — اضغط للفتح في تبويب جديد</small>}
      </span>
    </button>
  );
}

function Badge({ s }) {
  const [c, t] = ST[s] || ['b-dim', s];
  return <span className={'badge ' + c}>{t}</span>;
}

function Kpi({ label, value, sub, icon: Icon, color }) {
  return (
    <div className="kpi" style={{ '--acc': color }}>
      <div className="kpi-l">{Icon && <Icon size={13} color={color} />}{label}</div>
      <div className="kpi-v num">{value}</div>
      {sub && <div className="kpi-s">{sub}</div>}
    </div>
  );
}

/* ============ الخطوة 2: محرّك التنبيهات الذكية الاستباقية ============ */
function computeSmartAlerts(org, ops, myBranches, deficitThreshold = 50) {
  const alerts = [];
  const ids = myBranches.map(b => b.id);
  const td = today();
  const nowMin = new Date().getHours() * 60 + new Date().getMinutes();

  // 1) فروع لم تُغلق بعد موعدها اليوم
  myBranches.forEach(b => {
    const closed = (ops.closings || []).some(c => c.branchId === b.id && c.date === td);
    if (!closed && b.shiftEndTime) {
      const [h, m] = b.shiftEndTime.split(':').map(Number);
      if (nowMin > (h * 60 + m) + 30) {
        alerts.push({ id: 'late-' + b.id, sev: 'high', icon: 'clock',
          title: 'فرع تأخّر عن الإغلاق', msg: `${b.name} تجاوز موعد الإغلاق (${b.shiftEndTime}) ولم يُسجّل إغلاقه بعد.` });
      }
    }
  });

  // 2) عجز صندوق يتجاوز الحد اليوم
  (ops.closings || []).filter(c => countedClosing(c) && c.date === td && ids.includes(c.branchId) && c.variance < -deficitThreshold)
    .forEach(c => alerts.push({ id: 'def-' + c.id, sev: 'high', icon: 'down',
      title: 'عجز صندوق تجاوز الحد', msg: `${c.branchName}: عجز ${money(c.variance)} ر.س في إغلاق اليوم.` }));

  // 3) فواتير موردين تستحق اليوم أو غداً أو متأخرة
  const tomorrow = new Date(Date.now() + 864e5).toISOString().slice(0, 10);
  // المتبقي = القيمة − سداد الرئيسي − سداد الفروع المرتبط (نفس معادلة شاشة الموردين)
  const invBranchPaid = (invId) => sum((ops.closings || []).filter(countedClosing)
    .flatMap(c => (c.supplierPayments || []).filter(pm => pm.invoiceId === invId)), payTotal);
  (ops.invoices || []).filter(i => ids.includes(i.branchId) && (i.amount - (i.paidAmount || 0) - invBranchPaid(i.id)) > 0)
    .forEach(i => {
      const rem = i.amount - (i.paidAmount || 0) - invBranchPaid(i.id);
      if (i.dueDate < td) alerts.push({ id: 'ovd-' + i.id, sev: 'high', icon: 'truck',
        title: 'فاتورة مورد متأخرة', msg: `${i.supplierName} · فاتورة ${i.invoiceNo || ''} · متبقٍّ ${money(rem)} ر.س — تجاوزت ${i.dueDate}.` });
      else if (i.dueDate === td) alerts.push({ id: 'due-' + i.id, sev: 'medium', icon: 'truck',
        title: 'فاتورة مورد تستحق اليوم', msg: `${i.supplierName} · متبقٍّ ${money(rem)} ر.س.` });
      else if (i.dueDate === tomorrow) alerts.push({ id: 'dtm-' + i.id, sev: 'medium', icon: 'truck',
        title: 'فاتورة مورد تستحق غداً', msg: `${i.supplierName} · متبقٍّ ${money(rem)} ر.س.` });
    });

  // 4) سلف موظف تجاوزت راتبه لهذا الشهر
  const month = td.slice(0, 7);
  (org.employees || []).filter(e => ids.includes(e.branchId)).forEach(e => {
    const adv = sum((ops.advances || []).filter(a => a.employeeId === e.id && a.month === month), a => a.amount);
    const gross = (e.baseSalary || 0) + (e.housingAllowance || 0) + (e.transportAllowance || 0);
    if (adv > gross && gross > 0) alerts.push({ id: 'adv-' + e.id, sev: 'medium', icon: 'wallet',
      title: 'سلف تجاوزت الراتب', msg: `${e.name}: مجموع السلف ${money(adv)} ر.س يتجاوز صافي الراتب ${money(gross)} ر.س.` });
  });

  const order = { high: 0, medium: 1, low: 2 };
  return alerts.sort((a, b) => order[a.sev] - order[b.sev]);
}

const ALERT_ICON = { clock: Clock, down: TrendingDown, truck: Truck, wallet: Wallet, bell: Bell };

function Notifications({ ops, org, me, myBranches, commit, onClose }) {
  const list = [...(ops.notifications || [])].sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  const smart = computeSmartAlerts(org, ops, myBranches || []);
  const markAll = () => commit(d => ({ ...d, notifications: (d.notifications || []).map(n => ({ ...n, isRead: true })) }));

  // إعدادات تنبيهات النشاط الحيّة (لمدراء النظام — لكل جهاز)
  const isAdminRole = !!ROLES[me?.role]?.admin;
  const [ncfg, setNcfg] = useState(() => notifyCfg());
  const [nMsg, setNMsg] = useState('');
  const toggleLive = async () => {
    setNMsg('');
    if (!ncfg.on) {
      if (typeof Notification === 'undefined') { setNMsg('متصفحك لا يدعم إشعارات النظام'); return; }
      let perm = Notification.permission;
      if (perm === 'default') perm = await Notification.requestPermission();
      if (perm !== 'granted') { setNMsg('لم يُمنح الإذن — فعّل الإشعارات لهذا الموقع من إعدادات المتصفح'); return; }
    }
    const next = { on: !ncfg.on, sound: ncfg.sound };
    saveNotifyCfg(next); setNcfg(next);
    if (next.on) setNMsg('مفعّلة — ستصلك إشعارات أي نشاط يقوم به الآخرون أثناء فتح المنصة (ولو في تبويب خلفي)');
  };
  const toggleSound = () => { const next = { on: ncfg.on, sound: !ncfg.sound }; saveNotifyCfg(next); setNcfg(next); };
  const testNow = () => {
    const ok = notifyBrowser('تجربة تنبيه — ' + (org.company?.name || 'المنصة'), 'هكذا سيصلك إشعار النشاط', org.company?.logoUrl);
    if (ncfg.sound) alertBeep();
    setNMsg(ok ? 'أُرسلت التجربة ✓' : 'تعذّر الإشعار — تأكد من تفعيله ومن إذن المتصفح');
  };

  return (
    <Modal title="مركز التنبيهات" icon={Bell} onClose={onClose}
      foot={<><button className="btn" onClick={markAll}><Check size={14} />تعليم الكل كمقروء</button>
        <button className="btn gh" onClick={onClose}>إغلاق</button></>}>
      {isAdminRole && (
        <div className="card" style={{ background: 'var(--ink)', padding: 12, marginBottom: 14, border: '1px solid ' + (ncfg.on ? 'rgba(79,178,134,.45)' : 'var(--line)') }}>
          <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 8 }}>
            <div>
              <div style={{ fontSize: 12.5, fontWeight: 700, display: 'flex', gap: 6, alignItems: 'center' }}>
                <Radio size={14} color={ncfg.on ? 'var(--mint)' : 'var(--brass)'} />تنبيهات النشاط الحيّة (هذا الجهاز)
              </div>
              <div style={{ fontSize: 10.5, color: 'var(--faint)', marginTop: 3, lineHeight: 1.6 }}>
                إشعار وصوت لأي نشاط يقوم به الآخرون — ترحيل إغلاق، سداد، تعديل… أثناء فتح المنصة.
              </div>
            </div>
            <div className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
              <button className={'btn sm' + (ncfg.on ? ' ok' : ' pri')} onClick={toggleLive}>
                {ncfg.on ? <><Check size={13} />مفعّلة — إيقاف</> : <><Bell size={13} />تفعيل</>}
              </button>
              <button className={'btn sm' + (ncfg.sound ? '' : ' gh')} onClick={toggleSound} title="نغمة التنبيه">
                {ncfg.sound ? '🔊 الصوت' : '🔇 صامت'}
              </button>
              <button className="btn sm gh" onClick={testNow}>جرّب</button>
            </div>
          </div>
          {nMsg && <div style={{ fontSize: 10.5, marginTop: 8, color: nMsg.includes('✓') || nMsg.startsWith('مفعّلة') ? 'var(--mint)' : 'var(--amber)' }}>{nMsg}</div>}
        </div>
      )}
      {smart.length > 0 && (
        <div style={{ marginBottom: 14 }}>
          <div className="row" style={{ gap: 7, marginBottom: 8, color: 'var(--amber)', fontSize: 12, fontWeight: 600 }}>
            <ShieldAlert size={15} />تنبيهات استباقية ذكية ({smart.length})
          </div>
          {smart.map(a => {
            const Ic = ALERT_ICON[a.icon] || Bell;
            return (
              <div key={a.id} style={{ display: 'flex', gap: 10, alignItems: 'flex-start', padding: '10px 12px', marginBottom: 7,
                borderRadius: 'var(--r-sm)', background: a.sev === 'high' ? 'rgba(217,84,77,.1)' : 'rgba(224,164,88,.1)',
                border: '1px solid ' + (a.sev === 'high' ? 'rgba(217,84,77,.3)' : 'rgba(224,164,88,.3)') }}>
                <div style={{ flexShrink: 0, width: 32, height: 32, borderRadius: 9, display: 'grid', placeItems: 'center',
                  background: a.sev === 'high' ? 'rgba(217,84,77,.18)' : 'rgba(224,164,88,.18)',
                  color: a.sev === 'high' ? 'var(--rose)' : 'var(--amber)' }}>
                  <Ic size={16} />
                </div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: 12.5, fontWeight: 600 }}>{a.title}</div>
                  <div style={{ fontSize: 11.5, color: 'var(--dim)', marginTop: 2, lineHeight: 1.6 }}>{a.msg}</div>
                </div>
              </div>
            );
          })}
          {list.length > 0 && <div style={{ height: 1, background: 'var(--line)', margin: '14px 0 10px' }} />}
        </div>
      )}
      {list.length === 0 && smart.length === 0 && <div className="empty">لا توجد تنبيهات حالياً.</div>}
      {list.map(n => (
        <div key={n.id} className="mono-b" style={{ marginBottom: 8, alignItems: 'flex-start', opacity: n.isRead ? .55 : 1 }}>
          <div>
            <div className="row" style={{ gap: 7, marginBottom: 3 }}>
              <span className={'badge ' + (n.severity === 'high' ? 'b-rose' : n.severity === 'medium' ? 'b-amber' : 'b-sky')}>
                {n.severity === 'high' ? 'عاجل' : n.severity === 'medium' ? 'متابعة' : 'معلومة'}
              </span>
              <span style={{ fontSize: 12.5, fontWeight: 600 }}>{n.title}</span>
            </div>
            <div style={{ fontSize: 11.5, color: 'var(--dim)' }}>{n.message}</div>
            <div style={{ fontSize: 10, color: 'var(--faint)', marginTop: 3 }}>{arTime(n.createdAt)}</div>
          </div>
        </div>
      ))}
    </Modal>
  );
}

/* ================= لوحة المؤشرات ================= */
/* ================= طباعة تقارير الفروع اليومية ================= */
function DailyBranchReport({ org, scoped, myBranches, onClose }) {
  const [date, setDate] = useState(today());
  const [scope, setScope] = useState('all'); // all | one | some
  const [oneBranch, setOneBranch] = useState(myBranches[0]?.id || '');
  const [someIds, setSomeIds] = useState([]);

  const targetBranches = scope === 'all' ? myBranches
    : scope === 'one' ? myBranches.filter(b => b.id === oneBranch)
    : myBranches.filter(b => someIds.includes(b.id));

  const dayClosings = scoped.closings.filter(c => countedClosing(c) && c.date === date &&
    targetBranches.some(b => b.id === c.branchId));

  const toggleSome = (id) => setSomeIds(p => p.includes(id) ? p.filter(x => x !== id) : [...p, id]);

  // طباعة تقرير مجمّع ليوم واحد لكل الفروع المحددة
  const printConsolidated = () => {
    const co = org.company || {};
    const m = (n) => (Math.round((n || 0) * 100) / 100).toLocaleString('en-US', { minimumFractionDigits: 2 });
    const T = {
      rev: sum(dayClosings, c => c.totalRevenue), exp: sum(dayClosings, c => c.totalExpenses),
      cash: sum(dayClosings, c => c.cashSales), card: sum(dayClosings, c => c.cardSales),
      bank: sum(dayClosings, c => c.bankTransferSales || 0), del: sum(dayClosings, c => c.totalDeliverySales),
      transfer: sum(dayClosings, c => c.transferredToMainTreasury), variance: sum(dayClosings, c => c.variance)
    };
    const rows = dayClosings.map(c => `<tr>
      <td>${c.branchName}</td>
      <td class="num brass">${m(c.totalRevenue)}</td>
      <td class="num">${m(c.cashSales)}</td>
      <td class="num">${m(c.cardSales)}</td>
      <td class="num">${m(c.bankTransferSales || 0)}</td>
      <td class="num">${m(c.totalDeliverySales)}</td>
      <td class="num rose">${m(c.totalExpenses)}</td>
      <td class="num mint">${m(c.totalRevenue - c.totalExpenses)}</td>
      <td class="num">${m(c.transferredToMainTreasury)}</td>
      <td class="num ${c.variance < 0 ? 'rose' : ''}">${m(c.variance)}</td></tr>`).join('');
    const w = window.open('', '_blank', 'width=1000,height=800');
    if (!w) return;
    w.document.write(`<!doctype html><html dir="rtl" lang="ar"><head><meta charset="utf-8">
      <title>تقرير الفروع اليومي - ${date}</title><style>${A4_CSS}</style></head><body><div class="page">
      <div class="head">
        <div class="co">${co.logoUrl ? `<img class="logo" src="${co.logoUrl}">` : ''}
          <div><div class="co-n">${co.name || 'المنشأة'}</div>
          <div class="co-m">الرقم الضريبي: ${co.taxNumber || '—'} · السجل التجاري: ${co.commercialReg || '—'}</div></div></div>
        <div class="doc-title">تقرير الإغلاق اليومي المجمّع للفروع</div>
        <div class="doc-sub">${arDate(date)} · عدد الفروع: ${dayClosings.length}</div>
        <div class="doc-sub dim">تاريخ التصدير: ${new Date().toLocaleString('ar-SA-u-nu-latn')}</div>
      </div>
      <div class="kpis">
        <div class="kpi"><span>إجمالي الإيرادات</span><b class="brass">${m(T.rev)} ر.س</b></div>
        <div class="kpi"><span>إجمالي المصروفات</span><b class="rose">${m(T.exp)} ر.س</b></div>
        <div class="kpi ok"><span>صافي اليوم</span><b>${m(T.rev - T.exp)} ر.س</b></div>
        <div class="kpi"><span>المحوّل للخزينة</span><b>${m(T.transfer)} ر.س</b></div>
        <div class="kpi"><span>المبيعات النقدية</span><b>${m(T.cash)} ر.س</b></div>
        <div class="kpi ${T.variance === 0 ? 'ok' : T.variance < 0 ? 'bad' : 'warn'}"><span>فروقات الصندوق</span><b>${m(T.variance)} ر.س</b></div>
      </div>
      <table class="t"><thead><tr>
        <th>الفرع</th><th class="num">الإيراد</th><th class="num">نقدي</th><th class="num">شبكة</th>
        <th class="num">تحويل</th><th class="num">تطبيقات</th><th class="num">المصروف</th>
        <th class="num">الصافي</th><th class="num">للخزينة</th><th class="num">فروقات</th>
      </tr></thead><tbody>${rows || '<tr><td colspan="10" class="ce dim">لا إغلاقات في هذا اليوم للفروع المحددة</td></tr>'}</tbody>
      <tfoot><tr class="tot"><td>الإجمالي</td>
        <td class="num brass">${m(T.rev)}</td><td class="num">${m(T.cash)}</td><td class="num">${m(T.card)}</td>
        <td class="num">${m(T.bank)}</td><td class="num">${m(T.del)}</td><td class="num rose">${m(T.exp)}</td>
        <td class="num mint">${m(T.rev - T.exp)}</td><td class="num">${m(T.transfer)}</td>
        <td class="num">${m(T.variance)}</td></tr></tfoot></table>
      <div class="foot dim">تقرير مجمّع لأغراض الإدارة · ${co.name || ''}</div>
      </div></body></html>`);
    w.document.close();
    setTimeout(() => { w.focus(); w.print(); }, 500);
  };

  // طباعة تقرير رسمي منفصل لكل فرع (كل إغلاق في صفحته)
  const printEachDetailed = () => {
    if (dayClosings.length === 0) return;
    const co = org.company || {};
    const pages = dayClosings.map(c => buildClosingA4(c, org)).join('<div style="page-break-after:always"></div>');
    const w = window.open('', '_blank', 'width=1000,height=800');
    if (!w) return;
    w.document.write(`<!doctype html><html dir="rtl" lang="ar"><head><meta charset="utf-8">
      <title>تقارير الفروع اليومية - ${date}</title><style>${A4_CSS}</style></head><body>${pages}</body></html>`);
    w.document.close();
    setTimeout(() => { w.focus(); w.print(); }, 600);
  };

  return (
    <Modal title="طباعة تقارير الفروع اليومية" icon={FileText} onClose={onClose}
      foot={<>
        <button className="btn pri" disabled={dayClosings.length === 0} onClick={printConsolidated}>
          <FileText size={14} />تقرير مجمّع
        </button>
        <button className="btn" disabled={dayClosings.length === 0} onClick={printEachDetailed}>
          <Printer size={14} />تقرير رسمي لكل فرع
        </button>
        <button className="btn gh" onClick={onClose}>إغلاق</button>
      </>}>
      <Field label="اليوم">
        <input type="date" className="inp" value={date} onChange={e => setDate(e.target.value)} />
      </Field>
      <Field label="نطاق الفروع">
        <div className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
          <button type="button" className={'btn sm' + (scope === 'all' ? ' pri' : ' gh')} onClick={() => setScope('all')}>جميع الفروع</button>
          <button type="button" className={'btn sm' + (scope === 'some' ? ' pri' : ' gh')} onClick={() => setScope('some')}>فروع محددة</button>
          <button type="button" className={'btn sm' + (scope === 'one' ? ' pri' : ' gh')} onClick={() => setScope('one')}>فرع واحد</button>
        </div>
      </Field>
      {scope === 'one' && (
        <Field label="اختر الفرع">
          <select className="sel" value={oneBranch} onChange={e => setOneBranch(e.target.value)}>
            {myBranches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
          </select>
        </Field>
      )}
      {scope === 'some' && (
        <Field label="اختر الفروع المطلوبة">
          <div className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
            {myBranches.map(b => (
              <button key={b.id} type="button" className={'btn sm' + (someIds.includes(b.id) ? ' pri' : ' gh')}
                onClick={() => toggleSome(b.id)}>{b.name}</button>
            ))}
          </div>
        </Field>
      )}
      <div className="card" style={{ background: 'var(--ink)', padding: 12, marginTop: 4 }}>
        <div className="row" style={{ justifyContent: 'space-between' }}>
          <span style={{ fontSize: 12.5, color: 'var(--dim)' }}>الإغلاقات المتاحة في هذا اليوم</span>
          <span className="badge b-brass"><span className="num">{dayClosings.length}</span> من {targetBranches.length} فرع</span>
        </div>
        {dayClosings.length > 0 && (
          <div className="row" style={{ gap: 6, marginTop: 10, flexWrap: 'wrap' }}>
            {dayClosings.map(c => <span key={c.id} className="badge b-dim">{c.branchName}: <span className="num">{money(c.totalRevenue)}</span></span>)}
          </div>
        )}
        {dayClosings.length === 0 && (
          <div style={{ fontSize: 11.5, color: 'var(--amber)', marginTop: 8 }}>
            لا توجد إغلاقات مسجّلة في هذا اليوم للفروع المحددة. اختر يوماً آخر أو نطاقاً مختلفاً.
          </div>
        )}
      </div>
    </Modal>
  );
}

/* ============ تطبيق المبيعات — تحليل مبيعات نقاط البيع (مصدرها الإغلاق اليومي) v10.1 ============ */
function Sales({ org, ops, me, myBranches, scoped, setTab, say }) {
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [repOpen, setRepOpen] = useState(false);
  const inRange = (d) => (!from || d >= from) && (!to || d <= to);
  const cls = (scoped.closings || []).filter(c => countedClosing(c) && inRange(c.date));
  const delOf = (c) => sum(c.deliverySales || [], s => s.amount || 0);
  const totOf = (c) => (c.cashSales || 0) + (c.cardSales || 0) + delOf(c);
  const cash = sum(cls, c => c.cashSales || 0), card = sum(cls, c => c.cardSales || 0), del = sum(cls, delOf);
  const total = cash + card + del;
  const pct = (x) => total > 0 ? Math.round(x / total * 1000) / 10 : 0;
  const byBranch = myBranches.map(b => {
    const cs = cls.filter(c => c.branchId === b.id);
    return { id: b.id, name: b.name, n: cs.length, cash: sum(cs, c => c.cashSales || 0), card: sum(cs, c => c.cardSales || 0), del: sum(cs, delOf), total: sum(cs, totOf) };
  }).filter(x => x.n > 0).sort((a, b) => b.total - a.total);
  const byApp = (org.deliveryApps || []).map(a => ({ n: a.n, total: sum(cls, c => sum((c.deliverySales || []).filter(s => s.appId === a.id), s => s.amount || 0)) })).filter(x => x.total > 0).sort((a, b) => b.total - a.total);
  const days = [...new Set(cls.map(c => c.date))].length;
  const avgDay = days > 0 ? total / days : 0;
  const periodSub = (from || to) ? ((from || '…') + ' → ' + (to || '…')) : 'كل الفترات';

  const printSales = () => {
    const chan = `<table><thead><tr><th>القناة</th><th>المبلغ</th><th>النسبة</th></tr></thead><tbody>
      <tr><td>نقدي</td><td class="n">${money(cash)}</td><td class="n">${pct(cash)}%</td></tr>
      <tr><td>شبكة (مدى/بطاقات)</td><td class="n">${money(card)}</td><td class="n">${pct(card)}%</td></tr>
      <tr><td>تطبيقات التوصيل</td><td class="n">${money(del)}</td><td class="n">${pct(del)}%</td></tr>
      <tr class="tot"><td>الإجمالي</td><td class="n">${money(total)}</td><td class="n">100%</td></tr></tbody></table>`;
    const br = `<table><thead><tr><th>الفرع (نقطة البيع)</th><th>الإغلاقات</th><th>نقدي</th><th>شبكة</th><th>توصيل</th><th>الإجمالي</th></tr></thead><tbody>${byBranch.map(b => `<tr><td>${b.name}</td><td class="n">${b.n}</td><td class="n">${money(b.cash)}</td><td class="n">${money(b.card)}</td><td class="n">${money(b.del)}</td><td class="n">${money(b.total)}</td></tr>`).join('')}</tbody></table>`;
    printA4(org, 'تقرير المبيعات — نقاط البيع', periodSub + ' · ' + days + ' يوم', '<h3>حسب القناة</h3>' + chan + '<h3 style="margin-top:14px">حسب الفرع (نقطة البيع)</h3>' + br) || say('اسمح بالنوافذ المنبثقة للطباعة', 'no');
  };

  const Seg = ({ v, c, label }) => total > 0 && v > 0 ? <div style={{ width: pct(v) + '%', background: c, height: 26, display: 'grid', placeItems: 'center', fontSize: 10, color: '#12100c', fontWeight: 700, minWidth: pct(v) > 8 ? 'auto' : 0, overflow: 'hidden' }} title={label + ' ' + money(v)}>{pct(v) >= 9 ? pct(v) + '%' : ''}</div> : null;

  return (
    <div className="grid" style={{ gap: 14 }}>
      <div className="abar">
        <div className="abar-id"><span className="abar-ic"><CircleDollarSign size={17} /></span>المبيعات<small>مصدرها: نقاط البيع — الإغلاق اليومي</small></div>
        <div className="abar-sp" />
        <div className="abar-dd">
          <button className="btn sm" onClick={() => setRepOpen(o => !o)}><FileBarChart size={14} />التقارير<ChevronDown size={13} /></button>
          {repOpen && (<>
            <div className="abar-back" onClick={() => setRepOpen(false)} />
            <div className="abar-menu"><div className="abar-hd">تقارير المبيعات</div>
              <button onClick={() => { setRepOpen(false); printSales(); }}><Printer size={13} />تقرير المبيعات (A4)</button>
            </div>
          </>)}
        </div>
        <button className="btn sm gh" onClick={() => setTab('closing')}><ClipboardCheck size={14} />نقاط البيع (الإغلاق)</button>
      </div>

      <div className="card"><div className="row" style={{ gap: 8, flexWrap: 'wrap', alignItems: 'center' }}>
        <span style={{ fontSize: 11.5, color: 'var(--dim)' }}>من</span><input type="date" className="inp" style={{ width: 150 }} value={from} onChange={e => setFrom(e.target.value)} />
        <span style={{ fontSize: 11.5, color: 'var(--dim)' }}>إلى</span><input type="date" className="inp" style={{ width: 150 }} value={to} onChange={e => setTo(e.target.value)} />
        {(from || to) && <button className="btn sm gh" onClick={() => { setFrom(''); setTo(''); }}>كل الفترات</button>}
        <span className="badge b-dim" style={{ marginInlineStart: 'auto' }}>{cls.length} إغلاقًا معتمَدًا/مرحّلًا</span>
      </div></div>

      <div className="grid g4">
        <Kpi label="إجمالي المبيعات" value={money(total)} sub={days + ' يوم · متوسط ' + money(avgDay) + '/يوم'} icon={CircleDollarSign} color="#C8A24A" />
        <Kpi label="نقدي" value={money(cash)} sub={pct(cash) + '% من المبيعات'} icon={Coins} color="#4FB286" />
        <Kpi label="شبكة (مدى/بطاقات)" value={money(card)} sub={pct(card) + '% من المبيعات'} icon={CreditCard} color="#5B93C4" />
        <Kpi label="تطبيقات التوصيل" value={money(del)} sub={pct(del) + '% من المبيعات'} icon={Truck} color="#E0A458" />
      </div>

      {total > 0 && (
        <div className="card">
          <div className="card-t" style={{ marginBottom: 10 }}><BarChart3 size={15} color="var(--brass)" />توزيع المبيعات حسب القناة</div>
          <div style={{ display: 'flex', borderRadius: 8, overflow: 'hidden', border: '1px solid var(--line)' }}>
            <Seg v={cash} c="#4FB286" label="نقدي" /><Seg v={card} c="#5B93C4" label="شبكة" /><Seg v={del} c="#E0A458" label="توصيل" />
          </div>
          <div className="row" style={{ gap: 16, marginTop: 8, flexWrap: 'wrap', fontSize: 11.5 }}>
            <span><span style={{ display: 'inline-block', width: 10, height: 10, background: '#4FB286', borderRadius: 2, marginInlineEnd: 5 }} />نقدي {money(cash)}</span>
            <span><span style={{ display: 'inline-block', width: 10, height: 10, background: '#5B93C4', borderRadius: 2, marginInlineEnd: 5 }} />شبكة {money(card)}</span>
            <span><span style={{ display: 'inline-block', width: 10, height: 10, background: '#E0A458', borderRadius: 2, marginInlineEnd: 5 }} />توصيل {money(del)}</span>
          </div>
        </div>
      )}

      <div className="card">
        <div className="card-t" style={{ marginBottom: 8 }}><Store size={15} color="var(--brass)" />المبيعات حسب الفرع (نقطة البيع)</div>
        {byBranch.length === 0 ? <div className="empty">لا مبيعات معتمدة في هذه الفترة.</div> : (
          <div className="tw"><table className="tb">
            <thead><tr><th>الفرع</th><th>الإغلاقات</th><th>نقدي</th><th>شبكة</th><th>توصيل</th><th>الإجمالي</th><th></th></tr></thead>
            <tbody>{byBranch.map(b => (
              <tr key={b.id}>
                <td style={{ fontWeight: 600 }}>{b.name}</td>
                <td className="num">{b.n}</td>
                <td className="num">{money(b.cash)}</td>
                <td className="num">{money(b.card)}</td>
                <td className="num">{money(b.del)}</td>
                <td className="num" style={{ fontWeight: 700 }}>{money(b.total)}</td>
                <td style={{ width: 90 }}><div style={{ height: 6, background: 'var(--ink)', borderRadius: 4, overflow: 'hidden' }}><div style={{ width: (total > 0 ? (b.total / byBranch[0].total * 100) : 0) + '%', height: '100%', background: 'var(--brass)' }} /></div></td>
              </tr>
            ))}</tbody>
          </table></div>
        )}
      </div>

      {byApp.length > 0 && (
        <div className="card">
          <div className="card-t" style={{ marginBottom: 8 }}><Truck size={15} color="var(--brass)" />مبيعات تطبيقات التوصيل</div>
          <div className="tw"><table className="tb">
            <thead><tr><th>التطبيق</th><th>المبيعات</th><th>النسبة من التوصيل</th></tr></thead>
            <tbody>{byApp.map((a, i) => <tr key={i}><td style={{ fontWeight: 600 }}>{a.n}</td><td className="num">{money(a.total)}</td><td className="num">{del > 0 ? Math.round(a.total / del * 100) : 0}%</td></tr>)}</tbody>
          </table></div>
        </div>
      )}

      <div className="note">🔗 مصدر هذه الأرقام <b>نقاط البيع</b> = شاشة «الإغلاق اليومي» حيث يُدخل كل فرع مبيعاته اليومية (نقدي/شبكة/تطبيقات). المبيعات المعتمدة والمرحّلة فقط. اضغط «نقاط البيع (الإغلاق)» أعلاه لفتح المصدر.</div>
    </div>
  );
}

/* ============ الخطوة 1: لوحة مقارنة الفروع الفورية ============ */
function BranchCompare({ org, ops, me, myBranches, scoped, theme, setTab }) {
  const tn = chartTone(theme);
  const [day, setDay] = useState(today());

  const rows = useMemo(() => myBranches.map(b => {
    const c = scoped.closings.find(x => countedClosing(x) && x.branchId === b.id && x.date === day);
    return {
      id: b.id, name: b.name,
      closed: !!c,
      status: c ? c.status : 'none',
      rev: c ? c.totalRevenue : 0,
      exp: c ? c.totalExpenses : 0,
      net: c ? c.totalRevenue - c.totalExpenses : 0,
      cash: c ? c.cashSales : 0,
      variance: c ? c.variance : 0,
      transfer: c ? c.transferredToMainTreasury : 0,
      shiftEnd: b.shiftEndTime || ''
    };
  }), [myBranches, scoped, day]);

  const closedCount = rows.filter(r => r.closed).length;
  const pendingRows = rows.filter(r => !r.closed);
  const deficitRows = rows.filter(r => r.closed && r.variance < 0);
  const totRev = sum(rows, r => r.rev);
  const totNet = sum(rows, r => r.net);
  const sorted = [...rows].filter(r => r.closed).sort((a, b) => b.rev - a.rev);
  const top = sorted[0], bottom = sorted[sorted.length - 1];

  // هل تأخّر فرع عن موعد إغلاقه؟
  const nowMin = new Date().getHours() * 60 + new Date().getMinutes();
  const isToday = day === today();
  const late = (r) => {
    if (!isToday || r.closed || !r.shiftEnd) return false;
    const [h, m] = r.shiftEnd.split(':').map(Number);
    return nowMin > (h * 60 + m) + 30; // متأخر أكثر من 30 دقيقة
  };

  const barData = sorted.map(r => ({ name: r.name.replace('الفرع ', '').replace('فرع ', ''), الإيراد: r.rev, المصروف: r.exp }));

  return (
    <div className="grid" style={{ gap: 14 }}>
      <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 10 }}>
        <div>
          <h2 style={{ fontSize: 17 }}>مقارنة الفروع الفورية</h2>
          <div style={{ fontSize: 12, color: 'var(--dim)' }}>نظرة شاملة على أداء كل الفروع في يوم واحد</div>
        </div>
        <input type="date" className="inp" style={{ width: 'auto' }} value={day} onChange={e => setDay(e.target.value)} />
      </div>

      <div className="grid g4">
        <Kpi label="فروع أغلقت" value={`${closedCount} / ${rows.length}`} icon={CheckCircle2} color="#4FB286" />
        <Kpi label="إجمالي الإيراد" value={money(totRev)} icon={TrendingUp} color="#C8A24A" />
        <Kpi label="صافي المجموعة" value={money(totNet)} icon={Landmark} color={totNet >= 0 ? '#4FB286' : '#D9544D'} />
        <Kpi label="فروع بعجز" value={deficitRows.length} icon={AlertTriangle} color={deficitRows.length ? '#D9544D' : '#4FB286'} />
      </div>

      {/* تنبيهات فورية */}
      {(pendingRows.length > 0 || deficitRows.length > 0) && (
        <div className="card" style={{ borderColor: 'rgba(224,164,88,.35)' }}>
          <div className="card-h"><div className="card-t"><Bell size={15} color="#E0A458" />تنبيهات اليوم</div></div>
          <div className="grid" style={{ gap: 8 }}>
            {pendingRows.map(r => (
              <div key={r.id} className="row" style={{ justifyContent: 'space-between', padding: '8px 12px', background: late(r) ? 'rgba(217,84,77,.1)' : 'var(--ink)', borderRadius: 9, border: '1px solid ' + (late(r) ? 'rgba(217,84,77,.3)' : 'var(--line)') }}>
                <span className="row" style={{ gap: 8, fontSize: 12.5 }}>
                  {late(r) ? <AlertTriangle size={14} color="#D9544D" /> : <Clock size={14} color="#E0A458" />}
                  {r.name}
                </span>
                <span className="badge" style={{ color: late(r) ? '#D9544D' : '#E0A458', borderColor: 'currentColor', fontSize: 10 }}>
                  {late(r) ? 'متأخر عن الإغلاق' : 'لم يُغلق بعد'}{r.shiftEnd ? ' · ' + r.shiftEnd : ''}
                </span>
              </div>
            ))}
            {deficitRows.map(r => (
              <div key={r.id} className="row" style={{ justifyContent: 'space-between', padding: '8px 12px', background: 'rgba(217,84,77,.1)', borderRadius: 9, border: '1px solid rgba(217,84,77,.3)' }}>
                <span className="row" style={{ gap: 8, fontSize: 12.5 }}><TrendingDown size={14} color="#D9544D" />{r.name}</span>
                <span className="badge" style={{ color: '#D9544D', borderColor: 'currentColor', fontSize: 10 }}>عجز صندوق <span className="num">{money(r.variance)}</span></span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* الأفضل والأضعف */}
      {closedCount > 1 && (
        <div className="grid g2">
          <div className="card" style={{ background: 'linear-gradient(135deg,rgba(79,178,134,.1),transparent)' }}>
            <div className="row" style={{ gap: 8, color: '#4FB286', fontSize: 12, marginBottom: 6 }}><ArrowUp size={15} />الأعلى إيراداً</div>
            <div style={{ fontSize: 15, fontWeight: 600 }}>{top?.name}</div>
            <div className="num" style={{ fontSize: 22, color: '#4FB286', marginTop: 4 }}>{money(top?.rev || 0)}</div>
          </div>
          <div className="card" style={{ background: 'linear-gradient(135deg,rgba(217,84,77,.08),transparent)' }}>
            <div className="row" style={{ gap: 8, color: '#D9544D', fontSize: 12, marginBottom: 6 }}><ArrowDown size={15} />الأدنى إيراداً</div>
            <div style={{ fontSize: 15, fontWeight: 600 }}>{bottom?.name}</div>
            <div className="num" style={{ fontSize: 22, color: '#D9544D', marginTop: 4 }}>{money(bottom?.rev || 0)}</div>
          </div>
        </div>
      )}

      {/* رسم بياني مقارن */}
      {barData.length > 0 && (
        <div className="card">
          <div className="card-h"><div className="card-t"><BarChart3 size={15} />الإيراد مقابل المصروف لكل فرع</div></div>
          <ResponsiveContainer width="100%" height={Math.max(220, barData.length * 46)}>
            <BarChart data={barData} layout="vertical" margin={{ right: 12, left: 8 }}>
              <CartesianGrid strokeDasharray="3 3" stroke={tn.grid} horizontal={false} />
              <XAxis type="number" tick={{ fill: tn.tick, fontSize: 11 }} />
              <YAxis type="category" dataKey="name" tick={{ fill: tn.tick, fontSize: 11 }} width={80} />
              <Tooltip contentStyle={{ background: tn.tip, border: '1px solid ' + tn.grid, borderRadius: 8, fontSize: 12, color: tn.tipTxt }} />
              <Bar dataKey="الإيراد" fill={tn.pos} radius={[0, 4, 4, 0]} />
              <Bar dataKey="المصروف" fill={tn.neg} radius={[0, 4, 4, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      )}

      {/* جدول تفصيلي */}
      <div className="card">
        <div className="card-h"><div className="card-t"><Building2 size={15} />تفاصيل كل الفروع</div></div>
        <div className="tw">
          <table className="tb">
            <thead><tr>
              <th>الفرع</th><th>الحالة</th><th className="num">الإيراد</th><th className="num">المصروف</th>
              <th className="num">الصافي</th><th className="num">نقدي</th><th className="num">للخزينة</th><th className="num">الفرق</th>
            </tr></thead>
            <tbody>
              {rows.map(r => (
                <tr key={r.id}>
                  <td>{r.name}</td>
                  <td>
                    {!r.closed ? <span className="badge b-dim" style={{ fontSize: 10 }}>لم يُغلق</span>
                      : r.status === 'approved' ? <span className="badge b-mint" style={{ fontSize: 10 }}>معتمد</span>
                      : r.status === 'submitted' ? <span className="badge b-amber" style={{ fontSize: 10 }}>بانتظار</span>
                      : <span className="badge b-brass" style={{ fontSize: 10 }}>مغلق</span>}
                  </td>
                  <td className="num brass">{r.closed ? money(r.rev) : '—'}</td>
                  <td className="num rose">{r.closed ? money(r.exp) : '—'}</td>
                  <td className="num" style={{ color: r.net >= 0 ? '#4FB286' : '#D9544D' }}>{r.closed ? money(r.net) : '—'}</td>
                  <td className="num">{r.closed ? money(r.cash) : '—'}</td>
                  <td className="num">{r.closed ? money(r.transfer) : '—'}</td>
                  <td className="num" style={{ color: r.variance < 0 ? '#D9544D' : r.variance > 0 ? '#E0A458' : 'var(--dim)' }}>{r.closed ? money(r.variance) : '—'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

// ===== v10.8: اللوحة التنفيذية الموحّدة — تجمع مؤشرات كل الوحدات في شاشة واحدة =====
/* ============================================================
   v13.2 — المشتريات الذكية ونقطة إعادة الطلب
   حدود دنيا/عليا للأصناف، ومعدّل استهلاك، وأيام تغطية، واقتراح كميات
   الطلب، وإنشاء أمر شراء بضغطة. من مخزونك الفعلي — الحدود بيدك، بلا افتراض.
   ============================================================ */
function SmartPurchasing({ org, ops, me, commit, commitOrg, say }) {
  const r2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
  const items = org.items || [];
  const moves = ops.stockMoves || [];
  const canW = ROLES[me?.role]?.scope === 'all';
  const [lvl, setLvl] = useState({});
  const [supId, setSupId] = useState((org.suppliers || [])[0]?.id || '');

  const bal = {}; moves.forEach(m => { bal[m.itemId] = (bal[m.itemId] || 0) + (Number(m.qty) || 0); });
  const balOf = (id) => Math.round((bal[id] || 0) * 1000) / 1000;
  const cutoff = new Date(Date.now() - 30 * 86400000).toISOString().slice(0, 10);
  const usage = {}; moves.forEach(m => { if ((Number(m.qty) || 0) < 0 && (m.at || m.date || '').slice(0, 10) >= cutoff) usage[m.itemId] = (usage[m.itemId] || 0) + (-(Number(m.qty) || 0)); });
  const lastPrice = {}; (ops.purchaseOrders || []).forEach(po => (po.lines || []).forEach(l => { if (l.itemId && (Number(l.price) || 0) > 0) lastPrice[l.itemId] = Number(l.price); }));

  const minOf = (it) => { const v = lvl[it.id] && lvl[it.id].min; return v != null && v !== '' ? Number(v) || 0 : (it.minQty || 0); };
  const maxOf = (it) => { const v = lvl[it.id] && lvl[it.id].max; return v != null && v !== '' ? Number(v) || 0 : (it.maxQty || 0); };
  const rows = items.map(it => {
    const stock = balOf(it.id), min = minOf(it), max = maxOf(it);
    const daily = r2((usage[it.id] || 0) / 30);
    const cover = daily > 0.0001 ? Math.round(stock / daily) : null;
    const needs = min > 0 && stock <= min;
    const suggested = needs ? r2(Math.max(0, (max > 0 ? max : min * 2) - stock)) : 0;
    const status = needs ? 'reorder' : (min > 0 && stock <= min * 1.5 ? 'low' : 'ok');
    return { it, stock, min, max, daily, cover, needs, suggested, status, price: lastPrice[it.id] || it.cost || 0 };
  });
  const toOrder = rows.filter(r => r.suggested > 0);
  const orderValue = r2(sum(toOrder, r => r.suggested * r.price));
  const lowCount = rows.filter(r => r.status !== 'ok').length;

  const saveLevels = async () => {
    await commitOrg(d => ({ ...d, items: (d.items || []).map(it => lvl[it.id] ? { ...it, minQty: minOf(it), maxQty: maxOf(it) } : it) }), { actionType: 'update', targetType: 'stock_item', targetId: 'levels', title: 'حفظ حدود إعادة الطلب', details: Object.keys(lvl).length + ' صنف' });
    setLvl({}); say('حُفظت الحدود ✓');
  };
  const createPO = async () => {
    if (!toOrder.length) return say('لا أصناف تحت حد الطلب حاليًا 👍', 'ok');
    const sp = (org.suppliers || []).find(x => x.id === supId); if (!sp) return say('اختر موردًا أولًا', 'no');
    let mx = 0; (ops.purchaseOrders || []).forEach(x => { const m = /(\d+)$/.exec(x.poNo || ''); if (m) mx = Math.max(mx, +m[1]); });
    const poNo = 'PO-' + String(mx + 1).padStart(4, '0');
    const lines = toOrder.map(r => ({ desc: r.it.name, itemId: r.it.id, qty: r.suggested, price: r.price, received: 0 }));
    const rec = { id: uid('po'), poNo, supplierId: sp.id, supplierName: sp.name, branchId: '', note: 'إعادة طلب تلقائي', lines, status: 'open', by: me.name, at: nowISO(), date: today() };
    await commit(d => ({ ...d, purchaseOrders: [rec, ...(d.purchaseOrders || [])] }), { actionType: 'create', targetType: 'purchase_order', targetId: rec.id, title: 'أنشأ أمر شراء (إعادة طلب)', details: poNo + ' · ' + sp.name + ' · ' + lines.length + ' صنف' });
    say('أُنشئ أمر الشراء ' + poNo + ' ✓ — تابعه من «الموردون ← أوامر الشراء»');
  };
  const exportReq = () => { try { const head = ['الصنف', 'الوحدة', 'المخزون', 'حد الطلب', 'الكمية المقترحة', 'آخر سعر', 'القيمة']; const body = toOrder.map(r => [r.it.name, r.it.unit || '', r.stock, r.min, r.suggested, r.price, r2(r.suggested * r.price)]); const blob = makeXlsx([{ name: 'طلب شراء مقترح', rows: [head, ...body] }]); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'طلب_شراء_مقترح.xlsx'; document.body.appendChild(a); a.click(); document.body.removeChild(a); setTimeout(() => URL.revokeObjectURL(url), 1500); say('نُزّل الطلب (Excel) ✓'); } catch (e) { say('تعذّر توليد Excel', 'no'); } };
  const printReq = () => { const rws = toOrder.map(r => `<tr><td>${_xe(r.it.name)}</td><td>${_xe(r.it.unit || '')}</td><td class="n">${r.stock}</td><td class="n">${r.min}</td><td class="n">${r.suggested}</td><td class="n">${money(r.price)}</td><td class="n">${money(r2(r.suggested * r.price))}</td></tr>`).join('') || '<tr><td colspan="7" style="text-align:center;color:#999">لا أصناف تحتاج طلبًا</td></tr>'; printA4(org, 'طلب شراء مقترح (إعادة طلب)', arDate(today()) + ' · ' + toOrder.length + ' صنف · قيمة ' + money(orderValue), `<table><thead><tr><th>الصنف</th><th>الوحدة</th><th>المخزون</th><th>حد الطلب</th><th>المقترحة</th><th>آخر سعر</th><th>القيمة</th></tr></thead><tbody>${rws}<tr class="tot"><td colspan="6">إجمالي القيمة المقترحة</td><td class="n">${money(orderValue)}</td></tr></tbody></table>`) || say('اسمح بالنوافذ المنبثقة', 'no'); };

  const stBadge = (s) => s === 'reorder' ? { c: 'b-rose', t: 'أعِد الطلب' } : s === 'low' ? { c: 'b-amber', t: 'منخفض' } : { c: 'b-mint', t: 'كافٍ' };

  return (
    <div className="grid" style={{ gap: 14 }}>
      <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 10 }}>
        <div>
          <h2 style={{ fontSize: 17 }}>المشتريات الذكية ونقطة إعادة الطلب</h2>
          <div style={{ fontSize: 12, color: 'var(--dim)' }}>اعرف ماذا تطلب وكم — قبل أن ينفد أيّ صنف</div>
        </div>
        <div className="row" style={{ gap: 8, flexWrap: 'wrap' }}>
          <button className="btn sm" onClick={printReq}><Printer size={13} />طباعة الطلب</button>
          <button className="btn sm" onClick={exportReq}><Download size={13} />Excel</button>
          {canW && Object.keys(lvl).length > 0 && <button className="btn sm pri" onClick={saveLevels}><Check size={14} />حفظ الحدود</button>}
        </div>
      </div>

      {items.length === 0 ? <div className="card"><div className="empty">أضف أصناف مخزونك من «المخزون ← الأصناف والأرصدة» أولًا، ثم حدّد حد الطلب لكلٍّ منها هنا.</div></div> : <>
        <div className="grid g3">
          <Kpi label="أصناف تحت حد الطلب" value={String(toOrder.length)} sub={toOrder.length ? 'تحتاج إعادة طلب' : 'كل الأصناف كافية 👍'} icon={AlertTriangle} color={toOrder.length ? '#D9544D' : '#4FB286'} />
          <Kpi label="قيمة أمر الشراء المقترح" value={money(orderValue)} sub="بآخر أسعار الشراء" icon={Truck} color="#C8A24A" />
          <Kpi label="أصناف تحت المراقبة" value={String(lowCount)} sub="منخفضة أو تحت الحد" icon={HardDrive} color={lowCount ? '#E0A458' : '#4FB286'} />
        </div>

        {(org.suppliers || []).length > 0 && toOrder.length > 0 && canW && (
          <div className="card" style={{ borderColor: 'rgba(79,178,134,.3)' }}>
            <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 8, alignItems: 'center' }}>
              <div style={{ fontSize: 12.5 }}><b>{toOrder.length} صنف</b> تحت حد الطلب بقيمة <b>{money(orderValue)}</b> — أنشئ أمر شراء بها بضغطة.</div>
              <div className="row" style={{ gap: 8 }}>
                <select className="inp" style={{ width: 180 }} value={supId} onChange={e => setSupId(e.target.value)}>{(org.suppliers || []).map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select>
                <button className="btn pri" onClick={createPO}><Plus size={14} />إنشاء أمر شراء</button>
              </div>
            </div>
          </div>
        )}

        <div className="card">
          <div className="card-t" style={{ marginBottom: 8 }}><ClipboardCheck size={15} color="var(--brass)" />تحليل إعادة الطلب — حدّد الحد الأدنى/الأعلى لكل صنف</div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>الصنف</th><th style={{ textAlign: 'end' }}>المخزون</th><th style={{ textAlign: 'center' }}>حد الطلب</th><th style={{ textAlign: 'center' }}>الحد الأعلى</th><th style={{ textAlign: 'end' }}>استهلاك/يوم</th><th style={{ textAlign: 'end' }}>أيام التغطية</th><th style={{ textAlign: 'end' }}>المقترحة</th><th style={{ textAlign: 'center' }}>الحالة</th></tr></thead>
              <tbody>
                {rows.map(r => { const sb = stBadge(r.status); return (
                  <tr key={r.it.id} style={r.status === 'reorder' ? { background: 'rgba(217,84,77,.06)' } : null}>
                    <td style={{ fontWeight: 600, fontSize: 12.5 }}>{r.it.name}<span style={{ fontSize: 9.5, color: 'var(--faint)' }}> · {r.it.unit || ''}</span></td>
                    <td className="num" style={{ textAlign: 'end', fontWeight: 700 }}>{r.stock}</td>
                    <td style={{ textAlign: 'center' }}><input className="inp n" style={{ width: 70, textAlign: 'center' }} inputMode="decimal" value={lvl[r.it.id] && lvl[r.it.id].min != null ? lvl[r.it.id].min : (r.it.minQty || '')} placeholder="—" disabled={!canW} onChange={e => setLvl(s => ({ ...s, [r.it.id]: { ...s[r.it.id], min: e.target.value.replace(/[^\d.]/g, '') } }))} /></td>
                    <td style={{ textAlign: 'center' }}><input className="inp n" style={{ width: 70, textAlign: 'center' }} inputMode="decimal" value={lvl[r.it.id] && lvl[r.it.id].max != null ? lvl[r.it.id].max : (r.it.maxQty || '')} placeholder="—" disabled={!canW} onChange={e => setLvl(s => ({ ...s, [r.it.id]: { ...s[r.it.id], max: e.target.value.replace(/[^\d.]/g, '') } }))} /></td>
                    <td className="num" style={{ textAlign: 'end', color: 'var(--dim)' }}>{r.daily || '—'}</td>
                    <td className="num" style={{ textAlign: 'end', color: r.cover != null && r.cover < 7 ? '#D9544D' : 'var(--dim)' }}>{r.cover != null ? r.cover + ' يوم' : '—'}</td>
                    <td className="num" style={{ textAlign: 'end', fontWeight: 800, color: r.suggested > 0 ? 'var(--brass-l)' : 'var(--faint)' }}>{r.suggested || '—'}</td>
                    <td style={{ textAlign: 'center' }}><span className={'badge ' + sb.c}>{sb.t}</span></td>
                  </tr>
                ); })}
              </tbody>
            </table>
          </div>
        </div>

        <div className="note">💡 <b>حد الطلب</b> (نقطة إعادة الطلب): عند وصول المخزون إليه أو دونه يُقترَح الطلب. <b>الكمية المقترحة</b> = الحد الأعلى − المخزون (أو ضعف حد الطلب إن لم تحدّد أعلى). <b>الاستهلاك/اليوم</b> وأيام التغطية من حركات الصرف آخر ٣٠ يومًا. آخر سعر من أوامر الشراء السابقة. عدّل الحدود واحفظها لتُحسب تلقائيًا.</div>
      </>}
    </div>
  );
}

/* ============================================================
   v13.1 — التدفق النقدي المتدحرج (13 أسبوعًا)
   تنبؤ أسبوعي بالنقد الداخل والخارج لكشف فجوات السيولة مبكرًا.
   الافتراضات مبدئية من متوسطاتك الفعلية وذممك — كلها قابلة للتعديل. بلا افتراض خفيّ.
   ============================================================ */
function CashFlow13({ org, ops, me, scoped, theme, commitOrg, say }) {
  const tn = chartTone(theme);
  const r2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
  const A = useMemo(() => buildAccounting(org, ops), [org, ops]);
  const num = (s) => Number(String(s).replace(/[^\d.-]/g, '')) || 0;
  const [cfg, setCfg] = useState(() => { const c = org.cashflowCfg || {}; return { wkSales: c.wkSales != null ? String(c.wkSales) : '', wkOpex: c.wkOpex != null ? String(c.wkOpex) : '', payroll: c.payroll != null ? String(c.payroll) : '', fixed: c.fixed != null ? String(c.fixed) : '', colWeeks: c.colWeeks != null ? String(c.colWeeks) : '4', startCash: c.startCash != null ? String(c.startCash) : '' }; });
  const canPost = rolePost(me?.role);

  const cash0 = r2(sum(A.accounts.filter(a => a.cash), a => a.balance));
  const counted = scoped.closings.filter(countedClosing);
  const cutoff = new Date(Date.now() - 56 * 86400000).toISOString().slice(0, 10);
  const recent = counted.filter(c => (c.date || '') >= cutoff);
  const wkRevDef = recent.length ? r2(sum(recent, c => c.totalRevenue || 0) / 8) : 0;
  const wkExpDef = recent.length ? r2(sum(recent, c => c.totalExpenses || 0) / 8) : 0;
  const payrollDef = r2(sum(org.employees || [], e => (e.baseSalary || 0) + (e.housingAllowance || 0) + (e.transportAllowance || 0) + (e.otherAllowance || 0)));
  const arTot = r2(sum(buildPartners(org, ops).filter(p => p.type === 'customer'), p => customerAging(p, today()).total));
  const apTot = r2(sum(buildPartners(org, ops).filter(p => p.type === 'supplier'), p => supplierAging(p, today()).total));

  const startCash = cfg.startCash !== '' ? num(cfg.startCash) : cash0;
  const wkSales = cfg.wkSales !== '' ? num(cfg.wkSales) : wkRevDef;
  const wkOpex = cfg.wkOpex !== '' ? num(cfg.wkOpex) : wkExpDef;
  const payroll = cfg.payroll !== '' ? num(cfg.payroll) : payrollDef;
  const fixed = num(cfg.fixed);
  const colWeeks = Math.min(13, Math.max(1, Math.round(num(cfg.colWeeks) || 4)));

  const weeks = useMemo(() => {
    const out = []; let bal = startCash; let lastMonth = null; const start = new Date();
    for (let w = 0; w < 13; w++) {
      const ws = new Date(start.getTime() + w * 7 * 86400000);
      const ym = ws.getFullYear() + '-' + ws.getMonth(); const newMonth = ym !== lastMonth; lastMonth = ym;
      const inAR = w < colWeeks ? r2(arTot / colWeeks) : 0, outAP = w < colWeeks ? r2(apTot / colWeeks) : 0;
      const outPay = newMonth ? payroll : 0, outFix = newMonth ? fixed : 0;
      const inflow = r2(wkSales + inAR), outflow = r2(wkOpex + outAP + outPay + outFix);
      const net = r2(inflow - outflow); bal = r2(bal + net);
      out.push({ label: ws.toISOString().slice(5, 10), inflow, outflow, net, bal, gap: bal < -0.004, pay: outPay > 0 });
    }
    return out;
  }, [startCash, wkSales, wkOpex, payroll, fixed, colWeeks, arTot, apTot]);

  const minBal = weeks.reduce((m, w) => Math.min(m, w.bal), startCash);
  const gapCount = weeks.filter(w => w.gap).length;
  const endBal = weeks.length ? weeks[12].bal : startCash;
  const chartData = [{ label: 'الآن', الرصيد: startCash }, ...weeks.map(w => ({ label: w.label, الرصيد: w.bal }))];

  const save = async () => { await commitOrg(d => ({ ...d, cashflowCfg: { wkSales: num(wkSales), wkOpex: num(wkOpex), payroll: num(payroll), fixed: num(fixed), colWeeks, startCash: num(startCash) } }), { actionType: 'update', targetType: 'tax_settings', targetId: 'cashflowCfg', need: 'post', title: 'حفظ إعداد التدفق النقدي', details: '13 أسبوعًا' }); say('حُفظ الإعداد ✓'); };
  const exportCF = () => { try { const head = ['الأسبوع', 'النقد الداخل', 'النقد الخارج', 'صافي الأسبوع', 'الرصيد النهائي']; const body = weeks.map(w => [w.label, w.inflow, w.outflow, w.net, w.bal]); const blob = makeXlsx([{ name: 'تدفق 13 أسبوعًا', rows: [head, ...body] }]); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'التدفق_النقدي_13أسبوع.xlsx'; document.body.appendChild(a); a.click(); document.body.removeChild(a); setTimeout(() => URL.revokeObjectURL(url), 1500); say('نُزّل التدفق (Excel) ✓'); } catch (e) { say('تعذّر توليد Excel', 'no'); } };

  const F = (label, key, ph, hint) => (
    <Field label={label}><input className="inp n" inputMode="decimal" value={cfg[key]} placeholder={ph} disabled={!canPost} onChange={e => setCfg(s => ({ ...s, [key]: e.target.value.replace(/[^\d.-]/g, '') }))} />
      {hint && <div style={{ fontSize: 9.5, color: 'var(--faint)', marginTop: 2 }}>{hint}</div>}</Field>
  );

  return (
    <div className="grid" style={{ gap: 14 }}>
      <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 10 }}>
        <div>
          <h2 style={{ fontSize: 17 }}>التدفق النقدي المتدحرج — ١٣ أسبوعًا</h2>
          <div style={{ fontSize: 12, color: 'var(--dim)' }}>توقّع النقد أسبوعًا بأسبوع لتكتشف فجوات السيولة قبل وقوعها</div>
        </div>
        <div className="row" style={{ gap: 8, flexWrap: 'wrap' }}>
          <button className="btn sm" onClick={exportCF}><Download size={13} />Excel</button>
          {canPost && <button className="btn sm pri" onClick={save}><Check size={14} />حفظ الإعداد</button>}
        </div>
      </div>

      <div className="card">
        <div className="card-t" style={{ marginBottom: 10 }}><Settings size={15} color="var(--brass)" />الافتراضات (اتركها فارغة لاستخدام المبدئي من بياناتك)</div>
        <div className="grid g3" style={{ gap: 10 }}>
          {F('النقد الابتدائي', 'startCash', money(cash0), 'رصيدك النقدي الحالي')}
          {F('مبيعات أسبوعية متوقعة', 'wkSales', money(wkRevDef), 'متوسط آخر ٨ أسابيع')}
          {F('مصروفات تشغيلية أسبوعية', 'wkOpex', money(wkExpDef), 'متوسط آخر ٨ أسابيع')}
          {F('رواتب شهرية', 'payroll', money(payrollDef), 'مرّة كل شهر')}
          {F('التزامات ثابتة شهرية', 'fixed', '0', 'إيجار ونحوه — مرّة كل شهر')}
          {F('أسابيع تحصيل/سداد الذمم', 'colWeeks', '4', 'توزيع الذمم المدينة/الدائنة')}
        </div>
        <div className="note" style={{ marginTop: 8 }}>الذمم المدينة ({money(arTot)}) تُوزَّع تحصيلًا على أول {colWeeks} أسابيع، والدائنة ({money(apTot)}) سدادًا كذلك. الرواتب والثابتة مرّة عند بداية كل شهر.</div>
      </div>

      <div className="grid g3">
        <Kpi label="أدنى رصيد نقدي متوقّع" value={money(minBal)} sub={minBal < 0 ? 'عجز متوقّع!' : 'يبقى موجبًا'} icon={AlertTriangle} color={minBal < 0 ? '#D9544D' : minBal < startCash * 0.25 ? '#E0A458' : '#4FB286'} />
        <Kpi label="أسابيع العجز (رصيد سالب)" value={String(gapCount)} sub={gapCount ? 'تحتاج تدبير سيولة' : 'لا فجوات خلال ١٣ أسبوعًا'} icon={CalendarDays} color={gapCount ? '#D9544D' : '#4FB286'} />
        <Kpi label="الرصيد بعد ١٣ أسبوعًا" value={money(endBal)} sub={(endBal >= startCash ? 'أعلى من البداية' : 'أقل من البداية') + ' (' + money(startCash) + ')'} icon={Banknote} color={endBal >= 0 ? '#4FB286' : '#D9544D'} />
      </div>

      <div className="card">
        <div className="card-t" style={{ marginBottom: 14 }}><TrendingUp size={15} color="var(--brass)" />مسار الرصيد النقدي — إن هبط تحت الصفر فهناك فجوة</div>
        <div style={{ height: 240, direction: 'ltr' }}>
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={chartData} margin={{ top: 6, right: 10, left: -8, bottom: 0 }}>
              <CartesianGrid stroke={tn.grid} vertical={false} />
              <XAxis dataKey="label" tick={{ fill: tn.tick, fontSize: 9 }} axisLine={false} tickLine={false} />
              <YAxis tick={{ fill: tn.tick, fontSize: 10 }} axisLine={false} tickLine={false} tickFormatter={short} />
              <Tooltip contentStyle={{ background: tn.tip, border: '1px solid ' + tn.grid, borderRadius: 10, fontSize: 12, direction: 'rtl', color: tn.tipTxt }} formatter={(v) => [money(v), 'الرصيد']} />
              <Line type="monotone" dataKey="الرصيد" stroke={minBal < 0 ? '#D9544D' : '#4FB286'} strokeWidth={2.4} dot={{ r: 2 }} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="card">
        <div className="card-t" style={{ marginBottom: 8 }}><FileText size={15} color="var(--brass)" />الجدول الأسبوعي</div>
        <div className="tw">
          <table className="tb">
            <thead><tr><th>الأسبوع (يبدأ)</th><th style={{ textAlign: 'end' }}>الداخل</th><th style={{ textAlign: 'end' }}>الخارج</th><th style={{ textAlign: 'end' }}>الصافي</th><th style={{ textAlign: 'end' }}>الرصيد</th><th style={{ textAlign: 'center' }}>الحالة</th></tr></thead>
            <tbody>
              {weeks.map((w, i) => (
                <tr key={i} style={w.gap ? { background: 'rgba(217,84,77,.07)' } : null}>
                  <td className="num" style={{ fontSize: 11 }}>{w.label}{w.pay && <span className="badge b-sky" style={{ marginInlineStart: 6, fontSize: 9 }}>رواتب</span>}</td>
                  <td className="num" style={{ textAlign: 'end', color: 'var(--mint)' }}>{money(w.inflow)}</td>
                  <td className="num" style={{ textAlign: 'end', color: '#D9544D' }}>{money(w.outflow)}</td>
                  <td className="num" style={{ textAlign: 'end', color: w.net >= 0 ? 'var(--mint)' : '#D9544D' }}>{w.net >= 0 ? '+' : ''}{money(w.net)}</td>
                  <td className="num" style={{ textAlign: 'end', fontWeight: 800, color: w.gap ? '#D9544D' : 'inherit' }}>{money(w.bal)}</td>
                  <td style={{ textAlign: 'center' }}>{w.gap ? <span className="badge b-rose">عجز</span> : <span className="badge b-mint">سليم</span>}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div className="note">💡 تنبؤ استرشادي متدحرج من اليوم. المبيعات والمصروفات الأسبوعية مبدئيًا من متوسط آخر ٨ أسابيع، والذمم من أعمارها، والرواتب والثابتة عند بداية كل شهر — عدّل أيّ افتراض ليعكس واقعك. راقب <b>أدنى رصيد</b> و<b>أسابيع العجز</b> لتدبّر السيولة مبكرًا.</div>
    </div>
  );
}

/* ============================================================
   v13.0 — تقرير الإدارة الشهري الشامل (حزمة المالك)
   يجمع القوائم والمؤشرات والأعمار والتعادل والنمو وأداء الفروع في تقرير
   واحد للشهر — معاينة على الشاشة + طباعة A4 كاملة + Excel متعدّد الأوراق.
   ============================================================ */
function BoardPack({ org, ops, me, myBranches, scoped, say }) {
  const r2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
  const A = useMemo(() => buildAccounting(org, ops), [org, ops]);
  const [month, setMonth] = useState(today().slice(0, 7));

  const D = useMemo(() => {
    const magg = {}; A.entries.forEach(e => { if ((e.date || '').slice(0, 7) !== month) return; e.lines.forEach(l => { const x = magg[l.code] || (magg[l.code] = { d: 0, c: 0 }); x.d += l.debit; x.c += l.credit; }); });
    const mBal = (code, kind) => { const x = magg[code]; if (!x) return 0; return (kind === 'exp' || kind === 'asset') ? x.d - x.c : x.c - x.d; };
    const revAccts = A.accounts.filter(a => a.kind === 'rev' && magg[a.code]).map(a => ({ name: a.name, amt: r2(mBal(a.code, 'rev')) }));
    const expAccts = A.accounts.filter(a => a.kind === 'exp' && magg[a.code]).map(a => ({ code: a.code, name: a.name, amt: r2(mBal(a.code, 'exp')) })).sort((x, y) => y.amt - x.amt);
    const rev = r2(sum(revAccts, a => a.amt)), totExp = r2(sum(expAccts, a => a.amt)), net = r2(rev - totExp);
    const bsAssets = r2(sum(A.accounts.filter(a => a.kind === 'asset'), a => a.balance));
    const bsLiab = r2(sum(A.accounts.filter(a => a.kind === 'liab'), a => a.balance));
    // حقوق الملكية تشمل صافي أرباح الفترة غير المقفلة حتى تتوازن القائمة (الأصول = الالتزامات + الملكية)
    const cumNet = r2(sum(A.accounts.filter(a => a.kind === 'rev'), a => a.balance) - sum(A.accounts.filter(a => a.kind === 'exp'), a => a.balance));
    const bsEquity = r2(sum(A.accounts.filter(a => a.kind === 'equity'), a => a.balance) + cumNet);
    const cash = r2(sum(A.accounts.filter(a => a.cash), a => a.balance));
    const labor = r2(mBal('5201', 'exp') + mBal('5202', 'exp'));
    const costClass = org.costClass || {};
    const isVar = (c, n) => ['5301', '5302', '5198', '5150', '5199'].includes(c) || /مواد|مشتريات|بضاعة|خامات|طعام/.test(n || '');
    const variable = r2(sum(expAccts.filter(a => (costClass[a.code] || (isVar(a.code, a.name) ? 'variable' : 'fixed')) === 'variable'), a => a.amt));
    const fixed = r2(totExp - variable);
    const commissions = r2(mBal('5301', 'exp') + mBal('5302', 'exp'));
    const foodPct = rev > 0.004 ? r2((variable - commissions) / rev * 100) : 0;
    const laborPct = rev > 0.004 ? r2(labor / rev * 100) : 0;
    const primePct = r2(foodPct + laborPct);
    const varRatio = rev > 0.004 ? variable / rev : 0;
    const be = (1 - varRatio) > 0.0001 ? r2(fixed / (1 - varRatio)) : 0;
    const margin = rev > 0.004 ? r2(net / rev * 100) : 0;
    const pd = new Date(month + '-01'); pd.setMonth(pd.getMonth() - 1); const lastM = pd.toISOString().slice(0, 7);
    const counted = scoped.closings.filter(countedClosing);
    const mRevC = (m) => r2(sum(counted.filter(c => (c.date || '').slice(0, 7) === m), c => c.totalRevenue || 0));
    const revThis = mRevC(month), revLast = mRevC(lastM);
    const growth = revLast > 0.004 ? r2((revThis - revLast) / revLast * 100) : null;
    const arTot = r2(sum(buildPartners(org, ops).filter(p => p.type === 'customer'), p => customerAging(p, today()).total));
    const apTot = r2(sum(buildPartners(org, ops).filter(p => p.type === 'supplier'), p => supplierAging(p, today()).total));
    const perBr = (myBranches || []).map(b => { const bc = counted.filter(c => c.branchId === b.id && (c.date || '').slice(0, 7) === month); return { name: b.name, rev: r2(sum(bc, c => c.totalRevenue || 0)), net: r2(sum(bc, c => (c.totalRevenue || 0) - (c.totalExpenses || 0))) }; }).filter(x => x.rev > 0.004).sort((a, b) => b.net - a.net);
    return { revAccts, expAccts, rev, totExp, net, bsAssets, bsLiab, bsEquity, cash, foodPct, laborPct, primePct, be, margin, growth, lastM, revLast, arTot, apTot, perBr, hasData: rev > 0.004 || counted.some(c => (c.date || '').slice(0, 7) === month) };
  }, [A, month, org, ops, scoped, myBranches]);

  const mL = monthLabel(month);
  const printFull = () => {
    const tRows = (arr, neg) => arr.map(x => `<tr><td>${_xe(x.name)}</td><td class="n">${neg ? '(' + money(x.amt) + ')' : money(x.amt)}</td></tr>`).join('') || '<tr><td colspan="2" style="text-align:center;color:#999">—</td></tr>';
    const brRows = D.perBr.map(b => `<tr><td>${_xe(b.name)}</td><td class="n">${money(b.rev)}</td><td class="n">${money(b.net)}</td></tr>`).join('') || '<tr><td colspan="3" style="text-align:center;color:#999">لا بيانات فروع للشهر</td></tr>';
    const body = `
    <div class="box" style="display:flex;gap:10px;flex-wrap:wrap">
      <div style="flex:1;min-width:120px"><div class="sub">الإيراد</div><b>${money(D.rev)}</b></div>
      <div style="flex:1;min-width:120px"><div class="sub">صافي الربح</div><b>${money(D.net)}</b></div>
      <div style="flex:1;min-width:120px"><div class="sub">هامش الربح</div><b>${D.margin}%</b></div>
      <div style="flex:1;min-width:120px"><div class="sub">النقد</div><b>${money(D.cash)}</b></div>
      ${D.growth != null ? `<div style="flex:1;min-width:120px"><div class="sub">النمو عن ${D.lastM}</div><b>${D.growth >= 0 ? '+' : ''}${D.growth}%</b></div>` : ''}
    </div>
    <div class="grid2">
      <div><h2>قائمة الدخل — ${mL}</h2><table>${tRows(D.revAccts)}<tr class="tot"><td>إجمالي الإيراد</td><td class="n">${money(D.rev)}</td></tr>
      ${tRows(D.expAccts, true)}<tr class="tot"><td>إجمالي المصروفات</td><td class="n">(${money(D.totExp)})</td></tr>
      <tr class="tot"><td>${D.net >= 0 ? 'صافي الربح' : 'صافي الخسارة'}</td><td class="n">${money(D.net)}</td></tr></table></div>
      <div><h2>المركز المالي (حتى ${arDate(today())})</h2><table>
      <tr class="tot"><td>إجمالي الأصول</td><td class="n">${money(D.bsAssets)}</td></tr>
      <tr><td>إجمالي الالتزامات</td><td class="n">${money(D.bsLiab)}</td></tr>
      <tr><td>حقوق الملكية (شامل ربح الفترة)</td><td class="n">${money(D.bsEquity)}</td></tr>
      <tr class="tot"><td>الالتزامات + حقوق الملكية</td><td class="n">${money(r2(D.bsLiab + D.bsEquity))}</td></tr>
      <tr><td>النقد والصناديق</td><td class="n">${money(D.cash)}</td></tr></table>
      <h2>المؤشرات التشغيلية</h2><table>
      <tr><td>تكلفة الطعام %</td><td class="n">${D.foodPct}%</td></tr>
      <tr><td>تكلفة العمالة %</td><td class="n">${D.laborPct}%</td></tr>
      <tr><td>التكلفة الأولية %</td><td class="n">${D.primePct}%</td></tr>
      <tr><td>نقطة التعادل الشهرية</td><td class="n">${money(D.be)}</td></tr></table></div>
    </div>
    <h2>الذمم</h2><table><tr><td>ذمم مدينة (على العملاء)</td><td class="n">${money(D.arTot)}</td></tr><tr><td>ذمم دائنة (للموردين)</td><td class="n">${money(D.apTot)}</td></tr></table>
    <h2>أداء الفروع — ${mL}</h2><table><thead><tr><th>الفرع</th><th class="n">الإيراد</th><th class="n">الصافي</th></tr></thead><tbody>${brRows}</tbody></table>`;
    printA4(org, 'تقرير الإدارة الشهري — ' + mL, 'حزمة المالك · صادر ' + arDate(today()), body) || say('اسمح بالنوافذ المنبثقة للطباعة', 'no');
  };
  const exportXlsx = () => {
    try {
      const is = [['قائمة الدخل — ' + mL, ''], ...D.revAccts.map(a => [a.name, a.amt]), ['إجمالي الإيراد', D.rev], ...D.expAccts.map(a => [a.name, -a.amt]), ['إجمالي المصروفات', -D.totExp], ['صافي الربح', D.net]];
      const bs = [['المركز المالي', ''], ['إجمالي الأصول', D.bsAssets], ['إجمالي الالتزامات', D.bsLiab], ['حقوق الملكية (شامل ربح الفترة)', D.bsEquity], ['الالتزامات + الملكية', r2(D.bsLiab + D.bsEquity)], ['النقد', D.cash]];
      const kp = [['المؤشر', 'القيمة'], ['هامش الربح %', D.margin], ['تكلفة الطعام %', D.foodPct], ['تكلفة العمالة %', D.laborPct], ['التكلفة الأولية %', D.primePct], ['نقطة التعادل', D.be], ['النمو عن الشهر السابق %', D.growth == null ? '' : D.growth], ['ذمم مدينة', D.arTot], ['ذمم دائنة', D.apTot]];
      const br = [['الفرع', 'الإيراد', 'الصافي'], ...D.perBr.map(b => [b.name, b.rev, b.net])];
      const blob = makeXlsx([{ name: 'قائمة الدخل', rows: is }, { name: 'المركز المالي', rows: bs }, { name: 'المؤشرات', rows: kp }, { name: 'الفروع', rows: br }]);
      const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'تقرير_الإدارة_' + month + '.xlsx'; document.body.appendChild(a); a.click(); document.body.removeChild(a); setTimeout(() => URL.revokeObjectURL(url), 1500); say('نُزّل التقرير (Excel) ✓');
    } catch (e) { say('تعذّر توليد Excel', 'no'); }
  };

  const Mini = ({ title, icon: Ic, rows, foot }) => (
    <div className="card">
      <div className="card-t" style={{ marginBottom: 8 }}>{Ic && <Ic size={15} color="var(--brass)" />}{title}</div>
      <div className="tw"><table className="tb"><tbody>
        {rows.map((r, i) => <tr key={i} style={r[2] ? { fontWeight: 800, background: 'rgba(200,162,74,.05)' } : null}><td style={{ fontSize: 12.5 }}>{r[0]}</td><td className="num" style={{ textAlign: 'end', fontWeight: r[2] ? 800 : 500 }}>{r[1]}</td></tr>)}
      </tbody></table></div>
      {foot}
    </div>
  );

  return (
    <div className="grid" style={{ gap: 14 }}>
      <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 10 }}>
        <div>
          <h2 style={{ fontSize: 17 }}>تقرير الإدارة الشهري — حزمة المالك</h2>
          <div style={{ fontSize: 12, color: 'var(--dim)' }}>كل ما تحتاجه عن {mL} في تقرير واحد — القوائم والمؤشرات والذمم والفروع</div>
        </div>
        <div className="row" style={{ gap: 8, flexWrap: 'wrap' }}>
          <input type="month" className="inp" style={{ width: 'auto' }} value={month} onChange={e => setMonth(e.target.value)} />
          <button className="btn sm pri" onClick={printFull}><Printer size={13} />طباعة التقرير الكامل</button>
          <button className="btn sm" onClick={exportXlsx}><Download size={13} />Excel</button>
        </div>
      </div>

      {!D.hasData ? <div className="card"><div className="empty">لا نشاط مسجّل في {mL} — اختر شهرًا فيه إغلاقات وقيود.</div></div> : <>
        <div className="grid g4">
          <Kpi label="الإيراد" value={money(D.rev)} sub={mL} icon={TrendingUp} color="#C8A24A" />
          <Kpi label="صافي الربح" value={money(D.net)} sub={'هامش ' + D.margin + '%'} icon={Landmark} color={D.net >= 0 ? '#4FB286' : '#D9544D'} />
          <Kpi label="النقد والصناديق" value={money(D.cash)} sub="حتى اليوم" icon={Banknote} color="#5B93C4" />
          <Kpi label="النمو عن الشهر السابق" value={D.growth == null ? '—' : (D.growth >= 0 ? '+' : '') + D.growth + '%'} sub={D.growth == null ? 'لا شهر سابق' : 'مقابل ' + D.lastM} icon={D.growth >= 0 ? ArrowUp : ArrowDown} color={D.growth == null ? '#7E7566' : D.growth >= 0 ? '#4FB286' : '#D9544D'} />
        </div>

        <div className="grid g2" style={{ alignItems: 'start' }}>
          <Mini title={'قائمة الدخل — ' + mL} icon={FileBarChart} rows={[
            ...D.revAccts.map(a => [a.name, money(a.amt)]), ['إجمالي الإيراد', money(D.rev), true],
            ...D.expAccts.slice(0, 6).map(a => [a.name, '(' + money(a.amt) + ')']),
            ['إجمالي المصروفات', '(' + money(D.totExp) + ')', true], [D.net >= 0 ? 'صافي الربح' : 'صافي الخسارة', money(D.net), true]
          ]} />
          <div className="grid" style={{ gap: 12 }}>
            <Mini title="المركز المالي" icon={Scale} rows={[['إجمالي الأصول', money(D.bsAssets), true], ['إجمالي الالتزامات', money(D.bsLiab)], ['حقوق الملكية (شامل ربح الفترة)', money(D.bsEquity)], ['الالتزامات + الملكية', money(r2(D.bsLiab + D.bsEquity)), true]]} />
            <Mini title="المؤشرات التشغيلية" icon={BarChart3} rows={[['تكلفة الطعام %', D.foodPct + '%'], ['تكلفة العمالة %', D.laborPct + '%'], ['التكلفة الأولية %', D.primePct + '%'], ['نقطة التعادل', money(D.be), true]]} />
          </div>
        </div>

        <div className="grid g2" style={{ alignItems: 'start' }}>
          <Mini title="الذمم" icon={Users} rows={[['ذمم مدينة (على العملاء)', money(D.arTot)], ['ذمم دائنة (للموردين)', money(D.apTot)]]} />
          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}><Store size={15} color="var(--brass)" />أداء الفروع — {mL}</div>
            <div className="tw"><table className="tb">
              <thead><tr><th>الفرع</th><th style={{ textAlign: 'end' }}>الإيراد</th><th style={{ textAlign: 'end' }}>الصافي</th></tr></thead>
              <tbody>
                {D.perBr.map((b, i) => <tr key={i}><td style={{ fontSize: 12.5, fontWeight: 600 }}>{b.name}</td><td className="num" style={{ textAlign: 'end' }}>{money(b.rev)}</td><td className="num" style={{ textAlign: 'end', color: b.net >= 0 ? 'var(--mint)' : '#D9544D' }}>{money(b.net)}</td></tr>)}
                {D.perBr.length === 0 && <tr><td colSpan={3}><div className="empty">لا بيانات فروع للشهر.</div></td></tr>}
              </tbody>
            </table></div>
          </div>
        </div>

        <div className="note">📄 هذه معاينة مختصرة. اضغط <b>«طباعة التقرير الكامل»</b> لمستند A4 مفصّل، أو <b>Excel</b> لملف متعدّد الأوراق (قائمة الدخل · المركز المالي · المؤشرات · الفروع). القوائم من قيود {mL}؛ المركز المالي تراكميّ حتى اليوم.</div>
      </>}
    </div>
  );
}

/* ============================================================
   v12.9 — التخطيط والسيناريوهات (ماذا-لو)
   انطلاقًا من أرقام شهرٍ فعلي: حاكِ قرارات (أسعار/تكلفة مواد/تكاليف
   ثابتة/فرع جديد) وشاهد أثرها على الربح والتعادل قبل أن تقرّر. بلا افتراض.
   ============================================================ */
function Scenario({ org, ops, me, scoped, theme, say }) {
  const tn = chartTone(theme);
  const r2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
  const A = useMemo(() => buildAccounting(org, ops), [org, ops]);
  const [month, setMonth] = useState(today().slice(0, 7));
  const [sc, setSc] = useState({ revD: '', varD: '', fixD: '', brRev: '', brFix: '' });
  const num = (s) => Number(String(s).replace(/[^\d.-]/g, '')) || 0;

  const agg = useMemo(() => { const m = {}; A.entries.forEach(e => { if ((e.date || '').slice(0, 7) !== month) return; e.lines.forEach(l => { const x = m[l.code] || (m[l.code] = { d: 0, c: 0 }); x.d += l.debit; x.c += l.credit; }); }); return m; }, [A, month]);
  const accBal = (code, kind) => { const x = agg[code]; if (!x) return 0; return (kind === 'exp' || kind === 'asset') ? x.d - x.c : x.c - x.d; };
  const rev0 = r2(sum(A.accounts.filter(a => a.kind === 'rev'), a => accBal(a.code, 'rev')));
  const costClass = org.costClass || {};
  const isVarDefault = (code, name) => ['5301', '5302', '5198', '5150', '5199'].includes(code) || /مواد|مشتريات|بضاعة|خامات|طعام/.test(name || '');
  const expAccts = A.accounts.filter(a => a.kind === 'exp' && agg[a.code]).map(a => ({ code: a.code, name: a.name, amt: r2(accBal(a.code, 'exp')) }));
  const var0 = r2(sum(expAccts.filter(a => (costClass[a.code] || (isVarDefault(a.code, a.name) ? 'variable' : 'fixed')) === 'variable'), a => a.amt));
  const fix0 = r2(sum(expAccts.filter(a => (costClass[a.code] || (isVarDefault(a.code, a.name) ? 'variable' : 'fixed')) === 'fixed'), a => a.amt));
  const net0 = r2(rev0 - var0 - fix0);
  const varRatio0 = rev0 > 0.004 ? var0 / rev0 : 0;
  const be0 = (1 - varRatio0) > 0.0001 ? r2(fix0 / (1 - varRatio0)) : 0;
  const margin0 = rev0 > 0.004 ? r2(net0 / rev0 * 100) : 0;

  const revD = num(sc.revD), varD = num(sc.varD), fixD = num(sc.fixD), brRev = num(sc.brRev), brFix = num(sc.brFix);
  const rev1 = r2(rev0 * (1 + revD / 100) + brRev);
  const var1 = r2(var0 * (1 + revD / 100) * (1 + varD / 100) + brRev * varRatio0);
  const fix1 = r2(fix0 + fixD + brFix);
  const net1 = r2(rev1 - var1 - fix1);
  const varRatio1 = rev1 > 0.004 ? var1 / rev1 : 0;
  const be1 = (1 - varRatio1) > 0.0001 ? r2(fix1 / (1 - varRatio1)) : 0;
  const margin1 = rev1 > 0.004 ? r2(net1 / rev1 * 100) : 0;
  const dNet = r2(net1 - net0), dBe = r2(be1 - be0);
  const changed = revD || varD || fixD || brRev || brFix;

  const cmp = [
    ['الإيراد', rev0, rev1, true], ['التكاليف المتغيرة', var0, var1, false], ['التكاليف الثابتة', fix0, fix1, false],
    ['صافي الربح', net0, net1, true], ['هامش الربح %', margin0, margin1, true, true], ['نقطة التعادل', be0, be1, false]
  ];
  const preset = (patch) => setSc(s => ({ ...s, ...patch }));
  const reset = () => setSc({ revD: '', varD: '', fixD: '', brRev: '', brFix: '' });
  const chartData = [{ name: 'الإيراد', الحالي: rev0, السيناريو: rev1 }, { name: 'صافي الربح', الحالي: net0, السيناريو: net1 }];
  const exportSc = () => { try { const head = ['البند', 'الحالي', 'السيناريو', 'التغيّر']; const body = cmp.map(r => [r[0], r[4] ? r2(r[1]) : r[1], r[4] ? r2(r[2]) : r[2], r2(r[2] - r[1])]); const blob = makeXlsx([{ name: 'سيناريو ' + month, rows: [head, ...body] }]); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'سيناريو_' + month + '.xlsx'; document.body.appendChild(a); a.click(); document.body.removeChild(a); setTimeout(() => URL.revokeObjectURL(url), 1500); say('نُزّل السيناريو (Excel) ✓'); } catch (e) { say('تعذّر توليد Excel', 'no'); } };

  const L = (label, key, hint) => (
    <Field label={label}><input className="inp n" inputMode="decimal" value={sc[key]} placeholder="0" onChange={e => setSc(s => ({ ...s, [key]: e.target.value.replace(/[^\d.-]/g, '') }))} />
      {hint && <div style={{ fontSize: 9.5, color: 'var(--faint)', marginTop: 2 }}>{hint}</div>}</Field>
  );

  return (
    <div className="grid" style={{ gap: 14 }}>
      <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 10 }}>
        <div>
          <h2 style={{ fontSize: 17 }}>التخطيط والسيناريوهات (ماذا-لو)</h2>
          <div style={{ fontSize: 12, color: 'var(--dim)' }}>حاكِ قراراتك قبل أن تتّخذها — انطلاقًا من أرقام {monthLabel(month)}</div>
        </div>
        <div className="row" style={{ gap: 8, flexWrap: 'wrap' }}>
          <input type="month" className="inp" style={{ width: 'auto' }} value={month} onChange={e => setMonth(e.target.value)} />
          <button className="btn sm gh" onClick={reset}><RefreshCw size={13} />تصفير</button>
          <button className="btn sm" onClick={exportSc}><Download size={13} />Excel</button>
        </div>
      </div>

      {rev0 <= 0.004 ? <div className="card"><div className="empty">لا إيراد في {monthLabel(month)} — اختر شهرًا فيه نشاط لتبني عليه سيناريوهاتك.</div></div> : <>
        <div className="card">
          <div className="card-t" style={{ marginBottom: 10 }}><Compass size={15} color="var(--brass)" />روافع القرار</div>
          <div className="row" style={{ gap: 6, flexWrap: 'wrap', marginBottom: 12 }}>
            <button className="btn sm gh" onClick={() => preset({ revD: '5' })}>رفع الأسعار ٥٪</button>
            <button className="btn sm gh" onClick={() => preset({ varD: '-10' })}>خفض المواد ١٠٪</button>
            <button className="btn sm gh" onClick={() => preset({ fixD: '5000' })}>توظيف (+٥٬٠٠٠ ثابت)</button>
            <button className="btn sm gh" onClick={() => preset({ brRev: String(r2(rev0)), brFix: '10000' })}>فرع مماثل جديد</button>
          </div>
          <div className="grid g3" style={{ gap: 10 }}>
            {L('تغيّر الإيراد %', 'revD', 'رفع/خفض الأسعار أو الكميات (+ زيادة، − نقص)')}
            {L('تغيّر تكلفة المواد %', 'varD', 'تغيّر أسعار الموردين للوحدة')}
            {L('تغيّر التكاليف الثابتة (ر.س)', 'fixD', 'إيجار/توظيف إضافي (+) أو توفير (−)')}
            {L('إيراد فرع جديد شهريًا (ر.س)', 'brRev', 'بنفس هيكل تكاليف نشاطك الحالي')}
            {L('تكاليف الفرع الثابتة (ر.س)', 'brFix', 'إيجار ورواتب الفرع الجديد')}
          </div>
        </div>

        <div className="grid g3">
          <Kpi label="التغيّر في صافي الربح" value={(dNet >= 0 ? '+' : '') + money(dNet)} sub={changed ? 'شهريًا مقابل الحالي' : 'اضبط الروافع أعلاه'} icon={dNet >= 0 ? TrendingUp : TrendingDown} color={dNet >= 0 ? '#4FB286' : '#D9544D'} />
          <Kpi label="صافي ربح السيناريو" value={money(net1)} sub={'هامش ' + margin1 + '% (كان ' + margin0 + '%)'} icon={Landmark} color={net1 >= 0 ? '#4FB286' : '#D9544D'} />
          <Kpi label="نقطة التعادل الجديدة" value={money(be1)} sub={(dBe >= 0 ? 'ارتفعت ' : 'انخفضت ') + money(Math.abs(dBe))} icon={Scale} color={dBe <= 0 ? '#4FB286' : '#E0A458'} />
        </div>

        <div className="grid g2" style={{ alignItems: 'start' }}>
          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}><FileText size={15} color="var(--brass)" />الحالي مقابل السيناريو</div>
            <div className="tw">
              <table className="tb">
                <thead><tr><th>البند</th><th style={{ textAlign: 'end' }}>الحالي</th><th style={{ textAlign: 'end' }}>السيناريو</th><th style={{ textAlign: 'end' }}>التغيّر</th></tr></thead>
                <tbody>
                  {cmp.map((r, i) => { const d = r2(r[2] - r[1]); const good = r[3] ? d >= 0 : d <= 0; const fmt = (v) => r[4] ? r2(v).toFixed(1) + '%' : money(v); return (
                    <tr key={i} style={r[0] === 'صافي الربح' ? { fontWeight: 800, background: 'rgba(200,162,74,.05)' } : null}>
                      <td>{r[0]}</td>
                      <td className="num" style={{ textAlign: 'end' }}>{fmt(r[1])}</td>
                      <td className="num" style={{ textAlign: 'end', fontWeight: 700 }}>{fmt(r[2])}</td>
                      <td className="num" style={{ textAlign: 'end', color: Math.abs(d) < 0.005 ? 'var(--dim)' : good ? 'var(--mint)' : '#D9544D' }}>{d > 0 ? '+' : ''}{fmt(d)}</td>
                    </tr>
                  ); })}
                </tbody>
              </table>
            </div>
          </div>
          <div className="card">
            <div className="card-t" style={{ marginBottom: 14 }}><BarChart3 size={15} color="var(--brass)" />المقارنة البيانية</div>
            <div style={{ height: 230, direction: 'ltr' }}>
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={chartData} margin={{ top: 6, right: 6, left: -12, bottom: 0 }}>
                  <CartesianGrid stroke={tn.grid} vertical={false} />
                  <XAxis dataKey="name" tick={{ fill: tn.tick, fontSize: 10 }} axisLine={false} tickLine={false} />
                  <YAxis tick={{ fill: tn.tick, fontSize: 10 }} axisLine={false} tickLine={false} tickFormatter={short} />
                  <Tooltip cursor={{ fill: 'rgba(255,255,255,.03)' }} contentStyle={{ background: tn.tip, border: '1px solid ' + tn.grid, borderRadius: 10, fontSize: 12, direction: 'rtl', color: tn.tipTxt }} formatter={(v, n) => [money(v), n]} />
                  <Bar dataKey="الحالي" fill={tn.muted} radius={[5, 5, 0, 0]} />
                  <Bar dataKey="السيناريو" fill={tn.accent} radius={[5, 5, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>

        <div className="note">💡 المحاكاة تفترض أن التكاليف المتغيّرة تتحرّك مع النشاط (نسبتها من الإيراد ثابتة ما لم تغيّر «تكلفة المواد %»)، والثابتة تبقى ثابتة إلا بما تضيفه. الأرقام الأساسية من قيود {monthLabel(month)} وتصنيف تكاليفها في «تحليل التعادل». نتائج استرشادية للتخطيط.</div>
      </>}
    </div>
  );
}

/* ============================================================
   v12.8 — لوحة مؤشرات بأهداف (Scorecard)
   اختر مؤشراتك، حدّد أهدافها الشهرية، وتابع تحقّقها بإشارات لونية.
   القيم الفعلية من قيودك؛ الأهداف بيدك — بلا افتراض.
   ============================================================ */
const SC_KPIS = [
  { k: 'rev', ar: 'إيراد الشهر', unit: 'sar', dir: 'up' },
  { k: 'net', ar: 'صافي ربح الشهر', unit: 'sar', dir: 'up' },
  { k: 'margin', ar: 'هامش صافي الربح', unit: 'pct', dir: 'up' },
  { k: 'food', ar: 'تكلفة الطعام', unit: 'pct', dir: 'down' },
  { k: 'labor', ar: 'تكلفة العمالة', unit: 'pct', dir: 'down' },
  { k: 'prime', ar: 'التكلفة الأولية (طعام+عمالة)', unit: 'pct', dir: 'down' },
  { k: 'avgday', ar: 'متوسط الإغلاق اليومي', unit: 'sar', dir: 'up' },
  { k: 'variance', ar: 'فرق الصندوق (تسامح)', unit: 'sar', dir: 'zero' },
  { k: 'count', ar: 'عدد الإغلاقات', unit: 'num', dir: 'up' },
  { k: 'cash', ar: 'النقد الحالي', unit: 'sar', dir: 'up' }
];
function Scorecard({ org, ops, me, scoped, commitOrg, say, setTab }) {
  const r2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
  const A = useMemo(() => buildAccounting(org, ops), [org, ops]);
  const [month, setMonth] = useState(today().slice(0, 7));
  const [tg, setTg] = useState(() => ({ ...((org.scorecard && org.scorecard.targets) || {}) }));
  const [enabled, setEnabled] = useState(() => (org.scorecard && org.scorecard.enabled) || SC_KPIS.map(k => k.k));
  const canPost = rolePost(me?.role);

  const agg = useMemo(() => { const m = {}; A.entries.forEach(e => { if ((e.date || '').slice(0, 7) !== month) return; e.lines.forEach(l => { const x = m[l.code] || (m[l.code] = { d: 0, c: 0 }); x.d += l.debit; x.c += l.credit; }); }); return m; }, [A, month]);
  const accBal = (code, kind) => { const x = agg[code]; if (!x) return 0; return (kind === 'exp' || kind === 'asset') ? x.d - x.c : x.c - x.d; };
  const rev = r2(sum(A.accounts.filter(a => a.kind === 'rev'), a => accBal(a.code, 'rev')));
  const exp = r2(sum(A.accounts.filter(a => a.kind === 'exp'), a => accBal(a.code, 'exp')));
  const net = r2(rev - exp);
  const margin = rev > 0.004 ? r2(net / rev * 100) : 0;
  const labor = r2(accBal('5201', 'exp') + accBal('5202', 'exp'));
  const laborPct = rev > 0.004 ? r2(labor / rev * 100) : 0;
  const costClass = org.costClass || {};
  const isVarDefault = (code, name) => ['5301', '5302', '5198', '5150', '5199'].includes(code) || /مواد|مشتريات|بضاعة|خامات|طعام/.test(name || '');
  const expAccts = A.accounts.filter(a => a.kind === 'exp' && agg[a.code]).map(a => ({ code: a.code, name: a.name, amt: r2(accBal(a.code, 'exp')) }));
  const variable = r2(sum(expAccts.filter(a => (costClass[a.code] || (isVarDefault(a.code, a.name) ? 'variable' : 'fixed')) === 'variable'), a => a.amt));
  const commissions = r2(accBal('5301', 'exp') + accBal('5302', 'exp'));
  const foodPct = rev > 0.004 ? r2((variable - commissions) / rev * 100) : 0;
  const prime = r2(foodPct + laborPct);
  const counted = scoped.closings.filter(c => countedClosing(c) && (c.date || '').slice(0, 7) === month);
  const days = new Set(counted.map(c => c.date)).size || 1;
  const val = { rev, net, margin, food: foodPct, labor: laborPct, prime, avgday: r2(rev / days), variance: r2(sum(counted, c => c.variance || 0)), count: counted.length, cash: r2(sum(A.accounts.filter(a => a.cash), a => a.balance)) };

  const numT = (k) => { const v = tg[k]; if (v == null || v === '') return null; const n = Number(String(v).replace(/[^\d.-]/g, '')); return isNaN(n) ? null : n; };
  const statusOf = (kpi, actual, target) => {
    if (target == null) return { s: 'none', c: '#7E7566', ar: 'بلا هدف' };
    if (kpi.dir === 'up') return actual >= target ? { s: 'ok', c: '#4FB286', ar: 'محقّق' } : actual >= target * 0.85 ? { s: 'near', c: '#E0A458', ar: 'قريب' } : { s: 'miss', c: '#D9544D', ar: 'دون الهدف' };
    if (kpi.dir === 'down') return actual <= target ? { s: 'ok', c: '#4FB286', ar: 'محقّق' } : actual <= target * 1.15 ? { s: 'near', c: '#E0A458', ar: 'قريب' } : { s: 'miss', c: '#D9544D', ar: 'تجاوز الهدف' };
    return Math.abs(actual) <= Math.abs(target) ? { s: 'ok', c: '#4FB286', ar: 'ضمن الحد' } : Math.abs(actual) <= Math.abs(target) * 2 ? { s: 'near', c: '#E0A458', ar: 'قريب' } : { s: 'miss', c: '#D9544D', ar: 'خارج الحد' };
  };
  const fmtVal = (kpi, v) => kpi.unit === 'pct' ? (r2(v).toFixed(1) + '%') : kpi.unit === 'num' ? String(r2(v)) : money(v);
  const rows = SC_KPIS.filter(k => enabled.includes(k.k)).map(kpi => { const actual = r2(val[kpi.k]); const target = numT(kpi.k); return { kpi, actual, target, st: statusOf(kpi, actual, target) }; });
  const withTarget = rows.filter(r => r.target != null);
  const achieved = withTarget.filter(r => r.st.s === 'ok').length;

  const save = async () => { await commitOrg(d => ({ ...d, scorecard: { targets: tg, enabled } }), { actionType: 'update', targetType: 'tax_settings', targetId: 'scorecard', title: 'حفظ لوحة الأهداف', details: withTarget.length + ' هدف' }); say('حُفظت اللوحة ✓'); };
  const toggleKpi = (k) => setEnabled(e => e.includes(k) ? e.filter(x => x !== k) : [...e, k]);
  const exportSC = () => { try { const head = ['المؤشر', 'القيمة الحالية', 'الهدف', 'الحالة']; const body = rows.map(r => [r.kpi.ar, r.kpi.unit === 'pct' ? r2(r.actual) : r.actual, r.target == null ? '' : r.target, r.st.ar]); const blob = makeXlsx([{ name: 'لوحة الأهداف ' + month, rows: [head, ...body] }]); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'لوحة_الأهداف_' + month + '.xlsx'; document.body.appendChild(a); a.click(); document.body.removeChild(a); setTimeout(() => URL.revokeObjectURL(url), 1500); say('نُزّلت اللوحة (Excel) ✓'); } catch (e) { say('تعذّر توليد Excel', 'no'); } };

  return (
    <div className="grid" style={{ gap: 14 }}>
      <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 10 }}>
        <div>
          <h2 style={{ fontSize: 17 }}>لوحة المؤشرات بأهداف</h2>
          <div style={{ fontSize: 12, color: 'var(--dim)' }}>حدّد أهدافك الشهرية وتابع تحقّقها بإشارات لونية — القيم من قيودك</div>
        </div>
        <div className="row" style={{ gap: 8, flexWrap: 'wrap' }}>
          <input type="month" className="inp" style={{ width: 'auto' }} value={month} onChange={e => setMonth(e.target.value)} />
          <button className="btn sm" onClick={exportSC}><Download size={13} />Excel</button>
          {canPost && <button className="btn sm pri" onClick={save}><Check size={14} />حفظ</button>}
        </div>
      </div>

      <div className="grid g3">
        <Kpi label="أهداف محقّقة" value={achieved + ' / ' + withTarget.length} sub={withTarget.length ? Math.round(achieved / withTarget.length * 100) + '% من أهدافك' : 'حدّد أهدافك أدناه'} icon={CheckCircle2} color={withTarget.length && achieved === withTarget.length ? '#4FB286' : achieved > 0 ? '#E0A458' : '#7E7566'} />
        <Kpi label="إيراد الشهر" value={money(rev)} sub={monthLabel(month)} icon={TrendingUp} color="#C8A24A" />
        <Kpi label="صافي الشهر" value={money(net)} sub={'هامش ' + margin + '%'} icon={Landmark} color={net >= 0 ? '#4FB286' : '#D9544D'} />
      </div>

      <div className="card">
        <div className="card-t" style={{ marginBottom: 10 }}><CheckCircle2 size={15} color="var(--brass)" />المؤشرات مقابل الأهداف — {monthLabel(month)}</div>
        <div className="tw">
          <table className="tb">
            <thead><tr><th>المؤشر</th><th style={{ textAlign: 'end' }}>القيمة الحالية</th><th style={{ textAlign: 'center' }}>الهدف</th><th style={{ textAlign: 'center' }}>الحالة</th></tr></thead>
            <tbody>
              {rows.map(r => (
                <tr key={r.kpi.k}>
                  <td style={{ fontSize: 12.5, fontWeight: 600 }}>{r.kpi.ar}<span style={{ fontSize: 9.5, color: 'var(--faint)' }}> · {r.kpi.dir === 'up' ? 'الأعلى أفضل' : r.kpi.dir === 'down' ? 'الأقل أفضل' : 'قرب الصفر'}</span></td>
                  <td className="num" style={{ textAlign: 'end', fontWeight: 700 }}>{fmtVal(r.kpi, r.actual)}</td>
                  <td style={{ textAlign: 'center' }}>
                    <input className="inp n" style={{ width: 100, textAlign: 'center' }} inputMode="decimal" value={tg[r.kpi.k] != null ? tg[r.kpi.k] : ''} placeholder="—" disabled={!canPost} onChange={e => setTg(s => ({ ...s, [r.kpi.k]: e.target.value.replace(/[^\d.-]/g, '') }))} />
                  </td>
                  <td style={{ textAlign: 'center' }}><span className="badge" style={{ background: 'transparent', border: '1px solid ' + r.st.c, color: r.st.c }}>● {r.st.ar}</span></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div style={{ fontSize: 11, color: 'var(--dim)', margin: '12px 0 6px' }}>المؤشرات المعروضة (اضغط لإظهار/إخفاء)</div>
        <div className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
          {SC_KPIS.map(k => <button key={k.k} className={'btn sm' + (enabled.includes(k.k) ? ' pri' : ' gh')} onClick={() => canPost && toggleKpi(k.k)} disabled={!canPost}>{enabled.includes(k.k) ? '✓ ' : ''}{k.ar}</button>)}
        </div>
      </div>

      <div className="note">🎯 القيمة الحالية تُحتسب من قيود الشهر المختار؛ الهدف تحدّده أنت. الإشارة: <b style={{ color: '#4FB286' }}>أخضر</b> محقّق · <b style={{ color: '#E0A458' }}>أصفر</b> قريب (ضمن ١٥٪) · <b style={{ color: '#D9544D' }}>أحمر</b> بعيد. نِسَب الطعام والعمالة تتبع تصنيف التكاليف في «تحليل التعادل».</div>
    </div>
  );
}

/* ============================================================
   v12.6 — تحليل التعادل وتكلفة الطعام
   من أرقامك الفعلية (إيراد ومصروفات الشهر): تصنيف التكاليف ثابت/متغيّر
   (بمبدئيات معلنة قابلة للتعديل) → نقطة التعادل وهامش الأمان، ونِسَب
   تكلفة الطعام والعمالة والتكلفة الأولية. بلا افتراض — التصنيف بيدك.
   ============================================================ */
function BreakEven({ org, ops, me, scoped, setTab, theme, commitOrg, say }) {
  const tn = chartTone(theme);
  const r2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
  const A = useMemo(() => buildAccounting(org, ops), [org, ops]);
  const [month, setMonth] = useState(today().slice(0, 7));
  const [ovr, setOvr] = useState(() => ({ ...(org.costClass || {}) }));
  const [daysStr, setDaysStr] = useState(String((org.beCfg && org.beCfg.days) || 30));
  const canPost = rolePost(me?.role);

  const agg = useMemo(() => { const m = {}; A.entries.forEach(e => { if ((e.date || '').slice(0, 7) !== month) return; e.lines.forEach(l => { const x = m[l.code] || (m[l.code] = { d: 0, c: 0 }); x.d += l.debit; x.c += l.credit; }); }); return m; }, [A, month]);
  const acctBal = (code, kind) => { const x = agg[code]; if (!x) return 0; return (kind === 'exp' || kind === 'asset') ? x.d - x.c : x.c - x.d; };
  const revenue = r2(sum(A.accounts.filter(a => a.kind === 'rev'), a => acctBal(a.code, 'rev')));
  const expAccts = A.accounts.filter(a => a.kind === 'exp' && agg[a.code] && Math.abs(acctBal(a.code, 'exp')) > 0.004).map(a => ({ code: a.code, name: a.name, amt: r2(acctBal(a.code, 'exp')) }));
  const isVarDefault = (code, name) => ['5301', '5302', '5198', '5150', '5199'].includes(code) || /مواد|مشتريات|بضاعة|خامات|طعام/.test(name || '');
  const classOf = (a) => ovr[a.code] || (isVarDefault(a.code, a.name) ? 'variable' : 'fixed');
  const variableTotal = r2(sum(expAccts.filter(a => classOf(a) === 'variable'), a => a.amt));
  const fixedTotal = r2(sum(expAccts.filter(a => classOf(a) === 'fixed'), a => a.amt));
  const totalCost = r2(variableTotal + fixedTotal);
  const profit = r2(revenue - totalCost);
  const cm = r2(revenue - variableTotal);
  const cmRatio = revenue > 0.004 ? cm / revenue : 0;
  const breakEven = cmRatio > 0.0001 ? r2(fixedTotal / cmRatio) : 0;
  const days = Number(daysStr) || 30;
  const breakEvenDay = days > 0 ? r2(breakEven / days) : 0;
  const marginSafety = revenue > 0.004 ? r2((revenue - breakEven) / revenue * 100) : 0;
  const commissions = r2(acctBal('5301', 'exp') + acctBal('5302', 'exp'));
  const labor = r2(acctBal('5201', 'exp') + acctBal('5202', 'exp'));
  const food = r2(variableTotal - commissions);
  const foodPct = revenue > 0.004 ? r2(food / revenue * 100) : 0;
  const laborPct = revenue > 0.004 ? r2(labor / revenue * 100) : 0;
  const primePct = r2(foodPct + laborPct);
  const monName = (() => { try { return new Date(month + '-01').toLocaleDateString('ar-EG', { month: 'long', year: 'numeric' }); } catch { return month; } })();

  const hi = Math.max(revenue, breakEven, 1000) * 1.5;
  const varRatio = revenue > 0 ? variableTotal / revenue : 0;
  const chartData = Array.from({ length: 6 }, (_, i) => { const s = r2(hi * i / 5); return { s: short(s), 'الإيراد': s, 'التكلفة الكلية': r2(fixedTotal + varRatio * s) }; });

  const toggle = (code) => setOvr(o => ({ ...o, [code]: (o[code] || (isVarDefault(code, (expAccts.find(x => x.code === code) || {}).name) ? 'variable' : 'fixed')) === 'variable' ? 'fixed' : 'variable' }));
  const saveClass = async () => { await commitOrg(d => ({ ...d, costClass: ovr, beCfg: { days } }), { actionType: 'update', targetType: 'tax_settings', targetId: 'costClass', title: 'حفظ تصنيف التكاليف (التعادل)', details: 'أيام التشغيل ' + days }); say('حُفظ التصنيف ✓'); };
  const beRows = () => [['المؤشر', 'القيمة'], ['الشهر', monName], ['الإيراد', revenue], ['التكاليف المتغيرة', variableTotal], ['التكاليف الثابتة', fixedTotal], ['هامش المساهمة', cm], ['نسبة هامش المساهمة %', r2(cmRatio * 100)], ['نقطة التعادل (شهري)', breakEven], ['نقطة التعادل (يومي)', breakEvenDay], ['هامش الأمان %', marginSafety], ['الربح الحالي', profit], ['تكلفة الطعام %', foodPct], ['تكلفة العمالة %', laborPct], ['التكلفة الأولية %', primePct]];
  const exportBE = () => { try { const blob = makeXlsx([{ name: 'تحليل التعادل', rows: beRows() }, { name: 'تصنيف التكاليف', rows: [['الحساب', 'المبلغ', 'التصنيف'], ...expAccts.map(a => [a.name, a.amt, classOf(a) === 'variable' ? 'متغيّر' : 'ثابت'])] }]); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'تحليل_التعادل_' + month + '.xlsx'; document.body.appendChild(a); a.click(); document.body.removeChild(a); setTimeout(() => URL.revokeObjectURL(url), 1500); say('نُزّل تحليل التعادل (Excel) ✓'); } catch (e) { say('تعذّر توليد Excel', 'no'); } };

  return (
    <div className="grid" style={{ gap: 14 }}>
      <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 10 }}>
        <div>
          <h2 style={{ fontSize: 17 }}>تحليل التعادل وتكلفة الطعام</h2>
          <div style={{ fontSize: 12, color: 'var(--dim)' }}>كم مبيعات تحتاج لتغطية تكاليفك؟ ونِسَب تكلفة الطعام والعمالة — من أرقام {monName}</div>
        </div>
        <div className="row" style={{ gap: 8, flexWrap: 'wrap' }}>
          <input type="month" className="inp" style={{ width: 'auto' }} value={month} onChange={e => setMonth(e.target.value)} />
          <button className="btn sm" onClick={exportBE}><Download size={13} />Excel</button>
        </div>
      </div>

      {revenue <= 0.004 ? <div className="card"><div className="empty">لا إيراد مسجّل في {monName} — اختر شهرًا فيه إغلاقات معتمدة.</div></div> : <>
        <div className="grid g4">
          <Kpi label="نقطة التعادل (شهري)" value={money(breakEven)} sub={cmRatio > 0 ? 'لتغطية التكاليف الثابتة' : 'المتغيّر ≥ الإيراد!'} icon={Scale} color="#C8A24A" />
          <Kpi label="نقطة التعادل (يومي)" value={money(breakEvenDay)} sub={days + ' يوم تشغيل'} icon={CalendarDays} color="#5B93C4" />
          <Kpi label="هامش الأمان" value={marginSafety.toFixed(1) + '%'} sub={marginSafety >= 0 ? 'فوق التعادل' : 'تحت التعادل — خطر' } icon={ShieldCheck} color={marginSafety >= 20 ? '#4FB286' : marginSafety >= 0 ? '#E0A458' : '#D9544D'} />
          <Kpi label="الربح الحالي للشهر" value={money(profit)} sub={'هامش ' + (revenue > 0 ? r2(profit / revenue * 100) : 0) + '%'} icon={TrendingUp} color={profit >= 0 ? '#4FB286' : '#D9544D'} />
        </div>

        <div className="grid g3">
          <Kpi label="تكلفة الطعام / المواد" value={foodPct.toFixed(1) + '%'} sub={money(food) + ' من الإيراد' + (foodPct > 35 ? ' · مرتفعة' : '')} icon={Store} color={foodPct <= 35 ? '#4FB286' : '#E0A458'} />
          <Kpi label="تكلفة العمالة" value={laborPct.toFixed(1) + '%'} sub={money(labor) + ' رواتب وتأمينات'} icon={Users} color={laborPct <= 30 ? '#4FB286' : '#E0A458'} />
          <Kpi label="التكلفة الأولية (طعام + عمالة)" value={primePct.toFixed(1) + '%'} sub={primePct <= 60 ? 'ضمن المستهدف (≤60٪)' : 'أعلى من المستهدف'} icon={Landmark} color={primePct <= 60 ? '#4FB286' : primePct <= 65 ? '#E0A458' : '#D9544D'} />
        </div>

        <div className="card">
          <div className="card-t" style={{ marginBottom: 14 }}><Scale size={15} color="var(--brass)" />رسم التعادل — تلتقي التكلفة الكلية مع الإيراد عند نقطة التعادل</div>
          <div style={{ height: 250, direction: 'ltr' }}>
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={chartData} margin={{ top: 6, right: 10, left: -12, bottom: 0 }}>
                <CartesianGrid stroke={tn.grid} vertical={false} />
                <XAxis dataKey="s" tick={{ fill: tn.tick, fontSize: 9.5 }} axisLine={false} tickLine={false} />
                <YAxis tick={{ fill: tn.tick, fontSize: 10 }} axisLine={false} tickLine={false} tickFormatter={short} />
                <Tooltip contentStyle={{ background: tn.tip, border: '1px solid ' + tn.grid, borderRadius: 10, fontSize: 12, direction: 'rtl', color: tn.tipTxt }} formatter={(v, n) => [money(v), n]} />
                <Line type="monotone" dataKey="الإيراد" stroke={tn.pos} strokeWidth={2.2} dot={false} />
                <Line type="monotone" dataKey="التكلفة الكلية" stroke={tn.warn} strokeWidth={2.2} dot={false} />
              </LineChart>
            </ResponsiveContainer>
          </div>
          <div className="row" style={{ gap: 14, fontSize: 11, justifyContent: 'center', marginTop: 6 }}>
            <span className="row" style={{ gap: 5 }}><span style={{ width: 11, height: 3, background: '#4FB286', display: 'inline-block' }} />الإيراد</span>
            <span className="row" style={{ gap: 5 }}><span style={{ width: 11, height: 3, background: '#E0A458', display: 'inline-block' }} />التكلفة الكلية (ثابت + متغيّر)</span>
          </div>
        </div>

        <div className="card">
          <div className="card-h">
            <div className="card-t"><FileText size={15} color="var(--brass)" />تصنيف التكاليف — اضغط لتبديل ثابت/متغيّر</div>
            <div className="row" style={{ gap: 8, alignItems: 'flex-end' }}>
              <Field label="أيام التشغيل/شهر" style={{ width: 120 }}><input className="inp n" inputMode="decimal" value={daysStr} onChange={e => setDaysStr(e.target.value.replace(/[^\d.]/g, ''))} /></Field>
              {canPost && <button className="btn sm pri" onClick={saveClass}><Check size={14} />حفظ التصنيف</button>}
            </div>
          </div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>حساب المصروف</th><th style={{ textAlign: 'end' }}>المبلغ ({monName})</th><th style={{ textAlign: 'center' }}>التصنيف</th></tr></thead>
              <tbody>
                {expAccts.map(a => (
                  <tr key={a.code}>
                    <td style={{ fontSize: 12.5 }}>{a.name}</td>
                    <td className="num" style={{ textAlign: 'end' }}>{money(a.amt)}</td>
                    <td style={{ textAlign: 'center' }}>
                      <button className={'btn sm ' + (classOf(a) === 'variable' ? 'pri' : 'gh')} onClick={() => canPost && toggle(a.code)} disabled={!canPost}>{classOf(a) === 'variable' ? 'متغيّر' : 'ثابت'}</button>
                    </td>
                  </tr>
                ))}
                {expAccts.length === 0 && <tr><td colSpan={3}><div className="empty">لا مصروفات في هذا الشهر.</div></td></tr>}
                <tr style={{ fontWeight: 800, background: 'rgba(200,162,74,.05)' }}>
                  <td>الإجمالي — متغيّر {money(variableTotal)} · ثابت {money(fixedTotal)}</td>
                  <td className="num" style={{ textAlign: 'end' }}>{money(totalCost)}</td><td />
                </tr>
              </tbody>
            </table>
          </div>
        </div>

        <div className="note">
          <b>كيف تُقرأ؟</b> نقطة التعادل = التكاليف الثابتة ÷ نسبة هامش المساهمة (١ − نسبة التكاليف المتغيّرة). فوقها تربح، وتحتها تخسر.
          <b> التكلفة الأولية</b> (طعام + عمالة) أهم مؤشر مطاعم — استهدِفها ≤ ٦٠٪. المبدئيات: العمولات والمواد <b>متغيّرة</b>، والرواتب والإيجار والإهلاك <b>ثابتة</b> — بدّل أيّها بضغطة واحفظ. الأرقام من قيود الشهر المختار.
        </div>
      </>}
    </div>
  );
}

/* ============================================================
   v11.9 — تحليلات النمو والمقارنة السنوية
   عدسة تحليلية جديدة: النمو عبر الزمن (سنة بسنة · شهر بشهر) — تختلف عن
   «مقارنة الفروع» (لقطة يوم واحد) وعن «التحليل والنِسَب». تُشتق من الإغلاقات
   المعتمدة ضمن نطاق المستخدم، بلا أي افتراض — تظهر فقط ما سُجّل فعلًا.
   ============================================================ */
const GROWTH_MONTHS = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];
function GrowthAnalytics({ org, ops, me, myBranches, scoped, setTab, theme, say }) {
  const tn = chartTone(theme);
  const r2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
  const counted = useMemo(() => (scoped.closings || []).filter(countedClosing), [scoped]);

  // تجميع شهري: 'YYYY-MM' → {rev, exp, net, n}
  const monthly = useMemo(() => {
    const m = {};
    counted.forEach(c => {
      const key = (c.date || '').slice(0, 7); if (key.length !== 7) return;
      const x = m[key] || (m[key] = { rev: 0, exp: 0, n: 0 });
      x.rev += c.totalRevenue || 0; x.exp += c.totalExpenses || 0; x.n += 1;
    });
    Object.values(m).forEach(x => { x.rev = r2(x.rev); x.exp = r2(x.exp); x.net = r2(x.rev - x.exp); });
    return m;
  }, [counted]);

  const years = useMemo(() => { const s = new Set(); Object.keys(monthly).forEach(k => s.add(k.slice(0, 4))); return [...s].sort(); }, [monthly]);
  const hasData = years.length > 0;
  const latestYear = hasData ? years[years.length - 1] : String(new Date().getFullYear());
  const [selYear, setSelYear] = useState(latestYear);
  useEffect(() => { if (hasData && !years.includes(selYear)) setSelYear(latestYear); }, [years.join(',')]);

  const yr = years.includes(selYear) ? selYear : latestYear;
  const prevYr = String(Number(yr) - 1);
  const prevYearHasData = years.includes(prevYr);
  const cell = (y, mo) => monthly[y + '-' + String(mo).padStart(2, '0')];
  const monRev = (y, mo) => (cell(y, mo) || {}).rev || 0;
  const hasMon = (y, mo) => !!cell(y, mo);

  // نمو %: يعالج القسمة على صفر و«الجديد»
  const gpct = (cur, prev) => {
    if (prev > 0.005) { const v = r2((cur - prev) / prev * 100); return { txt: (v >= 0 ? '+' : '') + v.toFixed(1) + '%', up: v >= 0, has: true }; }
    if (cur > 0.005) return { txt: 'جديد', up: true, has: false };
    return { txt: '—', up: true, has: false };
  };

  // آخر شهر فيه بيانات في السنة المختارة (لمقارنة YTD المقابلة)
  let lastMo = 0; for (let mo = 1; mo <= 12; mo++) if (hasMon(yr, mo)) lastMo = mo;
  if (!lastMo) lastMo = 1;
  const ytdCur = r2(sum(Array.from({ length: lastMo }, (_, i) => monRev(yr, i + 1))));
  const ytdPrev = r2(sum(Array.from({ length: lastMo }, (_, i) => monRev(prevYr, i + 1))));
  const ytdG = gpct(ytdCur, ytdPrev);
  const curMoRev = monRev(yr, lastMo), prevMoRev = monRev(prevYr, lastMo);
  const moG = gpct(curMoRev, prevMoRev);

  const allMonths = Object.entries(monthly).map(([k, v]) => ({ k, rev: v.rev })).sort((a, b) => b.rev - a.rev);
  const bestMo = allMonths[0];
  const moLabel = (k) => k ? (GROWTH_MONTHS[Number(k.slice(5, 7)) - 1] + ' ' + k.slice(0, 4)) : '—';

  const trendData = Object.keys(monthly).sort().map(k => ({ lbl: GROWTH_MONTHS[Number(k.slice(5, 7)) - 1].slice(0, 3) + ' ' + k.slice(2, 4), الإيراد: monthly[k].rev, الصافي: monthly[k].net }));
  const yoyData = Array.from({ length: 12 }, (_, i) => ({ lbl: GROWTH_MONTHS[i].slice(0, 3), [yr]: monRev(yr, i + 1), [prevYr]: monRev(prevYr, i + 1) }));

  const monthlyRows = Array.from({ length: 12 }, (_, i) => {
    const cur = monRev(yr, i + 1), prev = monRev(prevYr, i + 1);
    return { name: GROWTH_MONTHS[i], cur, prev, g: gpct(cur, prev), active: hasMon(yr, i + 1) || hasMon(prevYr, i + 1) };
  });
  const totCur = r2(sum(monthlyRows, r => r.cur)), totPrev = r2(sum(monthlyRows, r => r.prev));
  const totG = gpct(totCur, totPrev);

  const branchGrowth = useMemo(() => (myBranches || []).map(b => {
    const cur = r2(sum(counted.filter(c => c.branchId === b.id && (c.date || '').slice(0, 4) === yr), c => c.totalRevenue || 0));
    const prev = r2(sum(counted.filter(c => c.branchId === b.id && (c.date || '').slice(0, 4) === prevYr), c => c.totalRevenue || 0));
    return { name: b.name, cur, prev, g: gpct(cur, prev) };
  }).filter(x => x.cur > 0.005 || x.prev > 0.005).sort((a, b) => b.cur - a.cur), [myBranches, counted, yr, prevYr]);

  const GBadge = ({ g }) => (<span className="num" style={{ fontWeight: 800, color: !g.has ? 'var(--dim)' : g.up ? 'var(--mint)' : '#D9544D' }}>{g.has ? (g.up ? '▲ ' : '▼ ') : ''}{g.txt}</span>);
  const dlBlob = (name, blob) => { const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = name; document.body.appendChild(a); a.click(); document.body.removeChild(a); setTimeout(() => URL.revokeObjectURL(url), 1500); };

  const printGrowth = () => {
    const mrows = monthlyRows.filter(r => r.active).map(r => `<tr><td>${r.name}</td><td class="n">${money(r.cur)}</td><td class="n">${money(r.prev)}</td><td class="n">${r.g.txt}</td></tr>`).join('');
    const brows = branchGrowth.map(r => `<tr><td>${_xe(r.name)}</td><td class="n">${money(r.cur)}</td><td class="n">${money(r.prev)}</td><td class="n">${r.g.txt}</td></tr>`).join('');
    const body = `
    <div class="box">إجمالي ${yr}: <b>${money(totCur)}</b> · إجمالي ${prevYr}: <b>${money(totPrev)}</b> · النمو السنوي: <b>${totG.txt}</b></div>
    <h3 style="margin:10px 0 4px">المقارنة الشهرية (سنة بسنة)</h3>
    <table><thead><tr><th>الشهر</th><th class="n">${yr}</th><th class="n">${prevYr}</th><th class="n">النمو</th></tr></thead><tbody>${mrows}
    <tr class="tot"><td>الإجمالي</td><td class="n">${money(totCur)}</td><td class="n">${money(totPrev)}</td><td class="n">${totG.txt}</td></tr></tbody></table>
    ${brows ? `<h3 style="margin:14px 0 4px">نمو الفروع (سنة بسنة)</h3><table><thead><tr><th>الفرع</th><th class="n">${yr}</th><th class="n">${prevYr}</th><th class="n">النمو</th></tr></thead><tbody>${brows}</tbody></table>` : ''}`;
    printA4(org, 'تحليلات النمو والمقارنة السنوية', yr + ' مقابل ' + prevYr, body) || say('اسمح بالنوافذ المنبثقة للطباعة', 'no');
  };
  const exportGrowthXlsx = () => {
    try {
      const mh = ['الشهر', yr, prevYr, 'النمو'];
      const mr = monthlyRows.filter(r => r.active).map(r => [r.name, r.cur, r.prev, r.g.txt]);
      mr.push(['الإجمالي', totCur, totPrev, totG.txt]);
      const bh = ['الفرع', yr, prevYr, 'النمو'];
      const br = branchGrowth.map(r => [r.name, r.cur, r.prev, r.g.txt]);
      const blob = makeXlsx([{ name: 'مقارنة شهرية', rows: [mh, ...mr] }, { name: 'نمو الفروع', rows: [bh, ...br] }]);
      dlBlob('تحليلات_النمو_' + yr + '.xlsx', blob);
    } catch (e) { say('تعذّر توليد ملف Excel', 'no'); }
  };

  if (!hasData) return (
    <div className="grid" style={{ gap: 14 }}>
      <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 10 }}>
        <div><h2 style={{ fontSize: 17 }}>تحليلات النمو والمقارنة السنوية</h2>
          <div style={{ fontSize: 12, color: 'var(--dim)' }}>نموّ مبيعاتك عبر الزمن — سنة بسنة وشهر بشهر</div></div>
      </div>
      <div className="card"><div className="empty">لا توجد إغلاقات معتمدة بعد — تظهر التحليلات فور اعتماد أول إغلاق يومي.</div></div>
    </div>
  );

  return (
    <div className="grid" style={{ gap: 14 }}>
      <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 10 }}>
        <div>
          <h2 style={{ fontSize: 17 }}>تحليلات النمو والمقارنة السنوية</h2>
          <div style={{ fontSize: 12, color: 'var(--dim)' }}>نموّ مبيعاتك عبر الزمن — سنة بسنة وشهر بشهر (من الإغلاقات المعتمدة)</div>
        </div>
        <div className="row" style={{ gap: 8, flexWrap: 'wrap' }}>
          <select className="inp" style={{ width: 'auto' }} value={yr} onChange={e => setSelYear(e.target.value)}>
            {[...years].reverse().map(y => <option key={y} value={y}>سنة {y}</option>)}
          </select>
          <button className="btn sm" onClick={printGrowth}><Printer size={13} />طباعة</button>
          <button className="btn sm" onClick={exportGrowthXlsx}><Download size={13} />Excel</button>
        </div>
      </div>

      {!prevYearHasData && <div className="note">ℹ️ لا توجد بيانات لسنة {prevYr} للمقارنة الكاملة — تظهر أرقام {yr} واتجاهها، وتكتمل المقارنة السنوية تلقائيًا عند توفّر سنة سابقة.</div>}

      <div className="grid g4">
        <Kpi label={'نمو ' + yr + ' (حتى ' + GROWTH_MONTHS[lastMo - 1] + ')'} value={ytdG.txt} sub={money(ytdCur) + ' مقابل ' + money(ytdPrev)} icon={TrendingUp} color={!ytdG.has ? '#7E7566' : ytdG.up ? '#4FB286' : '#D9544D'} />
        <Kpi label={'نمو شهر ' + GROWTH_MONTHS[lastMo - 1]} value={moG.txt} sub={money(curMoRev) + ' مقابل ' + money(prevMoRev)} icon={CalendarDays} color={!moG.has ? '#7E7566' : moG.up ? '#4FB286' : '#D9544D'} />
        <Kpi label="أعلى شهر مبيعات" value={money(bestMo.rev)} sub={moLabel(bestMo.k)} icon={ArrowUp} color="#C8A24A" />
        <Kpi label={'إجمالي مبيعات ' + yr} value={money(totCur)} sub={lastMo + ' من ٱثنَي عشر شهرًا مسجّلة'} icon={BarChart3} color="#5B93C4" />
      </div>

      <div className="card">
        <div className="card-t" style={{ marginBottom: 14 }}><TrendingUp size={15} color="var(--brass)" />اتجاه المبيعات والصافي الشهري</div>
        <div style={{ height: 240, direction: 'ltr' }}>
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={trendData} margin={{ top: 6, right: 8, left: -14, bottom: 0 }}>
              <CartesianGrid stroke={tn.grid} vertical={false} />
              <XAxis dataKey="lbl" tick={{ fill: tn.tick, fontSize: 9.5 }} axisLine={false} tickLine={false} />
              <YAxis tick={{ fill: tn.tick, fontSize: 10 }} axisLine={false} tickLine={false} tickFormatter={short} />
              <Tooltip contentStyle={{ background: tn.tip, border: '1px solid ' + tn.grid, borderRadius: 10, fontSize: 12, direction: 'rtl', color: tn.tipTxt }} labelStyle={{ color: '#A2968A' }} formatter={(v, n) => [money(v), n]} />
              <Line type="monotone" dataKey="الإيراد" stroke={tn.accent} strokeWidth={2.4} dot={{ r: 2 }} />
              <Line type="monotone" dataKey="الصافي" stroke={tn.pos} strokeWidth={1.8} dot={{ r: 2 }} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="card">
        <div className="card-h">
          <div className="card-t"><BarChart3 size={15} color="var(--brass)" />المقارنة السنوية شهرًا بشهر</div>
          <div className="row" style={{ gap: 12, fontSize: 11 }}>
            <span className="row" style={{ gap: 5 }}><span style={{ width: 11, height: 11, borderRadius: 3, background: '#C8A24A', display: 'inline-block' }} />{yr}</span>
            <span className="row" style={{ gap: 5 }}><span style={{ width: 11, height: 11, borderRadius: 3, background: '#7E7566', display: 'inline-block' }} />{prevYr}</span>
          </div>
        </div>
        <div style={{ height: 240, direction: 'ltr' }}>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={yoyData} margin={{ top: 6, right: 8, left: -14, bottom: 0 }}>
              <CartesianGrid stroke={tn.grid} vertical={false} />
              <XAxis dataKey="lbl" tick={{ fill: tn.tick, fontSize: 9.5 }} axisLine={false} tickLine={false} />
              <YAxis tick={{ fill: tn.tick, fontSize: 10 }} axisLine={false} tickLine={false} tickFormatter={short} />
              <Tooltip cursor={{ fill: 'rgba(255,255,255,.03)' }} contentStyle={{ background: tn.tip, border: '1px solid ' + tn.grid, borderRadius: 10, fontSize: 12, direction: 'rtl', color: tn.tipTxt }} formatter={(v, n) => [money(v), 'سنة ' + n]} />
              <Bar dataKey={yr} fill={tn.accent} radius={[5, 5, 0, 0]} />
              <Bar dataKey={prevYr} fill={tn.muted} radius={[5, 5, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid g2" style={{ alignItems: 'start' }}>
        <div className="card">
          <div className="card-t" style={{ marginBottom: 10 }}><CalendarDays size={15} color="var(--brass)" />المقارنة الشهرية — {yr} مقابل {prevYr}</div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>الشهر</th><th style={{ textAlign: 'end' }}>{yr}</th><th style={{ textAlign: 'end' }}>{prevYr}</th><th style={{ textAlign: 'end' }}>النمو</th></tr></thead>
              <tbody>
                {monthlyRows.filter(r => r.active).map((r, i) => (
                  <tr key={i}>
                    <td>{r.name}</td>
                    <td className="num" style={{ textAlign: 'end' }}>{money(r.cur)}</td>
                    <td className="num" style={{ textAlign: 'end', color: 'var(--dim)' }}>{money(r.prev)}</td>
                    <td className="num" style={{ textAlign: 'end' }}><GBadge g={r.g} /></td>
                  </tr>
                ))}
                <tr style={{ fontWeight: 900, background: 'rgba(200,162,74,.05)' }}>
                  <td>الإجمالي</td>
                  <td className="num" style={{ textAlign: 'end' }}>{money(totCur)}</td>
                  <td className="num" style={{ textAlign: 'end', color: 'var(--dim)' }}>{money(totPrev)}</td>
                  <td className="num" style={{ textAlign: 'end' }}><GBadge g={totG} /></td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>

        <div className="card">
          <div className="card-t" style={{ marginBottom: 10 }}><Store size={15} color="var(--brass)" />نمو الفروع — {yr} مقابل {prevYr}</div>
          {branchGrowth.length ? (
            <div className="tw">
              <table className="tb">
                <thead><tr><th>الفرع</th><th style={{ textAlign: 'end' }}>{yr}</th><th style={{ textAlign: 'end' }}>{prevYr}</th><th style={{ textAlign: 'end' }}>النمو</th></tr></thead>
                <tbody>
                  {branchGrowth.map((r, i) => (
                    <tr key={i}>
                      <td>{r.name}</td>
                      <td className="num" style={{ textAlign: 'end' }}>{money(r.cur)}</td>
                      <td className="num" style={{ textAlign: 'end', color: 'var(--dim)' }}>{money(r.prev)}</td>
                      <td className="num" style={{ textAlign: 'end' }}><GBadge g={r.g} /></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : <div className="empty">لا توجد بيانات فروع كافية للمقارنة.</div>}
        </div>
      </div>

      <div className="note">
        💡 الأرقام مبنيّة على <b>إجمالي إيراد الإغلاقات المعتمدة</b> ضمن نطاقك، مجمّعة شهريًا. «النمو» = تغيّر النسبة عن نفس الفترة من السنة السابقة؛
        يظهر «جديد» حين لا يوجد نظير في السنة السابقة، و«—» حين لا مبيعات في الطرفين.
      </div>
    </div>
  );
}

/* ============================================================
   v12.1 — تعدّد المنشآت/الشركات (اختياري، مطفأ افتراضيًا)
   المنشأة الرئيسية = org.company (كما هي). المنشآت الإضافية في org.entities،
   وكل فرع يُسنَد لمنشأة عبر branch.entityId (فارغ = الرئيسية). بلا منشآت
   إضافية يبقى النظام أحادي المنشأة تمامًا كما كان — توافق رجعي كامل.
   ============================================================ */
function entityList(org) {
  const co = org.company || {};
  const primary = { id: 'primary', name: co.name || 'المنشأة الرئيسية', taxNumber: co.taxNumber || '', commercialReg: co.commercialReg || '', activity: co.activity || '', primary: true };
  return [primary, ...((org.entities || []).map(e => ({ ...e, primary: false })))];
}
function branchEntityId(b) { return (b && b.entityId) ? b.entityId : 'primary'; }
function entityById(org, id) { const l = entityList(org); return l.find(e => e.id === (id || 'primary')) || l[0]; }
function multiEntityOn(org) { return (org.entities || []).length > 0; }

function EntitiesCenter({ org, ops, me, myBranches, scoped, commitOrg, say }) {
  const r2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
  const admin = !!ROLES[me?.role]?.admin;
  const ents = entityList(org);
  const branches = org.branches || [];
  const counted = (scoped.closings || []).filter(countedClosing);
  const [from, setFrom] = useState(''); const [to, setTo] = useState('');
  const [ef, setEf] = useState(null); // نموذج منشأة (إضافة/تعديل)
  const inP = (d) => (!from || d >= from) && (!to || d <= to);
  const brOfEnt = (eid) => branches.filter(b => branchEntityId(b) === eid);
  const figFor = (eid) => {
    const bids = new Set(brOfEnt(eid).map(b => b.id));
    const cs = counted.filter(c => bids.has(c.branchId) && inP(c.date || ''));
    const rev = r2(sum(cs, c => c.totalRevenue || 0)), exp = r2(sum(cs, c => c.totalExpenses || 0));
    return { nb: brOfEnt(eid).length, n: cs.length, rev, exp, net: r2(rev - exp) };
  };
  const rows = ents.map(e => ({ e, ...figFor(e.id) }));
  const tot = { nb: sum(rows, r => r.nb), rev: r2(sum(rows, r => r.rev)), exp: r2(sum(rows, r => r.exp)), net: r2(sum(rows, r => r.net)) };

  const preset = (kind) => {
    const d = new Date(), y = d.getFullYear(), m = d.getMonth(), iso = (dt) => dt.toISOString().slice(0, 10);
    if (kind === 'month') { setFrom(iso(new Date(y, m, 1))); setTo(iso(new Date(y, m + 1, 0))); }
    else if (kind === 'year') { setFrom(y + '-01-01'); setTo(y + '-12-31'); }
    else { setFrom(''); setTo(''); }
  };

  const saveEnt = async () => {
    const f = ef; if (!f.name.trim()) return say('أدخل اسم المنشأة', 'no');
    if (f.primary) {
      await commitOrg(d => ({ ...d, company: { ...(d.company || {}), name: f.name.trim(), taxNumber: (f.taxNumber || '').trim(), commercialReg: (f.commercialReg || '').trim(), activity: (f.activity || '').trim() } }), { actionType: 'update', targetType: 'entity', targetId: 'primary', title: 'تعديل المنشأة الرئيسية', details: f.name.trim() });
    } else if (f.id) {
      await commitOrg(d => ({ ...d, entities: (d.entities || []).map(e => e.id === f.id ? { ...e, name: f.name.trim(), taxNumber: (f.taxNumber || '').trim(), commercialReg: (f.commercialReg || '').trim(), activity: (f.activity || '').trim() } : e) }), { actionType: 'update', targetType: 'entity', targetId: f.id, title: 'تعديل منشأة', details: f.name.trim() });
    } else {
      const id = 'ent' + Date.now().toString(36);
      await commitOrg(d => ({ ...d, entities: [...(d.entities || []), { id, name: f.name.trim(), taxNumber: (f.taxNumber || '').trim(), commercialReg: (f.commercialReg || '').trim(), activity: (f.activity || '').trim() }] }), { actionType: 'create', targetType: 'entity', targetId: id, title: 'إضافة منشأة', details: f.name.trim() });
    }
    setEf(null);
  };
  const delEnt = async (e) => {
    if (e.primary) return;
    await commitOrg(d => ({ ...d, entities: (d.entities || []).filter(x => x.id !== e.id), branches: (d.branches || []).map(b => branchEntityId(b) === e.id ? { ...b, entityId: '' } : b) }), { actionType: 'delete', targetType: 'entity', targetId: e.id, title: 'حذف منشأة', details: e.name });
  };
  const assignBranch = async (bId, eid) => {
    await commitOrg(d => ({ ...d, branches: (d.branches || []).map(b => b.id === bId ? { ...b, entityId: eid === 'primary' ? '' : eid } : b) }), { actionType: 'update', targetType: 'branch', targetId: bId, title: 'إسناد فرع لمنشأة', details: entityById(org, eid).name });
  };

  return (
    <div className="grid" style={{ gap: 14 }}>
      <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 10 }}>
        <div>
          <h2 style={{ fontSize: 17 }}>مركز المنشآت</h2>
          <div style={{ fontSize: 12, color: 'var(--dim)' }}>أدِر أكثر من منشأة/شركة بأرقام ضريبية وفروع مستقلة — بنظرة موحّدة ولكل منشأة</div>
        </div>
        <div className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
          <input className="inp" style={{ width: 'auto' }} type="date" value={from} onChange={e => setFrom(e.target.value)} />
          <input className="inp" style={{ width: 'auto' }} type="date" value={to} onChange={e => setTo(e.target.value)} />
          <button className="btn sm gh" onClick={() => preset('month')}>هذا الشهر</button>
          <button className="btn sm gh" onClick={() => preset('year')}>هذه السنة</button>
          <button className="btn sm gh" onClick={() => preset('all')}>الكل</button>
        </div>
      </div>

      <div className="grid g3">
        <Kpi label="عدد المنشآت" value={ents.length} sub={multiEntityOn(org) ? (org.entities.length + ' إضافية + الرئيسية') : 'منشأة واحدة (الوضع الافتراضي)'} icon={Building2} color="#C8A24A" />
        <Kpi label="إجمالي الفروع" value={tot.nb} sub="موزّعة على المنشآت" icon={Store} color="#5B93C4" />
        <Kpi label="صافي المجموعة (موحّد)" value={money(tot.net)} sub={(from || to) ? 'للفترة المحددة' : 'كل المدة'} icon={Landmark} color={tot.net >= 0 ? '#4FB286' : '#D9544D'} />
      </div>

      <div className="card">
        <div className="card-t" style={{ marginBottom: 10 }}><Building2 size={15} color="var(--brass)" />النظرة الموحّدة — كل منشأة على حدة</div>
        <div className="tw">
          <table className="tb">
            <thead><tr><th>المنشأة</th><th>الرقم الضريبي</th><th style={{ textAlign: 'center' }}>الفروع</th><th style={{ textAlign: 'end' }}>الإيراد</th><th style={{ textAlign: 'end' }}>المصروفات</th><th style={{ textAlign: 'end' }}>الصافي</th></tr></thead>
            <tbody>
              {rows.map(r => (
                <tr key={r.e.id}>
                  <td>{r.e.name} {r.e.primary && <span className="badge b-brass" style={{ marginInlineStart: 6 }}>الرئيسية</span>}</td>
                  <td className="num" style={{ fontSize: 11, color: r.e.taxNumber ? 'inherit' : 'var(--amber)' }}>{r.e.taxNumber || 'غير محدّد'}</td>
                  <td className="num" style={{ textAlign: 'center' }}>{r.nb}</td>
                  <td className="num" style={{ textAlign: 'end' }}>{money(r.rev)}</td>
                  <td className="num" style={{ textAlign: 'end' }}>{money(r.exp)}</td>
                  <td className="num" style={{ textAlign: 'end', color: r.net >= 0 ? 'var(--mint)' : '#D9544D' }}>{money(r.net)}</td>
                </tr>
              ))}
              <tr style={{ fontWeight: 900, background: 'rgba(200,162,74,.05)' }}>
                <td>الإجمالي الموحّد</td><td /><td className="num" style={{ textAlign: 'center' }}>{tot.nb}</td>
                <td className="num" style={{ textAlign: 'end' }}>{money(tot.rev)}</td>
                <td className="num" style={{ textAlign: 'end' }}>{money(tot.exp)}</td>
                <td className="num" style={{ textAlign: 'end', color: 'var(--brass-l)' }}>{money(tot.net)}</td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>

      {admin ? (
        <div className="grid g2" style={{ alignItems: 'start' }}>
          <div className="card">
            <div className="card-h">
              <div className="card-t"><Building2 size={15} color="var(--brass)" />المنشآت</div>
              <button className="btn sm pri" onClick={() => setEf({ name: '', taxNumber: '', commercialReg: '', activity: '' })}><Plus size={14} />منشأة جديدة</button>
            </div>
            {ents.map(e => (
              <div key={e.id} className="row" style={{ justifyContent: 'space-between', alignItems: 'center', padding: '8px 0', borderBottom: '1px solid var(--frame-o)' }}>
                <div>
                  <div style={{ fontWeight: 700 }}>{e.name} {e.primary && <span className="badge b-brass" style={{ marginInlineStart: 6 }}>الرئيسية</span>}</div>
                  <div style={{ fontSize: 11, color: 'var(--dim)' }}>ض: {e.taxNumber || '—'} · س.ت: {e.commercialReg || '—'}</div>
                </div>
                <div className="row" style={{ gap: 6 }}>
                  <button className="btn sm gh" onClick={() => setEf({ ...e })}><Settings size={13} /></button>
                  {!e.primary && <button className="btn sm gh" onClick={() => delEnt(e)}><Trash2 size={13} /></button>}
                </div>
              </div>
            ))}
          </div>

          <div className="card">
            <div className="card-t" style={{ marginBottom: 10 }}><Store size={15} color="var(--brass)" />إسناد الفروع للمنشآت</div>
            {branches.length ? branches.map(b => (
              <div key={b.id} className="row" style={{ justifyContent: 'space-between', alignItems: 'center', padding: '7px 0', borderBottom: '1px solid var(--frame-o)' }}>
                <span style={{ fontSize: 13 }}>{b.name}</span>
                <select className="inp" style={{ width: 190 }} value={branchEntityId(b)} onChange={e => assignBranch(b.id, e.target.value)}>
                  {ents.map(en => <option key={en.id} value={en.id}>{en.name}{en.primary ? ' (الرئيسية)' : ''}</option>)}
                </select>
              </div>
            )) : <div className="empty">لا فروع بعد.</div>}
          </div>
        </div>
      ) : <div className="note">إدارة المنشآت وإسناد الفروع صلاحية للإدارة العليا/مسؤول النظام. هذه الشاشة لك للعرض الموحّد.</div>}

      {ef && (
        <Modal title={ef.primary ? 'تعديل المنشأة الرئيسية' : ef.id ? 'تعديل منشأة' : 'منشأة جديدة'} icon={Building2} onClose={() => setEf(null)}
          foot={<><button className="btn gh" onClick={() => setEf(null)}>إلغاء</button><button className="btn pri" onClick={saveEnt}><Check size={14} />حفظ</button></>}>
          <div className="grid g2" style={{ gap: 10 }}>
            <Field label="اسم المنشأة"><input className="inp" value={ef.name} onChange={e => setEf({ ...ef, name: e.target.value })} /></Field>
            <Field label="الرقم الضريبي"><input className="inp n" value={ef.taxNumber} placeholder="3xxxxxxxxxxxxx3" onChange={e => setEf({ ...ef, taxNumber: e.target.value })} /></Field>
            <Field label="السجل التجاري"><input className="inp n" value={ef.commercialReg} onChange={e => setEf({ ...ef, commercialReg: e.target.value })} /></Field>
            <Field label="النشاط"><input className="inp" value={ef.activity} onChange={e => setEf({ ...ef, activity: e.target.value })} /></Field>
          </div>
          {ef.primary && <div className="note" style={{ marginTop: 10 }}>هذه بيانات منشأتك الرئيسية (تُستخدم في الفواتير والتقارير) — تعديلها هنا يعدّل «بيانات الشركة».</div>}
        </Modal>
      )}

      <div className="note">💡 المنشأة الرئيسية هي منشأتك الحالية بلا أي تغيير. أضِف منشأة فقط إن كنت تدير أكثر من كيان قانوني؛ عندها تظهر خيارات المنشأة في <b>فاتورة زاتكا</b> و<b>منشئ التقارير</b>. الفروع غير المُسندة تبقى ضمن الرئيسية.</div>
    </div>
  );
}

/* ============================================================
   v12.0 — منشئ التقارير المخصّصة
   تقرير يبنيه المستخدم بنفسه: مصدر (إغلاقات/مصروفات/أرصدة) + فترة + فرع +
   تجميع + اختيار أعمدة + فرز، مع حفظ قوالب وإعادة استخدامها وطباعة/Excel/CSV.
   يُشتق من البيانات المعتمدة نفسها — لا تخزين مزدوج ولا افتراض.
   ============================================================ */
const RB_SOURCES = {
  closings: {
    ar: 'المبيعات والإغلاقات',
    groups: [['none', 'كل إغلاق'], ['branch', 'حسب الفرع'], ['month', 'حسب الشهر'], ['day', 'حسب اليوم']],
    cols: [
      { k: 'date', ar: 'التاريخ', num: false }, { k: 'branch', ar: 'الفرع', num: false },
      { k: 'rev', ar: 'الإيراد', num: true }, { k: 'exp', ar: 'المصروفات', num: true }, { k: 'net', ar: 'الصافي', num: true },
      { k: 'cash', ar: 'النقد', num: true }, { k: 'card', ar: 'الشبكة', num: true }, { k: 'delivery', ar: 'التوصيل', num: true },
      { k: 'variance', ar: 'فرق الصندوق', num: true }, { k: 'count', ar: 'عدد الإغلاقات', num: true }
    ],
    dflt: ['date', 'branch', 'rev', 'exp', 'net']
  },
  expenses: {
    ar: 'المصروفات',
    groups: [['none', 'كل بند'], ['category', 'حسب البند'], ['branch', 'حسب الفرع'], ['month', 'حسب الشهر']],
    cols: [
      { k: 'date', ar: 'التاريخ', num: false }, { k: 'branch', ar: 'الفرع', num: false }, { k: 'category', ar: 'البند', num: false },
      { k: 'beneficiary', ar: 'المستفيد', num: false }, { k: 'method', ar: 'طريقة الدفع', num: false },
      { k: 'amount', ar: 'المبلغ', num: true }, { k: 'count', ar: 'عدد البنود', num: true }
    ],
    dflt: ['date', 'branch', 'category', 'amount']
  },
  balances: {
    ar: 'أرصدة الحسابات',
    groups: [['none', 'كل حساب'], ['kind', 'حسب النوع']],
    cols: [
      { k: 'code', ar: 'الكود', num: false }, { k: 'name', ar: 'الحساب', num: false }, { k: 'kind', ar: 'النوع', num: false },
      { k: 'debit', ar: 'مدين', num: true }, { k: 'credit', ar: 'دائن', num: true }, { k: 'balance', ar: 'الرصيد', num: true }
    ],
    dflt: ['code', 'name', 'kind', 'balance']
  }
};
const RB_KIND_AR = { asset: 'أصول', liab: 'التزامات', equity: 'حقوق ملكية', rev: 'إيرادات', exp: 'مصروفات' };
const RB_PM_AR = { cash: 'نقدًا', card: 'شبكة', deferred: 'آجل', credit: 'آجل', cheque: 'شيك', bank_transfer: 'تحويل' };
function ReportBuilder({ org, ops, me, myBranches, scoped, commitOrg, say, theme }) {
  const r2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
  const [cfg, setCfg] = useState({ source: 'closings', from: '', to: '', branch: '', entity: '', groupBy: 'none', cols: RB_SOURCES.closings.dflt.slice(), sortBy: '', sortDir: 'desc' });
  const [tplName, setTplName] = useState('');
  const S = RB_SOURCES[cfg.source];
  const set = (patch) => setCfg(c => ({ ...c, ...patch }));
  const setSource = (src) => setCfg(c => ({ ...c, source: src, groupBy: 'none', cols: RB_SOURCES[src].dflt.slice(), sortBy: '' }));
  const toggleCol = (k) => setCfg(c => ({ ...c, cols: c.cols.includes(k) ? c.cols.filter(x => x !== k) : [...c.cols, k] }));
  const canManage = rolePost(me?.role);  // v15.11: منع «عرض فقط» (مراجع) من حفظ/حذف قوالب التقارير

  const A = useMemo(() => buildAccounting(org, ops), [org, ops]);
  const counted = useMemo(() => (scoped.closings || []).filter(countedClosing), [scoped]);
  const inP = (d) => (!cfg.from || d >= cfg.from) && (!cfg.to || d <= cfg.to);
  const brOk = (bid) => !cfg.branch ? true : cfg.branch === 'central' ? !bid : bid === cfg.branch;
  const brName = (bid) => (myBranches.find(b => b.id === bid) || {}).name || (bid ? '—' : 'المركز الرئيسي');
  const rbEntMap = {}; (org.branches || []).forEach(b => rbEntMap[b.id] = branchEntityId(b));
  const entOk = (bid) => !cfg.entity ? true : rbEntMap[bid] === cfg.entity;
  const rbMulti = multiEntityOn(org);

  const records = useMemo(() => {
    if (cfg.source === 'closings') {
      return counted.filter(c => inP(c.date || '') && brOk(c.branchId) && entOk(c.branchId)).map(c => ({
        date: c.date, branch: c.branchName || brName(c.branchId),
        rev: r2(c.totalRevenue), exp: r2(c.totalExpenses), net: r2((c.totalRevenue || 0) - (c.totalExpenses || 0)),
        cash: r2(c.cashSales), card: r2(c.cardSales), delivery: r2(sum(c.deliverySales || [], s => s.amount || 0)),
        variance: r2(c.variance), count: 1
      }));
    }
    if (cfg.source === 'expenses') {
      const out = [];
      counted.filter(c => inP(c.date || '') && brOk(c.branchId) && entOk(c.branchId)).forEach(c => (c.expenses || []).forEach(e => {
        if (!((e.amount || 0) > 0)) return;
        out.push({ date: c.date, branch: c.branchName || brName(c.branchId), category: e.categoryName || 'مصروف', beneficiary: e.beneficiaryName || '—', method: RB_PM_AR[e.paymentMethod] || e.paymentMethod || '—', amount: r2(e.amount), count: 1 });
      }));
      return out;
    }
    const acc = {}; A.accounts.forEach(a => acc[a.code] = { code: a.code, name: a.name, kind: a.kind, d: 0, c: 0 });
    A.entries.forEach(e => { if (!inP(e.date || '')) return; if (!brOk(e.branchId)) return; if (!entOk(e.branchId)) return; e.lines.forEach(l => { const x = acc[l.code]; if (x) { x.d += l.debit; x.c += l.credit; } }); });
    return Object.values(acc).map(a => ({ code: a.code, name: a.name, kind: RB_KIND_AR[a.kind] || a.kind, debit: r2(a.d), credit: r2(a.c), balance: r2((a.kind === 'asset' || a.kind === 'exp') ? a.d - a.c : a.c - a.d) }))
      .filter(x => Math.abs(x.debit) > 0.004 || Math.abs(x.credit) > 0.004);
  }, [cfg.source, cfg.from, cfg.to, cfg.branch, cfg.entity, counted, A]);

  const grouped = useMemo(() => {
    if (cfg.groupBy === 'none') return records;
    const keyOf = (r) => cfg.groupBy === 'branch' ? r.branch : cfg.groupBy === 'month' ? (r.date || '').slice(0, 7) : cfg.groupBy === 'day' ? r.date : cfg.groupBy === 'category' ? r.category : cfg.groupBy === 'kind' ? r.kind : '';
    const numCols = S.cols.filter(c => c.num).map(c => c.k);
    const map = {};
    records.forEach(r => { const k = keyOf(r) || '—'; const g = map[k] || (map[k] = { __group: k }); numCols.forEach(nc => { g[nc] = r2((g[nc] || 0) + (r[nc] || 0)); }); });
    return Object.values(map);
  }, [records, cfg.groupBy]);

  const isGroup = cfg.groupBy !== 'none';
  const visCols = isGroup
    ? [{ k: '__group', ar: (S.groups.find(g => g[0] === cfg.groupBy) || [])[1] || 'المجموعة', num: false }, ...S.cols.filter(c => c.num && cfg.cols.includes(c.k))]
    : S.cols.filter(c => cfg.cols.includes(c.k));

  const rows = useMemo(() => {
    const arr = grouped.slice();
    if (cfg.sortBy) {
      const col = visCols.find(c => c.k === cfg.sortBy);
      const numeric = col && col.num;
      arr.sort((a, b) => numeric ? (cfg.sortDir === 'asc' ? 1 : -1) * ((a[cfg.sortBy] || 0) - (b[cfg.sortBy] || 0)) : (cfg.sortDir === 'asc' ? 1 : -1) * String(a[cfg.sortBy] == null ? '' : a[cfg.sortBy]).localeCompare(String(b[cfg.sortBy] == null ? '' : b[cfg.sortBy]), 'ar'));
    }
    return arr;
  }, [grouped, cfg.sortBy, cfg.sortDir, cfg.cols.join(','), cfg.groupBy]);

  const totals = {}; visCols.forEach(c => { if (c.num) totals[c.k] = r2(sum(rows, r => r[c.k] || 0)); });

  const preset = (kind) => {
    const d = new Date(), y = d.getFullYear(), m = d.getMonth(), iso = (dt) => dt.toISOString().slice(0, 10);
    if (kind === 'month') set({ from: iso(new Date(y, m, 1)), to: iso(new Date(y, m + 1, 0)) });
    else if (kind === 'quarter') { const qs = Math.floor(m / 3) * 3; set({ from: iso(new Date(y, qs, 1)), to: iso(new Date(y, qs + 3, 0)) }); }
    else if (kind === 'year') set({ from: y + '-01-01', to: y + '-12-31' });
    else if (kind === 'lastyear') set({ from: (y - 1) + '-01-01', to: (y - 1) + '-12-31' });
    else set({ from: '', to: '' });
  };

  const templates = org.reportTemplates || [];
  const saveTpl = async () => {
    const nm = tplName.trim(); if (!nm) return say('أدخل اسمًا للقالب', 'no');
    const id = 'rt' + Date.now().toString(36);
    await commitOrg(d => ({ ...d, reportTemplates: [...(d.reportTemplates || []).filter(t => t.name !== nm), { id, name: nm, cfg: { ...cfg } }] }), { actionType: 'create', targetType: 'report_template', targetId: id, need: 'post', title: 'حفظ قالب تقرير', details: nm });
    setTplName(''); say('حُفظ القالب «' + nm + '»', 'ok');
  };
  const loadTpl = (t) => setCfg({ source: 'closings', from: '', to: '', branch: '', entity: '', groupBy: 'none', cols: [], sortBy: '', sortDir: 'desc', ...t.cfg, cols: (t.cfg.cols || []).slice() });
  const delTpl = async (t) => { await commitOrg(d => ({ ...d, reportTemplates: (d.reportTemplates || []).filter(x => x.id !== t.id) }), { actionType: 'delete', targetType: 'report_template', targetId: t.id, need: 'post', title: 'حذف قالب تقرير', details: t.name }); };

  const dlBlob = (name, blob) => { const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = name; document.body.appendChild(a); a.click(); document.body.removeChild(a); setTimeout(() => URL.revokeObjectURL(url), 1500); };
  const csvCell = (v) => { const s = String(v == null ? '' : v); return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
  const matrix = () => {
    const head = visCols.map(c => c.ar);
    const body = rows.map(r => visCols.map(c => c.num ? (r[c.k] || 0) : (r[c.k] != null ? r[c.k] : '')));
    const tot = visCols.map((c, i) => i === 0 ? 'الإجمالي' : (c.num ? totals[c.k] : ''));
    return { head, body, tot };
  };
  const subLine = () => S.ar + ((cfg.from || cfg.to) ? ' · ' + (cfg.from || 'البداية') + ' → ' + (cfg.to || 'النهاية') : ' · كل المدة') + (cfg.entity ? ' · ' + entityById(org, cfg.entity).name : '') + (cfg.branch ? ' · ' + (cfg.branch === 'central' ? 'المركز الرئيسي' : brName(cfg.branch)) : ' · كل الفروع') + (isGroup ? ' · ' + visCols[0].ar : '');
  const exportCsv = () => { const { head, body, tot } = matrix(); dlBlob('تقرير_مخصص.csv', new Blob(['﻿' + [head, ...body, tot].map(r => r.map(csvCell).join(',')).join('\r\n')], { type: 'text/csv;charset=utf-8' })); };
  const exportXlsx = () => { try { const { head, body, tot } = matrix(); dlBlob('تقرير_مخصص.xlsx', makeXlsx([{ name: S.ar.slice(0, 28), rows: [head, ...body, tot] }])); } catch (e) { say('تعذّر توليد Excel', 'no'); } };
  const printRep = () => {
    if (!visCols.length) return say('اختر عمودًا واحدًا على الأقل', 'no');
    const { head, body, tot } = matrix();
    const th = head.map(h => `<th>${_xe(h)}</th>`).join('');
    const trs = body.map(r => '<tr>' + r.map((v, i) => `<td class="${visCols[i].num ? 'n' : ''}">${visCols[i].num ? money(v) : _xe(v)}</td>`).join('') + '</tr>').join('');
    const trTot = '<tr class="tot">' + tot.map((v, i) => `<td class="${visCols[i].num ? 'n' : ''}">${visCols[i].num ? money(v) : _xe(v)}</td>`).join('') + '</tr>';
    printA4(org, 'تقرير مخصّص — ' + S.ar, subLine(), `<table><thead><tr>${th}</tr></thead><tbody>${trs}${trTot}</tbody></table>`) || say('اسمح بالنوافذ المنبثقة للطباعة', 'no');
  };

  const branchOpts = [{ v: '', ar: 'كل الفروع' }, { v: 'central', ar: 'المركز الرئيسي' }, ...myBranches.map(b => ({ v: b.id, ar: b.name }))];

  return (
    <div className="grid" style={{ gap: 14 }}>
      <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 10 }}>
        <div>
          <h2 style={{ fontSize: 17 }}>منشئ التقارير المخصّصة</h2>
          <div style={{ fontSize: 12, color: 'var(--dim)' }}>ابنِ تقريرك بنفسك — اختر المصدر والفترة والأعمدة والتجميع، ثم اطبع أو صدّر</div>
        </div>
      </div>

      <div className="card">
        <div className="card-t" style={{ marginBottom: 10 }}><Settings size={15} color="var(--brass)" />إعداد التقرير</div>

        <div style={{ fontSize: 11, color: 'var(--dim)', marginBottom: 6 }}>مصدر البيانات</div>
        <div className="row" style={{ gap: 8, flexWrap: 'wrap', marginBottom: 12 }}>
          {Object.entries(RB_SOURCES).map(([k, v]) => <button key={k} className={'btn sm' + (cfg.source === k ? ' pri' : ' gh')} onClick={() => setSource(k)}>{v.ar}</button>)}
        </div>

        <div className="grid g3" style={{ gap: 10, marginBottom: 12 }}>
          <Field label="من تاريخ"><input className="inp" type="date" value={cfg.from} onChange={e => set({ from: e.target.value })} /></Field>
          <Field label="إلى تاريخ"><input className="inp" type="date" value={cfg.to} onChange={e => set({ to: e.target.value })} /></Field>
          <Field label="الفرع"><select className="inp" value={cfg.branch} onChange={e => set({ branch: e.target.value })}>{branchOpts.map(o => <option key={o.v} value={o.v}>{o.ar}</option>)}</select></Field>
          {rbMulti && <Field label="المنشأة"><select className="inp" value={cfg.entity} onChange={e => set({ entity: e.target.value })}><option value="">كل المنشآت</option>{entityList(org).map(en => <option key={en.id} value={en.id}>{en.name}</option>)}</select></Field>}
        </div>
        <div className="row" style={{ gap: 6, flexWrap: 'wrap', marginBottom: 12 }}>
          {[['month', 'هذا الشهر'], ['quarter', 'هذا الربع'], ['year', 'هذه السنة'], ['lastyear', 'السنة الماضية'], ['all', 'كل المدة']].map(pz => <button key={pz[0]} className="btn sm gh" onClick={() => preset(pz[0])}>{pz[1]}</button>)}
        </div>

        <div className="grid g2" style={{ gap: 12 }}>
          <div>
            <div style={{ fontSize: 11, color: 'var(--dim)', marginBottom: 6 }}>التجميع</div>
            <div className="row" style={{ gap: 8, flexWrap: 'wrap' }}>
              {S.groups.map(g => <button key={g[0]} className={'btn sm' + (cfg.groupBy === g[0] ? ' pri' : ' gh')} onClick={() => set({ groupBy: g[0] })}>{g[1]}</button>)}
            </div>
          </div>
          <div>
            <div style={{ fontSize: 11, color: 'var(--dim)', marginBottom: 6 }}>الفرز</div>
            <div className="row" style={{ gap: 8 }}>
              <select className="inp" style={{ flex: 1 }} value={cfg.sortBy} onChange={e => set({ sortBy: e.target.value })}>
                <option value="">— بلا فرز —</option>
                {visCols.map(c => <option key={c.k} value={c.k}>{c.ar}</option>)}
              </select>
              <button className="btn sm gh" onClick={() => set({ sortDir: cfg.sortDir === 'asc' ? 'desc' : 'asc' })} title="اتجاه الفرز">{cfg.sortDir === 'asc' ? <ArrowUp size={14} /> : <ArrowDown size={14} />}</button>
            </div>
          </div>
        </div>

        <div style={{ fontSize: 11, color: 'var(--dim)', margin: '12px 0 6px' }}>الأعمدة {isGroup && <span>(عند التجميع تُجمَع الأعمدة الرقمية المختارة)</span>}</div>
        <div className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
          {S.cols.map(c => <button key={c.k} className={'btn sm' + (cfg.cols.includes(c.k) ? ' pri' : ' gh')} onClick={() => toggleCol(c.k)}>{cfg.cols.includes(c.k) ? '✓ ' : ''}{c.ar}</button>)}
        </div>
      </div>

      <div className="card">
        <div className="card-h">
          <div className="card-t"><Stamp size={15} color="var(--brass)" />قوالب محفوظة</div>
          {canManage && <div className="row" style={{ gap: 8 }}>
            <input className="inp" style={{ width: 180 }} placeholder="اسم القالب" value={tplName} onChange={e => setTplName(e.target.value)} />
            <button className="btn sm pri" onClick={saveTpl}><Plus size={14} />حفظ الإعداد الحالي</button>
          </div>}
        </div>
        {templates.length ? (
          <div className="row" style={{ gap: 8, flexWrap: 'wrap' }}>
            {templates.map(t => (
              <div key={t.id} className="row" style={{ gap: 4, alignItems: 'center', background: 'var(--acc-soft)', border: '1px solid var(--frame-o)', borderRadius: 8, padding: '4px 6px 4px 10px' }}>
                <button className="btn sm gh" onClick={() => loadTpl(t)}><Eye size={13} />{t.name}</button>
                {canManage && <button className="btn sm gh" onClick={() => delTpl(t)} title="حذف"><Trash2 size={12} /></button>}
              </div>
            ))}
          </div>
        ) : <div className="empty" style={{ padding: '14px 10px' }}>لا قوالب محفوظة بعد — اضبط تقريرًا واحفظه لإعادة استخدامه لاحقًا.</div>}
      </div>

      <div className="card">
        <div className="card-h">
          <div className="card-t"><FileText size={15} color="var(--brass)" />النتيجة — {rows.length} سطرًا</div>
          <div className="row" style={{ gap: 8 }}>
            <button className="btn sm" onClick={printRep}><Printer size={13} />طباعة</button>
            <button className="btn sm" onClick={exportXlsx}><Download size={13} />Excel</button>
            <button className="btn sm" onClick={exportCsv}><Download size={13} />CSV</button>
          </div>
        </div>
        <div style={{ fontSize: 11, color: 'var(--dim)', marginBottom: 8 }}>{subLine()}</div>
        {!visCols.length ? <div className="empty">اختر عمودًا واحدًا على الأقل لعرض التقرير.</div>
          : !rows.length ? <div className="empty">لا بيانات مطابقة للمرشّحات الحالية.</div>
            : (
              <div className="tw">
                <table className="tb">
                  <thead><tr>{visCols.map(c => <th key={c.k} style={c.num ? { textAlign: 'end' } : null}>{c.ar}</th>)}</tr></thead>
                  <tbody>
                    {rows.slice(0, 500).map((r, i) => (
                      <tr key={i}>{visCols.map(c => <td key={c.k} className={c.num ? 'num' : ''} style={c.num ? { textAlign: 'end' } : null}>{c.num ? money(r[c.k] || 0) : (r[c.k] != null ? r[c.k] : '—')}</td>)}</tr>
                    ))}
                    <tr style={{ fontWeight: 900, background: 'rgba(200,162,74,.05)' }}>
                      {visCols.map((c, i) => <td key={c.k} className={c.num ? 'num' : ''} style={c.num ? { textAlign: 'end' } : null}>{i === 0 ? 'الإجمالي' : (c.num ? money(totals[c.k] || 0) : '')}</td>)}
                    </tr>
                  </tbody>
                </table>
                {rows.length > 500 && <div className="note" style={{ marginTop: 8 }}>عُرض أول ٥٠٠ سطر — صدّر إلى Excel/CSV لكامل البيانات (الإجمالي أعلاه يشمل كل الأسطر).</div>}
              </div>
            )}
      </div>

      <div className="note">💡 كل الأرقام مشتقّة من بياناتك المعتمدة مباشرةً. «أرصدة الحسابات» تتأثر بالفترة والفرع كميزان مراجعة مصغّر؛ احفظ إعداداتك كقالب لتكرّر التقرير بضغطة.</div>
    </div>
  );
}

/* ============================================================
   v13.8 — نمط المراكز الموحّد (Hub) + تحسين التجربة
   مكوّن واحد عام لكل المراكز: ترويسة «نظرة عامة» (اسم المركز ووصفه) + شريط أقسام،
   يحترم صلاحيات الدور فيعرض المسموح فقط، ويتذكّر آخر قسم فتحته في كل مركز (لكل مستخدم).
   «القسم الحالي» = التبويب العام، فتظل الروابط القديمة تعمل وتفتح داخل المركز — بلا فقدان أي ميزة.
   ============================================================ */
const HUBS = {
  analytics: {
    ar: 'مركز التحليل والأداء', desc: 'لوحاتك ومؤشراتك وتحليلاتك في مكان واحد', icon: Compass,
    views: [
      { id: 'exec', ar: 'اللوحة التنفيذية', icon: Compass, comp: ExecDashboard },
      { id: 'dash', ar: 'لوحة المؤشرات', icon: LayoutDashboard, comp: Dashboard },
      { id: 'compare', ar: 'مقارنة الفروع', icon: BarChart3, comp: BranchCompare },
      { id: 'growth', ar: 'تحليلات النمو', icon: TrendingUp, comp: GrowthAnalytics },
      { id: 'breakeven', ar: 'تحليل التعادل', icon: Scale, comp: BreakEven },
      { id: 'scorecard', ar: 'لوحة الأهداف', icon: CheckCircle2, comp: Scorecard },
      { id: 'scenario', ar: 'ماذا-لو', icon: Compass, comp: Scenario },
      { id: 'ai', ar: 'المركز الذكي', icon: Sparkles, comp: AiCenter }
    ]
  },
  reporting: {
    ar: 'مركز التقارير', desc: 'التقارير المالية والإدارية وبناؤها وتصديرها', icon: FileBarChart,
    views: [
      { id: 'reports', ar: 'التقارير المالية', icon: FileBarChart, comp: Reports },
      { id: 'rbuild', ar: 'منشئ التقارير', icon: Wand2, comp: ReportBuilder },
      { id: 'boardpack', ar: 'تقرير الإدارة الشهري', icon: FileText, comp: BoardPack },
      { id: 'cashflow', ar: 'التدفق النقدي (13 أسبوعًا)', icon: Banknote, comp: CashFlow13 }
    ]
  },
  people: {
    ar: 'شؤون الموظفين', desc: 'البيانات الرئيسية والسياسات والرواتب والسلف وتخطيط العمالة', icon: Wallet,
    views: [
      { id: 'hrmaster', ar: 'البيانات الرئيسية', icon: Building2, comp: HrMaster },
      { id: 'hrpolicy', ar: 'السياسات والأدوار', icon: ShieldCheck, comp: HrPolicy },
      { id: 'payroll', ar: 'الرواتب والسلف', icon: Wallet, comp: Payroll },
      { id: 'workforce', ar: 'تخطيط العمالة والتكلفة', icon: CalendarDays, comp: Workforce }
    ]
  },
  purchasing: {
    ar: 'المشتريات والموردون', desc: 'الموردون والفواتير وأوامر الشراء وإعادة الطلب', icon: Truck,
    views: [
      { id: 'suppliers', ar: 'الموردون والمشتريات', icon: Truck, comp: Suppliers },
      { id: 'reorder', ar: 'المشتريات الذكية', icon: ClipboardCheck, comp: SmartPurchasing }
    ]
  },
  hrops: {
    ar: 'الموارد البشرية — التشغيل', desc: 'الحضور والورديات والمهام والنقاط والتوقيع الإلكتروني', icon: Fingerprint,
    views: [
      { id: 'attendance', ar: 'الحضور الموثَّق', icon: Fingerprint, comp: Attendance },
      { id: 'shiftengine', ar: 'محرّك الورديات', icon: ArrowLeftRight, comp: ShiftEngine },
      { id: 'tasks', ar: 'المهام', icon: CheckCircle2, comp: Tasks },
      { id: 'points', ar: 'دفتر النقاط', icon: Star, comp: PointsLedger },
      { id: 'esign', ar: 'التوقيع الإلكتروني', icon: Signature, comp: ESign }
    ]
  },
  hrperf: {
    ar: 'الأداء والانضباط', desc: 'التقييم ومؤشرات الدور والحوافز والإجراءات التصحيحية والتدريب وتجميد الأداء ولوحة HR', icon: TrendingUp,
    views: [
      { id: 'kpi', ar: 'الأداء والتقييم', icon: TrendingUp, comp: Performance },
      { id: 'rolekpi', ar: 'مؤشرات الأداء بالدور', icon: TrendingUp, comp: RoleKpi },
      { id: 'rewards', ar: 'المكافآت والجزاءات', icon: Coins, comp: Rewards },
      { id: 'corrective', ar: 'الإجراءات التصحيحية', icon: ShieldAlert, comp: Corrective },
      { id: 'training', ar: 'التدريب والشهادات', icon: Stamp, comp: Training },
      { id: 'perfsnap', ar: 'تجميد الأداء الشهري', icon: Lock, comp: PerfSnap },
      { id: 'hrdash', ar: 'لوحة الموارد البشرية', icon: LayoutDashboard, comp: HrDashboard }
    ]
  }
};
function Hub({ hubId, view, ...rest }) {
  const me = rest.me;
  const cfg = HUBS[hubId] || { ar: '', desc: '', icon: Compass, views: [] };
  const rt = ROLES[me.role]?.tabs || [];
  const full = ROLES[me.role]?.scope === 'all';
  const views = cfg.views.filter(v => full || rt.includes(v.id));
  const remembered = (appUseGet(me.id).hubView || {})[hubId];
  const cur = (views.find(v => v.id === view) || views.find(v => v.id === remembered) || views[0] || {}).id;
  const go = (id) => { const u = appUseGet(me.id); u.hubView = { ...(u.hubView || {}), [hubId]: id }; appUseSet(me.id, u); rest.setTab(id); };
  const Cur = (views.find(v => v.id === cur) || {}).comp;
  const HubIcon = cfg.icon;
  return (
    <div className="grid" style={{ gap: 12 }}>
      <div className="card" style={{ padding: '9px 13px' }}>
        <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 8, alignItems: 'center' }}>
          <div className="row" style={{ gap: 8, alignItems: 'center', minWidth: 0 }}>
            <HubIcon size={16} color="var(--brass)" />
            <b style={{ fontSize: 13 }}>{cfg.ar}</b>
            <span style={{ fontSize: 11, color: 'var(--dim)' }} className="hub-desc">· {cfg.desc}</span>
          </div>
          <div className="tw"><div className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
            {views.map(v => (
              <button key={v.id} className={'btn sm' + (cur === v.id ? ' pri' : ' gh')} onClick={() => go(v.id)}>
                <v.icon size={13} />{v.ar}
              </button>
            ))}
          </div></div>
        </div>
      </div>
      {Cur ? <Cur {...rest} /> : <div className="card"><div className="empty">لا توجد أقسام متاحة لصلاحيتك.</div></div>}
    </div>
  );
}

function ExecDashboard({ org, ops, me, myBranches, scoped, setTab, openAcctView, openInvView }) {
  const A = useMemo(() => buildAccounting(org, ops), [org, ops]);
  const sups = useMemo(() => buildPartners(org, ops).filter(p => p.type === 'supplier'), [org, ops]);
  const td = today(); const ym = td.slice(0, 7);
  const r2 = (n) => Math.round(n * 100) / 100;
  const accByCode = {}; A.accounts.forEach(a => { accByCode[a.code] = a; });
  const goAcct = (v) => { setTab('acct'); openAcctView && openAcctView(v); };

  const cashNow = r2(sum(A.accounts.filter(a => a.cash), a => a.balance));
  const monAgg = {};
  A.entries.forEach(e => { if ((e.date || '').slice(0, 7) === ym && !e.closing) e.lines.forEach(l => { const x = monAgg[l.code] || (monAgg[l.code] = { d: 0, c: 0 }); x.d += l.debit; x.c += l.credit; }); });
  const mbal = (a) => { const x = monAgg[a.code] || { d: 0, c: 0 }; return (a.kind === 'asset' || a.kind === 'exp') ? x.d - x.c : x.c - x.d; };
  const monRev = r2(sum(A.accounts.filter(a => a.kind === 'rev'), mbal));
  const monExp = r2(sum(A.accounts.filter(a => a.kind === 'exp'), mbal));
  const monNet = r2(monRev - monExp);
  const monCash = r2(sum(A.accounts.filter(a => a.cash), mbal));

  const budgetOn = !!(org.budget && org.budget.enabled);
  const budLines = (org.budget && org.budget.lines) || [];
  const budExp = r2(sum(budLines.filter(l => (accByCode[l.code] || {}).kind === 'exp'), l => l.amount));
  const budRev = r2(sum(budLines.filter(l => (accByCode[l.code] || {}).kind === 'rev'), l => l.amount));
  const budNet = r2(budRev - budExp);

  const counted = scoped.closings.filter(countedClosing);
  const daySales = (d) => r2(sum(counted.filter(c => c.date === d), c => c.totalRevenue || 0));
  let salesDay = td, salesVal = daySales(td);
  if (salesVal <= 0 && counted.length) { salesDay = counted.map(c => c.date).sort().slice(-1)[0]; salesVal = daySales(salesDay); }
  const isToday = salesDay === td;

  const aged = sups.map(p => ({ p, ...supplierAging(p, td) })).filter(r => r.total > 0.004);
  const totOwed = r2(sum(aged, r => r.total));
  const tot90 = r2(sum(aged, r => r.b90));
  const topOverdue = aged.map(r => ({ name: r.p.name, over: r2(r.b30 + r.b60 + r.b90), total: r.total, b90: r.b90 }))
    .filter(x => x.over > 0.004).sort((a, b) => b.over - a.over).slice(0, 5);

  const totAssets = sum(A.accounts.filter(a => a.kind === 'asset'), a => a.balance);
  const totLiab = sum(A.accounts.filter(a => a.kind === 'liab'), a => a.balance);
  const netFixed = ((accByCode['1701'] || {}).balance || 0) + ((accByCode['1791'] || {}).balance || 0);
  const curAssets = r2(totAssets - netFixed);
  const currentRatio = totLiab > 0.005 ? curAssets / totLiab : null;
  const workingCap = r2(curAssets - totLiab);
  const monMargin = monRev > 0.005 ? monNet / monRev * 100 : null;

  const stockBal = {}; (ops.stockMoves || []).forEach(m => { stockBal[m.itemId] = (stockBal[m.itemId] || 0) + (Number(m.qty) || 0); });
  const lowStock = (org.items || []).filter(it => (Number(it.minQty) || 0) > 0 && (stockBal[it.id] || 0) < (Number(it.minQty) || 0));
  const deficitsToday = counted.filter(c => c.date === td && (c.variance || 0) < 0).length;

  const alerts = [];
  if (tot90 > 0.004) alerts.push({ sev: 'high', txt: 'ذمم موردين متأخرة أكثر من 90 يومًا: ' + money(tot90), go: () => goAcct('apage') });
  if (budgetOn && monExp > budExp + 0.005) alerts.push({ sev: 'high', txt: 'تجاوزت موازنة مصروفات الشهر بـ ' + money(r2(monExp - budExp)), go: () => goAcct('bud') });
  if (deficitsToday > 0) alerts.push({ sev: 'mid', txt: 'عجز صندوق في ' + deficitsToday + ' إغلاق اليوم', go: () => setTab('approve') });
  if (lowStock.length) alerts.push({ sev: 'mid', txt: lowStock.length + ' صنف تحت حد الأمان', go: () => setTab('inv') });
  if (currentRatio != null && currentRatio < 1) alerts.push({ sev: 'mid', txt: 'النسبة الجارية دون 1 (سيولة قصيرة الأجل ضعيفة)', go: () => goAcct('anl') });
  if (!budgetOn) alerts.push({ sev: 'low', txt: 'الموازنة غير مفعّلة — فعّلها لمقارنة الأداء بالمخطّط', go: () => goAcct('bud') });
  const sevCls = { high: 'b-rose', mid: 'b-amber', low: 'b-dim' };
  const sevTxt = { high: 'عاجل', mid: 'متابعة', low: 'اقتراح' };

  const pctTxt = (x) => x == null ? '—' : (Math.round(x * 10) / 10) + '%';
  const xTxt = (x) => x == null ? '—' : (Math.round(x * 100) / 100).toFixed(2) + '×';
  const budBar = (actual, plan, isExp) => {
    const max = Math.max(actual, plan, 1); const wA = Math.max(2, actual / max * 100), wP = Math.max(2, plan / max * 100);
    const over = isExp ? actual > plan + 0.005 : actual + 0.005 < plan;
    return (
      <div style={{ margin: '2px 0 8px' }}>
        <div style={{ height: 9, borderRadius: 5, width: wA + '%', background: over ? 'var(--rose)' : 'var(--mint)' }} />
        <div style={{ height: 5, borderRadius: 3, width: wP + '%', background: 'var(--frame-o)', marginTop: 2 }} />
      </div>
    );
  };

  return (
    <div className="grid" style={{ gap: 14 }}>
      <div className="abar">
        <div className="abar-id"><span className="abar-ic"><Compass size={17} /></span>اللوحة التنفيذية<small>حالة عملك بلمحة — {td}</small></div>
      </div>

      <div className="grid g4">
        <Kpi label={isToday ? 'مبيعات اليوم' : 'مبيعات آخر يوم (' + salesDay + ')'} value={money(salesVal)} sub={isToday ? td : 'لا مبيعات اليوم بعد'} icon={CircleDollarSign} color="#4FB286" />
        <Kpi label="النقد الآن (خزائن + بنك)" value={money(cashNow)} sub="الرصيد الدفتري الحالي" icon={Wallet} color="#C8A24A" />
        <Kpi label="صافي ربح الشهر" value={money(monNet)} sub={'إيراد ' + money(monRev) + ' − مصروف ' + money(monExp)} icon={TrendingUp} color={monNet >= 0 ? '#4FB286' : '#D9544D'} />
        <Kpi label="التغيّر النقدي هذا الشهر" value={money(monCash)} sub={monCash >= 0 ? 'دخول صافٍ' : 'خروج صافٍ'} icon={ArrowLeftRight} color={monCash >= 0 ? '#4FB286' : '#E0A458'} />
      </div>

      <div className="grid g2" style={{ alignItems: 'start' }}>
        <div className="card">
          <div className="card-h"><div className="card-t"><BarChart3 size={15} color="var(--brass)" />الربح مقابل الموازنة — {ym}</div>
            <button className="btn sm gh" onClick={() => goAcct('bud')}>الموازنة<ChevronLeft size={13} /></button></div>
          {budgetOn ? (
            <div style={{ marginTop: 8 }}>
              <div className="row" style={{ justifyContent: 'space-between', fontSize: 12.5 }}><span style={{ color: 'var(--dim)' }}>الإيراد — فعلي {money(monRev)} · هدف {money(budRev)}</span></div>
              {budBar(monRev, budRev, false)}
              <div className="row" style={{ justifyContent: 'space-between', fontSize: 12.5 }}><span style={{ color: 'var(--dim)' }}>المصروف — فعلي {money(monExp)} · موازنة {money(budExp)}</span></div>
              {budBar(monExp, budExp, true)}
              <div className="row" style={{ justifyContent: 'space-between', paddingTop: 8, borderTop: '1px solid var(--line)', fontWeight: 800 }}>
                <span>صافي الربح — فعلي مقابل مخطّط</span>
                <b className="num" style={{ color: monNet + 0.005 >= budNet ? 'var(--mint)' : 'var(--rose)' }}>{money(monNet)} / {money(budNet)}</b>
              </div>
            </div>
          ) : <div className="note" style={{ marginTop: 8 }}>الموازنة غير مفعّلة. فعّلها من «المحاسبة ← الموازنة» لتقارن ربح الشهر بالمخطّط هنا.</div>}
        </div>

        <div className="card">
          <div className="card-h"><div className="card-t"><TrendingUp size={15} color="var(--mint)" />أهم النِسَب والمركز</div>
            <button className="btn sm gh" onClick={() => goAcct('anl')}>التحليل<ChevronLeft size={13} /></button></div>
          <div style={{ marginTop: 6 }}>
            {[['هامش ربح الشهر', pctTxt(monMargin), monMargin == null ? null : monMargin >= 0 ? 'var(--mint)' : 'var(--rose)'],
              ['النسبة الجارية', xTxt(currentRatio), currentRatio == null ? null : currentRatio >= 1 ? 'var(--mint)' : 'var(--amber)'],
              ['رأس المال العامل', money(workingCap), workingCap >= 0 ? 'var(--mint)' : 'var(--rose)'],
              ['إجمالي المستحق للموردين', money(totOwed), totOwed > 0.004 ? 'var(--amber)' : 'var(--mint)']].map(([l, v, c]) => (
              <div key={l} className="row" style={{ justifyContent: 'space-between', padding: '5px 0', borderBottom: '1px solid var(--line)' }}>
                <span style={{ fontSize: 12, color: 'var(--dim)' }}>{l}</span><b className="num" style={{ fontSize: 12.5, color: c || 'var(--txt)' }}>{v}</b>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="grid g2" style={{ alignItems: 'start' }}>
        <div className="card">
          <div className="card-h"><div className="card-t"><Users size={15} color="var(--brass)" />أعلى الموردين المتأخرين</div>
            <button className="btn sm gh" onClick={() => goAcct('apage')}>الأعمار<ChevronLeft size={13} /></button></div>
          <div className="tw" style={{ marginTop: 6 }}>
            <table className="tb">
              <thead><tr><th>المورد</th><th style={{ textAlign: 'end' }}>متأخر</th><th style={{ textAlign: 'end' }}>الإجمالي</th></tr></thead>
              <tbody>
                {topOverdue.map(s => (
                  <tr key={s.name}><td style={{ fontSize: 12.5 }}>{s.name}{s.b90 > 0.004 && <span className="badge b-rose" style={{ marginInlineStart: 6, fontSize: 9.5 }}>+90</span>}</td>
                    <td className="num" style={{ textAlign: 'end', color: 'var(--rose)' }}>{money(s.over)}</td>
                    <td className="num" style={{ textAlign: 'end', fontWeight: 700 }}>{money(s.total)}</td></tr>
                ))}
                {topOverdue.length === 0 && <tr><td colSpan={3}><div className="empty">لا موردين متأخرين — أحسنت.</div></td></tr>}
              </tbody>
            </table>
          </div>
        </div>

        <div className="card">
          <div className="card-h"><div className="card-t"><Bell size={15} color="var(--brass)" />تنبيهات سريعة</div>
            <button className="btn sm gh" onClick={() => setTab('alerts')}>عرض الكل<ChevronLeft size={13} /></button></div>
          <div className="grid" style={{ gap: 7, marginTop: 6 }}>
            {alerts.map((a, i) => (
              <button key={i} className="row" onClick={a.go} style={{ justifyContent: 'space-between', gap: 8, background: 'var(--ink3)', border: '1px solid var(--line)', borderRadius: 9, padding: '9px 11px', cursor: 'pointer', textAlign: 'start' }}>
                <span style={{ fontSize: 12, display: 'flex', alignItems: 'center', gap: 8 }}><span className={'badge ' + sevCls[a.sev]} style={{ fontSize: 9.5, flexShrink: 0 }}>{sevTxt[a.sev]}</span>{a.txt}</span>
                <ChevronLeft size={14} style={{ flexShrink: 0, color: 'var(--faint)' }} />
              </button>
            ))}
            {alerts.length === 0 && <div className="empty">لا تنبيهات — كل شيء ضمن المسار ✓</div>}
          </div>
        </div>
      </div>

      <div className="card" style={{ background: 'rgba(200,162,74,.04)', borderStyle: 'dashed' }}>
        <div className="row" style={{ gap: 8, flexWrap: 'wrap', alignItems: 'center' }}>
          <span style={{ fontSize: 11.5, color: 'var(--dim)', marginInlineEnd: 4 }}>انتقال سريع:</span>
          <button className="btn sm gh" onClick={() => goAcct('cf')}><ArrowLeftRight size={13} />التدفقات النقدية</button>
          <button className="btn sm gh" onClick={() => goAcct('bud')}><BarChart3 size={13} />الموازنة</button>
          <button className="btn sm gh" onClick={() => goAcct('anl')}><TrendingUp size={13} />التحليل والنِسَب</button>
          <button className="btn sm gh" onClick={() => goAcct('apage')}><Users size={13} />أعمار الموردين</button>
          <button className="btn sm gh" onClick={() => goAcct('fs')}><FileBarChart size={13} />القوائم المالية</button>
          <button className="btn sm gh" onClick={() => setTab('sales')}><CircleDollarSign size={13} />المبيعات</button>
        </div>
      </div>
    </div>
  );
}

// ===== v10.9: مركز التنبيهات الذكية — قائمة إجراءات حيّة عبر كل الوحدات، بأولويات وفئات وتصفية =====
function AlertsCenter({ org, ops, me, myBranches, scoped, setTab, openAcctView, openInvView }) {
  const A = useMemo(() => buildAccounting(org, ops), [org, ops]);
  const sups = useMemo(() => buildPartners(org, ops).filter(p => p.type === 'supplier'), [org, ops]);
  const [catF, setCatF] = useState('all');
  const [sevF, setSevF] = useState('all');
  const td = today(); const ym = td.slice(0, 7);
  const r2 = (n) => Math.round(n * 100) / 100;
  const dd = (a, b) => { const x = Date.parse(a), y = Date.parse(b); return (isNaN(x) || isNaN(y)) ? 0 : Math.floor((y - x) / 86400000); };
  const accByCode = {}; A.accounts.forEach(a => { accByCode[a.code] = a; });
  const goAcct = (v) => { setTab('acct'); openAcctView && openAcctView(v); };
  const AL = [];
  const push = (sev, cat, title, detail, action) => AL.push({ sev, cat, title, detail, action });

  // موردون
  const aged = sups.map(p => ({ p, ...supplierAging(p, td) }));
  const over90 = r2(sum(aged, r => r.b90)), over60 = r2(sum(aged, r => r.b60));
  const n90 = aged.filter(r => r.b90 > 0.004).length;
  if (over90 > 0.004) push('high', 'suppliers', 'ذمم موردين متأخرة أكثر من 90 يومًا', money(over90) + ' على ' + n90 + ' مورد — أولوية سداد.', { label: 'الأعمار', go: () => goAcct('apage') });
  if (over60 > 0.004) push('mid', 'suppliers', 'ذمم في شريحة 61–90 يومًا', money(over60) + ' تقترب من التأخّر الحرج.', { label: 'الأعمار', go: () => goAcct('apage') });
  const credSup = aged.filter(r => r.credit > 0.004);
  if (credSup.length) push('low', 'suppliers', credSup.length + ' مورد برصيد دفعة مقدمة', 'دفعتَ أكثر من المستحق — استرجاع أو خصم لاحق.', { label: 'الأعمار', go: () => goAcct('apage') });

  // عملاء وذمم مدينة (v12.2)
  const arAged = buildPartners(org, ops).filter(p => p.type === 'customer').map(p => { const ag = customerAging(p, td); const lim = Number(((org.partners || []).find(x => x.id === p.id) || {}).creditLimit) || 0; return { p, ...ag, lim, over: lim > 0 && ag.total > lim + 0.004 }; });
  const ar90 = r2(sum(arAged, r => r.b90)), arN90 = arAged.filter(r => r.b90 > 0.004).length;
  if (ar90 > 0.004) push('high', 'customers', 'ذمم عملاء متأخرة أكثر من 90 يومًا', money(ar90) + ' على ' + arN90 + ' عميل — أولوية تحصيل.', { label: 'أعمار العملاء', go: () => goAcct('arage') });
  const arOver = arAged.filter(r => r.over);
  if (arOver.length) push('high', 'customers', arOver.length + ' عميل تجاوز حد الائتمان', 'راجع حدودهم قبل بيع آجل إضافي.', { label: 'أعمار العملاء', go: () => goAcct('arage') });

  // موازنة
  const budgetOn = !!(org.budget && org.budget.enabled);
  if (budgetOn) {
    const monAgg = {}; A.entries.forEach(e => { if ((e.date || '').slice(0, 7) === ym && !e.closing) e.lines.forEach(l => { const x = monAgg[l.code] || (monAgg[l.code] = { d: 0, c: 0 }); x.d += l.debit; x.c += l.credit; }); });
    (org.budget.lines || []).forEach(l => {
      const a = accByCode[l.code]; if (!a || a.kind !== 'exp') return;
      const x = monAgg[l.code] || { d: 0, c: 0 }; const actual = r2(x.d - x.c);
      if (actual > (l.amount || 0) + 0.005) push('mid', 'budget', 'تجاوز موازنة: ' + a.name, 'الفعلي ' + money(actual) + ' مقابل موازنة ' + money(l.amount) + ' هذا الشهر.', { label: 'الموازنة', go: () => goAcct('bud') });
    });
  } else push('low', 'budget', 'الموازنة غير مفعّلة', 'فعّلها لمقارنة الأداء بالمخطّط والتنبيه عند التجاوز.', { label: 'تفعيل', go: () => goAcct('bud') });

  // نقد وسيولة
  A.accounts.filter(a => a.cash && a.balance < -0.004).forEach(a => push('high', 'cash', 'رصيد نقدي سالب: ' + a.name, money(a.balance) + ' — راجع القيود أو مصدر التمويل.', { label: 'دليل الحسابات', go: () => goAcct('coa') }));
  const totLiab = sum(A.accounts.filter(a => a.kind === 'liab'), a => a.balance);
  const totAssets = sum(A.accounts.filter(a => a.kind === 'asset'), a => a.balance);
  const netFixed = ((accByCode['1701'] || {}).balance || 0) + ((accByCode['1791'] || {}).balance || 0);
  const curAssets = r2(totAssets - netFixed);
  if (totLiab > 0.005 && curAssets / totLiab < 1) push('mid', 'cash', 'النسبة الجارية دون 1', 'الأصول المتداولة ' + money(curAssets) + ' أقل من الخصوم ' + money(totLiab) + '.', { label: 'التحليل', go: () => goAcct('anl') });
  const recs = (ops.bankRecs || []).slice().sort((a, b) => (a.date || '').localeCompare(b.date || ''));
  const bankMoved = A.entries.some(e => e.lines.some(l => l.code === '1201'));
  if (bankMoved) { const last = recs[recs.length - 1];
    if (!last) push('low', 'cash', 'لم تُجرِ تسوية بنكية بعد', 'طابِق رصيد البنك الدفتري مع كشفك الفعلي.', { label: 'التسوية', go: () => goAcct('bank') });
    else if (dd(last.date, td) > 30) push('mid', 'cash', 'آخر تسوية بنكية قبل ' + dd(last.date, td) + ' يومًا', 'راجع مطابقة البنك دوريًا.', { label: 'التسوية', go: () => goAcct('bank') }); }

  // مخزون
  const stockBal = {}; (ops.stockMoves || []).forEach(m => { stockBal[m.itemId] = (stockBal[m.itemId] || 0) + (Number(m.qty) || 0); });
  const low = (org.items || []).filter(it => (Number(it.minQty) || 0) > 0 && (stockBal[it.id] || 0) < (Number(it.minQty) || 0));
  if (low.length) push('mid', 'inventory', low.length + ' صنف تحت حد الأمان', low.slice(0, 4).map(it => it.name).join('، ') + (low.length > 4 ? '…' : '') + ' — أعِد التزويد.', { label: 'المخزون', go: () => setTab('inv') });
  if ((org.items || []).length && (ops.stockMoves || []).length && !(org.invValuation && org.invValuation.enabled)) push('low', 'inventory', 'رسملة المخزون غير مفعّلة', 'فعّلها لتظهر تكلفة البضاعة المباعة والمخزون بدقّة.', { label: 'المخزون', go: () => setTab('inv') });

  // ضريبة
  if (org.taxCfg && org.taxCfg.enabled) {
    let out = 0, inn = 0; A.entries.forEach(e => { if (e.vat) { out += e.vat.out; inn += e.vat.inn; } });
    const vatDue = r2(out - inn);
    if (vatDue > 0.004) push('mid', 'tax', 'صافي ضريبة مستحقة (تقديري)', money(vatDue) + ' — راجع مسودة الإقرار.', { label: 'الضريبة', go: () => goAcct('vat') });
  }

  // تشغيل
  const pendingApp = (ops.closings || []).filter(c => c.status === 'submitted').length;
  if (pendingApp > 0) push('mid', 'ops', pendingApp + ' إغلاق بانتظار الاعتماد', 'راجعها واعتمدها لتُرحَّل نهائيًا.', { label: 'الاعتماد', go: () => setTab('approve') });
  const defs = (ops.closings || []).filter(c => countedClosing(c) && (c.variance || 0) < 0 && dd(c.date, td) >= 0 && dd(c.date, td) <= 7);
  if (defs.length) push('high', 'ops', defs.length + ' عجز صندوق خلال أسبوع', 'إجمالي ' + money(r2(sum(defs, c => c.variance))) + ' — راقب الفروع.', { label: 'المقارنة', go: () => setTab('compare') });
  const unjust = (ops.advances || []).filter(a => a.isUnjustified).length;
  if (unjust > 0) push('mid', 'ops', unjust + ' سلفة غير مبررة', 'راجعها في شاشة الرواتب والسلف.', { label: 'الرواتب', go: () => setTab('payroll') });

  // إعداد/حوكمة
  const assetsDone = (A.assetRows || []).filter(a => a.done && !a.disposed).length;
  if (assetsDone > 0) push('low', 'setup', assetsDone + ' أصل اكتمل إهلاكه', 'راجعها للاستبعاد أو إعادة التقييم.', { label: 'الأصول', go: () => goAcct('ast') });
  const hasActivity = (ops.closings || []).some(countedClosing) || (ops.invoices || []).length > 0;
  if (hasActivity && !(org.openingBalances && (org.openingBalances.lines || []).length)) push('low', 'setup', 'الأرصدة الافتتاحية غير مُدخلة', 'أدخِل أرصدة ما قبل المنصة لدقّة المركز المالي.', { label: 'الأرصدة', go: () => goAcct('ob') });
  // v11.7 — انتهاء صلاحية الوثائق الرسمية
  const docRemind = Number((org.docCfg && org.docCfg.remindDays) != null ? org.docCfg.remindDays : 45) || 45;
  (org.documents || []).forEach(dc => {
    if (!dc.expiryDate) return; const dl = dd(td, dc.expiryDate);
    if (dl < 0) push('high', 'setup', 'وثيقة منتهية: ' + DOC_LABEL(dc.type), (dc.number ? dc.number + ' · ' : '') + 'انتهت في ' + dc.expiryDate + ' — جدّدها فورًا.', { label: 'الوثائق', go: () => setTab('docs') });
    else if (dl <= docRemind) push('mid', 'setup', 'وثيقة تنتهي قريبًا: ' + DOC_LABEL(dc.type), (dc.number ? dc.number + ' · ' : '') + 'تنتهي في ' + dc.expiryDate + ' (' + dl + ' يومًا).', { label: 'الوثائق', go: () => setTab('docs') });
  });

  // م٩ (v26.0) — تنبيهات الموارد البشرية (م١–م٨) ضمن فروعي
  try {
    const hrBranches = (myBranches || []).filter(b => b.isActive !== false);
    const hrIds = hrBranches.map(b => b.id);
    const hrEmps = (org.employees || []).filter(e => e.isActive !== false && hrIds.includes(e.branchId));
    // مستندات الموظفين (م١)
    let expDocs = 0, soonDocs = 0;
    hrEmps.forEach(e => (e.docs || []).forEach(dc => { if (!dc.expiryDate) return; const dl = dd(td, dc.expiryDate); if (dl < 0) expDocs++; else if (dl <= 30) soonDocs++; }));
    if (expDocs) push('high', 'hr', expDocs + ' مستند موظف منتهي الصلاحية', 'هوية/إقامة/عقد/شهادة انتهت — جدّدها من البيانات الرئيسية.', { label: 'البيانات الرئيسية', go: () => setTab('people') });
    if (soonDocs) push('mid', 'hr', soonDocs + ' مستند موظف ينتهي خلال 30 يومًا', 'راجع مستندات الموظفين قبل انتهائها.', { label: 'البيانات الرئيسية', go: () => setTab('people') });
    // غياب متكرر هذا الشهر (م٣/م٤)
    const repeatAbs = hrEmps.map(e => ({ e, st: hrEmpStats(org, ops, e, ym + '-01', ym + '-31') })).filter(x => x.st.absent >= 3);
    if (repeatAbs.length) push('high', 'hr', repeatAbs.length + ' موظف بغياب متكرر هذا الشهر (3 ورديات فأكثر)', repeatAbs.slice(0, 4).map(x => x.e.name + ' (' + x.st.absent + ')').join('، ') + (repeatAbs.length > 4 ? '…' : ''), { label: 'الأداء والتقييم', go: () => setTab('kpi') });
    // طلبات معلّقة (م٤/م٨)
    const pendRw = (ops.rewardRequests || []).filter(r => hrIds.includes(r.branchId) && r.status === 'pending').length;
    if (pendRw) push('mid', 'hr', pendRw + ' طلب مكافأة/جزاء بانتظار الاعتماد', 'لا أثر على الرواتب حتى يُعتمد.', { label: 'المكافآت', go: () => setTab('rewards') });
    const pendSw = (ops.shiftSwapRequests || []).filter(r => hrIds.includes(r.branchId) && r.status === 'pending').length;
    const pendTr = (ops.branchTransferRequests || []).filter(r => hrIds.includes(r.branchId) && r.status === 'pending').length;
    if (pendSw + pendTr) push('mid', 'hr', (pendSw ? pendSw + ' طلب تبديل وردية' : '') + (pendSw && pendTr ? ' و' : '') + (pendTr ? pendTr + ' طلب نقل موظف' : '') + ' بانتظار البتّ', 'راجعها في محرّك الورديات.', { label: 'محرّك الورديات', go: () => setTab('shiftengine') });
    // ورديات بلا تغطية غدًا (م٤)
    const tmr = new Date(td + 'T00:00:00'); tmr.setDate(tmr.getDate() + 1); const tds = tmr.toISOString().slice(0, 10); const twd = tmr.getDay();
    const addD = (ds, n) => { const d = new Date(ds + 'T00:00:00'); d.setDate(d.getDate() + n); return d.toISOString().slice(0, 10); };
    const uncovered = [];
    hrBranches.forEach(b => {
      (ops.shiftTemplates || []).filter(t => t.branchId === b.id && (t.days || []).includes(twd)).forEach(t => {
        const covered = (ops.shiftAssignments || []).some(a => a.branchId === b.id && (a.shiftIds || []).some((sid, di) => sid === t.id && addD(a.weekStart, di) === tds));
        if (!covered) uncovered.push(b.name + ' — ' + t.name);
      });
    });
    if (uncovered.length) push('mid', 'hr', uncovered.length + ' وردية بلا تغطية غدًا', uncovered.slice(0, 3).join('، ') + (uncovered.length > 3 ? '…' : ''), { label: 'التعيين الأسبوعي', go: () => setTab('shiftengine') });
    // موظفون بلا PIN ولا بطاقة (م٣)
    const noPin = hrEmps.filter(e => !(ops.hrPins || []).some(p => p.employeeId === e.id && (p.pinHash || p.badgeHash))).length;
    if (noPin) push('low', 'hr', noPin + ' موظف بلا رقم PIN ولا بطاقة QR', 'لن يستطيعوا تسجيل الحضور من جهاز الفرع.', { label: 'أرقام PIN', go: () => setTab('attendance') });
    // م١٠ (v27.0) — إقرارات/إشعارات بانتظار توقيع الموظف تجاوزت مهلة التذكير (hrPolicies.signReminderDays)
    const overdueSign = overdueSignDocs(org, ops, hrIds, td);
    if (overdueSign.length) {
      const sd = Number((org.hrPolicies || {}).signReminderDays != null ? org.hrPolicies.signReminderDays : defaultHrPolicies().signReminderDays) || 0;
      push('mid', 'hr', overdueSign.length + ' إقرار/إشعار بانتظار توقيع الموظف منذ أكثر من ' + sd + ' أيام', [...new Set(overdueSign.map(x => x.employeeName))].slice(0, 4).join('، ') + (overdueSign.length > 4 ? '…' : '') + ' — يوقّعون من كشك الفرع بعد التحقق بـPIN.', { label: 'التوقيع الإلكتروني', go: () => setTab('esign') });
    }
    // م٢٠ (v27.6) — إجراءات تأديبية بانتظار الاعتماد + مقترحات خطط تحسين الأداء
    const pendCorr = (ops.hrCorrective || []).filter(c => hrIds.includes(c.branchId) && c.status === 'pending').length;
    if (pendCorr) push('mid', 'hr', pendCorr + ' إجراء تأديبي بانتظار الاعتماد المركزي', 'راجعها في الإجراءات التصحيحية.', { label: 'الإجراءات التصحيحية', go: () => setTab('corrective') });
    const _polC = { ...defaultHrPolicies(), ...(org.hrPolicies || {}) }; const _pipTh = Number(_polC.pipTriggerScore) || 60;
    const _actPip = new Set((ops.hrPips || []).filter(p => p.status === 'active').map(p => p.employeeId));
    const _lowN = hrEmps.filter(e => { const sc = hrScoreFor(org, ops, e, td.slice(0, 7)).score; return sc != null && sc < _pipTh && !_actPip.has(e.id); }).length;
    if (_lowN) push('low', 'hr', _lowN + ' موظف بدرجة أداء دون العتبة (' + _pipTh + ') بلا خطة تحسين نشطة', 'افتح خطة تحسين أداء أو راجع إجراءاتهم.', { label: 'خطط تحسين الأداء', go: () => setTab('corrective') });
    // م١٩ (v27.7) — شهادات منتهية/قريبة + نقص تدريب إلزامي
    const _progs = (org.trainingPrograms && org.trainingPrograms.length) ? org.trainingPrograms : defaultTrainingPrograms();
    const _trAlertDays = Number((org.hrPolicies || {}).trainingExpiryAlertDays) || 30;
    const _trRecs = (ops.hrTraining || []).filter(r => hrIds.includes(r.branchId));
    const _expTr = expiringTraining(_trRecs, _trAlertDays, td);
    if (_expTr.length) push('mid', 'hr', _expTr.length + ' شهادة تدريب منتهية أو تنتهي خلال ' + _trAlertDays + ' يومًا', [...new Set(_expTr.map(x => x.employeeName))].slice(0, 4).join('، ') + ' — جدّدها في التدريب والشهادات.', { label: 'التدريب والشهادات', go: () => setTab('training') });
    let _missN = 0; hrEmps.forEach(e => { _missN += missingRequiredTraining(_progs, _trRecs, e, td).length; });
    if (_missN) push('mid', 'hr', _missN + ' تدريب إلزامي ناقص لدى موظفي فروعك', 'راجع مصفوفة الامتثال في التدريب والشهادات.', { label: 'مصفوفة الامتثال', go: () => setTab('training') });
  } catch (e) { }

  const sevRank = { high: 0, mid: 1, low: 2 };
  AL.sort((a, b) => sevRank[a.sev] - sevRank[b.sev]);
  const counts = { high: AL.filter(a => a.sev === 'high').length, mid: AL.filter(a => a.sev === 'mid').length, low: AL.filter(a => a.sev === 'low').length };
  const catMap = { suppliers: 'موردون', customers: 'عملاء', budget: 'موازنة', cash: 'نقد وسيولة', inventory: 'مخزون', tax: 'ضريبة', ops: 'تشغيل', setup: 'إعداد', hr: 'موارد بشرية' };
  const cats = [['all', 'كل الفئات'], ['suppliers', 'موردون'], ['customers', 'عملاء'], ['budget', 'موازنة'], ['cash', 'نقد وسيولة'], ['inventory', 'مخزون'], ['tax', 'ضريبة'], ['ops', 'تشغيل'], ['setup', 'إعداد'], ['hr', 'موارد بشرية']];
  const sevCls = { high: 'b-rose', mid: 'b-amber', low: 'b-dim' }, sevTxt = { high: 'عاجل', mid: 'متابعة', low: 'اقتراح' };
  const shown = AL.filter(a => (catF === 'all' || a.cat === catF) && (sevF === 'all' || a.sev === sevF));

  return (
    <div className="grid" style={{ gap: 14 }}>
      <div className="abar">
        <div className="abar-id"><span className="abar-ic"><Bell size={17} /></span>مركز التنبيهات<small>قائمة إجراءات حيّة — تختفي تلقائيًا عند حلّها · {td}</small></div>
      </div>

      <div className="grid g4">
        <Kpi label="إجمالي التنبيهات" value={String(AL.length)} sub="عبر كل الوحدات" icon={Bell} color="#C8A24A" />
        <Kpi label="عاجل" value={String(counts.high)} sub="يتطلب إجراءً الآن" icon={AlertTriangle} color={counts.high ? '#D9544D' : '#4FB286'} />
        <Kpi label="متابعة" value={String(counts.mid)} sub="راقبه هذا الأسبوع" icon={Clock} color={counts.mid ? '#E0A458' : '#4FB286'} />
        <Kpi label="اقتراح" value={String(counts.low)} sub="تحسينات وإعداد" icon={Sparkles} color="#5B93C4" />
      </div>

      <div className="card">
        <div className="row" style={{ gap: 6, flexWrap: 'wrap', alignItems: 'center', marginBottom: 8 }}>
          <span style={{ fontSize: 11.5, color: 'var(--dim)', marginInlineEnd: 2 }}>الأولوية:</span>
          {[['all', 'الكل'], ['high', 'عاجل'], ['mid', 'متابعة'], ['low', 'اقتراح']].map(([k, l]) => (
            <button key={k} className={'btn sm' + (sevF === k ? ' pri' : ' gh')} onClick={() => setSevF(k)}>{l}</button>
          ))}
        </div>
        <div className="row" style={{ gap: 6, flexWrap: 'wrap', alignItems: 'center' }}>
          <span style={{ fontSize: 11.5, color: 'var(--dim)', marginInlineEnd: 2 }}>الفئة:</span>
          {cats.map(([k, l]) => (
            <button key={k} className={'btn sm' + (catF === k ? ' pri' : ' gh')} onClick={() => setCatF(k)}>{l}</button>
          ))}
        </div>
      </div>

      <div className="grid" style={{ gap: 8 }}>
        {shown.map((a, i) => (
          <div key={i} className="card" style={{ borderInlineStart: '3px solid ' + (a.sev === 'high' ? 'var(--rose)' : a.sev === 'mid' ? 'var(--amber)' : 'var(--dim)') }}>
            <div className="row" style={{ justifyContent: 'space-between', gap: 10, flexWrap: 'wrap' }}>
              <div style={{ flex: 1, minWidth: 220 }}>
                <div className="row" style={{ gap: 7, alignItems: 'center', flexWrap: 'wrap' }}>
                  <span className={'badge ' + sevCls[a.sev]} style={{ fontSize: 9.5 }}>{sevTxt[a.sev]}</span>
                  <span className="badge b-dim" style={{ fontSize: 9.5 }}>{catMap[a.cat]}</span>
                  <b style={{ fontSize: 13 }}>{a.title}</b>
                </div>
                <div style={{ fontSize: 11.5, color: 'var(--dim)', marginTop: 4 }}>{a.detail}</div>
              </div>
              {a.action && <button className="btn sm" onClick={a.action.go}>{a.action.label}<ChevronLeft size={13} /></button>}
            </div>
          </div>
        ))}
        {shown.length === 0 && (
          <div className="card"><div className="empty">{AL.length === 0 ? 'لا تنبيهات — كل شيء ضمن المسار ✓' : 'لا تنبيهات ضمن هذا التصنيف.'}</div></div>
        )}
      </div>

      <div className="note">التنبيهات مشتقّة حيًّا من بياناتك وتختفي تلقائيًا عند معالجة سببها — لا حاجة لإغلاقها يدويًا. العتبات المعتمدة: تأخّر الموردين ٩٠ يومًا، أي عجز صندوق خلال أسبوع، المخزون تحت حد الأمان المعرّف لكل صنف، وتقادم التسوية البنكية بعد ٣٠ يومًا.</div>
    </div>
  );
}

function Dashboard({ org, ops, pulse, me, myBranches, scoped, online, setTab, theme, openAcctView, openInvView }) {
  const [days, setDays] = useState(14);
  const [dayReport, setDayReport] = useState(false);
  const tn = chartTone(theme);

  // منصة جديدة بلا فروع بعد → دليل البدء
  if ((org.branches || []).length === 0) {
    const steps = [
      { n: 1, t: 'أضف فروعك', d: 'سجّل كل فرع باسمه ومدينته والعهدة الافتتاحية.', to: 'admin', ic: Building2, done: false },
      { n: 2, t: 'أنشئ حسابات المستخدمين', d: 'مدير لكل فرع، ومحاسب للإدارة المالية — بريد وكلمة سر لكل منهم.', to: 'admin', ic: Users, done: false },
      { n: 3, t: 'أضف الموظفين', d: 'لتفعيل كشوف الرواتب والسلف.', to: 'admin', ic: UserCog, done: (org.employees || []).length > 0 },
      { n: 4, t: 'سجّل أول إغلاق يومي', d: 'ابدأ التشغيل الفعلي بإغلاق وردية.', to: 'closing', ic: ClipboardCheck, done: false }
    ];
    return (
      <div className="grid" style={{ gap: 14 }}>
        <div className="card" style={{ borderColor: 'rgba(200,162,74,.3)' }}>
          <h2 style={{ fontSize: 18, marginBottom: 6 }}>مرحباً {me.name.split(' ')[0]} — لنبدأ التهيئة</h2>
          <div style={{ fontSize: 12.5, color: 'var(--dim)', lineHeight: 1.9 }}>
            هذه منصة حية جديدة بلا بيانات تجريبية. أكمل الخطوات التالية لتشغيلها. كل ما تدخله يُحفظ سحابياً ويظهر لبقية المستخدمين فوراً.
          </div>
        </div>
        <div className="grid g2">
          {steps.map(st => (
            <div key={st.n} className="card" style={{ display: 'flex', gap: 12, alignItems: 'flex-start' }}>
              <div className="brand-mark" style={{ width: 38, height: 38, borderRadius: 11, flexShrink: 0,
                background: st.done ? 'linear-gradient(145deg,#4FB286,#2E8B62)' : 'linear-gradient(145deg,var(--brass),var(--brass-d))' }}>
                {st.done ? <Check size={18} /> : <st.ic size={17} />}
              </div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div className="row" style={{ justifyContent: 'space-between' }}>
                  <div style={{ fontSize: 13.5, fontWeight: 600 }}>الخطوة {st.n}: {st.t}</div>
                  {st.done && <span className="badge b-mint">تم</span>}
                </div>
                <div style={{ fontSize: 11.5, color: 'var(--dim)', margin: '5px 0 10px', lineHeight: 1.7 }}>{st.d}</div>
                <button className="btn sm pri" onClick={() => setTab(st.to)}>ابدأ</button>
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  const cls = scoped.closings.filter(countedClosing);
  const from = new Date(); from.setDate(from.getDate() - days);
  const fromS = from.toISOString().slice(0, 10);
  const win = cls.filter(c => c.date >= fromS);

  const rev = sum(win, c => c.totalRevenue);
  const exp = sum(win, c => c.totalExpenses);
  const net = rev - exp;
  const margin = rev ? (net / rev) * 100 : 0;
  const varSum = sum(win, c => c.variance);
  const deficits = win.filter(c => c.variance < 0);

  const series = useMemo(() => {
    const map = {};
    win.forEach(c => {
      if (!map[c.date]) map[c.date] = { d: c.date, rev: 0, exp: 0, cash: 0 };
      map[c.date].rev += c.totalRevenue; map[c.date].exp += c.totalExpenses; map[c.date].cash += c.cashSales;
    });
    return Object.values(map).sort((a, b) => a.d.localeCompare(b.d))
      .map(x => ({ ...x, lbl: x.d.slice(5).replace('-', '/'), net: x.rev - x.exp }));
  }, [win]);

  const perBranch = useMemo(() => myBranches.map(b => {
    const bc = win.filter(c => c.branchId === b.id);
    const r = sum(bc, c => c.totalRevenue), e = sum(bc, c => c.totalExpenses);
    return { name: b.name.replace('الفرع ', '').replace('فرع ', ''), rev: r, exp: e, net: r - e, id: b.id, n: bc.length };
  }).sort((a, b) => b.net - a.net), [win, myBranches]);

  const channels = useMemo(() => [
    { k: 'نقدي', v: sum(win, c => c.cashSales), c: '#4FB286' },
    { k: 'شبكة', v: sum(win, c => c.cardSales), c: '#5B93C4' },
    { k: 'تطبيقات', v: sum(win, c => c.totalDeliverySales), c: '#C8A24A' },
    { k: 'تحويل بنكي', v: sum(win, c => c.bankTransferSales || 0), c: '#9B7BB8' }
  ], [win]);
  const chTotal = sum(channels, c => c.v) || 1;

  const pendingT = scoped.transfers.filter(t => t.status === 'pending');
  const missing = myBranches.filter(b => !cls.some(c => c.date === today() && c.branchId === b.id));
  const audit = (pulse.audit || []).slice(0, 8);

  return (
    <div className="grid" style={{ gap: 14 }}>
      <AppsStrip me={me} setTab={setTab} openAcctView={openAcctView} openInvView={openInvView} />
      <div className="row" style={{ justifyContent: 'space-between' }}>
        <div>
          <h2 style={{ fontSize: 17 }}>مرحباً {me.name.split(' ')[0]} 👋</h2>
          <div style={{ fontSize: 12, color: 'var(--dim)' }}>
            {myBranches.length} فرع ضمن نطاق صلاحيتك · آخر {days} يوماً
          </div>
        </div>
        <div className="row">
          <button className="btn sm pri" onClick={() => setDayReport(true)}>
            <FileText size={14} />تقارير الفروع اليومية
          </button>
          {[7, 14, 30].map(d => (
            <button key={d} className={'btn sm' + (days === d ? ' pri' : ' gh')} onClick={() => setDays(d)}>
              {d} يوم
            </button>
          ))}
        </div>
      </div>

      {dayReport && <DailyBranchReport org={org} scoped={scoped} myBranches={myBranches} onClose={() => setDayReport(false)} />}

      <div className="grid g4">
        <Kpi label="إجمالي الإيرادات" value={money(rev)} sub={`${win.length} إغلاق مسجل`} icon={CircleDollarSign} color="#C8A24A" />
        <Kpi label="إجمالي المصروفات" value={money(exp)} sub={`${rev ? ((exp / rev) * 100).toFixed(1) : 0}% من الإيراد`} icon={Receipt} color="#D9544D" />
        <Kpi label="صافي الربح" value={money(net)} sub={`هامش ${margin.toFixed(1)}%`} icon={TrendingUp} color="#4FB286" />
        <Kpi label="فروقات الصندوق" value={money(varSum)} sub={`${deficits.length} حالة عجز`} icon={AlertTriangle} color={varSum < 0 ? '#D9544D' : '#5B93C4'} />
      </div>

      {(missing.length > 0 || pendingT.length > 0) && (
        <div className="grid g2">
          {missing.length > 0 && (
            <div className="card" style={{ borderColor: 'rgba(224,164,88,.35)' }}>
              <div className="card-t" style={{ color: 'var(--amber)' }}><AlertTriangle size={15} />إغلاقات اليوم لم تُسجّل بعد</div>
              {missing.map(b => (
                <div key={b.id} className="mono-b" style={{ marginBottom: 7 }}>
                  <div><div style={{ fontSize: 12.5 }}>{b.name}</div>
                    <div style={{ fontSize: 10.5, color: 'var(--faint)' }}>نهاية الوردية {b.shiftEndTime}</div></div>
                  <button className="btn sm pri" onClick={() => setTab('closing')}>تسجيل الآن</button>
                </div>
              ))}
            </div>
          )}
          {pendingT.length > 0 && (
            <div className="card">
              <div className="card-t"><Landmark size={15} color="var(--brass)" />تحويلات بانتظار الاستلام</div>
              <div className="kpi-v num" style={{ color: 'var(--brass)' }}>{money(sum(pendingT, t => t.amount))}</div>
              <div className="kpi-s">{pendingT.length} سند تحويل من {new Set(pendingT.map(t => t.branchId)).size} فرع</div>
              <button className="btn sm" style={{ marginTop: 12 }} onClick={() => setTab('treasury')}>
                <ArrowLeftRight size={13} />فتح الخزينة
              </button>
            </div>
          )}
        </div>
      )}

      <div className="card">
        <div className="card-h">
          <div className="card-t"><TrendingUp size={15} color="var(--brass)" />حركة الإيرادات والمصروفات</div>
          <span className="badge b-dim">ريال سعودي</span>
        </div>
        <div style={{ height: 260, direction: 'ltr' }}>
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={series} margin={{ top: 4, right: 4, left: -18, bottom: 0 }}>
              <defs>
                <linearGradient id="gr" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="#C8A24A" stopOpacity={0.42} />
                  <stop offset="100%" stopColor="#C8A24A" stopOpacity={0.02} />
                </linearGradient>
                <linearGradient id="ge" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="#D9544D" stopOpacity={0.3} />
                  <stop offset="100%" stopColor="#D9544D" stopOpacity={0.02} />
                </linearGradient>
              </defs>
              <CartesianGrid stroke={tn.grid} vertical={false} />
              <XAxis dataKey="lbl" tick={{ fill: tn.tick, fontSize: 10 }} axisLine={false} tickLine={false} />
              <YAxis tick={{ fill: tn.tick, fontSize: 10 }} axisLine={false} tickLine={false} tickFormatter={short} />
              <Tooltip contentStyle={{ background: tn.tip, border: '1px solid ' + tn.grid, borderRadius: 10, fontSize: 12, direction: 'rtl', color: tn.tipTxt }}
                labelStyle={{ color: '#A2968A' }} formatter={(v, n) => [money(v), n === 'rev' ? 'الإيراد' : n === 'exp' ? 'المصروف' : 'الصافي']} />
              <Area type="monotone" dataKey="rev" stroke={tn.accent} strokeWidth={2} fill="url(#gr)" />
              <Area type="monotone" dataKey="exp" stroke={tn.neg} strokeWidth={1.6} fill="url(#ge)" />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid g2">
        <div className="card">
          <div className="card-t" style={{ marginBottom: 14 }}><Store size={15} color="var(--brass)" />أداء الفروع</div>
          <div style={{ height: 210, direction: 'ltr' }}>
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={perBranch} margin={{ top: 4, right: 4, left: -18, bottom: 0 }}>
                <CartesianGrid stroke={tn.grid} vertical={false} />
                <XAxis dataKey="name" tick={{ fill: tn.tick, fontSize: 9.5 }} axisLine={false} tickLine={false} />
                <YAxis tick={{ fill: tn.tick, fontSize: 10 }} axisLine={false} tickLine={false} tickFormatter={short} />
                <Tooltip cursor={{ fill: 'rgba(255,255,255,.03)' }}
                  contentStyle={{ background: tn.tip, border: '1px solid ' + tn.grid, borderRadius: 10, fontSize: 12, direction: 'rtl', color: tn.tipTxt }}
                  formatter={(v, n) => [money(v), n === 'rev' ? 'الإيراد' : 'الصافي']} />
                <Bar dataKey="rev" fill={tn.bar} radius={[5, 5, 0, 0]} />
                <Bar dataKey="net" fill={tn.accent} radius={[5, 5, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="card">
          <div className="card-t" style={{ marginBottom: 14 }}><Banknote size={15} color="var(--brass)" />توزيع قنوات التحصيل</div>
          {channels.map((c, i) => (
            <div key={i} style={{ marginBottom: 13 }}>
              <div className="row" style={{ justifyContent: 'space-between', fontSize: 12, marginBottom: 5 }}>
                <span>{c.k}</span>
                <span className="num" style={{ color: c.c }}>{money(c.v)} · {((c.v / chTotal) * 100).toFixed(0)}%</span>
              </div>
              <div style={{ height: 6, background: 'var(--ink)', borderRadius: 6, overflow: 'hidden' }}>
                <div style={{ width: ((c.v / chTotal) * 100) + '%', height: '100%', background: c.c, borderRadius: 6, transition: '.5s' }} />
              </div>
            </div>
          ))}
          <hr className="hr" />
          <div className="row" style={{ justifyContent: 'space-between', fontSize: 12 }}>
            <span style={{ color: 'var(--dim)' }}>عمولات تطبيقات التوصيل المقدّرة</span>
            <span className="num" style={{ color: 'var(--rose)' }}>
              {money(sum(win, c => sum(c.deliverySales || [], d => d.commissionAmount || 0)))}
            </span>
          </div>
        </div>
      </div>

      <div className="card">
        <div className="card-h">
          <div className="card-t"><Radio size={15} color="var(--mint)" />النشاط اللحظي على المنصة</div>
          <span className="badge b-mint"><span className="dot" />{online.map(o => o.name.split(' ')[0]).join('، ') || 'أنت فقط'}</span>
        </div>
        {audit.length === 0 && <div className="empty">لا يوجد نشاط بعد — أي إجراء تقوم به سيظهر هنا لدى بقية المستخدمين.</div>}
        {audit.map(a => (
          <div key={a.id} className="feed">
            <div className="feed-d" />
            <div style={{ flex: 1, minWidth: 0 }}>
              <div><b style={{ fontWeight: 600 }}>{a.userName}</b> <span style={{ color: 'var(--dim)' }}>{a.title}</span></div>
              <div style={{ fontSize: 10.5, color: 'var(--faint)' }}>{a.details} · {arTime(a.timestamp)}</div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ================= الإغلاق اليومي ================= */
function Closing({ org, ops, me, myBranches, scoped, commit, commitOrg, say }) {
  const [open, setOpen] = useState(false);
  const [edit, setEdit] = useState(null);
  const [view, setView] = useState(null);
  const [formKey, setFormKey] = useState(0);
  const canEdit = !!ROLES[me.role]?.create;
  const [q, setQ] = useState('');
  const [st, setSt] = useState('all');
  const [bid, setBid] = useState('all');
  const [fromD, setFromD] = useState('');
  const [toD, setToD] = useState('');
  const [showFilters, setShowFilters] = useState(false);
  const [limit, setLimit] = useState(15);

  const filtered = [...scoped.closings]
    // v15.26/v15.27: قيْد «اليوم فقط» (الكاشير) لا يحجب ما ينتظر عمله — المسودات غير المكتملة
    // والمرفوضات المعادة للتصحيح تظهر دائماً مهما كان تاريخها، بينما السجل المرحّل/المعتمد
    // يبقى لليوم الحالي فقط (منع تصفّح تاريخ المبيعات).
    .filter(c => !ROLES[me.role]?.todayOnly || c.date === today() || c.status === 'draft' || c.status === 'rejected')
    .filter(c => st === 'all' || c.status === st)
    .filter(c => bid === 'all' || c.branchId === bid)
    .filter(c => !fromD || c.date >= fromD)
    .filter(c => !toD || c.date <= toD)
    .filter(c => !q || (c.branchName + c.date + (c.managerName || '')).includes(q))
    .sort((a, b) => b.date.localeCompare(a.date));
  const list = filtered.slice(0, limit);

  const remove = (c) => {
    if (periodLocked(org, c.date)) return say(LOCK_MSG(c.date), 'no');
    return commit(
    d => ({ ...d, closings: d.closings.filter(x => x.id !== c.id), transfers: d.transfers.filter(t => t.closingId !== c.id) }),
    { actionType: 'delete', targetType: 'daily_closing', targetId: c.id, branchName: c.branchName, title: 'حذف إغلاق يومي', details: `${c.branchName} — ${arDate(c.date)}` }
  ).then(() => say('تم حذف الإغلاق'));
  };

  // v15.17 — حذف نهائي لإغلاق مُرحّل/معتمد (للإدارة فقط): تصفير إدخال تجريبي بعينه.
  // القيود المحاسبية مشتقّة حسابيًا من الإغلاقات نفسها (لا نسخة مخزّنة) — فحذف الإغلاق
  // يُصفّر أثره من كل الحسابات والتقارير فورًا وبأثر رجعي، دون أي مساس بغيره من البيانات.
  const removeFinal = (c) => {
    if (periodLocked(org, c.date)) return say(LOCK_MSG(c.date), 'no');
    if (!window.confirm('حذف نهائي لإغلاق «' + c.branchName + ' — ' + arDate(c.date) + '» (إيراد ' + money(c.totalRevenue) + ' ر.س)؟\n\nسيختفي من كل السجلات والتقارير والحسابات فورًا وبأثر رجعي، وتُحذف تحويلاته المرتبطة بالخزينة، ولا يمكن التراجع.\nبقية الإغلاقات وكل البيانات الأخرى لا تتأثر إطلاقًا، ويصبح هذا اليوم قابلًا لإغلاق جديد.')) return;
    return commit(
      d => ({ ...d, closings: d.closings.filter(x => x.id !== c.id), transfers: (d.transfers || []).filter(t => t.closingId !== c.id) }),
      { actionType: 'delete', targetType: 'daily_closing', targetId: c.id, branchName: c.branchName, need: 'edit', title: 'حذف نهائي لإغلاق مُرحّل (تصفير)', details: `${c.branchName} — ${arDate(c.date)} · إيراد ${money(c.totalRevenue)} · كان بحالة ${c.status}` }
    ).then(ok => { if (ok) say('حُذف الإغلاق نهائيًا — وأثره أُزيل من كل الحسابات والتقارير ✓'); });
  };
  const isAdminMe = !!ROLES[me.role]?.admin;

  return (
    <div className="grid" style={{ gap: 14 }}>
      <div className="pagehead">
        <div>
          <h2 className="pagehead-t">الإغلاق اليومي</h2>
          <div className="pagehead-s">مطابقة النقدية وترحيلها للخزينة الرئيسية</div>
        </div>
        {canEdit && (
          <button className="btn pri newclosing-btn" onClick={() => { setEdit(null); setOpen(true); }}>
            <Plus size={16} />إغلاق وردية جديد
          </button>
        )}
      </div>

      {/* زر عائم دائم الظهور على الجوال — لا يختفي بالتمرير */}
      {canEdit && (
        <button className="btn pri fab-new" onClick={() => { setEdit(null); setOpen(true); }} aria-label="فتح نموذج إغلاق وردية جديد">
          <Plus size={20} /><span className="fab-lbl">إغلاق وردية</span>
        </button>
      )}

      <div className="card">
        <div style={{ marginBottom: 14 }}>
          <div className="row" style={{ gap: 8 }}>
            <div className="row" style={{ gap: 7, flex: 1, minWidth: 0 }}>
              <Search size={14} color="var(--faint)" style={{ flexShrink: 0 }} />
              <input className="inp" style={{ flex: 1, minWidth: 0 }} placeholder="بحث سريع..."
                value={q} onChange={e => setQ(e.target.value)} />
            </div>
            <button className={'btn sm' + (showFilters || st !== 'all' || bid !== 'all' || fromD || toD ? ' pri' : ' gh')}
              onClick={() => setShowFilters(v => !v)} style={{ flexShrink: 0 }}>
              <Search size={13} />فلترة
              {(st !== 'all' || bid !== 'all' || fromD || toD) && <span className="num" style={{ marginInlineStart: 3 }}>•</span>}
            </button>
            <span className="badge b-dim" style={{ flexShrink: 0 }}><span className="num">{filtered.length}</span></span>
          </div>
          {showFilters && (
            <div className="card" style={{ padding: 12, marginTop: 10, background: 'var(--ink)' }}>
              <div className="grid g2" style={{ gap: 10 }}>
                <Field label="الحالة">
                  <select className="sel" value={st} onChange={e => setSt(e.target.value)}>
                    <option value="all">كل الحالات</option>
                    <option value="draft">مسودة</option>
                    <option value="submitted">مرحّل للمراجعة</option>
                    <option value="approved">مدقّق ومعتمد</option>
                    <option value="rejected">مرفوض</option>
                  </select>
                </Field>
                {myBranches.length > 1 && (
                  <Field label="الفرع">
                    <select className="sel" value={bid} onChange={e => setBid(e.target.value)}>
                      <option value="all">كل الفروع</option>
                      {myBranches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
                    </select>
                  </Field>
                )}
                <Field label="من تاريخ">
                  <input type="date" className="inp" value={fromD} onChange={e => setFromD(e.target.value)} />
                </Field>
                <Field label="إلى تاريخ">
                  <input type="date" className="inp" value={toD} onChange={e => setToD(e.target.value)} />
                </Field>
              </div>
              {(q || st !== 'all' || bid !== 'all' || fromD || toD) && (
                <button className="btn sm gh" style={{ marginTop: 10 }} onClick={() => { setQ(''); setSt('all'); setBid('all'); setFromD(''); setToD(''); }}>
                  <X size={13} />مسح كل الفلاتر
                </button>
              )}
            </div>
          )}
        </div>
        <div className="tw">
          <table className="tb cards">
            <thead><tr>
              <th>التاريخ</th><th>الفرع</th><th>الإيراد</th><th>المصروف</th>
              <th>المتوقع بالصندوق</th><th>الفعلي</th><th>الفرق</th><th>الحالة</th><th></th>
            </tr></thead>
            <tbody>
              {list.map(c => (
                <tr key={c.id}>
                  <td data-label="التاريخ" style={{ whiteSpace: 'nowrap', fontSize: 12, fontWeight: 600 }}>{arDate(c.date)}</td>
                  <td data-label="الفرع" style={{ fontSize: 12 }}>{c.branchName}</td>
                  <td className="num" data-label="الإيراد" style={{ color: 'var(--brass)' }}>{money(c.totalRevenue)}</td>
                  <td className="num" data-label="المصروف" style={{ color: 'var(--rose)' }}>{money(c.totalExpenses)}</td>
                  <td className="num" data-label="المتوقع بالصندوق">{money(c.expectedCashInSafe)}</td>
                  <td className="num" data-label="الفعلي">{money(c.actualCashCount)}</td>
                  <td className="num" data-label="الفرق" style={{ color: c.variance < 0 ? 'var(--rose)' : c.variance > 0 ? 'var(--mint)' : 'var(--faint)' }}>
                    {c.variance > 0 ? '+' : ''}{money(c.variance)}
                  </td>
                  <td data-label="الحالة"><Badge s={c.status} /></td>
                  <td className="acts">
                    <div className="row" style={{ gap: 5, flexWrap: 'nowrap' }}>
                      <button className="btn sm gh" onClick={() => setView(c)}><Eye size={13} /></button>
                      {canEdit && (c.status === 'draft' || c.status === 'rejected') && (
                        <>
                          <button className="btn sm gh" onClick={() => { setEdit(c); setOpen(true); }}>{c.status === 'rejected' ? 'تصحيح' : 'تعديل'}</button>
                          {c.status === 'draft' && <button className="btn sm gh" onClick={() => remove(c)}><Trash2 size={13} color="#D9544D" /></button>}
                        </>
                      )}
                      {/* v16.9 — بطلب المالك: الإدارة تعدّل الإغلاق المرحّل/المعتمد وتعيده مسودة ليراجعها الكاشير */}
                      {isAdminMe && (c.status === 'submitted' || c.status === 'approved') && (
                        <button className="btn sm gh" title="تعديل الإغلاق وإعادته مسودة ليراجعها الكاشير ويرحّله من جديد (للإدارة)"
                          onClick={() => {
                            if (periodLocked(org, c.date)) return say(LOCK_MSG(c.date), 'no');
                            setEdit(c); setOpen(true);
                          }}>تعديل كمسودة</button>
                      )}
                      {isAdminMe && c.status !== 'draft' && (
                        <button className="btn sm gh" title="حذف نهائي — تصفير هذا الإغلاق من كل السجلات والحسابات (للإدارة)"
                          onClick={() => removeFinal(c)}><Trash2 size={13} color="#D9544D" /></button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
              {list.length === 0 && <tr><td colSpan={9}><div className="empty">
                {scoped.closings.length ? 'لا نتائج مطابقة لبحثك.' : 'لا توجد إغلاقات ضمن نطاقك بعد.'}
              </div></td></tr>}
            </tbody>
          </table>
        </div>
        {filtered.length > limit && (
          <button className="btn" style={{ marginTop: 12 }} onClick={() => setLimit(l => l + 15)}>
            عرض 15 إغلاقاً إضافياً ({filtered.length - limit} متبقٍ)
          </button>
        )}
      </div>

      {open && (
        <ClosingForm key={formKey} org={org} me={me} branches={myBranches} initial={edit} commit={commit} commitOrg={commitOrg} say={say}
          existing={ops.closings || []} invoices={ops.invoices || []} branchPartners={ops.branchPartners || []}
          onStartNew={() => { setEdit(null); setFormKey(k => k + 1); }}
          onClose={() => { setOpen(false); setEdit(null); }} />
      )}
      {view && <ClosingView c={view} org={org} onClose={() => setView(null)} />}
    </div>
  );
}

// ترحيل سدادات الصيغة القديمة {method, amount} إلى خانات التوزيع — حتى لا يضيع المبلغ عند التعديل
function normalizeSupPays(arr) {
  return (arr || []).map(pm => {
    if (pm.cash != null || pm.card != null || pm.transfer != null || pm.other != null) return pm;
    const s = paySplits(pm);
    const { method, amount, ...rest } = pm;
    return { ...rest, ...s };
  });
}

export function ClosingForm({ org, me, branches, initial, commit, commitOrg, say, onClose, onStartNew, existing = [], invoices = [], branchPartners = [] }) {
  const [f, setF] = useState(() => initial ? { ...initial, supplierPayments: normalizeSupPays(initial.supplierPayments) } : {
    date: today(), branchId: branches[0]?.id || '',
    openingBalance: branches[0]?.defaultFloat || 0,
    cashSales: 0, cardSales: 0, bankTransferSales: 0,
    deliverySales: (org.deliveryApps || APPS).map(a => ({ appId: a.id, appName: a.n, amount: 0, orderCount: 0, commissionPercentage: a.c })),
    expenses: [], supplierPayments: [], denominationDetails: emptyDenoms(),
    transferredToMainTreasury: 0, varianceReason: '', notes: ''
  });
  const [secs, setSecs] = useState(() => {
    const d = initial || {};
    return {
      sales: true,
      network: (d.cardSales || 0) > 0 || (d.bankTransferSales || 0) > 0,
      delivery: sum(d.deliverySales || [], x => x.amount) > 0,
      expenses: (d.expenses || []).length > 0,
      inventory: true,
      transfer: (d.transferredToMainTreasury || 0) > 0 || !!d.treasuryChoice,
      supplierPay: (d.supplierPayments || []).length > 0,
      notes: !!(d.notes || d.managerSignature || d.sessionPhoto || (d.sessionPhotos || []).length),
    };
  });
  const toggleSec = (k) => setSecs(p => {
    const willOpen = !p[k];
    // على الجوال: قسم واحد مفتوح في كل مرة (أكورديون)
    if (willOpen && typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(max-width:640px)').matches) {
      return { sales: false, network: false, delivery: false, expenses: false, inventory: false, transfer: false, supplierPay: false, notes: false, [k]: true };
    }
    return { ...p, [k]: !p[k] };
  });
  const allSecsOpen = Object.values(secs).every(Boolean);
  const setAllSecs = (v) => setSecs({ sales: v, network: v, delivery: v, expenses: v, inventory: v, transfer: v, supplierPay: v, notes: v });
  const [cam, setCam] = useState(false);
  const [sumOpen, setSumOpen] = useState(false);
  const [outPrompt, setOutPrompt] = useState(false);
  const [pend, setPend] = useState(null);
  const [done, setDone] = useState(null);
  const [newParty, setNewParty] = useState(null);   // إضافة مورد/موظف/عميل إلى الرئيسي من الإغلاق
  const set = (k, v) => setF(p => ({ ...p, [k]: v }));
  const branch = org.branches.find(b => b.id === f.branchId);

  const totalDelivery = sum(f.deliverySales, d => d.amount);
  const totalRevenue = f.cashSales + f.cardSales + (f.bankTransferSales || 0) + totalDelivery;
  const cashExp = sum(f.expenses.filter(e => e.paymentMethod === 'cash'), e => e.amount);
  const totalExp = sum(f.expenses, e => e.amount);
  const supPays = f.supplierPayments || [];
  const totalSupplierPay = sum(supPays, payTotal);
  const cashSupplierPay = sum(supPays, payCashPart);
  // السداد النقدي للموردين يخرج من الصندوق فيقلّل النقد المتوقع (لضبط الجرد)
  const expected = f.openingBalance + f.cashSales - cashExp - cashSupplierPay;
  const actual = countDenoms(f.denominationDetails);
  const variance = Math.round((actual - expected) * 100) / 100;
  // v16.8 — يوم بلا نقد متوقع (مبيعات شبكة/تحويل فقط، لا عهدة): الجرد صفر منطقي ولا يعيق الترحيل
  const zeroCashDay = Math.abs(expected) <= 0.004;
  const retained = Math.max(0, actual - f.transferredToMainTreasury);

  const setDen = (k, v) => set('denominationDetails', { ...f.denominationDetails, [k]: Math.max(0, v) });
  // v15.18 — صور توثيق متعددة عند الترحيل، بتوافق خلفي كامل: الإغلاقات القديمة بحقلها
  // المفرد sessionPhoto تُعرض وتعمل كما هي، والجديدة تحمل sessionPhotos + أول صورة تُنسخ
  // في sessionPhoto نفسه حتى تبقى كل الشاشات/التقارير/الأرشفة القديمة صحيحة بلا تعديل.
  const sPhotos = f.sessionPhotos || (f.sessionPhoto ? [f.sessionPhoto] : []);
  const setPhotos = (arr) => setF(p => ({ ...p, sessionPhotos: arr, sessionPhoto: arr[0] || '' }));
  const addDelivApp = () => set('deliverySales', [...f.deliverySales, { appId: uid('app'), appName: '', amount: 0, orderCount: 0, commissionPercentage: 0, custom: true }]);
  const upDeliv = (i, k, v) => { const n = [...f.deliverySales]; n[i] = { ...n[i], [k]: v }; set('deliverySales', n); };
  const removeDeliv = (i) => set('deliverySales', f.deliverySales.filter((_, x) => x !== i));

  // شركاء الرئيسي المتاحون للربط (موردون + موظفون + عملاء) + شركاء هذا الفرع تحديدًا (لم يُرقَّوا بعد)
  const myBranchPartners = (branchPartners || []).filter(bp => bp.branchId === f.branchId);
  const partyOptions = buildPartners(org, { branchPartners: myBranchPartners }).map(p => ({
    key: p.key, id: p.id, name: p.name, type: (PT_TYPE[p.type] || {}).ar || 'عميل', rawType: p.type, code: p.code,
    source: p.source || 'org', branchOriginName: p.branchOriginName || ''
  }));
  // منع التكرار: هل هذا الاسم (بنفس النوع) موجود مسبقًا ضمن الخيارات المتاحة؟
  const findPartyByName = (name, type) => {
    const q = (name || '').trim().toLowerCase();
    if (!q) return null;
    const t = type === 'supplier' ? 'supplier' : type === 'employee' ? 'employee' : (type || 'customer');
    return partyOptions.find(o => o.name.trim().toLowerCase() === q && o.rawType === t) || null;
  };
  const linkExpParty = (expId, key, name, supplierId) =>
    set('expenses', f.expenses.map(x => x.id === expId ? { ...x, partnerKey: key || undefined, beneficiaryName: name != null ? name : x.beneficiaryName, supplierId } : x));
  const linkPayParty = (payId, key, name, supplierId) =>
    set('supplierPayments', (f.supplierPayments || []).map(x => x.id === payId ? { ...x, partnerKey: key || undefined, supplierName: name != null ? name : x.supplierName, supplierId } : x));
  // سداد الموردين داخل الإغلاق
  const addSupPay = () => set('supplierPayments', [...(f.supplierPayments || []), { id: uid('sp'), partnerKey: '', supplierName: '', cash: 0, card: 0, transfer: 0, other: 0, reference: '' }]);
  const upSupPay = (id, k, v) => set('supplierPayments', (f.supplierPayments || []).map(x => x.id === id ? { ...x, [k]: v } : x));
  const removeSupPay = (id) => set('supplierPayments', (f.supplierPayments || []).filter(x => x.id !== id));
  // مع المصادقة السحابية: كتابة سجل الرئيسي للمدراء فقط — غير الإداري يرسل «طلب اعتماد» بدل كتابة تُرفض
  const canWriteOrg = !(typeof window !== 'undefined' && window.__forceOrgReadonly) && (!authApi.enabled || !!ROLES[me.role]?.admin);

  // حفظ شريك جديد في الرئيسي وربطه بالمصروف/السداد — هذا ما يجعله «ينضاف إلى الرئيسي»
  const saveParty = async () => {
    const np = newParty;
    if (!np.name || !np.name.trim()) return say('اكتب اسم الشريك', 'no');
    const nameQ = np.name.trim();
    // منع التكرار: لو الاسم موجود مسبقًا بنفس النوع (مركزيًا أو في دفتر هذا الفرع) نربط بالبطاقة القائمة بدل تكرارها
    const dupe = findPartyByName(nameQ, np.type);
    if (dupe) {
      if (np.target === 'pay') linkPayParty(np.rowId, dupe.key, dupe.name, dupe.rawType === 'supplier' ? dupe.id : undefined);
      else linkExpParty(np.rowId, dupe.key, dupe.name, dupe.rawType === 'supplier' ? dupe.id : undefined);
      say('«' + dupe.name + '» موجود مسبقًا (' + dupe.code + ') — رُبطت الحركة به بدل تكراره ✓');
      setNewParty(null);
      return;
    }
    if (!canWriteOrg) {
      // v15.14: دور غير إداري: يُضاف فورًا إلى دفتر شركاء هذا الفرع (بلا انتظار اعتماد)، ويُربط بالسطر مباشرة،
      // ويظهر مُجمَّعًا في دفتر الشركاء بالرئيسي — والإدارة تقدر ترقّيه لاحقًا للسجل الرسمي بضغطة واحدة.
      const id = uid('bp');
      const type = np.type === 'supplier' ? 'supplier' : np.type === 'employee' ? 'employee' : (np.type || 'customer');
      const key = (type === 'supplier' ? 'sup:' : type === 'employee' ? 'emp:' : 'cust:') + id;
      const code = nextPartnerCode(buildPartners(org, { branchPartners: myBranchPartners }), type);
      const bp = { id, key, type, name: nameQ, cat: np.cat || '', phone: np.phone || '', code, branchId: f.branchId, branchName: branch?.name || '', createdBy: me.name, at: nowISO() };
      const ok = await commit(d => ({ ...d, branchPartners: [bp, ...(d.branchPartners || [])] }), {
        actionType: 'create', targetType: 'user_account', targetId: id,
        title: 'أضاف شريكاً لدفتر الفرع', details: nameQ + ' — ' + (PT_TYPE[type] || { ar: 'عميل' }).ar + ' · فرع ' + (branch?.name || '')
      });
      if (ok) {
        if (np.target === 'pay') linkPayParty(np.rowId, key, nameQ, type === 'supplier' ? id : undefined);
        else linkExpParty(np.rowId, key, nameQ, type === 'supplier' ? id : undefined);
        say('أُضيف «' + nameQ + '» لدفتر شركاء الفرع ورُبط بالسطر فورًا ✓');
        setNewParty(null);
      }
      return;
    }
    if (!commitOrg) return say('لا تملك صلاحية الإضافة للرئيسي', 'no');
    const name = nameQ, id = uid('pt');
    const code = nextPartnerCode(buildPartners(org, { branchPartners: myBranchPartners }), np.type === 'supplier' ? 'supplier' : np.type === 'employee' ? 'employee' : (np.type || 'customer'));
    let key, mut;
    if (np.type === 'supplier') { key = 'sup:' + id; mut = d => ({ ...d, suppliers: [...(d.suppliers || []), { id, code, name, category: np.cat || '', phone: np.phone || '', vatNo: '', address: '', taxable: false, terms: 0 }] }); }
    else if (np.type === 'employee') { key = 'emp:' + id; mut = d => ({ ...d, employees: [...(d.employees || []), { id, code, name, jobTitle: np.cat || '', phone: np.phone || '', baseSalary: 0, housingAllowance: 0, transportAllowance: 0, branchId: f.branchId, isActive: true }] }); }
    else { key = 'cust:' + id; mut = d => ({ ...d, partners: [...(d.partners || []), { id, key, code, name, type: np.type, cat: np.cat || '', phone: np.phone || '', tax: '', terms: 0 }] }); }
    await commitOrg(mut, { actionType: 'create', targetType: 'user_account', targetId: id, title: 'أضاف شريكاً للرئيسي من الإغلاق', details: name + ' — ' + (PT_TYPE[np.type] || { ar: 'عميل' }).ar });
    if (np.target === 'pay') linkPayParty(np.rowId, key, name, np.type === 'supplier' ? id : undefined);
    else linkExpParty(np.rowId, key, name, np.type === 'supplier' ? id : undefined);
    say('أُضيف إلى دفتر الشركاء بالرئيسي ✓'); setNewParty(null);
  };
  const addExp = () => set('expenses', [...f.expenses, {
    id: uid('ex'), categoryId: (org.expenseCats || EXP_CATS)[0]?.id, categoryName: (org.expenseCats || EXP_CATS)[0]?.n,
    amount: 0, paymentMethod: 'cash', beneficiaryName: '', receiptNumber: '',
    isTaxable: true, taxInvoice: false
  }]);
  const upExp = (id, k, v) => set('expenses', f.expenses.map(e => {
    if (e.id !== id) return e;
    const n = { ...e, [k]: v };
    if (k === 'categoryId') {
      const c = (org.expenseCats || EXP_CATS).find(x => x.id === v);
      n.categoryName = c?.n || '';
      if (!e.taxTouched) n.isTaxable = !!c?.taxable; // احترام تعديل المستخدم اليدوي
    }
    if (k === 'isTaxable') n.taxTouched = true;
    return n;
  }));

  // v16.9 — الإدارة تعدّل إغلاقاً مرحّلاً/معتمداً: يعود مسودةً حصراً ليراجعها الكاشير
  const demoteMode = !!(initial && (initial.status === 'submitted' || initial.status === 'approved'));

  // بناء سجل الإغلاق بعد التحقّق (يعيد null عند فشل التحقّق)
  const buildRecord = (status) => {
    if (!f.branchId) { say('اختر الفرع أولاً', 'no'); return null; }
    if (totalRevenue <= 0) { say('أدخل مبيعات الوردية قبل الحفظ', 'no'); return null; }
    // المرفوض لا يمنع إعادة إغلاق اليوم — حتى لا يُقفل اليوم نهائيًا بعد الرفض
    const dup = existing.find(c => c.branchId === f.branchId && c.date === f.date && c.id !== initial?.id && c.status !== 'rejected');
    if (dup) { say('يوجد إغلاق مسجّل لهذا الفرع بنفس التاريخ — عدّل الإغلاق القائم بدل إنشاء نسخة ثانية', 'no'); return null; }
    if (status === 'submitted') {
      // v16.8: كان يُشترط عدّ موجب دائمًا — فيوم كل مبيعاته شبكة (صندوق صفر) يستحيل إغلاقه.
      // الآن: لا نقد متوقع ← يمر مباشرة؛ نقد متوقع وصندوق فارغ فعلًا ← إقرار صريح + توثيق سبب العجز.
      if (actual <= 0 && !zeroCashDay && !f.zeroCashConfirmed) {
        say('أكمل جرد الفئات النقدية قبل الترحيل — وإن كان الصندوق فارغًا فعلًا فعلّم «الصندوق فارغ» في قسم الجرد', 'no');
        return null;
      }
      if (variance !== 0 && !f.varianceReason.trim()) { say('وثّق سبب العجز أو الفائض قبل الترحيل', 'no'); return null; }
      if (f.transferredToMainTreasury > actual) { say('المرحّل للخزينة يتجاوز النقد المعدود', 'no'); return null; }
      // v15.18: صورة التوثيق إجبارية لكل الأدوار عدا الكاشير (بطلب صريح من المالك) — تبقى متاحة له اختيارياً
      if (me.role !== 'cashier' && sPhotos.length === 0) { say('التقط صورة توثيق المسؤول قبل الترحيل — إجباري', 'no'); return null; }
    }
    const id = initial?.id || 'cl-' + f.branchId + '-' + f.date + '-' + Math.random().toString(36).slice(2, 5);
    const ref = 'TR-' + f.date.replace(/-/g, '') + '-' + f.branchId.slice(-2);
    const rec = {
      ...f, id, branchName: branch?.name || '', managerName: me.name,
      sessionPhotos: sPhotos, sessionPhoto: sPhotos[0] || '',
      deliverySales: f.deliverySales.map(d => ({ ...d, commissionAmount: Math.round(d.amount * (d.commissionPercentage || 0)) / 100 })),
      totalDeliverySales: totalDelivery, otherRevenues: [], totalOtherRevenues: 0,
      totalRevenue, totalExpenses: totalExp, totalCashExpenses: cashExp,
      totalCardExpenses: sum(f.expenses.filter(e => e.paymentMethod === 'card'), e => e.amount),
      expectedCashInSafe: expected, actualCashCount: actual, variance,
      retainedFloatForTomorrow: retained, transferReferenceNo: ref,
      transferStatus: 'pending', status, gmApprovalStatus: 'pending',
      rejectionReason: status === 'submitted' ? '' : (f.rejectionReason || ''),
      // v16.9: عند العودة مسودةً تُمسح آثار التدقيق السابقة — دورة اعتماد جديدة نظيفة
      ...(status === 'draft' ? { auditedBy: '', auditNote: '' } : {}),
      createdBy: me.name, createdAt: initial?.createdAt || nowISO(), updatedAt: nowISO()
    };
    return { rec: { ...rec, closingNo: ref }, id, ref };
  };

  // إتمام الحفظ فعلياً + قيد التدقيق (out = بيانات الإخراج عند الإتمام)
  const finalize = async (status, recIn, id, ref, out) => {
    if (periodLocked(org, f.date)) return say(LOCK_MSG(f.date), 'no');
    const rec = { ...recIn, completion: out ? { ...out, at: nowISO(), by: me.name } : (recIn.completion || null) };
    // v15.18: نتحقق من نجاح الحفظ فعلياً — فشل الحفظ سابقاً كان يُتجاهَل فيظهر «تم الحفظ»
    // ويُغلق النموذج بينما لم يُكتب شيء للسحابة (فتختفي المسودة). الآن: عند الفشل تبقى
    // النافذة مفتوحة ببياناتها كاملة ليعيد المستخدم المحاولة (رسالة الخطأ يعرضها commit).
    const okSave = await commit(d => {
      // سياسة الاحتفاظ: بعد 60 يومًا تُنظَّف الصور من سجل الإغلاق (تبقى نسخها في أرشيف المستندات) لكبح تضخم التخزين
      const cutoff = new Date(Date.now() - 60 * 864e5).toISOString().slice(0, 10);
      const pruneImgs = (c) => {
        if (c.imagesPruned || !c.date || c.date >= cutoff || c.status === 'draft') return c;
        if (!c.sessionPhoto && !(c.sessionPhotos || []).length && !c.cardReceiptImage && !(c.expenses || []).some(e => e.receiptImage)) return c;
        return { ...c, sessionPhoto: '', sessionPhotos: [], cardReceiptImage: '', expenses: (c.expenses || []).map(e => e.receiptImage ? { ...e, receiptImage: '' } : e), imagesPruned: true };
      };
      const closings = [rec, ...d.closings.filter(c => c.id !== id)].map(pruneImgs);
      let transfers = d.transfers.filter(t => t.closingId !== id);
      if (status === 'submitted' && rec.transferredToMainTreasury > 0) {
        transfers = [{
          id: uid('tr'), closingId: id, date: f.date, branchId: f.branchId, branchName: rec.branchName,
          amount: rec.transferredToMainTreasury, referenceNo: ref, status: 'pending'
        }, ...transfers];
      }
      let notifications = d.notifications || [];
      if (status === 'submitted') {
        notifications = [{
          id: uid('n'), type: 'closing_submitted', title: 'إغلاق جديد بانتظار التدقيق',
          message: `${rec.branchName} — ${arDate(f.date)} · إيراد ${money(totalRevenue)} ر.س`,
          severity: variance < 0 ? 'high' : 'medium', branchId: f.branchId, closingId: id,
          date: f.date, createdAt: nowISO(), isRead: false
        }, ...notifications].slice(0, 60);
        if (variance < 0) notifications = [{
          id: uid('n'), type: 'cash_deficit', title: 'عجز نقدي في الصندوق',
          message: `${rec.branchName}: عجز بمقدار ${money(Math.abs(variance))} ر.س بتاريخ ${arDate(f.date)}`,
          severity: 'high', branchId: f.branchId, date: f.date, createdAt: nowISO(), isRead: false
        }, ...notifications].slice(0, 60);
      }
      // v16.9: الإدارة أعادت إغلاقاً مرحّلاً/معتمداً إلى مسودة — إشعار حتى يراجعه الكاشير ويرحّله
      if (status === 'draft' && demoteMode) {
        notifications = [{
          id: uid('n'), type: 'closing_reverted', title: 'إغلاق أُعيد مسودةً للمراجعة',
          message: `${rec.branchName} — ${arDate(f.date)} · عدّلته الإدارة (${me.name}) وأعادته مسودة — راجعه ورحّله من جديد`,
          severity: 'medium', branchId: f.branchId, closingId: id, date: f.date, createdAt: nowISO(), isRead: false
        }, ...notifications].slice(0, 60);
      }
      return { ...d, closings, transfers, notifications };
    }, {
      actionType: initial ? 'update' : 'create', targetType: 'daily_closing', targetId: id,
      branchId: f.branchId, branchName: rec.branchName,
      title: status === 'submitted' ? 'إتمام وترحيل إغلاق وردية'
        : (demoteMode ? 'أعادت الإدارة إغلاقاً مرحّلاً إلى مسودة للمراجعة' : 'حفظ مسودة إغلاق'),
      details: `${rec.branchName} — ${arDate(f.date)} · إيراد ${money(totalRevenue)} · فرق ${money(variance)}`
        + (out ? ` · إخراج: ${out.outputMethod} · جهاز: ${out.device} · بصمة ${(out.reportHash || '').slice(0, 10)}` : ''),
      ...(out ? {
        closingNo: ref, outputMethod: out.outputMethod, printerSize: out.thermalSize,
        pdfStatus: out.pdfStatus, printStatus: out.printStatus, printAttempts: out.printAttempts,
        device: out.device, browser: out.browser, reportHash: out.reportHash
      } : {})
    });
    if (!okSave) { setOutPrompt(false); setPend(null); return; }   // v15.18: لا نجاح زائف — البيانات باقية أمامك، أعد المحاولة

    // ترحيل صور الإغلاق إلى أرشيف المستندات، مرتّبة حسب الفرع واليوم
    let archivedCount = 0;
    try {
      const stamp = arDate(f.date);
      const docs = [];
      const push = (img, cat, catLabel, title, amount) => {
        if (!img) return;
        const pdfA = typeof img === 'string' && img.startsWith('data:application/pdf');
        docs.push({
          id: 'arc-' + id + '-' + cat + (docs.length),
          title, category: cat, categoryLabelAr: catLabel,
          branchId: f.branchId, branchName: rec.branchName,
          fileUrl: img, fileType: pdfA ? 'pdf' : 'image', fileName: title + (pdfA ? '.pdf' : '.jpg'),
          fileSizeKb: Math.round(img.length * 0.75 / 1024),
          uploadDate: f.date, uploadedBy: me.name, amount: amount || 0,
          closingId: id, source: 'closing', uploadedAt: nowISO()
        });
      };
      push(f.cardReceiptImage, 'pos_settlement', 'إثبات شبكة/تحويل', `إثبات الشبكة — ${rec.branchName} ${stamp}`, rec.cardSales);
      (rec.sessionPhotos && rec.sessionPhotos.length ? rec.sessionPhotos : (rec.sessionPhoto ? [rec.sessionPhoto] : []))
        .forEach((img, i, arr) => push(img, 'signature', 'توثيق المسؤول', `توثيق الإغلاق${arr.length > 1 ? ' ' + (i + 1) : ''} — ${rec.branchName} ${stamp}`, 0));
      (f.expenses || []).forEach((e) => push(e.receiptImage, 'expense', 'فاتورة مصروف',
        `${e.categoryName || 'مصروف'}${e.beneficiaryName ? ' — ' + e.beneficiaryName : ''} (${stamp})`, e.amount));

      if (docs.length) {
        const store = await cloud.get(bfKey(f.branchId), { items: [] });
        const prevItems = (store && Array.isArray(store.items)) ? store.items : [];
        const kept = prevItems.filter(x => x.closingId !== id);
        await cloud.set(bfKey(f.branchId), { items: [...docs, ...kept].slice(0, 1500) });
        archivedCount = docs.length;
      }
    } catch (err) { /* الأرشفة تكميلية — لا توقف حفظ الإغلاق */ }

    setOutPrompt(false); setPend(null);
    if (status === 'submitted') {
      say(archivedCount ? `تم إغلاق الوردية ✓ ورُحّل ${archivedCount} مستندًا للأرشيف` : 'تم إغلاق الوردية بنجاح ✓');
      setDone({ branchName: rec.branchName, total: totalRevenue, ref, docsArchived: archivedCount });
    } else {
      say(demoteMode ? 'أُعيد الإغلاق مسودةً وأُشعر الفرع — يراجعه الكاشير ويرحّله من جديد ✓' : 'تم حفظ المسودة');
      onClose();
    }
  };

  // المسودة تُحفظ مباشرة؛ أمّا الإتمام فيتطلب خطوة الإخراج الرسمية أولاً (#21)
  const save = (status) => {
    const built = buildRecord(status);
    if (!built) return;
    if (status === 'submitted') { setPend(built); setOutPrompt(true); }
    else finalize(status, built.rec, built.id, built.ref, null);
  };

  const vatDeduct = sum(f.expenses.filter(e => e.isTaxable), e => e.amount) * 15 / 115;
  // v16.8: الجرد يُعد مكتملاً أيضاً عندما لا نقد متوقع أصلاً (0.00 منطقية) أو أقرّ المستخدم بفراغ الصندوق
  const counted = actual > 0 || zeroCashDay || !!f.zeroCashConfirmed; // لم يُجرد الصندوق بعد؟ لا نُظهر عجزاً وهمياً
  const vColor = !counted ? 'var(--faint)' : variance < 0 ? 'var(--rose)' : variance > 0 ? 'var(--mint)' : 'var(--faint)';
  const vStat = !counted
    ? { c: 'var(--sky)', bg: 'rgba(91,147,196,.10)', bd: 'rgba(91,147,196,.40)', ic: '◔', t: 'أكمل جرد الصندوق (الخطوة ٣) لحساب الفرق' }
    : variance === 0
      ? { c: 'var(--mint)', bg: 'rgba(79,178,134,.12)', bd: 'rgba(79,178,134,.45)', ic: '✔', t: 'الصندوق مطابق — لا يوجد ما يمنع الترحيل' }
      : variance < 0
        ? { c: 'var(--rose)', bg: 'rgba(217,84,77,.12)', bd: 'rgba(217,84,77,.45)', ic: '⚠', t: `عجز ${money(Math.abs(variance))} ر.س — التوثيق إلزامي قبل الترحيل` }
        : { c: 'var(--amber)', bg: 'rgba(224,164,88,.12)', bd: 'rgba(224,164,88,.45)', ic: '▲', t: `فائض ${money(variance)} ر.س — راجع إدخالات المبيعات والمصروفات` };
  const summaryRows = (
    <>
      <div className="esum-h">ملخّص النظام · حيّ</div>
      <div className="esum-hero" style={{ borderColor: vStat.bd, background: vStat.bg }}>
        <div className="esum-hero-l">الفرق (الفعلي − المتوقع)</div>
        <div className="esum-hero-v num" style={{ color: vStat.c }}>{counted ? (variance > 0 ? '+' : '') + money(variance) : '—'}</div>
        <div className="esum-badge" style={{ color: vStat.c, borderColor: vStat.bd, background: vStat.bg }}>
          <span>{vStat.ic}</span><span>{!counted ? 'بانتظار الجرد' : variance === 0 ? 'الصندوق متوازن' : variance < 0 ? 'عجز نقدي' : 'فائض نقدي'}</span>
        </div>
      </div>
      <div className="esum-row"><span className="k">المبيعات</span><span className="v num" style={{ color: 'var(--brass)' }}>{money(totalRevenue)}</span></div>
      <div className="esum-row sub"><span className="k">— نقدي</span><span className="v num">{money(f.cashSales)}</span></div>
      <div className="esum-row sub"><span className="k">— شبكة وتحويل</span><span className="v num">{money(f.cardSales + (f.bankTransferSales || 0))}</span></div>
      <div className="esum-row sub"><span className="k">— توصيل</span><span className="v num">{money(totalDelivery)}</span></div>
      <div className="esum-row"><span className="k">المصروفات</span><span className="v num" style={{ color: 'var(--rose)' }}>{money(totalExp)}</span></div>
      <div className="esum-row"><span className="k">المتوقع بالصندوق</span><span className="v num">{money(expected)}</span></div>
      <div className="esum-row"><span className="k">العدّ الفعلي</span><span className="v num" style={{ color: 'var(--brass)' }}>{counted ? money(actual) : '—'}</span></div>
      <div className="esum-row"><span className="k">ض.ق.م القابلة للخصم</span><span className="v num" style={{ color: 'var(--mint)' }}>{money(vatDeduct)}</span></div>
      <div className="esum-net"><span className="k">صافي اليوم</span><span className="v num">{money(totalRevenue - totalExp)}</span></div>
      <div className="cflow-alert" style={{ border: `1px solid ${vStat.bd}`, background: vStat.bg, color: vStat.c, marginTop: 12 }}><span>{vStat.ic}</span><span>{vStat.t}</span></div>
    </>
  );

  const sec = (k, Ic, title, subt, valNode, done, body) => (
    <div className={'esec' + (secs[k] ? ' open' : '') + (done ? ' done' : '')}>
      <button type="button" className="esec-h" onClick={() => toggleSec(k)} aria-expanded={secs[k]}>
        <span className="esec-ic">{done ? <Check size={16} /> : <Ic size={16} />}</span>
        <span className="esec-t"><b>{title}</b><span>{subt}</span></span>
        {valNode != null && <span className="esec-v">{valNode}</span>}
        <ChevronDown size={16} className="esec-chv" />
      </button>
      {secs[k] && <div className="esec-b">{body}</div>}
    </div>
  );

  return (
    <Modal wide flow title={initial ? 'تعديل إغلاق وردية' : 'إغلاق وردية جديد'} icon={ClipboardCheck} onClose={onClose}
      sub={`${branch?.name || 'اختر الفرع'} · ${arDate(f.date)}${initial?.transferReferenceNo ? ' · ' + initial.transferReferenceNo : ''} · ${initial ? (initial.status === 'submitted' ? 'مُرحّل' : 'مسودة') : 'إغلاق جديد'}`}
      foot={demoteMode ? <>
        {/* v16.9: تعديل الإدارة لإغلاق مرحّل/معتمد — الحفظ الوحيد المتاح هو مسودة ليراجعها الكاشير */}
        <button className="btn pri" onClick={() => save('draft')}><FileText size={14} />حفظ كمسودة ليراجعها الكاشير</button>
        <button className="btn gh" onClick={onClose}>إلغاء</button>
      </> : <>
        <button className="btn pri" onClick={() => save('submitted')}><Send size={14} />ترحيل للإدارة المالية</button>
        <button className="btn" onClick={() => save('draft')}>حفظ كمسودة</button>
        <button className="btn gh" onClick={onClose}>إلغاء</button>
      </>}>

      <div className="cflow">
        <div className="cflow-main">
          <div className={'cflow-msum' + (sumOpen ? ' open' : '')}>
            <button type="button" className="cflow-msum-bar" onClick={() => setSumOpen(o => !o)}>
              <span className="msum-i"><small>صافي اليوم</small><b className="num" style={{ color: 'var(--mint)' }}>{money(totalRevenue - totalExp)}</b></span>
              <span className="msum-i"><small>الفرق</small><b className="num" style={{ color: vColor }}>{counted ? money(variance) : '—'}</b></span>
              <span className="msum-chv">الملخّص ▾</span>
            </button>
            <div className="cflow-msum-full">{summaryRows}</div>
          </div>
          <div className="cflow-form">
            <div className="eclose-tools">
              <span className="hint">أقسام قابلة للطي — املأ ما يلزم، والملخّص يتحدّث فورًا</span>
              <button type="button" className="btn sm gh" onClick={() => setAllSecs(!allSecsOpen)}>{allSecsOpen ? 'طيّ الكل' : 'توسيع الكل'}</button>
            </div>

            {sec('sales', Banknote, 'النقد والمبيعات', 'الفرع والتاريخ + العهدة والنقدي', <span className="num">{money(f.cashSales)}</span>, f.cashSales > 0, (
              <>
                <div className="grid g2">
                  <Field label="الفرع">
                    {branches.length <= 1 ? (
                      <div className="inp" style={{ display: 'flex', alignItems: 'center', background: 'var(--ink2)', color: 'var(--txt)', fontWeight: 600 }}>
                        {branch?.name || branches[0]?.name || '—'}
                      </div>
                    ) : (
                      <select className="sel" value={f.branchId} disabled={ROLES[me.role]?.scope === 'own' && !!initial}
                        onChange={e => { const b = org.branches.find(x => x.id === e.target.value); setF(p => ({ ...p, branchId: e.target.value, openingBalance: b?.defaultFloat || 0 })); }}>
                        {branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
                      </select>
                    )}
                  </Field>
                  <Field label="تاريخ الوردية">
                    <input type="date" className="inp" value={f.date} onChange={e => set('date', e.target.value)} />
                  </Field>
                </div>
                <div className="grid g2">
                  <Num label="العهدة الافتتاحية" value={f.openingBalance} onChange={v => set('openingBalance', v)} hint="رصيد بداية الوردية" />
                  <Num label="مبيعات نقدية (كاش)" value={f.cashSales} onChange={v => set('cashSales', v)} sum />
                </div>
              </>
            ))}

            {sec('network', CreditCard, 'الشبكة والتحويل', 'مدى/فيزا + تحويل بنكي مباشر', <span className="num">{money(f.cardSales + (f.bankTransferSales || 0))}</span>, (f.cardSales > 0 || f.bankTransferSales > 0), (
              <>
                <div className="grid g2">
                  <Num label="مبيعات الشبكة (مدى/فيزا)" value={f.cardSales} onChange={v => set('cardSales', v)} sum />
                  <Num label="مبيعات تحويل بنكي مباشر" value={f.bankTransferSales} onChange={v => set('bankTransferSales', v)} />
                </div>
                {(f.cardSales > 0 || f.bankTransferSales > 0) && (
                  <div className="card" style={{ background: 'var(--ink)', padding: 12, marginTop: 4 }}>
                    <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 8 }}>
                      <div>
                        <div style={{ fontSize: 12.5, fontWeight: 600 }}>إثبات تحصيل الشبكة / التحويل</div>
                        <div style={{ fontSize: 10.5, color: 'var(--faint)' }}>صورة إشعار الشبكة أو سند التحويل — اختياري لكنه يوثّق المبلغ</div>
                      </div>
                      <PhotoField value={f.cardReceiptImage} onChange={v => set('cardReceiptImage', v)} say={say} />
                    </div>
                  </div>
                )}
              </>
            ))}

            {sec('delivery', Truck, 'تطبيقات التوصيل', 'هنقرستيشن · كيتا · جاهز', <span className="num">{money(totalDelivery)}</span>, totalDelivery > 0, (
              <>
                <div className="row" style={{ justifyContent: 'space-between', marginBottom: 10 }}>
                  <div className="lbl" style={{ margin: 0 }}>مبيعات تطبيقات التوصيل</div>
                  <button className="btn sm" onClick={addDelivApp}><Plus size={13} />إضافة تطبيق</button>
                </div>
                {f.deliverySales.map((d, i) => (
                  <div key={d.appId} className="card" style={{ background: 'var(--ink)', padding: 12, marginBottom: 9 }}>
                    <div className="row" style={{ justifyContent: 'space-between', alignItems: 'center', marginBottom: 9, gap: 8, flexWrap: 'wrap' }}>
                      {d.custom
                        ? <input className="inp" style={{ maxWidth: 170, minHeight: 38 }} placeholder="اسم التطبيق"
                            value={d.appName} onChange={e => upDeliv(i, 'appName', e.target.value)} />
                        : <div style={{ fontSize: 14, fontWeight: 700 }}>{d.appName}</div>}
                      <div className="row" style={{ gap: 6, alignItems: 'center' }}>
                        {d.custom
                          ? <span className="row" style={{ gap: 4, alignItems: 'center' }}>
                              <span style={{ fontSize: 11, color: 'var(--dim)' }}>عمولة</span>
                              <input className="inp n" style={{ maxWidth: 56, minHeight: 38, textAlign: 'center' }} inputMode="decimal" placeholder="%"
                                value={d.commissionPercentage === 0 ? '' : d.commissionPercentage}
                                onChange={e => upDeliv(i, 'commissionPercentage', Number(e.target.value.replace(/[^\d.]/g, '')) || 0)} />
                              <span style={{ fontSize: 11, color: 'var(--dim)' }}>%</span>
                            </span>
                          : <span className="badge b-dim">عمولة <span className="num">{d.commissionPercentage}%</span></span>}
                        {d.custom && <button className="btn sm gh" onClick={() => removeDeliv(i)}><Trash2 size={13} color="#D9544D" /></button>}
                      </div>
                    </div>
                    <div className="grid g2" style={{ gap: 9 }}>
                      <div className="fld" style={{ margin: 0 }}>
                        <label className="lbl">مبيعات التطبيق · يقبل عدة مبالغ</label>
                        <MoneyField value={d.amount} sum onChange={v => upDeliv(i, 'amount', v)} />
                      </div>
                      <div className="fld" style={{ margin: 0 }}>
                        <label className="lbl">عدد الطلبات</label>
                        <input className="inp n" inputMode="numeric" placeholder="0" value={d.orderCount === 0 ? '' : d.orderCount}
                          onChange={e => upDeliv(i, 'orderCount', Number(e.target.value.replace(/[^\d]/g, '')) || 0)} />
                      </div>
                    </div>
                  </div>
                ))}
                <div className="mono-b" style={{ marginTop: 12, borderColor: 'var(--brass-d)' }}>
                  <span style={{ fontSize: 12.5 }}>إجمالي إيراد الوردية</span>
                  <span className="num" style={{ fontSize: 17, color: 'var(--brass)', fontWeight: 600 }}>{money(totalRevenue)}</span>
                </div>
              </>
            ))}

            {sec('expenses', Receipt, 'المصروفات والمشتريات', 'مسحوبات ومشتريات الوردية', <span className="num" style={{ color: 'var(--rose)' }}>{money(totalExp)}</span>, f.expenses.length > 0, (
              <>
          <div className="row" style={{ justifyContent: 'space-between', marginBottom: 12 }}>
            <div className="lbl" style={{ margin: 0 }}>مصروفات ومسحوبات الوردية</div>
            <button className="btn sm" onClick={addExp}><Plus size={13} />إضافة مصروف</button>
          </div>
          {f.expenses.length === 0 && <div className="empty">لا توجد مصروفات مسجلة على هذه الوردية.</div>}
          {f.expenses.map(e => (
            <div key={e.id} className="card" style={{ padding: 12, marginBottom: 9, background: 'var(--ink)' }}>
              <div className="grid g2" style={{ gap: 9 }}>
                <Field label="بند المصروف">
                  <select className="sel" value={e.categoryId} onChange={ev => upExp(e.id, 'categoryId', ev.target.value)}>
                    {(org.expenseCats || EXP_CATS).map(c => <option key={c.id} value={c.id}>{c.n}</option>)}
                  </select>
                </Field>
                <Field label="طريقة الدفع">
                  <select className="sel" value={e.paymentMethod} onChange={ev => upExp(e.id, 'paymentMethod', ev.target.value)}>
                    <option value="cash">نقداً من الصندوق</option>
                    <option value="card">شبكة (نقاط بيع)</option>
                    <option value="cheque">شيك</option>
                    <option value="bank_transfer">تحويل بنكي</option>
                    <option value="deferred">آجل (على الحساب)</option>
                  </select>
                </Field>
              </div>
              <div className="grid g3" style={{ gap: 9 }}>
                <Num label="المبلغ" value={e.amount} onChange={v => upExp(e.id, 'amount', v)} sum />
                <Field label="المستفيد / المورد">
                  <div className="row" style={{ gap: 6, marginBottom: 6 }}>
                    <select className="sel" style={{ flex: 1, minWidth: 0 }} value={e.partnerKey || ''}
                      onChange={ev => {
                        const o = partyOptions.find(x => x.key === ev.target.value);
                        linkExpParty(e.id, ev.target.value, o ? o.name : e.beneficiaryName, o && o.key.startsWith('sup:') ? o.id : undefined);
                      }}>
                      <option value="">— اربطه بشريك في الرئيسي (اختياري) —</option>
                      {partyOptions.map(o => <option key={o.key} value={o.key}>{o.code} · {o.name} · {o.type}</option>)}
                    </select>
                    {commitOrg && <button type="button" className="btn sm gh" style={{ flexShrink: 0 }} onClick={() => setNewParty({ target: 'exp', rowId: e.id, type: 'supplier', name: e.beneficiaryName || '', cat: '', phone: '' })}><Plus size={13} />جديد</button>}
                  </div>
                  <input className="inp" value={e.beneficiaryName || ''} placeholder="اسم الجهة"
                    onChange={ev => upExp(e.id, 'beneficiaryName', ev.target.value)} />
                </Field>
                <Field label={e.paymentMethod === 'cheque' ? 'رقم الشيك' : e.paymentMethod === 'bank_transfer' ? 'مرجع التحويل' : 'رقم الإيصال'}>
                  <input className="inp" value={e.receiptNumber || ''} placeholder="اختياري"
                    onChange={ev => upExp(e.id, 'receiptNumber', ev.target.value)} />
                </Field>
              </div>

              {/* التصنيف الضريبي للمشتريات */}
              <div className="grid g2" style={{ gap: 9 }}>
                <div className="fld">
                  <label className="lbl">التصنيف الضريبي</label>
                  <div className="row" style={{ gap: 6 }}>
                    <button type="button" style={{ flex: 1 }} className={'btn sm' + (e.isTaxable ? ' pri' : ' gh')}
                      onClick={() => upExp(e.id, 'isTaxable', true)}>خاضع للضريبة</button>
                    <button type="button" style={{ flex: 1 }} className={'btn sm' + (!e.isTaxable ? ' pri' : ' gh')}
                      onClick={() => upExp(e.id, 'isTaxable', false)}>غير خاضع</button>
                  </div>
                </div>
                {e.isTaxable && (
                  <div className="fld">
                    <label className="lbl">نوع الفاتورة</label>
                    <div className="row" style={{ gap: 6 }}>
                      <button type="button" className={'btn sm' + (e.taxInvoice ? ' pri' : ' gh')}
                        onClick={() => upExp(e.id, 'taxInvoice', true)}>ضريبية</button>
                      <button type="button" className={'btn sm' + (!e.taxInvoice ? ' pri' : ' gh')}
                        onClick={() => upExp(e.id, 'taxInvoice', false)}>مبسّطة</button>
                    </div>
                  </div>
                )}
              </div>

              <PhotoField label="صورة الفاتورة / الإيصال (كاميرا · صورة · PDF)" value={e.receiptImage}
                onChange={v => upExp(e.id, 'receiptImage', v)} say={say}
                onOcr={txt => upExp(e.id, 'note', ((e.note || '') + ' ' + txt).trim().slice(0, 500))} />
              <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 8 }}>
                <div className="row" style={{ gap: 6 }}>
                  {e.isTaxable ? (
                    <span className="badge b-brass">ض.ق.م 15% ≈ <span className="num">{money(e.amount * 15 / 115)}</span></span>
                  ) : <span className="badge b-dim">غير خاضع للضريبة</span>}
                  {e.isTaxable && e.taxInvoice && <span className="badge b-mint">فاتورة ضريبية</span>}
                  {e.paymentMethod === 'deferred' && <span className="badge b-amber">آجل — على الحساب</span>}
                  {e.paymentMethod === 'cheque' && <span className="badge b-sky">شيك</span>}
                </div>
                <button className="btn sm gh" onClick={() => set('expenses', f.expenses.filter(x => x.id !== e.id))}>
                  <Trash2 size={13} color="#D9544D" />حذف
                </button>
              </div>
            </div>
          ))}
          {f.expenses.length > 0 && (
            <div className="card" style={{ background: 'var(--ink)', padding: 12, marginTop: 12 }}>
              <div className="lbl" style={{ marginBottom: 8 }}>تحليل المشتريات</div>
              <div className="grid g2" style={{ gap: 8 }}>
                <div className="mono-b"><span style={{ fontSize: 11 }}>مشتريات خاضعة للضريبة</span>
                  <span className="num">{money(sum(f.expenses.filter(e => e.isTaxable), e => e.amount))}</span></div>
                <div className="mono-b"><span style={{ fontSize: 11 }}>مشتريات غير خاضعة</span>
                  <span className="num">{money(sum(f.expenses.filter(e => !e.isTaxable), e => e.amount))}</span></div>
                <div className="mono-b"><span style={{ fontSize: 11 }}>ض.ق.م القابلة للخصم</span>
                  <span className="num" style={{ color: 'var(--mint)' }}>{money(sum(f.expenses.filter(e => e.isTaxable), e => e.amount) * 15 / 115)}</span></div>
                <div className="mono-b"><span style={{ fontSize: 11 }}>مشتريات آجلة (ذمم)</span>
                  <span className="num" style={{ color: 'var(--amber)' }}>{money(sum(f.expenses.filter(e => e.paymentMethod === 'deferred'), e => e.amount))}</span></div>
              </div>
              <div className="row" style={{ gap: 6, marginTop: 10, flexWrap: 'wrap' }}>
                {[['cash', 'نقد'], ['card', 'شبكة'], ['cheque', 'شيك'], ['bank_transfer', 'تحويل'], ['deferred', 'آجل']].map(([pm, lbl]) => {
                  const v = sum(f.expenses.filter(e => e.paymentMethod === pm), e => e.amount);
                  return v > 0 ? <span key={pm} className="badge b-dim">{lbl}: <span className="num">{money(v)}</span></span> : null;
                })}
              </div>
            </div>
          )}
          <div className="grid g2" style={{ marginTop: 12 }}>
            <div className="mono-b"><span style={{ fontSize: 12 }}>إجمالي المصروفات</span>
              <span className="num" style={{ color: 'var(--rose)', fontWeight: 600 }}>{money(totalExp)}</span></div>
            <div className="mono-b"><span style={{ fontSize: 12 }}>المخصوم نقداً من الصندوق</span>
              <span className="num" style={{ color: 'var(--amber)', fontWeight: 600 }}>{money(cashExp)}</span></div>
          </div>
              </>
            ))}

            {sec('supplierPay', Banknote, 'سداد الموردين', 'دفعات نقد/شبكة/تحويل للموردين', <span className="num" style={{ color: 'var(--mint)' }}>{money(totalSupplierPay)}</span>, supPays.length > 0, (
              <>
          <div className="lbl" style={{ marginBottom: 8 }}>سجّل دفعات سداد الموردين — تُخصم الدفعة النقدية من الصندoق وتظهر في كشف حساب المورد بالرئيسي.</div>
          {supPays.map((pm) => (
            <div key={pm.id} className="card" style={{ background: 'var(--ink)', padding: 12, marginBottom: 10 }}>
              <div className="row" style={{ gap: 6, marginBottom: 8 }}>
                <select className="sel" style={{ flex: 1, minWidth: 0 }} value={pm.partnerKey || ''}
                  onChange={ev => { const o = partyOptions.find(x => x.key === ev.target.value); linkPayParty(pm.id, ev.target.value, o ? o.name : pm.supplierName, o && o.key.startsWith('sup:') ? o.id : undefined); }}>
                  <option value="">— اختر المورد من الرئيسي —</option>
                  {partyOptions.map(o => <option key={o.key} value={o.key}>{o.code} · {o.name} · {o.type}</option>)}
                </select>
                {commitOrg && <button type="button" className="btn sm gh" style={{ flexShrink: 0 }} onClick={() => setNewParty({ target: 'pay', rowId: pm.id, type: 'supplier', name: pm.supplierName || '', cat: '', phone: '' })}><Plus size={13} />جديد</button>}
                <button type="button" className="btn sm gh" style={{ flexShrink: 0 }} onClick={() => removeSupPay(pm.id)}><Trash2 size={13} color="#D9544D" /></button>
              </div>
              <input className="inp" style={{ marginBottom: 8 }} value={pm.supplierName || ''} placeholder="اسم المورد"
                onChange={ev => upSupPay(pm.id, 'supplierName', ev.target.value)} />
              {pm.supplierId && invoices.some(i => i.supplierId === pm.supplierId && (i.amount - (i.paidAmount || 0)) > 0) && (
                <select className="sel" style={{ marginBottom: 8 }} value={pm.invoiceId || ''}
                  onChange={ev => {
                    const inv = invoices.find(i => i.id === ev.target.value);
                    set('supplierPayments', (f.supplierPayments || []).map(x => x.id === pm.id
                      ? { ...x, invoiceId: ev.target.value || undefined, reference: inv ? (inv.invoiceNo || x.reference) : x.reference } : x));
                  }}>
                  <option value="">— اربط السداد بفاتورة مفتوحة (اختياري — يمنع الازدواج مع سداد الرئيسي) —</option>
                  {invoices.filter(i => i.supplierId === pm.supplierId && (i.amount - (i.paidAmount || 0)) > 0)
                    .map(i => <option key={i.id} value={i.id}>{i.invoiceNo} · متبقٍ {money(i.amount - (i.paidAmount || 0))}</option>)}
                </select>
              )}
              <div className="lbl" style={{ marginBottom: 4 }}>وزّع السداد على طرق الدفع (يمكن الجمع بينها لنفس الفاتورة)</div>
              <div className="grid g2" style={{ gap: 9 }}>
                <Num label="نقدًا" value={paySplits(pm).cash} onChange={v => upSupPay(pm.id, 'cash', v)} sum />
                <Num label="شبكة" value={paySplits(pm).card} onChange={v => upSupPay(pm.id, 'card', v)} sum />
                <Num label="تحويل" value={paySplits(pm).transfer} onChange={v => upSupPay(pm.id, 'transfer', v)} sum />
                <Num label="غير ذلك" value={paySplits(pm).other} onChange={v => upSupPay(pm.id, 'other', v)} sum />
              </div>
              <div className="grid g2" style={{ gap: 9, marginTop: 9 }}>
                <Field label="المرجع / الفاتورة (اختياري)"><input className="inp" value={pm.reference || ''} placeholder="رقم فاتورة/سند"
                  onChange={ev => upSupPay(pm.id, 'reference', ev.target.value)} /></Field>
                <div className="mono-b" style={{ alignSelf: 'end' }}><span style={{ fontSize: 12 }}>إجمالي هذه الدفعة</span>
                  <span className="num" style={{ color: 'var(--mint)', fontWeight: 700 }}>{money(payTotal(pm))}</span></div>
              </div>
            </div>
          ))}
          <button className="btn sm" onClick={addSupPay}><Plus size={14} />إضافة دفعة سداد مورد</button>
          {supPays.length > 0 && (
            <div className="grid g2" style={{ marginTop: 12 }}>
              <div className="mono-b"><span style={{ fontSize: 12 }}>إجمالي سداد الموردين</span>
                <span className="num" style={{ color: 'var(--mint)', fontWeight: 600 }}>{money(totalSupplierPay)}</span></div>
              <div className="mono-b"><span style={{ fontSize: 12 }}>المخصوم نقداً من الصندوق</span>
                <span className="num" style={{ color: 'var(--amber)', fontWeight: 600 }}>{money(cashSupplierPay)}</span></div>
            </div>
          )}
              </>
            ))}

            {sec('inventory', Coins, 'جرد الصندوق', 'عدّ الفئات النقدية فعليًّا', <span className="num" style={{ color: 'var(--brass)' }}>{counted ? money(actual) : '—'}</span>, counted, (
              <>
          <div className="lbl" style={{ marginBottom: 10 }}>جرد الفئات النقدية — عدّ الصندوق فعلياً</div>
          <div className="notes">
            {DENOMS.map(d => (
              <div key={d.k} className="note" style={{ '--nc': d.c }}>
                <div className="note-v">{d.k === 'coins' ? 'هللات' : d.v}</div>
                <div className="note-u">{d.k === 'coins' ? 'قطع × 0.50' : 'ريال'}</div>
                <div className="note-r">
                  <button className="stp" onClick={() => setDen(d.k, (f.denominationDetails[d.k] || 0) - 1)}><Minus size={12} /></button>
                  <input className="note-i" inputMode="numeric" value={f.denominationDetails[d.k] || 0}
                    onChange={e => setDen(d.k, Number(e.target.value.replace(/[^\d]/g, '')) || 0)} />
                  <button className="stp" onClick={() => setDen(d.k, (f.denominationDetails[d.k] || 0) + 1)}><Plus size={12} /></button>
                </div>
                <div className="note-t">{money((f.denominationDetails[d.k] || 0) * d.v)}</div>
              </div>
            ))}
          </div>

          <div className="grid g3" style={{ marginTop: 16 }}>
            <div className="mono-b"><span style={{ fontSize: 11.5 }}>المتوقع بالصندوق</span>
              <span className="num" style={{ fontWeight: 600 }}>{money(expected)}</span></div>
            <div className="mono-b"><span style={{ fontSize: 11.5 }}>العدّ الفعلي</span>
              <span className="num" style={{ fontWeight: 600, color: 'var(--brass)' }}>{money(actual)}</span></div>
            <div className="mono-b" style={{ borderColor: variance === 0 ? 'var(--line)' : variance < 0 ? 'rgba(217,84,77,.5)' : 'rgba(79,178,134,.5)' }}>
              <span style={{ fontSize: 11.5 }}>الفرق</span>
              <span className="num" style={{ fontWeight: 600, color: variance < 0 ? 'var(--rose)' : variance > 0 ? 'var(--mint)' : 'var(--faint)' }}>
                {variance > 0 ? '+' : ''}{money(variance)}
              </span></div>
          </div>

          {/* v16.8: صندوق فارغ فعليًا رغم وجود نقد متوقع — إقرار صريح يفتح الترحيل مع توثيق العجز */}
          {actual === 0 && !zeroCashDay && (
            <label className="row" style={{ gap: 9, marginTop: 12, cursor: 'pointer', padding: '11px 13px', borderRadius: 10, border: '1.5px dashed var(--line-g)', background: 'var(--acc-soft)', alignItems: 'flex-start' }}>
              <input type="checkbox" checked={!!f.zeroCashConfirmed} onChange={e => set('zeroCashConfirmed', e.target.checked)} style={{ marginTop: 2 }} />
              <span style={{ fontSize: 12, lineHeight: 1.7 }}>
                <b>أُجري الجرد والصندوق فارغ فعلًا (0.00)</b> — رغم أن المتوقع <b className="num">{money(expected)}</b>.
                سيُسجَّل الفرق كعجز ويلزم توثيق سببه قبل الترحيل.
              </span>
            </label>
          )}
          {actual === 0 && zeroCashDay && (
            <div className="note" style={{ marginTop: 12 }}>
              لا نقد متوقع بالصندوق لهذا اليوم (مبيعات غير نقدية ولا عهدة افتتاحية) — الجرد مكتمل تلقائيًا بقيمة 0.00 ويمكنك الترحيل مباشرة.
            </div>
          )}
          <div style={{ marginTop: 14 }}>
            {counted && (
              <div className="seal" style={{ '--sc': variance === 0 ? 'var(--mint)' : variance < 0 ? 'var(--rose)' : 'var(--amber)' }}>
                <Stamp size={22} />
                <div>
                  <div style={{ fontWeight: 700, fontSize: 13.5, fontFamily: "'Markazi Text',serif" }}>
                    {variance === 0 ? 'الصندوق مطابق تماماً' : variance < 0 ? 'عجز نقدي يستوجب التبرير' : 'فائض نقدي غير مبرر'}
                  </div>
                  <div style={{ fontSize: 11, opacity: .85 }}>
                    {variance === 0 ? 'لا فروقات — يمكن الترحيل مباشرة'
                      : `مقدار الفرق ${money(Math.abs(variance))} ر.س — التوثيق إلزامي قبل الترحيل`}
                  </div>
                </div>
              </div>
            )}
          </div>

          {variance !== 0 && (
            <Field label="سبب العجز أو الفائض (إلزامي)">
              <textarea className="inp" value={f.varianceReason} placeholder="مثال: باقي عميل لم يُستلم / خطأ في إدخال فاتورة"
                onChange={e => set('varianceReason', e.target.value)} />
            </Field>
          )}
              </>
            ))}

            {sec('transfer', Landmark, 'الترحيل للخزينة', 'وجهة نقد اليوم للخزينة الرئيسية', <span className="num">{money(f.transferredToMainTreasury)}</span>, (!!f.treasuryChoice || f.transferredToMainTreasury > 0), (
              <>
          <div className="card" style={{ background: 'var(--ink)', padding: 14, marginBottom: 14, borderColor: 'rgba(200,162,74,.3)' }}>
            <div className="card-t" style={{ fontSize: 13, marginBottom: 4 }}>
              <Landmark size={15} color="var(--brass)" />ماذا تريد أن تفعل بنقد اليوم؟
            </div>
            <div style={{ fontSize: 11.5, color: 'var(--dim)', marginBottom: 12 }}>
              المبلغ المعدود بالصندوق <span className="num" style={{ color: 'var(--brass)' }}>{money(actual)}</span> ر.س. اختر وجهته:
            </div>
            <div className="grid g3" style={{ gap: 9 }}>
              <button type="button" className={'btn' + (f.treasuryChoice === 'all' ? ' pri' : ' gh')}
                onClick={() => { set('treasuryChoice', 'all'); set('transferredToMainTreasury', actual); }}
                style={{ flexDirection: 'column', height: 'auto', padding: '12px 8px', gap: 5 }}>
                <ArrowLeftRight size={18} />
                <span style={{ fontSize: 12, fontWeight: 600 }}>ترحيل الكل للخزينة</span>
                <span className="num" style={{ fontSize: 11, opacity: .8 }}>{money(actual)}</span>
              </button>
              <button type="button" className={'btn' + (f.treasuryChoice === 'float' ? ' pri' : ' gh')}
                onClick={() => { set('treasuryChoice', 'float'); set('transferredToMainTreasury', Math.max(0, actual - (branch?.defaultFloat || 0))); }}
                style={{ flexDirection: 'column', height: 'auto', padding: '12px 8px', gap: 5 }}>
                <Wallet size={18} />
                <span style={{ fontSize: 12, fontWeight: 600 }}>ترحيل الفائض وإبقاء عهدة</span>
                <span className="num" style={{ fontSize: 11, opacity: .8 }}>عهدة {money(branch?.defaultFloat || 0)}</span>
              </button>
              <button type="button" className={'btn' + (f.treasuryChoice === 'keep' ? ' pri' : ' gh')}
                onClick={() => { set('treasuryChoice', 'keep'); set('transferredToMainTreasury', 0); }}
                style={{ flexDirection: 'column', height: 'auto', padding: '12px 8px', gap: 5 }}>
                <Lock size={18} />
                <span style={{ fontSize: 12, fontWeight: 600 }}>إبقاء الكل عهدة بالفرع</span>
                <span className="num" style={{ fontSize: 11, opacity: .8 }}>0 للخزينة</span>
              </button>
            </div>
          </div>
          <div className="grid g2">
            <Num label="المرحّل للخزينة الرئيسية" value={f.transferredToMainTreasury}
              onChange={v => { set('transferredToMainTreasury', Math.min(v, actual)); set('treasuryChoice', 'custom'); }}
              hint={`أقصى مبلغ متاح ${money(actual)} ر.س — يمكنك تعديله يدوياً`} />
            <div className="fld">
              <label className="lbl">المتبقي كعهدة للغد</label>
              <div className="mono-b"><span style={{ fontSize: 11.5, color: 'var(--dim)' }}>محسوب آلياً</span>
                <span className="num" style={{ fontWeight: 600, color: 'var(--mint)' }}>{money(retained)}</span></div>
            </div>
          </div>
              </>
            ))}

            {sec('notes', FileText, 'التوثيق والملاحظات', 'ملاحظات · توقيع · صور التوثيق', null, !!(f.notes || f.managerSignature || sPhotos.length), (
              <>
          <Field label="ملاحظات الإغلاق">
            <textarea className="inp" value={f.notes} placeholder="ملاحظات المدير على الوردية"
              onChange={e => set('notes', e.target.value)} />
          </Field>
          <Field label={me.role === 'cashier'
            ? 'صور توثيق الوردية (اختيارية للكاشير — يمكن التقاط أكثر من صورة)'
            : 'صور توثيق المسؤول (إجباري قبل الترحيل — يمكن التقاط أكثر من صورة)'}>
            {sPhotos.length > 0 && (
              <div className="row" style={{ alignItems: 'center', flexWrap: 'wrap', gap: 10, marginBottom: 8 }}>
                {sPhotos.map((img, i) => (
                  <div key={i} style={{ position: 'relative' }}>
                    <img src={img} alt={'توثيق ' + (i + 1)} style={{ width: 54, height: 54, objectFit: 'cover', borderRadius: 8, border: '1px solid var(--line)', display: 'block' }} />
                    <button type="button" className="btn sm gh" title="إزالة هذه الصورة"
                      style={{ position: 'absolute', top: -9, insetInlineEnd: -9, padding: '2px 5px', background: 'var(--ink2)', borderRadius: 999 }}
                      onClick={() => setPhotos(sPhotos.filter((_, x) => x !== i))}><X size={11} color="#D9544D" /></button>
                  </div>
                ))}
                <span className="badge b-mint"><Check size={11} />{sPhotos.length > 1 ? sPhotos.length + ' صور موثّقة' : 'تم التوثيق'}</span>
              </div>
            )}
            <button type="button" className="btn sm" onClick={() => setCam(true)}>
              <ScanFace size={13} />{sPhotos.length ? 'التقاط صورة إضافية' : 'التقاط صورة بالكاميرا'}
            </button>
          </Field>
          <Field label="توقيع المسؤول الرقمي">
            <SignaturePad value={f.managerSignature} onChange={v => set('managerSignature', v)} />
          </Field>
              </>
            ))}
          </div>
        </div>
        <aside className="cflow-sum">
          {summaryRows}
        </aside>
      </div>
      {cam && <CameraModal onClose={() => setCam(false)} say={say}
        onCapture={(img) => { setPhotos([...sPhotos, img]); setCam(false); say('تم توثيق الصورة (' + (sPhotos.length + 1) + ') — يمكنك التقاط صورة إضافية من نفس الزر'); }} />}
      {outPrompt && pend && <OutputDialog rec={pend.rec} org={org}
        onCancel={() => { setOutPrompt(false); setPend(null); }}
        onDone={(out) => finalize('submitted', pend.rec, pend.id, pend.ref, out)} />}
      {newParty && (
        <Modal title={canWriteOrg ? 'إضافة شريك جديد إلى الرئيسي' : 'إضافة شريك جديد إلى دفتر الفرع'} icon={Users} onClose={() => setNewParty(null)}
          foot={<><button className="btn pri" onClick={saveParty}><Check size={14} />{canWriteOrg ? 'حفظ وربط' : 'إضافة وربط فورًا'}</button>
            <button className="btn gh" onClick={() => setNewParty(null)}>إلغاء</button></>}>
          <Field label="النوع">
            <select className="sel" value={newParty.type} onChange={ev => setNewParty({ ...newParty, type: ev.target.value })}>
              <option value="supplier">مورد</option>
              <option value="employee">موظف</option>
              <option value="customer">عميل</option>
            </select>
          </Field>
          <Field label="الاسم"><input className="inp" autoFocus list="party-suggest" value={newParty.name} placeholder="اسم المورد/الموظف/العميل"
            onChange={ev => setNewParty({ ...newParty, name: ev.target.value })} />
            <datalist id="party-suggest">{partyOptions.map(o => <option key={o.key} value={o.name} />)}</datalist>
          </Field>
          {newParty.name && newParty.name.trim() && findPartyByName(newParty.name, newParty.type) && (
            <div style={{ fontSize: 11, color: 'var(--amber)', marginTop: -6, marginBottom: 8, lineHeight: 1.7 }}>
              ⚠ «{findPartyByName(newParty.name, newParty.type).name}» موجود مسبقًا ({findPartyByName(newParty.name, newParty.type).code}) — سيُربط السطر بنفس البطاقة بدل إنشاء بطاقة مكررة.
            </div>
          )}
          <div className="grid g2">
            <Field label={newParty.type === 'employee' ? 'المسمى الوظيفي' : 'التصنيف'}><input className="inp" value={newParty.cat}
              onChange={ev => setNewParty({ ...newParty, cat: ev.target.value })} placeholder={newParty.type === 'supplier' ? 'مثال: مواد خام' : ''} /></Field>
            <Field label="الجوال"><input className="inp" style={{ direction: 'ltr', textAlign: 'right' }} value={newParty.phone}
              onChange={ev => setNewParty({ ...newParty, phone: ev.target.value })} /></Field>
          </div>
          <div style={{ fontSize: 11, color: 'var(--dim)', marginTop: 6, lineHeight: 1.7 }}>
            {canWriteOrg
              ? 'يُسجَّل مباشرةً في الإدارة الرئيسية (دفتر الشركاء) ويُربط بهذا السطر — فيظهر في كشف حسابه.'
              : 'يُضاف فورًا لدفتر شركاء هذا الفرع ويُربط بالسطر مباشرة بلا انتظار — ويظهر مُجمَّعًا في دفتر الشركاء بالرئيسي فورًا. تقدر الإدارة ترقّيه لاحقًا للسجل الرسمي بضغطة واحدة، وكل حركاته تبقى مربوطة.'}
          </div>
        </Modal>
      )}
      {done && <Modal title="تم إغلاق الوردية" icon={CheckCircle2} onClose={onClose}
        foot={<>
          <button className="btn pri" onClick={() => (onStartNew ? onStartNew() : onClose())}><Plus size={14} />بدء وردية جديدة</button>
          <button className="btn gh" onClick={onClose}>العودة للقائمة</button>
        </>}>
        <div style={{ textAlign: 'center', padding: '8px 0' }}>
          <div style={{ width: 62, height: 62, borderRadius: '50%', background: 'rgba(79,178,134,.15)', color: 'var(--mint)', display: 'grid', placeItems: 'center', margin: '0 auto 14px' }}><Check size={32} /></div>
          <div style={{ fontFamily: "'Markazi Text',serif", fontSize: 20, fontWeight: 700 }}>تم إغلاق وردية {done.branchName} بنجاح</div>
          <div style={{ fontSize: 12.5, color: 'var(--dim)', marginTop: 8 }}>الإيراد <span className="num" style={{ color: 'var(--brass)' }}>{money(done.total)}</span> ر.س · سند <span className="num">{done.ref}</span></div>
          <div style={{ fontSize: 11.5, color: 'var(--faint)', marginTop: 12, lineHeight: 1.7 }}>حُفظ الإغلاق وقيد التدقيق والطباعة. يمكنك بدء وردية جديدة مباشرة أو العودة للقائمة.</div>
          {done.docsArchived > 0 && (
            <div style={{ fontSize: 11.5, color: 'var(--mint)', marginTop: 10, background: 'rgba(79,178,134,.1)', border: '1px solid rgba(79,178,134,.3)', borderRadius: 8, padding: '8px 12px', lineHeight: 1.7 }}>
              🗄 رُحّلت <b>{done.docsArchived}</b> مستندًا من هذا الإغلاق (إثبات الشبكة/التحويل · توثيق المسؤول · فواتير المصروفات) تلقائيًا إلى <b>«أرشيف المستندات»</b> — تجدها مرتّبة بالفرع والتاريخ.
            </div>
          )}
        </div>
      </Modal>}
    </Modal>
  );
}

function ClosingView({ c, org, onClose }) {
  const Row = ({ k, v, color }) => (
    <div className="row" style={{ justifyContent: 'space-between', padding: '7px 0', borderBottom: '1px solid var(--line)', fontSize: 12.5 }}>
      <span style={{ color: 'var(--dim)' }}>{k}</span><span className="num" style={{ color }}>{v}</span>
    </div>
  );
  // v16.2: صور توثيق المسؤول كانت محفوظة مع الإغلاق (وتظهر في تقرير PDF والأرشيف)
  // لكن نافذة الاستعراض لم تكن تعرضها إطلاقاً — قسم العرض أدناه جديد.
  const sessPhotos = (c.sessionPhotos && c.sessionPhotos.length) ? c.sessionPhotos : (c.sessionPhoto ? [c.sessionPhoto] : []);
  // v16.4: التكبير كان يفتح نافذة متصفح خارجية (window.open + document.write) وبعض
  // المتصفحات تحجبها فتظهر صفحة فارغة بصورة مكسورة — استُبدل بعارض داخل المنصة نفسها.
  const [zoom, setZoom] = useState(null);
  const [zoomErr, setZoomErr] = useState(false);
  // v16.5: ملف PDF يُفتح بعارض المتصفح مباشرة (وسم <img> لا يعرض PDF فيظهر مكسوراً)
  const zoomImg = (img) => { if (isPdfData(img)) { openPdfData(img); return; } setZoomErr(false); setZoom(img); };
  useEffect(() => {
    if (!zoom) return;
    // Escape يغلق العارض فقط دون إغلاق نافذة الاستعراض خلفه (التقاط قبل مستمع النافذة)
    const onKey = (e) => { if (e.key === 'Escape') { e.stopImmediatePropagation(); setZoom(null); } };
    window.addEventListener('keydown', onKey, true);
    return () => window.removeEventListener('keydown', onKey, true);
  }, [zoom]);
  return (
    <Modal wide title={`إغلاق ${c.branchName} — ${arDate(c.date)}`} icon={Receipt} onClose={onClose}
      foot={<><button className="btn pri" onClick={() => printClosingA4(c, org)}><FileText size={14} />تقرير PDF رسمي</button>
        <button className="btn" onClick={() => printReceipt(c, org)}><Printer size={14} />طباعة حرارية 80مم</button>
        <button className="btn gh" onClick={onClose}>إغلاق</button></>}>
      <div className="row" style={{ marginBottom: 14 }}>
        <Badge s={c.status} />
        {c.gmApprovalStatus === 'approved' && <span className="badge b-brass"><ShieldCheck size={11} />معتمد من الإدارة العليا</span>}
        {c.imagesPruned && <span className="badge b-dim" title="سياسة الاحتفاظ 60 يومًا">🗄 صور هذا الإغلاق في أرشيف المستندات</span>}
        <span className="badge b-dim">المسؤول: {c.managerName}</span>
        {c.auditedBy && <span className="badge b-sky">دقّقه: {c.auditedBy}</span>}
      </div>
      <div className="grid g2">
        <div className="card" style={{ background: 'var(--ink)' }}>
          <div className="card-t" style={{ marginBottom: 8, fontSize: 12.5 }}>الإيرادات</div>
          <Row k="مبيعات نقدية" v={money(c.cashSales)} />
          <Row k="مبيعات الشبكة" v={money(c.cardSales)} />
          <Row k="تحويل بنكي" v={money(c.bankTransferSales || 0)} />
          {(c.deliverySales || []).filter(d => d.amount > 0).map(d => (
            <Row key={d.appId} k={`${d.appName} (${d.orderCount} طلب)`} v={money(d.amount)} />
          ))}
          <Row k="الإجمالي" v={money(c.totalRevenue)} color="var(--brass)" />
          {c.cardReceiptImage && (
            <div style={{ marginTop: 8 }}>
              <div className="lbl">إثبات الشبكة / التحويل</div>
              {isPdfData(c.cardReceiptImage)
                ? <PdfTile v={c.cardReceiptImage} label="إثبات الشبكة / التحويل" />
                : <img src={c.cardReceiptImage} alt="إثبات"
                  onClick={() => zoomImg(c.cardReceiptImage)}
                  style={{ width: '100%', maxHeight: 160, objectFit: 'contain', borderRadius: 8, background: '#000', cursor: 'zoom-in' }} />}
            </div>
          )}
        </div>
        <div className="card" style={{ background: 'var(--ink)' }}>
          <div className="card-t" style={{ marginBottom: 8, fontSize: 12.5 }}>المصروفات</div>
          {(c.expenses || []).map(e => (
            <div key={e.id} style={{ paddingBottom: 4 }}>
              <Row k={`${e.categoryName}${e.beneficiaryName ? ' — ' + e.beneficiaryName : ''}`} v={money(e.amount)} />
              <div className="row" style={{ gap: 5, marginTop: 3, flexWrap: 'wrap' }}>
                <span className="badge b-dim" style={{ fontSize: 9 }}>{({cash:'نقد',card:'شبكة',cheque:'شيك',bank_transfer:'تحويل',deferred:'آجل'})[e.paymentMethod] || e.paymentMethod}</span>
                {e.isTaxable ? <span className="badge b-brass" style={{ fontSize: 9 }}>خاضع للضريبة{e.taxInvoice ? ' · ضريبية' : ''}</span> : <span className="badge b-dim" style={{ fontSize: 9 }}>غير خاضع</span>}
                {e.receiptNumber && <span className="badge b-dim" style={{ fontSize: 9 }}>#{e.receiptNumber}</span>}
              </div>
              {e.receiptImage && (isPdfData(e.receiptImage)
                ? <div style={{ margin: '4px 0 6px' }}><PdfTile small v={e.receiptImage} label="إيصال PDF" /></div>
                : <img src={e.receiptImage} alt="إيصال"
                  onClick={() => zoomImg(e.receiptImage)}
                  style={{ width: 42, height: 42, objectFit: 'cover', borderRadius: 6, margin: '4px 0 6px', cursor: 'zoom-in', border: '1px solid var(--line)' }} />)}
            </div>
          ))}
          {(!c.expenses || c.expenses.length === 0) && <div className="empty" style={{ padding: 18 }}>لا مصروفات</div>}
          <Row k="الإجمالي" v={money(c.totalExpenses)} color="var(--rose)" />
        </div>
      </div>
      {(c.supplierPayments || []).filter(pm => payTotal(pm) > 0).length > 0 && (
        <div className="card" style={{ background: 'var(--ink)', marginTop: 12 }}>
          <div className="card-t" style={{ marginBottom: 8, fontSize: 12.5 }}>سداد الموردين خلال الوردية</div>
          {(c.supplierPayments || []).filter(pm => payTotal(pm) > 0).map(pm => (
            <div key={pm.id} style={{ paddingBottom: 4 }}>
              <Row k={pm.supplierName || 'مورد'} v={money(payTotal(pm))} color="var(--mint)" />
              <div className="row" style={{ gap: 5, marginTop: 3, flexWrap: 'wrap' }}>
                <span className="badge b-dim" style={{ fontSize: 9 }}>{payLabel(pm) || '—'}</span>
                {pm.reference && <span className="badge b-dim" style={{ fontSize: 9 }}>#{pm.reference}</span>}
              </div>
            </div>
          ))}
          <Row k="الإجمالي — منه نقدًا من الصندوق" v={`${money(sum((c.supplierPayments || []), payCashPart))} / ${money(sum((c.supplierPayments || []), payTotal))}`} color="var(--mint)" />
        </div>
      )}
      <hr className="hr" />
      <div className="lbl" style={{ marginBottom: 10 }}>جرد الفئات النقدية</div>
      <div className="notes">
        {DENOMS.filter(d => (c.denominationDetails?.[d.k] || 0) > 0).map(d => (
          <div key={d.k} className="note" style={{ '--nc': d.c }}>
            <div className="note-v">{d.k === 'coins' ? 'هللات' : d.v}</div>
            <div className="note-u">عدد <span className="num">{c.denominationDetails[d.k]}</span></div>
            <div className="note-t">{money((c.denominationDetails[d.k] || 0) * d.v)}</div>
          </div>
        ))}
      </div>
      <div className="grid g3" style={{ marginTop: 14 }}>
        <div className="mono-b"><span style={{ fontSize: 11.5 }}>المتوقع</span><span className="num">{money(c.expectedCashInSafe)}</span></div>
        <div className="mono-b"><span style={{ fontSize: 11.5 }}>الفعلي</span><span className="num">{money(c.actualCashCount)}</span></div>
        <div className="mono-b"><span style={{ fontSize: 11.5 }}>الفرق</span>
          <span className="num" style={{ color: c.variance < 0 ? 'var(--rose)' : c.variance > 0 ? 'var(--mint)' : 'var(--faint)' }}>{money(c.variance)}</span></div>
      </div>
      {c.varianceReason && <div style={{ marginTop: 10, fontSize: 12, color: 'var(--dim)' }}>سبب الفرق: {c.varianceReason}</div>}
      <div className="grid g2" style={{ marginTop: 12 }}>
        <div className="mono-b"><span style={{ fontSize: 11.5 }}>المرحّل للخزينة</span><span className="num" style={{ color: 'var(--brass)' }}>{money(c.transferredToMainTreasury)}</span></div>
        <div className="mono-b"><span style={{ fontSize: 11.5 }}>عهدة الغد</span><span className="num">{money(c.retainedFloatForTomorrow)}</span></div>
      </div>
      {c.notes && <div style={{ marginTop: 12, fontSize: 12, color: 'var(--dim)' }}>ملاحظات: {c.notes}</div>}
      {sessPhotos.length > 0 && (
        <div style={{ marginTop: 12 }}>
          <div className="lbl">صور توثيق المسؤول ({sessPhotos.length}) — اضغط أي صورة لتكبيرها</div>
          <div className="row" style={{ gap: 8, flexWrap: 'wrap' }}>
            {sessPhotos.map((img, i) => (
              <img key={i} src={img} alt={'صورة توثيق ' + (i + 1)} onClick={() => zoomImg(img)}
                style={{ width: 96, height: 96, objectFit: 'cover', borderRadius: 10, border: '1px solid var(--line-g)', cursor: 'zoom-in' }} />
            ))}
          </div>
        </div>
      )}
      {c.imagesPruned && sessPhotos.length === 0 && (
        <div style={{ marginTop: 12, fontSize: 11.5, color: 'var(--dim)' }}>
          🗄 صور هذا الإغلاق نُقلت إلى «أرشيف المستندات» (سياسة الاحتفاظ 60 يومًا) — تجدها هناك باسم الفرع وتاريخ اليوم.
        </div>
      )}
      {c.managerSignature && (
        <div style={{ marginTop: 12 }}>
          <div className="lbl">توقيع المسؤول</div>
          <img src={c.managerSignature} alt="توقيع" style={{ maxWidth: 240, background: '#fff', borderRadius: 8, padding: 4 }} />
        </div>
      )}
      {c.completion && (
        <div className="card" style={{ background: 'var(--ink)', marginTop: 14, borderColor: 'rgba(200,162,74,.3)' }}>
          <div className="card-t" style={{ fontSize: 12.5, marginBottom: 8 }}><ShieldCheck size={14} color="var(--brass)" />سجل إتمام الإغلاق — قيد تدقيق غير قابل للتعديل</div>
          <div className="grid g2" style={{ gap: 8 }}>
            <div className="mono-b"><span style={{ fontSize: 11 }}>رقم الإغلاق</span><span className="num" style={{ fontSize: 11 }}>{c.closingNo || c.transferReferenceNo || '—'}</span></div>
            <div className="mono-b"><span style={{ fontSize: 11 }}>وسيلة الإخراج</span><span style={{ fontSize: 11.5 }}>{c.completion.outputMethod}</span></div>
            <div className="mono-b"><span style={{ fontSize: 11 }}>حالة PDF</span><span style={{ fontSize: 11.5 }}>{c.completion.pdfStatus}</span></div>
            <div className="mono-b"><span style={{ fontSize: 11 }}>الطباعة{c.completion.thermalSize && c.completion.thermalSize !== '—' ? ' (' + c.completion.thermalSize + ')' : ''}</span><span style={{ fontSize: 11.5 }}>{c.completion.printStatus} · محاولات <span className="num">{c.completion.printAttempts}</span></span></div>
            <div className="mono-b"><span style={{ fontSize: 11 }}>الجهاز / المتصفح</span><span style={{ fontSize: 11 }}>{c.completion.device} · {c.completion.browser}</span></div>
            <div className="mono-b"><span style={{ fontSize: 11 }}>المستخدم</span><span style={{ fontSize: 11 }}>{c.completion.by || c.managerName}</span></div>
          </div>
          <div style={{ fontSize: 10, color: 'var(--faint)', marginTop: 8, wordBreak: 'break-all' }}>🔒 بصمة التقرير الرقمية: <span className="num">{c.completion.reportHash || '—'}</span></div>
        </div>
      )}
      {zoom && (
        <div onClick={() => setZoom(null)} role="dialog" aria-label="معاينة الصورة"
          style={{ position: 'fixed', inset: 0, zIndex: 96, background: 'rgba(8,6,5,.92)', display: 'grid', placeItems: 'center', padding: 18, cursor: 'zoom-out' }}>
          {zoomErr
            ? <div style={{ background: 'var(--ink2)', border: '1px solid var(--line-g)', borderRadius: 14, padding: '26px 30px', textAlign: 'center', maxWidth: 420 }} onClick={e => e.stopPropagation()}>
              <AlertTriangle size={26} color="var(--amber)" style={{ marginBottom: 10 }} />
              <div style={{ fontWeight: 700, marginBottom: 6 }}>تعذّر عرض هذا المرفق</div>
              <div style={{ fontSize: 12, color: 'var(--dim)', lineHeight: 1.8 }}>
                الملف المحفوظ تالف أو من نوع غير مدعوم للعرض. إن كان الإغلاق قديمًا فقد تجد نسخته في «أرشيف المستندات».
              </div>
              <button className="btn sm" style={{ marginTop: 12 }} onClick={() => setZoom(null)}>إغلاق</button>
            </div>
            : <img src={zoom} alt="معاينة مكبّرة" onError={() => setZoomErr(true)}
              style={{ maxWidth: '96vw', maxHeight: '90vh', objectFit: 'contain', borderRadius: 10, boxShadow: '0 24px 70px rgba(0,0,0,.6)' }} />}
          <button className="btn sm" onClick={() => setZoom(null)}
            style={{ position: 'fixed', top: 16, insetInlineStart: 16, zIndex: 97 }}><X size={14} />إغلاق المعاينة</button>
          <div style={{ position: 'fixed', bottom: 14, insetInline: 0, textAlign: 'center', color: 'rgba(255,255,255,.55)', fontSize: 11.5, pointerEvents: 'none' }}>
            اضغط في أي مكان للإغلاق
          </div>
        </div>
      )}
    </Modal>
  );
}

/* ================= التدقيق والاعتماد ================= */
function Approvals({ org, me, scoped, commit, say }) {
  const [note, setNote] = useState({});
  const [view, setView] = useState(null);
  const isGM = !!ROLES[me.role]?.approver;
  const queue = scoped.closings.filter(c => c.status === 'submitted' || (c.status === 'approved' && c.gmApprovalStatus === 'pending'))
    .sort((a, b) => b.date.localeCompare(a.date));

  const act = async (c, kind) => {
    const reason = note[c.id] || '';
    if ((kind === 'audit' || kind === 'reject') && periodLocked(org, c.date)) return say(LOCK_MSG(c.date), 'no');
    if (kind === 'reject' && !reason) return say('اكتب سبب الرفض قبل الإرجاع', 'no');
    await commit(d => ({
      ...d,
      // v15.12: رفض الإغلاق يُبطِل توريده أيضًا (الحالة → rejected) فلا يبقى قيدٌ «تحت التحويل» وهمي في الحساب الوسيط ولا نقصٌ في نقد الفرع. (مطابق لسلوك حذف الإغلاق.)
      transfers: kind === 'reject' ? (d.transfers || []).map(t => t.closingId === c.id ? { ...t, status: 'rejected' } : t) : d.transfers,
      closings: d.closings.map(x => {
        if (x.id !== c.id) return x;
        if (kind === 'audit') return { ...x, status: 'approved', auditedBy: me.name, auditedAt: nowISO(), updatedAt: nowISO() };
        if (kind === 'gm') return { ...x, gmApprovalStatus: 'approved', gmApprovedBy: me.name, gmApprovedAt: nowISO(), gmNotes: reason, updatedAt: nowISO() };
        return { ...x, status: 'rejected', rejectionReason: reason, updatedAt: nowISO() };
      }),
      notifications: [{
        id: uid('n'), type: kind === 'reject' ? 'closing_rejected' : 'gm_approval',
        title: kind === 'reject' ? 'إغلاق مرفوض ويحتاج تصحيحاً' : kind === 'gm' ? 'اعتماد نهائي من الإدارة العليا' : 'تم تدقيق الإغلاق',
        message: `${c.branchName} — ${arDate(c.date)}${reason ? ' · ' + reason : ''}`,
        severity: kind === 'reject' ? 'high' : 'info', branchId: c.branchId, closingId: c.id,
        date: c.date, createdAt: nowISO(), isRead: false
      }, ...(d.notifications || [])].slice(0, 60)
    }), {
      actionType: kind === 'reject' ? 'reject' : 'approve', targetType: 'daily_closing', targetId: c.id,
      branchName: c.branchName,
      title: kind === 'audit' ? 'دقّق إغلاقاً مالياً' : kind === 'gm' ? 'اعتمد إغلاقاً نهائياً' : 'أرجع إغلاقاً للتصحيح',
      details: `${c.branchName} — ${arDate(c.date)}${reason ? ' · ' + reason : ''}`
    });
    say(kind === 'reject' ? 'أُرجع الإغلاق للفرع مع السبب' : 'تم الاعتماد بنجاح');
    setNote(p => ({ ...p, [c.id]: '' }));
  };

  return (
    <div className="grid" style={{ gap: 14 }}>
      <div className="grid g3">
        <Kpi label="بانتظار التدقيق المالي" value={scoped.closings.filter(c => c.status === 'submitted').length} icon={ClipboardCheck} color="#E0A458" />
        <Kpi label="بانتظار الاعتماد النهائي" value={scoped.closings.filter(c => c.status === 'approved' && c.gmApprovalStatus === 'pending').length} icon={ShieldCheck} color="#5B93C4" />
        <Kpi label="إغلاقات بها فروقات" value={queue.filter(c => c.variance !== 0).length} icon={AlertTriangle} color="#D9544D" />
      </div>

      {queue.length === 0 && <div className="card"><div className="empty">لا يوجد ما ينتظر إجراءك — كل الإغلاقات مدقّقة ومعتمدة.</div></div>}

      {queue.map(c => {
        const needAudit = c.status === 'submitted';
        const canAct = needAudit ? (ROLES[me.role]?.scope !== 'own' && ROLES[me.role]?.tabs?.includes('approve')) : isGM;
        return (
          <div key={c.id} className="card" style={{ borderColor: c.variance < 0 ? 'rgba(217,84,77,.3)' : 'var(--line)' }}>
            <div className="card-h">
              <div>
                <div className="card-t">{c.branchName}<span className="num" style={{ color: 'var(--faint)', fontSize: 12 }}>{arDate(c.date)}</span></div>
                <div style={{ fontSize: 11, color: 'var(--faint)', marginTop: 3 }}>سجّله {c.managerName} · {arTime(c.createdAt)}</div>
              </div>
              <div className="row">
                <Badge s={c.status} />
                {needAudit ? <span className="badge b-dim">المرحلة 1: تدقيق مالي</span> : <span className="badge b-sky">المرحلة 2: اعتماد نهائي</span>}
              </div>
            </div>
            <div className="grid g4" style={{ gap: 9 }}>
              <div className="mono-b"><span style={{ fontSize: 11 }}>الإيراد</span><span className="num" style={{ color: 'var(--brass)' }}>{money(c.totalRevenue)}</span></div>
              <div className="mono-b"><span style={{ fontSize: 11 }}>المصروف</span><span className="num" style={{ color: 'var(--rose)' }}>{money(c.totalExpenses)}</span></div>
              <div className="mono-b"><span style={{ fontSize: 11 }}>المرحّل</span><span className="num">{money(c.transferredToMainTreasury)}</span></div>
              <div className="mono-b" style={{ borderColor: c.variance !== 0 ? 'rgba(217,84,77,.4)' : 'var(--line)' }}>
                <span style={{ fontSize: 11 }}>الفرق</span>
                <span className="num" style={{ color: c.variance < 0 ? 'var(--rose)' : c.variance > 0 ? 'var(--mint)' : 'var(--faint)' }}>{money(c.variance)}</span>
              </div>
            </div>
            {c.varianceReason && <div style={{ fontSize: 11.5, color: 'var(--amber)', marginTop: 10 }}>تبرير الفرق: {c.varianceReason}</div>}
            <div className="row" style={{ marginTop: 12 }}>
              <input className="inp" style={{ flex: 1, minWidth: 180 }} placeholder="ملاحظة التدقيق أو سبب الإرجاع"
                value={note[c.id] || ''} onChange={e => setNote(p => ({ ...p, [c.id]: e.target.value }))} />
              <button className="btn sm gh" onClick={() => setView(c)}><Eye size={13} />تفاصيل</button>
              {canAct ? (
                <>
                  <button className="btn sm ok" onClick={() => act(c, needAudit ? 'audit' : 'gm')}>
                    <Check size={13} />{needAudit ? 'اعتماد التدقيق' : 'اعتماد نهائي'}
                  </button>
                  <button className="btn sm no" onClick={() => act(c, 'reject')}><X size={13} />إرجاع</button>
                </>
              ) : <span className="badge b-dim"><Lock size={10} />خارج صلاحيتك</span>}
            </div>
          </div>
        );
      })}
      {view && <ClosingView c={view} org={org} onClose={() => setView(null)} />}
    </div>
  );
}

/* ================= الخزينة الرئيسية ================= */
function Treasury({ org, ops, me, myBranches, scoped, commit, say }) {
  const [tab, setTab] = useState('in');
  const [add, setAdd] = useState(false);
  const [repOpen, setRepOpen] = useState(false);    // v9.5 قائمة تقارير التطبيق
  const [from, setFrom] = useState(''); const [to, setTo] = useState(''); // v15.5: فلتر التاريخ لكشف الخزينة
  const canReceive = ROLES[me.role]?.scope !== 'own';
  const isCentral = ROLES[me.role]?.scope !== 'own';

  const list = [...scoped.transfers].sort((a, b) => b.date.localeCompare(a.date));
  const pending = list.filter(t => t.status === 'pending');
  const received = list.filter(t => t.status === 'received');
  const disb = isCentral ? [...(ops.disbursements || [])].sort((a, b) => b.date.localeCompare(a.date)) : [];
  const inflow = sum((ops.transfers || []).filter(t => t.status === 'received'), t => t.amount);
  const outflow = sum(ops.disbursements || [], d => d.amount);
  const balance = inflow - outflow;

  const receive = async (t, ok) => {
    if (periodLocked(org, t.date)) return say(LOCK_MSG(t.date), 'no');
    await commit(d => ({
      ...d,
      transfers: d.transfers.map(x => x.id === t.id ? {
        ...x, status: ok ? 'received' : 'rejected', receivedBy: me.name, receivedAt: nowISO()
      } : x),
      closings: d.closings.map(c => c.id === t.closingId ? { ...c, transferStatus: ok ? 'received' : 'rejected' } : c)
    }), {
      actionType: 'cash_transfer', targetType: 'cash_transfer', targetId: t.id, branchName: t.branchName,
      title: ok ? 'استلم تحويلاً نقدياً بالخزينة' : 'رفض سند تحويل',
      details: `${t.branchName} · ${money(t.amount)} ر.س · سند ${t.referenceNo}`
    });
    say(ok ? 'تم تأكيد استلام المبلغ في الخزينة الرئيسية' : 'تم رفض السند وإبلاغ الفرع');
  };

  const ledger = useMemo(() => {
    const items = [
      ...(ops.transfers || []).filter(t => t.status === 'received')
        .map(t => ({ id: t.id, date: t.date, kind: 'in', label: 'توريد من ' + t.branchName, ref: t.referenceNo, amount: t.amount })),
      ...(ops.disbursements || [])
        .map(x => ({ id: x.id, date: x.date, kind: 'out', label: x.category + ' — ' + x.beneficiary, ref: x.reference, amount: x.amount }))
    ].sort((a, b) => a.date.localeCompare(b.date) || a.id.localeCompare(b.id));
    let run = 0;
    return items.map(i => { run += i.kind === 'in' ? i.amount : -i.amount; return { ...i, run }; }).reverse();
  }, [ops]);
  // v15.5: كشف الخزينة ضمن نطاق التاريخ (الرصيد الجاري يبقى تراكميًا حقيقيًا حتى كل حركة)
  const inRange = (d) => (!from || (d || '') >= from) && (!to || (d || '') <= to);
  const fLedger = useMemo(() => ledger.filter(i => inRange(i.date)), [ledger, from, to]);
  const pIn = sum(fLedger.filter(i => i.kind === 'in'), i => i.amount);
  const pOut = sum(fLedger.filter(i => i.kind === 'out'), i => i.amount);
  const rangeSub = (from || to) ? ('من ' + (from ? arDate(from) : 'البداية') + ' إلى ' + (to ? arDate(to) : arDate(today()))) : ('كل الحركات · حتى ' + arDate(today()));

  const printTreasury = () => {
    const rws = fLedger.map(i => `<tr><td class="n">${arDate(i.date)}</td><td>${i.label}</td><td>${i.ref || ''}</td><td class="n">${i.kind === 'in' ? money(i.amount) : '—'}</td><td class="n">${i.kind === 'out' ? money(i.amount) : '—'}</td><td class="n">${money(i.run)}</td></tr>`).join('');
    printA4(org, 'كشف حركة الخزينة الرئيسية', rangeSub + ' · الرصيد الحالي ' + money(balance),
      `<table><thead><tr><th>التاريخ</th><th>البيان</th><th>المرجع</th><th>وارد</th><th>منصرف</th><th>الرصيد</th></tr></thead><tbody>${rws}
      <tr class="tot"><td colspan="3">${(from || to) ? 'إجمالي الفترة' : 'الإجمالي'}</td><td class="n">${money(from || to ? pIn : inflow)}</td><td class="n">${money(from || to ? pOut : outflow)}</td><td class="n">${money(balance)}</td></tr></tbody></table>`) || say('اسمح بالنوافذ المنبثقة للطباعة', 'no');
  };

  return (
    <div className="grid" style={{ gap: 14 }}>
      {/* شريط التطبيق — v9.5 */}
      <div className="abar">
        <div className="abar-id"><span className="abar-ic"><Landmark size={17} /></span>الخزينة والترحيل<small>التحويلات الواردة · حركة الخزينة</small></div>
        <div className="abar-sp" />
        {isCentral && <div className="abar-dd">
          <button className="btn sm" onClick={() => setRepOpen(o => !o)}><FileBarChart size={14} />التقارير<ChevronDown size={13} /></button>
          {repOpen && (<>
            <div className="abar-back" onClick={() => setRepOpen(false)} />
            <div className="abar-menu">
              <div className="abar-hd">تقارير الخزينة</div>
              <button onClick={() => { setRepOpen(false); printTreasury(); }}><Printer size={13} />كشف حركة الخزينة الرئيسية</button>
            </div>
          </>)}
        </div>}
      </div>

      <div className="grid g4">
        {isCentral && <Kpi label="رصيد الخزينة الرئيسية" value={money(balance)} sub="الوارد ناقص المنصرف" icon={Landmark} color="#C8A24A" />}
        <Kpi label="بانتظار الاستلام" value={money(sum(pending, t => t.amount))} sub={`${pending.length} سند`} icon={ArrowLeftRight} color="#E0A458" />
        <Kpi label="الوارد المستلم" value={money(isCentral ? inflow : sum(received, t => t.amount))} sub={`${received.length} سند من فروعك`} icon={TrendingUp} color="#4FB286" />
        {isCentral && <Kpi label="المنصرف من الخزينة" value={money(outflow)} sub={`${disb.length} أمر صرف`} icon={TrendingDown} color="#D9544D" />}
      </div>

      <div className="row">
        <button className={'btn sm' + (tab === 'in' ? ' pri' : ' gh')} onClick={() => setTab('in')}>
          <ArrowLeftRight size={14} />سندات التوريد
        </button>
        {isCentral && <>
          <button className={'btn sm' + (tab === 'out' ? ' pri' : ' gh')} onClick={() => setTab('out')}>
            <Banknote size={14} />أوامر الصرف
          </button>
          <button className={'btn sm' + (tab === 'led' ? ' pri' : ' gh')} onClick={() => setTab('led')}>
            <FileText size={14} />كشف حركة الخزينة
          </button>
          {tab === 'out' && <button className="btn pri" style={{ marginInlineStart: 'auto' }} onClick={() => setAdd(true)}>
            <Plus size={15} />أمر صرف جديد
          </button>}
        </>}
      </div>

      {tab === 'in' && (
        <div className="card">
          <div className="card-h">
            <div className="card-t"><Landmark size={15} color="var(--brass)" />سندات ترحيل النقدية من الفروع</div>
            {!canReceive && <span className="badge b-dim"><Lock size={10} />الاستلام من صلاحية الإدارة المالية</span>}
          </div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>التاريخ</th><th>الفرع</th><th>رقم السند</th><th>المبلغ</th><th>الحالة</th><th>المستلم</th><th></th></tr></thead>
              <tbody>
                {list.slice(0, 60).map(t => (
                  <tr key={t.id}>
                    <td className="num" style={{ whiteSpace: 'nowrap' }}>{arDate(t.date)}</td>
                    <td style={{ fontSize: 12 }}>{t.branchName}</td>
                    <td className="num" style={{ fontSize: 11, color: 'var(--dim)' }}>{t.referenceNo}</td>
                    <td className="num" style={{ color: 'var(--brass)', fontWeight: 600 }}>{money(t.amount)}</td>
                    <td><Badge s={t.status} /></td>
                    <td style={{ fontSize: 11.5, color: 'var(--dim)' }}>{t.receivedBy || '—'}</td>
                    <td>
                      {t.status === 'pending' && canReceive && (
                        <div className="row" style={{ gap: 5, flexWrap: 'nowrap' }}>
                          <button className="btn sm ok" onClick={() => receive(t, true)}><Check size={12} />استلام</button>
                          <button className="btn sm no" onClick={() => receive(t, false)}><X size={12} /></button>
                        </div>
                      )}
                    </td>
                  </tr>
                ))}
                {list.length === 0 && <tr><td colSpan={7}><div className="empty">لا توجد سندات تحويل بعد.</div></td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {tab === 'out' && isCentral && (
        <div className="card">
          <div className="card-t" style={{ marginBottom: 12 }}><Banknote size={15} color="var(--brass)" />أوامر الصرف من الخزينة</div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>التاريخ</th><th>البند</th><th>المستفيد</th><th>المرجع</th><th>الطريقة</th><th>المبلغ</th><th>أمر الصرف</th></tr></thead>
              <tbody>
                {disb.map(x => (
                  <tr key={x.id}>
                    <td className="num" style={{ whiteSpace: 'nowrap' }}>{arDate(x.date)}</td>
                    <td style={{ fontSize: 12 }}>{x.category}</td>
                    <td style={{ fontSize: 11.5, color: 'var(--dim)' }}>{x.beneficiary}</td>
                    <td className="num" style={{ fontSize: 11, color: 'var(--faint)' }}>{x.reference}</td>
                    <td><span className="badge b-dim">
                      {{ cash: 'نقداً', bank_transfer: 'تحويل بنكي', cheque: 'شيك' }[x.method] || x.method}</span></td>
                    <td className="num" style={{ color: 'var(--rose)', fontWeight: 600 }}>{money(x.amount)}</td>
                    <td style={{ fontSize: 11.5, color: 'var(--dim)' }}>{x.by}</td>
                  </tr>
                ))}
                {disb.length === 0 && <tr><td colSpan={7}><div className="empty">لا توجد أوامر صرف مسجلة.</div></td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {tab === 'led' && isCentral && (
        <div className="card">
          <div className="card-h">
            <div className="card-t"><FileText size={15} color="var(--brass)" />كشف حركة الخزينة الرئيسية</div>
            <div className="row" style={{ gap: 8, flexWrap: 'wrap', alignItems: 'center' }}>
              <span style={{ fontSize: 11.5, color: 'var(--dim)' }}>من</span>
              <input type="date" className="inp" style={{ width: 145 }} value={from} onChange={e => setFrom(e.target.value)} />
              <span style={{ fontSize: 11.5, color: 'var(--dim)' }}>إلى</span>
              <input type="date" className="inp" style={{ width: 145 }} value={to} onChange={e => setTo(e.target.value)} />
              {(from || to) && <button className="btn sm gh" onClick={() => { setFrom(''); setTo(''); }}>إظهار الكل</button>}
              <button className="btn sm" onClick={printTreasury}><Printer size={13} />طباعة</button>
            </div>
          </div>
          <div style={{ fontSize: 11.5, color: 'var(--dim)', marginBottom: 8 }}>{rangeSub}{(from || to) && <> · وارد الفترة <b style={{ color: 'var(--mint)' }}>{money(pIn)}</b> · منصرف الفترة <b style={{ color: 'var(--rose)' }}>{money(pOut)}</b></>}</div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>التاريخ</th><th>البيان</th><th>المرجع</th><th>وارد</th><th>منصرف</th><th>الرصيد</th></tr></thead>
              <tbody>
                {fLedger.slice(0, 200).map(i => (
                  <tr key={i.kind + i.id}>
                    <td className="num" style={{ whiteSpace: 'nowrap' }}>{arDate(i.date)}</td>
                    <td style={{ fontSize: 12 }}>{i.label}</td>
                    <td className="num" style={{ fontSize: 10.5, color: 'var(--faint)' }}>{i.ref}</td>
                    <td className="num" style={{ color: 'var(--mint)' }}>{i.kind === 'in' ? money(i.amount) : '—'}</td>
                    <td className="num" style={{ color: 'var(--rose)' }}>{i.kind === 'out' ? money(i.amount) : '—'}</td>
                    <td className="num" style={{ fontWeight: 600, color: 'var(--brass)' }}>{money(i.run)}</td>
                  </tr>
                ))}
                {fLedger.length === 0 && <tr><td colSpan={6}><div className="empty">{(from || to) ? 'لا حركات ضمن هذه الفترة.' : 'لا حركات على الخزينة بعد.'}</div></td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {add && <DisbursementForm org={org} me={me} balance={balance} commit={commit} say={say} onClose={() => setAdd(false)} />}
    </div>
  );
}

function DisbursementForm({ org, me, balance, commit, say, onClose }) {
  const [f, setF] = useState({
    date: today(), category: 'توريد مواد خام مركزي', amount: 0,
    beneficiary: '', method: 'bank_transfer', reference: ''
  });
  const set = (k, v) => setF(p => ({ ...p, [k]: v }));
  const save = async () => {
    if (f.amount <= 0) return say('أدخل مبلغ الصرف', 'no');
    if (!f.beneficiary.trim()) return say('اكتب اسم المستفيد', 'no');
    if (f.amount > balance) return say('المبلغ يتجاوز رصيد الخزينة المتاح', 'no');
    if (periodLocked(org, f.date || today())) return say(LOCK_MSG(f.date || today()), 'no');
    const rec = { ...f, id: uid('ds'), by: me.name, createdAt: nowISO() };
    await commit(d => ({ ...d, disbursements: [rec, ...(d.disbursements || [])] }), {
      actionType: 'cash_transfer', targetType: 'cash_transfer', targetId: rec.id,
      title: 'أصدر أمر صرف من الخزينة',
      details: `${f.category} · ${f.beneficiary} · ${money(f.amount)} ر.س`
    });
    say('تم تسجيل أمر الصرف وخصمه من رصيد الخزينة');
    onClose();
  };
  return (
    <Modal title="أمر صرف من الخزينة الرئيسية" icon={Banknote} onClose={onClose}
      foot={<><button className="btn pri" onClick={save}><Check size={14} />اعتماد الصرف</button>
        <button className="btn gh" onClick={onClose}>إلغاء</button></>}>
      <div className="mono-b" style={{ marginBottom: 14 }}>
        <span style={{ fontSize: 12 }}>الرصيد المتاح بالخزينة</span>
        <span className="num" style={{ color: 'var(--brass)', fontWeight: 600 }}>{money(balance)}</span>
      </div>
      <div className="grid g2">
        <Field label="بند الصرف">
          <select className="sel" value={f.category} onChange={e => set('category', e.target.value)}>
            {['توريد مواد خام مركزي', 'إيجارات الفروع', 'صرف رواتب', 'سداد موردين', 'صيانة وتشغيل',
              'ضريبة القيمة المضافة', 'مصاريف إدارية'].map(c => <option key={c} value={c}>{c}</option>)}
          </select>
        </Field>
        <Field label="تاريخ الصرف">
          <input type="date" className="inp" value={f.date} onChange={e => set('date', e.target.value)} />
        </Field>
      </div>
      <div className="grid g2">
        <Num label="المبلغ" value={f.amount} onChange={v => set('amount', v)} />
        <Field label="طريقة الصرف">
          <select className="sel" value={f.method} onChange={e => set('method', e.target.value)}>
            <option value="bank_transfer">تحويل بنكي</option>
            <option value="cash">نقداً</option>
            <option value="cheque">شيك</option>
          </select>
        </Field>
      </div>
      <div className="grid g2">
        <Field label="المستفيد">
          <input className="inp" value={f.beneficiary} placeholder="اسم الجهة أو المورد"
            onChange={e => set('beneficiary', e.target.value)} />
        </Field>
        <Field label="رقم المرجع / السند">
          <input className="inp" value={f.reference} placeholder="اختياري"
            onChange={e => set('reference', e.target.value)} />
        </Field>
      </div>
    </Modal>
  );
}

/* ================= الرواتب والسلف ================= */
function Payroll({ org, ops, me, myBranches, scoped, commit, commitOrg, say }) {
  const [month, setMonth] = useState(today().slice(0, 7));
  const [add, setAdd] = useState(false);
  const [payFund, setPayFund] = useState('1201');   // v15.19: مصدر صرف الرواتب — بنك (افتراضي) أو خزينة رئيسية
  const [repOpen, setRepOpen] = useState(false);    // v9.5 قائمة تقارير التطبيق
  const [compF, setCompF] = useState(null);         // v11.0 تعديل راتب/بدلات موظف
  const [eosF, setEosF] = useState(null);           // v12.3 حاسبة نهاية الخدمة
  const [gosiD, setGosiD] = useState(() => {
    const g = org.gosiCfg || {};
    return {
      enabled: !!g.enabled,
      empRate: String(g.empRate != null ? g.empRate : 9.75), erRate: String(g.erRate != null ? g.erRate : 11.75),
      saudiOldEmp: String(g.saudiOldEmp != null ? g.saudiOldEmp : (g.empRate != null ? g.empRate : 9.75)),
      saudiOldEr: String(g.saudiOldEr != null ? g.saudiOldEr : (g.erRate != null ? g.erRate : 11.75)),
      saudiNewEmp: String(g.saudiNewEmp != null ? g.saudiNewEmp : 10.75), saudiNewEr: String(g.saudiNewEr != null ? g.saudiNewEr : 12.75),
      nonSaudiEmp: String(g.nonSaudiEmp != null ? g.nonSaudiEmp : 0), nonSaudiEr: String(g.nonSaudiEr != null ? g.nonSaudiEr : 2),
      ceiling: String(g.ceiling != null ? g.ceiling : 45000),
    };
  });
  const ids = myBranches.map(b => b.id);
  const emps = (org.employees || []).filter(e => ids.includes(e.branchId));
  const canPay = ROLES[me.role]?.scope !== 'own';
  // ترحيل الاستحقاق/الصرف قرار على مستوى المنشأة كلها — يُقصر على الأدوار شاملة النطاق
  const canPost = rolePost(me.role);

  // v11.0 — التأمينات الاجتماعية (GOSI): موقوفة افتراضيًا، بنِسَب قابلة للتعديل، وعلى وعاء الأساسي+السكن
  const gosi = org.gosiCfg || {};
  const gosiOn = !!gosi.enabled;
  const gosiEmpRate = Number(gosi.empRate != null ? gosi.empRate : 9.75) || 0;
  const gosiErRate = Number(gosi.erRate != null ? gosi.erRate : 11.75) || 0;
  const r2 = (n) => Math.round(n * 100) / 100;
  const rows = emps.map(e => {
    const ads = scoped.advances.filter(a => a.employeeId === e.id && a.month === month);
    const draws = sum(ads.filter(a => ['advance', 'salary_draw'].includes(a.type)), a => a.amount);
    const bonus = r2(sum(ads.filter(a => a.type === 'bonus'), a => a.amount));   // م٨ (v25.0): مكافآت معتمدة تُضاف للإجمالي
    const cuts = sum(ads.filter(a => !['advance', 'salary_draw', 'bonus'].includes(a.type)), a => a.amount);   // الجزاءات المعتمدة (discipline_penalty) خصم كسائر الخصومات
    const allow = (e.housingAllowance || 0) + (e.transportAllowance || 0) + (e.otherAllowance || 0);
    const gross = r2((e.baseSalary || 0) + allow + bonus);
    const gr = gosiRatesFor(e, org.gosiCfg);
    const gosiBase = gr.base;
    const gEmp = (gosiOn && e.gosiSubject) ? r2(gosiBase * gr.emp / 100) : 0;
    const gEr = (gosiOn && e.gosiSubject) ? r2(gosiBase * gr.er / 100) : 0;
    return { e, ads, draws, bonus, cuts, allow, gross, gEmp, gEr, net: r2(gross - draws - cuts - gEmp), flags: ads.filter(a => a.isUnjustified).length };
  });

  const totalNet = sum(rows, r => r.net);
  const totalGross = sum(rows, r => r.gross);
  const totalGEmp = r2(sum(rows, r => r.gEmp));
  const totalGEr = r2(sum(rows, r => r.gEr));
  const totalGosi = r2(totalGEmp + totalGEr);

  // م١٠ (v27.0) — إقرارات استلام الراتب الموقَّعة إلكترونيًا (ops.hrSignDocs): تُصدر تلقائيًا مع تسجيل الصرف، ويوقّعها الموظف من كشك الفرع أو من هنا
  const slipDocOf = (empId) => (ops.hrSignDocs || []).find(d => d.docType === 'payslip' && d.month === month && d.employeeId === empId && d.status !== 'voided') || null;
  const slipDocs = rows.map(r => slipDocOf(r.e.id)).filter(Boolean);
  const slipSigned = slipDocs.filter(d => d.status === 'signed').length;
  const missingSlips = rows.filter(r => r.net > 0 && !slipDocOf(r.e.id)).length;
  const [signRow, setSignRow] = useState(null);   // {emp, doc} — توقيع الاستلام من شاشة الرواتب (المكتب)
  const issueSlips = async () => {
    if (!missingSlips) return say('كل قسائم هذا الشهر صادرة للتوقيع مسبقًا', 'no');
    const ok = await commit(d => ({ ...d, hrSignDocs: [...buildPayslipSignDocs(rows, month, d.hrSignDocs || [], org.branches || [], me), ...(d.hrSignDocs || [])] }), {
      actionType: 'create', targetType: 'hr_sign_doc', targetId: 'payslips-' + month,
      title: 'إصدار قسائم الشهر للتوقيع الإلكتروني', details: month + ' · ' + missingSlips + ' قسيمة'
    });
    if (ok) say('صدرت ' + missingSlips + ' قسيمة للتوقيع — يوقّعها الموظفون من كشك الفرع أو من هنا ✓');
  };
  // خلية توقيع الموظف في المسير المطبوع: التوقيع الإلكتروني إن وُجد، وإلا فراغ للتوقيع اليدوي
  const musterSigCell = (r) => { const sd = slipDocOf(r.e.id); return sd && sd.status === 'signed' ? sigSvg(sd.sig, { width: 90 }) : (sd ? '<span style="font-size:9px;color:#999">بانتظار التوقيع</span>' : ''); };

  const printMuster = () => {
    const monthName = new Date(month + '-01').toLocaleDateString('ar-EG', { month: 'long', year: 'numeric' });
    const gc = gosiOn ? '<th>تأمينات</th>' : '';
    const rws = rows.map(r => `<tr><td>${r.e.name}</td><td>${(org.branches.find(b => b.id === r.e.branchId) || {}).name || ''}</td><td class="n">${money(r.e.baseSalary || 0)}</td><td class="n">${r.allow ? money(r.allow) : '—'}</td><td class="n">${r.bonus ? money(r.bonus) : '—'}</td><td class="n">${money(r.gross)}</td><td class="n">${r.draws ? money(r.draws) : '—'}</td><td class="n">${r.cuts ? money(r.cuts) : '—'}</td>${gosiOn ? `<td class="n">${r.gEmp ? money(r.gEmp) : '—'}</td>` : ''}<td class="n">${money(r.net)}</td><td style="width:100px;height:36px;text-align:center">${musterSigCell(r)}</td></tr>`).join('');
    const span = gosiOn ? 9 : 8;
    printA4(org, 'مسير الرواتب — ' + monthName, arDate(today()) + ' · ' + rows.length + ' موظف' + (slipDocs.length ? ' · توقيعات إلكترونية ' + slipSigned + '/' + slipDocs.length : ''),
      `<table><thead><tr><th>الموظف</th><th>الفرع</th><th>الأساسي</th><th>البدلات</th><th>مكافآت</th><th>الإجمالي</th><th>سلف/سحب</th><th>خصومات</th>${gc}<th>الصافي</th><th>توقيع الموظف</th></tr></thead><tbody>${rws}
      <tr class="tot"><td colspan="${span}">إجمالي صافي المسير</td><td class="n">${money(totalNet)}</td><td></td></tr>${gosiOn ? `<tr class="tot"><td colspan="${span}">إجمالي التأمينات للتحويل (موظف + صاحب عمل)</td><td class="n">${money(totalGosi)}</td><td></td></tr>` : ''}</tbody></table>
      ${slipDocs.length ? '<div class="ft" style="text-align:right">التوقيعات الإلكترونية مسجَّلة عبر كشك الفرع/المكتب بعد التحقق بـPIN أو بحضور مستخدم مركزي — تفاصيلها في «التوقيع الإلكتروني ← سجل الإقرارات».</div>' : ''}`) || say('اسمح بالنوافذ المنبثقة للطباعة', 'no');
  };

  // ===== v12.3: حماية الأجور (WPS) ونهاية الخدمة =====
  const empGrossOf = (e) => r2((e.baseSalary || 0) + (e.housingAllowance || 0) + (e.transportAllowance || 0) + (e.otherAllowance || 0));
  const tenureYears = (hire, end) => { if (!hire) return 0; const h = Date.parse(hire + 'T00:00:00'), t = Date.parse((end || today()) + 'T00:00:00'); if (isNaN(h) || isNaN(t) || t < h) return 0; return (t - h) / (365.25 * 86400000); };
  const eosFull = (wage, years) => years <= 5 ? wage * 0.5 * years : wage * (2.5 + (years - 5));
  const eosEntitled = (wage, years, reason) => { const full = eosFull(wage, years); if (reason === 'termination') return full; if (years < 2) return 0; if (years < 5) return full / 3; if (years < 10) return full * 2 / 3; return full; };
  const fmtYears = (y) => { const yr = Math.floor(y + 1e-9); const mo = Math.round((y - yr) * 12); return yr + ' سنة' + (mo ? ' و' + mo + ' شهر' : ''); };
  const exportWPS = () => {
    const head = ['رقم الهوية/الإقامة', 'اسم الموظف', 'الآيبان IBAN', 'الأساسي', 'بدل السكن', 'بدلات أخرى', 'الاستقطاعات', 'صافي الراتب', 'أيام العمل'];
    const lines = rows.map(r => [r.e.idNumber || r.e.iqamaNo || r.e.nationalId || '', r.e.name, r.e.iban || '', r.e.baseSalary || 0, r.e.housingAllowance || 0, r2((r.e.transportAllowance || 0) + (r.e.otherAllowance || 0) + (r.bonus || 0)), r2(r.draws + r.cuts + r.gEmp), r.net, 30]);
    try {
      const blob = makeXlsx([{ name: ('حماية الأجور ' + month).slice(0, 28), rows: [head, ...lines] }]);
      const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'حماية_الأجور_WPS_' + month + '.xlsx'; document.body.appendChild(a); a.click(); document.body.removeChild(a); setTimeout(() => URL.revokeObjectURL(url), 1500);
      const missing = rows.filter(r => !(r.e.iban && (r.e.idNumber || r.e.iqamaNo || r.e.nationalId))).length;
      say(missing ? ('نُزّل ملف Excel — لكن ' + missing + ' موظف بلا آيبان/هوية كاملة؛ أكمِلها من «تعديل الراتب»') : 'نُزّل ملف حماية الأجور (Excel) ✓', missing ? 'no' : 'ok');
    } catch (e) { say('تعذّر توليد ملف Excel', 'no'); }
  };
  const printEOSlip = (emp, calc) => {
    printA4(org, 'مخالصة نهاية الخدمة — ' + emp.name, 'حتى ' + arDate(calc.endDate) + ' · ' + (calc.reason === 'termination' ? 'إنهاء من صاحب العمل' : 'استقالة'),
      `<table><tbody>
      <tr><td>تاريخ التعيين</td><td class="n">${emp.hireDate || '—'}</td></tr>
      <tr><td>تاريخ انتهاء الخدمة</td><td class="n">${calc.endDate}</td></tr>
      <tr><td>مدة الخدمة</td><td class="n">${fmtYears(calc.years)}</td></tr>
      <tr><td>الأجر الشهري (أساسي + بدلات)</td><td class="n">${money(calc.wage)}</td></tr>
      <tr><td>مكافأة نهاية الخدمة الكاملة</td><td class="n">${money(calc.full)}</td></tr>
      <tr><td>المستحق حسب سبب الانتهاء</td><td class="n">${money(calc.entitled)}</td></tr>
      ${calc.leavePay ? `<tr><td>بدل إجازة متبقية (${calc.leaveDays} يوم)</td><td class="n">${money(calc.leavePay)}</td></tr>` : ''}
      <tr class="tot"><td>إجمالي المخالصة النهائية</td><td class="n">${money(calc.total)}</td></tr>
      </tbody></table>
      <div class="box" style="margin-top:12px;font-size:10px;color:#777">محسوبة وفق نظام العمل السعودي (م 84/85): نصف شهر عن كل سنة للخمس الأولى، وشهر كامل لما بعدها؛ وتُخفَّض في الاستقالة حسب المدة. تقدير استرشادي؛ التسوية النهائية قد تشمل بنودًا أخرى.</div>`) || say('اسمح بالنوافذ المنبثقة للطباعة', 'no');
  };

  const printPayslip = (r) => {
    const co = org.company || {};
    const b = org.branches.find(x => x.id === r.e.branchId);
    const m = (n) => money(n);
    const monthName = new Date(month + '-01').toLocaleDateString('ar-EG', { month: 'long', year: 'numeric' });
    const adRows = r.ads.map(a => `<tr>
      <td>${arDate(a.date)}</td>
      <td>${['advance', 'salary_draw'].includes(a.type) ? 'سلفة/سحب' : 'خصم/جزاء'}</td>
      <td class="n">${m(a.amount)}</td>
      <td>${a.reason || '—'}</td></tr>`).join('') || '<tr><td colspan="4" class="ce">لا سلف أو خصومات هذا الشهر</td></tr>';
    const w = window.open('', '_blank', 'width=850,height=1000');
    if (!w) return;
    w.document.write(`<!doctype html><html dir="rtl" lang="ar"><head><meta charset="utf-8">
      <title>قسيمة راتب - ${r.e.name} - ${monthName}</title>
      <style>
        *{margin:0;padding:0;box-sizing:border-box;font-family:'Segoe UI',Tahoma,sans-serif}
        body{padding:32px;color:#222;background:#fff}
        .head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #C8A24A;padding-bottom:16px;margin-bottom:20px}
        .logo{width:64px;height:64px;object-fit:contain}
        .co-n{font-size:19px;font-weight:bold;color:#8C6F2C}
        .co-m{font-size:11px;color:#666;margin-top:3px}
        .title{text-align:center;font-size:16px;font-weight:bold;margin:8px 0}
        .sub{text-align:center;font-size:13px;color:#666;margin-bottom:20px}
        .grid{display:grid;grid-template-columns:1fr 1fr;gap:10px 20px;margin-bottom:20px}
        .fld{display:flex;justify-content:space-between;padding:8px 12px;background:#F6F2E9;border-radius:6px;font-size:13px}
        .fld b{color:#8C6F2C}
        table{width:100%;border-collapse:collapse;margin:16px 0;font-size:12.5px}
        th{background:#241F1B;color:#fff;padding:8px;text-align:right}
        td{border:1px solid #ddd;padding:7px 10px}
        td.n{text-align:left;font-variant-numeric:tabular-nums}
        td.ce{text-align:center;color:#999}
        .totals{margin-top:20px;border:2px solid #C8A24A;border-radius:10px;overflow:hidden}
        .totals .row{display:flex;justify-content:space-between;padding:11px 16px;font-size:14px;border-bottom:1px solid #eee}
        .totals .net{background:#241F1B;color:#fff;font-size:17px;font-weight:bold;border:none}
        .sign{display:flex;justify-content:space-between;margin-top:48px;gap:40px}
        .sign div{flex:1;text-align:center;border-top:1px solid #999;padding-top:8px;font-size:12px;color:#666}
        @media print{body{padding:16px}}
      </style></head><body>
      <div class="head">
        <div style="display:flex;gap:14px;align-items:center">
          ${co.logoUrl ? `<img class="logo" src="${co.logoUrl}">` : ''}
          <div><div class="co-n">${co.name || 'المنشأة'}</div>
          <div class="co-m">الرقم الضريبي: ${co.taxNumber || '—'} · س.تجاري: ${co.commercialReg || '—'}</div></div>
        </div>
        <div style="text-align:left;font-size:11px;color:#888">تاريخ الإصدار<br><b>${new Date().toLocaleDateString('ar-EG')}</b></div>
      </div>
      <div class="title">قسيمة راتب</div>
      <div class="sub">عن شهر ${monthName}</div>
      <div class="grid">
        <div class="fld"><span>اسم الموظف</span><b>${r.e.name}</b></div>
        <div class="fld"><span>المسمى الوظيفي</span><b>${r.e.jobTitle || '—'}</b></div>
        <div class="fld"><span>الفرع</span><b>${b?.name || '—'}</b></div>
        <div class="fld"><span>رقم الموظف</span><b>${r.e.empNo || r.e.id.slice(-5)}</b></div>
      </div>
      <table><thead><tr><th>التاريخ</th><th>البند</th><th class="n">المبلغ</th><th>السبب</th></tr></thead>
        <tbody>${adRows}</tbody></table>
      <div class="totals">
        <div class="row"><span>الراتب الأساسي</span><b>${m(r.e.baseSalary || 0)} ر.س</b></div>
        <div class="row"><span>بدل السكن</span><b>${m(r.e.housingAllowance || 0)} ر.س</b></div>
        ${(r.e.transportAllowance || 0) ? `<div class="row"><span>بدل النقل</span><b>${m(r.e.transportAllowance || 0)} ر.س</b></div>` : ''}
        ${(r.e.otherAllowance || 0) ? `<div class="row"><span>بدلات أخرى</span><b>${m(r.e.otherAllowance || 0)} ر.س</b></div>` : ''}
        <div class="row"><span>إجمالي الاستحقاق</span><b>${m(r.gross)} ر.س</b></div>
        <div class="row"><span>السلف والسحوبات</span><b style="color:#C0392B">- ${m(r.draws)} ر.س</b></div>
        <div class="row"><span>الخصومات والجزاءات</span><b style="color:#C0392B">- ${m(r.cuts)} ر.س</b></div>
        ${r.gEmp ? `<div class="row"><span>التأمينات الاجتماعية (حصة الموظف)</span><b style="color:#C0392B">- ${m(r.gEmp)} ر.س</b></div>` : ''}
        <div class="row net"><span>صافي المستحق</span><b>${m(r.net)} ر.س</b></div>
      </div>
      ${r.gEr ? `<div style="margin-top:10px;font-size:11px;color:#666;text-align:center">حصة صاحب العمل من التأمينات: ${m(r.gEr)} ر.س (على المنشأة، خارج صافي الموظف)</div>` : ''}
      <div class="sign">
        <div>${(() => { const sd = slipDocOf(r.e.id); return sd && sd.status === 'signed' ? sigBlockHtml(sd, 150) + '<div style="margin-top:4px">توقيع الموظف — إقرار استلام</div>' : (sd ? 'توقيع الموظف <span style="font-size:9px;color:#999">(بانتظار التوقيع الإلكتروني)</span>' : 'توقيع الموظف'); })()}</div>
        <div>المحاسب</div>
        <div>اعتماد الإدارة</div>
      </div>
      </body></html>`);
    w.document.close();
    setTimeout(() => { w.focus(); w.print(); }, 500);
  };

  // ترحيل استحقاق الشهر وقيد الصرف إلى دفتر الشركاء — قيود دائمة لا تتغيّر بتغيّر الشهر (إصلاح المراجعة #4)
  const accrualPosted = (ops.ledgerEntries || []).some(x => x.kind === 'salary_accrual' && x.month === month);
  const payoutPosted = (ops.ledgerEntries || []).some(x => x.kind === 'salary_payout' && x.month === month);
  const postAccrual = async () => {
    if (lockedThru(org) && month <= lockedThru(org)) return say(LOCK_MSG(month + '-01'), 'no');
    if (accrualPosted) return say('استحقاق هذا الشهر مُرحّل مسبقاً', 'no');
    const entries = rows.filter(r => r.gross > 0).map(r => ({
      id: uid('le'), partnerKey: 'emp:' + r.e.id, date: month + '-28', month, kind: 'salary_accrual',
      desc: 'استحقاق راتب شهر ' + month, src: 'salary', debit: 0, credit: r.gross
    }));
    if (!entries.length) return say('لا رواتب لترحيلها هذا الشهر', 'no');
    await commit(d => ({ ...d, ledgerEntries: [...entries, ...(d.ledgerEntries || [])] }), {
      actionType: 'create', targetType: 'daily_closing', targetId: 'payroll-' + month,
      title: 'رحّل استحقاق رواتب الشهر للدفتر', details: month + ' · ' + entries.length + ' موظف · إجمالي ' + money(sum(rows.filter(r => r.gross > 0), r => r.gross))
    });
    say('رُحّل استحقاق ' + month + ' إلى دفتر الشركاء ✓');
  };
  const postPayout = async () => {
    if (lockedThru(org) && month <= lockedThru(org)) return say(LOCK_MSG(month + '-01'), 'no');
    if (!accrualPosted) return say('رحّل استحقاق الشهر أولاً', 'no');
    if (payoutPosted) return say('صرف هذا الشهر مسجّل مسبقاً', 'no');
    const entries = rows.filter(r => r.net > 0).map(r => ({
      id: uid('le'), partnerKey: 'emp:' + r.e.id, date: today(), month, kind: 'salary_payout',
      desc: 'صرف راتب شهر ' + month + ' (صافي بعد السلف والخصوم' + (r.gEmp > 0.004 ? ' والتأمينات' : '') + ')', src: 'salary', debit: r.net, credit: 0,
      gosi: r.gEmp || 0, gosiEr: r.gEr || 0,
      fund: payFund   // v15.19: مصدر صرف الرواتب المختار (بنك 1201 أو خزينة رئيسية 1101)
    }));
    if (!entries.length) return say('لا صافي مستحق للصرف', 'no');
    // م١٠ (v27.0): مع قيد الصرف تُصدر قسيمة إقرار استلام لكل موظف (تُكتب في مستند فرعه كي يوقّعها من كشك الفرع)
    const ok = await commit(d => ({ ...d, ledgerEntries: [...entries, ...(d.ledgerEntries || [])], hrSignDocs: [...buildPayslipSignDocs(rows, month, d.hrSignDocs || [], org.branches || [], me), ...(d.hrSignDocs || [])] }), {
      actionType: 'create', targetType: 'daily_closing', targetId: 'payout-' + month,
      title: 'سجّل صرف رواتب الشهر', details: month + ' · صافي ' + money(sum(rows.filter(r => r.net > 0), r => r.net)) + (payFund === '1101' ? ' · نقداً من الخزينة' : ' · من البنك') + (totalGosi > 0.004 ? ' · تأمينات ' + money(totalGosi) : '') + ' · صدرت ' + entries.length + ' قسيمة للتوقيع الإلكتروني'
    });
    if (!ok) return;
    say('سُجّل صرف رواتب ' + month + (payFund === '1101' ? ' نقداً من الخزينة الرئيسية' : ' من البنك') + ' — أُقفل استحقاق الشهر وصدرت قسائم الإقرار للتوقيع الإلكتروني ✓');
  };
  // v11.0 — حفظ إعداد التأمينات الاجتماعية
  const saveGosi = async () => {
    await commitOrg(d => ({ ...d, gosiCfg: {
      enabled: !!gosiD.enabled,
      empRate: Number(gosiD.saudiOldEmp) || 0, erRate: Number(gosiD.saudiOldEr) || 0,
      saudiOldEmp: Number(gosiD.saudiOldEmp) || 0, saudiOldEr: Number(gosiD.saudiOldEr) || 0,
      saudiNewEmp: Number(gosiD.saudiNewEmp) || 0, saudiNewEr: Number(gosiD.saudiNewEr) || 0,
      nonSaudiEmp: Number(gosiD.nonSaudiEmp) || 0, nonSaudiEr: Number(gosiD.nonSaudiEr) || 0,
      ceiling: Number(gosiD.ceiling) || 45000,
    } }), {
      actionType: 'update', targetType: 'year_end', targetId: 'gosi',
      title: gosiD.enabled ? 'فعّل/حدّث التأمينات الاجتماعية' : 'أوقف التأمينات الاجتماعية',
      details: gosiD.enabled ? ('سعودي قديم ' + gosiD.saudiOldEr + '% · جديد ' + gosiD.saudiNewEr + '% · غير سعودي ' + gosiD.nonSaudiEr + '%') : 'موقوفة'
    });
    say(gosiD.enabled ? 'حُفظ إعداد التأمينات — تُحتسب لكل موظف مشمول ✓' : 'أُوقفت التأمينات');
  };
  // v11.0 — حفظ راتب وبدلات موظف
  const saveComp = async () => {
    const f = compF;
    const patch = { baseSalary: Number(f.baseSalary) || 0, housingAllowance: Number(f.housingAllowance) || 0, transportAllowance: Number(f.transportAllowance) || 0, otherAllowance: Number(f.otherAllowance) || 0, gosiSubject: !!f.gosiSubject, nationality: f.nationality || '', hireDate: (f.hireDate || '').trim(), iban: (f.iban || '').trim().replace(/\s/g, ''), idNumber: (f.idNumber || '').trim() };
    await commitOrg(d => ({ ...d, employees: (d.employees || []).map(x => x.id === f.id ? { ...x, ...patch } : x) }), {
      actionType: 'update', targetType: 'user_account', targetId: f.id,
      title: 'حدّث راتب/بدلات موظف', details: f.name + ' · أساسي ' + money(patch.baseSalary)
    });
    setCompF(null); say('حُفظ راتب ' + f.name + ' ✓');
  };

  return (
    <div className="grid" style={{ gap: 14 }}>
      {/* شريط التطبيق — v9.5 */}
      <div className="abar">
        <div className="abar-id"><span className="abar-ic"><Wallet size={17} /></span>الرواتب والسلف<small>مسير الرواتب · السلف والخصومات</small></div>
        <div className="abar-sp" />
        <div className="abar-dd">
          <button className="btn sm" onClick={() => setRepOpen(o => !o)}><FileBarChart size={14} />التقارير<ChevronDown size={13} /></button>
          {repOpen && (<>
            <div className="abar-back" onClick={() => setRepOpen(false)} />
            <div className="abar-menu">
              <div className="abar-hd">تقارير الرواتب</div>
              <button onClick={() => { setRepOpen(false); printMuster(); }}><Printer size={13} />مسير الرواتب الشهري</button>
            </div>
          </>)}
        </div>
      </div>

      <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 8 }}>
        <div className="row">
          <input type="month" className="inp" style={{ width: 165 }} value={month} onChange={e => setMonth(e.target.value)} />
          <span className="badge b-dim">{emps.length} موظف</span>
        </div>
        <div className="row" style={{ gap: 8, flexWrap: 'wrap' }}>
          {canPost && (accrualPosted
            ? <span className="badge b-mint"><Check size={11} />استحقاق {month} مُرحّل للدفتر</span>
            : <button className="btn" onClick={postAccrual}><Landmark size={14} />ترحيل استحقاق الشهر للدفتر</button>)}
          {canPost && !payoutPosted && (
            <select className="sel" style={{ width: 'auto' }} value={payFund} title="مصدر صرف الرواتب"
              onChange={e => setPayFund(e.target.value)}>
              <option value="1201">الصرف من البنك التجميعي</option>
              {branchBanks(org).map(bb => <option key={bb.code} value={bb.code}>الصرف من {bb.name}</option>)}
              <option value="1101">الصرف نقداً من الخزينة الرئيسية</option>
            </select>
          )}
          {canPost && (payoutPosted
            ? <span className="badge b-mint"><Check size={11} />صرف {month} مسجّل</span>
            : <button className="btn" disabled={!accrualPosted} onClick={postPayout}><Banknote size={14} />تسجيل صرف الرواتب</button>)}
          {canPost && payoutPosted && missingSlips > 0 && <button className="btn" onClick={issueSlips} title="لأشهر صُرفت قبل تفعيل التوقيع الإلكتروني"><Signature size={14} />إصدار قسائم الشهر للتوقيع ({missingSlips})</button>}
          {slipDocs.length > 0 && <span className={'badge ' + (slipSigned === slipDocs.length ? 'b-mint' : 'b-amber')} title="إقرارات استلام الراتب الموقَّعة إلكترونيًا"><Signature size={11} />التوقيعات {slipSigned}/{slipDocs.length}</span>}
          <button className="btn pri" onClick={() => setAdd(true)}><Plus size={15} />تسجيل سلفة أو خصم</button>
        </div>
      </div>

      <div className="grid g4">
        <Kpi label="إجمالي الاستحقاق (أساسي + بدلات)" value={money(totalGross)} icon={Wallet} color="#C8A24A" />
        <Kpi label="السلف والمسحوبات" value={money(sum(rows, r => r.draws))} icon={TrendingDown} color="#E0A458" />
        {gosiOn
          ? <Kpi label="التأمينات (موظف + عمل)" value={money(totalGosi)} sub={'استقطاع ' + money(totalGEmp) + ' · صاحب العمل ' + money(totalGEr)} icon={ShieldCheck} color="#5B93C4" />
          : <Kpi label="الخصومات والجزاءات" value={money(sum(rows, r => r.cuts))} icon={AlertTriangle} color="#D9544D" />}
        <Kpi label="صافي المستحق للصرف" value={money(totalNet)} sub={gosiOn ? 'بعد السلف والخصوم والتأمينات' : 'بعد السلف والخصوم'} icon={Banknote} color="#4FB286" />
      </div>

      {canPost && (
        <div className="card">
          <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 8, alignItems: 'center' }}>
            <label className="row" style={{ gap: 6, fontSize: 12.5, cursor: 'pointer' }}>
              <input type="checkbox" checked={gosiD.enabled} onChange={e => setGosiD(s => ({ ...s, enabled: e.target.checked }))} />
              <ShieldCheck size={15} color="var(--brass)" />تفعيل التأمينات الاجتماعية (GOSI)
            </label>
            <button className="btn pri" onClick={saveGosi} disabled={!gosiD.enabled}><Check size={14} />حفظ إعداد التأمينات</button>
          </div>
          {gosiD.enabled && (
            <div className="grid g3" style={{ gap: 8, marginTop: 10 }}>
              <Field label="سعودي (قديم) — موظف %"><input className="inp n" inputMode="decimal" value={gosiD.saudiOldEmp} onChange={e => setGosiD(s => ({ ...s, saudiOldEmp: e.target.value.replace(/[^\d.]/g, '') }))} /></Field>
              <Field label="سعودي (قديم) — صاحب العمل %"><input className="inp n" inputMode="decimal" value={gosiD.saudiOldEr} onChange={e => setGosiD(s => ({ ...s, saudiOldEr: e.target.value.replace(/[^\d.]/g, '') }))} /></Field>
              <Field label="سقف الأجر الخاضع (ر.س)"><input className="inp n" inputMode="decimal" value={gosiD.ceiling} onChange={e => setGosiD(s => ({ ...s, ceiling: e.target.value.replace(/[^\d.]/g, '') }))} /></Field>
              <Field label="سعودي (جديد ٢٠٢٤+) — موظف %"><input className="inp n" inputMode="decimal" value={gosiD.saudiNewEmp} onChange={e => setGosiD(s => ({ ...s, saudiNewEmp: e.target.value.replace(/[^\d.]/g, '') }))} /></Field>
              <Field label="سعودي (جديد ٢٠٢٤+) — صاحب العمل %"><input className="inp n" inputMode="decimal" value={gosiD.saudiNewEr} onChange={e => setGosiD(s => ({ ...s, saudiNewEr: e.target.value.replace(/[^\d.]/g, '') }))} /></Field>
              <div />
              <Field label="غير سعودي — موظف %"><input className="inp n" inputMode="decimal" value={gosiD.nonSaudiEmp} onChange={e => setGosiD(s => ({ ...s, nonSaudiEmp: e.target.value.replace(/[^\d.]/g, '') }))} /></Field>
              <Field label="غير سعودي — صاحب العمل % (أخطار مهنية)"><input className="inp n" inputMode="decimal" value={gosiD.nonSaudiEr} onChange={e => setGosiD(s => ({ ...s, nonSaudiEr: e.target.value.replace(/[^\d.]/g, '') }))} /></Field>
            </div>
          )}
          <div className="note" style={{ marginTop: 8 }}>تُحتسب على وعاء (الأساسي + السكن) بحدّ أقصى السقف، للموظفين المشمولين فقط. تُطبَّق النسبة حسب «جنسية» الموظف (تُحدَّد من «تعديل الراتب»): سعودي قديم/جديد بحسب تاريخ التعيين قبل/بعد ٣ يوليو ٢٠٢٤، أو غير سعودي (٢٪ أخطار مهنية على صاحب العمل فقط). عند عدم تحديد الجنسية تُستخدم نِسَب «سعودي (قديم)». القيم افتراضات نظامية حالية — راجِعها مع GOSI/مُدد. يظهر القيد في المحاسبة (5202/2202) عند تسجيل الصرف.</div>
        </div>
      )}

      <div className="card">
        <div className="card-t" style={{ marginBottom: 12 }}><Users size={15} color="var(--brass)" />كشف رواتب {month}</div>
        <div className="tw">
          <table className="tb">
            <thead><tr>
              <th>الموظف</th><th>الفرع</th><th style={{ textAlign: 'end' }}>الأساسي</th><th style={{ textAlign: 'end' }}>البدلات</th><th style={{ textAlign: 'end' }}>الإجمالي</th>
              <th style={{ textAlign: 'end' }}>سلف</th><th style={{ textAlign: 'end' }}>خصومات</th>{gosiOn && <th style={{ textAlign: 'end' }}>تأمينات</th>}<th style={{ textAlign: 'end' }}>الصافي</th><th>التوقيع</th><th></th>
            </tr></thead>
            <tbody>
              {rows.map(r => { const sd = slipDocOf(r.e.id); return (
                <tr key={r.e.id}>
                  <td>
                    <div style={{ fontSize: 12.5, fontWeight: 600 }}>{r.e.name}<span style={{ fontSize: 9.5, color: 'var(--faint)', marginInlineStart: 6 }}>{r.e.jobTitle}</span></div>
                    <div className="row" style={{ gap: 4, marginTop: 3 }}>
                      {r.flags > 0 && <span className="badge b-rose">{r.flags} سحبية غير مبررة</span>}
                      {gosiOn && r.e.gosiSubject && <span className="badge b-sky" style={{ fontSize: 9 }}>مشمول تأمينات</span>}
                    </div>
                  </td>
                  <td style={{ fontSize: 11.5, color: 'var(--dim)' }}>{org.branches.find(b => b.id === r.e.branchId)?.name}</td>
                  <td className="num" style={{ textAlign: 'end' }}>{money(r.e.baseSalary || 0)}</td>
                  <td className="num" style={{ textAlign: 'end', color: 'var(--dim)' }}>{r.allow ? money(r.allow) : '—'}</td>
                  <td className="num" style={{ textAlign: 'end', fontWeight: 600 }}>{money(r.gross)}</td>
                  <td className="num" style={{ textAlign: 'end', color: 'var(--amber)' }}>{r.draws ? money(r.draws) : '—'}</td>
                  <td className="num" style={{ textAlign: 'end', color: 'var(--rose)' }}>{r.cuts ? money(r.cuts) : '—'}</td>
                  {gosiOn && <td className="num" style={{ textAlign: 'end', color: 'var(--sky)' }}>{r.gEmp ? money(r.gEmp) : '—'}</td>}
                  <td className="num" style={{ textAlign: 'end', color: 'var(--mint)', fontWeight: 700 }}>{money(r.net)}</td>
                  <td>
                    {!sd && (payoutPosted && r.net > 0 ? <span className="badge b-dim" title="أصدرها من زر «إصدار قسائم الشهر للتوقيع»">لم تُصدر</span> : <span style={{ color: 'var(--faint)' }}>—</span>)}
                    {sd && sd.status === 'signed' && <span className="badge b-mint" title={'وُقِّع ' + new Date(sd.signedAt).toLocaleString('ar-SA') + (sd.pinVerified ? ' · PIN' : ' · بحضور ' + sd.witnessName)}><Check size={11} />موقَّع</span>}
                    {sd && sd.status === 'pending' && <span className="badge b-amber">بانتظار التوقيع</span>}
                  </td>
                  <td>
                    <div className="row" style={{ gap: 5, justifyContent: 'flex-end' }}>
                      {canPost && <button className="btn sm gh" onClick={() => setCompF({ id: r.e.id, name: r.e.name, baseSalary: String(r.e.baseSalary || 0), housingAllowance: String(r.e.housingAllowance || 0), transportAllowance: String(r.e.transportAllowance || 0), otherAllowance: String(r.e.otherAllowance || 0), gosiSubject: !!r.e.gosiSubject, nationality: r.e.nationality || '', hireDate: r.e.hireDate || '', iban: r.e.iban || '', idNumber: r.e.idNumber || r.e.iqamaNo || r.e.nationalId || '' })}>تعديل الراتب</button>}
                      {sd && sd.status === 'pending' && <button className="btn sm gh" onClick={() => setSignRow({ emp: r.e, doc: sd })} title="يوقّع الموظف هنا بحضورك (PIN أو شاهد)"><PenLine size={13} />توقيع الاستلام</button>}
                      <button className="btn sm gh" onClick={() => printPayslip(r)} title="قسيمة راتب"><Printer size={13} />قسيمة</button>
                    </div>
                  </td>
                </tr>
              ); })}
              {rows.length === 0 && <tr><td colSpan={gosiOn ? 11 : 10}><div className="empty">لا يوجد موظفون ضمن نطاقك.</div></td></tr>}
            </tbody>
          </table>
        </div>
      </div>

      {gosiOn && rows.some(r => r.gEmp > 0.004 || r.gEr > 0.004) && (
        <div className="card">
          <div className="card-h"><div className="card-t"><ShieldCheck size={15} color="var(--brass)" />التأمينات الاجتماعية — للتحويل عن شهر {month}</div>
            <span className="badge b-brass">الإجمالي للتحويل: <b className="num">{money(totalGosi)}</b></span></div>
          <div className="tw" style={{ marginTop: 8 }}>
            <table className="tb">
              <thead><tr><th>الموظف</th><th style={{ textAlign: 'end' }}>وعاء التأمين</th><th style={{ textAlign: 'end' }}>حصة الموظف</th><th style={{ textAlign: 'end' }}>حصة صاحب العمل</th><th style={{ textAlign: 'end' }}>الإجمالي</th></tr></thead>
              <tbody>
                {rows.filter(r => r.gEmp > 0.004 || r.gEr > 0.004).map(r => (
                  <tr key={r.e.id}>
                    <td style={{ fontSize: 12.5 }}>{r.e.name}</td>
                    <td className="num" style={{ textAlign: 'end', color: 'var(--dim)' }}>{money((r.e.gosiWage != null ? Number(r.e.gosiWage) || 0 : (r.e.baseSalary || 0) + (r.e.housingAllowance || 0)))}</td>
                    <td className="num" style={{ textAlign: 'end', color: 'var(--sky)' }}>{money(r.gEmp)}</td>
                    <td className="num" style={{ textAlign: 'end', color: 'var(--amber)' }}>{money(r.gEr)}</td>
                    <td className="num" style={{ textAlign: 'end', fontWeight: 700 }}>{money(r2(r.gEmp + r.gEr))}</td>
                  </tr>
                ))}
                <tr style={{ fontWeight: 800, background: 'rgba(200,162,74,.05)' }}>
                  <td>الإجمالي</td><td /><td className="num" style={{ textAlign: 'end' }}>{money(totalGEmp)}</td><td className="num" style={{ textAlign: 'end' }}>{money(totalGEr)}</td><td className="num" style={{ textAlign: 'end' }}>{money(totalGosi)}</td>
                </tr>
              </tbody>
            </table>
          </div>
          <div className="note" style={{ marginTop: 8 }}>حصة الموظف مُستقطعة من صافي راتبه، وحصة صاحب العمل مصروف على المنشأة — كلاهما التزام يُحوَّل للتأمينات (حساب 2202). يُرحَّل قيدهما تلقائيًا عند «تسجيل صرف الرواتب».</div>
        </div>
      )}

      <div className="card">
        <div className="card-t" style={{ marginBottom: 12 }}><Receipt size={15} color="var(--brass)" />حركة السلف والخصومات</div>
        <div className="tw">
          <table className="tb">
            <thead><tr><th>التاريخ</th><th>الموظف</th><th>النوع</th><th>المبلغ</th><th>السبب</th><th>سجّله</th></tr></thead>
            <tbody>
              {scoped.advances.filter(a => a.month === month).sort((a, b) => b.date.localeCompare(a.date)).map(a => (
                <tr key={a.id}>
                  <td className="num" style={{ whiteSpace: 'nowrap' }}>{arDate(a.date)}</td>
                  <td style={{ fontSize: 12 }}>{a.employeeName}</td>
                  <td><span className={'badge ' + (['advance', 'salary_draw'].includes(a.type) ? 'b-amber' : a.type === 'bonus' ? 'b-mint' : 'b-rose')}>
                    {{ advance: 'سلفة', salary_draw: 'مسحوبة', discount: 'خصم', absence_penalty: 'غياب', lateness_penalty: 'تأخير', bonus: 'مكافأة معتمدة', discipline_penalty: 'جزاء معتمد', other: 'أخرى' }[a.type] || a.type}
                  </span></td>
                  <td className="num">{money(a.amount)}</td>
                  <td style={{ fontSize: 11.5, color: 'var(--dim)' }}>{a.reason}</td>
                  <td style={{ fontSize: 11.5, color: 'var(--faint)' }}>{a.createdByName}</td>
                </tr>
              ))}
              {scoped.advances.filter(a => a.month === month).length === 0 &&
                <tr><td colSpan={6}><div className="empty">لا حركات مسجلة لهذا الشهر.</div></td></tr>}
            </tbody>
          </table>
        </div>
      </div>

      <div className="card">
        <div className="card-h">
          <div className="card-t"><ShieldCheck size={15} color="var(--brass)" />الأجور والتسويات — حماية الأجور ونهاية الخدمة</div>
          {canPay && <button className="btn sm" onClick={exportWPS}><Download size={13} />ملف حماية الأجور (WPS)</button>}
        </div>
        <div className="tw">
          <table className="tb">
            <thead><tr><th>الموظف</th><th>تاريخ التعيين</th><th>مدة الخدمة</th><th style={{ textAlign: 'end' }}>الأجر الشهري</th><th style={{ textAlign: 'end' }}>مكافأة نهاية الخدمة (لو انتهت اليوم)</th><th /></tr></thead>
            <tbody>
              {emps.map(e => { const wage = empGrossOf(e); const yrs = tenureYears(e.hireDate, today()); const full = r2(eosFull(wage, yrs)); return (
                <tr key={e.id}>
                  <td style={{ fontWeight: 600, fontSize: 12.5 }}>{e.name}</td>
                  <td className="num" style={{ fontSize: 11 }}>{e.hireDate || <span style={{ color: 'var(--amber)' }}>غير محدّد</span>}</td>
                  <td className="num" style={{ fontSize: 11 }}>{e.hireDate ? fmtYears(yrs) : '—'}</td>
                  <td className="num" style={{ textAlign: 'end' }}>{money(wage)}</td>
                  <td className="num" style={{ textAlign: 'end', fontWeight: 700 }}>{e.hireDate ? money(full) : '—'}</td>
                  <td><button className="btn sm gh" onClick={() => setEosF({ id: e.id, reason: 'termination', endDate: today(), leaveDays: '' })}>تسوية</button></td>
                </tr>
              ); })}
              {emps.length === 0 && <tr><td colSpan={6}><div className="empty">لا موظفون في نطاقك.</div></td></tr>}
              {emps.length > 0 && (() => { const tot = r2(sum(emps, e => eosFull(empGrossOf(e), tenureYears(e.hireDate, today())))); return (
                <tr style={{ fontWeight: 800, background: 'rgba(200,162,74,.05)' }}>
                  <td colSpan={4}>مخصّص نهاية الخدمة التقديري (لو انتهت خدمة الجميع اليوم)</td>
                  <td className="num" style={{ textAlign: 'end', color: 'var(--brass-l)' }}>{money(tot)}</td><td />
                </tr>
              ); })()}
            </tbody>
          </table>
        </div>
        <div className="note" style={{ marginTop: 10 }}>ملف حماية الأجور (WPS) يُصدَّر CSV من مسير الشهر — أكمِل الآيبان ورقم الهوية لكل موظف من «تعديل الراتب». مكافأة نهاية الخدمة وفق نظام العمل السعودي (نصف شهر لكل سنة في الخمس الأولى، وشهر كامل لما بعدها). أضِف تاريخ التعيين ليظهر حسابها. اضغط «تسوية» لمخالصة مفصّلة بسبب الانتهاء وبدل الإجازة.</div>
      </div>

      {add && <AdvanceForm emps={emps} org={org} me={me} commit={commit} say={say} onClose={() => setAdd(false)} />}
      {signRow && <SignDocsModal org={org} ops={ops} me={me} emp={signRow.emp} docs={[signRow.doc]} onClose={() => setSignRow(null)} commit={commit} say={say} via="central" />}

      {eosF && (() => {
        const emp = emps.find(e => e.id === eosF.id); if (!emp) return null;
        const wage = empGrossOf(emp), years = tenureYears(emp.hireDate, eosF.endDate);
        const full = r2(eosFull(wage, years)), entitled = r2(eosEntitled(wage, years, eosF.reason));
        const leaveDays = Number(String(eosF.leaveDays).replace(/[^\d.]/g, '')) || 0, leavePay = r2(leaveDays * wage / 30);
        const total = r2(entitled + leavePay);
        const calc = { endDate: eosF.endDate, reason: eosF.reason, years, wage, full, entitled, leaveDays, leavePay, total };
        return (
          <Modal title={'تسوية نهاية الخدمة — ' + emp.name} icon={ShieldCheck} onClose={() => setEosF(null)}
            foot={<><button className="btn gh" onClick={() => setEosF(null)}>إغلاق</button><button className="btn pri" disabled={!emp.hireDate} onClick={() => printEOSlip(emp, calc)}><Printer size={14} />طباعة المخالصة</button></>}>
            {!emp.hireDate ? <div className="note">أضف «تاريخ التعيين» لهذا الموظف من «تعديل الراتب» أولًا لحساب المدة والمكافأة.</div> : <>
              <div className="grid g2">
                <Field label="سبب انتهاء الخدمة">
                  <select className="inp" value={eosF.reason} onChange={e => setEosF(f => ({ ...f, reason: e.target.value }))}>
                    <option value="termination">إنهاء من صاحب العمل</option>
                    <option value="resignation">استقالة</option>
                  </select>
                </Field>
                <Field label="تاريخ انتهاء الخدمة"><input className="inp" type="date" value={eosF.endDate} onChange={e => setEosF(f => ({ ...f, endDate: e.target.value }))} /></Field>
                <Field label="أيام إجازة متبقية (اختياري)"><input className="inp n" inputMode="decimal" value={eosF.leaveDays} onChange={e => setEosF(f => ({ ...f, leaveDays: e.target.value.replace(/[^\d.]/g, '') }))} /></Field>
                <Field label="الأجر الشهري"><input className="inp n" value={money(wage)} disabled /></Field>
              </div>
              <div className="card" style={{ background: 'rgba(200,162,74,.05)', marginTop: 10 }}>
                {[['مدة الخدمة', fmtYears(years)], ['المكافأة الكاملة', money(full)], ['المستحق حسب السبب', money(entitled)], leaveDays ? ['بدل الإجازة المتبقية', money(leavePay)] : null].filter(Boolean).map((x, i) => (
                  <div key={i} className="row" style={{ justifyContent: 'space-between', fontSize: 12.5, padding: '3px 0' }}><span>{x[0]}</span><b className="num">{x[1]}</b></div>
                ))}
                <div className="row" style={{ justifyContent: 'space-between', fontWeight: 900, fontSize: 14, borderTop: '1px solid var(--frame-o)', marginTop: 6, paddingTop: 6 }}><span>إجمالي المخالصة</span><b className="num" style={{ color: 'var(--brass-l)' }}>{money(total)}</b></div>
              </div>
              <div className="note" style={{ marginTop: 8 }}>وفق نظام العمل: نصف شهر لكل سنة في الخمس الأولى وشهر كامل لما بعدها. الاستقالة: لا شيء تحت سنتين، الثلث حتى ٥ سنوات، الثلثان حتى ١٠، وكامل بعدها. تقدير استرشادي.</div>
            </>}
          </Modal>
        );
      })()}

      {compF && (
        <Modal title={'راتب وبدلات — ' + compF.name} icon={Wallet} onClose={() => setCompF(null)}
          foot={<><button className="btn gh" onClick={() => setCompF(null)}>إلغاء</button>
            <button className="btn pri" onClick={saveComp}><Check size={14} />حفظ</button></>}>
          <div className="grid g2">
            <Field label="الراتب الأساسي"><input className="inp n" inputMode="decimal" value={compF.baseSalary} onChange={e => setCompF(f => ({ ...f, baseSalary: e.target.value.replace(/[^\d.]/g, '') }))} /></Field>
            <Field label="بدل السكن"><input className="inp n" inputMode="decimal" value={compF.housingAllowance} onChange={e => setCompF(f => ({ ...f, housingAllowance: e.target.value.replace(/[^\d.]/g, '') }))} /></Field>
            <Field label="بدل النقل"><input className="inp n" inputMode="decimal" value={compF.transportAllowance} onChange={e => setCompF(f => ({ ...f, transportAllowance: e.target.value.replace(/[^\d.]/g, '') }))} /></Field>
            <Field label="بدلات أخرى"><input className="inp n" inputMode="decimal" value={compF.otherAllowance} onChange={e => setCompF(f => ({ ...f, otherAllowance: e.target.value.replace(/[^\d.]/g, '') }))} /></Field>
          </div>
          <div className="grid g2" style={{ marginTop: 8 }}>
            <Field label="الجنسية (لنِسبة التأمينات)"><select className="inp sel" value={compF.nationality || ''} onChange={e => setCompF(f => ({ ...f, nationality: e.target.value }))}><option value="">غير محدّد</option><option value="saudi">سعودي</option><option value="nonSaudi">غير سعودي</option></select></Field>
            <Field label="تاريخ التعيين (نهاية الخدمة + نظام التأمينات)"><input className="inp" type="date" value={compF.hireDate} onChange={e => setCompF(f => ({ ...f, hireDate: e.target.value }))} /></Field>
            <Field label="رقم الهوية/الإقامة (لحماية الأجور)"><input className="inp n" value={compF.idNumber} onChange={e => setCompF(f => ({ ...f, idNumber: e.target.value }))} /></Field>
            <Field label="الآيبان IBAN (لحماية الأجور)" style={{ gridColumn: '1 / -1' }}><input className="inp n" value={compF.iban} placeholder="SA00 0000 0000 0000 0000 0000" onChange={e => setCompF(f => ({ ...f, iban: e.target.value }))} /></Field>
          </div>
          <label className="row" style={{ gap: 6, fontSize: 12.5, cursor: 'pointer', marginTop: 8 }}>
            <input type="checkbox" checked={compF.gosiSubject} onChange={e => setCompF(f => ({ ...f, gosiSubject: e.target.checked }))} />
            مشمول بالتأمينات الاجتماعية (تُحتسب على الأساسي + السكن)
          </label>
          <div className="card" style={{ background: 'rgba(200,162,74,.05)', marginTop: 8 }}>
            <div className="row" style={{ justifyContent: 'space-between', fontWeight: 800, fontSize: 13.5 }}>
              <span>إجمالي الاستحقاق الشهري</span>
              <b className="num">{money(r2((Number(compF.baseSalary) || 0) + (Number(compF.housingAllowance) || 0) + (Number(compF.transportAllowance) || 0) + (Number(compF.otherAllowance) || 0)))}</b>
            </div>
          </div>
          <div className="note">يُطبَّق على مسير هذا الشهر والأشهر القادمة. تعديل الراتب لا يغيّر أشهرًا سبق ترحيل استحقاقها.</div>
        </Modal>
      )}
    </div>
  );
}

// م٣ (v27.8) — بناء وصف وظيفي كامل قابل للطباعة من حقول الوظيفة
function positionJdHtml(pos, org) {
  const progs = (org.trainingPrograms && org.trainingPrograms.length) ? org.trainingPrograms : defaultTrainingPrograms();
  const posName = (id) => ((org.positions || []).find(p => p.id === id) || {}).title || '—';
  const deptName = ((org.departments || []).find(d => d.id === pos.departmentId) || {}).name || '—';
  const list = (s) => { const items = String(s || '').split(/\r?\n/).map(x => x.trim()).filter(Boolean); return items.length ? '<ul style="margin:4px 0;padding-inline-start:18px">' + items.map(i => '<li>' + escH(i) + '</li>').join('') + '</ul>' : '—'; };
  const reqT = (pos.requiredTrainingIds || []).map(id => (progs.find(p => p.id === id) || {}).title).filter(Boolean);
  const row = (k, v) => '<tr><td style="width:160px;color:#555;vertical-align:top">' + k + '</td><td>' + v + '</td></tr>';
  return '<table><tbody>' +
    row('المسمى الوظيفي', '<b>' + escH(pos.title) + '</b>') +
    row('الكود / الدرجة / المستوى', [pos.code, pos.grade, pos.level].map(x => escH(x || '—')).join(' · ')) +
    row('القسم', escH(deptName)) +
    row('يرفع تقاريره إلى', escH(posName(pos.reportsToId))) +
    row('الوظيفة البديلة', escH(posName(pos.backupPositionId))) +
    row('ملخص الوظيفة', escH(pos.summary || '—')) +
    row('المهام والمسؤوليات', list(pos.duties)) +
    row('المؤهلات والخبرات', list(pos.qualifications)) +
    row('الجدارات والمهارات', list(pos.competencies)) +
    row('الصلاحيات', list(pos.authorities)) +
    row('القيود والمحظورات', list(pos.restrictions)) +
    row('التدريب/الشهادات المطلوبة', reqT.length ? escH(reqT.join('، ')) : '—') +
    '</tbody></table>';
}
function HrMaster({ org, ops, me, commitOrg, commit, say }) {
  const [view, setView] = useState('depts');
  const [deptF, setDeptF] = useState(null);
  const [posF, setPosF] = useState(null);
  const [jdView, setJdView] = useState(null);
  const [assignF, setAssignF] = useState(null);
  const [docsFor, setDocsFor] = useState(null);
  const [docF, setDocF] = useState(null);
  const [empF, setEmpF] = useState(null); // v25.1: نموذج موظف جديد (لم يكن للموظفين نموذج إنشاء مباشر — كانوا يُضافون فقط عبر مسارات الشركاء)

  const depts = org.departments || [];
  const positions = org.positions || [];
  const emps = org.employees || [];
  const DOC_KINDS = { contract: 'عقد عمل', id: 'هوية/إقامة', cert: 'شهادة/مؤهل', license: 'رخصة/ترخيص', other: 'أخرى' };

  const posCountByDept = (dId) => positions.filter(p => p.departmentId === dId).length;
  const empCountByDept = (dId) => emps.filter(e => e.departmentId === dId).length;
  const empCountByPos = (pId) => emps.filter(e => e.positionId === pId).length;

  const saveDept = async () => {
    const f = deptF; const name = (f.name || '').trim();
    if (!name) return say('اسم القسم مطلوب', 'no');
    const isNew = !f.id;
    const id = f.id || uid('dept');
    await commitOrg(d => ({
      ...d, departments: isNew
        ? [...(d.departments || []), { id, name, note: (f.note || '').trim(), active: true }]
        : (d.departments || []).map(x => x.id === id ? { ...x, name, note: (f.note || '').trim() } : x)
    }), { actionType: isNew ? 'create' : 'update', targetType: 'user_account', targetId: id, title: (isNew ? 'أضاف قسمًا' : 'حدّث قسمًا') + ': ' + name, details: f.note || '' });
    setDeptF(null); say((isNew ? 'أُضيف القسم' : 'حُفظ القسم') + ' ✓');
  };
  const toggleDept = async (d) => {
    await commitOrg(x => ({ ...x, departments: (x.departments || []).map(y => y.id === d.id ? { ...y, active: !y.active } : y) }),
      { actionType: 'update', targetType: 'user_account', targetId: d.id, title: (d.active === false ? 'فعّل قسمًا' : 'عطّل قسمًا') + ': ' + d.name, details: '' });
    say(d.active === false ? 'أُعيد تفعيل القسم' : 'عُطّل القسم');
  };
  const delDept = async (d) => {
    if (posCountByDept(d.id) > 0 || empCountByDept(d.id) > 0) return say('لا يمكن حذف قسم مرتبط بوظائف أو موظفين — استخدم «تعطيل» بدلًا من ذلك', 'no');
    if (!window.confirm('حذف القسم «' + d.name + '» نهائيًا؟')) return;
    await commitOrg(x => ({ ...x, departments: (x.departments || []).filter(y => y.id !== d.id) }),
      { actionType: 'delete', targetType: 'user_account', targetId: d.id, title: 'حذف قسمًا: ' + d.name, details: '' });
    say('حُذف القسم');
  };

  const savePos = async () => {
    const f = posF; const title = (f.title || '').trim();
    if (!title) return say('المسمى الوظيفي مطلوب', 'no');
    const isNew = !f.id;
    const id = f.id || uid('pos');
    const jd = {
      code: (f.code || '').trim(), grade: (f.grade || '').trim(), level: (f.level || '').trim(),
      reportsToId: f.reportsToId || '', backupPositionId: f.backupPositionId || '',
      summary: (f.summary || '').trim(), duties: (f.duties || '').trim(),
      qualifications: (f.qualifications || '').trim(), competencies: (f.competencies || '').trim(),
      authorities: (f.authorities || '').trim(), restrictions: (f.restrictions || '').trim(),
      requiredTrainingIds: Array.isArray(f.requiredTrainingIds) ? f.requiredTrainingIds : []
    };
    await commitOrg(d => ({
      ...d, positions: isNew
        ? [...(d.positions || []), { id, title, departmentId: f.departmentId || '', ...jd, active: true }]
        : (d.positions || []).map(x => x.id === id ? { ...x, title, departmentId: f.departmentId || '', ...jd } : x)
    }), { actionType: isNew ? 'create' : 'update', targetType: 'user_account', targetId: id, title: (isNew ? 'أضاف وظيفة' : 'حدّث وظيفة') + ': ' + title, details: (depts.find(x => x.id === f.departmentId) || {}).name || '' });
    setPosF(null); say((isNew ? 'أُضيفت الوظيفة' : 'حُفظت الوظيفة') + ' ✓');
  };
  const togglePos = async (p) => {
    await commitOrg(x => ({ ...x, positions: (x.positions || []).map(y => y.id === p.id ? { ...y, active: !y.active } : y) }),
      { actionType: 'update', targetType: 'user_account', targetId: p.id, title: (p.active === false ? 'فعّل وظيفة' : 'عطّل وظيفة') + ': ' + p.title, details: '' });
    say(p.active === false ? 'أُعيد تفعيل الوظيفة' : 'عُطّلت الوظيفة');
  };
  const delPos = async (p) => {
    if (empCountByPos(p.id) > 0) return say('لا يمكن حذف وظيفة مُسندة لموظفين — استخدم «تعطيل» بدلًا من ذلك', 'no');
    if (!window.confirm('حذف الوظيفة «' + p.title + '» نهائيًا؟')) return;
    await commitOrg(x => ({ ...x, positions: (x.positions || []).filter(y => y.id !== p.id) }),
      { actionType: 'delete', targetType: 'user_account', targetId: p.id, title: 'حذف وظيفة: ' + p.title, details: '' });
    say('حُذفت الوظيفة');
  };

  const saveAssign = async () => {
    const f = assignF;
    const pos = positions.find(p => p.id === f.positionId);
    await commitOrg(d => ({
      ...d, employees: (d.employees || []).map(x => x.id === f.id ? {
        ...x, departmentId: f.departmentId || '', positionId: f.positionId || '',
        jobTitle: (f.syncTitle && pos) ? pos.title : x.jobTitle
      } : x)
    }), { actionType: 'update', targetType: 'user_account', targetId: f.id, title: 'حدّث القسم/الوظيفة لموظف', details: f.name + (pos ? ' → ' + pos.title : '') });
    setAssignF(null); say('حُفظ ✓');
  };

  // v25.1 — إنشاء موظف جديد مباشرة من البيانات الرئيسية (أدوار المركز)؛ v26.1 — التعديل بنفس النموذج
  const empToForm = (e) => ({ id: e.id, name: e.name || '', branchId: e.branchId || '', jobTitle: e.jobTitle || '', departmentId: e.departmentId || '', positionId: e.positionId || '', phone: e.phone || '', idNumber: e.idNumber || e.iqamaNo || e.nationalId || '', nationality: e.nationality || '', hireDate: e.hireDate || '', baseSalary: String(e.baseSalary || 0), housingAllowance: String(e.housingAllowance || 0), transportAllowance: String(e.transportAllowance || 0), gosiSubject: !!e.gosiSubject });
  const saveEmp = async () => {
    const f = empF; const name = (f.name || '').trim();
    if (!name) return say('اسم الموظف مطلوب', 'no');
    if (!f.branchId) return say('اختر فرع الموظف — بدونه لن يظهر في شاشات الحضور والمهام', 'no');
    const pos = positions.find(p => p.id === f.positionId);
    const patch = {
      name, branchId: f.branchId,
      jobTitle: (f.jobTitle || '').trim() || (pos ? pos.title : ''), departmentId: f.departmentId || (pos ? pos.departmentId || '' : ''), positionId: f.positionId || '',
      phone: (f.phone || '').trim(), idNumber: (f.idNumber || '').trim(), nationality: f.nationality || '', hireDate: f.hireDate || '',
      baseSalary: Number(f.baseSalary) || 0, housingAllowance: Number(f.housingAllowance) || 0, transportAllowance: Number(f.transportAllowance) || 0,
      gosiSubject: !!f.gosiSubject
    };
    if (f.id) {
      const prev = emps.find(x => x.id === f.id) || {};
      const branchChanged = prev.branchId && prev.branchId !== patch.branchId;
      const ok = await commitOrg(d => ({ ...d, employees: (d.employees || []).map(x => x.id === f.id ? { ...x, ...patch, updatedAt: nowISO(), updatedByName: me.name } : x) }),
        { actionType: 'update', targetType: 'user_account', targetId: f.id, branchName: ((org.branches || []).find(b => b.id === patch.branchId) || {}).name || '', title: 'عدّل بيانات موظف', details: name + (branchChanged ? ' — نُقل إلى فرع آخر' : '') });
      if (!ok) return;
      setEmpF(null); say('حُدِّثت بيانات «' + name + '» ✓' + (branchChanged ? ' — أعد ضبط PIN/البطاقة في فرعه الجديد' : ''));
      return;
    }
    if (emps.some(x => (x.name || '').trim() === name && x.branchId === f.branchId && x.isActive !== false) && !window.confirm('يوجد موظف نشط بنفس الاسم في هذا الفرع — إضافة موظف آخر بنفس الاسم؟')) return;
    const id = uid('emp');
    const rec = { id, code: nextPartnerCode(buildPartners(org, {}), 'employee'), ...patch, otherAllowance: 0, isActive: true, docs: [], createdAt: nowISO(), createdByName: me.name };
    const ok = await commitOrg(d => ({ ...d, employees: [...(d.employees || []), rec] }),
      { actionType: 'create', targetType: 'user_account', targetId: id, branchName: ((org.branches || []).find(b => b.id === rec.branchId) || {}).name || '', title: 'أضاف موظفًا جديدًا', details: name + (rec.jobTitle ? ' — ' + rec.jobTitle : '') + ' · ' + rec.code });
    if (!ok) return;
    setEmpF(null);
    say('أُضيف الموظف «' + name + '» ✓ — اضبط له رقم PIN أو أصدر بطاقة QR من «الحضور الموثَّق ← أرقام PIN»');
  };
  // v26.1 — إيقاف/تفعيل (حذف ناعم يحفظ التاريخ المالي)، وحذف نهائي فقط لموظف بلا أي سجلات
  const toggleEmp = async (e) => {
    const off = e.isActive !== false;
    if (!window.confirm((off ? 'إيقاف الموظف «' : 'إعادة تفعيل الموظف «') + e.name + '»؟' + (off ? ' سيختفي من الرواتب والحضور والمهام مع بقاء كل سجلاته.' : ''))) return;
    await commitOrg(d => ({ ...d, employees: (d.employees || []).map(x => x.id === e.id ? { ...x, isActive: !off, ...(off ? { endDate: today() } : { endDate: '' }) } : x) }),
      { actionType: 'update', targetType: 'user_account', targetId: e.id, title: off ? 'أوقف موظفًا' : 'أعاد تفعيل موظف', details: e.name });
    say(off ? 'أُوقف الموظف — سجلاته محفوظة' : 'أُعيد تفعيل الموظف ✓');
  };
  const empRecordCount = (e) => {
    const o = ops || {}; const key = 'emp:' + e.id;
    return (o.advances || []).filter(a => a.employeeId === e.id).length + (o.ledgerEntries || []).filter(l => l.partnerKey === key).length
      + (o.attendanceEvents || []).filter(x => x.employeeId === e.id).length + (o.shiftAssignments || []).filter(x => x.empId === e.id && (x.shiftIds || []).some(Boolean)).length
      + (o.taskAssignments || []).filter(x => x.employeeId === e.id).length + (o.taskCompletions || []).filter(x => x.employeeId === e.id).length
      + (o.pointsEntries || []).filter(x => x.employeeId === e.id).length + (o.qualityReviews || []).filter(x => x.employeeId === e.id).length + (o.rewardRequests || []).filter(x => x.employeeId === e.id).length
      + (o.hrSignDocs || []).filter(x => x.employeeId === e.id).length
      + (o.closings || []).filter(c => JSON.stringify(c).includes('"' + key + '"')).length;
  };
  const deleteEmp = async (e) => {
    const n = empRecordCount(e);
    if (n > 0) return say('لا يمكن الحذف النهائي: للموظف ' + n + ' سجلًا (رواتب/حضور/مهام/نقاط…) — استخدم «إيقاف» للحفاظ على التاريخ', 'no');
    if (!window.confirm('حذف الموظف «' + e.name + '» نهائيًا؟ لا يمكن التراجع.')) return;
    const ok = await commitOrg(d => ({ ...d, employees: (d.employees || []).filter(x => x.id !== e.id) }),
      { actionType: 'delete', targetType: 'user_account', targetId: e.id, title: 'حذف موظف نهائيًا (بلا سجلات)', details: e.name });
    if (!ok) return;
    if (commit && ((ops || {}).hrPins || []).some(p => p.employeeId === e.id)) await commit(d => ({ ...d, hrPins: (d.hrPins || []).filter(p => p.employeeId !== e.id) }));
    say('حُذف الموظف نهائيًا');
  };
  const [showInactive, setShowInactive] = useState(false);

  const empDocs = (e) => e.docs || [];
  const saveDoc = async () => {
    const f = docF; const emp = docsFor;
    if (!(f.title || '').trim()) return say('عنوان المستند مطلوب', 'no');
    const isNew = !f.id;
    const id = f.id || uid('edoc');
    const entry = { id, kind: f.kind || 'other', title: f.title.trim(), number: (f.number || '').trim(), issueDate: f.issueDate || '', expiryDate: f.expiryDate || '', file: f.file || '' };
    await commitOrg(d => ({
      ...d, employees: (d.employees || []).map(x => x.id === emp.id ? {
        ...x, docs: isNew ? [...(x.docs || []), entry] : (x.docs || []).map(y => y.id === id ? entry : y)
      } : x)
    }), { actionType: isNew ? 'create' : 'update', targetType: 'user_account', targetId: emp.id, title: (isNew ? 'أضاف مستند موظف' : 'حدّث مستند موظف') + ': ' + entry.title, details: emp.name });
    setDocF(null); say('حُفظ المستند ✓');
    setDocsFor(d => d ? { ...d, docs: isNew ? [...(d.docs || []), entry] : (d.docs || []).map(y => y.id === id ? entry : y) } : d);
  };
  const delDoc = async (docId) => {
    const emp = docsFor;
    if (!window.confirm('حذف هذا المستند؟')) return;
    await commitOrg(d => ({ ...d, employees: (d.employees || []).map(x => x.id === emp.id ? { ...x, docs: (x.docs || []).filter(y => y.id !== docId) } : x) }),
      { actionType: 'delete', targetType: 'user_account', targetId: emp.id, title: 'حذف مستند موظف', details: emp.name });
    say('حُذف المستند');
    setDocsFor(d => d ? { ...d, docs: (d.docs || []).filter(y => y.id !== docId) } : d);
  };

  const expiryTag = (dt) => {
    if (!dt) return null;
    const days = Math.round((Date.parse(dt + 'T00:00:00') - Date.parse(today() + 'T00:00:00')) / 86400000);
    if (days < 0) return <span className="badge b-rose">منتهٍ منذ {Math.abs(days)} يوم</span>;
    if (days <= 30) return <span className="badge b-amber">ينتهي خلال {days} يوم</span>;
    return <span className="badge b-mint">ساري</span>;
  };

  return (
    <div className="grid" style={{ gap: 12 }}>
      <div className="card" style={{ padding: '8px 12px' }}>
        <div className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
          <button className={'btn sm' + (view === 'depts' ? ' pri' : ' gh')} onClick={() => setView('depts')}><Building2 size={13} />الأقسام</button>
          <button className={'btn sm' + (view === 'positions' ? ' pri' : ' gh')} onClick={() => setView('positions')}><UserCog size={13} />الوظائف</button>
          <button className={'btn sm' + (view === 'emps' ? ' pri' : ' gh')} onClick={() => setView('emps')}><FileText size={13} />بيانات ومستندات الموظفين</button>
        </div>
      </div>

      {view === 'depts' && (
        <div className="card">
          <div className="card-h">
            <div className="card-t"><Building2 size={15} color="var(--brass)" />الأقسام</div>
            <button className="btn sm" onClick={() => setDeptF({ name: '', note: '' })}><Plus size={13} />قسم جديد</button>
          </div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>القسم</th><th>ملاحظة</th><th style={{ textAlign: 'end' }}>الوظائف</th><th style={{ textAlign: 'end' }}>الموظفون</th><th>الحالة</th><th /></tr></thead>
              <tbody>
                {depts.map(d => (
                  <tr key={d.id}>
                    <td style={{ fontWeight: 600 }}>{d.name}</td>
                    <td style={{ fontSize: 11.5, color: 'var(--dim)' }}>{d.note || '—'}</td>
                    <td className="num" style={{ textAlign: 'end' }}>{posCountByDept(d.id)}</td>
                    <td className="num" style={{ textAlign: 'end' }}>{empCountByDept(d.id)}</td>
                    <td>{d.active === false ? <span className="badge b-dim">معطّل</span> : <span className="badge b-mint">نشط</span>}</td>
                    <td>
                      <div className="row" style={{ gap: 5, justifyContent: 'flex-end' }}>
                        <button className="btn sm gh" onClick={() => setDeptF({ id: d.id, name: d.name, note: d.note || '' })}>تعديل</button>
                        <button className="btn sm gh" onClick={() => toggleDept(d)}>{d.active === false ? 'تفعيل' : 'تعطيل'}</button>
                        <button className="btn sm gh" style={{ color: 'var(--rose)' }} onClick={() => delDept(d)}><Trash2 size={13} /></button>
                      </div>
                    </td>
                  </tr>
                ))}
                {depts.length === 0 && <tr><td colSpan={6}><div className="empty">لا توجد أقسام بعد — أضف أول قسم.</div></td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {view === 'positions' && (
        <div className="card">
          <div className="card-h">
            <div className="card-t"><UserCog size={15} color="var(--brass)" />الوظائف</div>
            <button className="btn sm" onClick={() => setPosF({ title: '', departmentId: depts[0]?.id || '', code: '', grade: '', level: '', reportsToId: '', backupPositionId: '', summary: '', duties: '', qualifications: '', competencies: '', authorities: '', restrictions: '', requiredTrainingIds: [] })} disabled={depts.length === 0}><Plus size={13} />وظيفة جديدة</button>
          </div>
          {depts.length === 0 && <div className="note">أضف قسمًا واحدًا على الأقل أولًا قبل إنشاء وظيفة.</div>}
          <div className="tw">
            <table className="tb">
              <thead><tr><th>الوظيفة</th><th>القسم</th><th style={{ textAlign: 'end' }}>الموظفون</th><th>الحالة</th><th /></tr></thead>
              <tbody>
                {positions.map(p => (
                  <tr key={p.id}>
                    <td style={{ fontWeight: 600 }}>{p.title}{p.duties && <div style={{ fontSize: 10.5, color: 'var(--faint)', fontWeight: 400, marginTop: 2 }}>{p.duties.slice(0, 80)}{p.duties.length > 80 ? '…' : ''}</div>}</td>
                    <td style={{ fontSize: 12 }}>{(depts.find(d => d.id === p.departmentId) || {}).name || <span style={{ color: 'var(--amber)' }}>بلا قسم</span>}</td>
                    <td className="num" style={{ textAlign: 'end' }}>{empCountByPos(p.id)}</td>
                    <td>{p.active === false ? <span className="badge b-dim">معطّلة</span> : <span className="badge b-mint">نشطة</span>}</td>
                    <td>
                      <div className="row" style={{ gap: 5, justifyContent: 'flex-end' }}>
                        <button className="btn sm gh" onClick={() => setJdView(p)}><FileText size={13} />الوصف</button>
                        <button className="btn sm gh" onClick={() => setPosF({ id: p.id, title: p.title, departmentId: p.departmentId || '', code: p.code || '', grade: p.grade || '', level: p.level || '', reportsToId: p.reportsToId || '', backupPositionId: p.backupPositionId || '', summary: p.summary || '', duties: p.duties || '', qualifications: p.qualifications || '', competencies: p.competencies || '', authorities: p.authorities || '', restrictions: p.restrictions || '', requiredTrainingIds: p.requiredTrainingIds || [] })}>تعديل</button>
                        <button className="btn sm gh" onClick={() => togglePos(p)}>{p.active === false ? 'تفعيل' : 'تعطيل'}</button>
                        <button className="btn sm gh" style={{ color: 'var(--rose)' }} onClick={() => delPos(p)}><Trash2 size={13} /></button>
                      </div>
                    </td>
                  </tr>
                ))}
                {positions.length === 0 && <tr><td colSpan={5}><div className="empty">لا توجد وظائف بعد.</div></td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {view === 'emps' && (
        <div className="card">
          <div className="card-h" style={{ marginBottom: 10 }}>
            <div className="card-t"><Users size={15} color="var(--brass)" />الموظفون — القسم والوظيفة والمستندات</div>
            <div className="row" style={{ gap: 6 }}>
              <label className="row" style={{ gap: 5, fontSize: 12, cursor: 'pointer' }}><input type="checkbox" checked={showInactive} onChange={e => setShowInactive(e.target.checked)} />إظهار الموقوفين</label>
              <button className="btn sm pri" onClick={() => setEmpF({ name: '', branchId: ((org.branches || []).find(b => b.isActive !== false) || {}).id || '', jobTitle: '', departmentId: '', positionId: '', phone: '', idNumber: '', nationality: '', hireDate: today(), baseSalary: '', housingAllowance: '', transportAllowance: '', gosiSubject: false })}><Plus size={13} />موظف جديد</button>
            </div>
          </div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>الموظف</th><th>الفرع</th><th>القسم</th><th>الوظيفة</th><th style={{ textAlign: 'end' }}>المستندات</th><th /></tr></thead>
              <tbody>
                {emps.filter(e => showInactive || e.isActive !== false).map(e => {
                  const dept = depts.find(d => d.id === e.departmentId);
                  const pos = positions.find(p => p.id === e.positionId);
                  const docs = empDocs(e);
                  const expSoon = docs.some(x => x.expiryDate && Math.round((Date.parse(x.expiryDate + 'T00:00:00') - Date.parse(today() + 'T00:00:00')) / 86400000) <= 30);
                  return (
                    <tr key={e.id}>
                      <td style={{ fontWeight: 600, fontSize: 12.5 }}>{e.name}<span style={{ fontSize: 9.5, color: 'var(--faint)', marginInlineStart: 6 }}>{e.jobTitle}</span>{e.isActive === false && <span className="badge b-dim" style={{ marginInlineStart: 6, fontSize: 9 }}>موقوف</span>}</td>
                      <td style={{ fontSize: 11.5, color: 'var(--dim)' }}>{(org.branches.find(b => b.id === e.branchId) || {}).name || '—'}</td>
                      <td style={{ fontSize: 12 }}>{dept?.name || '—'}</td>
                      <td style={{ fontSize: 12 }}>{pos?.title || '—'}</td>
                      <td className="num" style={{ textAlign: 'end' }}>{docs.length}{expSoon && <span className="badge b-amber" style={{ marginInlineStart: 5, fontSize: 9 }}>انتباه</span>}</td>
                      <td>
                        <div className="row" style={{ gap: 5, justifyContent: 'flex-end' }}>
                          <button className="btn sm gh" onClick={() => setAssignF({ id: e.id, name: e.name, departmentId: e.departmentId || '', positionId: e.positionId || '', syncTitle: true })}>القسم/الوظيفة</button>
                          <button className="btn sm gh" onClick={() => setDocsFor(e)}><FileText size={13} />المستندات</button>
                          <button className="btn sm gh" onClick={() => setEmpF(empToForm(e))}>تعديل</button>
                          <button className="btn sm gh" onClick={() => toggleEmp(e)}>{e.isActive === false ? 'تفعيل' : 'إيقاف'}</button>
                          {e.isActive === false && <button className="btn sm gh" title="حذف نهائي (فقط لموظف بلا أي سجلات)" onClick={() => deleteEmp(e)}><Trash2 size={13} /></button>}
                        </div>
                      </td>
                    </tr>
                  );
                })}
                {emps.length === 0 && <tr><td colSpan={6}><div className="empty">لا يوجد موظفون بعد.</div></td></tr>}
              </tbody>
            </table>
          </div>
          <div className="note" style={{ marginTop: 8 }}>ربط الموظف بقسم/وظيفة اختياري ولا يغيّر أي شاشة أخرى في المنصّة — يُستخدم لاحقًا في مراحل الموارد البشرية القادمة (السياسات والتقييم والمكافآت).</div>
        </div>
      )}

      {deptF && (
        <Modal title={deptF.id ? 'تعديل قسم' : 'قسم جديد'} icon={Building2} onClose={() => setDeptF(null)}
          foot={<><button className="btn gh" onClick={() => setDeptF(null)}>إلغاء</button><button className="btn pri" onClick={saveDept}><Check size={14} />حفظ</button></>}>
          <Field label="اسم القسم"><input className="inp" value={deptF.name} onChange={e => setDeptF(f => ({ ...f, name: e.target.value }))} autoFocus /></Field>
          <Field label="ملاحظة (اختياري)"><input className="inp" value={deptF.note} onChange={e => setDeptF(f => ({ ...f, note: e.target.value }))} /></Field>
        </Modal>
      )}

      {posF && (
        <Modal title={posF.id ? 'تعديل وصف وظيفي' : 'وظيفة جديدة'} icon={UserCog} onClose={() => setPosF(null)} wide
          foot={<><button className="btn gh" onClick={() => setPosF(null)}>إلغاء</button><button className="btn pri" onClick={savePos}><Check size={14} />حفظ</button></>}>
          <div className="grid g3">
            <Field label="المسمى الوظيفي"><input className="inp" value={posF.title} onChange={e => setPosF(f => ({ ...f, title: e.target.value }))} autoFocus /></Field>
            <Field label="القسم">
              <select className="inp sel" value={posF.departmentId} onChange={e => setPosF(f => ({ ...f, departmentId: e.target.value }))}>
                <option value="">— بلا قسم —</option>
                {depts.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
              </select>
            </Field>
            <Field label="الكود الوظيفي"><input className="inp" value={posF.code || ''} onChange={e => setPosF(f => ({ ...f, code: e.target.value }))} placeholder="مثال: KIT-03" /></Field>
            <Field label="الدرجة"><input className="inp" value={posF.grade || ''} onChange={e => setPosF(f => ({ ...f, grade: e.target.value }))} /></Field>
            <Field label="المستوى"><input className="inp" value={posF.level || ''} onChange={e => setPosF(f => ({ ...f, level: e.target.value }))} placeholder="مثال: مبتدئ/متوسط/قيادي" /></Field>
            <Field label="يرفع تقاريره إلى">
              <select className="inp sel" value={posF.reportsToId || ''} onChange={e => setPosF(f => ({ ...f, reportsToId: e.target.value }))}>
                <option value="">—</option>
                {positions.filter(p => p.id !== posF.id).map(p => <option key={p.id} value={p.id}>{p.title}</option>)}
              </select>
            </Field>
            <Field label="الوظيفة البديلة">
              <select className="inp sel" value={posF.backupPositionId || ''} onChange={e => setPosF(f => ({ ...f, backupPositionId: e.target.value }))}>
                <option value="">—</option>
                {positions.filter(p => p.id !== posF.id).map(p => <option key={p.id} value={p.id}>{p.title}</option>)}
              </select>
            </Field>
          </div>
          <Field label="ملخص الوظيفة"><textarea className="inp" rows={2} value={posF.summary || ''} onChange={e => setPosF(f => ({ ...f, summary: e.target.value }))} placeholder="الغرض العام من الوظيفة في سطر أو سطرين" /></Field>
          <div className="grid g2">
            <Field label="المهام والمسؤوليات (سطر لكل مهمة)"><textarea className="inp" rows={4} value={posF.duties} onChange={e => setPosF(f => ({ ...f, duties: e.target.value }))} placeholder={'استقبال الطلبات\nتحضير الأصناف وفق المعايير'} /></Field>
            <Field label="المؤهلات والخبرات (سطر لكل بند)"><textarea className="inp" rows={4} value={posF.qualifications || ''} onChange={e => setPosF(f => ({ ...f, qualifications: e.target.value }))} placeholder={'الثانوية كحد أدنى\nخبرة سنة في مطاعم'} /></Field>
            <Field label="الجدارات والمهارات (سطر لكل بند)"><textarea className="inp" rows={4} value={posF.competencies || ''} onChange={e => setPosF(f => ({ ...f, competencies: e.target.value }))} placeholder={'العمل الجماعي\nسرعة تحت الضغط'} /></Field>
            <Field label="الصلاحيات (سطر لكل بند)"><textarea className="inp" rows={4} value={posF.authorities || ''} onChange={e => setPosF(f => ({ ...f, authorities: e.target.value }))} placeholder={'صرف مصروف نثري حتى حد\nاعتماد خصم للعميل حتى نسبة'} /></Field>
          </div>
          <Field label="القيود والمحظورات (سطر لكل بند)"><textarea className="inp" rows={3} value={posF.restrictions || ''} onChange={e => setPosF(f => ({ ...f, restrictions: e.target.value }))} placeholder={'لا يفتح الخزنة دون المدير\nلا يمنح خصمًا فوق الحد'} /></Field>
          <Field label="التدريب والشهادات المطلوبة (ربط م١٩)">
            <div className="row" style={{ gap: 10, flexWrap: 'wrap' }}>
              {((org.trainingPrograms && org.trainingPrograms.length) ? org.trainingPrograms : defaultTrainingPrograms()).map(pr => (
                <label key={pr.id} className="row" style={{ gap: 5, fontSize: 12.5, cursor: 'pointer' }}>
                  <input type="checkbox" checked={(posF.requiredTrainingIds || []).includes(pr.id)} onChange={() => setPosF(f => ({ ...f, requiredTrainingIds: (f.requiredTrainingIds || []).includes(pr.id) ? f.requiredTrainingIds.filter(x => x !== pr.id) : [...(f.requiredTrainingIds || []), pr.id] }))} />{pr.title}{pr.mandatory ? ' (إلزامي)' : ''}
                </label>
              ))}
            </div>
          </Field>
        </Modal>
      )}

      {jdView && (
        <Modal title={'الوصف الوظيفي — ' + jdView.title} icon={UserCog} onClose={() => setJdView(null)} wide
          foot={<><button className="btn gh" onClick={() => setJdView(null)}>إغلاق</button><button className="btn pri" onClick={() => { printA4(org, 'الوصف الوظيفي — ' + jdView.title, (depts.find(d => d.id === jdView.departmentId) || {}).name || '', positionJdHtml(jdView, org)) || say('اسمح بالنوافذ المنبثقة للطباعة', 'no'); }}><Printer size={14} />طباعة</button></>}>
          <div className="jdbox" style={{ fontSize: 13, lineHeight: 1.9 }} dangerouslySetInnerHTML={{ __html: positionJdHtml(jdView, org) }} />
        </Modal>
      )}

      {empF && (
        <Modal title={empF.id ? 'تعديل بيانات موظف' : 'موظف جديد'} icon={Users} onClose={() => setEmpF(null)}
          foot={<><button className="btn pri" onClick={saveEmp}><Check size={14} />حفظ الموظف</button>
            <button className="btn gh" onClick={() => setEmpF(null)}>إلغاء</button></>}>
          <div className="grid" style={{ gap: 10 }}>
            <div className="grid g2">
              <Field label="الاسم الكامل"><input className="inp" autoFocus value={empF.name} onChange={e => setEmpF(f => ({ ...f, name: e.target.value }))} placeholder="كما في الهوية" /></Field>
              <Field label="الفرع (إلزامي)">
                <select className="inp sel" value={empF.branchId} onChange={e => setEmpF(f => ({ ...f, branchId: e.target.value }))}>
                  <option value="">اختر الفرع</option>
                  {(org.branches || []).filter(b => b.isActive !== false).map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
                </select>
              </Field>
            </div>
            <div className="grid g3">
              <Field label="القسم"><select className="inp sel" value={empF.departmentId} onChange={e => setEmpF(f => ({ ...f, departmentId: e.target.value, positionId: '' }))}><option value="">—</option>{depts.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}</select></Field>
              <Field label="الوظيفة"><select className="inp sel" value={empF.positionId} onChange={e => setEmpF(f => ({ ...f, positionId: e.target.value }))}><option value="">—</option>{positions.filter(p => !empF.departmentId || p.departmentId === empF.departmentId).map(p => <option key={p.id} value={p.id}>{p.title}</option>)}</select></Field>
              <Field label="المسمّى (إن لم تُختر وظيفة)"><input className="inp" value={empF.jobTitle} onChange={e => setEmpF(f => ({ ...f, jobTitle: e.target.value }))} placeholder="كاشير، شيف…" /></Field>
            </div>
            <div className="grid g3">
              <Field label="الجوال"><input className="inp" style={{ direction: 'ltr', textAlign: 'right' }} value={empF.phone} onChange={e => setEmpF(f => ({ ...f, phone: e.target.value }))} /></Field>
              <Field label="رقم الهوية/الإقامة"><input className="inp n" value={empF.idNumber} onChange={e => setEmpF(f => ({ ...f, idNumber: e.target.value.replace(/\D/g, '') }))} /></Field>
              <Field label="تاريخ التعيين"><input type="date" className="inp" value={empF.hireDate} onChange={e => setEmpF(f => ({ ...f, hireDate: e.target.value }))} /></Field>
            </div>
            <div className="grid g3">
              <Field label="الجنسية (لنِسبة التأمينات)"><select className="inp sel" value={empF.nationality} onChange={e => setEmpF(f => ({ ...f, nationality: e.target.value }))}><option value="">غير محدّد</option><option value="saudi">سعودي</option><option value="nonSaudi">غير سعودي</option></select></Field>
              <Field label="الراتب الأساسي"><input className="inp n" inputMode="decimal" value={empF.baseSalary} onChange={e => setEmpF(f => ({ ...f, baseSalary: e.target.value.replace(/[^\d.]/g, '') }))} /></Field>
              <Field label="بدل السكن"><input className="inp n" inputMode="decimal" value={empF.housingAllowance} onChange={e => setEmpF(f => ({ ...f, housingAllowance: e.target.value.replace(/[^\d.]/g, '') }))} /></Field>
            </div>
            <div className="grid g2">
              <Field label="بدل النقل"><input className="inp n" inputMode="decimal" value={empF.transportAllowance} onChange={e => setEmpF(f => ({ ...f, transportAllowance: e.target.value.replace(/[^\d.]/g, '') }))} /></Field>
              <label className="row" style={{ gap: 8, alignSelf: 'end', cursor: 'pointer', paddingBottom: 8 }}><input type="checkbox" checked={!!empF.gosiSubject} onChange={e => setEmpF(f => ({ ...f, gosiSubject: e.target.checked }))} />مشمول بالتأمينات الاجتماعية</label>
            </div>
            <div className="note">{empF.id ? 'تغيير الفرع يُبقي كل السجلات السابقة؛ PIN وبطاقة QR مرتبطان بالفرع القديم فأعد ضبطهما في الفرع الجديد.' : 'بعد الحفظ: اضبط رقم PIN أو أصدر بطاقة QR للموظف من «الحضور الموثَّق ← أرقام PIN» (مدير فرعه يستطيع ذلك أيضًا). الراتب والبدلات قابلة للتعديل لاحقًا من «الرواتب والسلف».'}</div>
          </div>
        </Modal>
      )}
      {assignF && (
        <Modal title={'القسم والوظيفة — ' + assignF.name} icon={UserCog} onClose={() => setAssignF(null)}
          foot={<><button className="btn gh" onClick={() => setAssignF(null)}>إلغاء</button><button className="btn pri" onClick={saveAssign}><Check size={14} />حفظ</button></>}>
          <Field label="القسم">
            <select className="inp sel" value={assignF.departmentId} onChange={e => setAssignF(f => ({ ...f, departmentId: e.target.value, positionId: '' }))}>
              <option value="">— بلا قسم —</option>
              {depts.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
            </select>
          </Field>
          <Field label="الوظيفة">
            <select className="inp sel" value={assignF.positionId} onChange={e => setAssignF(f => ({ ...f, positionId: e.target.value }))}>
              <option value="">— بلا وظيفة —</option>
              {positions.filter(p => !assignF.departmentId || p.departmentId === assignF.departmentId).map(p => <option key={p.id} value={p.id}>{p.title}</option>)}
            </select>
          </Field>
          <label className="row" style={{ gap: 6, fontSize: 12.5, cursor: 'pointer', marginTop: 8 }}>
            <input type="checkbox" checked={assignF.syncTitle} onChange={e => setAssignF(f => ({ ...f, syncTitle: e.target.checked }))} />
            حدّث «المسمى الوظيفي» المعروض في المنصّة تلقائيًا من الوظيفة المختارة
          </label>
        </Modal>
      )}

      {docsFor && (
        <Modal title={'مستندات وعقود — ' + docsFor.name} icon={FileText} wide onClose={() => setDocsFor(null)}
          foot={<button className="btn gh" onClick={() => setDocsFor(null)}>إغلاق</button>}>
          <div className="row" style={{ justifyContent: 'flex-end', marginBottom: 8 }}>
            <button className="btn sm" onClick={() => setDocF({ kind: 'contract', title: '', number: '', issueDate: '', expiryDate: '', file: '' })}><Plus size={13} />مستند جديد</button>
          </div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>النوع</th><th>العنوان</th><th>الرقم</th><th>الإصدار</th><th>الانتهاء</th><th /></tr></thead>
              <tbody>
                {empDocs(docsFor).map(x => (
                  <tr key={x.id}>
                    <td style={{ fontSize: 11.5 }}>{DOC_KINDS[x.kind] || 'أخرى'}</td>
                    <td style={{ fontWeight: 600, fontSize: 12 }}>{x.title}{x.file && <FileText size={11} style={{ marginInlineStart: 5, color: 'var(--brass)' }} />}</td>
                    <td style={{ fontSize: 11.5, color: 'var(--dim)' }}>{x.number || '—'}</td>
                    <td className="num" style={{ fontSize: 11 }}>{x.issueDate || '—'}</td>
                    <td className="num" style={{ fontSize: 11 }}>{x.expiryDate || '—'} {expiryTag(x.expiryDate)}</td>
                    <td>
                      <div className="row" style={{ gap: 5, justifyContent: 'flex-end' }}>
                        <button className="btn sm gh" onClick={() => setDocF({ id: x.id, kind: x.kind, title: x.title, number: x.number, issueDate: x.issueDate, expiryDate: x.expiryDate, file: x.file })}>تعديل</button>
                        <button className="btn sm gh" style={{ color: 'var(--rose)' }} onClick={() => delDoc(x.id)}><Trash2 size={13} /></button>
                      </div>
                    </td>
                  </tr>
                ))}
                {empDocs(docsFor).length === 0 && <tr><td colSpan={6}><div className="empty">لا مستندات مرفوعة لهذا الموظف بعد.</div></td></tr>}
              </tbody>
            </table>
          </div>
        </Modal>
      )}

      {docF && docsFor && (
        <Modal title={docF.id ? 'تعديل مستند' : 'مستند جديد'} icon={FileText} onClose={() => setDocF(null)}
          foot={<><button className="btn gh" onClick={() => setDocF(null)}>إلغاء</button><button className="btn pri" onClick={saveDoc}><Check size={14} />حفظ</button></>}>
          <div className="grid g2">
            <Field label="النوع">
              <select className="inp sel" value={docF.kind} onChange={e => setDocF(f => ({ ...f, kind: e.target.value }))}>
                {Object.entries(DOC_KINDS).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
              </select>
            </Field>
            <Field label="العنوان"><input className="inp" value={docF.title} onChange={e => setDocF(f => ({ ...f, title: e.target.value }))} /></Field>
            <Field label="الرقم (اختياري)"><input className="inp" value={docF.number} onChange={e => setDocF(f => ({ ...f, number: e.target.value }))} /></Field>
            <Field label="تاريخ الإصدار (اختياري)"><input className="inp" type="date" value={docF.issueDate} onChange={e => setDocF(f => ({ ...f, issueDate: e.target.value }))} /></Field>
            <Field label="تاريخ الانتهاء (اختياري)"><input className="inp" type="date" value={docF.expiryDate} onChange={e => setDocF(f => ({ ...f, expiryDate: e.target.value }))} /></Field>
          </div>
          <PhotoField label="المرفق (صورة أو PDF، اختياري)" value={docF.file} onChange={v => setDocF(f => ({ ...f, file: v }))} say={say} />
        </Modal>
      )}
    </div>
  );
}

/* ================= م٢ — سياسات الموارد البشرية وأدوار الإشراف التنظيمي ================= */
const HR_WEEK_DAYS = [
  { v: 0, ar: 'الأحد' }, { v: 1, ar: 'الاثنين' }, { v: 2, ar: 'الثلاثاء' }, { v: 3, ar: 'الأربعاء' },
  { v: 4, ar: 'الخميس' }, { v: 5, ar: 'الجمعة' }, { v: 6, ar: 'السبت' },
];
const defaultHrPolicies = () => ({
  workHoursPerDay: 8, weeklyOffDays: [5], lateToleranceMinutes: 15,
  overtimeEnabled: false, overtimeMaxHoursPerMonth: 30,
  scoreWeightsEnabled: false, scoreWeights: { attendance: 25, quality: 25, tasks: 25, discipline: 25 },
  disciplineBase: 50, disciplinePointValue: 5, // م٧: محور الانضباط = القاعدة + (صافي نقاط الشهر × قيمة النقطة)، محصور 0–100
  signReminderDays: 3, // م١٠ (v27.0): بعد كم يومًا من إصدار إقرار/إشعار غير موقَّع يظهر تنبيه في مركز التنبيهات
  // م٢٠ (v27.6) — الإجراءات التأديبية (نظام العمل — افتراضات قابلة للضبط؛ لائحة المنشأة المسجّلة هي المرجع الملزم)
  penaltyEraseDays: 180, fineCapDaysPerMonth: 5, chargeWindowDays: 30, objectionDays: 15, pipTriggerScore: 60,
  penaltySchedule: defaultPenaltySchedule(),
  trainingExpiryAlertDays: 30, // م١٩ (v27.7): تنبيه قبل انتهاء الشهادة بعدد الأيام
  roleKpiEnabled: false, roleKpiWeight: 20, // م١١ (v27.9): محور مؤشرات الدور — مُعطَّل افتراضيًا
});
// م٦ — قواعد النقاط التلقائية (مُعطَّلة افتراضيًا حتى يراجعها المالك ويفعّلها — قرار H/3 في hr-audit-m0)
const defaultPointsRules = () => ({ enabled: false, onTime: 1, late: -1, absent: -3, taskDone: 1 });
// م٨ — شرائح مكافآت تلقائية حسب درجة الأداء (م٧): مُعطَّلة افتراضيًا (قرار H/3)؛ تُولِّد طلبات مقترحة تمرّ بالاعتماد نفسه
const defaultRewardTiers = () => ({ enabled: false, tiers: [{ minScore: 90, amount: 500 }, { minScore: 80, amount: 250 }] });
// كود نافذة زمنية للمعاينة فقط — دالة تجزئة خفيفة متزامنة (ليست تشفيرًا فعليًا).
// التحقّق الأمني الحقيقي عند تسجيل الحضور بمسح الرمز يُبنى في م٣ فوق نفس السرّ المخزَّن هنا.
function hrHashStr(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = (h * 16777619) >>> 0; }
  return h.toString(36);
}
function hrQrWindowCode(secret, rotateMinutes, branchId) {
  const win = Math.floor(Date.now() / ((rotateMinutes || 3) * 60000));
  return hrHashStr(branchId + ':' + secret + ':' + win);
}

function HrPolicy({ org, me, commitOrg, say }) {
  const [view, setView] = useState('general');
  const policies = { ...defaultHrPolicies(), ...(org.hrPolicies || {}) };
  const [pf, setPf] = useState(policies);
  const branches = org.branches || [];
  const depts = org.departments || [];
  const emps = org.employees || [];
  const [geoF, setGeoF] = useState({}); // {branchId: {lat, lng, radiusMeters}} — تعديلات محلية غير محفوظة بعد
  const [qrModalFor, setQrModalFor] = useState(null); // branch object
  const [, tick] = useState(0);

  useEffect(() => {
    if (!qrModalFor) return;
    const t = setInterval(() => tick(x => x + 1), 1000);
    return () => clearInterval(t);
  }, [qrModalFor]);

  const geoOf = (b) => geoF[b.id] || b.geofence || { lat: '', lng: '', radiusMeters: 100 };
  const setGeoField = (b, k, v) => setGeoF(g => ({ ...g, [b.id]: { ...geoOf(b), [k]: v } }));
  const useMyLocation = (b) => {
    if (!navigator.geolocation) return say('المتصفح لا يدعم تحديد الموقع', 'no');
    navigator.geolocation.getCurrentPosition(
      (pos) => setGeoF(g => ({ ...g, [b.id]: { ...geoOf(b), lat: +pos.coords.latitude.toFixed(6), lng: +pos.coords.longitude.toFixed(6) } })),
      () => say('تعذّر الحصول على الموقع — تحقّق من إذن الموقع بالمتصفح', 'no')
    );
  };
  const saveGeo = async (b) => {
    const g = geoOf(b);
    if (g.lat === '' || g.lng === '' || !g.radiusMeters) return say('أدخل خط العرض وخط الطول ونصف قطر السماح', 'no');
    await commitOrg(d => ({
      ...d, branches: (d.branches || []).map(x => x.id === b.id ? { ...x, geofence: { lat: +g.lat, lng: +g.lng, radiusMeters: +g.radiusMeters, updatedAt: nowISO() } } : x)
    }), { actionType: 'update', targetType: 'branch', targetId: b.id, branchName: b.name, title: 'ضبط جيوفنس الحضور للفرع', details: b.name + ' — نصف قطر ' + g.radiusMeters + 'م' });
    say('حُفظ جيوفنس الفرع ✓');
  };

  const savePolicies = async () => {
    const w = pf.scoreWeights || {};
    const sum = (Number(w.attendance) || 0) + (Number(w.quality) || 0) + (Number(w.tasks) || 0) + (Number(w.discipline) || 0);
    if (pf.scoreWeightsEnabled && sum !== 100) return say('مجموع أوزان الدرجة النهائية يجب أن يساوي 100 (المجموع الحالي ' + sum + ')', 'no');
    await commitOrg(d => ({ ...d, hrPolicies: { ...pf } }),
      { actionType: 'update', targetType: 'settings', targetId: 'hrPolicies', title: 'حفظ سياسات الدوام العامة', details: pf.workHoursPerDay + ' ساعات/يوم · سماحية تأخير ' + pf.lateToleranceMinutes + 'د' });
    say('حُفظت السياسات ✓');
  };

  const rotateToken = async (b) => {
    if (!window.confirm('توليد رمز حضور جديد لفرع «' + b.name + '»؟ الرمز القديم يتوقف فورًا عن العمل.')) return;
    const secret = uid('qr') + Math.random().toString(36).slice(2, 10);
    await commitOrg(d => ({
      ...d, branches: (d.branches || []).map(x => x.id === b.id ? { ...x, qrToken: { secret, rotateMinutes: (x.qrToken && x.qrToken.rotateMinutes) || 3, rotatedAt: nowISO() } } : x)
    }), { actionType: 'update', targetType: 'branch', targetId: b.id, branchName: b.name, title: 'توليد رمز حضور جديد للفرع', details: b.name });
    say('تولّد رمز جديد للفرع ✓');
  };
  const setRotateMinutes = async (b, mins) => {
    await commitOrg(d => ({
      ...d, branches: (d.branches || []).map(x => x.id === b.id ? { ...x, qrToken: { ...(x.qrToken || {}), rotateMinutes: mins } } : x)
    }), { actionType: 'update', targetType: 'branch', targetId: b.id, branchName: b.name, title: 'ضبط مدة تدوير رمز الحضور', details: b.name + ' — كل ' + mins + ' د' });
  };

  const setDeptHead = async (dId, headEmployeeId) => {
    await commitOrg(d => ({ ...d, departments: (d.departments || []).map(x => x.id === dId ? { ...x, headEmployeeId: headEmployeeId || '' } : x) }),
      { actionType: 'update', targetType: 'user_account', targetId: dId, title: 'تعيين رئيس قسم', details: (depts.find(x => x.id === dId) || {}).name || '' });
    say('حُفظ ✓');
  };
  const setEmpManager = async (eId, managerId) => {
    if (managerId === eId) return say('لا يمكن أن يكون الموظف مديرًا لنفسه', 'no');
    await commitOrg(d => ({ ...d, employees: (d.employees || []).map(x => x.id === eId ? { ...x, managerId: managerId || '' } : x) }),
      { actionType: 'update', targetType: 'user_account', targetId: eId, title: 'تعيين المدير المباشر لموظف', details: (emps.find(x => x.id === eId) || {}).name || '' });
    say('حُفظ ✓');
  };

  return (
    <div className="grid" style={{ gap: 12 }}>
      <div className="card" style={{ padding: '8px 12px' }}>
        <div className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
          <button className={'btn sm' + (view === 'general' ? ' pri' : ' gh')} onClick={() => setView('general')}><ShieldCheck size={13} />سياسات الدوام</button>
          <button className={'btn sm' + (view === 'geo' ? ' pri' : ' gh')} onClick={() => setView('geo')}><Compass size={13} />جيوفنس الفروع</button>
          <button className={'btn sm' + (view === 'qr' ? ' pri' : ' gh')} onClick={() => setView('qr')}><QrCode size={13} />رمز حضور الفرع</button>
          <button className={'btn sm' + (view === 'mgr' ? ' pri' : ' gh')} onClick={() => setView('mgr')}><UserCog size={13} />المدير المباشر</button>
        </div>
      </div>

      {view === 'general' && (
        <div className="card">
          <div className="card-t" style={{ marginBottom: 10 }}><ShieldCheck size={15} color="var(--brass)" />سياسات الدوام العامة</div>
          <div className="grid g2">
            <Num label="ساعات الدوام القياسية يوميًا" value={pf.workHoursPerDay} onChange={v => setPf(f => ({ ...f, workHoursPerDay: v }))} />
            <Num label="سماحية التأخير (دقائق) قبل احتساب تأخير" value={pf.lateToleranceMinutes} onChange={v => setPf(f => ({ ...f, lateToleranceMinutes: v }))} />
            <Num label="تنبيه بالإقرارات غير الموقَّعة بعد (أيام) من إصدارها" value={pf.signReminderDays} onChange={v => setPf(f => ({ ...f, signReminderDays: v }))} hint="م١٠ — إقرارات استلام الراتب وإشعارات المكافآت/الجزاءات التي لم يوقّعها الموظف من كشك الفرع" />
          </div>
          <Field label="أيام الإجازة الأسبوعية الافتراضية">
            <div className="row" style={{ gap: 10, flexWrap: 'wrap' }}>
              {HR_WEEK_DAYS.map(d => (
                <label key={d.v} className="row" style={{ gap: 5, fontSize: 12.5, cursor: 'pointer' }}>
                  <input type="checkbox" checked={(pf.weeklyOffDays || []).includes(d.v)}
                    onChange={e => setPf(f => ({ ...f, weeklyOffDays: e.target.checked ? [...(f.weeklyOffDays || []), d.v] : (f.weeklyOffDays || []).filter(x => x !== d.v) }))} />
                  {d.ar}
                </label>
              ))}
            </div>
          </Field>
          <div className="card" style={{ marginTop: 10, background: 'rgba(200,162,74,.05)' }}>
            <label className="row" style={{ gap: 6, fontSize: 12.5, cursor: 'pointer' }}>
              <input type="checkbox" checked={pf.overtimeEnabled} onChange={e => setPf(f => ({ ...f, overtimeEnabled: e.target.checked }))} />
              تفعيل احتساب العمل الإضافي
            </label>
            {pf.overtimeEnabled && <div style={{ marginTop: 8 }}>
              <Num label="الحد الأقصى لساعات الإضافي شهريًا" value={pf.overtimeMaxHoursPerMonth} onChange={v => setPf(f => ({ ...f, overtimeMaxHoursPerMonth: v }))} />
            </div>}
          </div>
          <div className="card" style={{ marginTop: 10, background: 'rgba(200,162,74,.05)' }}>
            <label className="row" style={{ gap: 6, fontSize: 12.5, cursor: 'pointer' }}>
              <input type="checkbox" checked={pf.scoreWeightsEnabled} onChange={e => setPf(f => ({ ...f, scoreWeightsEnabled: e.target.checked }))} />
              تفعيل أوزان الدرجة النهائية المقترحة (لمراحل التقييم والمكافآت القادمة — لا تُستخدم في أي احتساب حاليًا)
            </label>
            <div className="note" style={{ margin: '6px 0 10px' }}>هذه الأوزان تمهيدية فقط لمراحل م٦-م٨ (دفتر النقاط، التقييم، المكافآت)، وتبقى معطّلة افتراضيًا حتى تراجعها وتفعّلها بنفسك. يجب أن يساوي مجموعها 100.</div>
            <div className="grid g2">
              <Num label="الحضور والانضباط" value={pf.scoreWeights?.attendance} onChange={v => setPf(f => ({ ...f, scoreWeights: { ...f.scoreWeights, attendance: v } }))} />
              <Num label="جودة الأداء" value={pf.scoreWeights?.quality} onChange={v => setPf(f => ({ ...f, scoreWeights: { ...f.scoreWeights, quality: v } }))} />
              <Num label="إنجاز المهام" value={pf.scoreWeights?.tasks} onChange={v => setPf(f => ({ ...f, scoreWeights: { ...f.scoreWeights, tasks: v } }))} />
              <Num label="الالتزام والسلوك" value={pf.scoreWeights?.discipline} onChange={v => setPf(f => ({ ...f, scoreWeights: { ...f.scoreWeights, discipline: v } }))} />
            </div>
          </div>
          <div className="row" style={{ justifyContent: 'flex-end', marginTop: 12 }}>
            <button className="btn pri" onClick={savePolicies}><Check size={14} />حفظ السياسات</button>
          </div>
        </div>
      )}

      {view === 'geo' && (
        <div className="card">
          <div className="card-t" style={{ marginBottom: 6 }}><Compass size={15} color="var(--brass)" />جيوفنس الحضور لكل فرع</div>
          <div className="note" style={{ marginBottom: 10 }}>يحدّد هذا نطاق الموقع الجغرافي المسموح به لتسجيل الحضور من الفرع في مرحلة م٣ القادمة. اضبط إحداثيات مركز كل فرع ونصف قطر السماح بالأمتار.</div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>الفرع</th><th>خط العرض</th><th>خط الطول</th><th>نصف القطر (م)</th><th /></tr></thead>
              <tbody>
                {branches.map(b => {
                  const g = geoOf(b);
                  return (
                    <tr key={b.id}>
                      <td style={{ fontWeight: 600, fontSize: 12.5 }}>{b.name}{b.geofence && <div style={{ fontSize: 9.5, color: 'var(--faint)', fontWeight: 400 }}>محفوظ مسبقًا</div>}</td>
                      <td><input className="inp n" style={{ width: 110 }} value={g.lat} onChange={e => setGeoField(b, 'lat', e.target.value)} placeholder="21.543" /></td>
                      <td><input className="inp n" style={{ width: 110 }} value={g.lng} onChange={e => setGeoField(b, 'lng', e.target.value)} placeholder="39.172" /></td>
                      <td><input className="inp n" style={{ width: 90 }} value={g.radiusMeters} onChange={e => setGeoField(b, 'radiusMeters', e.target.value)} /></td>
                      <td>
                        <div className="row" style={{ gap: 5, justifyContent: 'flex-end' }}>
                          <button className="btn sm gh" onClick={() => useMyLocation(b)}><Compass size={13} />موقعي الحالي</button>
                          <button className="btn sm pri" onClick={() => saveGeo(b)}><Check size={13} />حفظ</button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
                {branches.length === 0 && <tr><td colSpan={5}><div className="empty">لا توجد فروع بعد.</div></td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {view === 'qr' && (
        <div className="card">
          <div className="card-t" style={{ marginBottom: 6 }}><QrCode size={15} color="var(--brass)" />رمز حضور الفرع (QR مدوَّر)</div>
          <div className="note" style={{ marginBottom: 10 }}>كل فرع يحصل على سرّ خاص به يُولَّد منه رمز QR يتغيّر تلقائيًا كل عدة دقائق. هذه الشاشة تُجهِّز السرّ وتعرضه للمعاينة فقط — التحقّق الفعلي عند مسح الرمز لتسجيل حضور موظف يُبنى في مرحلة م٣ القادمة.</div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>الفرع</th><th>الحالة</th><th>يتجدّد كل</th><th /></tr></thead>
              <tbody>
                {branches.map(b => (
                  <tr key={b.id}>
                    <td style={{ fontWeight: 600, fontSize: 12.5 }}>{b.name}</td>
                    <td>{b.qrToken?.secret ? <span className="badge b-mint">مُفعَّل</span> : <span className="badge b-dim">لم يُولَّد بعد</span>}</td>
                    <td>
                      <select className="inp sel" style={{ width: 100 }} value={(b.qrToken && b.qrToken.rotateMinutes) || 3} onChange={e => setRotateMinutes(b, +e.target.value)}>
                        {[1, 2, 3, 5, 10].map(m => <option key={m} value={m}>{m} دقائق</option>)}
                      </select>
                    </td>
                    <td>
                      <div className="row" style={{ gap: 5, justifyContent: 'flex-end' }}>
                        {b.qrToken?.secret && <button className="btn sm gh" onClick={() => setQrModalFor(b)}><QrCode size={13} />عرض الرمز</button>}
                        <button className="btn sm gh" onClick={() => rotateToken(b)}><RefreshCw size={13} />{b.qrToken?.secret ? 'تجديد الرمز' : 'توليد رمز'}</button>
                      </div>
                    </td>
                  </tr>
                ))}
                {branches.length === 0 && <tr><td colSpan={4}><div className="empty">لا توجد فروع بعد.</div></td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {view === 'mgr' && (
        <div className="grid" style={{ gap: 12 }}>
          <div className="card">
            <div className="card-t" style={{ marginBottom: 10 }}><Building2 size={15} color="var(--brass)" />رئيس كل قسم</div>
            <div className="tw">
              <table className="tb">
                <thead><tr><th>القسم</th><th>رئيس القسم</th></tr></thead>
                <tbody>
                  {depts.map(d => (
                    <tr key={d.id}>
                      <td style={{ fontWeight: 600, fontSize: 12.5 }}>{d.name}</td>
                      <td>
                        <select className="inp sel" value={d.headEmployeeId || ''} onChange={e => setDeptHead(d.id, e.target.value)}>
                          <option value="">— بلا رئيس قسم —</option>
                          {emps.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}
                        </select>
                      </td>
                    </tr>
                  ))}
                  {depts.length === 0 && <tr><td colSpan={2}><div className="empty">لا توجد أقسام بعد — أضِفها من «البيانات الرئيسية».</div></td></tr>}
                </tbody>
              </table>
            </div>
          </div>
          <div className="card">
            <div className="card-t" style={{ marginBottom: 10 }}><UserCog size={15} color="var(--brass)" />المدير المباشر لكل موظف</div>
            <div className="tw">
              <table className="tb">
                <thead><tr><th>الموظف</th><th>يرفع تقاريره إلى</th></tr></thead>
                <tbody>
                  {emps.map(e => (
                    <tr key={e.id}>
                      <td style={{ fontWeight: 600, fontSize: 12.5 }}>{e.name}</td>
                      <td>
                        <select className="inp sel" value={e.managerId || ''} onChange={ev => setEmpManager(e.id, ev.target.value)}>
                          <option value="">— بلا مدير مباشر —</option>
                          {emps.filter(x => x.id !== e.id).map(x => <option key={x.id} value={x.id}>{x.name}</option>)}
                        </select>
                      </td>
                    </tr>
                  ))}
                  {emps.length === 0 && <tr><td colSpan={2}><div className="empty">لا يوجد موظفون بعد.</div></td></tr>}
                </tbody>
              </table>
            </div>
            <div className="note" style={{ marginTop: 8 }}>تسلسل الاعتماد هذا اختياري ولا يُستخدم في أي منطق حاليًا — يُستثمَر لاحقًا في مراحل التقييم واعتماد المكافآت/الجزاءات (م٧-م٨).</div>
          </div>
        </div>
      )}

      {qrModalFor && (() => {
        const b = branches.find(x => x.id === qrModalFor.id) || qrModalFor;
        const rotateMinutes = (b.qrToken && b.qrToken.rotateMinutes) || 3;
        const code = b.qrToken?.secret ? hrQrWindowCode(b.qrToken.secret, rotateMinutes, b.id) : '';
        const payload = 'HRQR:' + b.id + ':' + code;
        const msLeft = ((rotateMinutes * 60000) - (Date.now() % (rotateMinutes * 60000)));
        const secLeft = Math.max(0, Math.round(msLeft / 1000));
        return (
          <Modal title={'رمز حضور — ' + b.name} icon={QrCode} onClose={() => setQrModalFor(null)}
            foot={<button className="btn gh" onClick={() => setQrModalFor(null)}>إغلاق</button>}>
            <div style={{ textAlign: 'center' }}>
              <div style={{ display: 'inline-block', background: '#fff', padding: 10, borderRadius: 12, border: '1px solid var(--frame-o)' }}
                dangerouslySetInnerHTML={{ __html: qrSvg(payload, { ecl: 1, px: 220 }) }} />
              <div className="note" style={{ marginTop: 10 }}>يتجدّد الرمز تلقائيًا خلال {secLeft} ثانية — معاينة فقط، غير مُستخدَم حاليًا: تسجيل الحضور المعتمد يتم من شاشة «الحضور الموثَّق» على جهاز الفرع برقم PIN (بقرار الإدارة، بلا مسح من جوال الموظف).</div>
            </div>
          </Modal>
        );
      })()}
    </div>
  );
}

/* ============================================================
   م٣ — الحضور الموثَّق (Verified Attendance)
   بلا حساب دخول شخصي للموظف وبلا دخول مجهول (Anonymous Auth) وبلا أي
   تعديل على قواعد Firestore: التسجيل يتم فقط عبر جهاز الفرع المشترك
   (جلسة الكاشير/مدير الفرع المُصادَق عليها أصلاً)، برقم PIN خاص بكل
   موظف (مُجزَّأ SHA-256 عبر sha()) + تحقّق موقعي اختياري (جيوفنس الفرع
   من م٢، عبر haversineMeters) يُسجَّل كعلَم امتثال بلا حجب العملية.
   ============================================================ */
function Attendance({ org, ops, me, myBranches, commit, say }) {
  const isCashier = me.role === 'cashier';
  const events = ops.attendanceEvents || [];
  const pinRecOf = (empId) => ((ops.hrPins || []).find(p => p.employeeId === empId)) || null;
  const pinHashOf = (empId) => (pinRecOf(empId) || {}).pinHash || '';
  const badgeHashOf = (empId) => (pinRecOf(empId) || {}).badgeHash || '';
  const branches = myBranches || [];

  const [view, setView] = useState('kiosk');
  const [branchId, setBranchId] = useState((branches[0] || {}).id || '');
  useEffect(() => {
    if (!branches.find(b => b.id === branchId)) setBranchId((branches[0] || {}).id || '');
  }, [branches, branchId]);
  const branch = branches.find(b => b.id === branchId) || null;

  const emps = (org.employees || []).filter(e => e.isActive !== false && branch && e.branchId === branch.id);

  const lastEventToday = (empId) => {
    const d = today();
    return events
      .filter(ev => ev.employeeId === empId && (ev.at || '').slice(0, 10) === d)
      .sort((a, b) => (a.at < b.at ? 1 : -1))[0] || null;
  };
  const nextType = (empId) => (lastEventToday(empId)?.type === 'in' ? 'out' : 'in');

  // --- كشك تسجيل الحضور ---
  const [pinFor, setPinFor] = useState(null);
  const [pinVal, setPinVal] = useState('');
  const [busy, setBusy] = useState(false);

  // v24.1: تسجيل الحدث نفسه مشترك بين مسار PIN ومسار بطاقة QR
  const recordEvent = async (emp, via) => {
    const type = nextType(emp.id);
    const rec = {
      id: uid('att'), branchId: branch.id, branchName: branch.name, employeeId: emp.id, employeeName: emp.name,
      type, at: nowISO(), via: via || 'pin', recordedBy: me.id, recordedByName: me.name,
      lat: null, lng: null, distanceMeters: null, withinGeofence: null
    };
    const finish = async (pos) => {
      if (pos) {
        rec.lat = +pos.coords.latitude.toFixed(6);
        rec.lng = +pos.coords.longitude.toFixed(6);
        if (branch.geofence && branch.geofence.lat !== '' && branch.geofence.lat != null) {
          rec.distanceMeters = haversineMeters(rec.lat, rec.lng, branch.geofence.lat, branch.geofence.lng);
          rec.withinGeofence = rec.distanceMeters <= (branch.geofence.radiusMeters || 100);
        }
      }
      const ok = await commit(d => ({ ...d, attendanceEvents: [rec, ...(d.attendanceEvents || [])] }), {
        actionType: 'update', targetType: 'attendance', targetId: rec.id, branchName: branch.name,
        title: (type === 'in' ? 'تسجيل حضور موظف' : 'تسجيل انصراف موظف') + (via === 'badge' ? ' (بطاقة QR)' : ''),
        details: emp.name + (rec.withinGeofence === false ? ' — خارج نطاق الفرع (' + rec.distanceMeters + 'م)' : '')
      });
      setBusy(false); setPinFor(null); setPinVal('');
      if (ok) say((type === 'in' ? 'سُجِّل الحضور' : 'سُجِّل الانصراف') + ' — ' + emp.name + ' ✓' +
        (rec.withinGeofence === false ? ' (تنبيه: خارج نطاق الفرع)' : ''));
    };
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(pos => finish(pos), () => finish(null), { timeout: 8000 });
    } else finish(null);
  };
  const doCheck = async () => {
    if (!pinFor || !branch || busy) return;
    if (!/^\d{4,6}$/.test(pinVal)) return say('أدخل رقم PIN المكوّن من ٤ إلى ٦ أرقام', 'no');
    setBusy(true);
    const hash = await sha(pinVal);
    if (!pinHashOf(pinFor.id) || pinHashOf(pinFor.id) !== hash) {
      setBusy(false); setPinVal('');
      return say('رقم PIN غير صحيح', 'no');
    }
    await recordEvent(pinFor, 'pin');
  };

  // --- v24.1: بطاقة QR الشخصية للموظف — يمسحها جهاز الفرع (كاميرا أو ماسح USB) بدل كتابة PIN ---
  const [scanBuf, setScanBuf] = useState('');
  const handleBadge = async (raw) => {
    if (!branch || busy) return;
    const t = String(raw || '').trim();
    setScanBuf('');
    const m = t.match(/^ATT:([^:]+):(.+)$/);
    if (!m) return say('رمز غير معروف — ليست بطاقة حضور صالحة', 'no');
    const emp = emps.find(e => e.id === m[1]);
    if (!emp) return say('البطاقة لموظف ليس ضمن هذا الفرع', 'no');
    setBusy(true);
    const h = await sha(m[2]);
    if (!badgeHashOf(emp.id) || badgeHashOf(emp.id) !== h) { setBusy(false); return say('بطاقة ملغاة أو غير صالحة — أعد إصدارها من مدير الفرع', 'no'); }
    await recordEvent(emp, 'badge');
  };
  const [cam, setCam] = useState(false);
  const videoRef = useRef(null); const streamRef = useRef(null); const rafRef = useRef(0);
  const stopCam = () => {
    if (typeof cancelAnimationFrame === 'function') cancelAnimationFrame(rafRef.current);
    try { ((streamRef.current && streamRef.current.getTracks()) || []).forEach(t => t.stop()); } catch { }
    streamRef.current = null; setCam(false);
  };
  const loadJsQR = () => new Promise((res, rej) => {
    if (window.jsQR) return res(window.jsQR);
    const sc = document.createElement('script'); sc.src = 'https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.js';
    sc.onload = () => res(window.jsQR); sc.onerror = () => rej(new Error('jsqr')); document.head.appendChild(sc);
  });
  const startCam = async () => {
    if (!(navigator.mediaDevices && navigator.mediaDevices.getUserMedia)) return say('المتصفح لا يدعم الكاميرا — استخدم ماسح USB أو رقم PIN', 'no');
    setCam(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      streamRef.current = stream;
      const v = videoRef.current; if (!v) { stopCam(); return; }
      v.srcObject = stream; await v.play();
      let detector = null;
      if ('BarcodeDetector' in window) { try { detector = new window.BarcodeDetector({ formats: ['qr_code'] }); } catch { detector = null; } }
      let jsQR = null;
      if (!detector) { try { jsQR = await loadJsQR(); } catch { stopCam(); return say('تعذّر تحميل قارئ QR — تحقّق من الاتصال أو استخدم ماسح USB / رقم PIN', 'no'); } }
      const canvas = document.createElement('canvas'); const ctx = canvas.getContext('2d', { willReadFrequently: true });
      let lastTry = 0;
      const tick = async () => {
        if (!streamRef.current) return;
        const now = Date.now();
        if (now - lastTry > 250 && v.readyState >= 2) {
          lastTry = now; let text = '';
          try {
            if (detector) { const codes = await detector.detect(v); text = ((codes || [])[0] || {}).rawValue || ''; }
            else { canvas.width = v.videoWidth; canvas.height = v.videoHeight; ctx.drawImage(v, 0, 0); const img = ctx.getImageData(0, 0, canvas.width, canvas.height); const r = jsQR(img.data, img.width, img.height); text = r ? r.data : ''; }
          } catch { }
          if (text) { stopCam(); handleBadge(text); return; }
        }
        rafRef.current = requestAnimationFrame(tick);
      };
      rafRef.current = requestAnimationFrame(tick);
    } catch (e) { stopCam(); say('تعذّر فتح الكاميرا — اسمح بالوصول للكاميرا أو استخدم ماسح USB / رقم PIN', 'no'); }
  };
  useEffect(() => () => stopCam(), []); // eslint-disable-line

  // --- ضبط أرقام PIN للموظفين ---
  const [pinSetFor, setPinSetFor] = useState(null);
  const [np1, setNp1] = useState('');
  const [np2, setNp2] = useState('');
  const savePin = async () => {
    if (!pinSetFor) return;
    if (!/^\d{4,6}$/.test(np1)) return say('رقم PIN يجب أن يكون ٤ إلى ٦ أرقام', 'no');
    if (np1 !== np2) return say('رقما PIN غير متطابقين', 'no');
    const hash = await sha(np1);
    await commit(d => { const prev = (d.hrPins || []).find(p => p.employeeId === pinSetFor.id) || {}; return { ...d, hrPins: [...(d.hrPins || []).filter(p => p.employeeId !== pinSetFor.id), { id: prev.id || uid('pin'), branchId: pinSetFor.branchId, employeeId: pinSetFor.id, badgeHash: prev.badgeHash || '', pinHash: hash, updatedAt: nowISO() }] }; },
      { actionType: 'update', targetType: 'user_account', targetId: pinSetFor.id, title: 'ضبط رقم PIN للحضور', details: pinSetFor.name });
    say('حُفظ رقم PIN ✓');
    setPinSetFor(null); setNp1(''); setNp2('');
  };
  const clearPin = async (e) => {
    if (!window.confirm('إلغاء رقم PIN الحالي لـ«' + e.name + '»؟ لن يستطيع تسجيل حضوره حتى يُضبط رقم جديد.')) return;
    await commit(d => ({ ...d, hrPins: (d.hrPins || []).map(p => p.employeeId === e.id ? { ...p, pinHash: '', updatedAt: nowISO() } : p).filter(p => p.pinHash || p.badgeHash) }),
      { actionType: 'update', targetType: 'user_account', targetId: e.id, title: 'إلغاء رقم PIN للحضور', details: e.name });
    say('أُلغي رقم PIN ✓');
  };
  // v24.1: إصدار/تجديد بطاقة QR — السرّ يُطبع مرة واحدة على البطاقة ولا يُخزَّن إلا مُجزَّأً في مستند الفرع؛ التجديد يُلغي البطاقة السابقة
  const issueBadge = async (e) => {
    if (badgeHashOf(e.id) && !window.confirm('إصدار بطاقة جديدة لـ«' + e.name + '»؟ البطاقة الحالية ستتوقف فورًا عن العمل.')) return;
    const w = window.open('', '_blank', 'width=520,height=720');   // تُفتح قبل أي انتظار كي لا يحجبها المتصفح
    // v27.13: النافذة لا تبقى فارغة أبدًا — رسالة فورية، ثم البطاقة أو سبب الفشل صريحًا
    const showMsg = (msg, err) => { try { if (w) { w.document.open(); w.document.write('<!doctype html><html dir="rtl" lang="ar"><head><meta charset="utf-8"><title>بطاقة حضور</title></head><body style="font-family:Tahoma,sans-serif;padding:28px;text-align:center;font-size:14px;color:' + (err ? '#b00' : '#333') + '">' + escH(msg) + '</body></html>'); w.document.close(); } } catch (_) { } };
    if (w) showMsg('جارٍ إصدار البطاقة…');
    try {
      const secret = uid('b').slice(2) + Math.random().toString(36).slice(2, 10) + Math.random().toString(36).slice(2, 10);
      const hash = await sha(secret);
      const ok = await commit(d => { const prev = (d.hrPins || []).find(p => p.employeeId === e.id) || {}; return { ...d, hrPins: [...(d.hrPins || []).filter(p => p.employeeId !== e.id), { id: prev.id || uid('pin'), branchId: e.branchId, employeeId: e.id, pinHash: prev.pinHash || '', badgeHash: hash, badgeIssuedAt: nowISO(), updatedAt: nowISO() }] }; },
        { actionType: 'update', targetType: 'user_account', targetId: e.id, branchName: branch ? branch.name : '', title: 'إصدار بطاقة QR للحضور', details: e.name });
      if (!ok) { showMsg('تعذّر حفظ البطاقة — تحقّق من الصلاحية أو الاتصال ثم أعِد المحاولة.', true); say('تعذّر إصدار البطاقة — لم تُحفظ', 'no'); return; }
      const payload = 'ATT:' + e.id + ':' + secret;
      const co = (org.company || {}).name || '';
      const svg = qrSvg(payload, { ecl: 2, px: 240 });
      const html = '<!doctype html><html dir="rtl" lang="ar"><head><meta charset="utf-8"><title>بطاقة حضور — ' + escH(e.name) + '</title>' +
        '<style>body{font-family:Tahoma,sans-serif;margin:0;padding:24px;display:flex;justify-content:center}.card{width:320px;border:2px solid #8C6F2C;border-radius:14px;padding:18px;text-align:center}' +
        '.co{font-size:12px;color:#5a4a1e;font-weight:700}.nm{font-size:20px;font-weight:800;margin:8px 0 2px}.br{font-size:12px;color:#666;margin-bottom:10px}.code{font-family:monospace;font-size:9px;color:#888;word-break:break-all;margin-top:8px;direction:ltr}.hint{font-size:10.5px;color:#666;margin-top:8px}@media print{body{padding:0}}</style></head><body><div class="card">' +
        '<div class="co">' + escH(co) + '</div><div class="nm">' + escH(e.name) + '</div><div class="br">' + escH(branch ? branch.name : '') + ' · بطاقة حضور</div>' +
        (svg || '<div style="color:#b00;font-size:12px">تعذّر توليد رمز QR — استخدم الرمز النصّي أدناه.</div>') + '<div class="code">' + escH(payload) + '</div><div class="hint">امسح البطاقة على جهاز الفرع لتسجيل الحضور/الانصراف. البطاقة شخصية — لا تُعِرها لأحد.</div></div>' +
        '<script>setTimeout(function(){window.print()},400)<\/script></body></html>';
      if (w) { w.document.open(); w.document.write(html); w.document.close(); } else say('اسمح بالنوافذ المنبثقة لطباعة البطاقة', 'no');
      say('صدرت بطاقة QR لـ' + e.name + ' ✓');
    } catch (err) {
      showMsg('تعذّر إصدار البطاقة: ' + (err && err.message ? err.message : 'خطأ غير متوقع'), true);
      say('تعذّر إصدار البطاقة: ' + (err && err.message ? err.message : 'خطأ غير متوقع'), 'no');
    }
  };

  // --- v26.1: حذف حدث حضور خاطئ (مدير الفرع/المركز) — بسبب موثَّق في سجل التدقيق ---
  const canFixLog = me.role === 'branch_manager' || (ROLES[me.role] || {}).scope === 'all';
  const delEvent = async (ev) => {
    const reason = window.prompt('سبب حذف حدث «' + (ev.type === 'in' ? 'حضور' : 'انصراف') + '» لـ' + ev.employeeName + ' (' + new Date(ev.at).toLocaleString('ar-SA') + ')؟');
    if (reason == null) return;
    if (!String(reason).trim()) return say('السبب إلزامي لحذف حدث حضور', 'no');
    const ok = await commit(d => ({ ...d, attendanceEvents: (d.attendanceEvents || []).filter(x => x.id !== ev.id) }),
      { actionType: 'delete', targetType: 'attendance', targetId: ev.id, branchName: ev.branchName, title: 'حذف حدث حضور', details: ev.employeeName + ' · ' + (ev.type === 'in' ? 'حضور' : 'انصراف') + ' · ' + new Date(ev.at).toLocaleString('ar-SA') + ' — السبب: ' + String(reason).trim() });
    if (ok) say('حُذف الحدث وسُجِّل السبب في التدقيق');
  };
  // --- سجل الحضور ---
  const [logBranch, setLogBranch] = useState('');
  const [logEmp, setLogEmp] = useState('');
  const [logFrom, setLogFrom] = useState(today());
  const [logTo, setLogTo] = useState(today());
  const branchIds = branches.map(b => b.id);
  const logRows = events
    .filter(ev => branchIds.includes(ev.branchId))
    .filter(ev => !logBranch || ev.branchId === logBranch)
    .filter(ev => !logEmp || ev.employeeId === logEmp)
    .filter(ev => (!logFrom || (ev.at || '') >= logFrom) && (!logTo || (ev.at || '').slice(0, 10) <= logTo))
    .sort((a, b) => (a.at < b.at ? 1 : -1));

  if (!branch && branches.length === 0) {
    return <div className="card"><div className="empty">لا يوجد فرع مُسند لحسابك — راجع مسؤول النظام.</div></div>;
  }

  return (
    <div className="grid" style={{ gap: 12 }}>
      {!isCashier && (
        <div className="card" style={{ padding: '8px 12px' }}>
          <div className="row" style={{ gap: 6, flexWrap: 'wrap', justifyContent: 'space-between' }}>
            <div className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
              <button className={'btn sm' + (view === 'kiosk' ? ' pri' : ' gh')} onClick={() => setView('kiosk')}><Fingerprint size={13} />تسجيل حضور/انصراف</button>
              <button className={'btn sm' + (view === 'pin' ? ' pri' : ' gh')} onClick={() => setView('pin')}><ShieldCheck size={13} />أرقام PIN</button>
              <button className={'btn sm' + (view === 'log' ? ' pri' : ' gh')} onClick={() => setView('log')}><Clock size={13} />سجل الحضور</button>
            </div>
            {branches.length > 1 && (
              <select className="inp sel" style={{ width: 180 }} value={branchId} onChange={e => setBranchId(e.target.value)}>
                {branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
              </select>
            )}
          </div>
        </div>
      )}

      {view === 'kiosk' && branch && (
        <div className="card">
          <div className="card-t" style={{ marginBottom: 4 }}><Fingerprint size={15} color="var(--brass)" />تسجيل الحضور — {branch.name}</div>
          <div className="note" style={{ marginBottom: 10 }}>امسح بطاقة QR الخاصة بك (بالكاميرا أو بماسح USB)، أو اختر اسمك ثم أدخل رقم PIN — يُحدَّد الحضور أو الانصراف تلقائيًا.</div>
          <div className="card" style={{ marginBottom: 12, padding: 12, border: '1px solid var(--frame-o)' }}>
            <div className="row" style={{ gap: 8, flexWrap: 'wrap', alignItems: 'flex-end' }}>
              <Field label="مسح بطاقة QR (ماسح USB أو لصق الرمز)" style={{ flex: 1, minWidth: 220 }}>
                <input className="inp" autoFocus value={scanBuf} onChange={e => setScanBuf(e.target.value)} onKeyDown={e => { if (e.key === 'Enter') handleBadge(scanBuf); }} placeholder="وجّه الماسح للبطاقة…" />
              </Field>
              <button className="btn pri" disabled={busy} onClick={startCam}><Camera size={14} />فتح الكاميرا</button>
            </div>
          </div>
          <div className="grid g3">
            {emps.map(e => {
              const nt = nextType(e.id);
              return (
                <button key={e.id} className="card" style={{ padding: 12, textAlign: 'center', cursor: 'pointer', border: '1px solid var(--frame-o)' }}
                  onClick={() => { setPinFor(e); setPinVal(''); }}>
                  <div style={{ fontWeight: 700, fontSize: 13 }}>{e.name}</div>
                  <div style={{ marginTop: 6 }}>
                    <span className={'badge ' + (nt === 'in' ? 'b-mint' : 'b-amber')}>{nt === 'in' ? 'تسجيل حضور' : 'تسجيل انصراف'}</span>
                  </div>
                  {!pinHashOf(e.id) && !badgeHashOf(e.id) && <div style={{ fontSize: 9.5, color: 'var(--rose)', marginTop: 4 }}>لا يوجد رقم PIN ولا بطاقة — راجع مدير الفرع</div>}
                </button>
              );
            })}
            {emps.length === 0 && <div className="empty">لا يوجد موظفون في هذا الفرع بعد — أضِفهم من «البيانات الرئيسية».</div>}
          </div>
        </div>
      )}

      {view === 'pin' && !isCashier && (
        <div className="card">
          <div className="card-t" style={{ marginBottom: 6 }}><ShieldCheck size={15} color="var(--brass)" />أرقام PIN للحضور</div>
          <div className="note" style={{ marginBottom: 10 }}>رقم PIN من ٤ إلى ٦ أرقام، أو بطاقة QR شخصية تُطبع ويمسحها جهاز الفرع — كلاهما لتسجيل الحضور من جهاز الفرع فقط، لا لتسجيل الدخول للنظام. إعادة إصدار البطاقة تُلغي السابقة فورًا.</div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>الموظف</th><th>PIN</th><th>بطاقة QR</th><th /></tr></thead>
              <tbody>
                {emps.map(e => (
                  <tr key={e.id}>
                    <td style={{ fontWeight: 600, fontSize: 12.5 }}>{e.name}</td>
                    <td>{pinHashOf(e.id) ? <span className="badge b-mint">مُفعَّل</span> : <span className="badge b-dim">غير مُفعَّل</span>}</td>
                    <td>{badgeHashOf(e.id) ? <span className="badge b-mint">صادرة</span> : <span className="badge b-dim">لا توجد</span>}</td>
                    <td>
                      <div className="row" style={{ gap: 5, justifyContent: 'flex-end', flexWrap: 'wrap' }}>
                        <button className="btn sm gh" onClick={() => { setPinSetFor(e); setNp1(''); setNp2(''); }}><Lock size={13} />{pinHashOf(e.id) ? 'إعادة ضبط' : 'ضبط رقم PIN'}</button>
                        {pinHashOf(e.id) && <button className="btn sm gh" onClick={() => clearPin(e)}><Trash2 size={13} />إلغاء</button>}
                        <button className="btn sm gh" onClick={() => issueBadge(e)}><QrCode size={13} />{badgeHashOf(e.id) ? 'إعادة إصدار البطاقة' : 'بطاقة QR'}</button>
                      </div>
                    </td>
                  </tr>
                ))}
                {emps.length === 0 && <tr><td colSpan={4}><div className="empty">لا يوجد موظفون في هذا الفرع بعد.</div></td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {view === 'log' && !isCashier && (
        <div className="card">
          <div className="card-t" style={{ marginBottom: 10 }}><Clock size={15} color="var(--brass)" />سجل الحضور</div>
          <div className="row" style={{ gap: 8, flexWrap: 'wrap', marginBottom: 10 }}>
            {branches.length > 1 && (
              <select className="inp sel" style={{ width: 160 }} value={logBranch} onChange={e => setLogBranch(e.target.value)}>
                <option value="">كل الفروع</option>
                {branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
              </select>
            )}
            <select className="inp sel" style={{ width: 160 }} value={logEmp} onChange={e => setLogEmp(e.target.value)}>
              <option value="">كل الموظفين</option>
              {(org.employees || []).filter(e => branchIds.includes(e.branchId)).map(e => <option key={e.id} value={e.id}>{e.name}</option>)}
            </select>
            <input className="inp" type="date" style={{ width: 140 }} value={logFrom} onChange={e => setLogFrom(e.target.value)} />
            <input className="inp" type="date" style={{ width: 140 }} value={logTo} onChange={e => setLogTo(e.target.value)} />
          </div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>الوقت</th><th>الموظف</th><th>الفرع</th><th>النوع</th><th>الطريقة</th><th>الموقع</th>{canFixLog && <th />}</tr></thead>
              <tbody>
                {logRows.map(ev => (
                  <tr key={ev.id}>
                    <td style={{ fontSize: 12 }}>{new Date(ev.at).toLocaleString('ar-SA')}</td>
                    <td style={{ fontWeight: 600, fontSize: 12.5 }}>{ev.employeeName}</td>
                    <td style={{ fontSize: 12 }}>{ev.branchName}</td>
                    <td><span className={'badge ' + (ev.type === 'in' ? 'b-mint' : 'b-amber')}>{ev.type === 'in' ? 'حضور' : 'انصراف'}</span></td>
                    <td><span className="badge b-dim">{ev.via === 'badge' ? 'بطاقة QR' : 'PIN'}</span></td>
                    <td>
                      {ev.withinGeofence === true && <span className="badge b-mint">ضمن النطاق</span>}
                      {ev.withinGeofence === false && <span className="badge b-rose">خارج النطاق ({ev.distanceMeters}م)</span>}
                      {ev.withinGeofence == null && <span className="badge b-dim">—</span>}
                    </td>
                    {canFixLog && <td><button className="btn sm gh" title="حذف حدث خاطئ" onClick={() => delEvent(ev)}><Trash2 size={13} /></button></td>}
                  </tr>
                ))}
                {logRows.length === 0 && <tr><td colSpan={canFixLog ? 7 : 6}><div className="empty">لا توجد سجلات حضور ضمن هذه الفلاتر.</div></td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {cam && (
        <Modal title="مسح بطاقة QR" icon={Camera} onClose={stopCam} foot={<button className="btn gh" onClick={stopCam}>إغلاق</button>}>
          <div style={{ textAlign: 'center' }}>
            <video ref={videoRef} playsInline muted style={{ width: '100%', maxWidth: 380, borderRadius: 12, background: '#000' }} />
            <div className="note" style={{ marginTop: 8 }}>وجّه الكاميرا نحو بطاقة الموظف — يُسجَّل الحضور فور قراءتها.</div>
          </div>
        </Modal>
      )}
      {pinFor && (
        <Modal title={'تسجيل ' + (nextType(pinFor.id) === 'in' ? 'حضور' : 'انصراف') + ' — ' + pinFor.name} icon={Fingerprint} onClose={() => { setPinFor(null); setPinVal(''); }}
          foot={<>
            <button className="btn gh" onClick={() => { setPinFor(null); setPinVal(''); }}>إلغاء</button>
            <button className="btn pri" disabled={busy} onClick={doCheck}><Check size={14} />{busy ? 'جارٍ...' : 'تأكيد'}</button>
          </>}>
          <Field label="رقم PIN">
            <input className="inp" type="password" inputMode="numeric" maxLength={6} autoFocus value={pinVal}
              onChange={e => setPinVal(e.target.value.replace(/\D/g, ''))}
              onKeyDown={e => { if (e.key === 'Enter') doCheck(); }} placeholder="••••" />
          </Field>
        </Modal>
      )}

      {pinSetFor && (
        <Modal title={'ضبط رقم PIN — ' + pinSetFor.name} icon={Lock} onClose={() => setPinSetFor(null)}
          foot={<>
            <button className="btn gh" onClick={() => setPinSetFor(null)}>إلغاء</button>
            <button className="btn pri" onClick={savePin}><Check size={14} />حفظ</button>
          </>}>
          <div className="grid" style={{ gap: 10 }}>
            <Field label="رقم PIN الجديد (٤-٦ أرقام)">
              <input className="inp" type="password" inputMode="numeric" maxLength={6} autoFocus value={np1} onChange={e => setNp1(e.target.value.replace(/\D/g, ''))} placeholder="••••" />
            </Field>
            <Field label="تأكيد رقم PIN">
              <input className="inp" type="password" inputMode="numeric" maxLength={6} value={np2} onChange={e => setNp2(e.target.value.replace(/\D/g, ''))} placeholder="••••" />
            </Field>
          </div>
        </Modal>
      )}
    </div>
  );
}

/* ============================================================
   م٤ — محرّك الورديات (Shift Engine)
   قوالب ورديات لكل فرع + تقويم تعيين أسبوعي + مطابقة تلقائية مع
   الحضور الفعلي (ops.attendanceEvents من م٣) + طلبات تبديل وردية بين
   موظفين + طلبات نقل موظف بين الفروع. تبويب مستقل (وليس متداخلًا داخل
   people) — مضاف صراحةً في ثلاثة مواضع معًا: ROLES.tabs، بلاطة
   LAUNCH_APPS/REG_APPS، ومصفوفة NAV (درس v19.0→v19.1، راجع الدليل).
   ============================================================ */
function ShiftEngine({ org, ops, me, myBranches, commitOrg, commit, say }) {
  const role = ROLES[me.role] || {};
  const isAll = role.scope === 'all';
  const canEdit = role.scope === 'own' || isAll; // تعديل: مدير الفرع + أدوار المركز — بلا تعديل للمدير الإقليمي (اطّلاع فقط)
  const canApproveTransfer = isAll; // اعتماد نقل الموظف بين الفروع: أدوار المركز فقط (أثر مالي/تنظيمي عابر للفروع)
  const branches = myBranches || [];
  const policies = { ...defaultHrPolicies(), ...(org.hrPolicies || {}) };
  const tolerance = Number(policies.lateToleranceMinutes) || 0;

  const [view, setView] = useState('templates');
  const [branchId, setBranchId] = useState((branches[0] || {}).id || '');
  useEffect(() => {
    if (!branches.find(b => b.id === branchId)) setBranchId((branches[0] || {}).id || '');
  }, [branches, branchId]);
  const branch = branches.find(b => b.id === branchId) || null;
  const branchIds = branches.map(b => b.id);

  const emps = (org.employees || []).filter(e => e.isActive !== false && branch && e.branchId === branch.id);
  const templates = (ops.shiftTemplates || []).filter(t => branch && t.branchId === branch.id);

  const addDays = (ds, n) => { const d = new Date(ds + 'T00:00:00'); d.setDate(d.getDate() + n); return d.toISOString().slice(0, 10); };
  const weekdayOf = (ds) => new Date(ds + 'T00:00:00').getDay();
  const dNm = (ds) => new Date(ds + 'T00:00:00').toLocaleDateString('ar', { weekday: 'short' });
  const dDay = (ds) => new Date(ds + 'T00:00:00').toLocaleDateString('en-GB', { day: '2-digit', month: '2-digit' });
  const parseHM = (t) => { const [h, m] = String(t || '00:00').split(':').map(Number); return (h || 0) * 60 + (m || 0); };

  const [weekStart, setWeekStart] = useState(() => today());
  const D7 = [0, 1, 2, 3, 4, 5, 6];
  const days = D7.map(i => addDays(weekStart, i));

  // === ١) قوالب الورديات ===
  const [tplF, setTplF] = useState(null); // {id?, name, startTime, endTime, breakMinutes, days:[]}
  const saveTpl = async () => {
    if (!branch) return;
    if (!tplF.name || !tplF.startTime || !tplF.endTime) return say('أدخل الاسم ووقتي البداية والنهاية', 'no');
    const rec = { id: tplF.id || uid('shtpl'), branchId: branch.id, name: tplF.name, startTime: tplF.startTime, endTime: tplF.endTime, breakMinutes: Number(tplF.breakMinutes) || 0, days: tplF.days && tplF.days.length ? tplF.days : [0, 1, 2, 3, 4, 5, 6] };
    const exists = (ops.shiftTemplates || []).some(t => t.id === rec.id);
    await commit(d => ({ ...d, shiftTemplates: exists ? (d.shiftTemplates || []).map(t => t.id === rec.id ? rec : t) : [...(d.shiftTemplates || []), rec] }),
      { actionType: exists ? 'update' : 'create', targetType: 'shift_template', targetId: rec.id, branchName: branch.name, title: exists ? 'عدّل قالب وردية' : 'أضاف قالب وردية', details: branch.name + ' — ' + rec.name });
    say('حُفظ قالب الوردية ✓'); setTplF(null);
  };
  const delTpl = async (t) => {
    if (!window.confirm('حذف قالب «' + t.name + '»؟ التعيينات القائمة عليه ستظهر بلا قالب (لن تُحذف بياناتها).')) return;
    await commit(d => ({ ...d, shiftTemplates: (d.shiftTemplates || []).filter(x => x.id !== t.id) }),
      { actionType: 'delete', targetType: 'shift_template', targetId: t.id, branchName: branch.name, title: 'حذف قالب وردية', details: t.name });
    say('حُذف القالب ✓');
  };

  // === ٢) تقويم التعيين الأسبوعي (ops.shiftAssignments — تُبقيها بجانب ops.attendanceEvents وطلبات التبديل/النقل
  // في نفس المستند كي يُعتمَد التبديل بكتابة ذرّية واحدة تُحدِّث التعيين وحالة الطلب معًا) ===
  const assignRecs = (ops.shiftAssignments || []).filter(a => a.weekStart === weekStart && branch && a.branchId === branch.id);
  const [draftAssign, setDraftAssign] = useState({}); // {empId: [7]}
  const shiftIdsOf = (empId) => {
    if (draftAssign[empId]) return draftAssign[empId];
    const r = assignRecs.find(a => a.empId === empId);
    return (r && r.shiftIds) || Array(7).fill('');
  };
  const setShiftId = (empId, di, val) => setDraftAssign(s => { const arr = [...shiftIdsOf(empId)]; arr[di] = val; return { ...s, [empId]: arr }; });
  const dirtyAssign = Object.keys(draftAssign).length > 0;
  const saveAssign = async () => {
    if (!branch) return;
    const recs = emps.map(e => ({ id: (assignRecs.find(a => a.empId === e.id) || {}).id || uid('shas'), weekStart, empId: e.id, branchId: branch.id, shiftIds: shiftIdsOf(e.id) }));
    await commit(d => ({ ...d, shiftAssignments: [...(d.shiftAssignments || []).filter(a => !(a.weekStart === weekStart && a.branchId === branch.id)), ...recs] }),
      { actionType: 'update', targetType: 'shift_assignment', targetId: weekStart, branchName: branch.name, title: 'حفظ تعيين ورديات الأسبوع', details: branch.name + ' — أسبوع ' + weekStart });
    setDraftAssign({}); say('حُفظ تعيين الأسبوع ✓');
  };
  const coverage = (di) => {
    const ds = days[di]; const wd = weekdayOf(ds);
    return templates.filter(t => (t.days || []).includes(wd)).map(t => ({ t, n: emps.filter(e => shiftIdsOf(e.id)[di] === t.id).length }));
  };

  // === ٣) مطابقة الحضور الفعلي بالجدول ===
  const matchRows = [];
  emps.forEach(e => {
    D7.forEach(di => {
      const shiftId = shiftIdsOf(e.id)[di];
      if (!shiftId) return;
      const tpl = templates.find(t => t.id === shiftId);
      const ds = days[di];
      if (ds > today()) { matchRows.push({ e, ds, tpl, status: 'upcoming' }); return; }
      const evs = (ops.attendanceEvents || []).filter(ev => ev.employeeId === e.id && (ev.at || '').slice(0, 10) === ds).sort((a, b) => a.at < b.at ? -1 : 1);
      const inEv = evs.find(ev => ev.type === 'in');
      const outEvs = evs.filter(ev => ev.type === 'out');
      const outEv = outEvs[outEvs.length - 1];
      if (!inEv) { matchRows.push({ e, ds, tpl, status: 'absent' }); return; }
      const inMin = new Date(inEv.at).getHours() * 60 + new Date(inEv.at).getMinutes();
      const lateBy = tpl ? inMin - parseHM(tpl.startTime) - tolerance : 0;
      let status = lateBy > 0 ? 'late' : 'on_time';
      let extra = lateBy > 0 ? lateBy : 0;
      if (outEv) {
        const outMin = new Date(outEv.at).getHours() * 60 + new Date(outEv.at).getMinutes();
        const earlyBy = tpl ? parseHM(tpl.endTime) - outMin - tolerance : 0;
        if (earlyBy > 0) { status = status === 'late' ? 'late_early' : 'early'; extra = Math.max(extra, earlyBy); }
      } else if (ds < today()) { status = status === 'late' ? 'late_nocheckout' : 'no_checkout'; }
      matchRows.push({ e, ds, tpl, status, extra, inEv, outEv });
    });
  });
  const matchLabel = { upcoming: ['قادم', 'b-dim'], absent: ['غياب', 'b-rose'], on_time: ['في الوقت', 'b-mint'], late: ['تأخير', 'b-amber'], early: ['انصراف مبكر', 'b-amber'], late_early: ['تأخير + انصراف مبكر', 'b-rose'], no_checkout: ['لم يُسجَّل انصراف', 'b-amber'], late_nocheckout: ['تأخير + لم يُسجَّل انصراف', 'b-rose'] };

  // === ٤) طلبات تبديل الوردية ===
  const [swapF, setSwapF] = useState({ di: 0, empA: '', empB: '' });
  const swapReqs = (ops.shiftSwapRequests || []).filter(r => branchIds.includes(r.branchId)).sort((a, b) => (a.requestedAt < b.requestedAt ? 1 : -1));
  const requestSwap = async () => {
    if (!branch || !swapF.empA || !swapF.empB || swapF.empA === swapF.empB) return say('اختر موظفين مختلفين', 'no');
    const rec = { id: uid('swap'), weekStart, day: Number(swapF.di), branchId: branch.id, branchName: branch.name, empFromId: swapF.empA, empFromName: emps.find(e => e.id === swapF.empA)?.name || '', empToId: swapF.empB, empToName: emps.find(e => e.id === swapF.empB)?.name || '', status: 'pending', requestedBy: me.id, requestedByName: me.name, requestedAt: nowISO() };
    await commit(d => ({ ...d, shiftSwapRequests: [rec, ...(d.shiftSwapRequests || [])] }),
      { actionType: 'create', targetType: 'shift_swap', targetId: rec.id, branchName: branch.name, title: 'طلب تبديل وردية', details: rec.empFromName + ' ↔ ' + rec.empToName + ' — ' + HR_WEEK_DAYS[rec.day].ar });
    say('أُرسل طلب التبديل ✓'); setSwapF({ di: 0, empA: '', empB: '' });
  };
  // v26.1 — إلغاء طلب معلّق (تبديل/نقل) قبل البتّ فيه
  const cancelSwap = async (r) => {
    if (r.status !== 'pending' || !window.confirm('إلغاء طلب التبديل بين ' + r.empFromName + ' و' + r.empToName + '؟')) return;
    await commit(d => ({ ...d, shiftSwapRequests: (d.shiftSwapRequests || []).filter(x => x.id !== r.id) }),
      { actionType: 'delete', targetType: 'shift_swap', targetId: r.id, branchName: r.branchName, title: 'إلغاء طلب تبديل وردية', details: r.empFromName + ' ↔ ' + r.empToName });
    say('أُلغي الطلب');
  };
  const cancelTransfer = async (r) => {
    if (r.status !== 'pending' || !window.confirm('إلغاء طلب نقل «' + r.employeeName + '» إلى ' + r.toBranchName + '؟')) return;
    await commit(d => ({ ...d, branchTransferRequests: (d.branchTransferRequests || []).filter(x => x.id !== r.id) }),
      { actionType: 'delete', targetType: 'branch_transfer', targetId: r.id, branchName: r.fromBranchName, title: 'إلغاء طلب نقل موظف', details: r.employeeName });
    say('أُلغي الطلب');
  };
  const decideSwap = async (r, approve) => {
    if (approve) {
      const recA = (ops.shiftAssignments || []).find(a => a.weekStart === r.weekStart && a.branchId === r.branchId && a.empId === r.empFromId);
      const recB = (ops.shiftAssignments || []).find(a => a.weekStart === r.weekStart && a.branchId === r.branchId && a.empId === r.empToId);
      const arrA = (recA && recA.shiftIds) || Array(7).fill('');
      const arrB = (recB && recB.shiftIds) || Array(7).fill('');
      const newArrA = [...arrA]; const newArrB = [...arrB];
      const tmp = newArrA[r.day]; newArrA[r.day] = newArrB[r.day]; newArrB[r.day] = tmp;
      await commit(d => {
        let list = (d.shiftAssignments || []).slice();
        const upsert = (empId, arr) => {
          const idx = list.findIndex(a => a.weekStart === r.weekStart && a.branchId === r.branchId && a.empId === empId);
          if (idx >= 0) list[idx] = { ...list[idx], shiftIds: arr };
          else list.push({ id: uid('shas'), weekStart: r.weekStart, branchId: r.branchId, empId, shiftIds: arr });
        };
        upsert(r.empFromId, newArrA); upsert(r.empToId, newArrB);
        return { ...d, shiftAssignments: list, shiftSwapRequests: (d.shiftSwapRequests || []).map(x => x.id === r.id ? { ...x, status: 'approved', decidedBy: me.id, decidedByName: me.name, decidedAt: nowISO() } : x) };
      }, { actionType: 'update', targetType: 'shift_swap', targetId: r.id, branchName: r.branchName, title: 'اعتماد تبديل وردية', details: r.empFromName + ' ↔ ' + r.empToName });
      say('اعتُمد التبديل وطُبِّق على الجدول ✓');
    } else {
      await commit(d => ({ ...d, shiftSwapRequests: (d.shiftSwapRequests || []).map(x => x.id === r.id ? { ...x, status: 'rejected', decidedBy: me.id, decidedByName: me.name, decidedAt: nowISO() } : x) }),
        { actionType: 'update', targetType: 'shift_swap', targetId: r.id, branchName: r.branchName, title: 'رفض تبديل وردية', details: r.empFromName + ' ↔ ' + r.empToName });
      say('رُفض الطلب');
    }
  };

  // === ٥) طلبات نقل موظف بين الفروع ===
  const [trF, setTrF] = useState({ empId: '', toBranchId: '', note: '' });
  const transferReqs = (ops.branchTransferRequests || []).filter(r => branchIds.includes(r.fromBranchId) || isAll).sort((a, b) => (a.requestedAt < b.requestedAt ? 1 : -1));
  const requestTransfer = async () => {
    if (!branch || !trF.empId || !trF.toBranchId) return say('اختر الموظف والفرع الجديد', 'no');
    const emp = (org.employees || []).find(x => x.id === trF.empId);
    const toB = (org.branches || []).find(x => x.id === trF.toBranchId);
    const rec = { id: uid('trreq'), branchId: branch.id, employeeId: emp.id, employeeName: emp.name, fromBranchId: branch.id, fromBranchName: branch.name, toBranchId: toB.id, toBranchName: toB.name, note: trF.note || '', status: 'pending', requestedBy: me.id, requestedByName: me.name, requestedAt: nowISO() };
    await commit(d => ({ ...d, branchTransferRequests: [rec, ...(d.branchTransferRequests || [])] }),
      { actionType: 'create', targetType: 'branch_transfer', targetId: rec.id, branchName: branch.name, title: 'طلب نقل موظف بين الفروع', details: emp.name + ': ' + branch.name + ' ← ' + toB.name });
    say('أُرسل طلب النقل ✓'); setTrF({ empId: '', toBranchId: '', note: '' });
  };
  const decideTransfer = async (r, approve) => {
    if (approve) {
      // v24.0: نقل الموظف في org (أدوار المركز تكتبه) ثم حالة الطلب في مستند الفرع — بترتيب يجعل إعادة المحاولة آمنة
      const ok1 = await commitOrg(d => ({ ...d, employees: (d.employees || []).map(x => x.id === r.employeeId ? { ...x, branchId: r.toBranchId } : x) }),
        { actionType: 'update', targetType: 'branch_transfer', targetId: r.id, branchName: r.toBranchName, title: 'اعتماد نقل موظف بين الفروع', details: r.employeeName + ': ' + r.fromBranchName + ' ← ' + r.toBranchName });
      if (!ok1) return;
      await commit(d => ({ ...d, branchTransferRequests: (d.branchTransferRequests || []).map(x => x.id === r.id ? { ...x, status: 'approved', decidedBy: me.id, decidedByName: me.name, decidedAt: nowISO() } : x) }));
      say('اعتُمد النقل — الموظف الآن ضمن ' + r.toBranchName + ' ✓');
    } else {
      await commit(d => ({ ...d, branchTransferRequests: (d.branchTransferRequests || []).map(x => x.id === r.id ? { ...x, status: 'rejected', decidedBy: me.id, decidedByName: me.name, decidedAt: nowISO() } : x) }),
        { actionType: 'update', targetType: 'branch_transfer', targetId: r.id, branchName: r.fromBranchName, title: 'رفض نقل موظف بين الفروع', details: r.employeeName });
      say('رُفض الطلب');
    }
  };

  if (!branch && branches.length === 0) {
    return <div className="card"><div className="empty">لا يوجد فرع مُسند لحسابك — راجع مسؤول النظام.</div></div>;
  }

  return (
    <div className="grid" style={{ gap: 12 }}>
      <div className="card" style={{ padding: '8px 12px' }}>
        <div className="row" style={{ gap: 6, flexWrap: 'wrap', justifyContent: 'space-between' }}>
          <div className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
            <button className={'btn sm' + (view === 'templates' ? ' pri' : ' gh')} onClick={() => setView('templates')}><Clock size={13} />قوالب الورديات</button>
            <button className={'btn sm' + (view === 'calendar' ? ' pri' : ' gh')} onClick={() => setView('calendar')}><CalendarDays size={13} />التعيين الأسبوعي</button>
            <button className={'btn sm' + (view === 'match' ? ' pri' : ' gh')} onClick={() => setView('match')}><ShieldCheck size={13} />مطابقة الحضور</button>
            <button className={'btn sm' + (view === 'swap' ? ' pri' : ' gh')} onClick={() => setView('swap')}><ArrowLeftRight size={13} />تبديل وردية</button>
            <button className={'btn sm' + (view === 'transfer' ? ' pri' : ' gh')} onClick={() => setView('transfer')}><Send size={13} />نقل موظف</button>
          </div>
          {branches.length > 1 && (
            <select className="inp sel" style={{ width: 180 }} value={branchId} onChange={e => setBranchId(e.target.value)}>
              {branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
            </select>
          )}
        </div>
      </div>

      {view === 'templates' && branch && (
        <div className="card">
          <div className="card-h" style={{ marginBottom: 8 }}>
            <div className="card-t"><Clock size={15} color="var(--brass)" />قوالب الورديات — {branch.name}</div>
            {canEdit && <button className="btn sm pri" onClick={() => setTplF({ name: '', startTime: '08:00', endTime: '16:00', breakMinutes: 0, days: [0, 1, 2, 3, 4, 5, 6] })}><Plus size={13} />قالب جديد</button>}
          </div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>الاسم</th><th>البداية</th><th>النهاية</th><th>الاستراحة</th><th>أيام التطبيق</th>{canEdit && <th />}</tr></thead>
              <tbody>
                {templates.map(t => (
                  <tr key={t.id}>
                    <td style={{ fontWeight: 600, fontSize: 12.5 }}>{t.name}</td>
                    <td className="num">{t.startTime}</td>
                    <td className="num">{t.endTime}</td>
                    <td className="num">{t.breakMinutes || 0} د</td>
                    <td style={{ fontSize: 11 }}>{(t.days || []).map(d => HR_WEEK_DAYS.find(x => x.v === d)?.ar.slice(0, 3)).join('، ')}</td>
                    {canEdit && <td>
                      <div className="row" style={{ gap: 5, justifyContent: 'flex-end' }}>
                        <button className="btn sm gh" onClick={() => setTplF({ ...t })}>تعديل</button>
                        <button className="btn sm gh" onClick={() => delTpl(t)}><Trash2 size={13} /></button>
                      </div>
                    </td>}
                  </tr>
                ))}
                {templates.length === 0 && <tr><td colSpan={canEdit ? 6 : 5}><div className="empty">لا توجد قوالب ورديات لهذا الفرع بعد.</div></td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {tplF && (
        <Modal title={tplF.id ? 'تعديل قالب وردية' : 'قالب وردية جديد'} icon={Clock} onClose={() => setTplF(null)}
          foot={<>
            <button className="btn gh" onClick={() => setTplF(null)}>إلغاء</button>
            <button className="btn pri" onClick={saveTpl}><Check size={14} />حفظ</button>
          </>}>
          <div className="grid" style={{ gap: 10 }}>
            <Field label="اسم الوردية">
              <input className="inp" autoFocus value={tplF.name} onChange={e => setTplF(f => ({ ...f, name: e.target.value }))} placeholder="صباحية" />
            </Field>
            <div className="grid g2">
              <Field label="وقت البداية"><input type="time" className="inp" value={tplF.startTime} onChange={e => setTplF(f => ({ ...f, startTime: e.target.value }))} /></Field>
              <Field label="وقت النهاية"><input type="time" className="inp" value={tplF.endTime} onChange={e => setTplF(f => ({ ...f, endTime: e.target.value }))} /></Field>
            </div>
            <Field label="مدة الاستراحة (دقائق)">
              <input className="inp n" inputMode="numeric" value={tplF.breakMinutes} onChange={e => setTplF(f => ({ ...f, breakMinutes: e.target.value.replace(/\D/g, '') }))} />
            </Field>
            <Field label="أيام التطبيق">
              <div className="row" style={{ gap: 10, flexWrap: 'wrap' }}>
                {HR_WEEK_DAYS.map(d => (
                  <label key={d.v} className="row" style={{ gap: 5, fontSize: 12.5, cursor: 'pointer' }}>
                    <input type="checkbox" checked={(tplF.days || []).includes(d.v)}
                      onChange={e => setTplF(f => ({ ...f, days: e.target.checked ? [...(f.days || []), d.v] : (f.days || []).filter(x => x !== d.v) }))} />
                    {d.ar}
                  </label>
                ))}
              </div>
            </Field>
          </div>
        </Modal>
      )}

      {view === 'calendar' && branch && (
        <div className="card">
          <div className="row" style={{ gap: 8, flexWrap: 'wrap', alignItems: 'center', marginBottom: 10 }}>
            <button className="btn sm gh" onClick={() => { setWeekStart(w => addDays(w, -7)); setDraftAssign({}); }}>▶ الأسبوع السابق</button>
            <input type="date" className="inp" style={{ width: 150 }} value={weekStart} onChange={e => { if (e.target.value) { setWeekStart(e.target.value); setDraftAssign({}); } }} />
            <button className="btn sm gh" onClick={() => { setWeekStart(w => addDays(w, 7)); setDraftAssign({}); }}>الأسبوع التالي ◀</button>
            <div style={{ flex: 1 }} />
            {canEdit && dirtyAssign && <button className="btn sm pri" onClick={saveAssign}><Check size={14} />حفظ تعيين الأسبوع</button>}
          </div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>الموظف</th>{days.map((ds, di) => <th key={di} style={{ textAlign: 'center', minWidth: 90 }}>{dNm(ds)}<div style={{ fontSize: 9, color: 'var(--faint)', fontWeight: 400 }}>{dDay(ds)}</div></th>)}</tr></thead>
              <tbody>
                {emps.map(e => (
                  <tr key={e.id}>
                    <td style={{ fontWeight: 600, fontSize: 12.5 }}>{e.name}</td>
                    {D7.map(di => {
                      const wd = weekdayOf(days[di]);
                      const opts = templates.filter(t => (t.days || []).includes(wd));
                      return (
                        <td key={di} style={{ textAlign: 'center' }}>
                          <select className="inp sel" style={{ width: 84, fontSize: 11 }} disabled={!canEdit} value={shiftIdsOf(e.id)[di] || ''} onChange={ev => setShiftId(e.id, di, ev.target.value)}>
                            <option value="">— إجازة —</option>
                            {opts.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
                          </select>
                        </td>
                      );
                    })}
                  </tr>
                ))}
                {emps.length === 0 && <tr><td colSpan={8}><div className="empty">لا يوجد موظفون في هذا الفرع بعد.</div></td></tr>}
              </tbody>
            </table>
          </div>
          {templates.length > 0 && (
            <div className="row" style={{ gap: 10, flexWrap: 'wrap', marginTop: 10 }}>
              {D7.map(di => {
                const cov = coverage(di).filter(c => c.n === 0);
                return cov.length ? <span key={di} className="badge b-amber">{dNm(days[di])}: لا تغطية لـ{cov.map(c => c.t.name).join('، ')}</span> : null;
              })}
            </div>
          )}
        </div>
      )}

      {view === 'match' && branch && (
        <div className="card">
          <div className="card-t" style={{ marginBottom: 8 }}><ShieldCheck size={15} color="var(--brass)" />مطابقة الحضور الفعلي بالجدول المعيَّن — {branch.name}</div>
          <div className="note" style={{ marginBottom: 10 }}>تقارن هذه الشاشة حركات الحضور الفعلية (من «الحضور الموثَّق») بوقت بداية/نهاية الوردية المُعيَّنة لكل موظف — بلا أي حجب أو منع، تصنيف معلوماتي فقط لأسبوع {weekStart}.</div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>الموظف</th><th>اليوم</th><th>الوردية</th><th>الحضور الفعلي</th><th>الانصراف الفعلي</th><th>الحالة</th></tr></thead>
              <tbody>
                {matchRows.map((r, i) => {
                  const lb = matchLabel[r.status];
                  return (
                    <tr key={i}>
                      <td style={{ fontWeight: 600, fontSize: 12.5 }}>{r.e.name}</td>
                      <td style={{ fontSize: 12 }}>{dNm(r.ds)} {dDay(r.ds)}</td>
                      <td style={{ fontSize: 12 }}>{r.tpl ? r.tpl.name + ' (' + r.tpl.startTime + '-' + r.tpl.endTime + ')' : 'قالب محذوف'}</td>
                      <td className="num">{r.inEv ? new Date(r.inEv.at).toLocaleTimeString('ar-SA', { hour: '2-digit', minute: '2-digit' }) : '—'}</td>
                      <td className="num">{r.outEv ? new Date(r.outEv.at).toLocaleTimeString('ar-SA', { hour: '2-digit', minute: '2-digit' }) : '—'}</td>
                      <td><span className={'badge ' + lb[1]}>{lb[0]}{r.extra ? ' (' + r.extra + 'د)' : ''}</span></td>
                    </tr>
                  );
                })}
                {matchRows.length === 0 && <tr><td colSpan={6}><div className="empty">لا تعيينات ورديات لهذا الأسبوع بعد — عيّن من «التعيين الأسبوعي».</div></td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {view === 'swap' && branch && (
        <div className="grid" style={{ gap: 12 }}>
          {canEdit && (
            <div className="card">
              <div className="card-t" style={{ marginBottom: 8 }}><ArrowLeftRight size={15} color="var(--brass)" />طلب تبديل وردية جديد</div>
              <div className="grid g3">
                <Field label="اليوم"><select className="inp sel" value={swapF.di} onChange={e => setSwapF(f => ({ ...f, di: e.target.value }))}>{HR_WEEK_DAYS.map(d => <option key={d.v} value={d.v}>{d.ar}</option>)}</select></Field>
                <Field label="الموظف الأول"><select className="inp sel" value={swapF.empA} onChange={e => setSwapF(f => ({ ...f, empA: e.target.value }))}><option value="">اختر</option>{emps.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}</select></Field>
                <Field label="الموظف الثاني"><select className="inp sel" value={swapF.empB} onChange={e => setSwapF(f => ({ ...f, empB: e.target.value }))}><option value="">اختر</option>{emps.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}</select></Field>
              </div>
              <div className="row" style={{ justifyContent: 'flex-end', marginTop: 10 }}>
                <button className="btn pri" onClick={requestSwap}><Send size={14} />إرسال طلب التبديل</button>
              </div>
            </div>
          )}
          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}>طلبات التبديل</div>
            <div className="tw">
              <table className="tb">
                <thead><tr><th>اليوم</th><th>الموظفان</th><th>الحالة</th>{canEdit && <th />}</tr></thead>
                <tbody>
                  {swapReqs.map(r => (
                    <tr key={r.id}>
                      <td style={{ fontSize: 12 }}>{HR_WEEK_DAYS[r.day]?.ar} · {r.weekStart}</td>
                      <td style={{ fontSize: 12.5, fontWeight: 600 }}>{r.empFromName} ↔ {r.empToName}</td>
                      <td><span className={'badge ' + (r.status === 'approved' ? 'b-mint' : r.status === 'rejected' ? 'b-rose' : 'b-amber')}>{r.status === 'approved' ? 'معتمد' : r.status === 'rejected' ? 'مرفوض' : 'قيد الانتظار'}</span></td>
                      {canEdit && <td>
                        {r.status === 'pending' && <div className="row" style={{ gap: 5, justifyContent: 'flex-end' }}>
                          <button className="btn sm pri" onClick={() => decideSwap(r, true)}><Check size={13} />اعتماد</button>
                          <button className="btn sm gh" onClick={() => decideSwap(r, false)}><X size={13} />رفض</button>
                          <button className="btn sm gh" title="إلغاء الطلب" onClick={() => cancelSwap(r)}><Trash2 size={13} /></button>
                        </div>}
                      </td>}
                    </tr>
                  ))}
                  {swapReqs.length === 0 && <tr><td colSpan={canEdit ? 4 : 3}><div className="empty">لا توجد طلبات تبديل بعد.</div></td></tr>}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {view === 'transfer' && branch && (
        <div className="grid" style={{ gap: 12 }}>
          {canEdit && (
            <div className="card">
              <div className="card-t" style={{ marginBottom: 8 }}><Send size={15} color="var(--brass)" />طلب نقل موظف إلى فرع آخر</div>
              <div className="grid g3">
                <Field label="الموظف"><select className="inp sel" value={trF.empId} onChange={e => setTrF(f => ({ ...f, empId: e.target.value }))}><option value="">اختر</option>{emps.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}</select></Field>
                <Field label="الفرع الجديد"><select className="inp sel" value={trF.toBranchId} onChange={e => setTrF(f => ({ ...f, toBranchId: e.target.value }))}><option value="">اختر</option>{(org.branches || []).filter(b => b.id !== branch.id).map(b => <option key={b.id} value={b.id}>{b.name}</option>)}</select></Field>
                <Field label="ملاحظة (اختياري)"><input className="inp" value={trF.note} onChange={e => setTrF(f => ({ ...f, note: e.target.value }))} /></Field>
              </div>
              <div className="row" style={{ justifyContent: 'flex-end', marginTop: 10 }}>
                <button className="btn pri" onClick={requestTransfer}><Send size={14} />إرسال طلب النقل</button>
              </div>
            </div>
          )}
          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}>طلبات النقل {canApproveTransfer ? '(كل الفروع)' : '(فرعي)'}</div>
            <div className="note" style={{ marginBottom: 8 }}>اعتماد النقل يُغيِّر فرع الموظف فعليًا فور الموافقة — متاح لأدوار المركز فقط لأثره المالي والتنظيمي العابر للفروع.</div>
            <div className="tw">
              <table className="tb">
                <thead><tr><th>الموظف</th><th>من</th><th>إلى</th><th>الحالة</th>{(canApproveTransfer || canEdit) && <th />}</tr></thead>
                <tbody>
                  {transferReqs.map(r => (
                    <tr key={r.id}>
                      <td style={{ fontWeight: 600, fontSize: 12.5 }}>{r.employeeName}</td>
                      <td style={{ fontSize: 12 }}>{r.fromBranchName}</td>
                      <td style={{ fontSize: 12 }}>{r.toBranchName}</td>
                      <td><span className={'badge ' + (r.status === 'approved' ? 'b-mint' : r.status === 'rejected' ? 'b-rose' : 'b-amber')}>{r.status === 'approved' ? 'معتمد' : r.status === 'rejected' ? 'مرفوض' : 'قيد الانتظار'}</span></td>
                      {(canApproveTransfer || canEdit) && <td>
                        {r.status === 'pending' && <div className="row" style={{ gap: 5, justifyContent: 'flex-end' }}>
                          {canApproveTransfer && <button className="btn sm pri" onClick={() => decideTransfer(r, true)}><Check size={13} />اعتماد</button>}
                          {canApproveTransfer && <button className="btn sm gh" onClick={() => decideTransfer(r, false)}><X size={13} />رفض</button>}
                          <button className="btn sm gh" title="إلغاء الطلب" onClick={() => cancelTransfer(r)}><Trash2 size={13} /></button>
                        </div>}
                      </td>}
                    </tr>
                  ))}
                  {transferReqs.length === 0 && <tr><td colSpan={(canApproveTransfer || canEdit) ? 5 : 4}><div className="empty">لا توجد طلبات نقل بعد.</div></td></tr>}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function Tasks({ org, ops, me, myBranches, commit, say }) {
  const role = ROLES[me.role] || {};
  const isAll = role.scope === 'all';
  const isCashier = me.role === 'cashier';
  const canManage = me.role === 'branch_manager' || isAll; // إنشاء/تعديل القوالب والتكليف الفردي: مدير الفرع + أدوار المركز
  const canComplete = canManage || isCashier; // إنجاز المهام من كشك الفرع: مدير الفرع، أدوار المركز، والكاشير
  const branches = myBranches || [];

  const [view, setView] = useState('checklist');
  useEffect(() => { if (isCashier && view !== 'checklist') setView('checklist'); }, [isCashier]); // eslint-disable-line
  const [branchId, setBranchId] = useState((branches[0] || {}).id || '');
  useEffect(() => {
    if (!branches.find(b => b.id === branchId)) setBranchId((branches[0] || {}).id || '');
  }, [branches, branchId]);
  const branch = branches.find(b => b.id === branchId) || null;

  const emps = (org.employees || []).filter(e => e.isActive !== false && branch && e.branchId === branch.id);
  const weekdayOf = (ds) => new Date(ds + 'T00:00:00').getDay();

  // === ١) قوالب مهام متكررة (يومية/أسبوعية) لكل فرع ===
  const templates = (ops.taskTemplates || []).filter(t => branch && t.branchId === branch.id);
  const [tplF, setTplF] = useState(null); // {id?, title, freq:'daily'|'weekly', weekdays:[], note}
  const saveTpl = async () => {
    if (!branch) return;
    if (!tplF.title) return say('أدخل عنوان المهمة', 'no');
    const rec = { id: tplF.id || uid('ttpl'), branchId: branch.id, title: tplF.title, freq: tplF.freq || 'daily', weekdays: tplF.freq === 'weekly' ? (tplF.weekdays || []) : [0, 1, 2, 3, 4, 5, 6], note: tplF.note || '', isActive: true };
    const exists = (ops.taskTemplates || []).some(t => t.id === rec.id);
    await commit(d => ({ ...d, taskTemplates: exists ? (d.taskTemplates || []).map(t => t.id === rec.id ? rec : t) : [...(d.taskTemplates || []), rec] }),
      { actionType: exists ? 'update' : 'create', targetType: 'task_template', targetId: rec.id, branchName: branch.name, title: exists ? 'عدّل قالب مهمة' : 'أضاف قالب مهمة', details: branch.name + ' — ' + rec.title });
    say('حُفظ قالب المهمة ✓'); setTplF(null);
  };
  const delTpl = async (t) => {
    if (!window.confirm('حذف قالب مهمة «' + t.title + '»؟')) return;
    await commit(d => ({ ...d, taskTemplates: (d.taskTemplates || []).filter(x => x.id !== t.id) }),
      { actionType: 'delete', targetType: 'task_template', targetId: t.id, branchName: branch.name, title: 'حذف قالب مهمة', details: t.title });
    say('حُذف القالب ✓');
  };

  // === ٢) تكليف مهمة فردية لموظف معيّن ===
  const assigns = (ops.taskAssignments || []).filter(a => branch && a.branchId === branch.id).sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1));
  const [assignF, setAssignF] = useState({ empId: '', title: '', dueDate: today(), priority: 'normal', note: '' });
  const saveAssign = async () => {
    if (!branch) return;
    const emp = emps.find(e => e.id === assignF.empId);
    if (!emp || !assignF.title) return say('اختر الموظف وأدخل عنوان المهمة', 'no');
    const rec = { id: uid('task'), branchId: branch.id, employeeId: emp.id, employeeName: emp.name, title: assignF.title, note: assignF.note || '', dueDate: assignF.dueDate || today(), priority: assignF.priority || 'normal', status: 'open', createdBy: me.id, createdByName: me.name, createdAt: nowISO() };
    await commit(d => ({ ...d, taskAssignments: [rec, ...(d.taskAssignments || [])] }),
      { actionType: 'create', targetType: 'task_assignment', targetId: rec.id, branchName: branch.name, title: 'تكليف مهمة فردية', details: emp.name + ' — ' + rec.title });
    say('أُسندت المهمة ✓'); setAssignF({ empId: '', title: '', dueDate: today(), priority: 'normal', note: '' });
  };
  // v26.1 — تعديل مهمة فردية مفتوحة
  const [editA, setEditA] = useState(null);
  const saveEditA = async () => {
    const f = editA; if (!f) return;
    if (!String(f.title || '').trim()) return say('عنوان المهمة مطلوب', 'no');
    await commit(d => ({ ...d, taskAssignments: (d.taskAssignments || []).map(x => x.id === f.id ? { ...x, title: f.title.trim(), dueDate: f.dueDate || x.dueDate, priority: f.priority || 'normal', note: f.note || '', updatedAt: nowISO(), updatedByName: me.name } : x) }),
      { actionType: 'update', targetType: 'task_assignment', targetId: f.id, branchName: branch ? branch.name : '', title: 'عدّل مهمة فردية', details: f.title });
    setEditA(null); say('حُدِّثت المهمة ✓');
  };
  const cancelAssign = async (a) => {
    if (!window.confirm('إلغاء المهمة «' + a.title + '»؟')) return;
    await commit(d => ({ ...d, taskAssignments: (d.taskAssignments || []).filter(x => x.id !== a.id) }),
      { actionType: 'delete', targetType: 'task_assignment', targetId: a.id, branchName: branch.name, title: 'إلغاء مهمة فردية', details: a.title });
    say('أُلغيت المهمة');
  };

  // === ٣) قائمة المهام من كشك الفرع (جهاز مشترك) — اختيار موظف ثم إنجاز مهامه ===
  const [empId, setEmpId] = useState('');
  useEffect(() => { if (!emps.find(e => e.id === empId)) setEmpId(''); }, [emps, empId]); // eslint-disable-line
  const chkEmp = emps.find(e => e.id === empId) || null;
  const dueTemplatesToday = branch ? templates.filter(t => t.isActive !== false && (t.freq === 'daily' || (t.weekdays || []).includes(weekdayOf(today())))) : [];
  const completionsToday = (ops.taskCompletions || []).filter(c => c.employeeId === empId && c.date === today());
  const isTplDone = (tplId) => completionsToday.some(c => c.templateId === tplId);
  const openIndivToday = chkEmp ? assigns.filter(a => a.employeeId === chkEmp.id && a.status === 'open' && a.dueDate <= today()) : [];
  const toggleTpl = async (t) => {
    if (!chkEmp || !branch) return;
    if (isTplDone(t.id)) {
      await commit(d => ({ ...d, taskCompletions: (d.taskCompletions || []).filter(c => !(c.templateId === t.id && c.employeeId === chkEmp.id && c.date === today())) }),
        { actionType: 'update', targetType: 'task_completion', targetId: t.id, branchName: branch.name, title: 'إلغاء إنجاز مهمة متكررة', details: chkEmp.name + ' — ' + t.title });
    } else {
      const rec = { id: uid('tcomp'), templateId: t.id, branchId: branch.id, employeeId: chkEmp.id, employeeName: chkEmp.name, date: today(), doneAt: nowISO(), doneBy: me.id, doneByName: me.name };
      await commit(d => ({ ...d, taskCompletions: [rec, ...(d.taskCompletions || [])] }),
        { actionType: 'create', targetType: 'task_completion', targetId: rec.id, branchName: branch.name, title: 'إنجاز مهمة متكررة', details: chkEmp.name + ' — ' + t.title });
    }
  };
  const doneIndiv = async (a) => {
    if (!branch) return;
    await commit(d => ({ ...d, taskAssignments: (d.taskAssignments || []).map(x => x.id === a.id ? { ...x, status: 'done', doneAt: nowISO(), doneBy: me.id, doneByName: me.name } : x) }),
      { actionType: 'update', targetType: 'task_assignment', targetId: a.id, branchName: branch.name, title: 'إنجاز مهمة فردية', details: a.employeeName + ' — ' + a.title });
    say('أُنجزت المهمة ✓');
  };

  // === ٤) تقرير الالتزام بالمهام لكل موظف/فرع ===
  const [repFrom, setRepFrom] = useState(today());
  const [repTo, setRepTo] = useState(today());
  const dateRange = () => {
    const arr = []; let d = repFrom;
    while (d <= repTo && arr.length < 62) { arr.push(d); const nd = new Date(d + 'T00:00:00'); nd.setDate(nd.getDate() + 1); d = nd.toISOString().slice(0, 10); }
    return arr;
  };
  const dates = dateRange();
  const reportRows = emps.map(e => {
    let expected = 0, done = 0;
    dates.forEach(ds => {
      const wd = weekdayOf(ds);
      templates.filter(t => t.isActive !== false && (t.freq === 'daily' || (t.weekdays || []).includes(wd))).forEach(t => {
        expected++;
        if ((ops.taskCompletions || []).some(c => c.templateId === t.id && c.employeeId === e.id && c.date === ds)) done++;
      });
    });
    const indiv = assigns.filter(a => a.employeeId === e.id && a.dueDate >= repFrom && a.dueDate <= repTo);
    const indivDone = indiv.filter(a => a.status === 'done').length;
    const totalExpected = expected + indiv.length;
    const totalDone = done + indivDone;
    const pct = totalExpected ? Math.round((totalDone / totalExpected) * 100) : null;
    return { e, expected: totalExpected, done: totalDone, pct };
  });

  if (!branch && branches.length === 0) {
    return <div className="card"><div className="empty">لا يوجد فرع مُسند لحسابك — راجع مسؤول النظام.</div></div>;
  }

  return (
    <div className="grid" style={{ gap: 12 }}>
      {!isCashier && (
        <div className="card" style={{ padding: '8px 12px' }}>
          <div className="row" style={{ gap: 6, flexWrap: 'wrap', justifyContent: 'space-between' }}>
            <div className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
              <button className={'btn sm' + (view === 'templates' ? ' pri' : ' gh')} onClick={() => setView('templates')}><CheckCircle2 size={13} />قوالب المهام المتكررة</button>
              <button className={'btn sm' + (view === 'assign' ? ' pri' : ' gh')} onClick={() => setView('assign')}><Send size={13} />تكليف فردي</button>
              <button className={'btn sm' + (view === 'checklist' ? ' pri' : ' gh')} onClick={() => setView('checklist')}><UserCog size={13} />إنجاز المهام</button>
              <button className={'btn sm' + (view === 'report' ? ' pri' : ' gh')} onClick={() => setView('report')}><FileBarChart size={13} />تقرير الالتزام</button>
            </div>
            {branches.length > 1 && (
              <select className="inp sel" style={{ width: 180 }} value={branchId} onChange={e => setBranchId(e.target.value)}>
                {branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
              </select>
            )}
          </div>
        </div>
      )}

      {view === 'templates' && branch && (
        <div className="card">
          <div className="card-h" style={{ marginBottom: 8 }}>
            <div className="card-t"><CheckCircle2 size={15} color="var(--brass)" />قوالب المهام المتكررة — {branch.name}</div>
            {canManage && <button className="btn sm pri" onClick={() => setTplF({ title: '', freq: 'daily', weekdays: [], note: '' })}><Plus size={13} />قالب جديد</button>}
          </div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>العنوان</th><th>التكرار</th><th>الأيام</th><th>ملاحظة</th>{canManage && <th />}</tr></thead>
              <tbody>
                {templates.map(t => (
                  <tr key={t.id}>
                    <td style={{ fontWeight: 600, fontSize: 12.5 }}>{t.title}</td>
                    <td><span className="badge b-dim">{t.freq === 'weekly' ? 'أسبوعي' : 'يومي'}</span></td>
                    <td style={{ fontSize: 11 }}>{t.freq === 'weekly' ? (t.weekdays || []).map(d => HR_WEEK_DAYS.find(x => x.v === d)?.ar.slice(0, 3)).join('، ') : 'كل يوم'}</td>
                    <td style={{ fontSize: 12 }}>{t.note || '—'}</td>
                    {canManage && <td>
                      <div className="row" style={{ gap: 5, justifyContent: 'flex-end' }}>
                        <button className="btn sm gh" onClick={() => setTplF({ ...t })}>تعديل</button>
                        <button className="btn sm gh" onClick={() => delTpl(t)}><Trash2 size={13} /></button>
                      </div>
                    </td>}
                  </tr>
                ))}
                {templates.length === 0 && <tr><td colSpan={canManage ? 5 : 4}><div className="empty">لا توجد قوالب مهام لهذا الفرع بعد.</div></td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {editA && (
        <Modal title="تعديل مهمة فردية" icon={Send} onClose={() => setEditA(null)}
          foot={<><button className="btn gh" onClick={() => setEditA(null)}>إلغاء</button><button className="btn pri" onClick={saveEditA}><Check size={14} />حفظ</button></>}>
          <div className="grid" style={{ gap: 10 }}>
            <Field label="عنوان المهمة"><input className="inp" autoFocus value={editA.title} onChange={e => setEditA(f => ({ ...f, title: e.target.value }))} /></Field>
            <div className="grid g2">
              <Field label="تاريخ الاستحقاق"><input type="date" className="inp" value={editA.dueDate} onChange={e => setEditA(f => ({ ...f, dueDate: e.target.value }))} /></Field>
              <Field label="الأولوية"><select className="inp sel" value={editA.priority} onChange={e => setEditA(f => ({ ...f, priority: e.target.value }))}><option value="normal">عادية</option><option value="high">عاجلة</option></select></Field>
            </div>
            <Field label="ملاحظة"><input className="inp" value={editA.note} onChange={e => setEditA(f => ({ ...f, note: e.target.value }))} /></Field>
          </div>
        </Modal>
      )}
      {tplF && (
        <Modal title={tplF.id ? 'تعديل قالب مهمة' : 'قالب مهمة جديد'} icon={CheckCircle2} onClose={() => setTplF(null)}
          foot={<>
            <button className="btn gh" onClick={() => setTplF(null)}>إلغاء</button>
            <button className="btn pri" onClick={saveTpl}><Check size={14} />حفظ</button>
          </>}>
          <div className="grid" style={{ gap: 10 }}>
            <Field label="عنوان المهمة">
              <input className="inp" autoFocus value={tplF.title} onChange={e => setTplF(f => ({ ...f, title: e.target.value }))} placeholder="تنظيف صالة العملاء" />
            </Field>
            <Field label="التكرار">
              <select className="inp sel" value={tplF.freq} onChange={e => setTplF(f => ({ ...f, freq: e.target.value }))}>
                <option value="daily">يومي (كل يوم)</option>
                <option value="weekly">أسبوعي (أيام محدَّدة)</option>
              </select>
            </Field>
            {tplF.freq === 'weekly' && (
              <Field label="أيام التكرار">
                <div className="row" style={{ gap: 10, flexWrap: 'wrap' }}>
                  {HR_WEEK_DAYS.map(d => (
                    <label key={d.v} className="row" style={{ gap: 5, fontSize: 12.5, cursor: 'pointer' }}>
                      <input type="checkbox" checked={(tplF.weekdays || []).includes(d.v)}
                        onChange={e => setTplF(f => ({ ...f, weekdays: e.target.checked ? [...(f.weekdays || []), d.v] : (f.weekdays || []).filter(x => x !== d.v) }))} />
                      {d.ar}
                    </label>
                  ))}
                </div>
              </Field>
            )}
            <Field label="ملاحظة (اختياري)">
              <input className="inp" value={tplF.note} onChange={e => setTplF(f => ({ ...f, note: e.target.value }))} />
            </Field>
          </div>
        </Modal>
      )}

      {view === 'assign' && branch && (
        <div className="grid" style={{ gap: 12 }}>
          {canManage && (
            <div className="card">
              <div className="card-t" style={{ marginBottom: 8 }}><Send size={15} color="var(--brass)" />تكليف مهمة فردية لموظف معيّن</div>
              <div className="grid g3">
                <Field label="الموظف"><select className="inp sel" value={assignF.empId} onChange={e => setAssignF(f => ({ ...f, empId: e.target.value }))}><option value="">اختر</option>{emps.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}</select></Field>
                <Field label="عنوان المهمة"><input className="inp" value={assignF.title} onChange={e => setAssignF(f => ({ ...f, title: e.target.value }))} /></Field>
                <Field label="تاريخ الاستحقاق"><input type="date" className="inp" value={assignF.dueDate} onChange={e => setAssignF(f => ({ ...f, dueDate: e.target.value }))} /></Field>
                <Field label="الأولوية">
                  <select className="inp sel" value={assignF.priority} onChange={e => setAssignF(f => ({ ...f, priority: e.target.value }))}>
                    <option value="normal">عادية</option>
                    <option value="high">عاجلة</option>
                  </select>
                </Field>
                <Field label="ملاحظة (اختياري)"><input className="inp" value={assignF.note} onChange={e => setAssignF(f => ({ ...f, note: e.target.value }))} /></Field>
              </div>
              <div className="row" style={{ justifyContent: 'flex-end', marginTop: 10 }}>
                <button className="btn pri" onClick={saveAssign}><Send size={14} />إسناد المهمة</button>
              </div>
            </div>
          )}
          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}>المهام الفردية — {branch.name}</div>
            <div className="tw">
              <table className="tb">
                <thead><tr><th>الموظف</th><th>العنوان</th><th>الاستحقاق</th><th>الأولوية</th><th>الحالة</th>{canManage && <th />}</tr></thead>
                <tbody>
                  {assigns.map(a => (
                    <tr key={a.id}>
                      <td style={{ fontWeight: 600, fontSize: 12.5 }}>{a.employeeName}</td>
                      <td style={{ fontSize: 12.5 }}>{a.title}</td>
                      <td className="num">{a.dueDate}</td>
                      <td><span className={'badge ' + (a.priority === 'high' ? 'b-rose' : 'b-dim')}>{a.priority === 'high' ? 'عاجلة' : 'عادية'}</span></td>
                      <td><span className={'badge ' + (a.status === 'done' ? 'b-mint' : 'b-amber')}>{a.status === 'done' ? 'منجزة' : 'مفتوحة'}</span></td>
                      {canManage && <td>
                        {a.status !== 'done' && <div className="row" style={{ gap: 5, justifyContent: 'flex-end' }}>
                          <button className="btn sm gh" onClick={() => setEditA({ id: a.id, title: a.title, dueDate: a.dueDate, priority: a.priority || 'normal', note: a.note || '' })}>تعديل</button>
                          <button className="btn sm gh" onClick={() => cancelAssign(a)}><Trash2 size={13} /></button>
                        </div>}
                      </td>}
                    </tr>
                  ))}
                  {assigns.length === 0 && <tr><td colSpan={canManage ? 6 : 5}><div className="empty">لا توجد مهام فردية بعد.</div></td></tr>}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {view === 'checklist' && branch && (
        <div className="grid" style={{ gap: 12 }}>
          <div className="card">
            <Field label="الموظف">
              <select className="inp sel" value={empId} onChange={e => setEmpId(e.target.value)}>
                <option value="">اختر الموظف</option>
                {emps.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}
              </select>
            </Field>
          </div>
          {chkEmp && (
            <>
              <div className="card">
                <div className="card-t" style={{ marginBottom: 8 }}>مهام اليوم المتكررة — {chkEmp.name}</div>
                <div className="grid" style={{ gap: 6 }}>
                  {dueTemplatesToday.map(t => (
                    <label key={t.id} className="row" style={{ gap: 8, justifyContent: 'space-between', padding: '7px 10px', border: '1px solid var(--line)', borderRadius: 10, cursor: canComplete ? 'pointer' : 'default' }}>
                      <span className="row" style={{ gap: 8 }}>
                        <input type="checkbox" checked={isTplDone(t.id)} disabled={!canComplete} onChange={() => canComplete && toggleTpl(t)} />
                        {t.title}
                      </span>
                      {isTplDone(t.id) && <span className="badge b-mint">منجزة</span>}
                    </label>
                  ))}
                  {dueTemplatesToday.length === 0 && <div className="empty">لا توجد مهام متكررة مستحقة اليوم لهذا الفرع.</div>}
                </div>
              </div>
              <div className="card">
                <div className="card-t" style={{ marginBottom: 8 }}>مهام فردية مستحقة</div>
                <div className="grid" style={{ gap: 6 }}>
                  {openIndivToday.map(a => (
                    <div key={a.id} className="row" style={{ gap: 8, justifyContent: 'space-between', padding: '7px 10px', border: '1px solid var(--line)', borderRadius: 10 }}>
                      <span style={{ fontSize: 12.5 }}>{a.title} {a.priority === 'high' && <span className="badge b-rose" style={{ marginInlineStart: 6 }}>عاجلة</span>}</span>
                      {canComplete && <button className="btn sm pri" onClick={() => doneIndiv(a)}><Check size={13} />إنجاز</button>}
                    </div>
                  ))}
                  {openIndivToday.length === 0 && <div className="empty">لا توجد مهام فردية مفتوحة ومستحقة لهذا الموظف.</div>}
                </div>
              </div>
            </>
          )}
        </div>
      )}

      {view === 'report' && branch && (
        <div className="card">
          <div className="card-h" style={{ marginBottom: 8 }}>
            <div className="card-t"><FileBarChart size={15} color="var(--brass)" />تقرير الالتزام بالمهام — {branch.name}</div>
            <div className="row" style={{ gap: 8 }}>
              <input type="date" className="inp" value={repFrom} onChange={e => setRepFrom(e.target.value)} />
              <input type="date" className="inp" value={repTo} onChange={e => setRepTo(e.target.value)} />
            </div>
          </div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>الموظف</th><th>المهام المستحقة</th><th>المُنجزة</th><th>نسبة الالتزام</th></tr></thead>
              <tbody>
                {reportRows.map(r => (
                  <tr key={r.e.id}>
                    <td style={{ fontWeight: 600, fontSize: 12.5 }}>{r.e.name}</td>
                    <td className="num">{r.expected}</td>
                    <td className="num">{r.done}</td>
                    <td><span className={'badge ' + (r.pct == null ? 'b-dim' : r.pct >= 90 ? 'b-mint' : r.pct >= 70 ? 'b-amber' : 'b-rose')}>{r.pct == null ? '—' : r.pct + '%'}</span></td>
                  </tr>
                ))}
                {reportRows.length === 0 && <tr><td colSpan={4}><div className="empty">لا يوجد موظفون نشطون لهذا الفرع.</div></td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

function PointsLedger({ org, ops, me, myBranches, commit, commitOrg, say }) {
  const role = ROLES[me.role] || {};
  const isAll = role.scope === 'all';
  const isCashier = me.role === 'cashier';
  const canManage = me.role === 'branch_manager' || isAll; // حركات يدوية: مدير الفرع + أدوار المركز
  const canRules = isAll; // قواعد النقاط التلقائية سياسة على مستوى الشركة: أدوار المركز فقط
  const branches = myBranches || [];
  const policies = { ...defaultHrPolicies(), ...(org.hrPolicies || {}) };
  const tolerance = Number(policies.lateToleranceMinutes) || 0;
  const rules = { ...defaultPointsRules(), ...(org.pointsRules || {}) };

  const [view, setView] = useState(isCashier ? 'kiosk' : 'ledger');
  useEffect(() => { if (isCashier && view !== 'kiosk') setView('kiosk'); }, [isCashier]); // eslint-disable-line
  const [branchId, setBranchId] = useState((branches[0] || {}).id || '');
  useEffect(() => {
    if (!branches.find(b => b.id === branchId)) setBranchId((branches[0] || {}).id || '');
  }, [branches, branchId]);
  const branch = branches.find(b => b.id === branchId) || null;
  const branchIds = branches.map(b => b.id);
  const emps = (org.employees || []).filter(e => e.isActive !== false && branch && e.branchId === branch.id);

  const addDays = (ds, n) => { const d = new Date(ds + 'T00:00:00'); d.setDate(d.getDate() + n); return d.toISOString().slice(0, 10); };
  const parseHM = (t) => { const [h, m] = String(t || '00:00').split(':').map(Number); return (h || 0) * 60 + (m || 0); };
  const [ym, setYm] = useState(() => today().slice(0, 7));
  const monthFrom = ym + '-01';
  const monthTo = ym + '-31';

  // === النقاط التلقائية (مُشتقّة، لا تُخزَّن — نفس فلسفة buildAccounting) من م٣/م٤/م٥ ===
  const autoFor = (emp, from, to) => {
    const c = { onTime: 0, late: 0, absent: 0, tasks: 0 };
    (ops.shiftAssignments || []).filter(a => a.empId === emp.id).forEach(a => {
      (a.shiftIds || []).forEach((sid, di) => {
        if (!sid) return;
        const ds = addDays(a.weekStart, di);
        if (ds < from || ds > to || ds > today()) return;
        const tpl = (ops.shiftTemplates || []).find(t => t.id === sid);
        const evs = (ops.attendanceEvents || []).filter(ev => ev.employeeId === emp.id && (ev.at || '').slice(0, 10) === ds).sort((x, y) => (x.at < y.at ? -1 : 1));
        const inEv = evs.find(ev => ev.type === 'in');
        if (!inEv) { if (ds < today()) c.absent++; return; }
        const inMin = new Date(inEv.at).getHours() * 60 + new Date(inEv.at).getMinutes();
        const lateBy = tpl ? inMin - parseHM(tpl.startTime) - tolerance : 0;
        if (lateBy > 0) c.late++; else c.onTime++;
      });
    });
    c.tasks = (ops.taskCompletions || []).filter(x => x.employeeId === emp.id && x.date >= from && x.date <= to).length
      + (ops.taskAssignments || []).filter(x => x.employeeId === emp.id && x.status === 'done' && (x.doneAt || '').slice(0, 10) >= from && (x.doneAt || '').slice(0, 10) <= to).length;
    const pts = rules.enabled ? c.onTime * Number(rules.onTime || 0) + c.late * Number(rules.late || 0) + c.absent * Number(rules.absent || 0) + c.tasks * Number(rules.taskDone || 0) : 0;
    return { ...c, pts };
  };
  const manualFor = (emp, from, to) => (ops.pointsEntries || []).filter(x => x.employeeId === emp.id && x.date >= from && x.date <= to).reduce((s, x) => s + Number(x.points || 0), 0);
  const ALL_FROM = '0000-00-00', ALL_TO = '9999-99-99';
  const balanceOf = (emp) => manualFor(emp, ALL_FROM, ALL_TO) + autoFor(emp, ALL_FROM, ALL_TO).pts;

  // === ١) حركات يدوية ===
  const [entF, setEntF] = useState({ empId: '', points: '', reason: '', date: today() });
  const entries = (ops.pointsEntries || []).filter(x => branchIds.includes(x.branchId)).sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1));
  const saveEntry = async () => {
    if (!branch) return;
    const emp = emps.find(e => e.id === entF.empId);
    const pts = Number(entF.points);
    if (!emp || !pts || !entF.reason) return say('اختر الموظف وأدخل عدد النقاط (موجب أو سالب) والسبب', 'no');
    const rec = { id: uid('pt'), branchId: branch.id, employeeId: emp.id, employeeName: emp.name, date: entF.date || today(), points: pts, reason: entF.reason, source: 'manual', createdBy: me.id, createdByName: me.name, createdAt: nowISO() };
    await commit(d => ({ ...d, pointsEntries: [rec, ...(d.pointsEntries || [])] }),
      { actionType: 'create', targetType: 'points_entry', targetId: rec.id, branchName: branch.name, title: pts > 0 ? 'إضافة نقاط لموظف' : 'خصم نقاط من موظف', details: emp.name + ': ' + (pts > 0 ? '+' : '') + pts + ' — ' + rec.reason });
    say('سُجِّلت الحركة ✓'); setEntF({ empId: '', points: '', reason: '', date: today() });
  };
  const delEntry = async (x) => {
    if (!window.confirm('حذف حركة النقاط «' + x.reason + '» (' + x.points + ') لـ' + x.employeeName + '؟')) return;
    await commit(d => ({ ...d, pointsEntries: (d.pointsEntries || []).filter(y => y.id !== x.id) }),
      { actionType: 'delete', targetType: 'points_entry', targetId: x.id, branchName: branch ? branch.name : '', title: 'حذف حركة نقاط', details: x.employeeName + ': ' + x.points });
    say('حُذفت الحركة');
  };

  // === ٢) قواعد النقاط التلقائية ===
  const [rulesF, setRulesF] = useState(rules);
  const saveRules = async () => {
    const rec = { enabled: !!rulesF.enabled, onTime: Number(rulesF.onTime) || 0, late: Number(rulesF.late) || 0, absent: Number(rulesF.absent) || 0, taskDone: Number(rulesF.taskDone) || 0 };
    await commitOrg(d => ({ ...d, pointsRules: rec }),
      { actionType: 'update', targetType: 'points_rules', targetId: 'pointsRules', title: 'تعديل قواعد النقاط التلقائية', details: (rec.enabled ? 'مفعَّلة' : 'مُعطَّلة') + ' — حضور ' + rec.onTime + ' / تأخير ' + rec.late + ' / غياب ' + rec.absent + ' / مهمة ' + rec.taskDone });
    say('حُفظت قواعد النقاط ✓');
  };

  // === ٣) لوحة الترتيب الشهرية ===
  const [boardScope, setBoardScope] = useState('branch');
  const boardEmps = boardScope === 'all' ? (org.employees || []).filter(e => e.isActive !== false && branchIds.includes(e.branchId)) : emps;
  const boardRows = boardEmps.map(e => {
    const auto = autoFor(e, monthFrom, monthTo);
    const manual = manualFor(e, monthFrom, monthTo);
    return { e, auto, manual, total: manual + auto.pts, branchName: ((org.branches || []).find(b => b.id === e.branchId) || {}).name || '' };
  }).sort((a, b) => b.total - a.total);

  // === ٤) كشك الفرع: رصيدي بعد PIN ===
  const [kEmpId, setKEmpId] = useState('');
  const [kPin, setKPin] = useState('');
  const [kShown, setKShown] = useState(null); // employee object after verified PIN
  const kioskCheck = async () => {
    const emp = emps.find(e => e.id === kEmpId);
    if (!emp) return say('اختر الموظف', 'no');
    if (!/^\d{4,6}$/.test(kPin)) return say('أدخل رقم PIN المكوّن من ٤ إلى ٦ أرقام', 'no');
    const hash = await sha(kPin);
    const ph = (((ops.hrPins || []).find(p => p.employeeId === emp.id)) || {}).pinHash || '';
    if (!ph || ph !== hash) { setKPin(''); return say('رقم PIN غير صحيح', 'no'); }
    setKShown(emp); setKPin('');
  };

  if (!branch && branches.length === 0) {
    return <div className="card"><div className="empty">لا يوجد فرع مُسند لحسابك — راجع مسؤول النظام.</div></div>;
  }
  const signed = (n) => (n > 0 ? '+' : '') + n;

  return (
    <div className="grid" style={{ gap: 12 }}>
      {!isCashier && (
        <div className="card" style={{ padding: '8px 12px' }}>
          <div className="row" style={{ gap: 6, flexWrap: 'wrap', justifyContent: 'space-between' }}>
            <div className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
              <button className={'btn sm' + (view === 'ledger' ? ' pri' : ' gh')} onClick={() => setView('ledger')}><Star size={13} />دفتر النقاط</button>
              {canRules && <button className={'btn sm' + (view === 'rules' ? ' pri' : ' gh')} onClick={() => setView('rules')}><Settings size={13} />قواعد النقاط</button>}
              <button className={'btn sm' + (view === 'board' ? ' pri' : ' gh')} onClick={() => setView('board')}><BarChart3 size={13} />لوحة الترتيب</button>
              <button className={'btn sm' + (view === 'kiosk' ? ' pri' : ' gh')} onClick={() => setView('kiosk')}><Fingerprint size={13} />رصيدي (كشك)</button>
            </div>
            {branches.length > 1 && (
              <select className="inp sel" style={{ width: 180 }} value={branchId} onChange={e => setBranchId(e.target.value)}>
                {branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
              </select>
            )}
          </div>
        </div>
      )}

      {view === 'ledger' && branch && (
        <div className="grid" style={{ gap: 12 }}>
          {!rules.enabled && <div className="note">قواعد النقاط التلقائية <b>مُعطَّلة</b> حاليًا — الأرصدة أدناه من الحركات اليدوية فقط. {canRules ? 'فعِّلها من «قواعد النقاط».' : 'تفعيلها من أدوار المركز.'}</div>}
          {canManage && (
            <div className="card">
              <div className="card-t" style={{ marginBottom: 8 }}><Plus size={15} color="var(--brass)" />حركة نقاط يدوية</div>
              <div className="grid g3">
                <Field label="الموظف"><select className="inp sel" value={entF.empId} onChange={e => setEntF(f => ({ ...f, empId: e.target.value }))}><option value="">اختر</option>{emps.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}</select></Field>
                <Field label="النقاط (موجب للإضافة، سالب للخصم)"><input className="inp n" inputMode="numeric" value={entF.points} onChange={e => setEntF(f => ({ ...f, points: e.target.value.replace(/[^\d-]/g, '') }))} placeholder="+5 أو -3" /></Field>
                <Field label="التاريخ"><input type="date" className="inp" value={entF.date} onChange={e => setEntF(f => ({ ...f, date: e.target.value }))} /></Field>
                <Field label="السبب (إلزامي)" style={{ gridColumn: '1 / -1' }}><input className="inp" value={entF.reason} onChange={e => setEntF(f => ({ ...f, reason: e.target.value }))} placeholder="مثال: تعامل ممتاز مع شكوى عميل" /></Field>
              </div>
              <div className="row" style={{ justifyContent: 'flex-end', marginTop: 10 }}>
                <button className="btn pri" onClick={saveEntry}><Check size={14} />تسجيل الحركة</button>
              </div>
            </div>
          )}
          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}>أرصدة النقاط — {branch.name}</div>
            <div className="tw">
              <table className="tb">
                <thead><tr><th>الموظف</th><th>يدوي</th><th>تلقائي</th><th>الرصيد</th></tr></thead>
                <tbody>
                  {emps.map(e => { const m = manualFor(e, ALL_FROM, ALL_TO); const a = autoFor(e, ALL_FROM, ALL_TO).pts; return (
                    <tr key={e.id}>
                      <td style={{ fontWeight: 600, fontSize: 12.5 }}>{e.name}</td>
                      <td className="num">{signed(m)}</td>
                      <td className="num">{signed(a)}</td>
                      <td><span className={'badge ' + (m + a > 0 ? 'b-mint' : m + a < 0 ? 'b-rose' : 'b-dim')}>{signed(m + a)}</span></td>
                    </tr>
                  ); })}
                  {emps.length === 0 && <tr><td colSpan={4}><div className="empty">لا يوجد موظفون نشطون لهذا الفرع.</div></td></tr>}
                </tbody>
              </table>
            </div>
          </div>
          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}>سجل الحركات اليدوية</div>
            <div className="tw">
              <table className="tb">
                <thead><tr><th>التاريخ</th><th>الموظف</th><th>النقاط</th><th>السبب</th><th>بواسطة</th>{canManage && <th />}</tr></thead>
                <tbody>
                  {entries.filter(x => x.branchId === branch.id).map(x => (
                    <tr key={x.id}>
                      <td className="num">{x.date}</td>
                      <td style={{ fontWeight: 600, fontSize: 12.5 }}>{x.employeeName}</td>
                      <td><span className={'badge ' + (x.points > 0 ? 'b-mint' : 'b-rose')}>{signed(x.points)}</span></td>
                      <td style={{ fontSize: 12 }}>{x.reason}</td>
                      <td style={{ fontSize: 11.5 }}>{x.createdByName}</td>
                      {canManage && <td><button className="btn sm gh" onClick={() => delEntry(x)}><Trash2 size={13} /></button></td>}
                    </tr>
                  ))}
                  {entries.filter(x => x.branchId === branch.id).length === 0 && <tr><td colSpan={canManage ? 6 : 5}><div className="empty">لا توجد حركات يدوية بعد.</div></td></tr>}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {view === 'rules' && canRules && (
        <div className="card">
          <div className="card-t" style={{ marginBottom: 8 }}><Settings size={15} color="var(--brass)" />قواعد النقاط التلقائية (على مستوى الشركة)</div>
          <div className="note" style={{ marginBottom: 10 }}>تُحسب تلقائيًا من الحضور الموثَّق (م٣) مقابل الوردية المجدولة (م٤) ومن إنجاز المهام (م٥) — بلا تخزين مزدوج، أي تعديل هنا يعيد الاحتساب فورًا لكل الفترات. تبقى مُعطَّلة حتى تفعّلها صراحةً.</div>
          <label className="row" style={{ gap: 8, marginBottom: 10, cursor: 'pointer' }}>
            <input type="checkbox" checked={!!rulesF.enabled} onChange={e => setRulesF(f => ({ ...f, enabled: e.target.checked }))} />
            <b>تفعيل النقاط التلقائية</b>
          </label>
          <div className="grid g2">
            <Field label="حضور في الوقت (لكل وردية)"><input className="inp n" value={rulesF.onTime} onChange={e => setRulesF(f => ({ ...f, onTime: e.target.value.replace(/[^\d-]/g, '') }))} /></Field>
            <Field label="تأخير (لكل وردية)"><input className="inp n" value={rulesF.late} onChange={e => setRulesF(f => ({ ...f, late: e.target.value.replace(/[^\d-]/g, '') }))} /></Field>
            <Field label="غياب عن وردية مجدولة"><input className="inp n" value={rulesF.absent} onChange={e => setRulesF(f => ({ ...f, absent: e.target.value.replace(/[^\d-]/g, '') }))} /></Field>
            <Field label="إنجاز مهمة (متكررة أو فردية)"><input className="inp n" value={rulesF.taskDone} onChange={e => setRulesF(f => ({ ...f, taskDone: e.target.value.replace(/[^\d-]/g, '') }))} /></Field>
          </div>
          <div className="row" style={{ justifyContent: 'flex-end', marginTop: 10 }}>
            <button className="btn pri" onClick={saveRules}><Check size={14} />حفظ القواعد</button>
          </div>
        </div>
      )}

      {view === 'board' && branch && (
        <div className="card">
          <div className="card-h" style={{ marginBottom: 8 }}>
            <div className="card-t"><BarChart3 size={15} color="var(--brass)" />لوحة الترتيب — {boardScope === 'all' ? 'كل فروعي' : branch.name}</div>
            <div className="row" style={{ gap: 8 }}>
              <input type="month" className="inp" value={ym} onChange={e => setYm(e.target.value)} />
              {branches.length > 1 && <select className="inp sel" value={boardScope} onChange={e => setBoardScope(e.target.value)}><option value="branch">هذا الفرع</option><option value="all">كل فروعي</option></select>}
            </div>
          </div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>#</th><th>الموظف</th>{boardScope === 'all' && <th>الفرع</th>}<th>في الوقت</th><th>تأخير</th><th>غياب</th><th>مهام</th><th>يدوي</th><th>الإجمالي</th></tr></thead>
              <tbody>
                {boardRows.map((r, i) => (
                  <tr key={r.e.id}>
                    <td className="num">{i + 1}</td>
                    <td style={{ fontWeight: 600, fontSize: 12.5 }}>{i === 0 && r.total > 0 ? '🏆 ' : ''}{r.e.name}</td>
                    {boardScope === 'all' && <td style={{ fontSize: 12 }}>{r.branchName}</td>}
                    <td className="num">{r.auto.onTime}</td>
                    <td className="num">{r.auto.late}</td>
                    <td className="num">{r.auto.absent}</td>
                    <td className="num">{r.auto.tasks}</td>
                    <td className="num">{signed(r.manual)}</td>
                    <td><span className={'badge ' + (r.total > 0 ? 'b-mint' : r.total < 0 ? 'b-rose' : 'b-dim')}>{signed(r.total)}</span></td>
                  </tr>
                ))}
                {boardRows.length === 0 && <tr><td colSpan={9}><div className="empty">لا يوجد موظفون نشطون.</div></td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {view === 'kiosk' && branch && (
        <div className="grid" style={{ gap: 12 }}>
          {!kShown ? (
            <div className="card">
              <div className="card-t" style={{ marginBottom: 8 }}><Fingerprint size={15} color="var(--brass)" />رصيدي من النقاط — {branch.name}</div>
              <div className="grid g2">
                <Field label="الموظف"><select className="inp sel" value={kEmpId} onChange={e => setKEmpId(e.target.value)}><option value="">اختر</option>{emps.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}</select></Field>
                <Field label="رقم PIN"><input className="inp n" type="password" inputMode="numeric" value={kPin} onChange={e => setKPin(e.target.value.replace(/\D/g, '').slice(0, 6))} onKeyDown={e => e.key === 'Enter' && kioskCheck()} /></Field>
              </div>
              <div className="row" style={{ justifyContent: 'flex-end', marginTop: 10 }}>
                <button className="btn pri" onClick={kioskCheck}><Eye size={14} />عرض رصيدي</button>
              </div>
            </div>
          ) : (() => { const a = autoFor(kShown, monthFrom, monthTo); const m = manualFor(kShown, monthFrom, monthTo); const bal = balanceOf(kShown); const my = (ops.pointsEntries || []).filter(x => x.employeeId === kShown.id).sort((x, y) => (x.createdAt < y.createdAt ? 1 : -1)).slice(0, 10); return (
            <div className="card">
              <div className="card-h" style={{ marginBottom: 8 }}>
                <div className="card-t"><Star size={15} color="var(--brass)" />{kShown.name}</div>
                <button className="btn sm gh" onClick={() => { setKShown(null); setKEmpId(''); }}><X size={13} />إغلاق</button>
              </div>
              <div style={{ textAlign: 'center', padding: '14px 0' }}>
                <div style={{ fontSize: 11.5, color: 'var(--muted)' }}>رصيدي الإجمالي</div>
                <div style={{ fontSize: 34, fontWeight: 800, color: bal >= 0 ? 'var(--mint)' : 'var(--rose)' }}>{signed(bal)}</div>
                <div style={{ fontSize: 12, marginTop: 6 }}>هذا الشهر: يدوي {signed(m)} · تلقائي {signed(a.pts)} (في الوقت {a.onTime} · تأخير {a.late} · غياب {a.absent} · مهام {a.tasks})</div>
              </div>
              <div className="card-t" style={{ marginBottom: 6, fontSize: 12.5 }}>آخر الحركات اليدوية</div>
              {my.length === 0 ? <div className="empty">لا توجد حركات يدوية.</div> : my.map(x => (
                <div key={x.id} className="row" style={{ justifyContent: 'space-between', padding: '6px 0', borderBottom: '1px solid var(--line)', fontSize: 12.5 }}>
                  <span>{x.date} — {x.reason}</span>
                  <span className={'badge ' + (x.points > 0 ? 'b-mint' : 'b-rose')}>{signed(x.points)}</span>
                </div>
              ))}
            </div>
          ); })()}
        </div>
      )}
    </div>
  );
}

// ===== م٧ — دوال نقيّة مشتركة لإحصاءات الموظف والدرجة المركّبة (مُشتقّة، لا تُخزَّن) =====
function hrEmpStats(org, ops, emp, from, to) {
  const policies = { ...defaultHrPolicies(), ...(org.hrPolicies || {}) };
  const tolerance = Number(policies.lateToleranceMinutes) || 0;
  const rules = { ...defaultPointsRules(), ...(org.pointsRules || {}) };
  const td = today();
  const cap = to < td ? to : td;
  const addDays = (ds, n) => { const d = new Date(ds + 'T00:00:00'); d.setDate(d.getDate() + n); return d.toISOString().slice(0, 10); };
  const parseHM = (t) => { const [h, m] = String(t || '00:00').split(':').map(Number); return (h || 0) * 60 + (m || 0); };
  const s = { onTime: 0, late: 0, absent: 0, tasksExpected: 0, tasksDone: 0, manualPts: 0, manualCount: 0, autoPts: 0 };
  (ops.shiftAssignments || []).filter(a => a.empId === emp.id).forEach(a => {
    (a.shiftIds || []).forEach((sid, di) => {
      if (!sid) return;
      const ds = addDays(a.weekStart, di);
      if (ds < from || ds > cap) return;
      const tpl = (ops.shiftTemplates || []).find(t => t.id === sid);
      const evs = (ops.attendanceEvents || []).filter(ev => ev.employeeId === emp.id && (ev.at || '').slice(0, 10) === ds).sort((x, y) => (x.at < y.at ? -1 : 1));
      const inEv = evs.find(ev => ev.type === 'in');
      if (!inEv) { if (ds < td) s.absent++; return; }
      const inMin = new Date(inEv.at).getHours() * 60 + new Date(inEv.at).getMinutes();
      const lateBy = tpl ? inMin - parseHM(tpl.startTime) - tolerance : 0;
      if (lateBy > 0) s.late++; else s.onTime++;
    });
  });
  if (from <= cap) {
    for (let ds = from, guard = 0; ds <= cap && guard < 62; ds = addDays(ds, 1), guard++) {
      const wd = new Date(ds + 'T00:00:00').getDay();
      (ops.taskTemplates || []).filter(t => t.branchId === emp.branchId && t.isActive !== false && (t.freq === 'daily' || (t.weekdays || []).includes(wd))).forEach(t => {
        s.tasksExpected++;
        if ((ops.taskCompletions || []).some(c => c.templateId === t.id && c.employeeId === emp.id && c.date === ds)) s.tasksDone++;
      });
    }
  }
  (ops.taskAssignments || []).filter(x => x.employeeId === emp.id && x.dueDate >= from && x.dueDate <= cap).forEach(x => { s.tasksExpected++; if (x.status === 'done') s.tasksDone++; });
  const manual = (ops.pointsEntries || []).filter(x => x.employeeId === emp.id && x.date >= from && x.date <= to);
  s.manualCount = manual.length;
  s.manualPts = manual.reduce((a, x) => a + Number(x.points || 0), 0);
  const taskCount = (ops.taskCompletions || []).filter(x => x.employeeId === emp.id && x.date >= from && x.date <= to).length
    + (ops.taskAssignments || []).filter(x => x.employeeId === emp.id && x.status === 'done' && (x.doneAt || '').slice(0, 10) >= from && (x.doneAt || '').slice(0, 10) <= to).length;
  s.autoPts = rules.enabled ? s.onTime * Number(rules.onTime || 0) + s.late * Number(rules.late || 0) + s.absent * Number(rules.absent || 0) + taskCount * Number(rules.taskDone || 0) : 0;
  s.pointsActivity = s.manualCount > 0 || (rules.enabled && (s.onTime + s.late + s.absent + taskCount > 0));
  return s;
}
function hrScoreFor(org, ops, emp, ym) {
  const from = ym + '-01', to = ym + '-31';
  const st = hrEmpStats(org, ops, emp, from, to);
  const policies = { ...defaultHrPolicies(), ...(org.hrPolicies || {}) };
  const w = policies.scoreWeightsEnabled ? (policies.scoreWeights || {}) : defaultHrPolicies().scoreWeights;
  const base = Number(policies.disciplineBase); const pv = Number(policies.disciplinePointValue);
  const attTotal = st.onTime + st.late + st.absent;
  const rv = (ops.qualityReviews || []).find(r => r.employeeId === emp.id && r.ym === ym) || null;
  // م١١ (v27.9): محور مؤشرات الدور — مُعطَّل افتراضيًا (roleKpiEnabled=false) فلا يغيّر أي درجة قائمة
  const rkOn = !!policies.roleKpiEnabled;
  const rkW = rkOn ? (Number(policies.roleKpiWeight) || 0) : 0;
  const axes = {
    attendance: attTotal ? Math.round(st.onTime / attTotal * 100) : null,
    tasks: st.tasksExpected ? Math.round(st.tasksDone / st.tasksExpected * 100) : null,
    discipline: st.pointsActivity ? Math.max(0, Math.min(100, Math.round((isNaN(base) ? 50 : base) + (st.manualPts + st.autoPts) * (isNaN(pv) ? 5 : pv)))) : null,
    quality: rv ? Math.round(((Number(rv.workQuality) + Number(rv.customerService) + Number(rv.teamwork)) / 3 - 1) / 4 * 100) : null,
    roleKpi: rkOn ? hrRoleKpiScore(org, ops, emp, ym).score : null,
  };
  let num = 0, den = 0;
  Object.keys(axes).forEach(k => { const wk = k === 'roleKpi' ? rkW : (Number(w[k]) || 0); if (axes[k] != null && wk > 0) { num += axes[k] * wk; den += wk; } });
  return { st, axes, score: den ? Math.round(num / den) : null, review: rv, weights: w, weightsEnabled: !!policies.scoreWeightsEnabled };
}

function Performance({ org, ops, me, myBranches, commit, commitOrg, say }) {
  const role = ROLES[me.role] || {};
  const isAll = role.scope === 'all';
  const canManage = me.role === 'branch_manager' || isAll; // تقييم المدير الشهري
  const canConfig = isAll; // الأوزان وأهداف KPI: أدوار المركز
  const branches = myBranches || [];
  const policies = { ...defaultHrPolicies(), ...(org.hrPolicies || {}) };

  const [view, setView] = useState('scores');
  const [branchId, setBranchId] = useState((branches[0] || {}).id || '');
  useEffect(() => { if (!branches.find(b => b.id === branchId)) setBranchId((branches[0] || {}).id || ''); }, [branches, branchId]);
  const branch = branches.find(b => b.id === branchId) || null;
  const emps = (org.employees || []).filter(e => e.isActive !== false && branch && e.branchId === branch.id);
  const [ym, setYm] = useState(() => today().slice(0, 7));
  const ymAdd = (y, n) => { const [Y, M] = y.split('-').map(Number); const d = new Date(Y, M - 1 + n, 1); return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0'); };
  const ymLabel = (y) => { const [Y, M] = y.split('-').map(Number); return new Date(Y, M - 1, 1).toLocaleDateString('ar', { month: 'long', year: 'numeric' }); };
  const scoreBadge = (v) => v == null ? 'b-dim' : v >= 85 ? 'b-mint' : v >= 70 ? 'b-amber' : 'b-rose';
  const fmt = (v) => v == null ? '—' : v;

  // === ١) الدرجات الشهرية ===
  const rows = emps.map(e => ({ e, ...hrScoreFor(org, ops, e, ym) }));
  const [wf, setWf] = useState({ scoreWeightsEnabled: !!policies.scoreWeightsEnabled, scoreWeights: { ...(policies.scoreWeights || {}) }, disciplineBase: policies.disciplineBase, disciplinePointValue: policies.disciplinePointValue });
  const saveWeights = async () => {
    const w = wf.scoreWeights || {};
    const sum = (Number(w.attendance) || 0) + (Number(w.quality) || 0) + (Number(w.tasks) || 0) + (Number(w.discipline) || 0);
    if (wf.scoreWeightsEnabled && sum !== 100) return say('مجموع الأوزان يجب أن يساوي 100 (الحالي ' + sum + ')', 'no');
    const patch = { scoreWeightsEnabled: !!wf.scoreWeightsEnabled, scoreWeights: { attendance: Number(w.attendance) || 0, quality: Number(w.quality) || 0, tasks: Number(w.tasks) || 0, discipline: Number(w.discipline) || 0 }, disciplineBase: Number(wf.disciplineBase) || 0, disciplinePointValue: Number(wf.disciplinePointValue) || 0 };
    await commitOrg(d => ({ ...d, hrPolicies: { ...defaultHrPolicies(), ...(d.hrPolicies || {}), ...patch } }),
      { actionType: 'update', targetType: 'settings', targetId: 'hrPolicies', title: 'ضبط أوزان درجة الأداء', details: (patch.scoreWeightsEnabled ? 'مفعَّلة' : 'مُعطَّلة') + ' — حضور ' + patch.scoreWeights.attendance + ' / جودة ' + patch.scoreWeights.quality + ' / مهام ' + patch.scoreWeights.tasks + ' / انضباط ' + patch.scoreWeights.discipline });
    say('حُفظت أوزان الدرجة ✓');
  };
  const [showW, setShowW] = useState(false);

  // === ٢) تقييم المدير الشهري ===
  const [rvEmp, setRvEmp] = useState('');
  const existing = (ops.qualityReviews || []).find(r => r.employeeId === rvEmp && r.ym === ym) || null;
  const [rvF, setRvF] = useState({ workQuality: 3, customerService: 3, teamwork: 3, note: '' });
  useEffect(() => { setRvF(existing ? { workQuality: existing.workQuality, customerService: existing.customerService, teamwork: existing.teamwork, note: existing.note || '' } : { workQuality: 3, customerService: 3, teamwork: 3, note: '' }); }, [rvEmp, ym, existing && existing.id]); // eslint-disable-line
  const saveReview = async () => {
    const emp = emps.find(e => e.id === rvEmp);
    if (!emp || !branch) return say('اختر الموظف', 'no');
    const rec = { id: existing ? existing.id : uid('qr'), branchId: branch.id, employeeId: emp.id, employeeName: emp.name, ym, workQuality: Number(rvF.workQuality), customerService: Number(rvF.customerService), teamwork: Number(rvF.teamwork), note: rvF.note || '', reviewedBy: me.id, reviewedByName: me.name, reviewedAt: nowISO() };
    await commit(d => ({ ...d, qualityReviews: existing ? (d.qualityReviews || []).map(r => r.id === rec.id ? rec : r) : [rec, ...(d.qualityReviews || [])] }),
      { actionType: existing ? 'update' : 'create', targetType: 'quality_review', targetId: rec.id, branchName: branch.name, title: 'تقييم المدير الشهري', details: emp.name + ' — ' + ym + ' (' + rec.workQuality + '/' + rec.customerService + '/' + rec.teamwork + ')' });
    say('حُفظ التقييم ✓');
  };
  const monthReviews = (ops.qualityReviews || []).filter(r => r.ym === ym && branch && r.branchId === branch.id);
  // v26.1 — حذف تقييم شهري
  const delReview = async (r) => {
    if (!window.confirm('حذف تقييم «' + r.employeeName + '» لشهر ' + r.ym + '؟ سيُستبعد محور الجودة من درجته.')) return;
    await commit(d => ({ ...d, qualityReviews: (d.qualityReviews || []).filter(x => x.id !== r.id) }),
      { actionType: 'delete', targetType: 'quality_review', targetId: r.id, branchName: r.branchName || (branch ? branch.name : ''), title: 'حذف تقييم المدير الشهري', details: r.employeeName + ' — ' + r.ym });
    say('حُذف التقييم');
  };
  const RATE = [1, 2, 3, 4, 5];
  const rateSel = (k, label) => (
    <Field label={label}>
      <select className="inp sel" value={rvF[k]} onChange={e => setRvF(f => ({ ...f, [k]: e.target.value }))}>
        {RATE.map(v => <option key={v} value={v}>{v} — {['ضعيف', 'مقبول', 'جيد', 'جيد جدًا', 'ممتاز'][v - 1]}</option>)}
      </select>
    </Field>
  );

  // === ٣) أهداف KPI للفرع مقابل الفعلي ===
  const targetsOf = (bid) => ({ onTimePct: '', taskPct: '', avgScore: '', ...(((org.kpiTargets || {})[bid]) || {}) });
  const [tgF, setTgF] = useState(() => targetsOf(branchId));
  useEffect(() => { setTgF(targetsOf(branchId)); }, [branchId, org.kpiTargets]); // eslint-disable-line
  const saveTargets = async () => {
    if (!branch) return;
    const rec = { onTimePct: Number(tgF.onTimePct) || 0, taskPct: Number(tgF.taskPct) || 0, avgScore: Number(tgF.avgScore) || 0 };
    await commitOrg(d => ({ ...d, kpiTargets: { ...(d.kpiTargets || {}), [branch.id]: rec } }),
      { actionType: 'update', targetType: 'settings', targetId: 'kpiTargets:' + branch.id, branchName: branch.name, title: 'ضبط أهداف KPI للفرع', details: branch.name + ' — حضور ' + rec.onTimePct + '% / مهام ' + rec.taskPct + '% / درجة ' + rec.avgScore });
    say('حُفظت أهداف الفرع ✓');
  };
  const branchActual = (() => {
    let on = 0, tot = 0, te = 0, tdn = 0; const scores = [];
    rows.forEach(r => { on += r.st.onTime; tot += r.st.onTime + r.st.late + r.st.absent; te += r.st.tasksExpected; tdn += r.st.tasksDone; if (r.score != null) scores.push(r.score); });
    return { onTimePct: tot ? Math.round(on / tot * 100) : null, taskPct: te ? Math.round(tdn / te * 100) : null, avgScore: scores.length ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length) : null };
  })();
  const tg = targetsOf(branchId);
  const kpiRows = [
    { k: 'onTimePct', ar: 'نسبة الحضور في الوقت', unit: '%' },
    { k: 'taskPct', ar: 'نسبة إنجاز المهام', unit: '%' },
    { k: 'avgScore', ar: 'متوسط درجة الأداء', unit: '' },
  ];

  // === ٤) بطاقة أداء الموظف (٦ أشهر + اتجاه) ===
  const [cardEmp, setCardEmp] = useState('');
  const cEmp = emps.find(e => e.id === cardEmp) || null;
  const months6 = [5, 4, 3, 2, 1, 0].map(n => ymAdd(ym, -n));
  const cardRows = cEmp ? months6.map(m => ({ m, ...hrScoreFor(org, ops, cEmp, m) })) : [];
  const withScore = cardRows.filter(r => r.score != null);
  const trend = withScore.length >= 2 ? withScore[withScore.length - 1].score - withScore[withScore.length - 2].score : null;

  if (!branch && branches.length === 0) {
    return <div className="card"><div className="empty">لا يوجد فرع مُسند لحسابك — راجع مسؤول النظام.</div></div>;
  }

  return (
    <div className="grid" style={{ gap: 12 }}>
      <div className="card" style={{ padding: '8px 12px' }}>
        <div className="row" style={{ gap: 6, flexWrap: 'wrap', justifyContent: 'space-between' }}>
          <div className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
            <button className={'btn sm' + (view === 'scores' ? ' pri' : ' gh')} onClick={() => setView('scores')}><TrendingUp size={13} />درجات الأداء</button>
            <button className={'btn sm' + (view === 'review' ? ' pri' : ' gh')} onClick={() => setView('review')}><Star size={13} />تقييم المدير</button>
            <button className={'btn sm' + (view === 'targets' ? ' pri' : ' gh')} onClick={() => setView('targets')}><BarChart3 size={13} />أهداف KPI</button>
            <button className={'btn sm' + (view === 'card' ? ' pri' : ' gh')} onClick={() => setView('card')}><FileText size={13} />بطاقة الموظف</button>
          </div>
          <div className="row" style={{ gap: 8 }}>
            <input type="month" className="inp" value={ym} onChange={e => setYm(e.target.value)} />
            {branches.length > 1 && (
              <select className="inp sel" style={{ width: 180 }} value={branchId} onChange={e => setBranchId(e.target.value)}>
                {branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
              </select>
            )}
          </div>
        </div>
      </div>

      {view === 'scores' && branch && (
        <div className="grid" style={{ gap: 12 }}>
          <div className="card">
            <div className="card-h" style={{ marginBottom: 6 }}>
              <div className="card-t"><Settings size={15} color="var(--brass)" />أوزان الدرجة النهائية {policies.scoreWeightsEnabled ? <span className="badge b-mint">مخصّصة</span> : <span className="badge b-dim">الافتراضية المتساوية (مُعطَّلة)</span>}</div>
              {canConfig && <button className="btn sm gh" onClick={() => setShowW(v => !v)}>{showW ? 'إخفاء' : 'ضبط الأوزان'}</button>}
            </div>
            <div style={{ fontSize: 12 }}>حضور {fmt(rows[0]?.weights.attendance ?? policies.scoreWeights.attendance)} · جودة {fmt(policies.scoreWeightsEnabled ? policies.scoreWeights.quality : 25)} · مهام {fmt(policies.scoreWeightsEnabled ? policies.scoreWeights.tasks : 25)} · انضباط {fmt(policies.scoreWeightsEnabled ? policies.scoreWeights.discipline : 25)} — المحاور غير المتاحة لموظف (بلا جدولة/مهام/تقييم) تُستبعد ويُعاد توزيع الوزن على الباقي.</div>
            {showW && canConfig && (
              <div style={{ marginTop: 10 }}>
                <label className="row" style={{ gap: 8, marginBottom: 8, cursor: 'pointer' }}>
                  <input type="checkbox" checked={!!wf.scoreWeightsEnabled} onChange={e => setWf(f => ({ ...f, scoreWeightsEnabled: e.target.checked }))} />
                  <b>تفعيل الأوزان المخصّصة</b> (يجب أن يكون مجموعها 100)
                </label>
                <div className="grid g3">
                  {[['attendance', 'الحضور'], ['quality', 'الجودة (تقييم المدير)'], ['tasks', 'المهام'], ['discipline', 'الانضباط (النقاط)']].map(([k, l]) => (
                    <Field key={k} label={l}><input className="inp n" inputMode="numeric" value={wf.scoreWeights[k] ?? ''} onChange={e => setWf(f => ({ ...f, scoreWeights: { ...f.scoreWeights, [k]: e.target.value.replace(/\D/g, '') } }))} /></Field>
                  ))}
                  <Field label="قاعدة محور الانضباط (0–100)"><input className="inp n" inputMode="numeric" value={wf.disciplineBase ?? ''} onChange={e => setWf(f => ({ ...f, disciplineBase: e.target.value.replace(/\D/g, '') }))} /></Field>
                  <Field label="قيمة النقطة الواحدة في محور الانضباط"><input className="inp n" inputMode="numeric" value={wf.disciplinePointValue ?? ''} onChange={e => setWf(f => ({ ...f, disciplinePointValue: e.target.value.replace(/\D/g, '') }))} /></Field>
                </div>
                <div className="row" style={{ justifyContent: 'flex-end', marginTop: 8 }}><button className="btn pri" onClick={saveWeights}><Check size={14} />حفظ الأوزان</button></div>
              </div>
            )}
          </div>
          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}><TrendingUp size={15} color="var(--brass)" />درجات الأداء — {branch.name} — {ymLabel(ym)}</div>
            <div className="tw">
              <table className="tb">
                <thead><tr><th>الموظف</th><th>الحضور</th><th>المهام</th><th>الانضباط</th><th>الجودة</th><th>الدرجة</th></tr></thead>
                <tbody>
                  {rows.map(r => (
                    <tr key={r.e.id}>
                      <td style={{ fontWeight: 600, fontSize: 12.5 }}>{r.e.name}</td>
                      <td className="num" title={r.st.onTime + ' في الوقت / ' + r.st.late + ' تأخير / ' + r.st.absent + ' غياب'}>{fmt(r.axes.attendance)}</td>
                      <td className="num" title={r.st.tasksDone + ' من ' + r.st.tasksExpected}>{fmt(r.axes.tasks)}</td>
                      <td className="num" title={'صافي النقاط ' + (r.st.manualPts + r.st.autoPts)}>{fmt(r.axes.discipline)}</td>
                      <td className="num">{fmt(r.axes.quality)}{!r.review && canManage ? <span style={{ fontSize: 10.5, color: 'var(--muted)', marginInlineStart: 4 }}>(بلا تقييم)</span> : null}</td>
                      <td><span className={'badge ' + scoreBadge(r.score)} style={{ fontWeight: 700 }}>{r.score == null ? '—' : r.score + ' / 100'}</span></td>
                    </tr>
                  ))}
                  {rows.length === 0 && <tr><td colSpan={6}><div className="empty">لا يوجد موظفون نشطون لهذا الفرع.</div></td></tr>}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {view === 'review' && branch && (
        <div className="grid" style={{ gap: 12 }}>
          {canManage && (
            <div className="card">
              <div className="card-t" style={{ marginBottom: 8 }}><Star size={15} color="var(--brass)" />تقييم المدير الشهري — {ymLabel(ym)}</div>
              <div className="grid g2">
                <Field label="الموظف"><select className="inp sel" value={rvEmp} onChange={e => setRvEmp(e.target.value)}><option value="">اختر</option>{emps.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}</select></Field>
                {rvEmp && existing && <div className="note" style={{ alignSelf: 'end' }}>يوجد تقييم محفوظ لهذا الشهر (بواسطة {existing.reviewedByName}) — الحفظ يُحدِّثه.</div>}
              </div>
              {rvEmp && (<>
                <div className="grid g3" style={{ marginTop: 8 }}>
                  {rateSel('workQuality', 'جودة العمل')}
                  {rateSel('customerService', 'التعامل مع العملاء')}
                  {rateSel('teamwork', 'العمل الجماعي')}
                </div>
                <Field label="ملاحظات (اختياري)" style={{ marginTop: 8 }}><input className="inp" value={rvF.note} onChange={e => setRvF(f => ({ ...f, note: e.target.value }))} /></Field>
                <div className="row" style={{ justifyContent: 'flex-end', marginTop: 10 }}><button className="btn pri" onClick={saveReview}><Check size={14} />حفظ التقييم</button></div>
              </>)}
            </div>
          )}
          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}>تقييمات {ymLabel(ym)} — {branch.name}</div>
            <div className="tw">
              <table className="tb">
                <thead><tr><th>الموظف</th><th>جودة العمل</th><th>العملاء</th><th>الجماعي</th><th>المتوسط</th><th>ملاحظة</th><th>بواسطة</th>{canManage && <th />}</tr></thead>
                <tbody>
                  {monthReviews.map(r => { const avg = ((Number(r.workQuality) + Number(r.customerService) + Number(r.teamwork)) / 3); return (
                    <tr key={r.id}>
                      <td style={{ fontWeight: 600, fontSize: 12.5 }}>{r.employeeName}</td>
                      <td className="num">{r.workQuality}</td><td className="num">{r.customerService}</td><td className="num">{r.teamwork}</td>
                      <td><span className={'badge ' + (avg >= 4 ? 'b-mint' : avg >= 3 ? 'b-amber' : 'b-rose')}>{avg.toFixed(1)}</span></td>
                      <td style={{ fontSize: 12 }}>{r.note || '—'}</td>
                      <td style={{ fontSize: 11.5 }}>{r.reviewedByName}</td>
                      {canManage && <td><div className="row" style={{ gap: 5, justifyContent: 'flex-end' }}><button className="btn sm gh" onClick={() => setRvEmp(r.employeeId)}>تعديل</button><button className="btn sm gh" onClick={() => delReview(r)}><Trash2 size={13} /></button></div></td>}
                    </tr>
                  ); })}
                  {monthReviews.length === 0 && <tr><td colSpan={canManage ? 8 : 7}><div className="empty">لا توجد تقييمات لهذا الشهر بعد.</div></td></tr>}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {view === 'targets' && branch && (
        <div className="grid" style={{ gap: 12 }}>
          {canConfig && (
            <div className="card">
              <div className="card-t" style={{ marginBottom: 8 }}><Settings size={15} color="var(--brass)" />أهداف KPI — {branch.name}</div>
              <div className="grid g3">
                <Field label="نسبة الحضور في الوقت المستهدفة (%)"><input className="inp n" inputMode="numeric" value={tgF.onTimePct} onChange={e => setTgF(f => ({ ...f, onTimePct: e.target.value.replace(/\D/g, '') }))} /></Field>
                <Field label="نسبة إنجاز المهام المستهدفة (%)"><input className="inp n" inputMode="numeric" value={tgF.taskPct} onChange={e => setTgF(f => ({ ...f, taskPct: e.target.value.replace(/\D/g, '') }))} /></Field>
                <Field label="متوسط درجة الأداء المستهدف (من 100)"><input className="inp n" inputMode="numeric" value={tgF.avgScore} onChange={e => setTgF(f => ({ ...f, avgScore: e.target.value.replace(/\D/g, '') }))} /></Field>
              </div>
              <div className="row" style={{ justifyContent: 'flex-end', marginTop: 10 }}><button className="btn pri" onClick={saveTargets}><Check size={14} />حفظ الأهداف</button></div>
            </div>
          )}
          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}><BarChart3 size={15} color="var(--brass)" />الفعلي مقابل المستهدف — {branch.name} — {ymLabel(ym)}</div>
            <div className="tw">
              <table className="tb">
                <thead><tr><th>المؤشر</th><th>المستهدف</th><th>الفعلي</th><th>الحالة</th></tr></thead>
                <tbody>
                  {kpiRows.map(k => { const t = Number(tg[k.k]) || 0; const a = branchActual[k.k]; const ok = a != null && t > 0 ? a >= t : null; return (
                    <tr key={k.k}>
                      <td style={{ fontWeight: 600, fontSize: 12.5 }}>{k.ar}</td>
                      <td className="num">{t > 0 ? t + k.unit : '—'}</td>
                      <td className="num">{a == null ? '—' : a + k.unit}</td>
                      <td><span className={'badge ' + (ok == null ? 'b-dim' : ok ? 'b-mint' : 'b-rose')}>{ok == null ? (t > 0 ? 'لا بيانات' : 'بلا هدف') : ok ? 'محقَّق ✓' : 'دون الهدف'}</span></td>
                    </tr>
                  ); })}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {view === 'card' && branch && (
        <div className="grid" style={{ gap: 12 }}>
          <div className="card">
            <div className="row" style={{ gap: 8, justifyContent: 'space-between', flexWrap: 'wrap' }}>
              <Field label="الموظف" style={{ minWidth: 220 }}><select className="inp sel" value={cardEmp} onChange={e => setCardEmp(e.target.value)}><option value="">اختر</option>{emps.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}</select></Field>
              {cEmp && <button className="btn sm gh" style={{ alignSelf: 'end' }} onClick={() => window.print()}><Printer size={13} />طباعة البطاقة</button>}
            </div>
          </div>
          {cEmp && (
            <div className="card">
              <div className="card-h" style={{ marginBottom: 8 }}>
                <div className="card-t"><FileText size={15} color="var(--brass)" />بطاقة أداء — {cEmp.name} — {branch.name}</div>
                {trend != null && <span className={'badge ' + (trend > 0 ? 'b-mint' : trend < 0 ? 'b-rose' : 'b-dim')}>{trend > 0 ? '▲ تحسّن +' + trend : trend < 0 ? '▼ تراجع ' + trend : '— ثابت'}</span>}
              </div>
              <div className="tw">
                <table className="tb">
                  <thead><tr><th>الشهر</th><th>الحضور</th><th>المهام</th><th>الانضباط</th><th>الجودة</th><th>الدرجة</th></tr></thead>
                  <tbody>
                    {cardRows.map(r => (
                      <tr key={r.m}>
                        <td style={{ fontSize: 12.5 }}>{ymLabel(r.m)}</td>
                        <td className="num">{fmt(r.axes.attendance)}</td>
                        <td className="num">{fmt(r.axes.tasks)}</td>
                        <td className="num">{fmt(r.axes.discipline)}</td>
                        <td className="num">{fmt(r.axes.quality)}</td>
                        <td><span className={'badge ' + scoreBadge(r.score)} style={{ fontWeight: 700 }}>{r.score == null ? '—' : r.score}</span></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              {cardRows.some(r => r.review && r.review.note) && (
                <div style={{ marginTop: 10 }}>
                  <div className="card-t" style={{ fontSize: 12.5, marginBottom: 4 }}>ملاحظات المدير</div>
                  {cardRows.filter(r => r.review && r.review.note).map(r => <div key={r.m} style={{ fontSize: 12, padding: '4px 0', borderBottom: '1px solid var(--line)' }}><b>{ymLabel(r.m)}:</b> {r.review.note} <span style={{ color: 'var(--muted)' }}>— {r.review.reviewedByName}</span></div>)}
                </div>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function Rewards({ org, ops, me, myBranches, commit, commitOrg, say }) {
  const role = ROLES[me.role] || {};
  const isAll = role.scope === 'all';
  const canRequest = me.role === 'branch_manager' || isAll;   // تسجيل طلب: مدير الفرع + أدوار المركز
  const canApprove = !!role.approver;                          // الاعتماد/الرفض: المكتب الرئيسي، مسؤول النظام، الإدارة العليا (قرار H/5: اعتماد كامل قبل أي أثر مالي)
  const canTiers = isAll;                                      // شرائح المكافآت: أدوار المركز
  const branches = myBranches || [];
  const tiersCfg = { ...defaultRewardTiers(), ...(org.rewardTiers || {}) };

  const [view, setView] = useState(canApprove ? 'queue' : 'requests');
  const [branchId, setBranchId] = useState((branches[0] || {}).id || '');
  useEffect(() => { if (!branches.find(b => b.id === branchId)) setBranchId((branches[0] || {}).id || ''); }, [branches, branchId]);
  const branch = branches.find(b => b.id === branchId) || null;
  const branchIds = branches.map(b => b.id);
  const emps = (org.employees || []).filter(e => e.isActive !== false && branch && e.branchId === branch.id);
  const [ym, setYm] = useState(() => today().slice(0, 7));
  const ymLabel = (y) => { const [Y, M] = String(y).split('-').map(Number); return isNaN(Y) ? y : new Date(Y, M - 1, 1).toLocaleDateString('ar', { month: 'long', year: 'numeric' }); };
  const kindAr = (k) => k === 'reward' ? 'مكافأة' : 'جزاء';
  const statusBadge = (st) => <span className={'badge ' + (st === 'approved' ? 'b-mint' : st === 'rejected' ? 'b-rose' : 'b-amber')}>{st === 'approved' ? 'معتمد ومُرحَّل' : st === 'rejected' ? 'مرفوض' : 'قيد الاعتماد'}</span>;
  const allReqs = (ops.rewardRequests || []).filter(r => branchIds.includes(r.branchId)).sort((a, b) => (a.requestedAt < b.requestedAt ? 1 : -1));

  // === ١) طلب مكافأة/جزاء ===
  const [f, setF] = useState({ empId: '', kind: 'reward', amount: '', reason: '', month: today().slice(0, 7) });
  const submit = async () => {
    if (!branch) return;
    const emp = emps.find(e => e.id === f.empId);
    const amt = Number(f.amount);
    if (!emp) return say('اختر الموظف', 'no');
    if (!(amt > 0)) return say('أدخل مبلغًا صحيحًا أكبر من صفر', 'no');
    if (!String(f.reason || '').trim()) return say('السبب إلزامي', 'no');
    if (!/^\d{4}-\d{2}$/.test(f.month)) return say('اختر شهر الراتب المستهدف', 'no');
    if (lockedThru(org) && f.month <= lockedThru(org)) return say(LOCK_MSG(f.month + '-01'), 'no');
    const rec = { id: uid('rw'), branchId: branch.id, branchName: branch.name, employeeId: emp.id, employeeName: emp.name, kind: f.kind, amount: Math.round(amt * 100) / 100, reason: f.reason.trim(), month: f.month, source: 'manual', status: 'pending', requestedBy: me.id, requestedByName: me.name, requestedAt: nowISO() };
    const ok = await commit(d => ({ ...d, rewardRequests: [rec, ...(d.rewardRequests || [])] }),
      { actionType: 'create', targetType: 'reward_request', targetId: rec.id, branchName: branch.name, title: 'طلب ' + kindAr(rec.kind) + ' لموظف', details: emp.name + ' · ' + money(rec.amount) + ' ر.س · ' + rec.reason + ' · شهر ' + rec.month });
    if (!ok) return;
    say('أُرسل طلب ' + kindAr(rec.kind) + ' ✓ — بانتظار الاعتماد المركزي');
    setF({ empId: '', kind: 'reward', amount: '', reason: '', month: f.month });
  };
  const cancelReq = async (r) => {
    if (r.status !== 'pending') return;
    if (!window.confirm('إلغاء طلب ' + kindAr(r.kind) + ' لـ«' + r.employeeName + '»؟')) return;
    await commit(d => ({ ...d, rewardRequests: (d.rewardRequests || []).filter(x => x.id !== r.id) }),
      { actionType: 'delete', targetType: 'reward_request', targetId: r.id, branchName: r.branchName, title: 'إلغاء طلب ' + kindAr(r.kind), details: r.employeeName + ' · ' + money(r.amount) });
    say('أُلغي الطلب');
  };

  // === ٢) الاعتماد المركزي + ٣) الترحيل التلقائي لمسيّر الرواتب ===
  const [notes, setNotes] = useState({});
  const pending = allReqs.filter(r => r.status === 'pending');
  const decided = allReqs.filter(r => r.status !== 'pending');
  const decide = async (r, approve) => {
    if (!canApprove) return;
    const note = (notes[r.id] || '').trim();
    if (approve) {
      if (lockedThru(org) && r.month <= lockedThru(org)) return say(LOCK_MSG(r.month + '-01'), 'no');
      // idempotent: إن كانت حركة الراتب موجودة من محاولة سابقة لم تكتمل، لا تُنشأ ثانية
      const existing = (ops.advances || []).find(a => a.rewardId === r.id);
      const adv = existing || {
        id: uid('ad'), rewardId: r.id, employeeId: r.employeeId, employeeName: r.employeeName, branchId: r.branchId, branchName: r.branchName,
        month: r.month, date: r.month + '-28', type: r.kind === 'reward' ? 'bonus' : 'discipline_penalty', amount: r.amount,
        reason: (r.kind === 'reward' ? 'مكافأة معتمدة' : 'جزاء معتمد') + (r.source === 'tier' ? ' (شريحة أداء)' : '') + ': ' + r.reason,
        paymentMethod: 'salary', isUnjustified: false, createdByName: me.name, createdAt: nowISO()
      };
      const ok = await commit(d => ({
        ...d,
        advances: existing ? (d.advances || []) : [adv, ...(d.advances || [])],
        rewardRequests: (d.rewardRequests || []).map(x => x.id === r.id ? { ...x, status: 'approved', decidedBy: me.id, decidedByName: me.name, decidedAt: nowISO(), decisionNote: note, advanceId: adv.id } : x),
        // م١٠ (v27.0): إشعار بالعلم يوقّعه الموظف من كشك الفرع (idempotent على refId)
        hrSignDocs: (d.hrSignDocs || []).some(x => x.refId === r.id) ? (d.hrSignDocs || []) : [rewardSignDoc(r, me), ...(d.hrSignDocs || [])]
      }), { actionType: 'approve', targetType: 'reward_request', targetId: r.id, branchName: r.branchName, title: 'اعتماد ' + kindAr(r.kind) + ' وترحيلها لمسيّر الرواتب', details: r.employeeName + ' · ' + money(r.amount) + ' ر.س · شهر ' + r.month + (note ? ' · ' + note : '') + ' · صدر إشعار للتوقيع الإلكتروني' });
      if (ok) say('اعتُمدت ' + kindAr(r.kind) + ' ورُحِّلت لمسيّر رواتب ' + r.month + ' وصدر إشعار بالعلم للتوقيع ✓');
    } else {
      if (!note) return say('اكتب سبب الرفض في الملاحظة', 'no');
      const ok = await commit(d => ({ ...d, rewardRequests: (d.rewardRequests || []).map(x => x.id === r.id ? { ...x, status: 'rejected', decidedBy: me.id, decidedByName: me.name, decidedAt: nowISO(), decisionNote: note } : x) }),
        { actionType: 'reject', targetType: 'reward_request', targetId: r.id, branchName: r.branchName, title: 'رفض طلب ' + kindAr(r.kind), details: r.employeeName + ' · ' + money(r.amount) + ' · ' + note });
      if (ok) say('رُفض الطلب');
    }
  };

  // v26.1 — التراجع عن اعتماد (إعادة الطلب إلى «قيد الاعتماد» وحذف حركة الراتب) ما دام استحقاق الشهر لم يُرحَّل للدفتر
  const revertApproval = async (r) => {
    if (!canApprove || r.status !== 'approved') return;
    const accrued = (ops.ledgerEntries || []).some(x => x.kind === 'salary_accrual' && x.month === r.month);
    if (accrued) return say('لا يمكن التراجع: استحقاق رواتب شهر ' + r.month + ' مُرحَّل للدفتر — عالجه بقيد يدوي أو طلب معاكس', 'no');
    if (lockedThru(org) && r.month <= lockedThru(org)) return say(LOCK_MSG(r.month + '-01'), 'no');
    if (!window.confirm('التراجع عن اعتماد ' + kindAr(r.kind) + ' «' + r.employeeName + '» (' + money(r.amount) + ')؟ ستُحذف حركة الراتب ويعود الطلب قيد الاعتماد.')) return;
    const ok = await commit(d => ({ ...d, advances: (d.advances || []).filter(a => a.rewardId !== r.id), rewardRequests: (d.rewardRequests || []).map(x => x.id === r.id ? { ...x, status: 'pending', decidedBy: '', decidedByName: '', decidedAt: '', decisionNote: '', advanceId: '', revertedAt: nowISO(), revertedByName: me.name } : x),
      // م١٠: إشعار التوقيع المعلّق يُحذف، والموقَّع يُعلَّم «مُلغى» (يبقى أثرًا)
      hrSignDocs: (d.hrSignDocs || []).filter(x => !(x.refId === r.id && x.status === 'pending')).map(x => (x.refId === r.id && x.status === 'signed') ? { ...x, status: 'voided', voidedAt: nowISO(), voidedByName: me.name } : x) }),
      { actionType: 'update', targetType: 'reward_request', targetId: r.id, branchName: r.branchName, title: 'التراجع عن اعتماد ' + kindAr(r.kind), details: r.employeeName + ' · ' + money(r.amount) + ' · شهر ' + r.month });
    if (ok) say('تراجعتَ عن الاعتماد — الطلب قيد الاعتماد مجددًا');
  };

  // === ٤) شرائح مكافآت تلقائية حسب درجة الأداء (م٧) ===
  const [tf, setTf] = useState({ enabled: !!tiersCfg.enabled, tiers: (tiersCfg.tiers || []).map(t => ({ minScore: String(t.minScore), amount: String(t.amount) })) });
  const saveTiers = async () => {
    const tiers = tf.tiers.map(t => ({ minScore: Number(t.minScore), amount: Number(t.amount) })).filter(t => t.minScore > 0 && t.minScore <= 100 && t.amount > 0).sort((a, b) => b.minScore - a.minScore);
    if (tf.enabled && !tiers.length) return say('أضف شريحة واحدة على الأقل (درجة من 1 إلى 100 ومبلغ أكبر من صفر)', 'no');
    const rec = { enabled: !!tf.enabled, tiers };
    const ok = await commitOrg(d => ({ ...d, rewardTiers: rec }),
      { actionType: 'update', targetType: 'settings', targetId: 'rewardTiers', title: 'ضبط شرائح المكافآت التلقائية', details: (rec.enabled ? 'مفعَّلة' : 'مُعطَّلة') + ' — ' + tiers.map(t => '≥' + t.minScore + ' ⇒ ' + t.amount).join(' · ') });
    if (ok) { say('حُفظت الشرائح ✓'); setTf({ enabled: rec.enabled, tiers: tiers.map(t => ({ minScore: String(t.minScore), amount: String(t.amount) })) }); }
  };
  const tierFor = (score) => { if (score == null) return null; return (tiersCfg.tiers || []).slice().sort((a, b) => b.minScore - a.minScore).find(t => score >= t.minScore) || null; };
  const genTier = async () => {
    if (!tiersCfg.enabled) return say('الشرائح مُعطَّلة — فعّلها واحفظها أولًا', 'no');
    if (lockedThru(org) && ym <= lockedThru(org)) return say(LOCK_MSG(ym + '-01'), 'no');
    const all = (org.employees || []).filter(e => e.isActive !== false && branchIds.includes(e.branchId));
    const recs = [];
    all.forEach(e => {
      if ((ops.rewardRequests || []).some(r => r.source === 'tier' && r.employeeId === e.id && r.month === ym)) return;
      const sc = hrScoreFor(org, ops, e, ym);
      const t = tierFor(sc.score);
      if (!t) return;
      const b = (org.branches || []).find(x => x.id === e.branchId) || {};
      recs.push({ id: uid('rw'), branchId: e.branchId, branchName: b.name || '', employeeId: e.id, employeeName: e.name, kind: 'reward', amount: t.amount, reason: 'درجة أداء ' + sc.score + '/100 ≥ ' + t.minScore + ' لشهر ' + ym, month: ym, source: 'tier', scoreSnapshot: sc.score, axesSnapshot: sc.axes, status: 'pending', requestedBy: me.id, requestedByName: me.name + ' (تلقائي)', requestedAt: nowISO() });
    });
    if (!recs.length) return say('لا مقترحات جديدة لهذا الشهر (لا درجات تبلغ الشرائح، أو المقترحات موجودة مسبقًا)', 'no');
    const ok = await commit(d => ({ ...d, rewardRequests: [...recs, ...(d.rewardRequests || [])] }),
      { actionType: 'create', targetType: 'reward_request', targetId: 'tier-' + ym, title: 'توليد مقترحات مكافآت الشرائح', details: 'شهر ' + ym + ' · ' + recs.length + ' مقترحًا' });
    if (ok) say('وُلِّد ' + recs.length + ' مقترح مكافأة لشهر ' + ym + ' — بانتظار الاعتماد ✓');
  };

  if (!branch && branches.length === 0) {
    return <div className="card"><div className="empty">لا يوجد فرع مُسند لحسابك — راجع مسؤول النظام.</div></div>;
  }

  const ReqTable = ({ rows, actions }) => (
    <div className="tw">
      <table className="tb">
        <thead><tr><th>الموظف</th>{branches.length > 1 && <th>الفرع</th>}<th>النوع</th><th>المبلغ</th><th>الشهر</th><th>السبب</th><th>الطالب</th><th>الحالة</th>{actions && <th />}</tr></thead>
        <tbody>
          {rows.map(r => (
            <tr key={r.id}>
              <td style={{ fontWeight: 600, fontSize: 12.5 }}>{r.employeeName}</td>
              {branches.length > 1 && <td style={{ fontSize: 12 }}>{r.branchName}</td>}
              <td><span className={'badge ' + (r.kind === 'reward' ? 'b-mint' : 'b-rose')}>{kindAr(r.kind)}{r.source === 'tier' ? ' · شريحة' : ''}</span></td>
              <td className="num">{money(r.amount)}</td>
              <td className="num">{r.month}</td>
              <td style={{ fontSize: 12 }}>{r.reason}{r.decisionNote ? <div style={{ fontSize: 11, color: 'var(--muted)' }}>قرار: {r.decisionNote} — {r.decidedByName}</div> : null}</td>
              <td style={{ fontSize: 11.5 }}>{r.requestedByName}</td>
              <td>{statusBadge(r.status)}{r.status === 'approved' && (() => { const sd = (ops.hrSignDocs || []).find(x => x.refId === r.id); return sd ? <div style={{ marginTop: 3 }}><span className={'badge ' + (sd.status === 'signed' ? 'b-mint' : sd.status === 'voided' ? 'b-dim' : 'b-amber')} style={{ fontSize: 9.5 }}><PenLine size={10} />{sd.status === 'signed' ? 'وقّع بالعلم' : sd.status === 'voided' ? 'إشعار مُلغى' : 'بانتظار توقيع الموظف'}</span></div> : null; })()}</td>
              {actions && <td>{actions(r)}</td>}
            </tr>
          ))}
          {rows.length === 0 && <tr><td colSpan={9}><div className="empty">لا توجد طلبات.</div></td></tr>}
        </tbody>
      </table>
    </div>
  );

  return (
    <div className="grid" style={{ gap: 12 }}>
      <div className="card" style={{ padding: '8px 12px' }}>
        <div className="row" style={{ gap: 6, flexWrap: 'wrap', justifyContent: 'space-between' }}>
          <div className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
            <button className={'btn sm' + (view === 'requests' ? ' pri' : ' gh')} onClick={() => setView('requests')}><Coins size={13} />الطلبات</button>
            {canApprove && <button className={'btn sm' + (view === 'queue' ? ' pri' : ' gh')} onClick={() => setView('queue')}><ShieldCheck size={13} />قائمة الاعتماد{pending.length ? <span className="badge b-amber" style={{ marginInlineStart: 6 }}>{pending.length}</span> : null}</button>}
            {canTiers && <button className={'btn sm' + (view === 'tiers' ? ' pri' : ' gh')} onClick={() => setView('tiers')}><TrendingUp size={13} />شرائح المكافآت</button>}
          </div>
          {branches.length > 1 && (
            <select className="inp sel" style={{ width: 180 }} value={branchId} onChange={e => setBranchId(e.target.value)}>
              {branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
            </select>
          )}
        </div>
      </div>

      {view === 'requests' && branch && (
        <div className="grid" style={{ gap: 12 }}>
          {canRequest && (
            <div className="card">
              <div className="card-t" style={{ marginBottom: 8 }}><Coins size={15} color="var(--brass)" />طلب مكافأة أو جزاء — {branch.name}</div>
              <div className="note" style={{ marginBottom: 8 }}>الطلب لا يُنتج أي أثر مالي حتى يعتمده المكتب الرئيسي؛ بعد الاعتماد يُرحَّل تلقائيًا إلى مسيّر رواتب الشهر المحدَّد (المكافأة تُضاف للإجمالي، والجزاء يُخصم).</div>
              <div className="grid g3">
                <Field label="الموظف"><select className="inp sel" value={f.empId} onChange={e => setF(x => ({ ...x, empId: e.target.value }))}><option value="">اختر</option>{emps.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}</select></Field>
                <Field label="النوع"><select className="inp sel" value={f.kind} onChange={e => setF(x => ({ ...x, kind: e.target.value }))}><option value="reward">مكافأة (تُضاف للراتب)</option><option value="penalty">جزاء (يُخصم من الراتب)</option></select></Field>
                <Field label="المبلغ (ر.س)"><input className="inp n" inputMode="decimal" value={f.amount} onChange={e => setF(x => ({ ...x, amount: e.target.value.replace(/[^\d.]/g, '') }))} /></Field>
                <Field label="شهر الراتب المستهدف"><input type="month" className="inp" value={f.month} onChange={e => setF(x => ({ ...x, month: e.target.value }))} /></Field>
                <Field label="السبب (إلزامي)" style={{ gridColumn: 'span 2' }}><input className="inp" value={f.reason} onChange={e => setF(x => ({ ...x, reason: e.target.value }))} placeholder="مثال: تغطية وردية إضافية في موسم الذروة" /></Field>
              </div>
              <div className="row" style={{ justifyContent: 'flex-end', marginTop: 10 }}><button className="btn pri" onClick={submit}><Send size={14} />إرسال الطلب للاعتماد</button></div>
            </div>
          )}
          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}>طلبات {branch.name}</div>
            <ReqTable rows={allReqs.filter(r => r.branchId === branch.id)} actions={canRequest ? (r) => (r.status === 'pending' && (r.requestedBy === me.id || isAll) ? <button className="btn sm gh" onClick={() => cancelReq(r)}><Trash2 size={13} />إلغاء</button> : null) : null} />
          </div>
        </div>
      )}

      {view === 'queue' && canApprove && (
        <div className="grid" style={{ gap: 12 }}>
          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}><ShieldCheck size={15} color="var(--brass)" />قائمة الاعتماد — {pending.length} طلب قيد الانتظار (كل فروعي)</div>
            <div className="note" style={{ marginBottom: 8 }}>الاعتماد يُرحِّل الطلب فورًا إلى مسيّر رواتب الشهر المحدَّد كحركة «مكافأة معتمدة» أو «جزاء معتمد» — لا يمكن اعتماد طلب لشهر مقفل محاسبيًا.</div>
            <ReqTable rows={pending} actions={(r) => (
              <div className="grid" style={{ gap: 5, minWidth: 180 }}>
                <input className="inp" placeholder="ملاحظة القرار (إلزامية للرفض)" value={notes[r.id] || ''} onChange={e => setNotes(n => ({ ...n, [r.id]: e.target.value }))} />
                <div className="row" style={{ gap: 5, justifyContent: 'flex-end' }}>
                  <button className="btn sm pri" onClick={() => decide(r, true)}><Check size={13} />اعتماد وترحيل</button>
                  <button className="btn sm gh" onClick={() => decide(r, false)}><X size={13} />رفض</button>
                </div>
              </div>
            )} />
          </div>
          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}>سجل القرارات</div>
            <ReqTable rows={decided} actions={(r) => (r.status === 'approved' ? <button className="btn sm gh" title="التراجع عن الاعتماد" onClick={() => revertApproval(r)}><X size={13} />تراجع</button> : null)} />
          </div>
        </div>
      )}

      {view === 'tiers' && canTiers && (
        <div className="card">
          <div className="card-t" style={{ marginBottom: 6 }}><TrendingUp size={15} color="var(--brass)" />شرائح المكافآت التلقائية حسب درجة الأداء {tiersCfg.enabled ? <span className="badge b-mint">مفعَّلة</span> : <span className="badge b-dim">مُعطَّلة</span>}</div>
          <div className="note" style={{ marginBottom: 10 }}>تُولِّد شهريًا — بضغطة زر — طلبات مكافأة مقترحة لكل موظف بلغت درجته (م٧) إحدى الشرائح، مع تثبيت لقطة الدرجة وقت الاقتراح. المقترحات تمرّ بقائمة الاعتماد نفسها ولا تُرحَّل إلا بعد اعتمادها. مُعطَّلة افتراضيًا حتى تراجعوها.</div>
          <label className="row" style={{ gap: 8, marginBottom: 8, cursor: 'pointer' }}>
            <input type="checkbox" checked={!!tf.enabled} onChange={e => setTf(x => ({ ...x, enabled: e.target.checked }))} /><b>تفعيل الشرائح</b>
          </label>
          <div className="grid" style={{ gap: 6 }}>
            {tf.tiers.map((t, i) => (
              <div key={i} className="row" style={{ gap: 8, alignItems: 'flex-end', flexWrap: 'wrap' }}>
                <Field label="الدرجة من (≥)"><input className="inp n" inputMode="numeric" value={t.minScore} onChange={e => setTf(x => ({ ...x, tiers: x.tiers.map((y, j) => j === i ? { ...y, minScore: e.target.value.replace(/\D/g, '') } : y) }))} /></Field>
                <Field label="مبلغ المكافأة (ر.س)"><input className="inp n" inputMode="decimal" value={t.amount} onChange={e => setTf(x => ({ ...x, tiers: x.tiers.map((y, j) => j === i ? { ...y, amount: e.target.value.replace(/[^\d.]/g, '') } : y) }))} /></Field>
                <button className="btn sm gh" onClick={() => setTf(x => ({ ...x, tiers: x.tiers.filter((_, j) => j !== i) }))}><Trash2 size={13} /></button>
              </div>
            ))}
            <div><button className="btn sm gh" onClick={() => setTf(x => ({ ...x, tiers: [...x.tiers, { minScore: '', amount: '' }] }))}><Plus size={13} />شريحة</button></div>
          </div>
          <div className="row" style={{ justifyContent: 'space-between', marginTop: 12, flexWrap: 'wrap', gap: 8 }}>
            <div className="row" style={{ gap: 8 }}>
              <input type="month" className="inp" value={ym} onChange={e => setYm(e.target.value)} />
              <button className="btn gh" disabled={!tiersCfg.enabled} onClick={genTier}><Sparkles size={14} />توليد مقترحات {ymLabel(ym)}</button>
            </div>
            <button className="btn pri" onClick={saveTiers}><Check size={14} />حفظ الشرائح</button>
          </div>
        </div>
      )}
    </div>
  );
}

/* ================= م٢٠ (v27.6) — الإجراءات التأديبية التصحيحية + خطط تحسين الأداء (PIP) =================
   نموذج البيانات (BR_COLS — بفرعها كي يقرأه/يكتبه جهاز الفرع ويقرأه المركز):
   ops.hrCorrective[] = { id, branchId, branchName, employeeId, employeeName, month(YYYY-MM), date,
     category, code, title, level, penaltyType, fineDays, fineAmount, description, discoveredAt, investigation, witnessName,
     status:'pending'|'approved'|'rejected', requestedBy/Name, requestedAt, decidedBy/Name, decidedAt, decisionNote,
     expiresAt, advanceId, signRefId, objection:{at,text,decidedNote,decidedByName,decidedAt} }
   ops.hrPips[] = { id, branchId, branchName, employeeId, employeeName, openedAt, reason, triggerScore, triggerMonth,
     objectives:[{text,metric,target}], mentorName, startAt, endAt, reviews:[{at,byName,note,progress}],
     status:'active'|'passed'|'failed'|'closed', outcome, closedByName, closedAt }
   نظام العمل السعودي (افتراضات قابلة للضبط في اللائحة — المرجع الملزم هو لائحة المنشأة المسجّلة بوزارة الموارد البشرية):
   أنواع الجزاءات وتدرّجها؛ محو الجزاء بعد ١٨٠ يومًا من الإبلاغ؛ سقف الغرامة أجر ٥ أيام شهريًا؛
   مهلة المؤاخذة ٣٠ يومًا من اكتشاف المخالفة؛ ومهلة تظلّم الموظف ١٥ يومًا من إبلاغه بالجزاء.
   ====================================================================================================== */
const PEN_TYPES = [
  { k: 'verbal', ar: 'تنبيه شفهي', rank: 1 },
  { k: 'warning', ar: 'إنذار كتابي', rank: 2 },
  { k: 'fine', ar: 'غرامة (خصم أيام أجر)', rank: 3 },
  { k: 'deny_raise', ar: 'الحرمان من العلاوة أو تأجيلها', rank: 4 },
  { k: 'deny_promo', ar: 'الحرمان من الترقية', rank: 5 },
  { k: 'suspend', ar: 'الإيقاف عن العمل', rank: 6 },
  { k: 'dismiss', ar: 'توصية بالفصل', rank: 7 },
];
const penTypeAr = (k) => (PEN_TYPES.find(t => t.k === k) || {}).ar || k;
function defaultPenaltySchedule() {
  const lad = (arr) => arr.map((x, i) => ({ level: i + 1, penaltyType: x[0], fineDays: x[1] || 0 }));
  return [
    { code: 'late', category: 'حضور', title: 'التأخّر عن موعد العمل', ladder: lad([['verbal', 0], ['warning', 0], ['fine', 0.5], ['fine', 1]]) },
    { code: 'absence', category: 'حضور', title: 'الغياب بدون إذن', ladder: lad([['warning', 0], ['fine', 1], ['fine', 3], ['dismiss', 0]]) },
    { code: 'hygiene', category: 'سلامة ونظافة', title: 'الإخلال بمعايير النظافة أو السلامة', ladder: lad([['verbal', 0], ['warning', 0], ['fine', 1], ['fine', 3]]) },
    { code: 'customer', category: 'سلوك', title: 'سوء التعامل مع العميل', ladder: lad([['warning', 0], ['fine', 1], ['fine', 3], ['suspend', 0]]) },
    { code: 'quality', category: 'جودة', title: 'مخالفة معايير التحضير أو الجودة', ladder: lad([['verbal', 0], ['warning', 0], ['fine', 1], ['fine', 2]]) },
    { code: 'cash', category: 'عهدة ونقدية', title: 'مخالفة تعليمات العهدة أو النقدية', ladder: lad([['warning', 0], ['fine', 2], ['fine', 5], ['dismiss', 0]]) },
  ];
}
// جزاءات معتمدة سابقة لنفس المخالفة ما زالت سارية (لم يمضِ عليها eraseDays) — أساس التدرّج ومحو الجزاء
function activePriorCorrectives(list, empId, code, asOfStr, eraseDays) {
  const asOf = new Date((asOfStr || today()) + 'T00:00:00');
  return (list || []).filter(c => c.employeeId === empId && c.code === code && c.status === 'approved')
    .filter(c => { const ds = (c.date || (c.decidedAt || '').slice(0, 10) || asOfStr); const d = new Date(ds + 'T00:00:00'); return (asOf - d) / 86400000 <= (Number(eraseDays) || 180); })
    .sort((a, b) => ((a.date || '') < (b.date || '') ? -1 : 1));
}
// المستوى التالي في سلّم اللائحة بحسب عدد الجزاءات السارية السابقة (0 ⇒ المستوى الأول)
function suggestNextLevel(schedule, code, priorCount) {
  const item = (schedule || []).find(s => s.code === code);
  if (!item || !(item.ladder || []).length) return null;
  const idx = Math.min(Number(priorCount) || 0, item.ladder.length - 1);
  return { ...item.ladder[idx], overflow: (Number(priorCount) || 0) >= item.ladder.length, title: item.title, category: item.category };
}
const correctiveExpiry = (dateStr, eraseDays) => { const d = new Date((dateStr || today()) + 'T00:00:00'); d.setDate(d.getDate() + (Number(eraseDays) || 180)); return d.toISOString().slice(0, 10); };
const dailyWageOf = (base) => (Number(base) || 0) / 30;   // أجر اليوم = الأساسي ÷ ٣٠ (نظام العمل)
// الغرامة المقترحة بحدّ نظام العمل: fineDays أيام أجر، بحيث لا يتجاوز مجموع غرامات الشهر السقف
function fineSuggest(base, fineDays, capDays, priorFineDaysThisMonth) {
  const dw = dailyWageOf(base);
  const remaining = Math.max(0, (Number(capDays) || 5) - (Number(priorFineDaysThisMonth) || 0));
  const days = Math.min(Number(fineDays) || 0, remaining);
  return { days, amount: Math.round(dw * days * 100) / 100, dw: Math.round(dw * 100) / 100, capped: (Number(fineDays) || 0) > remaining, remaining };
}
const pipTriggered = (score, threshold) => score != null && score < (Number(threshold) || 0);
const daysBetween = (aStr, bStr) => Math.round((new Date((bStr || today()) + 'T00:00:00') - new Date((aStr || today()) + 'T00:00:00')) / 86400000);

// محضر إجراء تأديبي يوقّعه الموظف بالعلم من كشك الفرع (م١٠) — إثبات المؤاخذة في محضر وفق نظام العمل
function correctiveSignDoc(rec, me) {
  return {
    id: uid('sg'), branchId: rec.branchId || '', branchName: rec.branchName || '', employeeId: rec.employeeId, employeeName: rec.employeeName,
    docType: 'corrective', month: rec.month || (rec.date || '').slice(0, 7), refId: rec.id,
    title: 'محضر إجراء تأديبي — ' + (rec.title || rec.category || ''), amount: rec.fineAmount || 0,
    lines: null, reason: (rec.category ? rec.category + ' · ' : '') + penTypeAr(rec.penaltyType) + (rec.description ? ' — ' + rec.description : ''),
    issuedAt: nowISO(), issuedBy: me ? me.id : '', issuedByName: me ? me.name : '', status: 'pending',
    signedAt: '', signedVia: '', signedOnBy: '', signedOnByName: '', pinVerified: false, witnessName: '', sig: null, sigHash: ''
  };
}

function Corrective({ org, ops, me, myBranches, commit, commitOrg, say }) {
  const role = ROLES[me.role] || {};
  const isAll = role.scope === 'all';
  const canRequest = me.role === 'branch_manager' || isAll;   // فتح إجراء: مدير الفرع + المركز
  const canApprove = !!role.approver;                         // الاعتماد النهائي: المكتب الرئيسي/مسؤول النظام/الإدارة العليا
  const canConfig = isAll;                                    // اللائحة والنوافذ الزمنية: أدوار المركز
  const branches = myBranches || [];
  const pol = { ...defaultHrPolicies(), ...(org.hrPolicies || {}) };
  const schedule = (pol.penaltySchedule && pol.penaltySchedule.length) ? pol.penaltySchedule : defaultPenaltySchedule();
  const eraseDays = Number(pol.penaltyEraseDays) || 180;
  const capDays = Number(pol.fineCapDaysPerMonth) || 5;
  const chargeWindow = Number(pol.chargeWindowDays) || 30;
  const objectionDays = Number(pol.objectionDays) || 15;
  const pipThreshold = Number(pol.pipTriggerScore) || 60;

  const [view, setView] = useState(canApprove ? 'queue' : 'log');
  const [branchId, setBranchId] = useState((branches[0] || {}).id || '');
  useEffect(() => { if (!branches.find(b => b.id === branchId)) setBranchId((branches[0] || {}).id || ''); }, [branches, branchId]); // eslint-disable-line
  const branch = branches.find(b => b.id === branchId) || null;
  const branchIds = branches.map(b => b.id);
  const emps = (org.employees || []).filter(e => e.isActive !== false && branch && e.branchId === branch.id);
  const empName = (id) => ((org.employees || []).find(e => e.id === id) || {}).name || '';
  const allRecs = (ops.hrCorrective || []).filter(r => branchIds.includes(r.branchId)).sort((a, b) => (a.requestedAt < b.requestedAt ? 1 : -1));
  const allPips = (ops.hrPips || []).filter(p => branchIds.includes(p.branchId)).sort((a, b) => (a.openedAt < b.openedAt ? 1 : -1));
  const td = today();
  const ymLabel = (y) => { const [Y, M] = String(y).split('-').map(Number); return isNaN(Y) ? y : new Date(Y, M - 1, 1).toLocaleDateString('ar', { month: 'long', year: 'numeric' }); };
  const penBadge = (k) => { const rank = (PEN_TYPES.find(t => t.k === k) || {}).rank || 0; return <span className={'badge ' + (rank >= 6 ? 'b-rose' : rank >= 3 ? 'b-amber' : 'b-sky')}>{penTypeAr(k)}</span>; };
  const statusBadge = (st) => <span className={'badge ' + (st === 'approved' ? 'b-mint' : st === 'rejected' ? 'b-rose' : 'b-amber')}>{st === 'approved' ? 'معتمد' : st === 'rejected' ? 'مرفوض' : 'قيد الاعتماد'}</span>;

  // ===== ١) فتح إجراء تأديبي =====
  const emptyF = { empId: '', code: '', penaltyType: 'warning', fineDays: '0', description: '', discoveredAt: td, date: td, investigation: '', witnessName: '' };
  const [f, setF] = useState(emptyF);
  const selItem = schedule.find(s => s.code === f.code) || null;
  const priorActives = f.empId && f.code ? activePriorCorrectives(ops.hrCorrective || [], f.empId, f.code, f.date, eraseDays) : [];
  const suggestion = f.code ? suggestNextLevel(schedule, f.code, priorActives.length) : null;
  // تطبيق اقتراح السلّم تلقائيًا عند تغيّر الموظف/المخالفة (يبقى قابلًا لتعديل المدير يدويًا)
  useEffect(() => {
    if (suggestion) setF(x => ({ ...x, penaltyType: suggestion.penaltyType, fineDays: String(suggestion.fineDays || 0), description: x.description || (selItem ? selItem.title : '') }));
  }, [f.empId, f.code]); // eslint-disable-line
  const priorFineDaysMonth = (empId, month, exclId) => (ops.hrCorrective || []).filter(c => c.employeeId === empId && c.status === 'approved' && c.penaltyType === 'fine' && (c.month === month) && c.id !== exclId).reduce((a, c) => a + (Number(c.fineDays) || 0), 0);
  const selEmp = emps.find(e => e.id === f.empId) || null;
  const fineCalc = (selEmp && f.penaltyType === 'fine') ? fineSuggest(selEmp.baseSalary, f.fineDays, capDays, priorFineDaysMonth(f.empId, (f.date || td).slice(0, 7))) : null;
  const chargeLate = f.discoveredAt && daysBetween(f.discoveredAt, f.date) > chargeWindow;

  const submit = async () => {
    if (!branch) return;
    if (!selEmp) return say('اختر الموظف', 'no');
    if (!f.code) return say('اختر نوع المخالفة من اللائحة', 'no');
    if (!String(f.description || '').trim()) return say('اكتب وصف المخالفة', 'no');
    const month = (f.date || td).slice(0, 7);
    if (f.penaltyType === 'fine' && lockedThru(org) && month <= lockedThru(org)) return say(LOCK_MSG(month + '-01'), 'no');
    const fc = f.penaltyType === 'fine' ? fineSuggest(selEmp.baseSalary, f.fineDays, capDays, priorFineDaysMonth(f.empId, month)) : { days: 0, amount: 0 };
    const rec = {
      id: uid('cr'), branchId: branch.id, branchName: branch.name, employeeId: selEmp.id, employeeName: selEmp.name,
      month, date: f.date || td, category: selItem ? selItem.category : '', code: f.code, title: selItem ? selItem.title : '',
      level: priorActives.length + 1, penaltyType: f.penaltyType, fineDays: fc.days || 0, fineAmount: fc.amount || 0,
      description: f.description.trim(), discoveredAt: f.discoveredAt || td, investigation: (f.investigation || '').trim(), witnessName: (f.witnessName || '').trim(),
      status: 'pending', requestedBy: me.id, requestedByName: me.name, requestedAt: nowISO()
    };
    const ok = await commit(d => ({ ...d, hrCorrective: [rec, ...(d.hrCorrective || [])] }),
      { actionType: 'create', targetType: 'corrective_action', targetId: rec.id, branchName: branch.name, title: 'فتح إجراء تأديبي', details: rec.employeeName + ' · ' + rec.title + ' · مستوى ' + rec.level + ' · ' + penTypeAr(rec.penaltyType) + (rec.fineAmount ? ' (' + money(rec.fineAmount) + ' ر.س)' : '') });
    if (!ok) return;
    say('سُجِّل الإجراء ✓ — بانتظار الاعتماد المركزي');
    setF({ ...emptyF, date: f.date, discoveredAt: f.discoveredAt });
  };
  const cancelReq = async (r) => {
    if (r.status !== 'pending') return;
    if (!window.confirm('إلغاء إجراء «' + r.employeeName + '»؟')) return;
    await commit(d => ({ ...d, hrCorrective: (d.hrCorrective || []).filter(x => x.id !== r.id) }),
      { actionType: 'delete', targetType: 'corrective_action', targetId: r.id, branchName: r.branchName, title: 'إلغاء إجراء تأديبي', details: r.employeeName + ' · ' + (r.title || '') });
    say('أُلغي الإجراء');
  };

  // ===== ٢) الاعتماد المركزي (+ ترحيل الغرامة لمسيّر الرواتب + إصدار محضر التوقيع) =====
  const [notes, setNotes] = useState({});
  const pending = allRecs.filter(r => r.status === 'pending');
  const decided = allRecs.filter(r => r.status !== 'pending');
  const decide = async (r, approve) => {
    if (!canApprove) return;
    const note = (notes[r.id] || '').trim();
    if (approve) {
      const month = r.month || (r.date || '').slice(0, 7);
      let adv = null, fineAmt = 0;
      if (r.penaltyType === 'fine') {
        if (lockedThru(org) && month <= lockedThru(org)) return say(LOCK_MSG(month + '-01'), 'no');
        const fc = fineSuggest(((org.employees || []).find(e => e.id === r.employeeId) || {}).baseSalary, r.fineDays, capDays, priorFineDaysMonth(r.employeeId, month, r.id));
        fineAmt = fc.amount;
        const existing = (ops.advances || []).find(a => a.correctiveId === r.id);
        adv = existing || {
          id: uid('ad'), correctiveId: r.id, employeeId: r.employeeId, employeeName: r.employeeName, branchId: r.branchId, branchName: r.branchName,
          month, date: month + '-28', type: 'discipline_penalty', amount: fineAmt,
          reason: 'غرامة تأديبية معتمدة: ' + (r.title || '') + ' — مستوى ' + r.level, paymentMethod: 'salary', isUnjustified: false, createdByName: me.name, createdAt: nowISO()
        };
        if (existing) adv = { ...existing, amount: fineAmt };
      }
      const ok = await commit(d => {
        const hasAdv = adv ? (d.advances || []).some(a => a.correctiveId === r.id) : false;
        return {
          ...d,
          advances: !adv ? (d.advances || []) : (hasAdv ? (d.advances || []).map(a => a.correctiveId === r.id ? { ...a, amount: fineAmt } : a) : [adv, ...(d.advances || [])]),
          hrCorrective: (d.hrCorrective || []).map(x => x.id === r.id ? { ...x, status: 'approved', fineAmount: fineAmt, decidedBy: me.id, decidedByName: me.name, decidedAt: nowISO(), decisionNote: note, expiresAt: correctiveExpiry(r.date, eraseDays), advanceId: adv ? adv.id : '', signRefId: r.id } : x),
          hrSignDocs: (d.hrSignDocs || []).some(x => x.refId === r.id) ? (d.hrSignDocs || []) : [correctiveSignDoc({ ...r, fineAmount: fineAmt }, me), ...(d.hrSignDocs || [])]
        };
      }, { actionType: 'approve', targetType: 'corrective_action', targetId: r.id, branchName: r.branchName, title: 'اعتماد إجراء تأديبي', details: r.employeeName + ' · ' + (r.title || '') + ' · ' + penTypeAr(r.penaltyType) + (fineAmt ? ' · غرامة ' + money(fineAmt) + ' ر.س لشهر ' + month : '') + ' · صدر محضر للتوقيع' + (note ? ' · ' + note : '') });
      if (ok) say('اعتُمد الإجراء ✓' + (fineAmt ? ' ورُحِّلت الغرامة لمسيّر رواتب ' + month : '') + ' وصدر محضر بالعلم للتوقيع');
    } else {
      if (!note) return say('اكتب سبب الرفض في الملاحظة', 'no');
      const ok = await commit(d => ({ ...d, hrCorrective: (d.hrCorrective || []).map(x => x.id === r.id ? { ...x, status: 'rejected', decidedBy: me.id, decidedByName: me.name, decidedAt: nowISO(), decisionNote: note } : x) }),
        { actionType: 'reject', targetType: 'corrective_action', targetId: r.id, branchName: r.branchName, title: 'رفض إجراء تأديبي', details: r.employeeName + ' · ' + note });
      if (ok) say('رُفض الإجراء');
    }
  };
  const revertApproval = async (r) => {
    if (!canApprove || r.status !== 'approved') return;
    const month = r.month || (r.date || '').slice(0, 7);
    if (r.penaltyType === 'fine') {
      const accrued = (ops.ledgerEntries || []).some(x => x.kind === 'salary_accrual' && x.month === month);
      if (accrued) return say('لا يمكن التراجع: استحقاق رواتب شهر ' + month + ' مُرحَّل للدفتر — عالجه بقيد يدوي', 'no');
      if (lockedThru(org) && month <= lockedThru(org)) return say(LOCK_MSG(month + '-01'), 'no');
    }
    if (!window.confirm('التراجع عن اعتماد إجراء «' + r.employeeName + '»؟ ستُحذف الغرامة إن وُجدت ويعود الإجراء قيد الاعتماد.')) return;
    const ok = await commit(d => ({
      ...d,
      advances: (d.advances || []).filter(a => a.correctiveId !== r.id),
      hrCorrective: (d.hrCorrective || []).map(x => x.id === r.id ? { ...x, status: 'pending', decidedBy: '', decidedByName: '', decidedAt: '', decisionNote: '', expiresAt: '', advanceId: '' } : x),
      hrSignDocs: (d.hrSignDocs || []).filter(x => !(x.refId === r.id && x.status === 'pending')).map(x => (x.refId === r.id && x.status === 'signed') ? { ...x, status: 'voided', voidedAt: nowISO(), voidedByName: me.name } : x)
    }), { actionType: 'update', targetType: 'corrective_action', targetId: r.id, branchName: r.branchName, title: 'التراجع عن اعتماد إجراء تأديبي', details: r.employeeName + ' · ' + (r.title || '') });
    if (ok) say('تراجعتَ عن الاعتماد — الإجراء قيد الاعتماد مجددًا');
  };
  // تظلّم الموظف (خلال objectionDays من الاعتماد) — يُسجَّل ثم يبتّه المركز
  const [objTxt, setObjTxt] = useState({});
  const logObjection = async (r) => {
    const t = (objTxt[r.id] || '').trim(); if (!t) return say('اكتب نص التظلّم', 'no');
    const ok = await commit(d => ({ ...d, hrCorrective: (d.hrCorrective || []).map(x => x.id === r.id ? { ...x, objection: { at: nowISO(), text: t, decidedNote: '', decidedByName: '', decidedAt: '' } } : x) }),
      { actionType: 'update', targetType: 'corrective_action', targetId: r.id, branchName: r.branchName, title: 'تسجيل تظلّم موظف', details: r.employeeName + ' · ' + t });
    if (ok) { say('سُجِّل التظلّم ✓'); setObjTxt(o => ({ ...o, [r.id]: '' })); }
  };
  const decideObjection = async (r, note) => {
    if (!canApprove) return; const n = (note || '').trim(); if (!n) return say('اكتب قرار البتّ في التظلّم', 'no');
    const ok = await commit(d => ({ ...d, hrCorrective: (d.hrCorrective || []).map(x => x.id === r.id ? { ...x, objection: { ...(x.objection || {}), decidedNote: n, decidedByName: me.name, decidedAt: nowISO() } } : x) }),
      { actionType: 'update', targetType: 'corrective_action', targetId: r.id, branchName: r.branchName, title: 'البتّ في تظلّم موظف', details: r.employeeName + ' · ' + n });
    if (ok) say('سُجِّل قرار التظلّم');
  };

  // ===== ٣) خطط تحسين الأداء (PIP) =====
  const curYm = td.slice(0, 7);
  const activePipEmpIds = new Set(allPips.filter(p => p.status === 'active').map(p => p.employeeId));
  const belowThreshold = branch ? emps.map(e => ({ e, sc: hrScoreFor(org, ops, e, curYm).score })).filter(x => pipTriggered(x.sc, pipThreshold) && !activePipEmpIds.has(x.e.id)) : [];
  const [pf, setPf] = useState(null);   // نموذج فتح PIP للموظف المحدَّد
  const openPipForm = (e, sc) => {
    const end = new Date(td + 'T00:00:00'); end.setDate(end.getDate() + 30);
    setPf({ empId: e.id, empName: e.name, reason: sc != null ? ('درجة الأداء ' + sc + '/100 دون العتبة ' + pipThreshold) : 'قرار إداري', triggerScore: sc, mentorName: '', startAt: td, endAt: end.toISOString().slice(0, 10), objectives: [{ text: '', metric: '', target: '' }] });
  };
  const savePip = async () => {
    if (!pf || !branch) return;
    const objs = (pf.objectives || []).filter(o => String(o.text || '').trim()).map(o => ({ text: o.text.trim(), metric: (o.metric || '').trim(), target: (o.target || '').trim() }));
    if (!objs.length) return say('أضف هدفًا واحدًا على الأقل', 'no');
    const rec = { id: uid('pip'), branchId: branch.id, branchName: branch.name, employeeId: pf.empId, employeeName: pf.empName, openedAt: nowISO(), reason: pf.reason, triggerScore: pf.triggerScore, triggerMonth: curYm, objectives: objs, mentorName: (pf.mentorName || '').trim(), startAt: pf.startAt, endAt: pf.endAt, reviews: [], status: 'active', outcome: '', closedByName: '', closedAt: '' };
    const ok = await commit(d => ({ ...d, hrPips: [rec, ...(d.hrPips || [])] }),
      { actionType: 'create', targetType: 'pip', targetId: rec.id, branchName: branch.name, title: 'فتح خطة تحسين أداء', details: rec.employeeName + ' · ' + objs.length + ' هدف · حتى ' + rec.endAt });
    if (ok) { say('فُتحت خطة تحسين الأداء ✓'); setPf(null); }
  };
  const [rvTxt, setRvTxt] = useState({});
  const addReview = async (p) => {
    const v = rvTxt[p.id] || {}; const note = (v.note || '').trim(); const progress = Number(v.progress);
    if (!note) return say('اكتب ملاحظة المراجعة', 'no');
    const rev = { at: nowISO(), byName: me.name, note, progress: isNaN(progress) ? null : Math.max(0, Math.min(100, progress)) };
    const ok = await commit(d => ({ ...d, hrPips: (d.hrPips || []).map(x => x.id === p.id ? { ...x, reviews: [...(x.reviews || []), rev] } : x) }),
      { actionType: 'update', targetType: 'pip', targetId: p.id, branchName: p.branchName, title: 'مراجعة خطة تحسين أداء', details: p.employeeName + ' · ' + note + (rev.progress != null ? ' · ' + rev.progress + '%' : '') });
    if (ok) { say('سُجِّلت المراجعة ✓'); setRvTxt(o => ({ ...o, [p.id]: {} })); }
  };
  const closePip = async (p, outcome) => {
    const outAr = { passed: 'ناجحة', failed: 'غير ناجحة', closed: 'مُغلقة' }[outcome] || outcome;
    if (!window.confirm('إغلاق خطة «' + p.employeeName + '» كـ«' + outAr + '»؟')) return;
    const ok = await commit(d => ({ ...d, hrPips: (d.hrPips || []).map(x => x.id === p.id ? { ...x, status: outcome, outcome: outAr, closedByName: me.name, closedAt: nowISO() } : x) }),
      { actionType: 'update', targetType: 'pip', targetId: p.id, branchName: p.branchName, title: 'إغلاق خطة تحسين أداء', details: p.employeeName + ' · ' + outAr });
    if (ok) say('أُغلقت الخطة (' + outAr + ')');
  };

  // ===== ٤) اللائحة والنوافذ الزمنية (المركز) =====
  const [cf, setCf] = useState(() => ({
    penaltyEraseDays: String(eraseDays), fineCapDaysPerMonth: String(capDays), chargeWindowDays: String(chargeWindow), objectionDays: String(objectionDays), pipTriggerScore: String(pipThreshold),
    penaltySchedule: schedule.map(s => ({ ...s, ladder: (s.ladder || []).map(l => ({ ...l })) }))
  }));
  const saveConfig = async () => {
    const sched = (cf.penaltySchedule || []).filter(s => String(s.code || '').trim() && String(s.title || '').trim()).map(s => ({
      code: s.code.trim(), category: (s.category || '').trim(), title: s.title.trim(),
      ladder: (s.ladder || []).map((l, i) => ({ level: i + 1, penaltyType: l.penaltyType || 'warning', fineDays: Number(l.fineDays) || 0 }))
    }));
    const patch = { penaltyEraseDays: Number(cf.penaltyEraseDays) || 180, fineCapDaysPerMonth: Number(cf.fineCapDaysPerMonth) || 5, chargeWindowDays: Number(cf.chargeWindowDays) || 30, objectionDays: Number(cf.objectionDays) || 15, pipTriggerScore: Number(cf.pipTriggerScore) || 60, penaltySchedule: sched };
    const ok = await commitOrg(d => ({ ...d, hrPolicies: { ...defaultHrPolicies(), ...(d.hrPolicies || {}), ...patch } }),
      { actionType: 'update', targetType: 'settings', targetId: 'hrPolicies.penalty', title: 'ضبط لائحة الجزاءات والنوافذ الزمنية', details: sched.length + ' مخالفة · محو ' + patch.penaltyEraseDays + 'ي · سقف غرامة ' + patch.fineCapDaysPerMonth + ' أيام · عتبة PIP ' + patch.pipTriggerScore });
    if (ok) say('حُفظت اللائحة ✓');
  };

  if (!branch && branches.length === 0) return <div className="card"><div className="empty">لا يوجد فرع مُسند لحسابك — راجع مسؤول النظام.</div></div>;

  const CorrTable = ({ rows, actions }) => (
    <div className="tw">
      <table className="tb">
        <thead><tr><th>الموظف</th>{branches.length > 1 && <th>الفرع</th>}<th>المخالفة</th><th>المستوى</th><th>الجزاء</th><th>الغرامة</th><th>التاريخ</th><th>الحالة</th>{actions && <th />}</tr></thead>
        <tbody>
          {rows.map(r => (
            <tr key={r.id}>
              <td style={{ fontWeight: 600, fontSize: 12.5 }}>{r.employeeName}</td>
              {branches.length > 1 && <td style={{ fontSize: 12 }}>{r.branchName}</td>}
              <td style={{ fontSize: 12 }}>{r.title || '—'}{r.category ? <div style={{ fontSize: 10.5, color: 'var(--muted)' }}>{r.category}</div> : null}{r.description ? <div style={{ fontSize: 10.5, color: 'var(--faint)' }}>{r.description}</div> : null}</td>
              <td className="num">{r.level}</td>
              <td>{penBadge(r.penaltyType)}</td>
              <td className="num">{r.penaltyType === 'fine' ? money(r.fineAmount || 0) : '—'}</td>
              <td className="num" style={{ fontSize: 11.5 }}>{r.date}{r.status === 'approved' && r.expiresAt ? <div style={{ fontSize: 10, color: 'var(--faint)' }}>يُمحى {r.expiresAt}</div> : null}</td>
              <td>{statusBadge(r.status)}{r.decisionNote ? <div style={{ fontSize: 10.5, color: 'var(--muted)' }}>{r.decisionNote}</div> : null}{r.status === 'approved' && (() => { const sd = (ops.hrSignDocs || []).find(x => x.refId === r.id); return sd ? <div style={{ marginTop: 3 }}><span className={'badge ' + (sd.status === 'signed' ? 'b-mint' : sd.status === 'voided' ? 'b-dim' : 'b-amber')} style={{ fontSize: 9.5 }}><PenLine size={10} />{sd.status === 'signed' ? 'وقّع المحضر' : sd.status === 'voided' ? 'محضر مُلغى' : 'بانتظار توقيع الموظف'}</span></div> : null; })()}{r.objection ? <div style={{ marginTop: 3, fontSize: 10.5, color: 'var(--amber)' }}>تظلّم: {r.objection.text}{r.objection.decidedNote ? <div style={{ color: 'var(--mint)' }}>القرار: {r.objection.decidedNote}</div> : null}</div> : null}</td>
              {actions && <td>{actions(r)}</td>}
            </tr>
          ))}
          {rows.length === 0 && <tr><td colSpan={branches.length > 1 ? 9 : 8}><div className="empty">لا توجد إجراءات.</div></td></tr>}
        </tbody>
      </table>
    </div>
  );

  return (
    <div className="grid" style={{ gap: 12 }}>
      <div className="card" style={{ padding: '8px 12px' }}>
        <div className="row" style={{ gap: 6, flexWrap: 'wrap', justifyContent: 'space-between' }}>
          <div className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
            <button className={'btn sm' + (view === 'log' ? ' pri' : ' gh')} onClick={() => setView('log')}><ShieldAlert size={13} />الإجراءات التأديبية</button>
            {canApprove && <button className={'btn sm' + (view === 'queue' ? ' pri' : ' gh')} onClick={() => setView('queue')}><ShieldCheck size={13} />الاعتماد{pending.length ? <span className="badge b-amber" style={{ marginInlineStart: 6 }}>{pending.length}</span> : null}</button>}
            <button className={'btn sm' + (view === 'pip' ? ' pri' : ' gh')} onClick={() => setView('pip')}><ClipboardCheck size={13} />خطط تحسين الأداء{belowThreshold.length ? <span className="badge b-rose" style={{ marginInlineStart: 6 }}>{belowThreshold.length}</span> : null}</button>
            {canConfig && <button className={'btn sm' + (view === 'schedule' ? ' pri' : ' gh')} onClick={() => setView('schedule')}><Scale size={13} />اللائحة</button>}
          </div>
          {branches.length > 1 && view !== 'schedule' && (
            <select className="inp sel" style={{ width: 180 }} value={branchId} onChange={e => setBranchId(e.target.value)}>
              {branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
            </select>
          )}
        </div>
      </div>

      {view === 'log' && branch && (
        <div className="grid" style={{ gap: 12 }}>
          {canRequest && (
            <div className="card">
              <div className="card-t" style={{ marginBottom: 8 }}><ShieldAlert size={15} color="var(--brass)" />فتح إجراء تأديبي — {branch.name}</div>
              <div className="note" style={{ marginBottom: 8 }}>يُحدَّد الجزاء تلقائيًا حسب سلّم اللائحة وعدد المخالفات السابقة السارية للموظف (تُمحى بعد {eraseDays} يومًا). لا أثر مالي قبل الاعتماد المركزي؛ بعد الاعتماد يصدر محضر بالعلم يوقّعه الموظف من كشك الفرع، وتُرحَّل الغرامة — إن وُجدت — لمسيّر الرواتب.</div>
              <div className="grid g3">
                <Field label="الموظف"><select className="inp sel" value={f.empId} onChange={e => setF(x => ({ ...x, empId: e.target.value }))}><option value="">اختر</option>{emps.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}</select></Field>
                <Field label="المخالفة (من اللائحة)"><select className="inp sel" value={f.code} onChange={e => setF(x => ({ ...x, code: e.target.value }))}><option value="">اختر</option>{schedule.map(s => <option key={s.code} value={s.code}>{s.title} ({s.category})</option>)}</select></Field>
                <Field label="تاريخ المخالفة"><input type="date" className="inp" value={f.date} onChange={e => setF(x => ({ ...x, date: e.target.value }))} /></Field>
                <Field label="نوع الجزاء"><select className="inp sel" value={f.penaltyType} onChange={e => setF(x => ({ ...x, penaltyType: e.target.value }))}>{PEN_TYPES.map(t => <option key={t.k} value={t.k}>{t.ar}</option>)}</select></Field>
                {f.penaltyType === 'fine' && <Field label="أيام الغرامة (أجر)"><input className="inp n" inputMode="decimal" value={f.fineDays} onChange={e => setF(x => ({ ...x, fineDays: e.target.value.replace(/[^\d.]/g, '') }))} /></Field>}
                <Field label="تاريخ اكتشاف المخالفة"><input type="date" className="inp" value={f.discoveredAt} onChange={e => setF(x => ({ ...x, discoveredAt: e.target.value }))} /></Field>
                <Field label="وصف المخالفة (إلزامي)" style={{ gridColumn: 'span 2' }}><input className="inp" value={f.description} onChange={e => setF(x => ({ ...x, description: e.target.value }))} placeholder="ماذا حدث بالتحديد ومتى وأين" /></Field>
                <Field label="الشاهد (اختياري)"><input className="inp" value={f.witnessName} onChange={e => setF(x => ({ ...x, witnessName: e.target.value }))} /></Field>
                <Field label="التحقيق ودفاع الموظف (محضر — نظام العمل)" style={{ gridColumn: 'span 3' }}><textarea className="inp" rows={2} value={f.investigation} onChange={e => setF(x => ({ ...x, investigation: e.target.value }))} placeholder="ما أُبلِغ به الموظف كتابةً، واستجوابه، ودفاعه — يُثبَت في المحضر" /></Field>
              </div>
              {(suggestion || priorActives.length > 0 || fineCalc || chargeLate) && (
                <div className="card" style={{ padding: 10, marginTop: 8, background: 'rgba(200,162,74,.06)', fontSize: 12, lineHeight: 1.9 }}>
                  {priorActives.length > 0 && <div>سجل ساري لهذه المخالفة: <b>{priorActives.length}</b> جزاء سابق ⇒ هذا هو المستوى <b>{priorActives.length + 1}</b>.</div>}
                  {priorActives.length === 0 && <div>لا جزاء ساري سابق لهذه المخالفة ⇒ المستوى <b>الأول</b>.</div>}
                  {suggestion && <div>اقتراح اللائحة: <b>{penTypeAr(suggestion.penaltyType)}</b>{suggestion.overflow ? ' (تجاوز أعلى درجات السلّم — راجع اللائحة)' : ''}.</div>}
                  {fineCalc && <div>الغرامة: {fineCalc.days} يوم أجر × {money(fineCalc.dw)} = <b>{money(fineCalc.amount)} ر.س</b>{fineCalc.capped ? <span style={{ color: 'var(--rose)' }}> — محدودة بسقف {capDays} أيام أجر شهريًا (المتبقي هذا الشهر {fineCalc.remaining} يوم)</span> : ''}.</div>}
                  {chargeLate && <div style={{ color: 'var(--rose)' }}>⚠ مضى أكثر من {chargeWindow} يومًا بين اكتشاف المخالفة وتاريخها — قد تسقط المؤاخذة نظامًا (المادة ٦٩).</div>}
                </div>
              )}
              <div className="row" style={{ justifyContent: 'flex-end', marginTop: 10 }}><button className="btn pri" onClick={submit}><Send size={14} />إرسال للاعتماد</button></div>
            </div>
          )}
          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}>سجل إجراءات {branch.name}</div>
            <CorrTable rows={allRecs.filter(r => r.branchId === branch.id)} actions={(r) => (
              <div className="grid" style={{ gap: 4, minWidth: 150 }}>
                {r.status === 'pending' && canRequest && (r.requestedBy === me.id || isAll) && <button className="btn sm gh" onClick={() => cancelReq(r)}><Trash2 size={13} />إلغاء</button>}
                {r.status === 'approved' && !r.objection && daysBetween((r.decidedAt || '').slice(0, 10), td) <= objectionDays && (
                  <><input className="inp" style={{ fontSize: 11 }} placeholder={'تظلّم (خلال ' + objectionDays + ' يوم)'} value={objTxt[r.id] || ''} onChange={e => setObjTxt(o => ({ ...o, [r.id]: e.target.value }))} /><button className="btn sm gh" onClick={() => logObjection(r)}>تسجيل تظلّم</button></>
                )}
                {r.status === 'approved' && r.objection && !r.objection.decidedNote && canApprove && (
                  <><input className="inp" style={{ fontSize: 11 }} placeholder="قرار البتّ" value={notes['obj-' + r.id] || ''} onChange={e => setNotes(n => ({ ...n, ['obj-' + r.id]: e.target.value }))} /><button className="btn sm gh" onClick={() => decideObjection(r, notes['obj-' + r.id])}>بتّ التظلّم</button></>
                )}
              </div>
            )} />
          </div>
        </div>
      )}

      {view === 'queue' && canApprove && (
        <div className="grid" style={{ gap: 12 }}>
          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}><ShieldCheck size={15} color="var(--brass)" />اعتماد الإجراءات التأديبية — {pending.length} قيد الانتظار (كل فروعي)</div>
            <div className="note" style={{ marginBottom: 8 }}>الاعتماد يُثبِّت مدة محو الجزاء، ويصدر محضرًا بالعلم للتوقيع الإلكتروني، ويُرحِّل الغرامة (إن وُجدت) لمسيّر رواتب الشهر — بسقف {capDays} أيام أجر شهريًا.</div>
            <CorrTable rows={pending} actions={(r) => (
              <div className="grid" style={{ gap: 5, minWidth: 190 }}>
                <input className="inp" placeholder="ملاحظة القرار (إلزامية للرفض)" value={notes[r.id] || ''} onChange={e => setNotes(n => ({ ...n, [r.id]: e.target.value }))} />
                <div className="row" style={{ gap: 5, justifyContent: 'flex-end' }}>
                  <button className="btn sm pri" onClick={() => decide(r, true)}><Check size={13} />اعتماد</button>
                  <button className="btn sm gh" onClick={() => decide(r, false)}><X size={13} />رفض</button>
                </div>
              </div>
            )} />
          </div>
          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}>سجل القرارات</div>
            <CorrTable rows={decided} actions={(r) => (r.status === 'approved' ? <button className="btn sm gh" title="التراجع عن الاعتماد" onClick={() => revertApproval(r)}><X size={13} />تراجع</button> : null)} />
          </div>
        </div>
      )}

      {view === 'pip' && branch && (
        <div className="grid" style={{ gap: 12 }}>
          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}><ClipboardCheck size={15} color="var(--brass)" />خطط تحسين الأداء — {branch.name}</div>
            <div className="note" style={{ marginBottom: 8 }}>خطة تحسين الأداء بديل تطويري عن الجزاء: أهداف قابلة للقياس ومدة ومراجعات دورية. تُقترح تلقائيًا لمن درجته (م٧) لشهر {ymLabel(curYm)} دون العتبة {pipThreshold} وليست لديه خطة نشطة.</div>
            {belowThreshold.length > 0 ? (
              <div className="grid g3">
                {belowThreshold.map(({ e, sc }) => (
                  <div key={e.id} className="card" style={{ padding: 10, border: '1px solid var(--frame-o)' }}>
                    <div style={{ fontWeight: 700, fontSize: 13 }}>{e.name}</div>
                    <div style={{ marginTop: 4 }}><span className="badge b-rose">درجة {sc}/100</span></div>
                    <button className="btn sm pri" style={{ marginTop: 8 }} onClick={() => openPipForm(e, sc)}><Plus size={13} />فتح خطة</button>
                  </div>
                ))}
              </div>
            ) : <div className="empty">لا موظفين دون العتبة لهذا الشهر — أو خططهم نشطة. يمكنك فتح خطة يدويًا لأي موظف.</div>}
            <div className="row" style={{ marginTop: 10, gap: 8, flexWrap: 'wrap', alignItems: 'flex-end' }}>
              <Field label="فتح خطة يدويًا لموظف"><select className="inp sel" style={{ width: 200 }} value={(pf && pf.manualSel) || ''} onChange={e => { const emp = emps.find(x => x.id === e.target.value); if (emp) openPipForm(emp, hrScoreFor(org, ops, emp, curYm).score); }}><option value="">اختر موظفًا</option>{emps.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}</select></Field>
            </div>
          </div>

          {pf && (
            <div className="card">
              <div className="card-t" style={{ marginBottom: 8 }}><ClipboardCheck size={15} color="var(--brass)" />خطة تحسين أداء — {pf.empName}</div>
              <div className="grid g3">
                <Field label="السبب"><input className="inp" value={pf.reason} onChange={e => setPf(x => ({ ...x, reason: e.target.value }))} /></Field>
                <Field label="المسؤول/الموجّه"><input className="inp" value={pf.mentorName} onChange={e => setPf(x => ({ ...x, mentorName: e.target.value }))} /></Field>
                <Field label="من"><input type="date" className="inp" value={pf.startAt} onChange={e => setPf(x => ({ ...x, startAt: e.target.value }))} /></Field>
                <Field label="إلى"><input type="date" className="inp" value={pf.endAt} onChange={e => setPf(x => ({ ...x, endAt: e.target.value }))} /></Field>
              </div>
              <div style={{ fontSize: 12, fontWeight: 600, margin: '10px 0 4px' }}>الأهداف القابلة للقياس</div>
              <div className="grid" style={{ gap: 6 }}>
                {pf.objectives.map((o, i) => (
                  <div key={i} className="row" style={{ gap: 6, alignItems: 'flex-end', flexWrap: 'wrap' }}>
                    <Field label="الهدف" style={{ flex: 2, minWidth: 180 }}><input className="inp" value={o.text} onChange={e => setPf(x => ({ ...x, objectives: x.objectives.map((y, j) => j === i ? { ...y, text: e.target.value } : y) }))} /></Field>
                    <Field label="المقياس"><input className="inp" value={o.metric} onChange={e => setPf(x => ({ ...x, objectives: x.objectives.map((y, j) => j === i ? { ...y, metric: e.target.value } : y) }))} /></Field>
                    <Field label="المستهدف"><input className="inp" value={o.target} onChange={e => setPf(x => ({ ...x, objectives: x.objectives.map((y, j) => j === i ? { ...y, target: e.target.value } : y) }))} /></Field>
                    <button className="btn sm gh" onClick={() => setPf(x => ({ ...x, objectives: x.objectives.filter((_, j) => j !== i) }))}><Trash2 size={13} /></button>
                  </div>
                ))}
                <div><button className="btn sm gh" onClick={() => setPf(x => ({ ...x, objectives: [...x.objectives, { text: '', metric: '', target: '' }] }))}><Plus size={13} />هدف</button></div>
              </div>
              <div className="row" style={{ justifyContent: 'flex-end', gap: 6, marginTop: 10 }}>
                <button className="btn gh" onClick={() => setPf(null)}>إلغاء</button>
                <button className="btn pri" onClick={savePip}><Check size={14} />فتح الخطة</button>
              </div>
            </div>
          )}

          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}>الخطط النشطة والمغلقة — {branch.name}</div>
            <div className="grid" style={{ gap: 10 }}>
              {allPips.filter(p => p.branchId === branch.id).map(p => (
                <div key={p.id} className="card" style={{ padding: 12, border: '1px solid var(--frame-o)' }}>
                  <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 6 }}>
                    <div><b>{p.employeeName}</b> <span className="badge b-dim" style={{ fontSize: 10 }}>{p.startAt} ← {p.endAt}</span></div>
                    <span className={'badge ' + (p.status === 'active' ? 'b-amber' : p.status === 'passed' ? 'b-mint' : p.status === 'failed' ? 'b-rose' : 'b-dim')}>{p.status === 'active' ? 'نشطة' : p.outcome || p.status}</span>
                  </div>
                  <div style={{ fontSize: 11.5, color: 'var(--muted)', marginTop: 4 }}>{p.reason}{p.mentorName ? ' · الموجّه: ' + p.mentorName : ''}</div>
                  <ul style={{ margin: '6px 0', paddingInlineStart: 18, fontSize: 12 }}>{p.objectives.map((o, i) => <li key={i}>{o.text}{o.metric ? ' — ' + o.metric : ''}{o.target ? ' (' + o.target + ')' : ''}</li>)}</ul>
                  {(p.reviews || []).length > 0 && <div style={{ fontSize: 11, color: 'var(--dim)', borderTop: '1px dashed var(--frame-o)', paddingTop: 6 }}>{p.reviews.map((rv, i) => <div key={i}>• {(rv.at || '').slice(0, 10)} — {rv.note}{rv.progress != null ? ' (' + rv.progress + '%)' : ''} — {rv.byName}</div>)}</div>}
                  {p.status === 'active' && (
                    <div className="row" style={{ gap: 6, marginTop: 8, flexWrap: 'wrap', alignItems: 'flex-end' }}>
                      <Field label="مراجعة" style={{ flex: 2, minWidth: 160 }}><input className="inp" value={(rvTxt[p.id] || {}).note || ''} onChange={e => setRvTxt(o => ({ ...o, [p.id]: { ...(o[p.id] || {}), note: e.target.value } }))} /></Field>
                      <Field label="التقدّم %"><input className="inp n" inputMode="numeric" style={{ width: 80 }} value={(rvTxt[p.id] || {}).progress || ''} onChange={e => setRvTxt(o => ({ ...o, [p.id]: { ...(o[p.id] || {}), progress: e.target.value.replace(/\D/g, '') } }))} /></Field>
                      <button className="btn sm gh" onClick={() => addReview(p)}><Plus size={13} />مراجعة</button>
                      <div className="row" style={{ gap: 4 }}>
                        <button className="btn sm pri" onClick={() => closePip(p, 'passed')}>ناجحة</button>
                        <button className="btn sm gh" onClick={() => closePip(p, 'failed')}>غير ناجحة</button>
                        <button className="btn sm gh" onClick={() => closePip(p, 'closed')}>إغلاق</button>
                      </div>
                    </div>
                  )}
                </div>
              ))}
              {allPips.filter(p => p.branchId === branch.id).length === 0 && <div className="empty">لا خطط بعد.</div>}
            </div>
          </div>
        </div>
      )}

      {view === 'schedule' && canConfig && (
        <div className="grid" style={{ gap: 12 }}>
          <div className="card">
            <div className="card-t" style={{ marginBottom: 6 }}><Scale size={15} color="var(--brass)" />النوافذ الزمنية (نظام العمل — قابلة للضبط)</div>
            <div className="note" style={{ marginBottom: 8 }}>القيم الافتراضية مبنية على نظام العمل السعودي؛ عدّلوها لتطابق لائحة تنظيم العمل المسجّلة لمنشأتكم لدى وزارة الموارد البشرية — هي المرجع الملزم.</div>
            <div className="grid g3">
              <Field label="محو الجزاء بعد (يوم)"><input className="inp n" inputMode="numeric" value={cf.penaltyEraseDays} onChange={e => setCf(x => ({ ...x, penaltyEraseDays: e.target.value.replace(/\D/g, '') }))} /></Field>
              <Field label="سقف الغرامة الشهري (أيام أجر)"><input className="inp n" inputMode="numeric" value={cf.fineCapDaysPerMonth} onChange={e => setCf(x => ({ ...x, fineCapDaysPerMonth: e.target.value.replace(/\D/g, '') }))} /></Field>
              <Field label="مهلة المؤاخذة من الاكتشاف (يوم)"><input className="inp n" inputMode="numeric" value={cf.chargeWindowDays} onChange={e => setCf(x => ({ ...x, chargeWindowDays: e.target.value.replace(/\D/g, '') }))} /></Field>
              <Field label="مهلة تظلّم الموظف (يوم)"><input className="inp n" inputMode="numeric" value={cf.objectionDays} onChange={e => setCf(x => ({ ...x, objectionDays: e.target.value.replace(/\D/g, '') }))} /></Field>
              <Field label="عتبة اقتراح خطة تحسين الأداء (من 100)"><input className="inp n" inputMode="numeric" value={cf.pipTriggerScore} onChange={e => setCf(x => ({ ...x, pipTriggerScore: e.target.value.replace(/\D/g, '') }))} /></Field>
            </div>
          </div>
          <div className="card">
            <div className="card-t" style={{ marginBottom: 6 }}><Scale size={15} color="var(--brass)" />لائحة المخالفات وسلّم الجزاءات</div>
            <div className="grid" style={{ gap: 10 }}>
              {cf.penaltySchedule.map((s, si) => (
                <div key={si} className="card" style={{ padding: 10, border: '1px solid var(--frame-o)' }}>
                  <div className="row" style={{ gap: 6, alignItems: 'flex-end', flexWrap: 'wrap' }}>
                    <Field label="الرمز"><input className="inp" style={{ width: 90 }} value={s.code} onChange={e => setCf(x => ({ ...x, penaltySchedule: x.penaltySchedule.map((y, j) => j === si ? { ...y, code: e.target.value } : y) }))} /></Field>
                    <Field label="التصنيف"><input className="inp" style={{ width: 120 }} value={s.category} onChange={e => setCf(x => ({ ...x, penaltySchedule: x.penaltySchedule.map((y, j) => j === si ? { ...y, category: e.target.value } : y) }))} /></Field>
                    <Field label="المخالفة" style={{ flex: 2, minWidth: 180 }}><input className="inp" value={s.title} onChange={e => setCf(x => ({ ...x, penaltySchedule: x.penaltySchedule.map((y, j) => j === si ? { ...y, title: e.target.value } : y) }))} /></Field>
                    <button className="btn sm gh" onClick={() => setCf(x => ({ ...x, penaltySchedule: x.penaltySchedule.filter((_, j) => j !== si) }))}><Trash2 size={13} /></button>
                  </div>
                  <div style={{ fontSize: 11, color: 'var(--dim)', margin: '6px 0 4px' }}>سلّم الجزاء بالتكرار (المستوى ١ = أول مرة):</div>
                  <div className="grid" style={{ gap: 4 }}>
                    {(s.ladder || []).map((l, li) => (
                      <div key={li} className="row" style={{ gap: 6, alignItems: 'center', flexWrap: 'wrap' }}>
                        <span className="badge b-dim">{li + 1}</span>
                        <select className="inp sel" style={{ width: 200 }} value={l.penaltyType} onChange={e => setCf(x => ({ ...x, penaltySchedule: x.penaltySchedule.map((y, j) => j === si ? { ...y, ladder: y.ladder.map((z, k) => k === li ? { ...z, penaltyType: e.target.value } : z) } : y) }))}>{PEN_TYPES.map(t => <option key={t.k} value={t.k}>{t.ar}</option>)}</select>
                        {l.penaltyType === 'fine' && <input className="inp n" style={{ width: 90 }} inputMode="decimal" placeholder="أيام أجر" value={l.fineDays} onChange={e => setCf(x => ({ ...x, penaltySchedule: x.penaltySchedule.map((y, j) => j === si ? { ...y, ladder: y.ladder.map((z, k) => k === li ? { ...z, fineDays: e.target.value.replace(/[^\d.]/g, '') } : z) } : y) }))} />}
                        <button className="btn sm gh" onClick={() => setCf(x => ({ ...x, penaltySchedule: x.penaltySchedule.map((y, j) => j === si ? { ...y, ladder: y.ladder.filter((_, k) => k !== li) } : y) }))}><X size={12} /></button>
                      </div>
                    ))}
                    <div><button className="btn sm gh" onClick={() => setCf(x => ({ ...x, penaltySchedule: x.penaltySchedule.map((y, j) => j === si ? { ...y, ladder: [...(y.ladder || []), { level: (y.ladder || []).length + 1, penaltyType: 'warning', fineDays: 0 }] } : y) }))}><Plus size={12} />درجة</button></div>
                  </div>
                </div>
              ))}
              <div><button className="btn sm gh" onClick={() => setCf(x => ({ ...x, penaltySchedule: [...x.penaltySchedule, { code: '', category: '', title: '', ladder: [{ level: 1, penaltyType: 'verbal', fineDays: 0 }] }] }))}><Plus size={13} />مخالفة</button></div>
            </div>
            <div className="row" style={{ justifyContent: 'flex-end', marginTop: 12 }}><button className="btn pri" onClick={saveConfig}><Check size={14} />حفظ اللائحة</button></div>
          </div>
        </div>
      )}
    </div>
  );
}


/* ================= م١٩ (v27.7) — التدريب والشهادات الإلزامية =================
   نموذج البيانات:
   - org.trainingPrograms[] (إعداد مركزي، يصل الفروع عبر dirOf): { id, title, category, validityMonths(0=بلا انتهاء), mandatory, requiredJobTitles[], provider }
   - ops.hrTraining[] (BR_COLS — بفرعها؛ يقرأه/يكتبه جهاز الفرع ويقرأه المركز):
       { id, branchId, employeeId, employeeName, programId, programTitle, status:'planned'|'in_progress'|'completed',
         plannedDate, completedDate, expiryDate, score, result:'pass'|'fail'|'', certNo, note, recordedBy/Name, recordedAt }
   - الإعداد في org.hrPolicies: trainingExpiryAlertDays (تنبيه قبل انتهاء الشهادة).
   السياق (السعودية): الشهادة الصحية إلزامية لكل متداولي الأغذية وصلاحيتها سنة (وزارة البلديات)؛
   وتدريب سلامة الغذاء من جهة معتمدة لدى هيئة الغذاء والدواء. المدد والبرامج قابلة للضبط — لائحة الجهة الرسمية هي المرجع.
   المصادر موثّقة في claude/hr-training-v27.7.md.
   ============================================================================= */
function defaultTrainingPrograms() {
  return [
    { id: 'health_cert', title: 'الشهادة الصحية (متداول أغذية)', category: 'إلزامي', validityMonths: 12, mandatory: true, requiredJobTitles: [], provider: 'وزارة البلديات / بلدي' },
    { id: 'food_safety', title: 'تدريب سلامة الغذاء الأساسي', category: 'سلامة غذاء', validityMonths: 36, mandatory: true, requiredJobTitles: [], provider: 'جهة معتمدة (هيئة الغذاء والدواء)' },
    { id: 'haccp', title: 'نظام الهاسب (HACCP) للمشرفين', category: 'سلامة غذاء', validityMonths: 36, mandatory: false, requiredJobTitles: ['مدير الفرع', 'مشرف', 'شيف'], provider: 'جهة معتمدة' },
    { id: 'fire_safety', title: 'السلامة ومكافحة الحريق', category: 'سلامة', validityMonths: 24, mandatory: false, requiredJobTitles: [], provider: 'الدفاع المدني / جهة معتمدة' },
    { id: 'customer_service', title: 'مهارات خدمة العملاء', category: 'مهارات', validityMonths: 0, mandatory: false, requiredJobTitles: [], provider: 'داخلي' },
  ];
}
const TRAIN_STATUS_AR = { planned: 'مجدول', in_progress: 'جارٍ', completed: 'مكتمل', expired: 'منتهية' };
function addMonthsStr(dateStr, months) {
  if (!dateStr) return '';
  const [Y, M, D] = dateStr.split('-').map(Number); const d = new Date(Y, (M - 1) + (Number(months) || 0), D || 1);
  return d.toISOString().slice(0, 10);
}
const trainingExpiryOf = (completedDate, validityMonths) => (!completedDate || !(Number(validityMonths) > 0)) ? '' : addMonthsStr(completedDate, validityMonths);
// الحالة الفعلية الآن: مكتمل بشهادة منتهية ⇒ 'expired'
function trainingStatusNow(rec, todayStr) {
  const td = todayStr || today();
  if (rec.status === 'completed' && rec.expiryDate && rec.expiryDate < td) return 'expired';
  return rec.status;
}
// هل البرنامج مطلوب لهذا الموظف (إلزامي، ومطابق لمسماه إن حُدّدت مسميات)
function programRequiredFor(prog, emp) {
  if (!prog || !prog.mandatory) return false;
  const jt = (prog.requiredJobTitles || []);
  return jt.length === 0 || jt.includes(emp.jobTitle || '');
}
// آخر سجل مكتمل ساري المفعول لبرنامج
function activeTrainingRecord(records, empId, programId, todayStr) {
  const td = todayStr || today();
  return (records || []).filter(r => r.employeeId === empId && r.programId === programId && r.status === 'completed')
    .filter(r => !r.expiryDate || r.expiryDate >= td)
    .sort((a, b) => ((a.completedDate || '') < (b.completedDate || '') ? 1 : -1))[0] || null;
}
// برامج إلزامية ينقص الموظف اجتيازها ساريةً
function missingRequiredTraining(programs, records, emp, todayStr) {
  return (programs || []).filter(p => programRequiredFor(p, emp)).filter(p => !activeTrainingRecord(records, emp.id, p.id, todayStr));
}
// سجلات مكتملة تنتهي خلال days (أو منتهية) — للتنبيهات والمصفوفة
function expiringTraining(records, days, todayStr) {
  const td = todayStr || today(); const lim = addMonthsStr(td, 0);
  const cutoff = (() => { const d = new Date(td + 'T00:00:00'); d.setDate(d.getDate() + (Number(days) || 0)); return d.toISOString().slice(0, 10); })();
  void lim;
  return (records || []).filter(r => r.status === 'completed' && r.expiryDate && r.expiryDate <= cutoff);
}

function Training({ org, ops, me, myBranches, commit, commitOrg, say }) {
  const role = ROLES[me.role] || {};
  const isAll = role.scope === 'all';
  const canManage = me.role === 'branch_manager' || isAll;   // تسجيل/تحديث سجلات التدريب
  const canConfig = isAll;                                   // البرامج المركزية
  const branches = myBranches || [];
  const pol = { ...defaultHrPolicies(), ...(org.hrPolicies || {}) };
  const alertDays = Number(pol.trainingExpiryAlertDays) || 30;
  const programs = (org.trainingPrograms && org.trainingPrograms.length) ? org.trainingPrograms : defaultTrainingPrograms();
  const td = today();

  const [view, setView] = useState('records');
  const [branchId, setBranchId] = useState((branches[0] || {}).id || '');
  useEffect(() => { if (!branches.find(b => b.id === branchId)) setBranchId((branches[0] || {}).id || ''); }, [branches, branchId]); // eslint-disable-line
  const branch = branches.find(b => b.id === branchId) || null;
  const branchIds = branches.map(b => b.id);
  const emps = (org.employees || []).filter(e => e.isActive !== false && branch && e.branchId === branch.id);
  const allRecs = (ops.hrTraining || []).filter(r => branchIds.includes(r.branchId)).sort((a, b) => ((a.completedDate || a.plannedDate || '') < (b.completedDate || b.plannedDate || '') ? 1 : -1));
  const progById = (id) => programs.find(p => p.id === id) || null;
  const statusBadge = (st) => { const cls = st === 'completed' ? 'b-mint' : st === 'expired' ? 'b-rose' : st === 'in_progress' ? 'b-sky' : 'b-amber'; return <span className={'badge ' + cls}>{TRAIN_STATUS_AR[st] || st}</span>; };

  // ===== ١) تسجيل/تحديث سجل تدريب =====
  const emptyF = { id: '', empId: '', programId: '', status: 'completed', plannedDate: td, completedDate: td, score: '', result: 'pass', certNo: '', note: '' };
  const [f, setF] = useState(emptyF);
  const selProg = progById(f.programId);
  const previewExpiry = (f.status === 'completed' && selProg) ? trainingExpiryOf(f.completedDate, selProg.validityMonths) : '';
  const editRec = (r) => setF({ id: r.id, empId: r.employeeId, programId: r.programId, status: r.status, plannedDate: r.plannedDate || td, completedDate: r.completedDate || td, score: r.score != null ? String(r.score) : '', result: r.result || '', certNo: r.certNo || '', note: r.note || '' });
  const submit = async () => {
    if (!branch) return;
    const emp = emps.find(e => e.id === f.empId); const prog = progById(f.programId);
    if (!emp) return say('اختر الموظف', 'no');
    if (!prog) return say('اختر البرنامج التدريبي', 'no');
    const completedDate = f.status === 'completed' ? (f.completedDate || td) : '';
    const rec = {
      id: f.id || uid('tr'), branchId: branch.id, branchName: branch.name, employeeId: emp.id, employeeName: emp.name,
      programId: prog.id, programTitle: prog.title, status: f.status,
      plannedDate: f.plannedDate || '', completedDate, expiryDate: trainingExpiryOf(completedDate, prog.validityMonths),
      score: f.score === '' ? null : Number(f.score), result: f.status === 'completed' ? (f.result || 'pass') : '', certNo: (f.certNo || '').trim(), note: (f.note || '').trim(),
      recordedBy: me.id, recordedByName: me.name, recordedAt: nowISO()
    };
    const ok = await commit(d => ({ ...d, hrTraining: f.id ? (d.hrTraining || []).map(x => x.id === f.id ? rec : x) : [rec, ...(d.hrTraining || [])] }),
      { actionType: f.id ? 'update' : 'create', targetType: 'training_record', targetId: rec.id, branchName: branch.name, title: (f.id ? 'تحديث' : 'تسجيل') + ' سجل تدريب', details: emp.name + ' · ' + prog.title + ' · ' + (TRAIN_STATUS_AR[rec.status] || rec.status) + (rec.expiryDate ? ' · ينتهي ' + rec.expiryDate : '') });
    if (ok) { say('حُفظ سجل التدريب ✓'); setF({ ...emptyF, plannedDate: f.plannedDate, completedDate: f.completedDate }); }
  };
  const delRec = async (r) => {
    if (!window.confirm('حذف سجل تدريب «' + r.programTitle + '» لـ' + r.employeeName + '؟')) return;
    await commit(d => ({ ...d, hrTraining: (d.hrTraining || []).filter(x => x.id !== r.id) }),
      { actionType: 'delete', targetType: 'training_record', targetId: r.id, branchName: r.branchName, title: 'حذف سجل تدريب', details: r.employeeName + ' · ' + r.programTitle });
    say('حُذف السجل');
  };

  // ===== ٢) البرامج (المركز) =====
  const [cf, setCf] = useState(() => programs.map(p => ({ ...p, requiredJobTitles: (p.requiredJobTitles || []).join('، ') })));
  const saveProgs = async () => {
    const list = (cf || []).filter(p => String(p.title || '').trim()).map(p => ({
      id: (p.id || uid('tp')), title: p.title.trim(), category: (p.category || '').trim(), validityMonths: Number(p.validityMonths) || 0,
      mandatory: !!p.mandatory, requiredJobTitles: String(p.requiredJobTitles || '').split(/[،,]/).map(s => s.trim()).filter(Boolean), provider: (p.provider || '').trim()
    }));
    const ok = await commitOrg(d => ({ ...d, trainingPrograms: list }),
      { actionType: 'update', targetType: 'settings', targetId: 'trainingPrograms', title: 'ضبط البرامج التدريبية', details: list.length + ' برنامجًا · ' + list.filter(p => p.mandatory).length + ' إلزامي' });
    if (ok) say('حُفظت البرامج ✓');
  };

  if (!branch && branches.length === 0) return <div className="card"><div className="empty">لا يوجد فرع مُسند لحسابك — راجع مسؤول النظام.</div></div>;

  // بيانات المصفوفة: الموظفون × البرامج الإلزامية المنطبقة
  const mandProgs = programs.filter(p => p.mandatory);
  const cellFor = (emp, prog) => {
    if (!programRequiredFor(prog, emp)) return { t: 'na', ar: '—', cls: 'b-dim' };
    const rec = activeTrainingRecord(ops.hrTraining || [], emp.id, prog.id, td);
    if (!rec) return { t: 'missing', ar: 'مفقود', cls: 'b-rose' };
    if (rec.expiryDate) {
      const soon = (() => { const d = new Date(td + 'T00:00:00'); d.setDate(d.getDate() + alertDays); return rec.expiryDate <= d.toISOString().slice(0, 10); })();
      if (soon) return { t: 'soon', ar: 'ينتهي ' + rec.expiryDate, cls: 'b-amber' };
      return { t: 'ok', ar: 'ساري حتى ' + rec.expiryDate, cls: 'b-mint' };
    }
    return { t: 'ok', ar: 'مكتمل', cls: 'b-mint' };
  };

  return (
    <div className="grid" style={{ gap: 12 }}>
      <div className="card" style={{ padding: '8px 12px' }}>
        <div className="row" style={{ gap: 6, flexWrap: 'wrap', justifyContent: 'space-between' }}>
          <div className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
            <button className={'btn sm' + (view === 'records' ? ' pri' : ' gh')} onClick={() => setView('records')}><Stamp size={13} />سجل التدريب</button>
            <button className={'btn sm' + (view === 'matrix' ? ' pri' : ' gh')} onClick={() => setView('matrix')}><ClipboardCheck size={13} />مصفوفة الامتثال</button>
            {canConfig && <button className={'btn sm' + (view === 'programs' ? ' pri' : ' gh')} onClick={() => setView('programs')}><FileText size={13} />البرامج</button>}
          </div>
          {branches.length > 1 && view !== 'programs' && (
            <select className="inp sel" style={{ width: 180 }} value={branchId} onChange={e => setBranchId(e.target.value)}>
              {branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
            </select>
          )}
        </div>
      </div>

      {view === 'records' && branch && (
        <div className="grid" style={{ gap: 12 }}>
          {canManage && (
            <div className="card">
              <div className="card-t" style={{ marginBottom: 8 }}><Stamp size={15} color="var(--brass)" />{f.id ? 'تحديث سجل تدريب' : 'تسجيل تدريب/شهادة'} — {branch.name}</div>
              <div className="note" style={{ marginBottom: 8 }}>سجّل اجتياز الموظف برنامجًا تدريبيًا أو شهادة؛ يُحسب تاريخ الانتهاء تلقائيًا من مدة صلاحية البرنامج، وتظهر الشهادات المنتهية قريبًا في مركز التنبيهات ومصفوفة الامتثال.</div>
              <div className="grid g3">
                <Field label="الموظف"><select className="inp sel" value={f.empId} onChange={e => setF(x => ({ ...x, empId: e.target.value }))}><option value="">اختر</option>{emps.map(e => <option key={e.id} value={e.id}>{e.name}{e.jobTitle ? ' — ' + e.jobTitle : ''}</option>)}</select></Field>
                <Field label="البرنامج"><select className="inp sel" value={f.programId} onChange={e => setF(x => ({ ...x, programId: e.target.value }))}><option value="">اختر</option>{programs.map(p => <option key={p.id} value={p.id}>{p.title}{p.mandatory ? ' (إلزامي)' : ''}</option>)}</select></Field>
                <Field label="الحالة"><select className="inp sel" value={f.status} onChange={e => setF(x => ({ ...x, status: e.target.value }))}><option value="planned">مجدول</option><option value="in_progress">جارٍ</option><option value="completed">مكتمل</option></select></Field>
                {f.status !== 'completed' && <Field label="تاريخ الجدولة"><input type="date" className="inp" value={f.plannedDate} onChange={e => setF(x => ({ ...x, plannedDate: e.target.value }))} /></Field>}
                {f.status === 'completed' && <Field label="تاريخ الإكمال"><input type="date" className="inp" value={f.completedDate} onChange={e => setF(x => ({ ...x, completedDate: e.target.value }))} /></Field>}
                {f.status === 'completed' && <Field label="النتيجة"><select className="inp sel" value={f.result} onChange={e => setF(x => ({ ...x, result: e.target.value }))}><option value="pass">اجتياز</option><option value="fail">عدم اجتياز</option></select></Field>}
                {f.status === 'completed' && <Field label="الدرجة (اختياري)"><input className="inp n" inputMode="numeric" value={f.score} onChange={e => setF(x => ({ ...x, score: e.target.value.replace(/\D/g, '') }))} /></Field>}
                {f.status === 'completed' && <Field label="رقم الشهادة (اختياري)"><input className="inp" value={f.certNo} onChange={e => setF(x => ({ ...x, certNo: e.target.value }))} /></Field>}
                <Field label="ملاحظة (اختياري)" style={{ gridColumn: 'span 2' }}><input className="inp" value={f.note} onChange={e => setF(x => ({ ...x, note: e.target.value }))} /></Field>
              </div>
              {previewExpiry && <div className="note" style={{ marginTop: 8 }}>تاريخ انتهاء الشهادة المحسوب: <b>{previewExpiry}</b> (مدة الصلاحية {selProg.validityMonths} شهرًا).</div>}
              {f.status === 'completed' && selProg && !(selProg.validityMonths > 0) && <div className="note" style={{ marginTop: 8 }}>هذا البرنامج بلا تاريخ انتهاء.</div>}
              <div className="row" style={{ justifyContent: 'flex-end', gap: 6, marginTop: 10 }}>
                {f.id && <button className="btn gh" onClick={() => setF(emptyF)}>إلغاء التحرير</button>}
                <button className="btn pri" onClick={submit}><Check size={14} />{f.id ? 'تحديث' : 'حفظ'}</button>
              </div>
            </div>
          )}
          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}>سجل تدريب {branch.name}</div>
            <div className="tw">
              <table className="tb">
                <thead><tr><th>الموظف</th><th>البرنامج</th><th>الحالة</th><th>الإكمال</th><th>الانتهاء</th><th>النتيجة</th><th>الشهادة</th>{canManage && <th />}</tr></thead>
                <tbody>
                  {allRecs.filter(r => r.branchId === branch.id).map(r => { const st = trainingStatusNow(r, td); return (
                    <tr key={r.id}>
                      <td style={{ fontWeight: 600, fontSize: 12.5 }}>{r.employeeName}</td>
                      <td style={{ fontSize: 12 }}>{r.programTitle}</td>
                      <td>{statusBadge(st)}</td>
                      <td className="num" style={{ fontSize: 11.5 }}>{r.completedDate || '—'}</td>
                      <td className="num" style={{ fontSize: 11.5 }}>{r.expiryDate || '—'}</td>
                      <td style={{ fontSize: 11.5 }}>{r.result === 'pass' ? 'اجتياز' : r.result === 'fail' ? 'عدم اجتياز' : '—'}{r.score != null ? ' · ' + r.score : ''}</td>
                      <td style={{ fontSize: 11.5 }}>{r.certNo || '—'}</td>
                      {canManage && <td><div className="row" style={{ gap: 4 }}><button className="btn sm gh" onClick={() => editRec(r)}>تحرير</button><button className="btn sm gh" onClick={() => delRec(r)}><Trash2 size={13} /></button></div></td>}
                    </tr>
                  ); })}
                  {allRecs.filter(r => r.branchId === branch.id).length === 0 && <tr><td colSpan={canManage ? 8 : 7}><div className="empty">لا سجلات تدريب بعد.</div></td></tr>}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {view === 'matrix' && branch && (
        <div className="card">
          <div className="card-t" style={{ marginBottom: 8 }}><ClipboardCheck size={15} color="var(--brass)" />مصفوفة الامتثال للتدريب الإلزامي — {branch.name}</div>
          <div className="note" style={{ marginBottom: 8 }}>لكل موظف والبرامج الإلزامية المنطبقة على مسماه: <span className="badge b-mint">ساري</span> <span className="badge b-amber">ينتهي خلال {alertDays} يومًا</span> <span className="badge b-rose">مفقود/منتهٍ</span> <span className="badge b-dim">غير مطلوب</span>.</div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>الموظف</th>{mandProgs.map(p => <th key={p.id} style={{ fontSize: 11 }}>{p.title}</th>)}</tr></thead>
              <tbody>
                {emps.map(e => (
                  <tr key={e.id}>
                    <td style={{ fontWeight: 600, fontSize: 12.5 }}>{e.name}<div style={{ fontSize: 10, color: 'var(--faint)' }}>{e.jobTitle || ''}</div></td>
                    {mandProgs.map(p => { const c = cellFor(e, p); return <td key={p.id}><span className={'badge ' + c.cls} style={{ fontSize: 9.5 }}>{c.ar}</span></td>; })}
                  </tr>
                ))}
                {emps.length === 0 && <tr><td colSpan={mandProgs.length + 1}><div className="empty">لا موظفين نشطين.</div></td></tr>}
                {mandProgs.length === 0 && <tr><td colSpan={1}><div className="empty">لا برامج إلزامية معرَّفة — أضِفها من «البرامج».</div></td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {view === 'programs' && canConfig && (
        <div className="card">
          <div className="card-t" style={{ marginBottom: 6 }}><FileText size={15} color="var(--brass)" />البرامج التدريبية والشهادات</div>
          <div className="note" style={{ marginBottom: 10 }}>عرِّف برامجك وشهاداتك ومدد صلاحيتها. البرامج «الإلزامية» تدخل مصفوفة الامتثال وتنبيهات النقص؛ حصر «المسميات المطلوبة» (مفصولة بفواصل) يقصر الإلزام على تلك المسميات — واتركه فارغًا ليشمل الجميع. المدد الافتراضية مبنية على متطلبات السعودية (الشهادة الصحية سنة)، وهي قابلة للضبط حسب لائحة الجهة الرسمية.</div>
          <div className="grid" style={{ gap: 8 }}>
            {cf.map((p, i) => (
              <div key={i} className="card" style={{ padding: 10, border: '1px solid var(--frame-o)' }}>
                <div className="row" style={{ gap: 6, alignItems: 'flex-end', flexWrap: 'wrap' }}>
                  <Field label="البرنامج/الشهادة" style={{ flex: 2, minWidth: 180 }}><input className="inp" value={p.title} onChange={e => setCf(x => x.map((y, j) => j === i ? { ...y, title: e.target.value } : y))} /></Field>
                  <Field label="التصنيف"><input className="inp" style={{ width: 120 }} value={p.category} onChange={e => setCf(x => x.map((y, j) => j === i ? { ...y, category: e.target.value } : y))} /></Field>
                  <Field label="الصلاحية (شهر، 0=دائم)"><input className="inp n" style={{ width: 120 }} inputMode="numeric" value={p.validityMonths} onChange={e => setCf(x => x.map((y, j) => j === i ? { ...y, validityMonths: e.target.value.replace(/\D/g, '') } : y))} /></Field>
                  <button className="btn sm gh" onClick={() => setCf(x => x.filter((_, j) => j !== i))}><Trash2 size={13} /></button>
                </div>
                <div className="row" style={{ gap: 6, alignItems: 'flex-end', flexWrap: 'wrap', marginTop: 6 }}>
                  <label className="row" style={{ gap: 6, fontSize: 12.5, cursor: 'pointer' }}><input type="checkbox" checked={!!p.mandatory} onChange={e => setCf(x => x.map((y, j) => j === i ? { ...y, mandatory: e.target.checked } : y))} />إلزامي</label>
                  <Field label="المسميات المطلوبة (فارغ=الجميع)" style={{ flex: 2, minWidth: 180 }}><input className="inp" value={p.requiredJobTitles} onChange={e => setCf(x => x.map((y, j) => j === i ? { ...y, requiredJobTitles: e.target.value } : y))} placeholder="مثال: شيف، مشرف" /></Field>
                  <Field label="الجهة"><input className="inp" style={{ width: 160 }} value={p.provider} onChange={e => setCf(x => x.map((y, j) => j === i ? { ...y, provider: e.target.value } : y))} /></Field>
                </div>
              </div>
            ))}
            <div><button className="btn sm gh" onClick={() => setCf(x => [...x, { id: '', title: '', category: '', validityMonths: 0, mandatory: false, requiredJobTitles: '', provider: '' }])}><Plus size={13} />برنامج</button></div>
          </div>
          <div className="row" style={{ justifyContent: 'flex-end', marginTop: 12 }}><button className="btn pri" onClick={saveProgs}><Check size={14} />حفظ البرامج</button></div>
        </div>
      )}
    </div>
  );
}


/* ================= م١١ (v27.9) — مكتبة مؤشرات الأداء لكل دور (Role KPIs) =================
   نموذج البيانات:
   - org.roleKpis[] (إعداد مركزي، يصل الفروع عبر dirOf): { id, jobTitles[], title, unit, direction:'higher'|'lower', target, weight }
   - ops.hrKpiEntries[] (BR_COLS — بفرعها): { id, branchId, employeeId, employeeName, ym, values:{kpiId:number}, recordedBy/Name, recordedAt }
   - org.hrPolicies.roleKpiEnabled (افتراضي false) + roleKpiWeight (وزن المحور في الدرجة المركّبة م٧ عند التفعيل).
   التكامل: عند التفعيل فقط يُضاف محور roleKpi إلى hrScoreFor؛ وهو مُعطَّل افتراضيًا فلا يغيّر أي درجة قائمة.
   ========================================================================================= */
function defaultRoleKpis() {
  return [
    { id: 'cash_var', jobTitles: ['كاشير'], title: 'دقة النقدية (إجمالي الفروقات شهريًا)', unit: 'ريال', direction: 'lower', target: 0, weight: 40 },
    { id: 'avg_ticket', jobTitles: ['كاشير'], title: 'متوسط قيمة الطلب', unit: 'ريال', direction: 'higher', target: 50, weight: 30 },
    { id: 'food_quality', jobTitles: ['شيف', 'مساعد شيف'], title: 'الالتزام بمعايير الجودة', unit: '%', direction: 'higher', target: 95, weight: 50 },
    { id: 'waste', jobTitles: ['شيف', 'مساعد شيف'], title: 'نسبة الهدر', unit: '%', direction: 'lower', target: 5, weight: 30 },
    { id: 'prep_time', jobTitles: [], title: 'زمن تجهيز الطلب', unit: 'دقيقة', direction: 'lower', target: 8, weight: 20 },
    { id: 'csat', jobTitles: [], title: 'رضا العملاء', unit: '%', direction: 'higher', target: 90, weight: 30 },
  ];
}
// نسبة تحقّق مؤشر واحد (0–100) وفق الاتجاه والهدف
function kpiAchievement(actual, target, direction) {
  const a = Number(actual), tgt = Number(target) || 0;
  if (actual == null || actual === '' || isNaN(a)) return null;
  if (direction === 'lower') {
    if (a <= tgt) return 100;
    if (tgt <= 0) return 0;                 // الهدف صفر وتجاوزه ⇒ 0
    return Math.max(0, Math.round(tgt / a * 100));
  }
  if (tgt <= 0) return a > 0 ? 100 : 0;
  return Math.max(0, Math.min(100, Math.round(a / tgt * 100)));
}
// مؤشرات منطبقة على مسمى الموظف (فارغة jobTitles ⇒ للجميع)
function roleKpisFor(org, emp) {
  const kpis = (org.roleKpis && org.roleKpis.length) ? org.roleKpis : defaultRoleKpis();
  return kpis.filter(k => !(k.jobTitles || []).length || (k.jobTitles || []).includes(emp.jobTitle || ''));
}
// درجة KPI بالدور لموظف/شهر (مُشتقّة): متوسط مرجّح لنسب التحقّق للمؤشرات المُدخَلة
function hrRoleKpiScore(org, ops, emp, ym) {
  const kpis = roleKpisFor(org, emp);
  const entry = (ops.hrKpiEntries || []).find(e => e.employeeId === emp.id && e.ym === ym) || null;
  const vals = (entry && entry.values) || {};
  let num = 0, den = 0; const items = [];
  kpis.forEach(k => {
    const w = Number(k.weight) || 0;
    const ach = kpiAchievement(vals[k.id], k.target, k.direction);
    items.push({ kpi: k, actual: vals[k.id], ach });
    if (ach != null && w > 0) { num += ach * w; den += w; }
  });
  return { score: den ? Math.round(num / den) : null, items, hasEntry: !!entry };
}

function RoleKpi({ org, ops, me, myBranches, commit, commitOrg, say }) {
  const role = ROLES[me.role] || {};
  const isAll = role.scope === 'all';
  const canManage = me.role === 'branch_manager' || isAll;   // إدخال قياسات الشهر
  const canConfig = isAll;                                   // المكتبة والتفعيل
  const branches = myBranches || [];
  const pol = { ...defaultHrPolicies(), ...(org.hrPolicies || {}) };
  const kpisAll = (org.roleKpis && org.roleKpis.length) ? org.roleKpis : defaultRoleKpis();

  const [view, setView] = useState('entry');
  const [branchId, setBranchId] = useState((branches[0] || {}).id || '');
  useEffect(() => { if (!branches.find(b => b.id === branchId)) setBranchId((branches[0] || {}).id || ''); }, [branches, branchId]); // eslint-disable-line
  const branch = branches.find(b => b.id === branchId) || null;
  const emps = (org.employees || []).filter(e => e.isActive !== false && branch && e.branchId === branch.id);
  const [ym, setYm] = useState(() => today().slice(0, 7));
  const ymLabel = (y) => { const [Y, M] = String(y).split('-').map(Number); return isNaN(Y) ? y : new Date(Y, M - 1, 1).toLocaleDateString('ar', { month: 'long', year: 'numeric' }); };

  // ===== ١) إدخال القياسات الشهرية =====
  const [empId, setEmpId] = useState('');
  useEffect(() => { if (!emps.find(e => e.id === empId)) setEmpId((emps[0] || {}).id || ''); }, [branchId, emps.length]); // eslint-disable-line
  const selEmp = emps.find(e => e.id === empId) || null;
  const empKpis = selEmp ? roleKpisFor(org, selEmp) : [];
  const existing = selEmp ? (ops.hrKpiEntries || []).find(e => e.employeeId === selEmp.id && e.ym === ym) : null;
  const [vals, setVals] = useState({});
  useEffect(() => { setVals((existing && existing.values) ? { ...existing.values } : {}); }, [empId, ym, existing && existing.id]); // eslint-disable-line
  const liveScore = selEmp ? (() => { let num = 0, den = 0; empKpis.forEach(k => { const ach = kpiAchievement(vals[k.id], k.target, k.direction); const w = Number(k.weight) || 0; if (ach != null && w > 0) { num += ach * w; den += w; } }); return den ? Math.round(num / den) : null; })() : null;
  const saveEntry = async () => {
    if (!branch || !selEmp) return say('اختر الموظف', 'no');
    const clean = {}; Object.keys(vals).forEach(k => { if (vals[k] !== '' && vals[k] != null) clean[k] = Number(vals[k]); });
    if (!Object.keys(clean).length) return say('أدخل قيمة مؤشر واحد على الأقل', 'no');
    const rec = existing
      ? { ...existing, values: clean, recordedBy: me.id, recordedByName: me.name, recordedAt: nowISO() }
      : { id: uid('kpi'), branchId: branch.id, branchName: branch.name, employeeId: selEmp.id, employeeName: selEmp.name, ym, values: clean, recordedBy: me.id, recordedByName: me.name, recordedAt: nowISO() };
    const ok = await commit(d => ({ ...d, hrKpiEntries: existing ? (d.hrKpiEntries || []).map(x => x.id === existing.id ? rec : x) : [rec, ...(d.hrKpiEntries || [])] }),
      { actionType: existing ? 'update' : 'create', targetType: 'kpi_entry', targetId: rec.id, branchName: branch.name, title: 'قياسات KPI شهرية', details: selEmp.name + ' · ' + ymLabel(ym) + ' · ' + Object.keys(clean).length + ' مؤشر' });
    if (ok) say('حُفظت القياسات ✓');
  };

  // ===== ٢) المكتبة + التفعيل (المركز) =====
  const [cf, setCf] = useState(() => ({
    roleKpiEnabled: !!pol.roleKpiEnabled, roleKpiWeight: String(Number(pol.roleKpiWeight) || 20),
    kpis: kpisAll.map(k => ({ ...k, jobTitles: (k.jobTitles || []).join('، '), target: String(k.target), weight: String(k.weight) }))
  }));
  const saveLib = async () => {
    const list = (cf.kpis || []).filter(k => String(k.title || '').trim()).map(k => ({
      id: k.id || uid('rk'), title: k.title.trim(), unit: (k.unit || '').trim(), direction: k.direction === 'lower' ? 'lower' : 'higher',
      target: Number(k.target) || 0, weight: Number(k.weight) || 0,
      jobTitles: String(k.jobTitles || '').split(/[،,]/).map(s => s.trim()).filter(Boolean)
    }));
    const ok = await commitOrg(d => ({ ...d, roleKpis: list, hrPolicies: { ...defaultHrPolicies(), ...(d.hrPolicies || {}), roleKpiEnabled: !!cf.roleKpiEnabled, roleKpiWeight: Number(cf.roleKpiWeight) || 0 } }),
      { actionType: 'update', targetType: 'settings', targetId: 'roleKpis', title: 'ضبط مكتبة مؤشرات الأداء بالدور', details: list.length + ' مؤشر · ' + (cf.roleKpiEnabled ? 'مفعّل بوزن ' + (Number(cf.roleKpiWeight) || 0) : 'غير مفعّل في الدرجة') });
    if (ok) say('حُفظت المكتبة ✓');
  };

  if (!branch && branches.length === 0) return <div className="card"><div className="empty">لا يوجد فرع مُسند لحسابك — راجع مسؤول النظام.</div></div>;

  const achBadge = (ach) => ach == null ? <span className="badge b-dim">—</span> : <span className={'badge ' + (ach >= 85 ? 'b-mint' : ach >= 60 ? 'b-amber' : 'b-rose')}>{ach}%</span>;

  return (
    <div className="grid" style={{ gap: 12 }}>
      <div className="card" style={{ padding: '8px 12px' }}>
        <div className="row" style={{ gap: 6, flexWrap: 'wrap', justifyContent: 'space-between' }}>
          <div className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
            <button className={'btn sm' + (view === 'entry' ? ' pri' : ' gh')} onClick={() => setView('entry')}><TrendingUp size={13} />التقييم الشهري</button>
            {canConfig && <button className={'btn sm' + (view === 'library' ? ' pri' : ' gh')} onClick={() => setView('library')}><FileText size={13} />المكتبة والتفعيل</button>}
          </div>
          <div className="row" style={{ gap: 8 }}>
            {view === 'entry' && <input type="month" className="inp" value={ym} onChange={e => setYm(e.target.value)} />}
            {branches.length > 1 && view === 'entry' && (
              <select className="inp sel" style={{ width: 180 }} value={branchId} onChange={e => setBranchId(e.target.value)}>
                {branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
              </select>
            )}
          </div>
        </div>
      </div>

      {view === 'entry' && branch && (
        <div className="grid" style={{ gap: 12 }}>
          {!pol.roleKpiEnabled && <div className="note" style={{ color: 'var(--amber)' }}>محور مؤشرات الدور غير مفعّل في درجة الأداء المركّبة (م٧) — يمكنك إدخال القياسات الآن، لكنها لن تؤثّر في الدرجة حتى يفعّلها المركز من «المكتبة والتفعيل». هذا مقصود كي لا تتغيّر الدرجات القائمة قبل مراجعتك.</div>}
          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}><TrendingUp size={15} color="var(--brass)" />قياسات مؤشرات الأداء — {branch.name} · {ymLabel(ym)}</div>
            <div className="grid g3" style={{ marginBottom: 8 }}>
              <Field label="الموظف"><select className="inp sel" value={empId} onChange={e => setEmpId(e.target.value)}><option value="">اختر</option>{emps.map(e => <option key={e.id} value={e.id}>{e.name}{e.jobTitle ? ' — ' + e.jobTitle : ''}</option>)}</select></Field>
              {selEmp && <div style={{ alignSelf: 'flex-end' }}><span className="badge b-dim">درجة KPI: </span> {achBadge(liveScore)}</div>}
            </div>
            {selEmp ? (empKpis.length ? (
              <div className="tw">
                <table className="tb">
                  <thead><tr><th>المؤشر</th><th>الاتجاه</th><th>الهدف</th><th>الفعلي</th><th>الوزن</th><th>التحقّق</th></tr></thead>
                  <tbody>
                    {empKpis.map(k => { const ach = kpiAchievement(vals[k.id], k.target, k.direction); return (
                      <tr key={k.id}>
                        <td style={{ fontWeight: 600, fontSize: 12.5 }}>{k.title}{k.unit ? <span style={{ fontSize: 10.5, color: 'var(--faint)' }}> ({k.unit})</span> : null}</td>
                        <td style={{ fontSize: 11.5 }}>{k.direction === 'lower' ? 'الأقل أفضل' : 'الأعلى أفضل'}</td>
                        <td className="num">{k.target}</td>
                        <td style={{ width: 120 }}><input className="inp n" inputMode="decimal" value={vals[k.id] == null ? '' : vals[k.id]} onChange={e => setVals(v => ({ ...v, [k.id]: e.target.value.replace(/[^\d.]/g, '') }))} /></td>
                        <td className="num">{k.weight}</td>
                        <td>{achBadge(ach)}</td>
                      </tr>
                    ); })}
                  </tbody>
                </table>
              </div>
            ) : <div className="empty">لا مؤشرات منطبقة على مسمى «{selEmp.jobTitle || '—'}» — أضِف مؤشرات في المكتبة أو اترك مسمياتها فارغة لتشمل الجميع.</div>) : <div className="empty">اختر موظفًا لإدخال قياساته.</div>}
            {selEmp && empKpis.length > 0 && canManage && (
              <div className="row" style={{ justifyContent: 'flex-end', marginTop: 10 }}><button className="btn pri" onClick={saveEntry}><Check size={14} />حفظ القياسات</button></div>
            )}
          </div>
        </div>
      )}

      {view === 'library' && canConfig && (
        <div className="grid" style={{ gap: 12 }}>
          <div className="card">
            <div className="card-t" style={{ marginBottom: 6 }}><TrendingUp size={15} color="var(--brass)" />تفعيل المحور في درجة الأداء</div>
            <div className="note" style={{ marginBottom: 8 }}>عند التفعيل يُضاف «مؤشرات الدور» محورًا خامسًا في درجة الأداء المركّبة (م٧) بالوزن المحدَّد — تُطبَّع الدرجة تلقائيًا مع بقية المحاور المتوفّرة. مُعطَّل افتراضيًا كي لا يغيّر أي درجة قائمة قبل مراجعتك.</div>
            <div className="row" style={{ gap: 12, flexWrap: 'wrap', alignItems: 'flex-end' }}>
              <label className="row" style={{ gap: 6, cursor: 'pointer' }}><input type="checkbox" checked={!!cf.roleKpiEnabled} onChange={e => setCf(x => ({ ...x, roleKpiEnabled: e.target.checked }))} /><b>تفعيل محور مؤشرات الدور في الدرجة</b></label>
              <Field label="وزن المحور"><input className="inp n" style={{ width: 100 }} inputMode="numeric" value={cf.roleKpiWeight} onChange={e => setCf(x => ({ ...x, roleKpiWeight: e.target.value.replace(/\D/g, '') }))} /></Field>
            </div>
          </div>
          <div className="card">
            <div className="card-t" style={{ marginBottom: 6 }}><FileText size={15} color="var(--brass)" />مكتبة مؤشرات الأداء لكل دور</div>
            <div className="note" style={{ marginBottom: 8 }}>عرّف مؤشرات كل مسمى وظيفي وهدفه ووزنه واتجاهه (الأعلى/الأقل أفضل). «المسميات» مفصولة بفواصل — فارغة تعني «لكل المسميات». الوزن نسبي داخل مؤشرات الموظف نفسه.</div>
            <div className="grid" style={{ gap: 8 }}>
              {cf.kpis.map((k, i) => (
                <div key={i} className="card" style={{ padding: 10, border: '1px solid var(--frame-o)' }}>
                  <div className="row" style={{ gap: 6, alignItems: 'flex-end', flexWrap: 'wrap' }}>
                    <Field label="المؤشر" style={{ flex: 2, minWidth: 180 }}><input className="inp" value={k.title} onChange={e => setCf(x => ({ ...x, kpis: x.kpis.map((y, j) => j === i ? { ...y, title: e.target.value } : y) }))} /></Field>
                    <Field label="الوحدة"><input className="inp" style={{ width: 90 }} value={k.unit} onChange={e => setCf(x => ({ ...x, kpis: x.kpis.map((y, j) => j === i ? { ...y, unit: e.target.value } : y) }))} /></Field>
                    <Field label="الاتجاه"><select className="inp sel" style={{ width: 130 }} value={k.direction} onChange={e => setCf(x => ({ ...x, kpis: x.kpis.map((y, j) => j === i ? { ...y, direction: e.target.value } : y) }))}><option value="higher">الأعلى أفضل</option><option value="lower">الأقل أفضل</option></select></Field>
                    <Field label="الهدف"><input className="inp n" style={{ width: 90 }} inputMode="decimal" value={k.target} onChange={e => setCf(x => ({ ...x, kpis: x.kpis.map((y, j) => j === i ? { ...y, target: e.target.value.replace(/[^\d.]/g, '') } : y) }))} /></Field>
                    <Field label="الوزن"><input className="inp n" style={{ width: 80 }} inputMode="numeric" value={k.weight} onChange={e => setCf(x => ({ ...x, kpis: x.kpis.map((y, j) => j === i ? { ...y, weight: e.target.value.replace(/\D/g, '') } : y) }))} /></Field>
                    <button className="btn sm gh" onClick={() => setCf(x => ({ ...x, kpis: x.kpis.filter((_, j) => j !== i) }))}><Trash2 size={13} /></button>
                  </div>
                  <Field label="المسميات المنطبقة (فارغ = الجميع)" style={{ marginTop: 6 }}><input className="inp" value={k.jobTitles} onChange={e => setCf(x => ({ ...x, kpis: x.kpis.map((y, j) => j === i ? { ...y, jobTitles: e.target.value } : y) }))} placeholder="مثال: كاشير، شيف" /></Field>
                </div>
              ))}
              <div><button className="btn sm gh" onClick={() => setCf(x => ({ ...x, kpis: [...x.kpis, { id: '', title: '', unit: '', direction: 'higher', target: '0', weight: '20', jobTitles: '' }] }))}><Plus size={13} />مؤشر</button></div>
            </div>
            <div className="row" style={{ justifyContent: 'flex-end', marginTop: 12 }}><button className="btn pri" onClick={saveLib}><Check size={14} />حفظ المكتبة والتفعيل</button></div>
          </div>
        </div>
      )}
    </div>
  );
}


/* ================= م٦/§٣٢ (v27.10) — تجميد الأداء الشهري + كشف التلاعب =================
   نموذج البيانات: ops.hrScoreSnapshots[] (CORE_COLS — مركزي فقط، لا تكتبه/تقرؤه أجهزة الفروع):
   { id, ym, createdAt, createdBy, createdByName, locked:true,
     meta:{ weightsEnabled, roleKpiEnabled, roleKpiWeight, weights },
     rows:[{ employeeId, employeeName, branchId, branchName, jobTitle, score, axes, st:{scheduled,onTime,late,absent,tasksExpected,tasksDone,manualPts,autoPts} }] }
   الغرض: تجميد درجة الأداء ومكوّناتها لحظة الاعتماد لقطةً ثابتة لا تُعاد حسابها؛ ومقارنة الحيّ بالمجمّد
   لكشف أي تغيّر رجعي في بيانات شهر مُعتمَد (منع التلاعب). التجميد يدوي مركزي؛ فكّ التجميد للمسؤول فقط بتدقيق.
   ======================================================================================= */
function frozenSnapshotFor(ops, ym) {
  return ((ops || {}).hrScoreSnapshots || []).find(s => s.ym === ym && s.locked) || null;
}

function PerfSnap({ org, ops, me, myBranches, commit, say }) {
  const role = ROLES[me.role] || {};
  const isAll = role.scope === 'all';
  const canFreeze = isAll;                 // التجميد: أدوار المركز
  const canUnlock = !!role.admin;          // فكّ التجميد: مسؤول النظام/الإدارة العليا فقط
  const td = today();
  const [ym, setYm] = useState(() => today().slice(0, 7));
  const ymLabel = (y) => { const [Y, M] = String(y).split('-').map(Number); return isNaN(Y) ? y : new Date(Y, M - 1, 1).toLocaleDateString('ar', { month: 'long', year: 'numeric' }); };
  const bName = (id) => ((org.branches || []).find(b => b.id === id) || {}).name || '';
  const snaps = ((ops.hrScoreSnapshots || [])).slice().sort((a, b) => (a.ym < b.ym ? 1 : -1));
  const frozen = frozenSnapshotFor(ops, ym);
  const activeEmps = () => (org.employees || []).filter(e => e.isActive !== false);

  const freeze = async () => {
    if (!canFreeze) return;
    if (!/^\d{4}-\d{2}$/.test(ym)) return say('اختر شهرًا صحيحًا', 'no');
    if (ym > td.slice(0, 7)) return say('لا يمكن تجميد شهر لم ينتهِ بعد', 'no');
    if (frozenSnapshotFor(ops, ym)) return say('هذا الشهر مجمّد بالفعل — فكّ التجميد أولًا لإعادته', 'no');
    const pol = { ...defaultHrPolicies(), ...(org.hrPolicies || {}) };
    const rows = activeEmps().map(e => {
      const sc = hrScoreFor(org, ops, e, ym);
      return {
        employeeId: e.id, employeeName: e.name, branchId: e.branchId || '', branchName: bName(e.branchId), jobTitle: e.jobTitle || '',
        score: sc.score, axes: sc.axes,
        st: { scheduled: sc.st.scheduled, onTime: sc.st.onTime, late: sc.st.late, absent: sc.st.absent, tasksExpected: sc.st.tasksExpected, tasksDone: sc.st.tasksDone, manualPts: sc.st.manualPts, autoPts: sc.st.autoPts }
      };
    });
    const rec = {
      id: uid('snap'), ym, createdAt: nowISO(), createdBy: me.id, createdByName: me.name, locked: true,
      meta: { weightsEnabled: !!pol.scoreWeightsEnabled, roleKpiEnabled: !!pol.roleKpiEnabled, roleKpiWeight: Number(pol.roleKpiWeight) || 0, weights: pol.scoreWeightsEnabled ? pol.scoreWeights : defaultHrPolicies().scoreWeights },
      rows
    };
    const ok = await commit(d => ({ ...d, hrScoreSnapshots: [rec, ...(d.hrScoreSnapshots || []).filter(s => !(s.ym === ym && s.locked))] }),
      { actionType: 'create', targetType: 'score_snapshot', targetId: rec.id, title: 'تجميد الأداء الشهري', details: ymLabel(ym) + ' · ' + rows.length + ' موظف · ' + rows.filter(r => r.score != null).length + ' بدرجة' });
    if (ok) say('جُمِّد أداء ' + ymLabel(ym) + ' ✓ — صار سجلًّا ثابتًا لا يُعاد حسابه');
  };
  const unlock = async (snap) => {
    if (!canUnlock) return say('فكّ التجميد لمسؤول النظام فقط', 'no');
    if (!window.confirm('فكّ تجميد ' + ymLabel(snap.ym) + '؟ سيعود الأداء للحساب الحيّ ويُفقد السجل الثابت لهذا الشهر (يُوثَّق في التدقيق).')) return;
    const ok = await commit(d => ({ ...d, hrScoreSnapshots: (d.hrScoreSnapshots || []).filter(s => s.id !== snap.id) }),
      { actionType: 'delete', targetType: 'score_snapshot', targetId: snap.id, title: 'فكّ تجميد الأداء الشهري', details: ymLabel(snap.ym) + ' · بواسطة ' + me.name });
    if (ok) say('فُكّ تجميد ' + ymLabel(snap.ym));
  };

  // مقارنة الحيّ بالمجمّد لكشف تغيّر رجعي
  const driftRows = frozen ? frozen.rows.map(r => {
    const emp = (org.employees || []).find(e => e.id === r.employeeId) || { id: r.employeeId, name: r.employeeName, branchId: r.branchId };
    const live = hrScoreFor(org, ops, emp, frozen.ym).score;
    return { ...r, live, drift: (r.score != null || live != null) && r.score !== live };
  }) : [];
  const driftN = driftRows.filter(r => r.drift).length;

  const AX = [['attendance', 'حضور'], ['tasks', 'مهام'], ['quality', 'جودة'], ['discipline', 'انضباط'], ['roleKpi', 'مؤشرات الدور']];
  const scoreBadge = (v) => v == null ? <span className="badge b-dim">—</span> : <span className={'badge ' + (v >= 85 ? 'b-mint' : v >= 70 ? 'b-amber' : 'b-rose')}>{v}</span>;

  const download = () => {
    if (!frozen) return;
    const head = ['الموظف', 'الفرع', 'المسمى', 'الدرجة المجمّدة', 'الدرجة الحيّة الآن', 'تغيّر', ...AX.map(a => a[1])];
    const lines = driftRows.map(r => [r.employeeName, r.branchName, r.jobTitle, r.score == null ? '' : r.score, r.live == null ? '' : r.live, r.drift ? 'نعم' : 'لا', ...AX.map(a => r.axes && r.axes[a[0]] != null ? r.axes[a[0]] : '')]);
    try { const blob = makeXlsx([{ name: 'أداء ' + frozen.ym, rows: [head, ...lines] }]); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'لقطة_الأداء_' + frozen.ym + '.xlsx'; document.body.appendChild(a); a.click(); document.body.removeChild(a); setTimeout(() => URL.revokeObjectURL(url), 1500); say('نُزّل ملف Excel ✓'); } catch { say('تعذّر التصدير', 'no'); }
  };

  if (!isAll) return <div className="card"><div className="empty">تجميد الأداء الشهري متاح لأدوار المركز فقط.</div></div>;

  return (
    <div className="grid" style={{ gap: 12 }}>
      <div className="card">
        <div className="card-h" style={{ flexWrap: 'wrap', gap: 8 }}>
          <div className="card-t"><Lock size={15} color="var(--brass)" />تجميد الأداء الشهري</div>
          <div className="row" style={{ gap: 8, flexWrap: 'wrap' }}>
            <input type="month" className="inp" value={ym} onChange={e => setYm(e.target.value)} />
            {!frozen && canFreeze && <button className="btn pri" onClick={freeze}><Lock size={14} />جمّد أداء {ymLabel(ym)}</button>}
            {frozen && <span className="badge b-mint"><Lock size={11} />مجمّد {frozen.createdAt ? ('· ' + (frozen.createdAt || '').slice(0, 10)) : ''}</span>}
          </div>
        </div>
        <div className="note">التجميد يخزّن درجة كل موظف ومكوّناتها لحظته سجلًّا ثابتًا لا يُعاد حسابه — يُنفَّذ بعد اعتماد الشهر (مع قفل الرواتب). أي تغيّر لاحق في بيانات الشهر يُكشف هنا بمقارنة «الحيّ» بـ«المجمّد».</div>
      </div>

      {frozen ? (
        <div className="card">
          <div className="card-h" style={{ flexWrap: 'wrap', gap: 8 }}>
            <div className="card-t">لقطة {ymLabel(frozen.ym)} — {frozen.rows.length} موظف {driftN > 0 ? <span className="badge b-rose" style={{ marginInlineStart: 6 }}><AlertTriangle size={11} />{driftN} تغيّرت بياناتهم بعد التجميد</span> : <span className="badge b-mint" style={{ marginInlineStart: 6 }}>لا انحراف</span>}</div>
            <div className="row" style={{ gap: 6 }}>
              <button className="btn sm gh" onClick={download}><Download size={13} />Excel</button>
              {canUnlock && <button className="btn sm gh" style={{ color: 'var(--rose)' }} onClick={() => unlock(frozen)}><X size={13} />فكّ التجميد</button>}
            </div>
          </div>
          <div className="note" style={{ marginBottom: 8 }}>
            عند التجميد: {frozen.meta && frozen.meta.weightsEnabled ? 'أوزان مخصّصة' : 'أوزان متساوية'}{frozen.meta && frozen.meta.roleKpiEnabled ? ' · محور مؤشرات الدور مفعّل (وزن ' + frozen.meta.roleKpiWeight + ')' : ' · محور مؤشرات الدور غير مفعّل'}. «الدرجة الحيّة الآن» تُحسب من البيانات الحالية — اختلافها عن المجمّدة يعني تغيّر بيانات الشهر بعد اعتماده.
          </div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>الموظف</th><th>الفرع</th><th>الدرجة المجمّدة</th><th>الحيّة الآن</th>{AX.map(a => <th key={a[0]}>{a[1]}</th>)}</tr></thead>
              <tbody>
                {driftRows.map(r => (
                  <tr key={r.employeeId} style={r.drift ? { background: 'rgba(217,84,77,.07)' } : undefined}>
                    <td style={{ fontWeight: 600, fontSize: 12.5 }}>{r.employeeName}<div style={{ fontSize: 10, color: 'var(--faint)' }}>{r.jobTitle}</div></td>
                    <td style={{ fontSize: 11.5 }}>{r.branchName}</td>
                    <td>{scoreBadge(r.score)}</td>
                    <td>{r.drift ? <span className="row" style={{ gap: 4 }}>{scoreBadge(r.live)}<AlertTriangle size={12} color="var(--rose)" /></span> : scoreBadge(r.live)}</td>
                    {AX.map(a => <td key={a[0]} className="num" style={{ fontSize: 11.5 }}>{r.axes && r.axes[a[0]] != null ? r.axes[a[0]] : '—'}</td>)}
                  </tr>
                ))}
                {frozen.rows.length === 0 && <tr><td colSpan={4 + AX.length}><div className="empty">لا موظفين في اللقطة.</div></td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      ) : (
        <div className="card"><div className="empty">{ymLabel(ym)} غير مجمّد. الدرجات لهذا الشهر تُحسب حيًّا وتتغيّر بتغيّر بياناته — جمّده بعد اعتماده لتثبيته.</div></div>
      )}

      {snaps.length > 0 && (
        <div className="card">
          <div className="card-t" style={{ marginBottom: 8 }}>الشهور المجمّدة</div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>الشهر</th><th>موظفون</th><th>تاريخ التجميد</th><th>بواسطة</th><th /></tr></thead>
              <tbody>
                {snaps.map(s => (
                  <tr key={s.id}>
                    <td style={{ fontWeight: 600 }}>{ymLabel(s.ym)}</td>
                    <td className="num">{(s.rows || []).length}</td>
                    <td style={{ fontSize: 11.5 }}>{(s.createdAt || '').slice(0, 10)}</td>
                    <td style={{ fontSize: 11.5 }}>{s.createdByName || '—'}</td>
                    <td><div className="row" style={{ gap: 5, justifyContent: 'flex-end' }}><button className="btn sm gh" onClick={() => setYm(s.ym)}>عرض</button>{canUnlock && <button className="btn sm gh" style={{ color: 'var(--rose)' }} onClick={() => unlock(s)}><X size={12} /></button>}</div></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}


// ===== م٩ — تفصيل حضور موظف لفترة (مُشتقّ، لا يُخزَّن): أيام مجدولة، حضور، تأخير بالدقائق، غياب، انصراف مبكر =====
function hrAttendanceDetail(org, ops, emp, from, to) {
  const policies = { ...defaultHrPolicies(), ...(org.hrPolicies || {}) };
  const tolerance = Number(policies.lateToleranceMinutes) || 0;
  const td = today(); const cap = to < td ? to : td;
  const addDays = (ds, n) => { const d = new Date(ds + 'T00:00:00'); d.setDate(d.getDate() + n); return d.toISOString().slice(0, 10); };
  const parseHM = (t) => { const [h, m] = String(t || '00:00').split(':').map(Number); return (h || 0) * 60 + (m || 0); };
  const s = { scheduled: 0, present: 0, onTime: 0, late: 0, lateMinutes: 0, absent: 0, early: 0, earlyMinutes: 0, noCheckout: 0, unscheduledIns: 0,
    // v27.4 — حضور فعلي بلا اعتماد على الجدولة (يعمل حتى بلا ورديات مُعيَّنة)
    actualDays: 0, workedMinutes: 0, openDays: 0 };
  const seen = new Set();
  (ops.shiftAssignments || []).filter(a => a.empId === emp.id).forEach(a => {
    (a.shiftIds || []).forEach((sid, di) => {
      if (!sid) return;
      const ds = addDays(a.weekStart, di);
      if (ds < from || ds > cap || seen.has(ds)) return;
      seen.add(ds); s.scheduled++;
      const tpl = (ops.shiftTemplates || []).find(t => t.id === sid);
      const evs = (ops.attendanceEvents || []).filter(ev => ev.employeeId === emp.id && (ev.at || '').slice(0, 10) === ds).sort((x, y) => (x.at < y.at ? -1 : 1));
      const inEv = evs.find(ev => ev.type === 'in');
      if (!inEv) { if (ds < td) s.absent++; else s.scheduled--; return; }
      s.present++;
      const inMin = new Date(inEv.at).getHours() * 60 + new Date(inEv.at).getMinutes();
      const lateBy = tpl ? inMin - parseHM(tpl.startTime) - tolerance : 0;
      if (lateBy > 0) { s.late++; s.lateMinutes += lateBy; } else s.onTime++;
      const outs = evs.filter(ev => ev.type === 'out'); const outEv = outs[outs.length - 1];
      if (outEv && tpl) {
        const outMin = new Date(outEv.at).getHours() * 60 + new Date(outEv.at).getMinutes();
        const earlyBy = parseHM(tpl.endTime) - outMin - tolerance;
        if (earlyBy > 0) { s.early++; s.earlyMinutes += earlyBy; }
      } else if (!outEv && ds < td) s.noCheckout++;
    });
  });
  // v27.4 — الحضور الفعلي: يُحسب من البصمات مباشرة لكل يوم (بلا حاجة لوردية مُعيَّنة)
  //   actualDays = أيام بها بصمة دخول، workedMinutes = مجموع (آخر خروج − أول دخول) لكل يوم، openDays = دخول بلا خروج
  const byDay = {};
  (ops.attendanceEvents || []).filter(ev => ev.employeeId === emp.id && (ev.at || '').slice(0, 10) >= from && (ev.at || '').slice(0, 10) <= cap)
    .forEach(ev => { const ds = (ev.at || '').slice(0, 10); (byDay[ds] = byDay[ds] || []).push(ev); });
  Object.keys(byDay).forEach(ds => {
    const evs = byDay[ds].sort((a, b) => (a.at < b.at ? -1 : 1));
    const firstIn = evs.find(e => e.type === 'in');
    if (!firstIn) return;                         // يوم بلا دخول لا يُعدّ حضورًا
    s.actualDays++;
    if (!seen.has(ds)) s.unscheduledIns++;        // دخول في يوم غير مجدول (معلوماتي)
    const outs = evs.filter(e => e.type === 'out'); const lastOut = outs[outs.length - 1];
    if (lastOut && lastOut.at > firstIn.at) { const mins = Math.round((new Date(lastOut.at) - new Date(firstIn.at)) / 60000); if (mins > 0) s.workedMinutes += mins; }
    else s.openDays++;                            // دخول بلا انصراف (فعلي)
  });
  return s;
}

function HrDashboard({ org, ops, me, myBranches, say, setTab }) {
  const branches = (myBranches || []).filter(b => b.isActive !== false);
  const [view, setView] = useState('dash');
  const [ym, setYm] = useState(() => today().slice(0, 7));
  const [branchId, setBranchId] = useState('');
  const ymAdd = (y, n) => { const [Y, M] = y.split('-').map(Number); const d = new Date(Y, M - 1 + n, 1); return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0'); };
  const ymLabel = (y) => { const [Y, M] = String(y).split('-').map(Number); return isNaN(Y) ? y : new Date(Y, M - 1, 1).toLocaleDateString('ar', { month: 'long', year: 'numeric' }); };
  const from = ym + '-01', to = ym + '-31';
  const pct = (a, b) => b ? Math.round(a / b * 100) : null;
  const fmtP = (v) => v == null ? '—' : v + '%';
  const empsOf = (bId) => (org.employees || []).filter(e => e.isActive !== false && e.branchId === bId);
  const bName = (id) => ((org.branches || []).find(b => b.id === id) || {}).name || '';

  // === ١) اللوحة التنفيذية — تجميع لكل فرع (والشركة) لشهر، مع الشهر السابق ===
  const aggBranch = (bId, y) => {
    const f = y + '-01', t = y + '-31';
    const emps = empsOf(bId);
    const agg = { emps: emps.length, scheduled: 0, onTime: 0, late: 0, absent: 0, lateMinutes: 0, tasksExpected: 0, tasksDone: 0, scores: [], rewards: 0, penalties: 0, points: 0 };
    emps.forEach(e => {
      const d = hrAttendanceDetail(org, ops, e, f, t);
      agg.scheduled += d.scheduled; agg.onTime += d.onTime; agg.late += d.late; agg.absent += d.absent; agg.lateMinutes += d.lateMinutes;
      const st = hrEmpStats(org, ops, e, f, t);
      agg.tasksExpected += st.tasksExpected; agg.tasksDone += st.tasksDone; agg.points += st.manualPts + st.autoPts;
      const sc = hrScoreFor(org, ops, e, y); if (sc.score != null) agg.scores.push(sc.score);
    });
    (ops.rewardRequests || []).filter(r => r.branchId === bId && r.month === y && r.status === 'approved').forEach(r => { if (r.kind === 'reward') agg.rewards += Number(r.amount) || 0; else agg.penalties += Number(r.amount) || 0; });
    return { ...agg, onTimePct: pct(agg.onTime, agg.scheduled), taskPct: pct(agg.tasksDone, agg.tasksExpected), avgScore: agg.scores.length ? Math.round(agg.scores.reduce((a, b) => a + b, 0) / agg.scores.length) : null };
  };
  const sumAgg = (list) => {
    const t = { emps: 0, scheduled: 0, onTime: 0, late: 0, absent: 0, lateMinutes: 0, tasksExpected: 0, tasksDone: 0, scores: [], rewards: 0, penalties: 0, points: 0 };
    list.forEach(a => { ['emps', 'scheduled', 'onTime', 'late', 'absent', 'lateMinutes', 'tasksExpected', 'tasksDone', 'rewards', 'penalties', 'points'].forEach(k => { t[k] += a[k]; }); t.scores = t.scores.concat(a.scores); });
    return { ...t, onTimePct: pct(t.onTime, t.scheduled), taskPct: pct(t.tasksDone, t.tasksExpected), avgScore: t.scores.length ? Math.round(t.scores.reduce((a, b) => a + b, 0) / t.scores.length) : null };
  };
  const rowsNow = branches.map(b => ({ b, ...aggBranch(b.id, ym) }));
  const rowsPrev = branches.map(b => ({ b, ...aggBranch(b.id, ymAdd(ym, -1)) }));
  const totNow = sumAgg(rowsNow), totPrev = sumAgg(rowsPrev);
  const delta = (a, b) => (a == null || b == null) ? null : a - b;
  const DeltaBadge = ({ d, unit, invert }) => d == null || d === 0 ? <span className="badge b-dim">—</span> : <span className={'badge ' + ((invert ? d < 0 : d > 0) ? 'b-mint' : 'b-rose')}>{d > 0 ? '▲ +' : '▼ '}{d}{unit || ''}</span>;
  const tone = chartTone();
  const chartData = rowsNow.map(r => ({ name: r.b.name, 'حضور في الوقت %': r.onTimePct || 0, 'إنجاز المهام %': r.taskPct || 0, 'متوسط الدرجة': r.avgScore || 0 }));

  // === ٢) تقرير الحضور الشهري التفصيلي ===
  const repBranches = branchId ? branches.filter(b => b.id === branchId) : branches;
  const attRows = repBranches.flatMap(b => empsOf(b.id).map(e => ({ e, b, ...hrAttendanceDetail(org, ops, e, from, to) })));
  // v27.4 — أعمدة «الحضور الفعلي» (بلا اعتماد على الجدولة) أولًا، ثم أعمدة الالتزام بالوردية المجدولة
  const hoursOf = (m) => m > 0 ? Math.round(m / 6) / 10 : 0;   // دقائق ⇒ ساعات بمنزلة عشرية
  const attHead = ['الموظف', 'الفرع', 'أيام حضور فعلي', 'ساعات فعلية', 'دخول بلا انصراف', 'أيام مجدولة', 'حضور مقابل الوردية', 'في الوقت', 'تأخير (مرات)', 'دقائق التأخير', 'غياب', 'انصراف مبكر (مرات)', 'دقائق مبكرة', 'بلا انصراف (مجدول)', 'نسبة الحضور في الوقت %'];
  const attLine = (r) => [r.e.name, r.b.name, r.actualDays, hoursOf(r.workedMinutes), r.openDays, r.scheduled, r.present, r.onTime, r.late, r.lateMinutes, r.absent, r.early, r.earlyMinutes, r.noCheckout, pct(r.onTime, r.scheduled) == null ? '' : pct(r.onTime, r.scheduled)];
  // === ٣) تقرير المكافآت والجزاءات والنقاط ===
  const rwRows = repBranches.flatMap(b => empsOf(b.id).map(e => {
    const reqs = (ops.rewardRequests || []).filter(r => r.employeeId === e.id && r.month === ym);
    const st = hrEmpStats(org, ops, e, from, to);
    return { e, b, rewards: reqs.filter(r => r.kind === 'reward' && r.status === 'approved').reduce((a, r) => a + Number(r.amount || 0), 0), penalties: reqs.filter(r => r.kind === 'penalty' && r.status === 'approved').reduce((a, r) => a + Number(r.amount || 0), 0), pending: reqs.filter(r => r.status === 'pending').length, rejected: reqs.filter(r => r.status === 'rejected').length, points: st.manualPts + st.autoPts, score: hrScoreFor(org, ops, e, ym).score };
  }));
  const rwHead = ['الموظف', 'الفرع', 'مكافآت معتمدة', 'جزاءات معتمدة', 'الصافي', 'طلبات معلّقة', 'مرفوضة', 'صافي النقاط', 'درجة الأداء'];
  const rwLine = (r) => [r.e.name, r.b.name, r.rewards, r.penalties, r.rewards - r.penalties, r.pending, r.rejected, r.points, r.score == null ? '' : r.score];

  const download = (name, head, lines) => {
    try {
      const blob = makeXlsx([{ name: name.slice(0, 28), rows: [head, ...lines] }]);
      const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = name + '_' + ym + '.xlsx'; document.body.appendChild(a); a.click(); document.body.removeChild(a); setTimeout(() => URL.revokeObjectURL(url), 1500);
      say('نُزّل ملف Excel ✓');
    } catch (e) { say('تعذّر توليد ملف Excel', 'no'); }
  };
  const printTable = (title, head, lines) => {
    const html = '<table><thead><tr>' + head.map(h => '<th>' + h + '</th>').join('') + '</tr></thead><tbody>' + lines.map(l => '<tr>' + l.map((c, i) => '<td' + (i > 1 ? ' class="n"' : '') + '>' + (c === '' ? '—' : c) + '</td>').join('') + '</tr>').join('') + '</tbody></table>';
    printA4(org, title + ' — ' + ymLabel(ym), (branchId ? bName(branchId) : 'كل الفروع') + ' · ' + lines.length + ' موظف', html) || say('اسمح بالنوافذ المنبثقة للطباعة', 'no');
  };

  if (!branches.length) return <div className="card"><div className="empty">لا يوجد فرع مُسند لحسابك — راجع مسؤول النظام.</div></div>;

  const ToolBar = ({ title, head, lines, fileName }) => (
    <div className="card-h" style={{ marginBottom: 8, flexWrap: 'wrap', gap: 8 }}>
      <div className="card-t"><FileBarChart size={15} color="var(--brass)" />{title} — {ymLabel(ym)}</div>
      <div className="row" style={{ gap: 6 }}>
        <button className="btn sm gh" onClick={() => printTable(title, head, lines)}><Printer size={13} />طباعة</button>
        <button className="btn sm gh" onClick={() => download(fileName, head, lines)}><Download size={13} />Excel</button>
      </div>
    </div>
  );

  return (
    <div className="grid" style={{ gap: 12 }}>
      <div className="card" style={{ padding: '8px 12px' }}>
        <div className="row" style={{ gap: 6, flexWrap: 'wrap', justifyContent: 'space-between' }}>
          <div className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
            <button className={'btn sm' + (view === 'dash' ? ' pri' : ' gh')} onClick={() => setView('dash')}><LayoutDashboard size={13} />اللوحة التنفيذية</button>
            <button className={'btn sm' + (view === 'attendance' ? ' pri' : ' gh')} onClick={() => setView('attendance')}><Fingerprint size={13} />تقرير الحضور</button>
            <button className={'btn sm' + (view === 'rewards' ? ' pri' : ' gh')} onClick={() => setView('rewards')}><Coins size={13} />المكافآت والنقاط</button>
          </div>
          <div className="row" style={{ gap: 8 }}>
            <input type="month" className="inp" value={ym} onChange={e => setYm(e.target.value)} />
            {view !== 'dash' && branches.length > 1 && (
              <select className="inp sel" style={{ width: 180 }} value={branchId} onChange={e => setBranchId(e.target.value)}>
                <option value="">كل الفروع</option>
                {branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
              </select>
            )}
          </div>
        </div>
      </div>

      {view === 'dash' && (
        <div className="grid" style={{ gap: 12 }}>
          <div className="grid g4">
            <Kpi label="الحضور في الوقت" value={fmtP(totNow.onTimePct)} sub={totNow.scheduled + ' يوم مجدول · ' + totNow.late + ' تأخير · ' + totNow.absent + ' غياب'} icon={Fingerprint} color={tone.pos} />
            <Kpi label="إنجاز المهام" value={fmtP(totNow.taskPct)} sub={totNow.tasksDone + ' من ' + totNow.tasksExpected} icon={CheckCircle2} color={tone.info} />
            <Kpi label="متوسط درجة الأداء" value={totNow.avgScore == null ? '—' : String(totNow.avgScore)} sub={totNow.scores.length + ' موظف بدرجة'} icon={TrendingUp} color={tone.accent} />
            <Kpi label="مكافآت − جزاءات معتمدة" value={money(totNow.rewards - totNow.penalties)} sub={money(totNow.rewards) + ' مكافآت · ' + money(totNow.penalties) + ' جزاءات'} icon={Coins} color={tone.warn} />
          </div>
          <div className="card">
            <div className="card-t" style={{ marginBottom: 8 }}><LayoutDashboard size={15} color="var(--brass)" />مقارنة الفروع — {ymLabel(ym)} (مقابل {ymLabel(ymAdd(ym, -1))})</div>
            <div className="tw">
              <table className="tb">
                <thead><tr><th>الفرع</th><th>موظفون</th><th>حضور في الوقت</th><th>تغيّر</th><th>تأخير</th><th>غياب</th><th>إنجاز المهام</th><th>تغيّر</th><th>متوسط الدرجة</th><th>تغيّر</th><th>مكافآت</th><th>جزاءات</th><th>صافي النقاط</th></tr></thead>
                <tbody>
                  {rowsNow.map((r, i) => { const p = rowsPrev[i]; return (
                    <tr key={r.b.id}>
                      <td style={{ fontWeight: 600, fontSize: 12.5 }}>{r.b.name}</td>
                      <td className="num">{r.emps}</td>
                      <td className="num">{fmtP(r.onTimePct)}</td><td><DeltaBadge d={delta(r.onTimePct, p.onTimePct)} unit="%" /></td>
                      <td className="num">{r.late}</td><td className="num">{r.absent}</td>
                      <td className="num">{fmtP(r.taskPct)}</td><td><DeltaBadge d={delta(r.taskPct, p.taskPct)} unit="%" /></td>
                      <td className="num">{r.avgScore == null ? '—' : r.avgScore}</td><td><DeltaBadge d={delta(r.avgScore, p.avgScore)} /></td>
                      <td className="num">{money(r.rewards)}</td><td className="num">{money(r.penalties)}</td>
                      <td className="num">{r.points > 0 ? '+' : ''}{r.points}</td>
                    </tr>
                  ); })}
                  <tr className="tot"><td style={{ fontWeight: 700 }}>الشركة</td><td className="num">{totNow.emps}</td><td className="num">{fmtP(totNow.onTimePct)}</td><td><DeltaBadge d={delta(totNow.onTimePct, totPrev.onTimePct)} unit="%" /></td><td className="num">{totNow.late}</td><td className="num">{totNow.absent}</td><td className="num">{fmtP(totNow.taskPct)}</td><td><DeltaBadge d={delta(totNow.taskPct, totPrev.taskPct)} unit="%" /></td><td className="num">{totNow.avgScore == null ? '—' : totNow.avgScore}</td><td><DeltaBadge d={delta(totNow.avgScore, totPrev.avgScore)} /></td><td className="num">{money(totNow.rewards)}</td><td className="num">{money(totNow.penalties)}</td><td className="num">{totNow.points > 0 ? '+' : ''}{totNow.points}</td></tr>
                </tbody>
              </table>
            </div>
          </div>
          {branches.length > 0 && (
            <div className="card">
              <div className="card-t" style={{ marginBottom: 8 }}><BarChart3 size={15} color="var(--brass)" />مؤشرات الفروع</div>
              <div style={{ width: '100%', height: 260 }}>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData} margin={{ top: 8, right: 8, left: 0, bottom: 8 }}>
                    <CartesianGrid stroke={tone.grid} strokeDasharray="3 3" />
                    <XAxis dataKey="name" tick={{ fill: tone.tick, fontSize: 11 }} />
                    <YAxis domain={[0, 100]} tick={{ fill: tone.tick, fontSize: 11 }} />
                    <Tooltip contentStyle={{ background: tone.tip, color: tone.tipTxt, border: 'none', borderRadius: 8, fontSize: 12 }} />
                    <Bar dataKey="حضور في الوقت %" fill={tone.pos} radius={[6, 6, 0, 0]} />
                    <Bar dataKey="إنجاز المهام %" fill={tone.info} radius={[6, 6, 0, 0]} />
                    <Bar dataKey="متوسط الدرجة" fill={tone.accent} radius={[6, 6, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>
          )}
        </div>
      )}

      {view === 'attendance' && (
        <div className="card">
          <ToolBar title="تقرير الحضور الشهري" head={attHead} lines={attRows.map(attLine)} fileName="تقرير_الحضور" />
          <div className="note" style={{ marginBottom: 8 }}>الأعمدة الأولى «الحضور الفعلي» (أيام الحضور والساعات) تُحسب من البصمات مباشرة وتعمل بلا ورديات. أعمدة «مقابل الوردية» (حضور/تأخير/غياب/نسبة) لا تُحسب إلا لموظف له ورديات مُعيَّنة في «محرّك الورديات» — تبقى صفرًا لمن لا وردية له.</div>
          <div className="tw">
            <table className="tb">
              <thead><tr>{attHead.map(h => <th key={h}>{h}</th>)}</tr></thead>
              <tbody>
                {attRows.map(r => { const l = attLine(r); return <tr key={r.e.id}>{l.map((c, i) => <td key={i} className={i > 1 ? 'num' : ''} style={i === 0 ? { fontWeight: 600, fontSize: 12.5 } : {}}>{c === '' ? '—' : c}</td>)}</tr>; })}
                {attRows.length === 0 && <tr><td colSpan={attHead.length}><div className="empty">لا يوجد موظفون نشطون.</div></td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {view === 'rewards' && (
        <div className="card">
          <ToolBar title="تقرير المكافآت والجزاءات والنقاط" head={rwHead} lines={rwRows.map(rwLine)} fileName="تقرير_المكافآت" />
          <div className="tw">
            <table className="tb">
              <thead><tr>{rwHead.map(h => <th key={h}>{h}</th>)}</tr></thead>
              <tbody>
                {rwRows.map(r => { const l = rwLine(r); return <tr key={r.e.id}>{l.map((c, i) => <td key={i} className={i > 1 ? 'num' : ''} style={i === 0 ? { fontWeight: 600, fontSize: 12.5 } : {}}>{c === '' ? '—' : c}</td>)}</tr>; })}
                {rwRows.length === 0 && <tr><td colSpan={rwHead.length}><div className="empty">لا يوجد موظفون نشطون.</div></td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

/* ================= م١٠ (v27.0) — التوقيع الإلكتروني: إقرارات استلام الراتب وإشعارات المكافآت/الجزاءات =================
   نموذج البيانات: ops.hrSignDocs[] — ضمن BR_COLS (مستند الفرع) كي يقرأه ويكتبه جهاز الفرع، ويقرأه المركز:
   { id, branchId, branchName, employeeId, employeeName, docType:'payslip'|'reward'|'penalty', month, refId, title, amount,
     lines:{base,allow,bonus,gross,draws,cuts,gEmp,net} (القسيمة فقط), reason, issuedAt, issuedBy, issuedByName,
     status:'pending'|'signed'|'voided', signedAt, signedVia:'branch_kiosk'|'central', signedOnBy, signedOnByName,
     pinVerified, witnessName, sig:{w,h,s:[[x,y,x,y,…],…]} (مسارات متجهة مبسَّطة — لا صور), sigHash }
   الإصدار: المركز (تسجيل صرف الرواتب / اعتماد مكافأة أو جزاء). التوقيع: كشك الفرع بعد التحقق بـPIN، أو من المكتب.
   ============================================================================================================ */
const SIG_W = 400, SIG_H = 160;
const SIGN_DOC_AR = { payslip: 'إقرار استلام راتب', reward: 'إشعار مكافأة', penalty: 'إشعار جزاء', corrective: 'محضر إجراء تأديبي' };
const escH = (s) => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

// تبسيط المسارات: تقريب لأعداد صحيحة داخل الإطار وإسقاط النقاط الأقرب من minDist إلى آخر نقطة محفوظة (تصغير الحجم المخزَّن بلا أثر مرئي)
function simplifySig(strokes, minDist) {
  const md = minDist == null ? 1.5 : minDist;
  const out = [];
  (strokes || []).forEach(pts => {
    const s = []; let lx = null, ly = null;
    for (let i = 0; i + 1 < pts.length; i += 2) {
      const x = Math.round(Math.min(SIG_W, Math.max(0, Number(pts[i]) || 0))), y = Math.round(Math.min(SIG_H, Math.max(0, Number(pts[i + 1]) || 0)));
      const last = i + 2 >= pts.length;
      if (lx != null && !last && Math.hypot(x - lx, y - ly) < md) continue;
      s.push(x, y); lx = x; ly = y;
    }
    if (s.length >= 2) out.push(s);
  });
  return out;
}
const sigPoints = (sig) => ((sig && sig.s) || []).reduce((n, s) => n + Math.floor(s.length / 2), 0);
function sigPathD(sig) {
  return ((sig && sig.s) || []).map(pts => {
    if (pts.length < 2) return '';
    let d = 'M' + pts[0] + ' ' + pts[1];
    if (pts.length < 4) return d + ' l0.5 0';   // نقطة مفردة تُرسم كنقطة
    for (let i = 2; i + 1 < pts.length; i += 2) d += ' L' + pts[i] + ' ' + pts[i + 1];
    return d;
  }).filter(Boolean).join(' ');
}
// SVG للطباعة/التصدير (نص) — والمكوّن SigView للعرض داخل التطبيق
function sigSvg(sig, opts) {
  const o = opts || {};
  if (!sigPoints(sig)) return '';
  const w = o.width || 160, W = sig.w || SIG_W, H = sig.h || SIG_H, h = Math.round(w * H / W);
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + W + ' ' + H + '" width="' + w + '" height="' + h + '" style="display:block;margin:0 auto"><path d="' + sigPathD(sig) + '" fill="none" stroke="' + (o.stroke || '#1b2a6b') + '" stroke-width="' + (o.sw || 3) + '" stroke-linecap="round" stroke-linejoin="round"/></svg>';
}
function SigView({ sig, width, style }) {
  if (!sigPoints(sig)) return <span style={{ color: 'var(--faint)' }}>—</span>;
  const w = width || 120, W = sig.w || SIG_W, H = sig.h || SIG_H;
  return <svg viewBox={'0 0 ' + W + ' ' + H} width={w} height={Math.round(w * H / W)} style={{ display: 'block', background: '#fff', borderRadius: 6, ...(style || {}) }}><path d={sigPathD(sig)} fill="none" stroke="#1b2a6b" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" /></svg>;
}

// قسائم الشهر: مستند إقرار لكل موظف صافيه > 0 لا يملك مستندًا لهذا الشهر بعد (idempotent — يُستدعى داخل mutator على أحدث نسخة)
function buildPayslipSignDocs(rows, month, existing, branches, me) {
  const has = new Set((existing || []).filter(d => d.docType === 'payslip' && d.month === month && d.status !== 'voided').map(d => d.employeeId));
  return (rows || []).filter(r => r.net > 0 && !has.has(r.e.id)).map(r => {
    const b = (branches || []).find(x => x.id === r.e.branchId) || {};
    return {
      id: uid('sg'), branchId: r.e.branchId || '', branchName: b.name || '', employeeId: r.e.id, employeeName: r.e.name,
      docType: 'payslip', month, refId: 'payout-' + month, title: 'إقرار استلام راتب شهر ' + month, amount: r.net,
      lines: { base: r.e.baseSalary || 0, allow: r.allow || 0, bonus: r.bonus || 0, gross: r.gross, draws: r.draws || 0, cuts: r.cuts || 0, gEmp: r.gEmp || 0, net: r.net },
      reason: '', issuedAt: nowISO(), issuedBy: me ? me.id : '', issuedByName: me ? me.name : '', status: 'pending',
      signedAt: '', signedVia: '', signedOnBy: '', signedOnByName: '', pinVerified: false, witnessName: '', sig: null, sigHash: ''
    };
  });
}
// إشعار بالعلم عند الاعتماد النهائي لمكافأة/جزاء (م٨)
function rewardSignDoc(r, me) {
  return {
    id: uid('sg'), branchId: r.branchId || '', branchName: r.branchName || '', employeeId: r.employeeId, employeeName: r.employeeName,
    docType: r.kind === 'reward' ? 'reward' : 'penalty', month: r.month, refId: r.id, title: (r.kind === 'reward' ? 'إشعار مكافأة' : 'إشعار جزاء') + ' — شهر ' + r.month, amount: r.amount,
    lines: null, reason: r.reason || '', issuedAt: nowISO(), issuedBy: me ? me.id : '', issuedByName: me ? me.name : '', status: 'pending',
    signedAt: '', signedVia: '', signedOnBy: '', signedOnByName: '', pinVerified: false, witnessName: '', sig: null, sigHash: ''
  };
}
// نص الإقرار الذي يوقّعه الموظف
function signDeclaration(doc) {
  const m = money(doc.amount || 0);
  if (doc.docType === 'payslip') return 'أقرّ أنا ' + doc.employeeName + ' باستلام صافي راتبي عن شهر ' + doc.month + ' وقدره ' + m + ' ر.س بعد السلف والخصومات الموضّحة، وبأنه لا مطالبة لي عن هذا الشهر.';
  if (doc.docType === 'reward') return 'أقرّ أنا ' + doc.employeeName + ' بالعلم باعتماد مكافأة قدرها ' + m + ' ر.س تُضاف إلى راتب شهر ' + doc.month + (doc.reason ? ' — السبب: ' + doc.reason : '') + '.';
  if (doc.docType === 'corrective') return 'أقرّ أنا ' + doc.employeeName + ' بالعلم بالإجراء التأديبي: ' + (doc.reason || doc.title || '') + (doc.amount ? ' — بغرامة قدرها ' + m + ' ر.س تُخصم من راتب شهر ' + doc.month : '') + '، وقد أُبلِغتُ به واستُجوِبتُ، مع احتفاظي بحق التظلّم خلال المدة النظامية.';
  return 'أقرّ أنا ' + doc.employeeName + ' بالعلم بتوقيع جزاء قدره ' + m + ' ر.س يُخصم من راتب شهر ' + doc.month + (doc.reason ? ' — السبب: ' + doc.reason : '') + '، مع احتفاظي بحق التظلّم وفق النظام.';
}
// مستندات معلّقة تجاوزت مهلة التذكير (hrPolicies.signReminderDays) — لمركز التنبيهات
function overdueSignDocs(org, ops, branchIds, todayStr) {
  const pol = (org || {}).hrPolicies || {};
  const days = Math.max(0, Number(pol.signReminderDays != null ? pol.signReminderDays : defaultHrPolicies().signReminderDays) || 0);
  const d = new Date((todayStr || today()) + 'T00:00:00'); d.setDate(d.getDate() - days);
  const cutoff = d.toISOString().slice(0, 10);
  return ((ops || {}).hrSignDocs || []).filter(x => x.status === 'pending' && (branchIds || []).includes(x.branchId) && (x.issuedAt || '').slice(0, 10) <= cutoff);
}
// كتلة التوقيع للطباعة (قسيمة الراتب، المسير، الإقرار)
function sigBlockHtml(doc, width) {
  if (!doc || doc.status !== 'signed' || !sigPoints(doc.sig)) return '';
  let when = ''; try { when = new Date(doc.signedAt).toLocaleString('ar-SA'); } catch { when = doc.signedAt || ''; }
  return '<div style="text-align:center">' + sigSvg(doc.sig, { width: width || 150 }) + '<div style="font-size:9.5px;color:#555;margin-top:2px">وُقِّع إلكترونيًا ' + escH(when) + (doc.pinVerified ? ' · تحقّق PIN' : (doc.witnessName ? ' · بحضور ' + escH(doc.witnessName) : '')) + (doc.sigHash ? ' · #' + escH(String(doc.sigHash).slice(0, 10)) : '') + '</div></div>';
}
// صفحة الإقرار A4 (للطباعة من السجل أو من شاشة الرواتب)
function signDocHtml(doc, showAmounts) {
  const L = doc.lines || {}; const m = (n) => money(n);
  let body = '';
  if (doc.docType === 'payslip') {
    body = showAmounts ? `<table><tbody>
      <tr><td>الراتب الأساسي</td><td class="n">${m(L.base)}</td></tr>
      <tr><td>البدلات</td><td class="n">${m(L.allow)}</td></tr>
      ${L.bonus ? `<tr><td>مكافآت معتمدة</td><td class="n">${m(L.bonus)}</td></tr>` : ''}
      <tr><td>إجمالي الاستحقاق</td><td class="n">${m(L.gross)}</td></tr>
      <tr><td>السلف والسحوبات</td><td class="n neg">- ${m(L.draws)}</td></tr>
      <tr><td>الخصومات والجزاءات</td><td class="n neg">- ${m(L.cuts)}</td></tr>
      ${L.gEmp ? `<tr><td>التأمينات الاجتماعية (حصة الموظف)</td><td class="n neg">- ${m(L.gEmp)}</td></tr>` : ''}
      <tr class="tot"><td>صافي المستلم</td><td class="n">${m(L.net)}</td></tr></tbody></table>`
      : `<table><tbody><tr><td>شهر الراتب</td><td class="n">${escH(doc.month)}</td></tr><tr><td>صافي المستلم</td><td class="n">${m(doc.amount)}</td></tr></tbody></table>`;
  } else {
    body = doc.docType === 'corrective'
      ? `<table><tbody><tr><td>الإجراء</td><td>${escH(doc.title || 'محضر إجراء تأديبي')}</td></tr>${doc.amount ? `<tr><td>الغرامة</td><td class="n">${m(doc.amount)}</td></tr>` : ''}<tr><td>الشهر</td><td class="n">${escH(doc.month)}</td></tr><tr><td>البيان</td><td>${escH(doc.reason) || '—'}</td></tr></tbody></table>`
      : `<table><tbody><tr><td>النوع</td><td>${SIGN_DOC_AR[doc.docType] || ''}</td></tr><tr><td>المبلغ</td><td class="n">${m(doc.amount)}</td></tr><tr><td>شهر الراتب</td><td class="n">${escH(doc.month)}</td></tr><tr><td>السبب</td><td>${escH(doc.reason) || '—'}</td></tr></tbody></table>`;
  }
  const signed = doc.status === 'signed';
  const sigPart = signed
    ? `<div style="display:flex;justify-content:space-around;margin-top:24px;align-items:flex-end"><div style="text-align:center"><div style="font-size:11px;color:#555;margin-bottom:4px">توقيع الموظف</div>${sigBlockHtml(doc, 170)}</div><div class="sign" style="margin-top:0"><div>${escH(doc.witnessName ? 'الشاهد: ' + doc.witnessName : 'المحاسب / الإدارة')}</div></div></div>`
    : `<div class="sign"><div>توقيع الموظف</div><div>المحاسب / الإدارة</div></div>`;
  return `<div class="box"><b>${escH(doc.employeeName)}</b>${doc.branchName ? ' · ' + escH(doc.branchName) : ''} · رقم المستند ${escH(doc.id)}<br>أُصدر ${escH((doc.issuedAt || '').slice(0, 10))}${doc.issuedByName ? ' بواسطة ' + escH(doc.issuedByName) : ''} · الحالة: ${signed ? 'موقَّع إلكترونيًا' : doc.status === 'voided' ? 'مُلغى' : 'بانتظار التوقيع'}</div>
  ${body}
  <div class="box" style="margin-top:12px;font-size:12.5px;line-height:1.9">${escH(signDeclaration(doc))}</div>
  ${sigPart}`;
}

// لوحة التوقيع: قلم/لمس/فأرة عبر Pointer Events — الرسم على canvas للاستجابة الفورية، والمسارات تُخزَّن بإحداثيات منطقية SIG_W×SIG_H
function HrSignPad({ onChange, disabled }) {
  const canvasRef = useRef(null);
  const strokes = useRef([]);   // مسارات مكتملة
  const cur = useRef(null);     // المسار الجاري
  const [, bump] = useState(0);
  const geom = () => {
    const c = canvasRef.current; const rect = c ? c.getBoundingClientRect() : { left: 0, top: 0, width: 0, height: 0 };
    return { rect, sx: rect.width ? SIG_W / rect.width : 1, sy: rect.height ? SIG_H / rect.height : 1 };
  };
  const redraw = () => {
    const c = canvasRef.current; if (!c) return;
    let ctx = null; try { ctx = c.getContext('2d'); } catch { ctx = null; }
    if (!ctx) return;   // بيئات بلا canvas (اختبارات) — المسارات تُسجَّل رغم ذلك
    const rect = c.getBoundingClientRect(); const dpr = window.devicePixelRatio || 1;
    const cw = Math.max(1, Math.round((rect.width || SIG_W) * dpr)), ch = Math.max(1, Math.round((rect.height || SIG_H) * dpr));
    if (c.width !== cw || c.height !== ch) { c.width = cw; c.height = ch; }
    ctx.setTransform(1, 0, 0, 1, 0, 0); ctx.clearRect(0, 0, c.width, c.height);
    ctx.setTransform(c.width / SIG_W, 0, 0, c.height / SIG_H, 0, 0);
    ctx.save(); ctx.strokeStyle = 'rgba(0,0,0,.18)'; ctx.lineWidth = 1; ctx.setLineDash([6, 6]); ctx.beginPath(); ctx.moveTo(24, SIG_H - 34); ctx.lineTo(SIG_W - 24, SIG_H - 34); ctx.stroke(); ctx.restore();
    ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.strokeStyle = '#1b2a6b'; ctx.lineWidth = 3;
    const all = cur.current ? [...strokes.current, cur.current] : strokes.current;
    all.forEach(pts => {
      if (pts.length < 2) return;
      ctx.beginPath(); ctx.moveTo(pts[0], pts[1]);
      if (pts.length < 4) ctx.lineTo(pts[0] + 0.5, pts[1]);
      for (let i = 2; i + 1 < pts.length; i += 2) ctx.lineTo(pts[i], pts[i + 1]);
      ctx.stroke();
    });
  };
  const pt = (e) => { const { rect, sx, sy } = geom(); return [((e.clientX || 0) - rect.left) * sx, ((e.clientY || 0) - rect.top) * sy]; };
  const emit = () => { const s = simplifySig(strokes.current); onChange && onChange(s.length ? { w: SIG_W, h: SIG_H, s } : null); };
  const down = (e) => {
    if (disabled) return;
    if (e.preventDefault) e.preventDefault();
    try { if (e.currentTarget && e.currentTarget.setPointerCapture && e.pointerId != null) e.currentTarget.setPointerCapture(e.pointerId); } catch { }
    cur.current = pt(e); redraw();
  };
  const move = (e) => { if (!cur.current) return; if (e.preventDefault) e.preventDefault(); cur.current.push(...pt(e)); redraw(); };
  const up = (e) => { if (!cur.current) return; if (e && e.preventDefault) e.preventDefault(); strokes.current.push(cur.current); cur.current = null; redraw(); emit(); bump(x => x + 1); };
  const clear = () => { strokes.current = []; cur.current = null; redraw(); emit(); bump(x => x + 1); };
  const undo = () => { strokes.current.pop(); redraw(); emit(); bump(x => x + 1); };
  useEffect(() => { redraw(); const h = () => redraw(); window.addEventListener('resize', h); return () => window.removeEventListener('resize', h); }, []); // eslint-disable-line
  const n = strokes.current.length;
  return (
    <div>
      <canvas ref={canvasRef} data-testid="sigpad" aria-label="لوحة التوقيع"
        style={{ width: '100%', maxWidth: 520, aspectRatio: SIG_W + ' / ' + SIG_H, display: 'block', border: '1.5px dashed var(--brass)', borderRadius: 12, background: '#fff', touchAction: 'none', cursor: disabled ? 'not-allowed' : 'crosshair' }}
        onPointerDown={down} onPointerMove={move} onPointerUp={up} onPointerCancel={up} onPointerLeave={up} />
      <div className="row" style={{ gap: 6, marginTop: 6, justifyContent: 'space-between', flexWrap: 'wrap' }}>
        <div style={{ fontSize: 10.5, color: 'var(--faint)' }}>{n ? n + ' خط' : 'وقّع بإصبعك أو بالقلم داخل الإطار'}</div>
        <div className="row" style={{ gap: 6 }}>
          <button type="button" className="btn sm gh" disabled={!n} onClick={undo}>تراجع</button>
          <button type="button" className="btn sm gh" disabled={!n} onClick={clear}><Trash2 size={13} />مسح</button>
        </div>
      </div>
    </div>
  );
}

// نافذة التوقيع: تحقّق PIN مرة واحدة (أو بحضور مستخدم مركزي) ثم التوقيع على كل مستند معلّق للموظف على التوالي
function SignDocsModal({ org, ops, me, emp, docs, onClose, commit, say, via }) {
  const isAll = (ROLES[me.role] || {}).scope === 'all';
  const pinRec = (ops.hrPins || []).find(p => p.employeeId === emp.id) || {};
  const hasPin = !!pinRec.pinHash;
  const [list] = useState(() => (docs || []).filter(d => d.status === 'pending'));   // تُجمَّد عند الفتح كي لا يقفز الترتيب بعد كل حفظ
  const [step, setStep] = useState('pin');
  const [pin, setPin] = useState('');
  const [witness, setWitness] = useState(false);
  const [idx, setIdx] = useState(0);
  const [sig, setSig] = useState(null);
  const [agree, setAgree] = useState(false);
  const [busy, setBusy] = useState(false);
  const [doneN, setDoneN] = useState(0);
  const doc = list[idx] || null;
  const verify = async () => {
    if (busy) return;
    if (!hasPin) return say('لا يوجد رقم PIN لهذا الموظف', 'no');
    if (!/^\d{4,6}$/.test(pin)) return say('أدخل رقم PIN المكوّن من ٤ إلى ٦ أرقام', 'no');
    setBusy(true); const h = await sha(pin); setBusy(false);
    if (h !== pinRec.pinHash) { setPin(''); return say('رقم PIN غير صحيح', 'no'); }
    setPin(''); setStep('sign');
  };
  const witnessGo = () => {
    if (!isAll) return;
    if (!window.confirm('التوقيع بحضورك دون تحقّق PIN؟ سيُسجَّل اسمك شاهدًا على المستند.')) return;
    setWitness(true); setStep('sign');
  };
  const save = async () => {
    if (!doc || busy) return;
    if (sigPoints(sig) < 6) return say('ارسم توقيعك داخل الإطار أولًا', 'no');
    if (!agree) return say('أكّد قراءة نص الإقرار والموافقة عليه', 'no');
    setBusy(true);
    const signedAt = nowISO();
    const sigHash = await sha(JSON.stringify(sig) + '|' + doc.id + '|' + emp.id + '|' + signedAt);
    const patch = { status: 'signed', signedAt, signedVia: via || (isAll ? 'central' : 'branch_kiosk'), signedOnBy: me.id, signedOnByName: me.name, pinVerified: !witness, witnessName: witness ? me.name : '', sig, sigHash };
    const ok = await commit(d => ({ ...d, hrSignDocs: (d.hrSignDocs || []).map(x => (x.id === doc.id && x.status === 'pending') ? { ...x, ...patch } : x) }),
      { actionType: 'update', targetType: 'hr_sign_doc', targetId: doc.id, branchName: doc.branchName, title: 'توقيع إلكتروني — ' + (SIGN_DOC_AR[doc.docType] || doc.docType), details: emp.name + ' · ' + doc.title + ' · ' + money(doc.amount) + ' ر.س · ' + (witness ? 'بحضور ' + me.name : 'تحقّق PIN') });
    setBusy(false);
    if (!ok) return;
    say('حُفظ توقيع ' + emp.name + ' ✓');
    setDoneN(n => n + 1); setSig(null); setAgree(false);
    if (idx + 1 < list.length) setIdx(idx + 1); else setStep('done');
  };
  const L = (doc && doc.lines) || {};
  const title = step === 'done' ? 'اكتمل التوقيع — ' + emp.name : (doc ? (SIGN_DOC_AR[doc.docType] || 'توقيع') + ' — ' + emp.name : 'توقيع — ' + emp.name);
  return (
    <Modal title={title} icon={Signature} onClose={onClose} wide
      foot={<>
        <button className="btn gh" onClick={onClose}>{step === 'done' ? 'إغلاق' : 'إلغاء'}</button>
        {step === 'pin' && <button className="btn pri" disabled={busy || !hasPin} onClick={verify}><Check size={14} />{busy ? 'جارٍ...' : 'تأكيد PIN'}</button>}
        {step === 'sign' && <button className="btn pri" disabled={busy} onClick={save}><PenLine size={14} />{busy ? 'جارٍ الحفظ...' : 'اعتماد التوقيع'}</button>}
      </>}>
      {step === 'pin' && (
        <div className="grid" style={{ gap: 10 }}>
          <div className="note">لديك <b>{list.length}</b> {list.length === 1 ? 'مستند' : 'مستندات'} بانتظار توقيعك: {list.map(d => SIGN_DOC_AR[d.docType] + ' (' + d.month + ')').join('، ')}. تُعرض التفاصيل والمبالغ بعد التحقق من هويتك.</div>
          {hasPin ? (
            <Field label="رقم PIN الخاص بك">
              <input className="inp" type="password" inputMode="numeric" maxLength={6} autoFocus value={pin}
                onChange={e => setPin(e.target.value.replace(/\D/g, ''))} onKeyDown={e => { if (e.key === 'Enter') verify(); }} placeholder="••••" />
            </Field>
          ) : (
            <div className="note" style={{ color: 'var(--rose)' }}>لا يوجد رقم PIN لهذا الموظف — يضبطه مدير الفرع من «الحضور الموثَّق ← أرقام PIN».</div>
          )}
          {isAll && (
            <div className="row" style={{ justifyContent: 'flex-end' }}>
              <button className="btn sm gh" onClick={witnessGo}><Eye size={13} />التوقيع بحضوري ({me.name}) دون PIN</button>
            </div>
          )}
        </div>
      )}
      {step === 'sign' && doc && (
        <div className="grid" style={{ gap: 10 }}>
          <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 6 }}>
            <span className={'badge ' + ((doc.docType === 'penalty' || doc.docType === 'corrective') ? 'b-rose' : doc.docType === 'reward' ? 'b-mint' : 'b-brass')}>{SIGN_DOC_AR[doc.docType]} · شهر {doc.month}</span>
            <span className="badge b-dim">المستند {idx + 1} من {list.length}</span>
          </div>
          <div className="card" style={{ padding: 12, border: '1px solid var(--frame-o)' }}>
            <div style={{ fontSize: 12.5, color: 'var(--dim)' }}>{doc.docType === 'payslip' ? 'صافي المستلم' : doc.docType === 'corrective' ? 'الغرامة' : 'المبلغ'}</div>
            <div className="num" style={{ fontSize: 24, fontWeight: 800, color: (doc.docType === 'penalty' || doc.docType === 'corrective') ? 'var(--rose)' : 'var(--mint)' }}>{doc.docType === 'corrective' && !doc.amount ? <span style={{ fontSize: 15, fontWeight: 700 }}>بلا غرامة مالية</span> : <>{money(doc.amount)} <span style={{ fontSize: 12, fontWeight: 400 }}>ر.س</span></>}</div>
            {doc.docType === 'payslip' && (
              <div className="grid g2" style={{ gap: 4, marginTop: 8, fontSize: 12 }}>
                <div>الأساسي: <b className="num">{money(L.base)}</b></div><div>البدلات: <b className="num">{money(L.allow)}</b></div>
                {L.bonus > 0 && <div>مكافآت: <b className="num">{money(L.bonus)}</b></div>}
                <div>الإجمالي: <b className="num">{money(L.gross)}</b></div>
                <div>سلف/سحوبات: <b className="num" style={{ color: 'var(--amber)' }}>{money(L.draws)}</b></div>
                <div>خصومات/جزاءات: <b className="num" style={{ color: 'var(--rose)' }}>{money(L.cuts)}</b></div>
                {L.gEmp > 0 && <div>تأمينات: <b className="num" style={{ color: 'var(--sky)' }}>{money(L.gEmp)}</b></div>}
              </div>
            )}
            {doc.docType !== 'payslip' && <div style={{ fontSize: 12.5, marginTop: 6 }}>السبب: <b>{doc.reason || '—'}</b></div>}
          </div>
          <div className="card" style={{ padding: 10, background: 'rgba(200,162,74,.06)', fontSize: 12.5, lineHeight: 1.8 }}>{signDeclaration(doc)}</div>
          <label className="row" style={{ gap: 6, fontSize: 12.5, cursor: 'pointer' }}>
            <input type="checkbox" checked={agree} onChange={e => setAgree(e.target.checked)} />قرأتُ نص الإقرار وأوافق عليه
          </label>
          <HrSignPad key={doc.id} onChange={setSig} />
          {witness && <div className="note" style={{ color: 'var(--amber)' }}>سيُسجَّل هذا التوقيع بحضور {me.name} دون تحقّق PIN.</div>}
        </div>
      )}
      {step === 'done' && (
        <div className="empty" style={{ padding: 20 }}>
          <CheckCircle2 size={34} color="var(--mint)" />
          <div style={{ marginTop: 8, fontWeight: 700 }}>اكتمل توقيع {doneN} {doneN === 1 ? 'مستند' : 'مستندات'} ✓</div>
          <div style={{ fontSize: 11.5, color: 'var(--faint)', marginTop: 4 }}>شكرًا {emp.name} — يظهر توقيعك على القسيمة والمسير المطبوعين.</div>
        </div>
      )}
    </Modal>
  );
}

// شاشة «التوقيع الإلكتروني»: كشك الفرع (كل الأدوار) + سجل الإقرارات وتقرير الحالة (غير الكاشير) + إلغاء المعلّق (المركز)
function ESign({ org, ops, me, myBranches, commit, say }) {
  const role = ROLES[me.role] || {};
  const isAll = role.scope === 'all';
  const isCashier = me.role === 'cashier';
  const canCancel = isAll;          // إلغاء مستند معلّق: أدوار المركز (الجهة المُصدِرة)
  const showAmounts = isAll;        // مبالغ الرواتب لا تُعرض لأدوار الفروع في السجل — يراها الموظف نفسه بعد PIN فقط
  const branches = myBranches || [];
  const [view, setView] = useState('kiosk');
  const [branchId, setBranchId] = useState((branches[0] || {}).id || '');
  useEffect(() => { if (!branches.find(b => b.id === branchId)) setBranchId((branches[0] || {}).id || ''); }, [branches, branchId]);
  const branch = branches.find(b => b.id === branchId) || null;
  const branchIds = branches.map(b => b.id);
  const emps = (org.employees || []).filter(e => e.isActive !== false && branch && e.branchId === branch.id);
  const docsAll = (ops.hrSignDocs || []).filter(d => branchIds.includes(d.branchId));
  const pendingOf = (empId) => docsAll.filter(d => d.employeeId === empId && d.status === 'pending' && branch && d.branchId === branch.id).sort((a, b) => (a.issuedAt < b.issuedAt ? -1 : 1));
  const [signFor, setSignFor] = useState(null);
  const ymLabel = (y) => { const [Y, M] = String(y).split('-').map(Number); return isNaN(Y) ? y : new Date(Y, M - 1, 1).toLocaleDateString('ar', { month: 'long', year: 'numeric' }); };
  const statusBadge = (d) => d.status === 'signed' ? <span className="badge b-mint"><Check size={11} />موقَّع</span> : d.status === 'voided' ? <span className="badge b-dim">مُلغى</span> : <span className="badge b-amber">بانتظار التوقيع</span>;
  const viaAr = (d) => d.status !== 'signed' ? '—' : (d.pinVerified ? 'PIN' : 'بحضور ' + (d.witnessName || '')) + (d.signedVia === 'central' ? ' · المكتب' : ' · جهاز الفرع');

  // === سجل الإقرارات ===
  const [ym, setYm] = useState(() => today().slice(0, 7));
  const [logBranch, setLogBranch] = useState('');
  const [logStatus, setLogStatus] = useState('');
  const [logType, setLogType] = useState('');
  const logRows = docsAll
    .filter(d => !ym || d.month === ym)
    .filter(d => !logBranch || d.branchId === logBranch)
    .filter(d => !logStatus || d.status === logStatus)
    .filter(d => !logType || d.docType === logType)
    .sort((a, b) => (a.issuedAt < b.issuedAt ? 1 : -1));
  const monthDocs = docsAll.filter(d => d.month === ym && (!logBranch || d.branchId === logBranch));
  const nSigned = monthDocs.filter(d => d.status === 'signed').length, nPending = monthDocs.filter(d => d.status === 'pending').length;
  const [viewDoc, setViewDoc] = useState(null);
  const cancelDoc = async (d) => {
    if (!canCancel || d.status !== 'pending') return;
    if (!window.confirm('إلغاء «' + d.title + '» لـ' + d.employeeName + '؟ يمكن إعادة إصداره من شاشة الرواتب.')) return;
    const ok = await commit(x => ({ ...x, hrSignDocs: (x.hrSignDocs || []).filter(y => y.id !== d.id) }),
      { actionType: 'delete', targetType: 'hr_sign_doc', targetId: d.id, branchName: d.branchName, title: 'إلغاء مستند توقيع معلّق', details: d.employeeName + ' · ' + d.title });
    if (ok) say('أُلغي المستند');
  };
  const printDoc = (d) => {
    printA4(org, (SIGN_DOC_AR[d.docType] || 'إقرار') + ' — ' + d.employeeName, 'شهر ' + d.month + ' · ' + (d.branchName || ''), signDocHtml(d, showAmounts)) || say('اسمح بالنوافذ المنبثقة للطباعة', 'no');
  };
  const printReport = () => {
    const rws = logRows.map(d => `<tr><td>${escH(d.employeeName)}</td><td>${escH(d.branchName)}</td><td>${SIGN_DOC_AR[d.docType] || ''}</td><td class="n">${escH(d.month)}</td>${showAmounts ? `<td class="n">${money(d.amount)}</td>` : ''}<td>${d.status === 'signed' ? 'موقَّع' : d.status === 'voided' ? 'مُلغى' : 'بانتظار التوقيع'}</td><td class="n">${d.signedAt ? escH(new Date(d.signedAt).toLocaleString('ar-SA')) : '—'}</td><td>${escH(viaAr(d))}</td><td style="width:110px">${d.status === 'signed' ? sigSvg(d.sig, { width: 100 }) : ''}</td></tr>`).join('');
    printA4(org, 'تقرير حالة التوقيعات — ' + ymLabel(ym), (logBranch ? (branches.find(b => b.id === logBranch) || {}).name + ' · ' : '') + 'موقَّع ' + nSigned + ' · بانتظار ' + nPending,
      `<table><thead><tr><th>الموظف</th><th>الفرع</th><th>المستند</th><th>الشهر</th>${showAmounts ? '<th>المبلغ</th>' : ''}<th>الحالة</th><th>وقت التوقيع</th><th>الطريقة</th><th>التوقيع</th></tr></thead><tbody>${rws || '<tr><td colspan="9" style="text-align:center;color:#888">لا مستندات ضمن هذه الفلاتر</td></tr>'}</tbody></table>`) || say('اسمح بالنوافذ المنبثقة للطباعة', 'no');
  };

  if (!branch && branches.length === 0) {
    return <div className="card"><div className="empty">لا يوجد فرع مُسند لحسابك — راجع مسؤول النظام.</div></div>;
  }
  return (
    <div className="grid" style={{ gap: 12 }}>
      {!isCashier && (
        <div className="card" style={{ padding: '8px 12px' }}>
          <div className="row" style={{ gap: 6, flexWrap: 'wrap', justifyContent: 'space-between' }}>
            <div className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
              <button className={'btn sm' + (view === 'kiosk' ? ' pri' : ' gh')} onClick={() => setView('kiosk')}><Signature size={13} />كشك التوقيع</button>
              <button className={'btn sm' + (view === 'log' ? ' pri' : ' gh')} onClick={() => setView('log')}><FileText size={13} />سجل الإقرارات</button>
            </div>
            {branches.length > 1 && view === 'kiosk' && (
              <select className="inp sel" style={{ width: 180 }} value={branchId} onChange={e => setBranchId(e.target.value)}>
                {branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
              </select>
            )}
          </div>
        </div>
      )}

      {view === 'kiosk' && branch && (
        <div className="card">
          <div className="card-t" style={{ marginBottom: 4 }}><Signature size={15} color="var(--brass)" />كشك التوقيع الإلكتروني — {branch.name}</div>
          <div className="note" style={{ marginBottom: 10 }}>اختر اسمك، أدخل رقم PIN، اقرأ الإقرار ثم وقّع بإصبعك. تُعرض المبالغ لك وحدك بعد التحقق من هويتك، ويظهر توقيعك على قسيمة الراتب والمسير المطبوعين.</div>
          <div className="grid g3">
            {emps.map(e => {
              const pend = pendingOf(e.id);
              const n = pend.length;
              return (
                <button key={e.id} className="card" disabled={!n} style={{ padding: 12, textAlign: 'center', cursor: n ? 'pointer' : 'default', border: '1px solid var(--frame-o)', opacity: n ? 1 : 0.6 }}
                  onClick={() => { if (n) setSignFor(e); }}>
                  <div style={{ fontWeight: 700, fontSize: 13 }}>{e.name}</div>
                  <div style={{ marginTop: 6 }}>
                    {n ? <span className="badge b-amber">{n} {n === 1 ? 'مستند بانتظار توقيعك' : 'مستندات بانتظار توقيعك'}</span> : <span className="badge b-dim">لا مستندات بانتظارك</span>}
                  </div>
                  {n > 0 && <div style={{ fontSize: 10, color: 'var(--faint)', marginTop: 4 }}>{pend.map(d => SIGN_DOC_AR[d.docType] + ' ' + d.month).join(' · ')}</div>}
                </button>
              );
            })}
            {emps.length === 0 && <div className="empty">لا يوجد موظفون في هذا الفرع بعد — أضِفهم من «البيانات الرئيسية».</div>}
          </div>
        </div>
      )}

      {view === 'log' && !isCashier && (
        <div className="card">
          <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 8, marginBottom: 10 }}>
            <div className="card-t"><FileText size={15} color="var(--brass)" />سجل الإقرارات والإشعارات</div>
            <div className="row" style={{ gap: 6 }}>
              <span className="badge b-mint">موقَّع {nSigned}</span>
              <span className="badge b-amber">بانتظار {nPending}</span>
              <button className="btn sm gh" onClick={printReport}><Printer size={13} />تقرير حالة التوقيعات</button>
            </div>
          </div>
          <div className="row" style={{ gap: 8, flexWrap: 'wrap', marginBottom: 10 }}>
            <input type="month" className="inp" style={{ width: 150 }} value={ym} onChange={e => setYm(e.target.value)} />
            {branches.length > 1 && (
              <select className="inp sel" style={{ width: 160 }} value={logBranch} onChange={e => setLogBranch(e.target.value)}>
                <option value="">كل الفروع</option>
                {branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
              </select>
            )}
            <select className="inp sel" style={{ width: 150 }} value={logType} onChange={e => setLogType(e.target.value)}>
              <option value="">كل المستندات</option>
              <option value="payslip">إقرارات الراتب</option>
              <option value="reward">إشعارات المكافآت</option>
              <option value="penalty">إشعارات الجزاءات</option>
              <option value="corrective">محاضر الإجراءات التأديبية</option>
            </select>
            <select className="inp sel" style={{ width: 150 }} value={logStatus} onChange={e => setLogStatus(e.target.value)}>
              <option value="">كل الحالات</option>
              <option value="pending">بانتظار التوقيع</option>
              <option value="signed">موقَّع</option>
              <option value="voided">مُلغى</option>
            </select>
          </div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>الموظف</th><th>الفرع</th><th>المستند</th><th>الشهر</th>{showAmounts && <th style={{ textAlign: 'end' }}>المبلغ</th>}<th>الحالة</th><th>وقت التوقيع</th><th>الطريقة</th><th>التوقيع</th><th /></tr></thead>
              <tbody>
                {logRows.map(d => (
                  <tr key={d.id}>
                    <td style={{ fontWeight: 600, fontSize: 12.5 }}>{d.employeeName}</td>
                    <td style={{ fontSize: 12 }}>{d.branchName}</td>
                    <td><span className={'badge ' + (d.docType === 'penalty' ? 'b-rose' : d.docType === 'reward' ? 'b-mint' : 'b-brass')}>{SIGN_DOC_AR[d.docType]}</span></td>
                    <td className="num">{d.month}</td>
                    {showAmounts && <td className="num" style={{ textAlign: 'end' }}>{money(d.amount)}</td>}
                    <td>{statusBadge(d)}</td>
                    <td style={{ fontSize: 11.5 }}>{d.signedAt ? new Date(d.signedAt).toLocaleString('ar-SA') : '—'}</td>
                    <td style={{ fontSize: 11.5 }}>{viaAr(d)}</td>
                    <td>{d.status === 'signed' ? <button className="btn sm gh" onClick={() => setViewDoc(d)} title="عرض التوقيع"><SigView sig={d.sig} width={70} /></button> : <span style={{ color: 'var(--faint)' }}>—</span>}</td>
                    <td>
                      <div className="row" style={{ gap: 5, justifyContent: 'flex-end' }}>
                        <button className="btn sm gh" onClick={() => printDoc(d)} title="طباعة الإقرار"><Printer size={13} /></button>
                        {canCancel && d.status === 'pending' && <button className="btn sm gh" onClick={() => cancelDoc(d)} title="إلغاء المستند المعلّق"><Trash2 size={13} /></button>}
                      </div>
                    </td>
                  </tr>
                ))}
                {logRows.length === 0 && <tr><td colSpan={showAmounts ? 10 : 9}><div className="empty">لا مستندات ضمن هذه الفلاتر — تُصدَر قسائم الشهر تلقائيًا عند «تسجيل صرف الرواتب»، وإشعارات المكافآت/الجزاءات عند اعتمادها.</div></td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {signFor && (
        <SignDocsModal org={org} ops={ops} me={me} emp={signFor} docs={pendingOf(signFor.id)} onClose={() => setSignFor(null)} commit={commit} say={say} via={isAll ? 'central' : 'branch_kiosk'} />
      )}
      {viewDoc && (
        <Modal title={SIGN_DOC_AR[viewDoc.docType] + ' — ' + viewDoc.employeeName} icon={Signature} onClose={() => setViewDoc(null)} foot={<button className="btn gh" onClick={() => setViewDoc(null)}>إغلاق</button>}>
          <div className="grid" style={{ gap: 8, textAlign: 'center' }}>
            <SigView sig={viewDoc.sig} width={320} style={{ margin: '0 auto', border: '1px solid var(--frame-o)' }} />
            <div style={{ fontSize: 11.5, color: 'var(--dim)' }}>وُقِّع {viewDoc.signedAt ? new Date(viewDoc.signedAt).toLocaleString('ar-SA') : ''} · {viaAr(viewDoc)}{viewDoc.sigHash ? ' · #' + String(viewDoc.sigHash).slice(0, 10) : ''}</div>
            <div style={{ fontSize: 12, lineHeight: 1.8 }}>{signDeclaration(viewDoc)}</div>
          </div>
        </Modal>
      )}
    </div>
  );
}

function AdvanceForm({ emps, org, me, commit, say, onClose }) {
  const [f, setF] = useState({ employeeId: emps[0]?.id || '', date: today(), type: 'advance', amount: 0, reason: '', paymentMethod: 'cash', isUnjustified: false });
  const set = (k, v) => setF(p => ({ ...p, [k]: v }));
  const emp = emps.find(e => e.id === f.employeeId);

  const save = async () => {
    if (!emp) return say('اختر الموظف', 'no');
    if (f.amount <= 0) return say('أدخل مبلغاً صحيحاً', 'no');
    if (!f.reason.trim()) return say('اكتب سبب السلفة أو الخصم', 'no');
    if (periodLocked(org, f.date)) return say(LOCK_MSG(f.date), 'no');
    const b = org.branches.find(x => x.id === emp.branchId);
    const rec = {
      ...f, id: uid('ad'), employeeName: emp.name, branchId: emp.branchId, branchName: b?.name || '',
      month: f.date.slice(0, 7), createdByName: me.name, createdAt: nowISO()
    };
    await commit(d => ({ ...d, advances: [rec, ...(d.advances || [])] }), {
      actionType: 'payroll_record', targetType: 'payroll', targetId: rec.id, branchName: rec.branchName,
      title: 'سجّل سلفة/خصماً على موظف',
      details: `${emp.name} · ${money(f.amount)} ر.س · ${f.reason}`
    });
    say('تم تسجيل الحركة على كشف الراتب');
    onClose();
  };

  return (
    <Modal title="تسجيل سلفة أو خصم" icon={Wallet} onClose={onClose}
      foot={<><button className="btn pri" onClick={save}><Check size={14} />حفظ الحركة</button>
        <button className="btn gh" onClick={onClose}>إلغاء</button></>}>
      <div className="grid g2">
        <Field label="الموظف">
          <select className="sel" value={f.employeeId} onChange={e => set('employeeId', e.target.value)}>
            {emps.map(e => <option key={e.id} value={e.id}>{e.name} — {e.jobTitle}</option>)}
          </select>
        </Field>
        <Field label="التاريخ">
          <input type="date" className="inp" value={f.date} onChange={e => set('date', e.target.value)} />
        </Field>
      </div>
      <div className="grid g2">
        <Field label="نوع الحركة">
          <select className="sel" value={f.type} onChange={e => set('type', e.target.value)}>
            <option value="advance">سلفة</option>
            <option value="salary_draw">مسحوبة على الراتب</option>
            <option value="discount">خصم</option>
            <option value="absence_penalty">جزاء غياب</option>
            <option value="lateness_penalty">جزاء تأخير</option>
          </select>
        </Field>
        <Num label="المبلغ" value={f.amount} onChange={v => set('amount', v)}
          hint={emp ? `الراتب الأساسي ${money(emp.baseSalary)} ر.س` : ''} />
      </div>
      <Field label="طريقة الصرف">
        <select className="sel" value={f.paymentMethod} onChange={e => set('paymentMethod', e.target.value)}>
          <option value="cash">نقداً من صندوق الفرع</option>
          <option value="bank_transfer">تحويل بنكي</option>
          <option value="petty_cash">عهدة نثرية</option>
        </select>
      </Field>
      <Field label="السبب">
        <textarea className="inp" value={f.reason} placeholder="سبب السلفة أو الخصم" onChange={e => set('reason', e.target.value)} />
      </Field>
      <label className="row" style={{ fontSize: 12, cursor: 'pointer' }}>
        <input type="checkbox" checked={f.isUnjustified} onChange={e => set('isUnjustified', e.target.checked)} />
        وضع علامة "غير مبررة" لتنبيه الإدارة المالية
      </label>
    </Modal>
  );
}

/* ================= التقارير المالية ================= */
function Reports({ org, ops, me, myBranches, scoped, say, theme }) {
  const [repOpen, setRepOpen] = useState(false);    // v9.5 قائمة تقارير التطبيق
  const tn = chartTone(theme);
  const [mode, setMode] = useState('ops');
  const d30 = new Date(); d30.setDate(d30.getDate() - 29);
  const [from, setFrom] = useState(d30.toISOString().slice(0, 10));
  const [to, setTo] = useState(today());
  const [bid, setBid] = useState('all');

  const rows = scoped.closings.filter(c => countedClosing(c) && c.date >= from && c.date <= to && (bid === 'all' || c.branchId === bid));

  const byBranch = myBranches.filter(b => bid === 'all' || b.id === bid).map(b => {
    const bc = rows.filter(c => c.branchId === b.id);
    const rev = sum(bc, c => c.totalRevenue), exp = sum(bc, c => c.totalExpenses);
    const cash = sum(bc, c => c.cashSales), card = sum(bc, c => c.cardSales);
    const del = sum(bc, c => c.totalDeliverySales);
    const net = rev - exp;
    return {
      id: b.id, name: b.name, n: bc.length, rev, exp, cash, card, del, net,
      margin: rev ? (net / rev) * 100 : 0, varr: sum(bc, c => c.variance),
      vat: sum(bc, c => c.totalRevenue) * 15 / 115
    };
  });

  const T = {
    rev: sum(byBranch, x => x.rev), exp: sum(byBranch, x => x.exp),
    net: sum(byBranch, x => x.net), varr: sum(byBranch, x => x.varr), vat: sum(byBranch, x => x.vat)
  };

  const daily = useMemo(() => {
    const m = {};
    rows.forEach(c => { m[c.date] = (m[c.date] || 0) + c.totalRevenue - c.totalExpenses; });
    return Object.entries(m).sort().map(([d, v]) => ({ lbl: d.slice(5).replace('-', '/'), net: v }));
  }, [rows]);

  const exportCsv = () => {
    const head = ['الفرع', 'عدد الإغلاقات', 'الإيراد', 'المصروف', 'الصافي', 'الهامش%', 'نقدي', 'شبكة', 'تطبيقات', 'فروقات الصندوق', 'ض.القيمة المضافة'];
    const body = byBranch.map(b => [b.name, b.n, b.rev.toFixed(2), b.exp.toFixed(2), b.net.toFixed(2), b.margin.toFixed(1), b.cash.toFixed(2), b.card.toFixed(2), b.del.toFixed(2), b.varr.toFixed(2), b.vat.toFixed(2)]);
    const csv = '\uFEFF' + [head, ...body].map(r => r.join(',')).join('\n');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));
    const a = document.createElement('a');
    a.href = url; a.download = `تقرير-الفروع-${from}_${to}.csv`; a.click();
    URL.revokeObjectURL(url);
    say('تم تنزيل التقرير بصيغة CSV');
  };

  const exportXlsx = () => {
    const headers = ['الفرع', 'عدد الإغلاقات', 'الإيراد', 'المصروف', 'الصافي', 'الهامش %', 'نقدي', 'شبكة', 'تطبيقات', 'فروقات الصندوق', 'ض.القيمة المضافة'];
    const rows = byBranch.map(b => [b.name, b.n, +b.rev.toFixed(2), +b.exp.toFixed(2), +b.net.toFixed(2), +b.margin.toFixed(1), +b.cash.toFixed(2), +b.card.toFixed(2), +b.del.toFixed(2), +b.varr.toFixed(2), +b.vat.toFixed(2)]);
    const t = byBranch.reduce((a, b) => ({ n: a.n + b.n, rev: a.rev + b.rev, exp: a.exp + b.exp, net: a.net + b.net, cash: a.cash + b.cash, card: a.card + b.card, del: a.del + b.del, varr: a.varr + b.varr, vat: a.vat + b.vat }), { n: 0, rev: 0, exp: 0, net: 0, cash: 0, card: 0, del: 0, varr: 0, vat: 0 });
    exportExcel(`تقرير-الفروع-${from}_${to}`, `تقرير أداء الفروع`, headers, rows, {
      meta: [`${org.company.name || ''} · الرقم الضريبي: ${org.company.taxNumber || '—'}`, `الفترة: من ${from} إلى ${to}`],
      totals: ['الإجمالي', t.n, +t.rev.toFixed(2), +t.exp.toFixed(2), +t.net.toFixed(2), '', +t.cash.toFixed(2), +t.card.toFixed(2), +t.del.toFixed(2), +t.varr.toFixed(2), +t.vat.toFixed(2)]
    });
    say('تم تنزيل التقرير بصيغة Excel');
  };

  const printOps = () => {
    const co = org.company || {};
    const m = (n) => (Math.round((n || 0) * 100) / 100).toLocaleString('en-US', { minimumFractionDigits: 2 });
    const rows = byBranch.map(b => `<tr>
      <td>${b.name}</td><td class="num">${b.n}</td>
      <td class="num brass">${m(b.rev)}</td><td class="num">${m(b.cash)}</td>
      <td class="num">${m(b.card)}</td><td class="num">${m(b.del)}</td>
      <td class="num rose">${m(b.exp)}</td><td class="num mint">${m(b.net)}</td>
      <td class="num">${b.margin.toFixed(1)}%</td>
      <td class="num">${m(b.varr)}</td></tr>`).join('');
    const w = window.open('', '_blank', 'width=980,height=780');
    if (!w) return;
    w.document.write(`<!doctype html><html dir="rtl" lang="ar"><head><meta charset="utf-8">
      <title>تقرير أداء الفروع</title><style>${A4_CSS}</style></head><body><div class="page">
      <div class="head">
        <div class="co">${co.logoUrl ? `<img class="logo" src="${co.logoUrl}">` : ''}
          <div><div class="co-n">${co.name || 'المنشأة'}</div>
          <div class="co-m">الرقم الضريبي: ${co.taxNumber || '—'}</div></div></div>
        <div class="doc-title">تقرير الأداء التشغيلي للفروع</div>
        <div class="doc-sub">من ${arDate(from)} إلى ${arDate(to)}</div>
      </div>
      <table class="t"><thead><tr>
        <th>الفرع</th><th class="num">إغلاقات</th><th class="num">الإيراد</th><th class="num">نقدي</th>
        <th class="num">شبكة</th><th class="num">تطبيقات</th><th class="num">المصروف</th>
        <th class="num">الصافي</th><th class="num">الهامش</th><th class="num">فروقات</th>
      </tr></thead><tbody>${rows}</tbody>
      <tfoot><tr class="tot"><td>الإجمالي</td><td class="num">${sum(byBranch, b => b.n)}</td>
        <td class="num brass">${m(T.rev)}</td><td class="num">${m(sum(byBranch, b => b.cash))}</td>
        <td class="num">${m(sum(byBranch, b => b.card))}</td><td class="num">${m(sum(byBranch, b => b.del))}</td>
        <td class="num rose">${m(T.exp)}</td><td class="num mint">${m(T.net)}</td><td>—</td>
        <td class="num">${m(T.varr)}</td></tr></tfoot></table>
      <div class="foot dim">تم التصدير آلياً من منصة إغلاق الفروع · ${new Date().toLocaleString('ar-SA-u-nu-latn')}</div>
      </div></body></html>`);
    w.document.close();
    setTimeout(() => { w.focus(); w.print(); }, 500);
  };

  const Tabs = () => (
    <div className="row scroll-x">
      <button className={'btn sm' + (mode === 'ops' ? ' pri' : ' gh')} onClick={() => setMode('ops')}>
        <FileBarChart size={14} />الأداء التشغيلي
      </button>
      <button className={'btn sm' + (mode === 'pnl' ? ' pri' : ' gh')} onClick={() => setMode('pnl')}>
        <FileText size={14} />قائمة الدخل (يومي/شهري/سنوي)
      </button>
    </div>
  );

  if (mode === 'pnl') return (
    <div className="grid" style={{ gap: 14 }}>
      <Tabs />
      <FinancialReports org={org} ops={ops} myBranches={myBranches} scoped={scoped} say={say} />
    </div>
  );

  return (
    <div className="grid" style={{ gap: 14 }}>
      {/* شريط التطبيق — v9.5 */}
      <div className="abar">
        <div className="abar-id"><span className="abar-ic"><FileBarChart size={17} /></span>التقارير المالية<small>تقرير الفروع · التصدير · قائمة الدخل</small></div>
        <div className="abar-sp" />
        <div className="abar-dd">
          <button className="btn sm" onClick={() => setRepOpen(o => !o)}><FileBarChart size={14} />التقارير<ChevronDown size={13} /></button>
          {repOpen && (<>
            <div className="abar-back" onClick={() => setRepOpen(false)} />
            <div className="abar-menu">
              <div className="abar-hd">تقارير ومخرجات</div>
              <button onClick={() => { setRepOpen(false); printOps(); }}><Printer size={13} />طباعة تقرير الفروع</button>
              <button onClick={() => { setRepOpen(false); exportCsv(); }}><Download size={13} />تصدير CSV</button>
              <button onClick={() => { setRepOpen(false); exportXlsx(); }}><Download size={13} />تصدير Excel</button>
            </div>
          </>)}
        </div>
      </div>

      <Tabs />
      <div className="card">
        <div className="row">
          <div style={{ flex: 1, minWidth: 140 }}>
            <label className="lbl">من تاريخ</label>
            <input type="date" className="inp" value={from} onChange={e => setFrom(e.target.value)} />
          </div>
          <div style={{ flex: 1, minWidth: 140 }}>
            <label className="lbl">إلى تاريخ</label>
            <input type="date" className="inp" value={to} onChange={e => setTo(e.target.value)} />
          </div>
          <div style={{ flex: 1.4, minWidth: 170 }}>
            <label className="lbl">الفرع</label>
            <select className="sel" value={bid} onChange={e => setBid(e.target.value)}>
              <option value="all">جميع الفروع ضمن صلاحيتي</option>
              {myBranches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
            </select>
          </div>
          <div className="row" style={{ alignSelf: 'flex-end' }}>
            <button className="btn pri" onClick={printOps}><FileText size={14} />طباعة (PDF)</button>
            <button className="btn" onClick={exportCsv}><Download size={14} />تصدير CSV</button>
            <button className="btn ok" onClick={exportXlsx}><FileBarChart size={14} />تصدير Excel</button>
          </div>
        </div>
      </div>

      <div className="grid g4">
        <Kpi label="الإيرادات" value={money(T.rev)} sub={`${rows.length} إغلاق`} icon={CircleDollarSign} color="#C8A24A" />
        <Kpi label="المصروفات" value={money(T.exp)} icon={Receipt} color="#D9544D" />
        <Kpi label="صافي الربح" value={money(T.net)} sub={`هامش ${T.rev ? ((T.net / T.rev) * 100).toFixed(1) : 0}%`} icon={TrendingUp} color="#4FB286" />
        <Kpi label="ض. القيمة المضافة المستحقة" value={money(T.vat)} sub="15% من الإيراد الشامل" icon={Landmark} color="#5B93C4" />
      </div>

      <div className="card">
        <div className="card-t" style={{ marginBottom: 14 }}><TrendingUp size={15} color="var(--brass)" />صافي الربح اليومي</div>
        <div style={{ height: 220, direction: 'ltr' }}>
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={daily} margin={{ top: 4, right: 4, left: -18, bottom: 0 }}>
              <CartesianGrid stroke={tn.grid} vertical={false} />
              <XAxis dataKey="lbl" tick={{ fill: tn.tick, fontSize: 10 }} axisLine={false} tickLine={false} />
              <YAxis tick={{ fill: tn.tick, fontSize: 10 }} axisLine={false} tickLine={false} tickFormatter={short} />
              <Tooltip contentStyle={{ background: tn.tip, border: '1px solid ' + tn.grid, borderRadius: 10, fontSize: 12, direction: 'rtl', color: tn.tipTxt }}
                formatter={v => [money(v), 'الصافي']} />
              <Line type="monotone" dataKey="net" stroke={tn.pos} strokeWidth={2.2} dot={false} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="card">
        <div className="card-t" style={{ marginBottom: 12 }}><FileBarChart size={15} color="var(--brass)" />قائمة أداء الفروع</div>
        <div className="tw">
          <table className="tb">
            <thead><tr>
              <th>الفرع</th><th>إغلاقات</th><th>الإيراد</th><th>نقدي</th><th>شبكة</th><th>تطبيقات</th>
              <th>المصروف</th><th>الصافي</th><th>الهامش</th><th>فروقات</th>
            </tr></thead>
            <tbody>
              {byBranch.map(b => (
                <tr key={b.id}>
                  <td style={{ fontSize: 12, fontWeight: 600 }}>{b.name}</td>
                  <td className="num">{b.n}</td>
                  <td className="num" style={{ color: 'var(--brass)' }}>{money(b.rev)}</td>
                  <td className="num">{money(b.cash)}</td>
                  <td className="num">{money(b.card)}</td>
                  <td className="num">{money(b.del)}</td>
                  <td className="num" style={{ color: 'var(--rose)' }}>{money(b.exp)}</td>
                  <td className="num" style={{ color: 'var(--mint)', fontWeight: 600 }}>{money(b.net)}</td>
                  <td><span className={'badge ' + (b.margin > 25 ? 'b-mint' : b.margin > 12 ? 'b-amber' : 'b-rose')}>
                    <span className="num">{b.margin.toFixed(1)}%</span></span></td>
                  <td className="num" style={{ color: b.varr < 0 ? 'var(--rose)' : 'var(--faint)' }}>{money(b.varr)}</td>
                </tr>
              ))}
              <tr style={{ background: 'rgba(200,162,74,.06)' }}>
                <td style={{ fontWeight: 700 }}>الإجمالي</td><td className="num">{sum(byBranch, b => b.n)}</td>
                <td className="num" style={{ fontWeight: 700, color: 'var(--brass)' }}>{money(T.rev)}</td>
                <td className="num">{money(sum(byBranch, b => b.cash))}</td>
                <td className="num">{money(sum(byBranch, b => b.card))}</td>
                <td className="num">{money(sum(byBranch, b => b.del))}</td>
                <td className="num" style={{ color: 'var(--rose)' }}>{money(T.exp)}</td>
                <td className="num" style={{ fontWeight: 700, color: 'var(--mint)' }}>{money(T.net)}</td>
                <td>—</td>
                <td className="num" style={{ color: T.varr < 0 ? 'var(--rose)' : 'var(--faint)' }}>{money(T.varr)}</td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

/* ================= الفروع والمستخدمون ================= */
/* ============ إدارة تطبيقات التوصيل ============ */
function DeliveryAppsPanel({ org, commitOrg, say }) {
  const apps = org.deliveryApps || APPS;
  const [nm, setNm] = useState('');
  const [comm, setComm] = useState('');

  const addApp = async () => {
    const name = nm.trim();
    if (!name) return say('أدخل اسم التطبيق', 'no');
    const c = Number(comm) || 0;
    if (c < 0 || c > 100) return say('نسبة العمولة يجب أن تكون بين 0 و 100', 'no');
    if (apps.some(a => a.n === name)) return say('هذا التطبيق مضاف مسبقاً', 'no');
    const app = { id: uid('app'), n: name, c };
    await commitOrg(d => ({ ...d, deliveryApps: [...(d.deliveryApps || APPS), app] }), {
      actionType: 'create', targetType: 'delivery_app', targetId: app.id, title: 'أضاف تطبيق توصيل', details: `${name} — عمولة ${c}%`
    });
    setNm(''); setComm(''); say('تمت إضافة التطبيق — سيظهر في الإغلاقات الجديدة');
  };

  const updateComm = async (id, c) => {
    await commitOrg(d => ({ ...d, deliveryApps: (d.deliveryApps || APPS).map(a => a.id === id ? { ...a, c: Number(c) || 0 } : a) }), {
      actionType: 'update', targetType: 'delivery_app', targetId: id, title: 'عدّل عمولة تطبيق توصيل', details: `عمولة ${c}%`
    });
  };

  const removeApp = async (app) => {
    await commitOrg(d => ({ ...d, deliveryApps: (d.deliveryApps || APPS).filter(a => a.id !== app.id) }), {
      actionType: 'delete', targetType: 'delivery_app', targetId: app.id, title: 'حذف تطبيق توصيل', details: app.n
    });
    say('تم حذف التطبيق');
  };

  return (
    <div className="grid" style={{ gap: 14 }}>
      <div className="card" style={{ borderColor: 'rgba(200,162,74,.3)' }}>
        <div className="card-h"><div className="card-t"><Plus size={15} />إضافة تطبيق توصيل جديد</div></div>
        <div style={{ fontSize: 12, color: 'var(--dim)', marginBottom: 12 }}>
          عند ظهور تطبيق توصيل جديد في السوق، أضِفه هنا فيظهر تلقائياً في نموذج الإغلاق اليومي لكل الفروع.
        </div>
        <div className="row" style={{ gap: 9, flexWrap: 'wrap', alignItems: 'flex-end' }}>
          <Field label="اسم التطبيق" style={{ flex: 1, minWidth: 160 }}>
            <input className="inp" placeholder="مثال: مرسول، ذا شيف..." value={nm} onChange={e => setNm(e.target.value)} />
          </Field>
          <Field label="نسبة العمولة %" style={{ width: 130 }}>
            <input className="inp n" inputMode="decimal" placeholder="0" value={comm} onChange={e => setComm(e.target.value.replace(/[^\d.]/g, ''))} />
          </Field>
          <button className="btn pri" onClick={addApp}><Plus size={15} />إضافة</button>
        </div>
      </div>

      <div className="card">
        <div className="card-h"><div className="card-t"><Truck size={15} />التطبيقات المفعّلة ({apps.length})</div></div>
        <div className="tw">
          <table className="tb">
            <thead><tr><th>التطبيق</th><th>نسبة العمولة %</th><th></th></tr></thead>
            <tbody>
              {apps.map(a => (
                <tr key={a.id}>
                  <td style={{ fontWeight: 600 }}>{a.n}</td>
                  <td>
                    <input className="inp n" style={{ width: 90 }} inputMode="decimal" defaultValue={a.c}
                      onBlur={e => updateComm(a.id, e.target.value.replace(/[^\d.]/g, ''))} />
                  </td>
                  <td>
                    <button className="btn sm gh" onClick={() => removeApp(a)}><Trash2 size={12} color="#D9544D" />حذف</button>
                  </td>
                </tr>
              ))}
              {apps.length === 0 && <tr><td colSpan={3}><div className="empty">لا توجد تطبيقات. أضف تطبيقاً من الأعلى.</div></td></tr>}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

function Admin({ org, ops, me, commit, commitOrg, say }) {
  const [tab, setTab] = useState('branches');
  const [bEdit, setBEdit] = useState(null);
  const [uEdit, setUEdit] = useState(null);

  const saveBranch = async (b) => {
    const isNew = !org.branches.some(x => x.id === b.id);
    await commitOrg(d => ({ ...d, branches: isNew ? [...d.branches, b] : d.branches.map(x => x.id === b.id ? b : x) }), {
      actionType: isNew ? 'create' : 'update', targetType: 'branch', targetId: b.id, branchName: b.name,
      title: isNew ? 'أضاف فرعاً جديداً' : 'عدّل بيانات فرع', details: `${b.name} — ${b.city}`
    });
    say(isNew ? 'تمت إضافة الفرع' : 'تم تحديث بيانات الفرع'); setBEdit(null);
  };
  const saveUser = async (u) => {
    const isNew = !org.users.some(x => x.id === u.id);
    const email = (u.email || '').trim().toLowerCase();
    if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return say('أدخل بريداً إلكترونياً صحيحاً', 'no');
    if (org.users.some(x => x.id !== u.id && (x.email || '').toLowerCase() === email)) return say('هذا البريد مستخدم بحساب آخر', 'no');
    if (isNew && (!u.newPass || u.newPass.length < 6)) return say('كلمة سر الحساب الجديد يجب ألا تقل عن 6 أحرف', 'no');
    if (isNew && u.newPass && u.newPass !== u.newPass.trim()) return say('كلمة السر تبدأ أو تنتهي بمسافة — احذفها ثم أعد الحفظ (المسافات الخفية أشهر سبب لفشل الدخول لاحقاً)', 'no');
    // v15.15 — إصلاح جذري: كان إنشاء حساب المصادقة يجري «بعد» حفظ السجل، وفشله (خصوصاً بريد
    // ما زال قائماً في Firebase من محاولة سابقة) يُبتلع بصمت وتظهر رسالة «تم إنشاء الحساب»
    // بينما كلمة السر الجديدة لم تصل لحساب الدخول إطلاقاً — فيفشل دخول الموظف للأبد بلا
    // تفسير. الصحيح: إنشاء حساب المصادقة أولاً، وعند فشله نوقف الحفظ ونشرح بدقة ماذا يُفعل.
    if (authApi.enabled && isNew && u.newPass) {
      try { await authApi.createUser(email, u.newPass); }
      catch (e) {
        const c = String((e && e.code) || '');
        if (c.includes('email-already-in-use')) {
          return say('يوجد حساب دخول قديم بهذا البريد في Firebase وكلمة سره القديمة هي التي ستبقى سارية — لن تُطبَّق كلمة السر الجديدة. الحل: احذف هذا البريد من لوحة Firebase (Authentication → Users) ثم أعد إنشاء المستخدم هنا.', 'no');
        }
        if (c.includes('weak-password')) return say('كلمة السر ضعيفة وفق سياسة Firebase — اختر كلمة أقوى ثم أعد المحاولة', 'no');
        if (c.includes('invalid-email')) return say('البريد الإلكتروني غير مقبول لدى Firebase — تأكد من صياغته', 'no');
        if (c.includes('network')) return say('تعذّر الاتصال بخادم المصادقة — تحقق من الشبكة وأعد المحاولة (لم يُحفَظ شيء)', 'no');
        return say('تعذّر إنشاء حساب الدخول (' + c.replace('auth/', '') + ') — لم يُحفَظ المستخدم. أعد المحاولة', 'no');
      }
    }
    const rec = { ...u, email };
    if (u.newPass) { rec.passHash = await sha(u.newPass); }
    if (u.newPin) { rec.pinHash = await sha('pin:' + u.newPin); }
    delete rec.newPass; delete rec.newPin; delete rec.pin;
    await commitOrg(d => ({ ...d, users: isNew ? [...d.users, rec] : d.users.map(x => x.id === rec.id ? rec : x) }), {
      actionType: isNew ? 'create' : 'permission_change', targetType: 'user_account', targetId: rec.id,
      title: isNew ? 'أنشأ مستخدماً جديداً' : 'عدّل بيانات مستخدم', details: `${rec.name} — ${ROLES[rec.role].ar}`
    });
    // مزامنة العضوية وصفة المدير حسب الدور
    // v27.2: فشل المزامنة كان يُبتلع بصمت (upsertMember تعيد false) فيُحفظ المستخدم بلا عضوية خادمية صحيحة
    // ⇒ جهاز فرعه لا يستطيع قراءة/كتابة بياناته. نُبلغ صراحةً.
    let memOk = true;
    if (authApi.enabled) {
      memOk = await authApi.upsertMember(email, { active: rec.isActive !== false, role: rec.role, branchId: rec.branchId || '', branchIds: rec.allowedBranchIds || [], scope: (ROLES[rec.role]?.scope === 'all') ? 'all' : 'branch' });
      const admOk = await authApi.syncAdmin(email, !!ROLES[rec.role]?.admin);
      if (memOk && !admOk && ROLES[rec.role]?.admin) say('حُفظ المستخدم لكن تعذّر إدراجه في قائمة المدراء على الخادم — نفّذ الحفظ من حساب مسؤول النظام الأول', 'no');
    }
    if (!memOk) say('حُفظ المستخدم في المنصة، لكن تعذّرت مزامنة عضويته على الخادم (حسابك ليس ضمن قائمة المدراء على الخادم) — لن يستطيع هذا المستخدم قراءة/كتابة بيانات فرعه حتى تُنفَّذ «مزامنة صلاحيات الأعضاء» من حساب مسؤول النظام الأول', 'no');
    else say(isNew ? 'تم إنشاء الحساب — يدخل ببريده وكلمة سره ✓' : 'تم تحديث الحساب');
    setUEdit(null);
  };

  const delUser = async (u) => {
    if (u.id === me.id) return say('لا يمكنك حذف حسابك الحالي', 'no');
    if ((ROLES[u.role] || {}).admin && org.users.filter(x => x.isActive && (ROLES[x.role] || {}).admin).length <= 1) {
      return say('لا يمكن حذف آخر حساب مدير نشط في المنصة', 'no');
    }
    if (!window.confirm(`سيُحذف حساب «${u.name}» (${u.email}) نهائياً من المنصة، ويصبح بريده متاحاً لإنشاء حساب جديد به. إغلاقاته وسجلاته السابقة تبقى محفوظة في فرعها. هل أنت متأكد؟`)) return;
    await commitOrg(d => ({ ...d, users: d.users.filter(x => x.id !== u.id) }), {
      actionType: 'delete', targetType: 'user_account', targetId: u.id, title: 'حذف مستخدماً', details: `${u.name} — ${u.email}`
    });
    if (authApi.enabled) { try { await authApi.upsertMember(u.email, { active: false }); } catch { } }
    say('تم حذف الحساب');
  };

  // v27.1 — إعادة مزامنة عضويات الخادم (members/{email}: الفرع/النطاق/الدور) لكل المستخدمين — هي ما تعتمد عليه
  // قواعد Firestore لعزل الفروع؛ عضوية بلا فرع صحيح = جهاز الفرع يقرأ نسخة قديمة ولا يستطيع حفظ أي شيء سحابيًا.
  const [memSync, setMemSync] = useState(null);
  const syncMembers = async () => {
    if (!authApi.enabled) return say('المصادقة السحابية غير مفعّلة في هذه النسخة', 'no');
    setMemSync('busy');
    let ok = 0, fail = 0; const failed = [];
    for (const u of (org.users || [])) {
      if (!u.email) continue;
      const r = await authApi.upsertMember(u.email, { active: u.isActive !== false, role: u.role, branchId: u.branchId || '', branchIds: u.allowedBranchIds || [], scope: (ROLES[u.role]?.scope === 'all') ? 'all' : 'branch' });
      if (r) { ok++; try { await authApi.syncAdmin(u.email, !!ROLES[u.role]?.admin); } catch { } } else { fail++; failed.push(u.name || u.email); }
    }
    setMemSync({ ok, fail, failed });
    if (fail) say('تعذّرت مزامنة ' + fail + ' عضوية (' + failed.slice(0, 3).join('، ') + (fail > 3 ? '…' : '') + ') — حسابك ليس ضمن قائمة المدراء على الخادم (platform/admins)؛ نفّذها من حساب مسؤول النظام الأول', 'no');
    else say('زُومنت عضويات ' + ok + ' مستخدم مع الخادم ✓ — أعد الدخول على أجهزة الفروع');
  };

  return (
    <div className="grid" style={{ gap: 14 }}>
      <div className="row">
        <button className={'btn sm' + (tab === 'branches' ? ' pri' : ' gh')} onClick={() => setTab('branches')}>
          <Building2 size={14} />الفروع
        </button>
        <button className={'btn sm' + (tab === 'users' ? ' pri' : ' gh')} onClick={() => setTab('users')}>
          <Users size={14} />المستخدمون والصلاحيات
        </button>
        <button className={'btn sm' + (tab === 'cats' ? ' pri' : ' gh')} onClick={() => setTab('cats')}>
          <Receipt size={14} />بنود المصروف والميزانيات
        </button>
        <button className={'btn sm' + (tab === 'delivery' ? ' pri' : ' gh')} onClick={() => setTab('delivery')}>
          <Truck size={14} />تطبيقات التوصيل
        </button>
        <button className={'btn sm' + (tab === 'perms' ? ' pri' : ' gh')} onClick={() => setTab('perms')}>
          <ShieldCheck size={14} />مصفوفة الصلاحيات
        </button>
        <button className={'btn sm' + (tab === 'appperms' ? ' pri' : ' gh')} onClick={() => setTab('appperms')}>
          <Grid3x3 size={14} />ظهور التطبيقات للمستخدمين
        </button>
        <button className={'btn sm' + (tab === 'system' ? ' pri' : ' gh')} onClick={() => setTab('system')}>
          <Settings size={14} />بيانات الشركة والنسخ الاحتياطي
        </button>
        {(tab === 'branches' || tab === 'users') && <button className="btn pri" style={{ marginInlineStart: 'auto' }}
          onClick={() => tab === 'branches'
            ? setBEdit({ id: uid('b'), name: '', city: '', managerName: '', phone: '', defaultFloat: 1500, shiftEndTime: '02:00', isActive: true })
            : setUEdit({ id: uid('u'), name: '', email: '', role: 'branch_manager', newPass: '', branchId: org.branches[0]?.id, allowedBranchIds: [], isActive: true, createdAt: today() })}>
          <Plus size={15} />{tab === 'branches' ? 'فرع جديد' : 'مستخدم جديد'}
        </button>}
      </div>

      {tab === 'branches' && (
        <div className="grid g2">
          {org.branches.map(b => (
            <div key={b.id} className="card">
              <div className="card-h">
                <div className="card-t"><Store size={15} color="var(--brass)" />{b.name}</div>
                <span className={'badge ' + (b.isActive ? 'b-mint' : 'b-dim')}>{b.isActive ? 'نشط' : 'موقوف'}</span>
              </div>
              <div style={{ fontSize: 12, color: 'var(--dim)', lineHeight: 2 }}>
                <div>المدينة: {b.city} · المسؤول: {b.managerName}</div>
                <div>الجوال: <span className="num">{b.phone}</span> · نهاية الوردية: <span className="num">{b.shiftEndTime}</span></div>
                <div>العهدة الافتراضية: <span className="num" style={{ color: 'var(--brass)' }}>{money(b.defaultFloat)}</span> ر.س</div>
                {(b.bankName || b.bankIban) && <div>🏦 بنك الفرع: <b style={{ color: 'var(--brass)' }}>{b.bankName || '—'}</b>{b.bankIban ? <> · <span className="num" style={{ direction: 'ltr', unicodeBidi: 'embed' }}>{b.bankIban}</span></> : ''}</div>}
              </div>
              <div className="row" style={{ marginTop: 12 }}>
                <button className="btn sm" onClick={() => setBEdit(b)}>تعديل</button>
                <button className="btn sm gh" onClick={() => saveBranch({ ...b, isActive: !b.isActive })}>
                  {b.isActive ? 'إيقاف' : 'تفعيل'}
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {tab === 'users' && (
        <div className="card">
          <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 8, marginBottom: 10 }}>
            <div className="note" style={{ flex: 1, minWidth: 260 }}>قواعد الخادم تعزل الفروع اعتمادًا على «عضوية» كل حساب (الفرع/النطاق). إن ظهر على جهاز فرع شريط أحمر «لن تُحفظ أي بيانات» أو اختفى حضور/إغلاق بعد إعادة التحميل، اضغط «مزامنة صلاحيات الأعضاء» ثم أعد الدخول على ذلك الجهاز.</div>
            <button className="btn sm" disabled={memSync === 'busy'} onClick={syncMembers} title="إعادة كتابة members/{email} لكل المستخدمين من سجلاتهم هنا"><ShieldCheck size={13} />{memSync === 'busy' ? 'جارٍ المزامنة…' : 'مزامنة صلاحيات الأعضاء'}</button>
            {memSync && memSync !== 'busy' && <span className={'badge ' + (memSync.fail ? 'b-rose' : 'b-mint')}>{memSync.ok} ✓{memSync.fail ? ' · ' + memSync.fail + ' ✗' : ''}</span>}
          </div>
          <div className="tw">
            <table className="tb">
              <thead><tr><th>المستخدم</th><th>الدور</th><th>النطاق</th><th>الحالة</th><th></th></tr></thead>
              <tbody>
                {org.users.map((u, i) => (
                  <tr key={u.id}>
                    <td>
                      <div className="row" style={{ gap: 9, flexWrap: 'nowrap' }}>
                        <div className="av" style={{ background: clr(i), margin: 0 }}>{u.name.charAt(0)}</div>
                        <div><div style={{ fontSize: 12.5, fontWeight: 600 }}>{u.name}</div>
                          <div style={{ fontSize: 10.5, color: 'var(--faint)' }}>{u.email}</div></div>
                      </div>
                    </td>
                    <td><span className={'badge ' + (ROLES[u.role] || ROLES.cashier).badge}>{(ROLES[u.role] || ROLES.cashier).ar.split('—')[0]}</span></td>
                    <td style={{ fontSize: 11.5, color: 'var(--dim)' }}>
                      {(ROLES[u.role] || ROLES.cashier).scope === 'all' ? 'جميع الفروع'
                        : (ROLES[u.role] || ROLES.cashier).scope === 'own' ? (org.branches.find(b => b.id === u.branchId)?.name || '—')
                          : `${(u.allowedBranchIds || []).length} فرع مصرّح`}
                    </td>
                    <td><span className={'badge ' + (u.isActive ? 'b-mint' : 'b-dim')}>{u.isActive ? 'نشط' : 'موقوف'}</span></td>
                    <td>
                      <div className="row" style={{ gap: 5, flexWrap: 'nowrap' }}>
                        <button className="btn sm" onClick={() => setUEdit(u)}>تعديل</button>
                        <button className="btn sm gh" onClick={() => saveUser({ ...u, isActive: !u.isActive })} title={u.isActive ? 'إيقاف الحساب' : 'تفعيل الحساب'}>
                          {u.isActive ? <Lock size={12} /> : <Check size={12} />}
                        </button>
                        <button className="btn sm gh" onClick={() => delUser(u)} title="حذف الحساب نهائياً" style={{ color: 'var(--rose)' }}>
                          <Trash2 size={12} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {tab === 'cats' && <CategoriesPanel org={org} ops={ops} commitOrg={commitOrg} say={say} />}
      {tab === 'delivery' && <DeliveryAppsPanel org={org} commitOrg={commitOrg} say={say} />}
      {tab === 'appperms' && <AppPermsPanel org={org} commitOrg={commitOrg} say={say} />}
      {tab === 'system' && <SystemPanel org={org} ops={ops} me={me} commit={commit} commitOrg={commitOrg} say={say} />}
      {tab === 'perms' && (() => {
        const roleIds = ['system_admin', 'general_management', 'head_office', 'finance_department', 'regional_manager', 'branch_manager', 'cashier'];
        return (
          <div className="grid" style={{ gap: 12 }}>
            <div className="card">
              <div className="card-t" style={{ marginBottom: 10 }}><ShieldCheck size={15} color="var(--brass)" />مصفوفة الصلاحيات — من يرى ماذا (المصدر الواحد للحقيقة)</div>
              <div className="tw">
                <table className="tb" style={{ fontSize: 11.5 }}>
                  <thead><tr><th>الشاشة</th>{roleIds.map(r => <th key={r} style={{ textAlign: 'center', whiteSpace: 'nowrap' }}>{(ROLES[r]?.ar || r).split(' — ')[0]}</th>)}</tr></thead>
                  <tbody>
                    {ALL_TABS.map(t => (
                      <tr key={t}>
                        <td style={{ fontWeight: 600 }}>{TAB_AR[t] || t}</td>
                        {roleIds.map(r => {
                          const ok = (ROLES[r]?.tabs || []).includes(t);
                          return <td key={r} style={{ textAlign: 'center', color: ok ? 'var(--mint)' : 'var(--faint)', fontWeight: ok ? 800 : 400 }}>{ok ? '✓' : '—'}</td>;
                        })}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
            <div className="card" style={{ background: 'rgba(200,162,74,.04)', borderStyle: 'dashed' }}>
              <div style={{ fontSize: 11.5, color: 'var(--dim)', lineHeight: 2 }}>
                <b style={{ color: 'var(--brass-l)' }}>صلاحيات الكتابة الحساسة (إضافة إلى رؤية الشاشات):</b><br />
                • القيود اليدوية والأصول والتسوية البنكية وأوامر الشراء والمخزون: الأدوار كاملة النطاق (مسؤول النظام، الإدارة العليا، المكتب الرئيسي، المحاسب الرئيسي)<br />
                • تفعيل الضريبة ونسبتها، إدارة المستخدمين والفروع، إدارة التطبيقات: أدوار الإدارة فقط (مسؤول النظام، الإدارة العليا)<br />
                • الاعتماد النهائي للإغلاقات: أصحاب صفة «معتمِد» — والقيود التلقائية لا يعدّلها أحد: تصحيح المصدر يصحّح قيده<br />
                • مدير الفرع والكاشير: إدخال إغلاقات فرعهم فقط، وإضافة الشركاء عبر «طلب اعتماد» يقرّه المركز
              </div>
            </div>
          </div>
        );
      })()}

      {bEdit && <BranchForm b={bEdit} org={org} say={say} onSave={saveBranch} onClose={() => setBEdit(null)} />}
      {uEdit && <UserForm u={uEdit} org={org} onSave={saveUser} onClose={() => setUEdit(null)} />}
    </div>
  );
}

function BranchForm({ b, org, say, onSave, onClose }) {
  const [f, setF] = useState(b);
  const set = (k, v) => setF(p => ({ ...p, [k]: v }));
  return (
    <Modal title={b.name ? 'تعديل فرع' : 'إضافة فرع جديد'} icon={Building2} onClose={onClose}
      foot={<><button className="btn pri" onClick={() => f.name ? onSave(f) : null} disabled={!f.name}>
        <Check size={14} />حفظ الفرع</button><button className="btn gh" onClick={onClose}>إلغاء</button></>}>
      <div className="grid g2">
        <Field label="اسم الفرع"><input className="inp" value={f.name} onChange={e => set('name', e.target.value)} placeholder="فرع ..." /></Field>
        <Field label="المدينة"><input className="inp" value={f.city} onChange={e => set('city', e.target.value)} /></Field>
        <Field label="مدير الفرع"><input className="inp" value={f.managerName} onChange={e => set('managerName', e.target.value)} /></Field>
        <Field label="جوال الفرع"><input className="inp n" value={f.phone} onChange={e => set('phone', e.target.value)} /></Field>
        <Num label="العهدة التشغيلية الافتراضية" value={f.defaultFloat} onChange={v => set('defaultFloat', v)} />
        <Field label="وقت نهاية الوردية"><input type="time" className="inp" value={f.shiftEndTime} onChange={e => set('shiftEndTime', e.target.value)} /></Field>
      </div>
      <div className="card" style={{ marginTop: 6, background: 'rgba(200,162,74,.05)', borderColor: 'var(--frame)' }}>
        <div className="card-t" style={{ marginBottom: 4 }}><Landmark size={14} color="var(--brass)" />الحساب البنكي للفرع (اختياري)</div>
        <div className="note" style={{ marginBottom: 10 }}>عند إدخال بنكٍ للفرع، تُرحَّل إليه تحصيلات الشبكة والتحويل بدل البنك التجميعي، ويُنشأ للفرع <b>حساب وسيط «تحصيلات تحت التحويل»</b> يمرّ عبره توريد النقد للخزينة الرئيسية. اتركه فارغًا ليعمل الفرع كالسابق تمامًا.</div>
        <div className="grid g2">
          <Field label="اسم البنك"><input className="inp" value={f.bankName || ''} onChange={e => set('bankName', e.target.value)} placeholder="مثال: مصرف الراجحي" /></Field>
          <Field label="الآيبان / رقم الحساب"><input className="inp n" style={{ direction: 'ltr', textAlign: 'right' }} value={f.bankIban || ''} onChange={e => set('bankIban', e.target.value)} placeholder="SA00 0000 0000 0000 0000 0000" /></Field>
        </div>
        {/* v15.21 — ربط بنك الفرع بحساب قائم في الدليل المحاسبي بدل الحساب التلقائي */}
        <Field label="حساب البنك في الدليل المحاسبي">
          <select className="sel" value={f.bankAcc || ''} onChange={e => set('bankAcc', e.target.value)}>
            <option value="">تلقائي — يُنشأ حساب مستقل باسم الفرع (الوضع المعتاد)</option>
            <option value="1201">1201 · البنك — الشبكة والمدفوعات البنكية (تجميعي)</option>
            {((org && org.customAccounts) || []).filter(a => (a.kind || '') === 'asset').map(a => (
              <option key={a.code} value={String(a.code)}>{a.code} · {a.name}</option>
            ))}
          </select>
        </Field>
        <div style={{ fontSize: 10.5, color: 'var(--faint)', marginTop: -4, lineHeight: 1.7 }}>
          اختر حساباً من دليلك المحاسبي لتُرحَّل إليه تحصيلات هذا الفرع مباشرةً (يظهر هنا: البنك التجميعي + حساباتك المخصّصة من نوع «أصول» — أنشئها أولاً من المحاسبة ← دليل الحسابات). يمكن ربط أكثر من فرع بنفس الحساب إن كانا يصبّان في حساب بنكي واحد فعلاً.
        </div>
      </div>
      <Field label="شعار الفرع (يظهر في تقارير هذا الفرع)">
        <PhotoField value={f.logoUrl} onChange={v => set('logoUrl', v)} say={say} />
      </Field>
    </Modal>
  );
}

function UserForm({ u, org, onSave, onClose }) {
  const [resetMsg, setResetMsg] = useState('');
  const [f, setF] = useState(u);
  const [bioMsg, setBioMsg] = useState('');
  const [showPw, setShowPw] = useState(false); // v15.15 — استعراض كلمة السر أثناء الكتابة (رمز العين)
  const set = (k, v) => setF(p => ({ ...p, [k]: v }));
  const toggle = (id) => {
    const cur = f.allowedBranchIds || [];
    set('allowedBranchIds', cur.includes(id) ? cur.filter(x => x !== id) : [...cur, id]);
  };
  return (
    <Modal title={u.name ? 'تعديل مستخدم' : 'مستخدم جديد'} icon={UserCog} onClose={onClose}
      foot={<><button className="btn pri" disabled={!f.name} onClick={() => onSave(f)}><Check size={14} />حفظ الحساب</button>
        <button className="btn gh" onClick={onClose}>إلغاء</button></>}>
      <div className="grid g2">
        <Field label="الاسم الكامل"><input className="inp" value={f.name} onChange={e => set('name', e.target.value)} /></Field>
        <Field label="البريد الإلكتروني"><input className="inp" type="email" style={{ direction: 'ltr', textAlign: 'right' }} value={f.email} onChange={e => set('email', e.target.value)} placeholder="name@company.com" /></Field>
      </div>
      <Field label="الدور والصلاحية">
        <select className="sel" value={f.role} onChange={e => set('role', e.target.value)}>
          {Object.entries(ROLES).filter(([k, v]) => !v.legacy || k === f.role).map(([k, v]) => <option key={k} value={k}>{v.ar}</option>)}
        </select>
      </Field>
      {ROLES[f.role].scope === 'own' && (
        <Field label="الفرع المخصص">
          <select className="sel" value={f.branchId} onChange={e => set('branchId', e.target.value)}>
            {org.branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
          </select>
        </Field>
      )}
      {ROLES[f.role].scope === 'assigned' && (
        <Field label="الفروع المصرّح بالوصول إليها">
          <div className="row">
            {org.branches.map(b => (
              <button key={b.id} className={'btn sm' + ((f.allowedBranchIds || []).includes(b.id) ? ' pri' : ' gh')}
                onClick={() => toggle(b.id)}>{b.name}</button>
            ))}
          </div>
        </Field>
      )}
      <Field label={u.name ? 'كلمة سر جديدة (اتركها فارغة للإبقاء على الحالية)' : 'كلمة السر'}>
        <div style={{ position: 'relative' }}>
          <input className="inp" type={showPw ? 'text' : 'password'} value={f.newPass || ''} placeholder={u.name ? 'بدون تغيير' : '٦ أحرف على الأقل'}
            style={showPw ? { direction: 'ltr', textAlign: 'right', letterSpacing: 1 } : undefined}
            onChange={e => set('newPass', e.target.value)} />
          <button type="button" className="btn sm gh pw-eye" style={{ position: 'absolute', insetInlineEnd: 4, top: 4, padding: '4px 8px' }}
            title={showPw ? 'إخفاء كلمة السر' : 'إظهار كلمة السر'}
            onClick={() => setShowPw(s => !s)} tabIndex={-1}><Eye size={14} /></button>
        </div>
        {showPw && f.newPass && (
          <div style={{ fontSize: 10.5, color: 'var(--brass-l)', marginTop: 4 }}>
            تُكتب هكذا حرفاً بحرف: <b className="num" style={{ direction: 'ltr', unicodeBidi: 'isolate', letterSpacing: 2 }}>{f.newPass}</b>
            {f.newPass !== f.newPass.trim() && <span style={{ color: 'var(--rose)' }}> — ⚠ تحوي مسافة في البداية أو النهاية!</span>}
          </div>
        )}
        {u.passHash && !f.newPass && <div style={{ fontSize: 10.5, color: 'var(--faint)', marginTop: 4 }}>للحساب كلمة سر محفوظة — لن تتغير ما لم تكتب واحدة جديدة.</div>}
        {authApi.enabled && (
          <div style={{ fontSize: 10.5, color: 'var(--sky)', marginTop: 6, lineHeight: 1.8 }}>
            المصادقة السحابية مفعّلة: كلمة السر هنا تُنشئ حساب دخول المستخدم <b>الجديد</b>. لتغيير كلمة سر مستخدم قائم:
            <button type="button" className="btn sm gh" style={{ marginInlineStart: 6 }}
              onClick={async () => {
                if (!f.email) { setResetMsg('اكتب البريد أولاً'); return; }
                setResetMsg('...');
                try { await authApi.resetPass(f.email); setResetMsg('أُرسل رابط التعيين إلى ' + f.email); }
                catch { setResetMsg('تعذّر الإرسال — تأكد من صحة البريد ووجود حساب مصادقة له'); }
              }}>إرسال رابط تعيين كلمة السر</button>
            {resetMsg && <div style={{ marginTop: 4, color: resetMsg.startsWith('أُرسل') ? 'var(--mint)' : 'var(--amber)' }}>{resetMsg}</div>}
          </div>
        )}
      </Field>
      <Field label="رقم سري للدخول السريع (اختياري — 4 إلى 6 أرقام)">
        <input className="inp" inputMode="numeric" style={{ direction: 'ltr', textAlign: 'right', letterSpacing: 4 }} value={f.newPin || ''}
          placeholder={f.pinHash ? 'محفوظ — اكتب رقماً جديداً لتغييره' : 'يمكّن الدخول السريع بالرقم'}
          onChange={e => set('newPin', e.target.value.replace(/\D/g, '').slice(0, 6))} />
        {f.pinHash && !f.newPin && <div style={{ fontSize: 10.5, color: 'var(--faint)', marginTop: 4 }}>لهذا الحساب رقم سري محفوظ للدخول السريع.</div>}
      </Field>

      <div className="card" style={{ background: 'var(--ink)', padding: 12 }}>
        <div className="row" style={{ justifyContent: 'space-between', flexWrap: 'wrap', gap: 8 }}>
          <div>
            <div style={{ fontSize: 12.5, fontWeight: 600, display: 'flex', gap: 6, alignItems: 'center' }}>
              <Fingerprint size={14} color="var(--brass)" />البصمة الحيوية لهذا الجهاز
            </div>
            <div style={{ fontSize: 10.5, color: 'var(--faint)', marginTop: 3, lineHeight: 1.6 }}>
              تسجّل بصمة/وجه هذا الجهاز (Touch ID / Face ID / Windows Hello) لدخول أسرع.
            </div>
          </div>
          {f.bioCredId ? (
            <div className="row">
              <span className="badge b-mint"><Check size={11} />مُفعّلة</span>
              <button type="button" className="btn sm gh" onClick={() => set('bioCredId', undefined)}>
                <Trash2 size={12} color="#D9544D" />إلغاء
              </button>
            </div>
          ) : (
            <button type="button" className="btn sm" disabled={bioMsg === 'busy'}
              onClick={async () => {
                if (!webauthnSupported()) { setBioMsg('unsupported'); return; }
                if (!f.email) { setBioMsg('needmail'); return; }
                setBioMsg('busy');
                try { const id = await bioEnroll({ ...f, id: f.id }); set('bioCredId', id); setBioMsg('done'); }
                catch { setBioMsg('fail'); }
              }}>
              {bioMsg === 'busy' ? <RefreshCw size={12} className="spin" /> : <ScanFace size={13} />}تفعيل البصمة
            </button>
          )}
        </div>
        {bioMsg === 'unsupported' && <div style={{ fontSize: 10.5, color: 'var(--amber)', marginTop: 8 }}>هذا الجهاز/المتصفح لا يدعم البصمة الحيوية.</div>}
        {bioMsg === 'needmail' && <div style={{ fontSize: 10.5, color: 'var(--amber)', marginTop: 8 }}>أدخل البريد الإلكتروني أولاً.</div>}
        {bioMsg === 'fail' && <div style={{ fontSize: 10.5, color: 'var(--rose)', marginTop: 8 }}>تعذّر التسجيل — تأكد من إعداد البصمة على الجهاز.</div>}
        {bioMsg === 'done' && <div style={{ fontSize: 10.5, color: 'var(--mint)', marginTop: 8 }}>تم — احفظ الحساب لاعتماد البصمة.</div>}
      </div>
      <div className="card" style={{ background: 'var(--ink)', padding: 12 }}>
        <div className="lbl">ما يستطيع هذا الدور فعله</div>
        {ROLES[f.role].perms.map((p, i) => (
          <div key={i} style={{ fontSize: 11.5, color: 'var(--dim)', display: 'flex', gap: 7, marginBottom: 4 }}>
            <Check size={13} color="var(--mint)" style={{ flexShrink: 0, marginTop: 3 }} />{p}
          </div>
        ))}
      </div>
    </Modal>
  );
}

/* ================= سجل التدقيق ================= */
function AuditView({ pulse, onSeen }) {
  const [q, setQ] = useState('');
  useEffect(() => { onSeen && onSeen(); }, []);
  const logs = (pulse.audit || []).filter(l =>
    !q || (l.userName + l.title + l.details).toLowerCase().includes(q.toLowerCase()));
  return (
    <div className="grid" style={{ gap: 14 }}>
      <div className="card">
        <div className="card-h">
          <div className="card-t"><Eye size={15} color="var(--brass)" />سجل الإجراءات على المنصة</div>
          <div className="row">
            <Search size={14} color="var(--faint)" />
            <input className="inp" style={{ width: 200 }} placeholder="بحث بالمستخدم أو الإجراء"
              value={q} onChange={e => setQ(e.target.value)} />
          </div>
        </div>
        <div className="tw">
          <table className="tb">
            <thead><tr><th>الوقت</th><th>المستخدم</th><th>الدور</th><th>الإجراء</th><th>التفاصيل</th></tr></thead>
            <tbody>
              {logs.map(l => (
                <tr key={l.id}>
                  <td style={{ fontSize: 11, color: 'var(--faint)', whiteSpace: 'nowrap' }}>{arTime(l.timestamp)}</td>
                  <td style={{ fontSize: 12, fontWeight: 600 }}>{l.userName}</td>
                  <td><span className={'badge ' + (ROLES[l.userRole] || ROLES.cashier).badge}>{(ROLES[l.userRole] || ROLES.cashier).ar.split('—')[0]}</span></td>
                  <td style={{ fontSize: 12 }}>{l.title}</td>
                  <td style={{ fontSize: 11.5, color: 'var(--dim)' }}>{l.details}</td>
                </tr>
              ))}
              {logs.length === 0 && <tr><td colSpan={5}><div className="empty">
                لا توجد سجلات بعد. كل إجراء يقوم به أي مستخدم سيُقيَّد هنا تلقائياً.</div></td></tr>}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

/* ================= طباعة تقارير الإغلاق ================= */

// بناء محتوى تقرير A4 رسمي مطابق للنموذج المعتمد
function buildClosingA4(c, org) {
  const co = org.company || {};
  const branch = (org.branches || []).find(b => b.id === c.branchId);
  const headLogo = (branch && branch.logoUrl) || co.logoUrl || '';
  const money2 = (n) => (Math.round((n || 0) * 100) / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const dels = (c.deliverySales || []);
  const delComm = (d) => (d.commissionAmount != null ? d.commissionAmount : (d.amount * (d.commissionPercentage || 0) / 100));
  const statusAr = c.gmApprovalStatus === 'approved' ? 'معتمد نهائياً'
    : c.status === 'approved' ? 'مدقّق — بانتظار الاعتماد'
    : c.status === 'submitted' ? 'بانتظار الاعتماد' : 'مسودة';
  const varClass = c.variance === 0 ? 'ok' : c.variance < 0 ? 'bad' : 'warn';
  const varText = c.variance === 0 ? 'مطابق (0.00)' : c.variance < 0 ? 'عجز ' + money2(Math.abs(c.variance)) : 'فائض ' + money2(c.variance);

  const delRows = dels.length ? `<tr class="subhead"><td colspan="4">مبيعات تطبيقات التوصيل (${dels.length} تطبيقات)</td></tr>` +
    dels.map(d => `<tr>
    <td>تطبيق: ${d.appName || '—'}</td>
    <td class="num">${money2(d.amount)}</td>
    <td class="num dim">-${money2(delComm(d))}</td>
    <td class="num dim">${d.orderCount || 0} طلب</td></tr>`).join('') : '';

  const payLbl = (pm) => ({cash:'نقداً',card:'شبكة',cheque:'شيك',bank_transfer:'تحويل',deferred:'آجل'})[pm] || pm;
  // سداد الموردين خلال الوردية — يظهر في التقرير حتى تكتمل معادلة الصندوق أمام المدقق
  const supPaysArr = (c.supplierPayments || []).filter(pm => payTotal(pm) > 0);
  const supPayRows = supPaysArr.map(pm => `<tr>
    <td>${pm.supplierName || '—'}</td>
    <td class="dim">${payLabel(pm) || '—'}</td>
    <td class="dim">${pm.reference || '—'}</td>
    <td class="num">${money2(payTotal(pm))} ر.س</td></tr>`).join('');
  const supPaySum = supPaysArr.reduce((s, pm) => s + payTotal(pm), 0);
  const supPayCash = supPaysArr.reduce((s, pm) => s + payCashPart(pm), 0);
  const expRows = (c.expenses || []).length ? (c.expenses || []).map(e => `<tr>
    <td>${e.categoryName || '—'}${e.isTaxable ? '<br><span style="font-size:8px;color:#8C6F2C">خاضع للضريبة' + (e.taxInvoice ? ' · فاتورة ضريبية' : '') + '</span>' : '<br><span style="font-size:8px;color:#999">غير خاضع</span>'}</td>
    <td class="dim">${e.beneficiaryName || '—'}</td>
    <td>${payLbl(e.paymentMethod)}${e.receiptNumber ? '<br><span style="font-size:8px;color:#999">' + e.receiptNumber + '</span>' : ''}</td>
    <td class="ce">${e.receiptImage ? '<span class="chip">مرفق ✓</span>' : '—'}</td>
    <td class="num rose">${money2(e.amount)} ر.س</td></tr>`).join('')
    : `<tr><td colspan="5" class="ce dim">لا توجد مصروفات على هذه الوردية</td></tr>`;

  // v16.5: مرفقات PDF لا تُوضع في <img> (تظهر مكسورة) — تُذكر عدّاً في التقرير وتُفتح من المنصة
  const allAtt = [];
  if (c.cardReceiptImage) allAtt.push({ t: 'إثبات الشبكة / التحويل', u: c.cardReceiptImage });
  (c.expenses || []).forEach(e => { if (e.receiptImage) allAtt.push({ t: (e.categoryName || 'مصروف') + (e.beneficiaryName ? ' — ' + e.beneficiaryName : ''), u: e.receiptImage }); });
  ((c.sessionPhotos && c.sessionPhotos.length) ? c.sessionPhotos : (c.sessionPhoto ? [c.sessionPhoto] : []))
    .forEach((u, i, arr) => allAtt.push({ t: 'توثيق المسؤول' + (arr.length > 1 ? ' ' + (i + 1) : ''), u }));
  const isPdfU = (v) => typeof v === 'string' && v.indexOf('data:application/pdf') === 0;
  const receiptImgs = allAtt.filter(im => !isPdfU(im.u));
  const pdfAtts = allAtt.filter(im => isPdfU(im.u));
  const imgsBlock = (receiptImgs.length || pdfAtts.length) ? `
    <div class="sec-h">صور الفواتير والمرفقات (${allAtt.length})</div>
    ${receiptImgs.length ? `<div class="imgs">${receiptImgs.map(im => `<div class="img-c"><img src="${im.u}"><div class="img-t">${im.t}</div></div>`).join('')}</div>` : ''}
    ${pdfAtts.length ? `<div style="font-size:9.5px;color:#666;margin-top:4px">📎 مرفقات PDF (${pdfAtts.length}): ${pdfAtts.map(x => x.t).join(' · ')} — تُفتح من شاشة استعراض الإغلاق في المنصة.</div>` : ''}` : '';

  return `<div class="page">
    <div class="head">
      <div class="co">
        ${headLogo ? `<img class="logo" src="${headLogo}">` : ''}
        <div>
          <div class="co-n">${co.name || 'المنشأة'}</div>
          <div class="co-m">الرقم الضريبي: ${co.taxNumber || '—'} · السجل التجاري: ${co.commercialReg || '—'}</div>
        </div>
      </div>
      <div class="doc-title">تقرير الإغلاق اليومي الرسمي</div>
      <div class="doc-sub">فرع ${c.branchName} · ${arDate(c.date)}</div>
      <div class="doc-sub dim">تاريخ التصدير: ${new Date().toLocaleString('ar-SA-u-nu-latn')}</div>
    </div>

    <div class="summary-card">
      <div class="summary-h">📊 التلخيص المالي — تقرير إغلاق يومي</div>
      <div class="summary-grid">
        <div class="sc"><span>إجمالي المبيعات</span><b class="mint">${money2(c.totalRevenue)} ر.س</b></div>
        <div class="sc"><span>إجمالي المصروفات</span><b class="rose">${money2(c.totalExpenses)} ر.س</b></div>
        <div class="sc"><span>عمولات منصات التوصيل</span><b class="warn2">${money2(sum(dels, d => delComm(d)))} ر.س</b></div>
        <div class="sc"><span>صافي الأرباح التشغيلية</span><b class="mint">${money2(c.totalRevenue - c.totalExpenses)} ر.س</b></div>
        <div class="sc"><span>صور الفواتير المرفقة</span><b class="brass">${receiptImgs.length} صور</b></div>
      </div>
    </div>

    <div class="banner">
      <div class="banner-r">
        <div class="banner-id">تقرير الإغلاق اليومي #${c.id || c.transferReferenceNo || ''}</div>
        <div class="banner-sub">التاريخ: ${arDate(c.date)}${c.transferReferenceNo ? ' · سند: ' + c.transferReferenceNo : ''}</div>
      </div>
      <div class="banner-l">
        <div>الفرع: <b>${c.branchName}</b> · المسؤول: <b>${c.managerName}</b></div>
        <span class="banner-badge">${statusAr}</span>
      </div>
    </div>

    <div class="kpis">
      <div class="kpi"><span>إجمالي الإيرادات</span><b class="brass">${money2(c.totalRevenue)} ر.س</b></div>
      <div class="kpi"><span>إجمالي المصروفات</span><b class="rose">${money2(c.totalExpenses)} ر.س</b></div>
      <div class="kpi"><span>عمولات التوصيل</span><b>${money2(sum(dels, d => d.commissionAmount || 0))} ر.س</b></div>
      <div class="kpi"><span>صافي اليوم التشغيلي</span><b class="mint">${money2(c.totalRevenue - c.totalExpenses)} ر.س</b></div>
      <div class="kpi"><span>المحوّل للخزينة</span><b>${money2(c.transferredToMainTreasury)} ر.س</b></div>
      <div class="kpi ${varClass}"><span>مطابقة الصندوق</span><b>${varText}</b></div>
    </div>

    <div class="meta-row">
      <span class="badge">${statusAr}</span>
      <span>المسؤول: ${c.managerName}</span>
      <span>سند التحويل: ${c.transferReferenceNo || '—'}</span>
    </div>

    <div class="sec-h">تفاصيل المبيعات والإيرادات</div>
    <table class="t">
      <thead><tr><th>نوع الإيراد / الوسيلة</th><th class="num">المبلغ (ر.س)</th><th class="num">العمولة</th><th class="num">التفاصيل</th></tr></thead>
      <tbody>
        <tr><td>الرصيد الافتتاحي للعهدة</td><td class="num">${money2(c.openingBalance)}</td><td class="num dim">—</td><td class="num dim">افتتاح الصندوق</td></tr>
        <tr><td>المبيعات النقدية (Cash)</td><td class="num">${money2(c.cashSales)}</td><td class="num dim">—</td><td class="num dim">محصّل كاش</td></tr>
        <tr><td>مبيعات الشبكة (مدى/POS)</td><td class="num">${money2(c.cardSales)}</td><td class="num dim">—</td><td class="num dim">نقاط البيع</td></tr>
        ${c.bankTransferSales ? `<tr><td>تحويل بنكي مباشر</td><td class="num">${money2(c.bankTransferSales)}</td><td class="num dim">—</td><td class="num dim">حساب بنكي</td></tr>` : ''}
        ${delRows}
      </tbody>
      <tfoot><tr class="tot"><td>إجمالي الإيرادات</td><td class="num brass">${money2(c.totalRevenue)}</td><td colspan="2"></td></tr></tfoot>
    </table>

    <div class="sec-h">المصروفات التشغيلية المخصومة</div>
    <table class="t">
      <thead><tr><th>التصنيف</th><th>المورد/المستفيد</th><th>طريقة الدفع</th><th class="ce">المرفقات</th><th class="num">المبلغ</th></tr></thead>
      <tbody>${expRows}</tbody>
      <tfoot><tr class="tot"><td colspan="4">إجمالي المصروفات التشغيلية</td><td class="num rose">${money2(c.totalExpenses)} ر.س</td></tr></tfoot>
    </table>

    ${supPaysArr.length ? `
    <div class="sec-h">سداد الموردين خلال الوردية</div>
    <table class="t">
      <thead><tr><th>المورد</th><th>توزيع الدفع</th><th>المرجع/الفاتورة</th><th class="num">المبلغ</th></tr></thead>
      <tbody>${supPayRows}</tbody>
      <tfoot><tr class="tot"><td colspan="3">إجمالي سداد الموردين — منه نقدًا من الصندوق ${money2(supPayCash)} ر.س</td><td class="num">${money2(supPaySum)} ر.س</td></tr></tfoot>
    </table>` : ''}

    <div class="sec-h">مطابقة الصندوق والعهدة</div>
    <table class="t compact">
      <tr><td>المتوقع بالصندوق (كاش)</td><td class="num">${money2(c.expectedCashInSafe)} ر.س</td></tr>
      <tr><td>العدّ الفعلي بالجرد</td><td class="num">${money2(c.actualCashCount)} ر.س</td></tr>
      <tr><td>العهدة المتبقية للغد</td><td class="num">${money2(c.retainedFloatForTomorrow)} ر.س</td></tr>
      <tr class="tot ${varClass}"><td>فارق الصندوق</td><td class="num">${varText}</td></tr>
    </table>
    ${c.varianceReason ? `<div class="note">سبب الفرق: ${c.varianceReason}</div>` : ''}
    ${imgsBlock}

    <div class="sigs">
      <div class="sig">
        <div class="sig-t">إعداد وتوقيع مسؤول الفرع</div>
        <div class="sig-r dim">${c.managerName}</div>
        ${c.managerSignature ? `<img class="sig-img" src="${c.managerSignature}">` : '<div class="sig-line"></div>'}
        <div class="sig-ok">${c.managerSignature ? '✔ توقيع رقمي موثّق' : ''}</div>
      </div>
      <div class="sig">
        <div class="sig-t">مراجعة الإدارة المالية</div>
        <div class="sig-r dim">قسم المحاسبة والمالية</div>
        <div class="sig-line"></div>
        <div class="sig-ok dim">التوقيع والختم</div>
      </div>
      <div class="sig">
        <div class="sig-t">اعتماد المدير العام</div>
        <div class="sig-r dim">المالك والمدير العام</div>
        <div class="sig-line"></div>
        <div class="sig-ok dim">الاعتماد النهائي</div>
      </div>
    </div>
    <div class="foot dim">تم تصدير هذا التقرير آلياً من منصة إغلاق الفروع · ${co.name || ''}</div>
  </div>`;
}

